// Define the structure of a record
typedef struct {
    int key;
} Record;

// Define the function to dynamically allocate memory for arrays
void initialize_arrays(int num_records, long** offset_arr, int** key_arr, Record*** records) {
    // Validate input sizes to prevent out-of-bounds access and memory allocation failures
    if (num_records <= 0 || sizeof(Record) > UINT64_MAX / num_records) {
        fprintf(stderr, "Invalid input size. Must be a positive integer.\n");
        return;
    }

    // Dynamically allocate memory for the offset array and initialize it with random values within a specified range
    *offset_arr = malloc(sizeof(long) * num_records);
    if (*offset_arr == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }
    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        (*offset_arr)[i] = rand() % 1000; // random value within a specified range (e.g., [0, 1000])
    }

    // Dynamically allocate memory for the key array and initialize it with random values within a specified range
    *key_arr = malloc(sizeof(int) * num_records);
    if (*key_arr == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }
    for (int i = 0; i < num_records; ++i) {
        (*key_arr)[i] = rand() % 1000; // random value within a specified range (e.g., [0, 1000])
    }

    // Dynamically allocate memory for the record array and initialize it with random values within a specified range
    *records = malloc(sizeof(Record) * num_records);
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }
    for (int i = 0; i < num_records; ++i) {
        (*records)[i].key = rand() % 1000; // random value within a specified range (e.g., [0, 1000])
    }
}

// Define the function to release memory for arrays
void cleanup_arrays(long* offset_arr, int* key_arr, Record** records) {
    free(offset_arr);
    free(key_arr);
    free(records);
}

// Example usage of the initialize and cleanup functions
int main() {
    // Initialize arrays with 10,000 elements
    int num_records = 10000;
    long* offset_arr;
    int* key_arr;
    Record** records;
    initialize_arrays(num_records, &offset_arr, &key_arr, &records);

    // Use the arrays as needed
    for (int i = 0; i < num_records; ++i) {
        printf("Offset: %ld, Key: %d\n", offset_arr[i], key_arr[i]);
        printf("Record: %d\n", records[i].key);
    }

    // Clean up memory
    cleanup_arrays(offset_arr, key_arr, records);
    return 0;
}
