    // Parse the input file and generate the output file based on the transformation rules
    while (!feof(input)) {
        int bytes_read = fread(buffer, sizeof(char), BUFFER_SIZE, input);
        if (bytes_read > 0) {
            pthread_create(&threads[0], NULL, parse_input, &args);
            pthread_create(&threads[1], NULL, transform_data, &args);
            pthread_create(&threads[2], NULL, write_output, &args);
        } else {
            printf("Error reading from input file\n");
            fclose(input);
            fclose(output);
            free(buffer);
            sem_close(sem);
            pthread_mutex_destroy(mutex);
            free(mutex);
            return 1;
        }
    }

    // Wait for all threads to complete
    for (int i = 0; i < 3; i++) {
        pthread_join(threads[i], NULL);
    }

    // Close the input and output files and free memory
    fclose(input);
    fclose(output);
    free(buffer);
    sem_close(sem);
    pthread_mutex_destroy(mutex);
    free(mutex);
    return 0;
}
