public class BattleStatisticsService {
  private static final String API_ENDPOINT = "https://pokeapi.co/api/v2/pokemon";
  private static final int MAX_API_CALLS = 10;
  private static final int CACHE_SIZE = 1000;
  private static Map<Integer, String> cache = new ConcurrentHashMap<>();
  private static AtomicInteger apiCalls = new AtomicInteger(0);

  public static String getBattleStatistics(int pokemonId) {
    if (pokemonId <= 0 || pokemonId > 807) {
      return "Invalid Pokemon ID";
    }

    // Check cache for existing entry
    if (cache.containsKey(pokemonId)) {
      return cache.get(pokemonId);
    }

    // Fetch data from API
    String response = fetchFromApi(pokemonId);

    // Parse response and create battle statistics string
    Map<String, Object> jsonResponse = (Map<String, Object>) JSONValue.parse(response);
    String name = (String) jsonResponse.get("name");
    List<Object> types = (List<Object>) jsonResponse.get("types");
    List<Object> weaknesses = new ArrayList<>();
    List<Object> resistances = new ArrayList<>();
    List<Object> immunities = new ArrayList<>();

    for (int i = 0; i < types.size(); i++) {
      Map<String, Object> type = (Map<String, Object>) types.get(i);
      String typeName = (String) type.get("type");
      if (typeName.equals("normal")) {
        weaknesses.add("fire");
        resistances.add("water");
      } else if (typeName.equals("fire")) {
        weaknesses.add("water");
        resistances.add("grass");
      } else if (typeName.equals("water")) {
        weaknesses.add("ground");
        resistances.add("rock");
      } else if (typeName.equals("electric")) {
        weaknesses.add("fighting");
        resistances.add("grass");
      } else if (typeName.equals("grass")) {
        weaknesses.add("fire", "ice");
        resistances.add("water", "electric");
      } else if (typeName.equals("ground")) {
        weaknesses.add("flying", "rock");
        resistances.add("bug");
      } else if (typeName.equals("poison")) {
        weaknesses.add("grass", "steel");
        resistances.add("ghost");
      } else if (typeName.equals("ice")) {
        weaknesses.add("fire", "flying");
        resistances.add("ground");
      } else if (typeName.equals("psychic")) {
        weaknesses.add("bug", "ghost");
        resistances.add("fighting", "poison");
      } else if (typeName.equals("fighting")) {
        weaknesses.add("flying", "psychic");
        resistances.add("normal");
      } else if (typeName.equals("bug")) {
        weaknesses.add("grass", "fire", "fighting");
        resistances.add("ground", "rock");
      } else if (typeName.equals("dragon")) {
        weaknesses.add("water", "ice");
        resistances.add("normal");
      } else if (typeName.equals("ghost")) {
        weaknesses.add("psychic", "bug");
        resistances.add("fighting", "dragon");
      } else if (typeName.equals("steel")) {
        weaknesses.add("fire", "water", "ice");
        resistances.add("normal");
      } else if (typeName.equals("fairy")) {
        weaknesses.add("poison", "dragon");
        resistances.add("bug", "steel");
      }
    }

    // Add immunities to list of types
    for (int i = 0; i < types.size(); i++) {
      Map<String, Object> type = (Map<String, Object>) types.get(i);
      String typeName = (String) type.get("type");
      if (typeName.equals("normal")) {
        immunities.add("fire");
      } else if (typeName.equals("fire")) {
        immunities.add("water");
      } else if (typeName.equals("water")) {
        immunities.add("ground");
      } else if (typeName.equals("electric")) {
        immunities.add("fighting");
      } else if (typeName.equals("grass")) {
        immunities.add("fire", "ice");
      } else if (typeName.equals("ground")) {
        immunities.add("bug");
      } else if (typeName.equals("poison")) {
        immunities.add("grass", "steel");
      } else if (typeName.equals("ice")) {
        immunities.add("fire", "flying");
      } else if (typeName.equals("psychic")) {
        immunities.add("bug", "ghost");
      } else if (typeName.equals("fighting")) {
        immunities.add("flying", "rock");
      } else if (typeName.equals("bug")) {
        immunities.add("grass", "fire", "fighting");
      } else if (typeName.equals("dragon")) {
        immunities.add("water", "ice");
      } else if (typeName.equals("ghost")) {
        immunities.add("psychic");
      } else if (typeName.equals("steel")) {
        immunities.add("fire", "water", "ice");
      } else if (typeName.equals("fairy")) {
        immunities.add("poison", "dragon");
      }
    }

    // Cache response and return battle statistics string
    cache.put(pokemonId, StringUtils.join(new Object[] {name, weaknesses, resistances, immunities}, ","));
    return cache.get(pokemonId);
  }

  private static String fetchFromApi(int pokemonId) {
    Client client = ClientBuilder.newClient();
    Response response = client.target(API_ENDPOINT + "/" + pokemonId).request().accept(MediaType.APPLICATION_JSON).get();
    if (response.getStatus() == 200) {
      return response.readEntity(String.class);
    } else if (apiCalls.incrementAndGet() < MAX_API_CALLS) {
      try {
        Thread.sleep(1000);
      } catch (InterruptedException e) {
        // ignore
      }
      return fetchFromApi(pokemonId);
    } else {
      return "API call limit reached";
    }
  }
}
