// Function to perform encryption based on command line options
int encrypt(char *input, char *output, int mode, char *key) {
    // Load the OpenSSL libraries at runtime
    load_openssl();

    // Set up the encryption context
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        LOG_ERROR("Failed to create encryption context");
        return -1;
    }

    // Initialize the encryption algorithm
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, NULL) != 1) {
        LOG_ERROR("Failed to initialize encryption algorithm");
        return -1;
    }

