    if (mode == ECB) {
        EVP_CIPHER_CTX_set_flags(ctx, EVP_CIPH_ECB_MODE);
    } else if (mode == CBC) {
        EVP_CIPHER_CTX_set_flags(ctx, EVP_CIPH_CBC_MODE);
