    outbuf = malloc(inbuf_size + BLOCK_SIZE - 1);
    if (!outbuf) {
        LOG_ERROR("Failed to allocate output buffer");
        return -1;
    }
    outbuf_size = inbuf_size + BLOCK_SIZE - 1;

    // Perform the encryption
    int len, outlen;
    if (EVP_EncryptUpdate(ctx, outbuf, &outlen, inbuf, inbuf_size) != 1) {
        LOG_ERROR("Failed to encrypt data");
        return -1;
    }

    // Write the output to file
    FILE *output_file = fopen(output, "wb");
    if (!output_file) {
        LOG_ERROR("Failed to open output file");
        free(outbuf);
        return -1;
    }
    fwrite(outbuf, 1, outlen, output_file);
    fclose(output_file);

    // Clean up resources
    EVP_CIPHER_CTX_free(ctx);
    free(outbuf);

    return 0;
