}

// Define a logger class that can be used to log messages
class Logger {
public:
    // Constructor that takes the name of the application and creates a logger instance for it
    Logger(const std::string& app_name) : logger_(boost::log::trivial::logger(app_name)) {}

    // Log a message with a specific severity level (trace, debug, info, warn, error, fatal)
    void log(boost::log::trivial::severity_level level, const std::string& msg) {
        logger_.set_value(level);
        logger_.record_message(msg);
    }

private:
    boost::log::sources::logger logger_; // The Boost.Log logger instance
};

// Define a thread-safe log buffer that can be used to store logs from multiple threads
class LogBuffer {
public:
    LogBuffer() {}

    void push_back(const std::string& msg) {
        boost::lock_guard<boost::mutex> lock(mtx_); // Lock the mutex before modifying the log buffer
        messages_.push_back(msg);
    }

    std::vector<std::string> get() {
        return messages_; // Return a copy of the log buffer, so that multiple threads can access it safely
    }

private:
    boost::mutex mtx_; // The mutex used to protect the log buffer from concurrent access
    std::vector<std::string> messages_; // The log buffer itself
};

// Define a thread-safe logging function that can be called by multiple threads simultaneously
void log(const std::string& app_name, boost::log::trivial::severity_level level, const std::string& msg) {
    static LogBuffer* log_buffer = new LogBuffer(); // A singleton instance of the log buffer

    log_buffer->push_back(msg); // Add the message to the log buffer

    if (log_buffer->size() >= 100) { // If the log buffer is full, flush it to the central storage service
        std::vector<std::string> messages = log_buffer->get();
        send_messages(app_name, level, messages);
        log_buffer->clear();
    }
}

