public class StateLoader {
    private static final String CONFIG_FILE = "config.properties";
    private static final String FILE_PATH_KEY = "file.path";

    public MoSTState load(String filePath) throws IOException {
        // Load properties from config file
        Properties props = new Properties();
        try (FileInputStream inputStream = new FileInputStream(CONFIG_FILE)) {
            props.load(inputStream);
        } catch (IOException e) {
            System.out.println("Error loading configuration: " + e.getMessage());
            return null;
        }

        // Retrieve file path from properties
        String configFilePath = props.getProperty(FILE_PATH_KEY, null);
        if (configFilePath == null) {
            System.out.println("Error retrieving configuration: " + FILE_PATH_KEY + " not found");
            return null;
        }

        // Load state from file path
        MoSTState state = loadFromFile(configFilePath);
        if (state == null) {
            System.out.println("Error loading state: state is null");
            return null;
        }

        return state;
    }

    private MoSTState loadFromFile(String filePath) throws IOException {
        try (ObjectInputStream inputStream = new ObjectInputStream(new FileInputStream(filePath))) {
            MoSTState state = (MoSTState) inputStream.readObject();
            return state;
