['```rust
use std::{time, process};

fn compile_projects(project_dirs: Vec<String>) -> Result<Vec<Report>, String> {
    let mut reports = vec![];
    for project in project_dirs {
        let start_time = time::Instant::now();
        match process::Command::new("cargo").arg("build").current_dir(&project).status() {
            Ok(exit_code) => {
                if exit_code.success() {
                    reports.push(Report {
                        project: project,
                        duration: start_time.elapsed(),
                        memory_usage: get_resident_set_size(&project),
                        exit_code: exit_code.code().unwrap_or(-1),
                    });
                } else {
                    reports.push(Report {
                        project: project,
                        duration: start_time.elapsed(),
                        memory_usage: get_resident_set_size(&project),
                        exit_code: -1,
                    });
                }
            }
            Err(error) => {
                reports.push(Report {
                    project: project,
                    duration: start_time.elapsed(),
                    memory_usage: get_resident_set_size(&project),
                    exit_code: -1,
                });
            }
        };
    }
    Ok(reports)
}

struct Report {
    project: String,
    duration: time::Duration,
    memory_usage: u64,
    exit_code: i32,
}

fn get_resident_set_size(project: &String) -> u64 {
    process::Command::new("cargo")
        .arg("build")
        .current_dir(&project)
        .output()
        .and_then(|output| String::from_utf8(output.stderr).map_err(|error| error.to_string()))
        .and_then(|stderr| stderr.lines().next())
        .unwrap_or("".to_string())
        .trim()
        .parse::<u64>()
        .unwrap_or(0)
}
