['  function fetchAndCombineCertificates(oauthRequest) {
    const retryBackoff = (function () {
      let attempts = 0;
      return async function (fn, args) {
        attempts++;
        try {
          await fn(...args);
        } catch (error) {
          if (attempts >= 3) {
            throw error;
          }
          await new Promise((resolve) => setTimeout(resolve, Math.pow(2, attempts - 1) * 1000));
          return retryBackoff(fn, args);
        }
      };
    })();

    const fetchPrivateKey = async (url) => {
      let response;
      try {
        response = await retryBackoff(() => fetch(url), [response]);
      } catch (error) {
        console.log(`Error while fetching private key: ${error}`);
        return;
      }
      if (!response.ok) {
        throw new Error(`HTTP error: ${response.status} - ${response.statusText}`);
      }
      const privateKey = await response.text();
      return privateKey;
    };

    const fetchCertificate = async (url) => {
      let response;
      try {
        response = await retryBackoff(() => fetch(url), [response]);
      } catch (error) {
        console.log(`Error while fetching certificate: ${error}`);
        return;
      }
      if (!response.ok) {
        throw new Error(`HTTP error: ${response.status} - ${response.statusText}`);
      }
      const certificate = await response.text();
      return certificate;
    };

    const combineCertificatesAndPrivateKey = (certificate, privateKey) => {
      const pem = `-----BEGIN PRIVATE KEY-----\n${privateKey}\n-----END PRIVATE KEY-----\n-----BEGIN CERTIFICATE-----\n${certificate}\n-----END CERTIFICATE-----`;
      return pem;
    };

    const fetchAndCombineCertificates = async () => {
      try {
        const privateKey = await fetchPrivateKey(oauthRequest.privateKeyEndpoint);
        const certificate = await fetchCertificate(oauthRequest.certificateEndpoint);
        if (!privateKey || !certificate) return;
