#include <iostream>
#include <string>
#include <vector>
#include <memory>
#include <stdexcept>

// Define a templated struct to represent an octree node
template<typename T>
struct OctreeNode {
    // The key for the node, which is used to index into the tree
    const T& key;
    // The value stored in the node, which can be any type of data
    T value;
    // A pointer to the parent node
    OctreeNode<T>* parent;
    // A vector of pointers to child nodes, which are indexed by the keys of the child nodes
    std::vector<OctreeNode<T>*> children;
};

// Define a templated class to represent an octree data structure
template<typename T>
class Octree {
private:
    // The root node of the tree, which is used as the starting point for queries
    OctreeNode<T>* root;
    // A vector of pointers to all nodes in the tree, used for traversal and debugging purposes
    std::vector<OctreeNode<T>*> nodes;
    // The size of the tree, which is equal to the number of nodes in the tree
    int size;

public:
    // Constructor that initializes an empty octree with a given capacity
    explicit Octree(int capacity) {
        root = new OctreeNode<T>(nullptr);
        size = 0;
    }

    // Destructor that deallocates all nodes in the tree
    ~Octree() {
        for (int i = 0; i < size; ++i) {
            delete nodes[i];
        }
    }

    // Method to insert a new node into the octree with a given key and value
    void insert(const T& key, const T& value) {
        OctreeNode<T>* current = root;
        while (current->children.size() > 0) {
            int index = current->key.compare(key);
            if (index == 0) {
                // The key is already in the tree, so update the value and return
                current->value = value;
                return;
            } else if (index < 0) {
                // The key is less than the current node's key, so move to the left child
                current = current->children[index];
            } else {
                // The key is greater than the current node's key, so move to the right child
                current = current->children[-index - 1];
            }
        }

        // Add a new node with the given key and value as a child of the current node
        OctreeNode<T>* new_node = new OctreeNode<T>(key, value);
        current->children.push_back(new_node);

        // Update the size of the tree and add the new node to the vector of nodes for traversal
        ++size;
        nodes.push_back(new_node);
    }

    // Method to query a value from the octree given a key
    T& get(const T& key) {
        OctreeNode<T>* current = root;
        while (current->children.size() > 0) {
            int index = current->key.compare(key);
            if (index == 0) {
                return current->value;
            } else if (index < 0) {
                current = current->children[index];
            } else {
                current = current->children[-index - 1];
            }
        }

        // If the key is not in the tree, throw an exception
        throw std::runtime_error("Key not found");
    }

    // Method to print the octree structure and values for debugging purposes
    void print() {
        for (int i = 0; i < size; ++i) {
            std::cout << nodes[i]->key << ": " << nodes[i]->value << std::endl;
        }
    }
};

// Define a templated function to initialize an octree with data from an external data source
template<typename T>
void init_octree(Octree<T>& tree, const std::string& filename) {
    // Open the file containing the data and read it into memory
    std::ifstream file(filename);
    if (!file.is_open()) {
        throw std::runtime_error("Failed to open file");
    }

    // Initialize a vector to store the data in
    std::vector<T> data;

    // Read each line of the file and parse it into a key-value pair
    for (std::string line; getline(file, line);) {
        T key;
        T value;
        std::istringstream iss(line);
        if (!(iss >> key >> value)) {
            throw std::runtime_error("Failed to parse data");
        }

        // Insert the key-value pair into the octree
        tree.insert(key, value);
    }
}
```
This code defines a templated `Octree` class that can be used to represent an octree data structure with variable feature sizes and dynamic data expansion. The `init_octree` function is provided for convenience, allowing the octree to be initialized from an external data source.

The `OctreeNode` struct represents a node in the octree, which contains a key, value, pointer to the parent node, and vector of pointers to child nodes. The `Octree` class provides methods for inserting new nodes into the tree with a given key and value, querying values from the tree given a key, and printing the tree structure and values for debugging purposes.

The `init_octree` function takes an `Octree` object by reference as its first argument, and a string containing the name of the file to read data from as its second argument. It opens the file using `std::ifstream`, reads each line into memory using `getline`, and parses each line into a key-value pair using `std::istringstream`. The parsed data is then inserted into the octree using the `insert` method of the `Octree` class.

This code should be efficient, scalable, and easy to use, while also handling potential integration issues with external data sources and third-party libraries.']

