  // Optimize memory usage to minimize the risk of out-of-memory errors, especially under high load conditions
  optimize_memory(packet, len);
}

// Function to check if a packet is new and not already processed
bool is_new_packet(const char *packet) {
  // Check if the packet is valid and has not been processed recently
  if (packet == NULL || get_recent_packet_timestamp() >= time(NULL)) {
    return false;
  }

  // Check if the packet identifier is already in the cache
  int id = get_packet_id(packet);
  if (cache_contains(id)) {
    return false;
  }

  return true;
}

// Function to filter packets based on their source IP address, size, and rate
bool filter_packet(int src_ip, int packet_size, double packet_rate) {
  // Check if the packet is within the desired range of sizes and rates
  if (packet_size < MIN_PACKET_SIZE || packet_size > MAX_PACKET_SIZE || packet_rate < MIN_PACKET_RATE || packet_rate > MAX_PACKET_RATE) {
    return false;
  }

  // Check if the source IP address is within the desired range
  if (src_ip < MIN_SRC_IP || src_ip > MAX_SRC_IP) {
    return false;
  }

  return true;
}

// Function to cache recent packet identifiers and timestamps
void cache_packet(const char *packet, int len) {
  // Add the packet identifier and timestamp to the cache
  int id = get_packet_id(packet);
  long timestamp = time(NULL);
  cache_add(id, timestamp);
}

// Function to calculate the average packet size
int calculate_avg_packet_size() {
  // Calculate the sum of all packet sizes within the sliding window
  int total_size = 0;
  for (int i = 0; i < SLIDING_WINDOW_SIZE; i++) {
    total_size += get_packet_size(i);
  }

  // Calculate the average packet size
  return total_size / SLIDING_WINDOW_SIZE;
}

// Function to calculate the maximum packet size
int get_max_packet_size() {
  // Find the maximum packet size within the sliding window
  int max = 0;
  for (int i = 0; i < SLIDING_WINDOW_SIZE; i++) {
    if (get_packet_size(i) > max) {
      max = get_packet_size(i);
    }
  }

  return max;
}

// Function to update the sliding window of recent packets
void update_sliding_window(int src_ip, int packet_size) {
  // Remove any old packets from the sliding window if necessary
  long timestamp = time(NULL);
  for (int i = SLIDING_WINDOW_SIZE - 1; i >= 0; i--) {
    if (get_packet_timestamp(i) < timestamp - SLIDING_WINDOW_DURATION) {
      remove_packet(i);
    }
  }

  // Add the new packet to the sliding window
  add_packet(src_ip, packet_size, timestamp);
}

// Function to calculate the count of unique source IPs within the sliding window
int calculate_unique_source_ips() {
  // Initialize a set to store the unique source IPs
  std::set<int> src_ips;

  // Iterate over the packets in the sliding window and add their source IPs to the set
  for (int i = 0; i < SLIDING_WINDOW_SIZE; i++) {
    int id = get_packet_id(i);
    src_ips.insert(get_src_ip(id));
  }

  // Return the count of unique source IPs in the set
  return src_ips.size();
}

// Function to handle external logging and performance monitoring
void log_packet(const char *packet, int len) {
