public class DynamicValueGenerator
{
    private readonly Dictionary<string, (float min, float max)> _contexts = new();
    private string _activeContext;

    public void AddContext(string name, float min, float max)
    {
        if (_contexts.ContainsKey(name))
            throw new InvalidOperationException($"A context with the name '{name}' already exists.");

        _contexts[name] = (min, max);
    }

    public void RemoveContext(string name)
    {
        if (!_contexts.ContainsKey(name))
            throw new InvalidOperationException($"A context with the name '{name}' does not exist.");

        _contexts.Remove(name);
    }

    public void SetActiveContext(string name)
    {
        if (!_contexts.ContainsKey(name))
            throw new InvalidOperationException($"A context with the name '{name}' does not exist.");

        _activeContext = name;
    }

    public float GetNextFloat()
    {
        return NextFloat(_activeContext);
    }

    private float NextFloat(string contextName)
    {
        (float min, float max) contextParams = _contexts[contextName];
        float randomValue = Random.Range(contextParams.min, contextParams.max);
        return randomValue;
    }

    public int GetNextInt()
    {
        return NextInt(_activeContext);
    }

    private int NextInt(string contextName)
    {
        (float min, float max) contextParams = _contexts[contextName];
        int randomValue = Random.Range((int)Mathf.Floor(contextParams.min), (int)Mathf.Ceil(contextParams.max));
        return randomValue;
    }

    public override string ToString()
    {
        return $"Current active context: {_activeContext}, parameters: ({_contexts[_activeContext].min}, {_contexts[_activeContext].max})";
    }
}
