typedef struct {
    char* tag;
    int attr_count;
    char** attr_names;
    char** attr_values;
} html_element_t;

// Define a function to append a slash to an HTML element string if eligible
char* appendSlashOrReturnNull(char* input, int sizeLimit) {
    // Check for null pointer or empty input
    if (input == NULL || strlen(input) == 0) {
        return NULL;
    }

    // Initialize variables for tracking the state of the traversal
    html_element_t* element = parseHtmlElement(input);
    int attr_idx = 0;
    char* attr_value = NULL;
    char* output = NULL;

    // Recursively traverse the DOM structure and append slashes as needed
    while (element != NULL) {
        if (selectorFunction(element)) {
            // Append a slash to the element's tag name
            int len = strlen(element->tag);
            output = realloc(output, len + 2);
            memcpy(output, element->tag, len);
            output[len] = '/';
            output[len + 1] = '\0';
        } else {
            // Append the element's tag name and any nested elements
            int len = strlen(element->tag);
            output = realloc(output, len + 2);
            memcpy(output, element->tag, len);
            output[len] = ' ';
            output[len + 1] = '\0';
            if (element->attr_count > 0) {
                attr_idx = 0;
                while (attr_idx < element->attr_count && selectorFunction(element)) {
                    // Append the attribute name and value, separated by a space
                    int attr_len = strlen(element->attr_names[attr_idx]);
                    output = realloc(output, len + attr_len + 3);
                    memcpy(output, element->tag, len);
                    output[len] = ' ';
                    memcpy(output + len + 1, element->attr_names[attr_idx], attr_len);
                    output[len + attr_len + 1] = '=';
                    attr_value = element->attr_values[attr_idx];
                    int val_len = strlen(attr_value);
                    memcpy(output + len + attr_len + 2, attr_value, val_len);
                    output[len + attr_len + val_len + 2] = '\0';
                    attr_idx++;
                }
            }
        }

        // Recursively traverse the element's nested elements, if any
        html_element_t* child = element->next;
        while (child != NULL) {
            char* tmp = appendSlashOrReturnNull(child->tag, sizeLimit);
            if (tmp == NULL) {
                free(output);
                return NULL;
            } else {
                output = realloc(output, strlen(output) + strlen(tmp));
                memcpy(output + len, tmp, strlen(tmp));
                free(tmp);
            }
            child = child->next;
        }

        // Free the current element and move on to the next one
        html_element_t* next = element->next;
        freeElement(element);
        element = next;
    }

    return output;
}

// Define a function to parse an HTML element from a string
html_element_t* parseHtmlElement(char* input) {
    // Check for null pointer or empty input
    if (input == NULL || strlen(input) == 0) {
        return NULL;
    }

    html_element_t* element = malloc(sizeof(html_element_t));
    int pos = 0;

    // Parse the tag name and attributes, if any
    while (input[pos] != '\0' && input[pos] != ' ') {
        pos++;
    }
    element->tag = malloc(pos + 1);
    memcpy(element->tag, input, pos);
    element->tag[pos] = '\0';
    if (input[pos] == ' ') {
        int attr_count = 0;
        while (input[pos] != '\0' && input[pos] != '>') {
            // Parse the attribute name and value, if any
            while (input[pos] != '\0' && input[pos] != '=') {
                pos++;
            }
            int attr_len = 0;
            while (input[pos + attr_len] != '\0' && input[pos + attr_len] != ' ') {
                attr_len++;
            }
            char* attr_name = malloc(attr_len + 1);
            memcpy(attr_name, input + pos, attr_len);
            attr_name[attr_len] = '\0';
            int val_len = 0;
            while (input[pos + attr_len + val_len] != '\0' && input[pos + attr_len + val_len] != ' ') {
                val_len++;
            }
            char* attr_value = malloc(val_len + 1);
            memcpy(attr_value, input + pos + attr_len, val_len);
            attr_value[val_len] = '\0';
            element->attr_names = realloc(element->attr_names, sizeof(char*) * (attr_count + 1));
            element->attr_values = realloc(element->attr_values, sizeof(char*) * (attr_count + 1));
            element->attr_names[attr_count] = attr_name;
            element->attr_values[attr_count] = attr_value;
            pos += attr_len + val_len + 2; // skip past the attribute value and space after it
        }
    }

    return element;
}

// Define a function to free an HTML element and its attributes
void freeElement(html_element_t* element) {
    if (element != NULL) {
        int i = 0;
        while (i < element->attr_count) {
            free(element->attr_names[i]);
            free(element->attr_values[i]);
            i++;
        }
        free(element->tag);
        free(element->attr_names);
        free(element->attr_values);
        free(element);
    }
}

// Define a selector function to determine eligibility for appending a slash
int selectorFunction(html_element_t* element) {
    // This function can be modified to include additional selection criteria, such as class names or attribute values
    int i = 0;
    while (i < element->attr_count) {
        if (strcmp(element->attr_names[i], "class") == 0 && strcmp(element->attr_values[i], "active") == 0) {
            return 1;
        }
        i++;
    }
    return 0;
}
