// Struct to represent a theme with its bitmap image and metadata
typedef struct {
    char *bitmap;
    int length;
    int last_field[2];
} Theme;

// Function to check if default theme directory exists and create it if not
void check_default_theme_directory() {
    // Check if the default theme directory exists
    if (!fileExists("./themes")) {
        // Create the default theme directory with appropriate permissions
        mkdir("./themes", 0755);
    }
}

// Function to process a line of text and return a Theme struct
Theme *process_line(char *line) {
    // Split the line into metadata fields using spaces as delimiters
    char **fields = strsplit(line, ' ');

    // Check if the line has the required number of fields
    if (strlen(fields[0]) < 2 || strlen(fields[1]) != 4) {
        return NULL;
    }

    // Allocate memory for the theme bitmap
    Theme *theme = malloc(sizeof(Theme));
    theme->bitmap = fields[0];

    // Store the length of the metadata field in the struct
    theme->length = strlen(fields[1]);

    // Split the last two numeric fields into their own arrays
    char **last_field = strsplit(fields[1], ',');

    // Calculate the average of the last two numeric fields and store it in the struct
    int sum = 0;
    for (int i = 0; i < 2; i++) {
        sum += atoi(last_field[i]);
    }
    theme->last_field[0] = sum / 2;

    // Free the memory allocated for the last field array
    free(last_field);

    return theme;
}

// Function to process a text file and output each line in a comma-separated format
void process_file(FILE *file) {
    // Check if the file exists and is not empty
    if (!fileExists(file)) {
        printf("File does not exist or is empty\n");
        return;
    }

    // Initialize an array to store the processed themes
    Theme **themes = malloc(sizeof(Theme *) * file_size(file));
    int i = 0;

    // Read each line of the file and process it
    char *line = NULL;
    while ((line = fgets(file)) != NULL) {
        Theme *theme = process_line(line);

        if (theme != NULL) {
            themes[i++] = theme;
        }
    }

    // Output each processed theme in a comma-separated format
    for (int i = 0; i < file_size(file); i++) {
        Theme *theme = themes[i];

        printf("%s,", theme->bitmap);
        printf("%d,", theme->length);
        printf("%d\n", theme->last_field[0]);
    }
}

// Function to free the memory allocated for a Theme struct
void free_theme(Theme *theme) {
    free(theme->bitmap);
    free(theme);
}

int main() {
    // Check if the default theme directory exists and create it if not
    check_default_theme_directory();

    // Open the text file containing themes represented as bitmap images
    FILE *file = fopen("./themes/themes.txt", "r");

    // Process each line of the file and output each processed theme in a comma-separated format
    process_file(file);

    // Free the memory allocated for each Theme struct
    free_theme(themes);

    return 0;
}
