#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/sha.h>
#include "tiff_utils.h"

typedef struct TiffFileInfo {
    int bits_per_sample;
    int samples_per_pixel;
    int num_extra_samples;
    char* sha256_hash;
} TiffFileInfo;

TiffFileInfo processTiffFile(const char* filepath) {
    FILE* fp = fopen(filepath, "rb");
    if (fp == NULL) {
        perror("Failed to open TIFF file");
        return NULL;
    }

    // Read the header of the TIFF file
    TiffHeader header;
    fread(&header, sizeof(TiffHeader), 1, fp);

    // Check if the file is a valid TIFF image
    if (header.magic_number != 0x4949 && header.magic_number != 0x4D4D) {
        perror("Invalid TIFF magic number");
        return NULL;
    }

    // Read the image data from the file
    int num_images = (header.num_directories - 1) * header.max_directory_count;
    TiffImage* images = malloc(sizeof(TiffImage) * num_images);
    for (int i = 0; i < num_images; i++) {
        fread(&images[i], sizeof(TiffImage), 1, fp);
    }

    // Extract the bits per sample and sample per pixel information from the image data
    int bits_per_sample = images[0].bits_per_sample;
    int samples_per_pixel = images[0].samples_per_pixel;

    // Check if the image has any extra samples, and calculate the number of bytes needed to store them
    int num_extra_samples = 0;
    for (int i = 1; i < num_images; i++) {
        num_extra_samples += images[i].samples_per_pixel - samples_per_pixel;
    }

    // Allocate memory to store the extra sample values
    unsigned char* extra_samples = malloc(num_extra_samples * sizeof(unsigned char));

    // Read the extra sample values from the file
    for (int i = 0, j = 1; i < num_images; i++) {
        if (images[i].samples_per_pixel > samples_per_pixel) {
            int num_extra_samples_read = images[i].samples_per_pixel - samples_per_pixel;
            fread(extra_samples + j * num_extra_samples, sizeof(unsigned char), num_extra_samples_read, fp);
        }
    }

    // Calculate the SHA-256 hash of the file content
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    while (1) {
        unsigned char buffer[4096];
        size_t read = fread(buffer, 1, sizeof(buffer), fp);
        if (read == 0) break;
        SHA256_Update(&ctx, buffer, read);
    }
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_Final(hash, &ctx);

    // Return the TiffFileInfo struct with the extracted information and the SHA-256 hash
    TiffFileInfo info;
    info.bits_per_sample = bits_per_sample;
    info.samples_per_pixel = samples_per_pixel;
    info.num_extra_samples = num_extra_samples;
    info.sha256_hash = malloc(SHA256_DIGEST_LENGTH * sizeof(char));
    memcpy(info.sha256_hash, hash, SHA256_DIGEST_LENGTH);

    // Clean up memory allocation
    free(extra_samples);
    for (int i = 0; i < num_images; i++) {
        free(&images[i]);
    }
    free(images);

    return info;
}
```
This function takes a file path as input and processes the TIFF image file, extracting information about the bits per sample, sample per pixel, and any extra samples. It also generates a SHA-256 hash of the file content for data integrity purposes. The function first reads the header of the TIFF file to determine its validity and the number of images it contains. Then, it reads each image from the file and extracts the bits per sample and sample per pixel information. If the image has any extra samples, it allocates memory to store them and reads them from the file. Finally, the function calculates the SHA-256 hash of the file content using the `SHA256_Update` and `SHA256_Final` functions from the OpenSSL library. The function returns a custom `TiffFileInfo` struct with the extracted information and the SHA-256 hash, and frees any allocated memory before returning.']

