// Function to manage theme caching and cryptographic operations for a mobile application
void initThemeCipher(const char *password) {
    // Initialize AES-256-CBC cipher with given password
    EVP_CIPHER_CTX *ctx;
    const EVP_CIPHER *cipher;
    unsigned char key[32], iv[16];
    int len, ret;

    // Set IV length to 16 bytes (AES-256-CBC)
    memset(iv, 0, sizeof(iv));

    // Derive encryption key from password using SHA-256
    SHA256_CTX sha256;
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, password, strlen(password));
    SHA256_Final(hash, &sha256);
    memcpy(key, hash, sizeof(key));

    // Enable AES-256-CBC cipher
    cipher = EVP_get_cipherbyname("AES-256-CBC");
    ctx = EVP_CIPHER_CTX_new();
    ret = EVP_EncryptInit(ctx, cipher, key, iv);
    if (ret != 1) {
        printf("Error initializing AES-256-CBC cipher\n");
        return NULL;
    }

    // Enable theme caching and cryptographic operations
    FILE *file = fopen("theme_cache", "r+b");
    if (file == NULL) {
        printf("Error opening theme cache file\n");
        return NULL;
    }
    ret = EVP_EncryptUpdate(ctx, iv, sizeof(iv), NULL, 0);
    if (ret != 1) {
        printf("Error encrypting IV\n");
        return NULL;
    }
    len = fread(file, 1, sizeof(file), file);
    ret = EVP_EncryptUpdate(ctx, file, len, NULL, 0);
    if (ret != 1) {
        printf("Error encrypting theme cache\n");
        return NULL;
    }
    fclose(file);

    // Clean up and disable cipher resources
    EVP_CIPHER_CTX_free(ctx);
    return ctx;
}

