int mediaConverter(struct media_config *config) {
    /* Define variables for temporary files and conversion process */
    int infile, outfile;
    char *infilename = config->input_file;
    char *outfilename = config->output_file;
    char *tempfilename1 = "temp1.jpg";
    char *tempfilename2 = "temp2.pdf";
