    /* Create temporary files for conversion */
    tempfd1 = creat(tempfilename1, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    tempfd2 = creat(tempfilename2, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);

    if (tempfd1 < 0 || tempfd2 < 0) {
        /* Log error and return failure */
        perror("Error creating temporary files");
        return 1;
    }

    /* Copy input file to temporary file for conversion */
    buffer = malloc(BUFSIZ);
    bytesread = read(infile, buffer, BUFSIZ);
    while (bytesread > 0) {
        bytestoread = write(tempfd1, buffer, bytesread);
        if (bytestoread != bytesread) {
            /* Log error and return failure */
            perror("Error writing to temporary file");
            return 1;
        }
        bytesread = read(infile, buffer, BUFSIZ);
    }
    free(buffer);

    /* Close input file */
    close(infile);

    /* Convert image from JPEG to PDF using third-party library */
    if (convert_jpeg_to_pdf(tempfilename1, tempfilename2) != 0) {
        /* Log error and return failure */
        perror("Error converting image");
        return 1;
    }

    /* Delete temporary files */
    unlink(tempfilename1);
    unlink(tempfilename2);

    /* Open PDF output file */
    outfile = open(outfilename, O_RDONLY);

    if (outfile < 0) {
        /* Log error and return failure */
        perror("Error opening output file");
        return 1;
    }

    /* Copy PDF output file to memory */
    buffer = malloc(BUFSIZ);
    bytesread = read(outfile, buffer, BUFSIZ);
    while (bytesread > 0) {
        bytestoread = write(1, buffer, bytesread);
        if (bytestoread != bytesread) {
            /* Log error and return failure */
            perror("Error writing to output file");
            return 1;
        }
        bytesread = read(outfile, buffer, BUFSIZ);
    }
    free(buffer);

    /* Close output file */
    close(outfile);

    return 0;
}

