#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>

// Define the maximum number of concurrent processes and file descriptors
#define MAX_PROCESSES 100
#define MAX_FILEDESCRIPTORS 256

// Structure to hold information about each command
typedef struct {
    char* command;
    int fileDescriptor;
} Command;

int executeCommand(const char* command, int fileDescriptor) {
    // Validate the input parameters
    if (command == NULL || fileDescriptor < 0) {
        return -1;
    }

    // Create a new process to execute the command
    pid_t pid = fork();
    if (pid == 0) {
        // Child process: execute the command and exit
        execl(command, "sh", "-c", NULL);
        _exit(1);
    } else if (pid > 0) {
        // Parent process: wait for the child process to finish and return its status code
        int status;
        waitpid(pid, &status, 0);
        return WIFEXITED(status) ? WEXITSTATUS(status) : -1;
    } else {
        // Fork failed: handle the error
        perror("fork");
        return -1;
    }
}

int manageCommands(Command commands[], int numCommands) {
    // Initialize the resource usage and allocate memory for the command structures
    struct rusage usage;
    Command* allocatedCommands = (Command*) malloc(numCommands * sizeof(Command));

    // Loop through each command and execute it if possible
    for (int i = 0; i < numCommands; ++i) {
        // Check if the command is valid and if there are available resources
        if (!validateCommand(&commands[i]) || !checkResourceUsage(&usage)) {
            continue;
        }

        // Execute the command and handle errors
        int status = executeCommand(commands[i].command, commands[i].fileDescriptor);
        if (status < 0) {
            perror("executeCommand");
            return 0;
        }
    }

    // Free the memory allocated for the command structures and return success
    free(allocatedCommands);
    return 1;
}

int validateCommand(const Command* command) {
    // Check if the command is null or empty
    if (command == NULL || strlen(command->command) == 0) {
        return 0;
    }

    // Check if the file descriptor is valid and if it corresponds to a valid file
    if (command->fileDescriptor < 0 || !validateFileDescriptor(command->fileDescriptor)) {
        return 0;
    }

    // The command is valid: return success
    return 1;
}

int validateFileDescriptor(int fd) {
    // Check if the file descriptor is open and corresponds to a valid file
    struct stat sb;
    if (fstat(fd, &sb) < 0 || !S_ISREG(sb.st_mode)) {
        return 0;
    }

    // The file descriptor is valid: return success
    return 1;
}

int checkResourceUsage(struct rusage* usage) {
    // Check if the system has exceeded the maximum number of concurrent processes or file descriptors
    if (usage->ru_nivcsw >= MAX_PROCESSES || usage->ru_nfd + 1 >= MAX_FILEDESCRIPTORS) {
        return 0;
    }

    // The system has enough resources: return success
    return 1;
}
