using System.IO;

public struct ImageFileInfo {
    public int BitsPerSample { get; set; }
    public int SamplesPerPixel { get; set; }
    public int ExtraSamples { get; set; }
    public string Sha256Hash { get; set; }
}

public ImageFileInfo processImageFile(byte[] fileData) {
    // Initialize image metadata struct
    var imgMetadata = new ImageFileInfo();

    try {
        using (var ms = new MemoryStream(fileData)) {
            // Read TIFF or binary data structure from memory stream
            var reader = new BinaryReader(ms);

            // Determine bits per sample and samples per pixel
            imgMetadata.BitsPerSample = reader.ReadInt16();
            imgMetadata.SamplesPerPixel = reader.ReadInt32();

            // Handle unsupported bits per sample or invalid structure gracefully
            if (imgMetadata.BitsPerSample < 0 || imgMetadata.BitsPerSample > 16) {
                throw new Exception("Unsupported bits per sample");
            }

            // Read extra samples if present
            if (imgMetadata.SamplesPerPixel > 3) {
                imgMetadata.ExtraSamples = reader.ReadInt32();
            }

            // Hash file content using SHA-256
            var sha = new SHA256Managed();
            var hashBytes = sha.ComputeHash(ms);
            imgMetadata.Sha256Hash = BitConverter.ToString(hashBytes).Replace("-", "");
        }
    } catch (Exception e) {
        // Log error message to specified error log file
        Console.WriteLine($"Error processing image file: {e.Message}");
    }

    return imgMetadata;
}
```
