using System.Text;

public class CryptoUtils {
    public static string DecryptTripleDes(string base64EncodedMessage, string password) {
        // Generate key and IV from password using HMAC-SHA1
        var hmac = new HMACSHA1(Encoding.ASCII.GetBytes(password));
        byte[] key = hmac.ComputeHash("key".ToCharArray());
        byte[] iv = hmac.ComputeHash("iv".ToCharArray());

        // Convert base64-encoded message to bytes
        var plainTextBytes = Convert.FromBase64String(base64EncodedMessage);

        // Decrypt message using Triple DES encryption
        var tripleDes = new TripleDESCryptoServiceProvider();
        try {
            var decryptedBytes = EncryptionUtils.DecryptTripleDes(plainTextBytes, key, iv);
            return Encoding.UTF8.GetString(decryptedBytes);
        } catch (Exception e) {
            // Log error and return empty string to indicate decryption failure
            Console.WriteLine($"Error decrypting message: {e.Message}");
            return "";
        } finally {
            tripleDes.Clear();
        }
    }
}

public static class EncryptionUtils {
    public static byte[] DecryptTripleDes(byte[] cipherTextBytes, byte[] key, byte[] iv) {
        using (var provider = new TripleDESCryptoServiceProvider()) {
            provider.Key = key;
            provider.IV = iv;
            return provider.CreateDecryptor().TransformFinalBlock(cipherTextBytes, 0, cipherTextBytes.Length);
        }
    }
