using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public static async Task<Dictionary<string, string>> CalculateHashes(string filePath)
{
    using var stream = new FileStream(filePath, FileMode.Open);
    using var hashAlgorithm = SHA256.Create();
    var dictionary = new Dictionary<string, string>();

    await foreach (var line in ReadLinesAsync(stream))
    {
        var hash = ComputeHash(line, hashAlgorithm);
        dictionary[line] = hash;
    }

    return dictionary;
}

private static async Task<IEnumerable<string>> ReadLinesAsync(Stream stream)
{
    using var reader = new StreamReader(stream);

    while (!reader.EndOfStream)
    {
        yield return await reader.ReadLineAsync();
    }
}

private static string ComputeHash(string input, SHA256 hashAlgorithm)
{
    var data = Encoding.UTF8.GetBytes(input);
    var hash = hashAlgorithm.ComputeHash(data);
    return Convert.ToBase64String(hash);
}
```
This implementation uses the `FileStream` class to read the file line by line, and the `SHA256` class to compute the SHA-256 hash for each line. The `ReadLinesAsync` method is used to asynchronously read lines from the stream, allowing for efficient handling of large files.

