namespace EncryptionDecryptionFramework
{
    public class EncryptionDecryption
    {
        // Initialize the AES encryption algorithm with a secure random IV
        private static readonly AesEncryption _aes = new AesEncryption(AesAlgorithm.CBC, SecureRandom.GenerateSeed(16));

        // Key management service integration
        private static readonly KeyManagementService _kms = new KeyManagementService();

        // Decryption process with HMAC-SHA256 integrity verification and padding error detection
        public static byte[] Decrypt(byte[] ciphertext)
        {
            try
            {
                // Extract the IV from the ciphertext
                byte[] iv = new byte[16];
                Array.Copy(ciphertext, 0, iv, 0, iv.Length);

                // Decrypt the ciphertext using the AES algorithm
                byte[] plaintext = _aes.Decrypt(ciphertext);

                // Verify integrity of the decrypted data using HMAC-SHA256
                byte[] hmac = HMACSha256.ComputeHash(plaintext, _kms.GetKey());
                if (!hmac.SequenceEqual(iv))
                {
                    throw new DecryptionException("Integrity check failed.");
                }

                // Remove padding from the decrypted data
                int paddingLength = plaintext[0];
                byte[] unpaddedPlaintext = new byte[plaintext.Length - paddingLength];
                Array.Copy(plaintext, 1, unpaddedPlaintext, 0, unpaddedPlaintext.Length);

                return unpaddedPlaintext;
            }
            catch (DecryptionException e)
            {
                Console.WriteLine($"Error decrypting data: {e.Message}");
                return null;
            }
        }

        // Encryption process with secure IV generation and HMAC-SHA256 integrity verification
        public static byte[] Encrypt(byte[] plaintext)
        {
            try
            {
                // Generate a new secure IV for each encryption operation
                byte[] iv = SecureRandom.GenerateSeed(16);

                // Encrypt the plaintext using the AES algorithm
                byte[] ciphertext = _aes.Encrypt(plaintext);

                // Add padding to the encrypted data
                int paddingLength = 16 - (ciphertext.Length % 16);
                if (paddingLength < 16)
                {
                    paddingLength += 16;
                }
                byte[] paddedCiphertext = new byte[ciphertext.Length + paddingLength];
                Array.Copy(ciphertext, paddedCiphertext, ciphertext.Length);
                for (int i = 0; i < paddingLength; i++)
                {
                    paddedCiphertext[ciphertext.Length + i] = (byte)(paddingLength - 1);
                }

                // Store the IV alongside the ciphertext for decryption
                byte[] encryptedData = new byte[iv.Length + paddedCiphertext.Length];
                Array.Copy(iv, encryptedData, iv.Length);
                Array.Copy(paddedCiphertext, 0, encryptedData, iv.Length, paddedCiphertext.Length);

                // Verify integrity of the encrypted data using HMAC-SHA256
                byte[] hmac = HMACSha256.ComputeHash(encryptedData, _kms.GetKey());
                if (!hmac.SequenceEqual(iv))
                {
                    throw new EncryptionException("Integrity check failed.");
                }

                return encryptedData;
            }
            catch (EncryptionException e)
            {
                Console.WriteLine($"Error encrypting data: {e.Message}");
                return null;
            }
        }
    }

    public class DecryptionException : Exception
    {
        public DecryptionException(string message) : base(message) {}
    }

    public class EncryptionException : Exception
    {
        public EncryptionException(string message) : base(message) {}
    }
}
