using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

public class DataLoader
{
    public static async Task<CustomData> LoadAsync(string filePath, CancellationToken cancellationToken = default)
    {
        // Validate input parameters
        if (string.IsNullOrEmpty(filePath))
            throw new ArgumentException("Invalid file path", nameof(filePath));

        // Open the compressed binary file for reading
        using var fileStream = File.OpenRead(filePath);

        // Determine the compression format of the file
        var compressionFormat = GetCompressionFormat(filePath);

        // Read the header of the file to determine the size of the data structure
        using var reader = new BinaryReader(fileStream, Encoding.UTF8, true);
        var dataStructureSize = reader.ReadInt32();

        // Create a new instance of the custom data structure
        var dataStructure = new CustomData { Size = dataStructureSize };

        // Deserialize the data from the file stream
        using var decompressionStream = GetDecompressionStream(fileStream, compressionFormat);
        await DeserializeAsync(decompressionStream, dataStructure, cancellationToken).ConfigureAwait(false);

        // Validate the integrity of the deserialized data
        ValidateDataIntegrity(dataStructure);

        // Return the deserialized data structure
        return dataStructure;
    }

    private static Stream GetDecompressionStream(Stream compressedFileStream, CompressionFormat compressionFormat)
    {
        switch (compressionFormat)
        {
            case CompressionFormat.GZip:
                return new GZipStream(compressedFileStream, CompressionMode.Decompress);
            case CompressionFormat.Deflate:
                return new DeflateStream(compressedFileStream, CompressionMode.Decompress);
            default:
                throw new NotSupportedException($"Compression format {compressionFormat} is not supported");
        }
    }

    private static async Task DeserializeAsync(Stream decompressionStream, CustomData dataStructure, CancellationToken cancellationToken = default)
    {
        // Deserialize the data from the decompression stream into the custom data structure
        using var reader = new BinaryReader(decompressionStream, Encoding.UTF8, true);
        for (int i = 0; i < dataStructure.Size; i++)
        {
            if (cancellationToken.IsCancellationRequested)
                break;

            // Read the next item from the file stream
            var item = reader.ReadString();

