package com.example;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.util.ArrayList;
import java.util.List;

public class Deserializer {
    private static final List<String> TRUSTED_PACKAGES = new ArrayList<>();

    // Add trusted packages to the list as necessary
    static {
        TRUSTED_PACKAGES.add("com.example.package1");
        TRUSTED_PACKAGES.add("com.example.package2");
    }

    public <T> T deserialize(byte[] data, Class<T> clazz) throws RuntimeException {
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data))) {
            // Check if the incoming class is in the trusted packages list
            String className = ois.readUTF();
            if (!TRUSTED_PACKAGES.contains(className)) {
                throw new RuntimeException("Class not found in trusted package: " + className);
            }

            // Validate the incoming data
            validateIncomingData(data, clazz);

            // Deserialize the object
            return (T) ois.readObject();
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("Failed to deserialize object", e);
        }
    }

    private void validateIncomingData(byte[] data, Class<?> clazz) throws IOException {
        // Check if the incoming data is valid
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data))) {
            ois.readUTF(); // Read class name
            ois.readObject(); // Read object data
        } catch (ClassNotFoundException e) {
            throw new IOException("Invalid data", e);
        }
    }
}

// Sample usage:
Deserializer deserializer = new Deserializer();
MyInterface myInterface = deserializer.deserialize(data, MyInterface.class);

interface MyInterface {
    // Interface methods
}']

