use std::env;
use std::error::Error;
use std::fs::File;
use std::io::{self, BufWriter};
use std::path::PathBuf;
use std::process::Command;
use std::str::FromStr;
use tokio::runtime::Builder;
use tokio::task::JoinHandle;

// Environment variables for adjustable logging thresholds and retry intervals
const LOGGING_THRESHOLD: &str = "LOGGING_THRESHOLD";
const RETRY_INTERVAL: &str = "RETRY_INTERVAL";

#[tokio::main]
async fn main() -> Result<(), Box<dyn Error>> {
    // Create a Tokio runtime builder with default configuration
    let mut builder = Builder::new();

    // Set the number of threads to use for the runtime
    builder.threaded_scheduler().core_threads(8);

    // Build the runtime and spawn it as an asynchronous task
    let runtime = builder.build()?;
    let handle = JoinHandle::spawn(runtime);

    // Create a buffered writer for logging
    let mut buffer = BufWriter::new(File::create("log.txt")?);

    // Set the logging threshold and retry interval based on environment variables
    let logging_threshold: usize = match env::var(LOGGING_THRESHOLD) {
        Ok(val) => val.parse().unwrap(),
        Err(_) => 5,
    };
    let retry_interval: u64 = match env::var(RETRY_INTERVAL) {
        Ok(val) => val.parse().unwrap(),
        Err(_) => 10,
    };

    // Iterate over the command-line arguments
    for arg in env::args() {
        // Check if the argument is a valid URL
        let url = match FromStr::from_str(&arg) {
            Ok(url) => url,
            Err(_) => continue,
        };

        // Fetch real-time data from the external API
        let response = Command::new("curl")
            .args(&["--silent", &url])
            .output()?;

        // Parse the response as JSON and handle errors gracefully
        let json: serde_json::Value = match serde_json::from_slice(&response.stdout) {
            Ok(val) => val,
            Err(err) => {
                log_error(format!("Failed to parse JSON: {}", err));
                continue;
            }
        };

        // Extract the data from the response and handle errors gracefully
        let data = match json.get("data") {
            Some(val) => val,
            None => {
                log_error("Invalid response".to_string());
                continue;
            }
        };

        // Process the data asynchronously and handle errors gracefully
        let task = tokio::spawn(async move {
            match process_data(&data).await {
                Ok(_) => (),
                Err(err) => log_error(format!("Failed to process data: {}", err)),
            }
        });

        // Add the task to the runtime's scheduler and handle errors gracefully
        match handle.add(task).await {
            Ok(_) => (),
            Err(err) => log_error(format!("Failed to add task to runtime: {}", err)),
        };
    }

    // Wait for the runtime to finish processing all tasks and shut down gracefully
    handle.shutdown().await;

    Ok(())
}

// Log an error message asynchronously using `snprintf` for efficient resource utilization during peak load times
fn log_error(message: String) {
    let mut buffer = BufWriter::new(File::create("log.txt")?);
    buffer.write_fmt(format_args!("{}: {}", "ERROR", message)).unwrap();
}

// Process the data asynchronously using the Tokio library to handle failures gracefully and ensure minimal impact on overall service availability
async fn process_data(data: &serde_json::Value) -> Result<(), Box<dyn Error>> {
    // Handle errors gracefully
    match data.get("error") {
        Some(val) => Err(format!("Invalid response: {}", val)),
        None => (),
    };

    // Process the data asynchronously using the Tokio library
    let task = tokio::spawn(async move {
        match process_data(&data).await {
            Ok(_) => (),
            Err(err) => log_error(format!("Failed to process data: {}", err)),
        }
    });

    // Add the task to the runtime's scheduler and handle errors gracefully
    match handle.add(task).await {
        Ok(_) => (),
        Err(err) => log_error(format!("Failed to add task to runtime: {}", err)),
    };

    // Return a successful result
    Ok(())
}
