// Define the structure for the array of records
typedef struct {
    int value;
} Record;

// Function to read input from standard input and initialize an array of records
Record* readInput(int numRecords) {
    // Check if the number of records is valid
    if (numRecords <= 0) {
        return NULL;
    }

    // Allocate memory for the array of records
    Record* records = malloc(sizeof(Record) * numRecords);
    if (records == NULL) {
        return NULL;
    }

    // Initialize each record with a default value of 0
    for (int i = 0; i < numRecords; i++) {
        records[i].value = 0;
    }

    // Read input from standard input and update the values in the array of records
    int inputValue;
    while (scanf("%d", &inputValue) == 1) {
        if (inputValue < 0 || inputValue >= numRecords) {
            continue;
        }
        records[inputValue].value++;
    }

    return records;
}

// Function to print the largest integer in the array of records
void printLargest(Record* records, int numRecords) {
    // Check if the input is valid
    if (records == NULL || numRecords <= 0) {
        return;
    }

    // Find the index of the largest value in the array
    int largestIndex = 0;
    for (int i = 1; i < numRecords; i++) {
        if (records[i].value > records[largestIndex].value) {
            largestIndex = i;
        }
    }

    // Print the value at the largest index
    printf("Largest integer: %d\n", largestIndex);
}

// Main function to demonstrate the use of the readInput and printLargest functions
int main() {
    // Read input from standard input and initialize an array of records
    int numRecords = 5;
    Record* records = readInput(numRecords);

    // Print the largest integer in the array
    printLargest(records, numRecords);

    return 0;
}']

