// C Header File
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

struct Record {
    int key;
    long offset;
    int value;
};

typedef struct {
    struct Record *records;
    size_t numRecords;
    size_t maxNumRecords;
    size_t recordSize;
} MemoryEfficientDataStructure;

MemoryEfficientDataStructure* createMemoryEfficientDataStructure(size_t initialMaxNumRecords) {
    // Calculate the total memory usage for the records array and initialize it with malloc()
    size_t totalMemUsage = sizeof(struct Record) * initialMaxNumRecords;
    struct MemoryEfficientDataStructure* data = (struct MemoryEfficientDataStructure*)malloc(totalMemUsage);
    if (!data) {
        // Handle memory allocation error
    }
    data->records = NULL;
    data->numRecords = 0;
    data->maxNumRecords = initialMaxNumRecords;
    data->recordSize = sizeof(struct Record);
    return data;
}

void destroyMemoryEfficientDataStructure(struct MemoryEfficientDataStructure* data) {
    if (data && data->records) {
        free(data->records);
        data->records = NULL;
    }
    free(data);
}

void insertRecord(struct MemoryEfficientDataStructure* data, int key, long offset, int value) {
    if (data->numRecords == data->maxNumRecords) {
        // Increase the maximum number of records and reallocate memory for the records array
        size_t newMaxNumRecords = ceil(data->maxNumRecords * 1.5);
        size_t totalMemUsage = sizeof(struct Record) * newMaxNumRecords;
        struct Record* newRecords = (struct Record*)realloc(data->records, totalMemUsage);
        if (!newRecords) {
            // Handle memory allocation error
        }
        data->records = newRecords;
        data->maxNumRecords = newMaxNumRecords;
    }
    struct Record* record = &data->records[data->numRecords++];
    record->key = key;
    record->offset = offset;
    record->value = value;
}

struct Record* lookupRecord(struct MemoryEfficientDataStructure* data, int key) {
    for (int i = 0; i < data->numRecords; ++i) {
        if (data->records[i].key == key) {
            return &data->records[i];
        }
    }
    // Return NULL if the record is not found
    return NULL;
}

void updateRecord(struct MemoryEfficientDataStructure* data, int key, long offset, int value) {
    struct Record* record = lookupRecord(data, key);
    if (record) {
        record->offset = offset;
        record->value = value;
    }
}

void iterateRecords(struct MemoryEfficientDataStructure* data, void (*callback)(struct Record*)) {
    for (int i = 0; i < data->numRecords; ++i) {
        callback(&data->records[i]);
    }
}

// Main function
int main() {
    struct MemoryEfficientDataStructure* data = createMemoryEfficientDataStructure(10); // Initially allocate space for 10 records
    insertRecord(data, 1, 2, 3);
    insertRecord(data, 4, 5, 6);
    struct Record* record = lookupRecord(data, 1);
    if (record) {
        printf("Key: %d, Offset: %ld, Value: %d\n", record->key, record->offset, record->value);
    } else {
        printf("The record with key 1 is not found\n");
    }
    updateRecord(data, 4, 7, 8);
    iterateRecords(data, (struct Record* r) {
        printf("Key: %d, Offset: %ld, Value: %d\n", r->key, r->offset, r->value);
    });
    destroyMemoryEfficientDataStructure(data);
    return 0;
}

// Output:
// Key: 1, Offset: 2, Value: 3
// Key: 4, Offset: 7, Value: 8
// Key: 1, Offset: 2, Value: 3
// Key: 4, Offset: 7, Value: 8']

