void processInputStrings(const vector<string>& input_strings) {
    // Initialize a vector to store the hashed strings.
    vector<unsigned long long> hashes;

    // Iterate over the input strings and calculate their hash values.
    for (auto& input_string : input_strings) {
        if (!input_string.empty() && input_string.length() <= 4096) {
            unsigned long long hash = std::hash<std::string>{}(input_string);
            hashes.push_back(hash);
        } else {
            // Log the string as invalid and skip it.
            cerr << "Invalid input string: " << input_string << endl;
        }
    }

    // Sort the vector of hashes.
    std::sort(hashes.begin(), hashes.end());

    // Calculate the frequency of each hash value.
    unordered_map<unsigned long long, int> hash_frequencies;
    for (auto& hash : hashes) {
        ++hash_frequencies[hash];
    }

    // Print the top 10 most frequent hash values and their frequencies.
    cout << "Top 10 most frequent hash values:" << endl;
    for (const auto& entry : hash_frequencies) {
        if (entry.second > 10) {
            cout << entry.first << ": " << entry.second << endl;
        }
    }
}

