using System;
using System.Net.Http;
using System.Security.Cryptography.X509Certificates;
using System.Threading;
using System.Threading.Tasks;

namespace HTTPClientContextManager
{
    public class HTTPClientContextManager
    {
        private readonly Dictionary<string, HttpClient> _clients = new Dictionary<string, HttpClient>();
        private readonly IConfigurationService _configurationService;

        public HTTPClientContextManager(IConfigurationService configurationService)
        {
            _configurationService = configurationService;
        }

        public async Task<HttpResponseMessage> MakeRequestAsync(string url, bool validateCertificate, int timeoutMilliseconds)
        {
            var client = GetOrCreateClient(url, validateCertificate);
            return await client.GetAsync(url).ConfigureAwait(false);
        }

        private HttpClient GetOrCreateClient(string url, bool validateCertificate)
        {
            if (!_clients.ContainsKey(url))
            {
                _clients[url] = new HttpClient();
                _clients[url].DefaultRequestHeaders.Add("User-Agent", "HTTP Client Context Manager");

                if (validateCertificate)
                {
                    var certs = _configurationService.Get<List<X509Certificate2>>("certificates");
                    _clients[url].DefaultRequestHeaders.Add("Accept", "application/json");
                }
            }

            return _clients[url];
        }

        public void ResetClient(string url)
        {
            if (_clients.ContainsKey(url))
            {
                var client = _clients[url];
                client.DefaultRequestHeaders.Clear();
                client.DefaultRequestHeaders.Add("User-Agent", "HTTP Client Context Manager");
            }
        }

        public override string ToString()
        {
            return $"Active Context: {_clients.Count}";
        }
    }
}
```
