    LoggingInfo logging_info = {logFilename, NULL};
    if (logging_info.logfile != NULL) {
        logging_info.log_stream = fopen(logging_info.logfile, "w");
        if (logging_info.log_stream == NULL) {
            result.errors = "Error opening log file";
            return result;
        }
        fprintf(logging_info.log_stream, "Sample rate: %d\nChannels: %d\nFrame rate: %f\n",
                audio_stream.sample_rate, audio_stream.channels, audio_stream.frame_rate);
    }

    // Apply the effects to the audio stream
    if (effects != NULL) {
        char *effects_str = strdup(effects);
        char *token = strtok(effects_str, ",");
        while (token != NULL) {
            if (strcmp(token, "equalization") == 0) {
                // Apply equalization effect
                result.cpu_usage += applyEqualizationEffect(&audio_stream);
            } else if (strcmp(token, "noise_reduction") == 0) {
                // Apply noise reduction effect
                result.cpu_usage += applyNoiseReductionEffect(&audio_stream);
            } else if (strcmp(token, "compression") == 0) {
                // Apply compression effect
                result.cpu_usage += applyCompressionEffect(&audio_stream);
            }
            token = strtok(NULL, ",");
        }
        free(effects_str);
    }

    // Write the log information and close the log file
    if (logging_info.logfile != NULL) {
        fprintf(logging_info.log_stream, "CPU usage: %f\nMemory usage: %f\n", result.cpu_usage, result.memory_usage);
        fclose(logging_info.log_stream);
    }

    return result;
}

