// Macro for checking if an error has occurred
#define check_error(expr) \
    if ((expr) == NULL) { \
        printf("Error: %s\n", strerror(errno)); \
        return 1; \
    }

typedef struct record {
    int key;
    double value;
    time_t timestamp;
} record;

void* initialize(void* arg) {
    // Allocate memory for the arrays
    long *offset_arr = malloc(sizeof(long) * arg->num_records);
    check_error(offset_arr);

    int *key_arr = malloc(sizeof(int) * arg->num_records);
    check_error(key_arr);

    double *value_arr = malloc(sizeof(double) * arg->num_records);
    check_error(value_arr);

    // Initialize the arrays with random values
    for (int i = 0; i < arg->num_records; ++i) {
        offset_arr[i] = rand() % 100;
        key_arr[i] = rand() % 100;
        value_arr[i] = (double)rand() / RAND_MAX * 10.0;
    }

    // Initialize the record structure array
    record *records = malloc(sizeof(record) * arg->num_records);
    check_error(records);

    for (int i = 0; i < arg->num_records; ++i) {
        records[i].key = key_arr[i];
        records[i].value = value_arr[i];
        records[i].timestamp = time(NULL);
    }

    return (void*)records;
}

int main() {
    // Define the number of records to be initialized
    const int num_records = 10;

    // Define the number of threads for concurrent execution
    const int num_threads = 4;

    // Create an array of thread arguments
    struct thread_arg {
        int id;
        int num_records;
    } args[num_threads];

    // Initialize the thread arguments
    for (int i = 0; i < num_threads; ++i) {
        args[i].id = i;
        args[i].num_records = num_records / num_threads;
    }

    pthread_t threads[num_threads];

    // Create the threads
    for (int i = 0; i < num_threads; ++i) {
        int rc = pthread_create(&threads[i], NULL, initialize, &args[i]);
        if (rc != 0) {
            printf("Error: %s\n", strerror(errno));
            return 1;
        }
    }

    // Wait for the threads to complete
    for (int i = 0; i < num_threads; ++i) {
        void* records;
        pthread_join(threads[i], &records);
    }

    return 0;
}
