// Function to initialize the arrays for offset values, keys, and records
void initArrays(int numRecords) {
    // Dynamically allocate memory for the offset array
    long* offsets = (long*)malloc(numRecords * sizeof(long));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offset array\n");
        return;
    }

    // Initialize the offset values with random integers within a specified range
    srand((unsigned int)time(NULL));
    for (int i = 0; i < numRecords; i++) {
        offsets[i] = rand() % 1000 + 1;
    }

    // Dynamically allocate memory for the key array
    int* keys = (int*)malloc(numRecords * sizeof(int));
    if (!keys) {
        printf("Error: Failed to allocate memory for key array\n");
        free(offsets);
        return;
    }

    // Initialize the key values with random integers within a specified range
    srand((unsigned int)time(NULL));
    for (int i = 0; i < numRecords; i++) {
        keys[i] = rand() % 100 + 1;
    }

    // Dynamically allocate memory for the record array
    Record* records = (Record*)malloc(numRecords * sizeof(Record));
    if (!records) {
        printf("Error: Failed to allocate memory for record array\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize the record values with random double values and string pointers
    srand((unsigned int)time(NULL));
    for (int i = 0; i < numRecords; i++) {
        records[i].value = rand() % 100 + 0.1;
        records[i].flag = (rand() % 2 == 0);
        records[i].string = malloc(sizeof(char) * 10);
        sprintf(records[i].string, "Record %d", i + 1);
    }

    // Print the initialized arrays
    printf("Offset array: ");
    for (int i = 0; i < numRecords; i++) {
        printf("%ld ", offsets[i]);
    }
    printf("\n");
    printf("Key array: ");
    for (int i = 0; i < numRecords; i++) {
        printf("%d ", keys[i]);
    }
    printf("\n");
    printf("Record array: ");
    for (int i = 0; i < numRecords; i++) {
        printf("{value: %f, flag: %s, string: \"%s\"} ", records[i].value, records[i].flag ? "true" : "false", records[i].string);
    }
    printf("\n");

    // Free the memory allocated for the arrays
    free(offsets);
    free(keys);
    for (int i = 0; i < numRecords; i++) {
        free(records[i].string);
    }
    free(records);
}

// Function to generate random values within a specified range
double generateRandomValue(double min, double max) {
    // Generate a random number between 0 and 1
    double randNum = (double)rand() / RAND_MAX;

    // Scale the random number to the specified range
    return randNum * (max - min) + min;
}

// Function to handle memory allocation failures gracefully
void handleMemoryAllocationError(const char* errorMessage, bool exitOnFailure) {
    printf("Error: %s\n", errorMessage);
    if (exitOnFailure) {
        exit(1);
    }
}

// Function to generate a random string within a specified range
char* generateRandomString(int minLength, int maxLength) {
    // Generate a random length for the string
    int length = rand() % (maxLength - minLength + 1) + minLength;

    // Allocate memory for the string
    char* str = (char*)malloc(length * sizeof(char));
    if (!str) {
        handleMemoryAllocationError("Failed to allocate memory for random string", false);
        return NULL;
    }

    // Fill the string with random characters
    for (int i = 0; i < length; i++) {
        str[i] = 'a' + rand() % ('z' - 'a');
    }

    return str;
}

// Function to incorporate multi-threading for value generation
void generateValuesInThreads(int numThreads) {
