    for (int i = 0; i < numRecords; i++) {
        records[i].value = generateRandomValue(0, 1);
        records[i].flag = (rand() % 2 == 0);
        records[i].string = generateRandomString(5, 10);
    }
}

// Function to validate input sizes and manage memory allocation failures
void validateInputSizes(int numRecords) {
    // Validate the number of records is a positive integer
    if (numRecords <= 0) {
        printf("Error: Invalid number of records specified\n");
        return;
    }

    // Dynamically allocate memory for the offset, key, and record arrays
    offsets = (long*)malloc(numRecords * sizeof(long));
    keys = (int*)malloc(numRecords * sizeof(int));
    records = (Record*)malloc(numRecords * sizeof(Record));
    if (!offsets || !keys || !records) {
        handleMemoryAllocationError("Failed to allocate memory for arrays", true);
    }
}

// Function to manage memory allocation failures during runtime
void handleMemoryLeak() {
    // Check if there are any memory leaks using valgrind or other tools
