    // Allocate memory for the array of records
    record* records = malloc(sizeof(record) * num_records);
    if (!records) {
        perror("malloc");
        return NULL;
    }

    // Read the records from the network stream
    int bytes_read = read(fd, records, sizeof(record) * num_records);
    if (bytes_read < 0) {
        perror("read");
        free(records);
        return NULL;
    } else if (bytes_read == 0) {
        // End of file reached
        printf("End of file reached\n");
        free(records);
        return NULL;
