// Custom data structure representing network configuration settings for a mobile network base station
typedef struct {
    int frequency_band;
    int channel_number;
    int power_level;
    char* modulation_type;
} network_config;

// Initializes and populates an array of custom data structures representing network configuration settings for a mobile network base station
// Returns initialized array and the semaphore's initial value upon successful completion, NULL otherwise
network_config** initialize_network_configuration(int num_configs, int initial_value) {
    // Check if number of configurations is valid
    if (num_configs < 1) {
        printf("Error: Number of configurations must be positive.\n");
        return NULL;
    }

    // Create array to store network configuration settings
    network_config** configs = malloc(sizeof(network_config*) * num_configs);
    if (configs == NULL) {
        printf("Error: Memory allocation failed. Aborting...\n");
        return NULL;
    }

    // Initialize each configuration with default values
    for (int i = 0; i < num_configs; i++) {
        configs[i] = malloc(sizeof(network_config));
        if (configs[i] == NULL) {
            printf("Error: Memory allocation failed. Aborting...\n");
            return NULL;
        }
        configs[i]->frequency_band = 0;
        configs[i]->channel_number = 0;
        configs[i]->power_level = 0;
        configs[i]->modulation_type = malloc(sizeof(char) * 16);
        if (configs[i]->modulation_type == NULL) {
            printf("Error: Memory allocation failed. Aborting...\n");
            return NULL;
        }
    }

    // Initialize semaphore with initial value
    sem_t* semaphore = malloc(sizeof(sem_t));
    if (semaphore == NULL) {
        printf("Error: Memory allocation failed. Aborting...\n");
        return NULL;
    }
    int semaphore_init_error = sem_init(semaphore, initial_value);
    if (semaphore_init_error != 0) {
        printf("Error: Semaphore initialization failed. Aborting...\n");
        return NULL;
    }

    // Return initialized array and semaphore's initial value
    return configs;
}

// Updates a network configuration setting in the array based on given parameters
// Returns true if successful, false otherwise
bool update_network_configuration(network_config** configs, int frequency_band, int channel_number, int power_level, char* modulation_type) {
    // Check if frequency band and channel number are valid
    if (frequency_band < 0 || frequency_band > 99 || channel_number < 1 || channel_number > 256) {
        printf("Error: Frequency band and channel number must be within range [0, 99] and [1, 256].\n");
        return false;
    }

    // Check if power level is valid
    if (power_level < -10 || power_level > 45) {
        printf("Error: Power level must be within range [-10, 45].\n");
        return false;
    }

    // Check if modulation type is valid
    bool valid_modulation = false;
    for (int i = 0; i < strlen(modulation_type); i++) {
        char c = modulation_type[i];
        if (c == 'A' || c == 'N') {
            valid_modulation = true;
            break;
        }
    }
    if (!valid_modulation) {
        printf("Error: Invalid modulation type. Must be either A or N.\n");
        return false;
    }

    // Update configuration with given parameters
    configs[frequency_band]->channel_number = channel_number;
    configs[frequency_band]->power_level = power_level;
    strcpy(configs[frequency_band]->modulation_type, modulation_type);

    // Return true if successful
    return true;
}

// Deletes an array of network configuration settings
void delete_network_configuration(network_config** configs) {
    for (int i = 0; i < num_configs; i++) {
        free(configs[i]);
    }
    free(configs);
}
