        if (records[i].type == type) {
            void* data = records[i].data;
            if (type == TYPE_INT) {
                if (*((int*)data) > *((int*)largest)) {
                    free(largest);
                    largest = malloc(sizeof(int));
                    memcpy(largest, data, sizeof(int));
                }
            } else if (type == TYPE_STR) {
                if (strlen(data) > strlen((char*)largest)) {
                    free(largest);
                    largest = malloc(5);
                    memcpy(largest, data, 5);
                }
            }
        }
    }

    // Print the largest value
    if (type == TYPE_INT) {
        printf("The largest integer is %d\n", *((int*)largest));
    } else if (type == TYPE_STR) {
        printf("The longest string is %s\n", (char*)largest);
    }

    // Free the memory for the largest value
    free(largest);
}

