// Define the struct for an item in the hash table
struct item {
    int integer_field;
    float floating_point_field;
    char character_field;
};

// Define a hash table with dynamic resizing and chaining for collisions
typedef struct {
    size_t capacity; // number of elements in the table
    size_t count; // number of elements currently stored in the table
    size_t threshold; // load factor at which to resize the table
    double grow_factor; // factor by which to grow the table when full
    double shrink_factor; // factor by which to shrink the table when near capacity
    struct item** items; // array of pointers to items in the table
} hash_table_t;

// Initialize a new hash table with an initial capacity and load factor
hash_table_t* init_hash_table(size_t capacity, double threshold) {
    assert(capacity > 0);
    assert(threshold > 0 && threshold <= 1.0);

    // Allocate memory for the hash table struct and its items array
    hash_table_t* table = malloc(sizeof(hash_table_t));
    if (!table) {
        return NULL;
    }
    table->capacity = capacity;
    table->count = 0;
    table->threshold = threshold;
    table->grow_factor = 2.0;
    table->shrink_factor = 0.5;
    table->items = calloc(capacity, sizeof(struct item*));
    if (!table->items) {
        free(table);
        return NULL;
    }

    // Return the initialized hash table
    return table;
}

// Add a new item to the hash table by its key
int add_item(hash_table_t* table, int key, struct item* item) {
    assert(table != NULL);
    assert(key > 0);
    assert(item != NULL);

    // Find an empty slot in the items array for this key
    size_t index = key % table->capacity;
    while (table->items[index] != NULL && table->items[index]->integer_field != key) {
        index = (index + 1) % table->capacity;
    }

    // If no empty slot is found, resize the table if near capacity and try again
    if (table->count >= table->threshold * table->capacity) {
        resize_hash_table(table, table->grow_factor);
        index = key % table->capacity;
        while (table->items[index] != NULL && table->items[index]->integer_field != key) {
            index = (index + 1) % table->capacity;
        }
    }

    // Add the item to the hash table and return success
    if (table->items[index] == NULL) {
        table->count++;
        table->items[index] = item;
        return 0;
    } else {
        return -1;
    }
}

// Remove an item from the hash table by its key
int remove_item(hash_table_t* table, int key) {
    assert(table != NULL);
    assert(key > 0);

    // Find the slot for this key in the items array and check if it exists
    size_t index = key % table->capacity;
    while (table->items[index] != NULL && table->items[index]->integer_field != key) {
        index = (index + 1) % table->capacity;
    }
    if (table->items[index] == NULL) {
        return -1;
    }

    // Remove the item from the hash table and return success
    free(table->items[index]);
    table->count--;
    table->items[index] = NULL;
    return 0;
}

// Retrieve an item from the hash table by its key, handling cases where the key may not exist
struct item* get_item(hash_table_t* table, int key) {
    assert(table != NULL);
    assert(key > 0);

    // Find the slot for this key in the items array and check if it exists
    size_t index = key % table->capacity;
    while (table->items[index] != NULL && table->items[index]->integer_field != key) {
        index = (index + 1) % table->capacity;
    }
    if (table->items[index] == NULL) {
        return NULL;
    } else {
        return table->items[index];
    }
}

// Resize the hash table to a new capacity and load factor
int resize_hash_table(hash_table_t* table, double factor) {
    assert(table != NULL);
    assert(factor > 0 && factor <= 1.0);

    // Calculate the new capacity based on the current one and the given factor
    size_t new_capacity = (size_t)(table->capacity * factor);
    if (new_capacity == 0) {
        return -1;
    }

    // Allocate memory for the new items array and copy the existing items to it
    struct item** new_items = calloc(new_capacity, sizeof(struct item*));
    if (!new_items) {
        return -1;
    }
    size_t count = 0;
    for (size_t i = 0; i < table->capacity; i++) {
        struct item* item = table->items[i];
        if (item != NULL) {
            int index = item->integer_field % new_capacity;
            while (new_items[index] != NULL && new_items[index]->integer_field != key) {
                index = (index + 1) % new_capacity;
            }
            if (new_items[index] == NULL) {
                count++;
                new_items[index] = item;
            } else {
                free(item);
            }
        }
    }

    // Free the existing items array and update the hash table struct with the new one
    free(table->items);
    table->capacity = new_capacity;
    table->count = count;
    table->threshold = factor * new_capacity;
    table->items = new_items;

    // Return success
    return 0;
}

// Free the memory allocated for a hash table and its items array
void free_hash_table(hash_table_t* table) {
    assert(table != NULL);

    // Free the items array and reset the hash table struct
    free(table->items);
    table->capacity = 0;
    table->count = 0;
    table->threshold = 0.0;
    table->grow_factor = 1.0;
    table->shrink_factor = 1.0;
    free(table);
}
```
This code implements a hash table with dynamic resizing and chaining for collisions, using `struct item` to store the items in the table. The `add_item` function adds an item by its key to the hash table, allocating memory for the new item if necessary. The `remove_item` function removes an item from the hash table by its key. The `get_item` function retrieves an item from the hash table by its key, handling cases where the key may not exist. The `resize_hash_table` function resizes the hash table to a new capacity and load factor, allocating memory for the new items array and copying the existing items to it. Finally, the `free_hash_table` function frees the memory allocated for the hash table and its items array.

