    Record* records = (Record*)malloc(numRecords * sizeof(Record));
    if (records == NULL) {
        printf("Error: failed to allocate memory for records\n");
        return NULL;
    }

    // Initialize the array of records with default values
    for (int i = 0; i < numRecords; i++) {
        records[i].value = 0;
    }

    return records;
}

// Function to identify and print the largest integer in an array of 'record' structures
void printLargestInt(Record* records, int numRecords) {
    if (records == NULL || numRecords <= 0) {
        printf("Error: invalid input\n");
        return;
    }

    // Initialize the largest integer to the first element in the array
    int largest = records[0].value;
    for (int i = 1; i < numRecords; i++) {
        if (records[i].value > largest) {
            largest = records[i].value;
        }
    }

