#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>
#include <stdbool.h>
#include <limits.h>

// Define the record structure
typedef struct {
    int type; // 0 for integer, 1 for string
    union {
        int i;
        char *s;
    } value;
} Record;

// Define the filter criteria structure
typedef struct {
    int min_int;
    size_t max_string_len;
    bool (*filter)(Record *);
} FilterCriteria;

// Function to initialize the record array and validate input sizes
void init_records(size_t n, Record **records) {
    // Validate input sizes
    if (n > SIZE_MAX / sizeof(Record)) {
        fprintf(stderr, "Error: too many records\n");
        exit(EXIT_FAILURE);
    }
    size_t size = n * sizeof(Record);
    *records = malloc(size);
    if (*records == NULL) {
        fprintf(stderr, "Error: failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }
}

// Function to generate random integers within a specified range
int gen_random_int(int min, int max) {
    assert(min <= max);
    return (rand() % (max - min + 1)) + min;
}

// Function to generate random strings of a specified length
char *gen_random_string(size_t len) {
    char *str = malloc(len);
    if (str == NULL) {
        fprintf(stderr, "Error: failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < len - 1; ++i) {
        str[i] = 'a' + rand() % ('z' - 'a');
    }
    str[len - 1] = '\0';
    return str;
}

// Function to filter records based on specific criteria
bool filter_records(Record *record, FilterCriteria *criteria) {
    // Check if the record is an integer and meets the minimum threshold
    if (record->type == 0 && record->value.i >= criteria->min_int) {
        return true;
    }
    // Check if the record is a string and meets the maximum length threshold
    else if (record->type == 1 && strlen(record->value.s) <= criteria->max_string_len) {
        return true;
    }
    // Otherwise, filter out the record
    return false;
}

// Function to find and print the largest integer in an array of records
void print_largest_int(Record *records, size_t n) {
    int max = INT_MIN;
    for (size_t i = 0; i < n; ++i) {
        if (records[i].type == 0 && records[i].value.i > max) {
            max = records[i].value.i;
        }
    }
    printf("The largest integer is %d\n", max);
}

// Function to find and print the longest string in an array of records
void print_longest_string(Record *records, size_t n) {
    char *max = NULL;
    for (size_t i = 0; i < n; ++i) {
        if (records[i].type == 1 && strlen(records[i].value.s) > strlen(max)) {
            max = records[i].value.s;
        }
    }
    printf("The longest string is %s\n", max);
}

// Function to execute an external command using system-level API calls
void exec_command(const char *command) {
    // Use the `system` function to execute the command and capture its output
    FILE *fp = popen(command, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: failed to open file\n");
        exit(EXIT_FAILURE);
    }
    char buffer[BUFSIZ];
    while (fgets(buffer, BUFSIZ, fp)) {
        // Print the output line by line
        printf("%s", buffer);
    }
    // Close the file and check for errors
    if (ferror(fp)) {
        fprintf(stderr, "Error: failed to read from file\n");
        exit(EXIT_FAILURE);
    }
    if (pclose(fp) == -1) {
        fprintf(stderr, "Error: failed to close file\n");
        exit(EXIT_FAILURE);
    }
}

// Function to delete a specified file before executing an external command
void exec_command_with_file_deletion(const char *file, const char *command) {
    // Use the `remove` function to delete the file if it exists
    int result = remove(file);
    if (result == -1) {
        fprintf(stderr, "Error: failed to delete file\n");
        exit(EXIT_FAILURE);
    }
    // Execute the command using system-level API calls
    exec_command(command);
}
