#include <time.h>

typedef struct file_info {
    char* path;
    int64_t size;
    time_t modified;
} file_info;

file_info* process_files(char** args, int argc) {
    // Initialize the array of file information structures
    file_info* files = malloc(sizeof(file_info) * argc);

    if (!files) {
        fprintf(stderr, "Error: unable to allocate memory for file information\n");
        return NULL;
    }

    // Iterate over each command-line argument and process the corresponding file path
    for (int i = 0; i < argc; i++) {
        char* path = args[i];
        struct stat sb;

        if (stat(path, &sb) == -1) {
            fprintf(stderr, "Error: unable to access file %s\n", path);
            continue;
        }

        files[i].size = sb.st_size;
        files[i].modified = sb.st_mtime;
        files[i].path = strdup(path);
    }

    return files;
}

void print_largest_file(file_info* files, int count) {
    // Find the largest file and its size
    int64_t max_size = -1;
    int idx = -1;
    for (int i = 0; i < count; i++) {
        if (files[i].size > max_size) {
            max_size = files[i].size;
            idx = i;
        }
    }

    // Print the file information
    if (idx != -1) {
        printf("Largest file: %s\nSize: %lld bytes\n", files[idx].path, max_size);
    } else {
        printf("No files found\n");
    }
}

void print_most_recently_modified(file_info* files, int count) {
    // Find the most recently modified file and its modification time
    time_t max_time = -1;
    int idx = -1;
    for (int i = 0; i < count; i++) {
        if (files[i].modified > max_time) {
            max_time = files[i].modified;
            idx = i;
        }
    }

    // Print the file information
    if (idx != -1) {
        printf("Most recently modified: %s\nModification time: %lld\n", files[idx].path, max_time);
    } else {
        printf("No files found\n");
    }
}
