    size_t free_chunk_threshold = 0;

    // Loop through each record in the input stream
    for (size_t i = 0; i < pipeline->record_count; i++) {
        // Check if the current record is an integer value or a string value
        if (pipeline->records[i].type == INTEGER) {
            // Calculate the memory usage of the integer value
            total_memory_usage += sizeof(int);
        } else if (pipeline->records[i].type == STRING) {
            // Calculate the memory usage of the string value
            total_memory_usage += strlen(pipeline->records[i].value.str_val.value);
        }
    }

    // Update the free chunk threshold based on the input stream parameters and the memory management parameters
    free_chunk_threshold = (size_t)round(((double)total_memory_usage / 100) * pipeline->input_stream_params.max_memory_usage);
    if (free_chunk_threshold < mem_params.allocation_unit_size) {
        free_chunk_threshold = mem_params.allocation_unit_size;
    } else if (free_chunk_threshold > pipeline->memory_management_params.max_memory_usage - mem_params.allocation_unit_size) {
        free_chunk_threshold = pipeline->memory_management_params.max_memory_usage - mem_params.allocation_unit_size;
    }

    // Print the total memory usage and the free chunk threshold
    printf("Total memory usage: %lu bytes\n", total_memory_usage);
    printf("Free chunk threshold: %lu bytes\n", free_chunk_threshold);
}

