} record_t;

long* initializeDataStructures(int size, int seed) {
    // Validate input parameters
    if (size <= 0 || size > 1000) {
        fprintf(stderr, "Invalid size parameter: %d\n", size);
        return NULL;
    }

    // Allocate memory for the arrays
    long* offsets = malloc(sizeof(long) * size);
    int* keys = malloc(sizeof(int) * size);
    record_t* records = malloc(sizeof(record_t) * size);

    if (offsets == NULL || keys == NULL || records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Initialize the arrays with random values using the provided seed
    srand(seed);
    for (int i = 0; i < size; i++) {
        offsets[i] = rand() % 1000 - 500;
        keys[i] = rand() % 1000 - 500;
        records[i].value = rand() % 1000 - 500;
    }

    // Initialize the pointers within each record to point back to its corresponding key and offset
    for (int i = 0; i < size; i++) {
        records[i].key = &keys[i];
        records[i].offset = &offsets[i];
    }

    return records;
}
