#include "json_config.h"

// Define the configuration manager struct
struct json_config {
    char *filename; // The JSON file path
    FILE *file; // The JSON file stream
    size_t filesize; // The JSON file size
    struct config_item *items; // A list of configuration items
};

// Define the configuration item struct
struct config_item {
    char *key; // The configuration key
    char *value; // The configuration value
};

// Function to read and parse a JSON file
static int json_config_read(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening JSON file");
        return 1;
    }

    // Calculate the file size and allocate memory for it
    long filesize;
    fseek(file, 0, SEEK_END);
    filesize = ftell(file);
    rewind(file);

    char *buffer = (char *) malloc(filesize + 1);
    if (buffer == NULL) {
        perror("Error allocating memory for JSON file");
        fclose(file);
        return 1;
    }

    // Read the entire JSON file into the buffer
    size_t read = fread(buffer, 1, filesize, file);
    if (read != filesize) {
        perror("Error reading JSON file");
        free(buffer);
        fclose(file);
        return 1;
    }

    // Parse the JSON data and store it in a structured manner
    char *json = buffer;
    json_object *obj = json_tokener_parse(json);
    if (obj == NULL) {
        perror("Error parsing JSON file");
        free(buffer);
        fclose(file);
        return 1;
    }

    // Iterate over the JSON object and extract key-value pairs
    struct config_item *items = (struct config_item *) malloc(obj->length * sizeof(struct config_item));
    if (items == NULL) {
        perror("Error allocating memory for configuration items");
        json_object_put(obj);
        fclose(file);
        return 1;
    }

    int i = 0;
    json_object_object_foreach(obj, key, val) {
        // Check if the value is a string, integer, or boolean
        const char *value = NULL;
        int intval = 0;
        bool boolval = false;
        if (json_object_is_type(val, json_type_string)) {
            value = (const char *) json_object_get_string(val);
        } else if (json_object_is_type(val, json_type_int)) {
            intval = json_object_get_int(val);
        } else if (json_object_is_type(val, json_type_boolean)) {
            boolval = json_object_get_boolean(val);
        } else {
            printf("Unsupported value type for key '%s'\n", key);
        }

        // Add the configuration item to the list
        if (value != NULL) {
            items[i].key = strdup(key);
            items[i].value = strdup(value);
            i++;
        } else if (intval > 0) {
            char *strval = malloc(16); // 16 bytes should be enough for a 32-bit integer
            snprintf(strval, 16, "%d", intval);
            items[i].key = strdup(key);
            items[i].value = strval;
            i++;
        } else if (boolval) {
            char *strval = malloc(5); // 5 bytes should be enough for a boolean value
            snprintf(strval, 5, "%d", boolval);
            items[i].key = strdup(key);
            items[i].value = strval;
            i++;
        } else {
            printf("Unsupported value type for key '%s'\n", key);
        }
    }

    // Close the JSON file and free memory
    json_object_put(obj);
    fclose(file);
    free(buffer);

    return 0;
}

// Function to read a configuration value by key
char *json_config_get(const char *key) {
    // Check if the configuration manager has been initialized
    if (json_config == NULL) {
        printf("The JSON configuration manager has not been initialized\n");
        return NULL;
    }

    // Search for the configuration item with the specified key
    struct config_item *item = json_config->items;
    while (item != NULL && strcmp(item->key, key) != 0) {
        item = item->next;
    }

    // Return the configuration value if found, or NULL otherwise
    return (item == NULL) ? NULL : item->value;
}

// Function to set a configuration value by key
void json_config_set(const char *key, const char *value) {
    // Check if the configuration manager has been initialized
    if (json_config == NULL) {
        printf("The JSON configuration manager has not been initialized\n");
        return;
    }

    // Search for the configuration item with the specified key
    struct config_item *item = json_config->items;
    while (item != NULL && strcmp(item->key, key) != 0) {
        item = item->next;
    }

    // Update the value of the existing configuration item or add a new one if not found
    if (item != NULL) {
        free(item->value);
        item->value = strdup(value);
    } else {
        struct config_item *new_item = (struct config_item *) malloc(sizeof(struct config_item));
        new_item->key = strdup(key);
        new_item->value = strdup(value);
        new_item->next = json_config->items;
        json_config->items = new_item;
    }
}

// Function to delete a configuration value by key
void json_config_delete(const char *key) {
    // Check if the configuration manager has been initialized
    if (json_config == NULL) {
        printf("The JSON configuration manager has not been initialized\n");
        return;
    }

    // Search for the configuration item with the specified key
    struct config_item **prev = &(json_config->items);
    struct config_item *item = json_config->items;
    while (item != NULL && strcmp(item->key, key) != 0) {
        prev = &(item->next);
        item = item->next;
    }

    // Delete the configuration item if found
    if (item != NULL) {
        free(item->key);
        free(item->value);
        *prev = item->next;
        free(item);
    } else {
        printf("The key '%s' is not present in the JSON configuration\n", key);
    }
}

// Function to initialize the JSON configuration manager
int json_config_init(const char *filename) {
    // Check if the configuration manager has already been initialized
    if (json_config != NULL) {
        printf("The JSON configuration manager has already been initialized\n");
        return 1;
    }

    // Open and read the JSON file
    int ret = json_config_read(filename);
    if (ret != 0) {
        return ret;
    }

    // Create a new configuration manager struct
    json_config = (struct json_config *) malloc(sizeof(struct json_config));
    if (json_config == NULL) {
        perror("Error allocating memory for JSON configuration manager");
        fclose(file);
        free(buffer);
        return 1;
    }

    // Initialize the configuration manager struct
    json_config->filename = strdup(filename);
    json_config->file = file;
    json_config->filesize = filesize;
    json_config->items = items;

    return 0;
}

// Function to clean up the JSON configuration manager
void json_config_cleanup() {
    // Check if the configuration manager has been initialized
    if (json_config == NULL) {
        printf("The JSON configuration manager has not been initialized\n");
        return;
    }

    // Release memory for the configuration items and the configuration manager struct
    struct config_item *item = json_config->items;
    while (item != NULL) {
        free(item->key);
        free(item->value);
        item = item->next;
    }
    free(json_config->items);
    free(json_config->filename);
    fclose(json_config->file);
    free(json_config);
    json_config = NULL;
}
