import java.util.Arrays;
import java.util.List;

public class RecordManager {
    private static final int INITIAL_CAPACITY = 16;
    private static final int MAX_CAPACITY = 1024;
    private static final String INIT_RANDOM_INTS = "randomInts";
    private static final String INIT_RANDOM_STRS = "randomStrs";
    private static final int MIN_INT_VALUE = 0;
    private static final int MAX_INT_VALUE = 100;
    private static final int STR_LENGTH = 16;

    // Array of Records
    private List<Record> records;

    public RecordManager(int numRecords) {
        this.records = new ArrayList<>();

        // Initialize array with given number of records
        for (int i = 0; i < numRecords; i++) {
            records.add(new Record());
        }
    }

    public void initialize(String initType, int lowerBound, int upperBound) {
        if (initType == INIT_RANDOM_INTS) {
            // Initialize with random integers within range
            for (Record record : records) {
                record.setValue(new Random().nextInt(upperBound - lowerBound + 1) + lowerBound);
            }
        } else if (initType == INIT_RANDOM_STRS) {
            // Initialize with random strings of specified length
            for (Record record : records) {
                record.setValue(new String(new char[STR_LENGTH]).replace("\0", "a"));
            }
        } else {
            throw new IllegalArgumentException("Invalid initialization type");
        }
    }

    public List<Record> filter(String attribute, int value) {
        return records.stream()
                .filter(record -> record.getValue().equals(value))
                .collect(Collectors.toList());
    }

    public void executeCommand(String command) {
        try {
            // Execute system command and handle output/error streams
            Process process = Runtime.getRuntime().exec(command);
            BufferedReader stdInput = new BufferedReader(new InputStreamReader(process.getInputStream()));
            BufferedReader stdError = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            String line;
            while ((line = stdInput.readLine()) != null) {
                System.out.println(line);
            }
            while ((line = stdError.readLine()) != null) {
                System.err.println(line);
            }
        } catch (IOException e) {
            // Handle error
        }
    }

    public void optimizeMemory() {
        // Periodic memory optimization routine to free up unused resources
        Runtime runtime = Runtime.getRuntime();
        long totalMemory = runtime.totalMemory();
        long maxMemory = runtime.maxMemory();
        if (totalMemory > maxMemory * 0.8) {
            records.clear();
            System.gc();
        }
    }

    public void printMaxValue() {
        // Helper method to identify and print the maximum integer value or longest string among records
        int maxInt = Integer.MIN_VALUE;
        String maxStr = "";
        for (Record record : records) {
            if (record.getValue() instanceof Integer && ((Integer) record.getValue()) > maxInt) {
                maxInt = (Integer) record.getValue();
            } else if (record.getValue() instanceof String && ((String) record.getValue()).length() > maxStr.length()) {
                maxStr = (String) record.getValue();
            }
        }
        System.out.println("Maximum integer value: " + maxInt);
        System.out.println("Longest string: " + maxStr);
    }
}
