            session->authenticated = false;
            free(session);
            sessions[i] = NULL;
        } else if (!is_session_within_limits(session)) {
            // Handle invalid session by removing its associated data structure
            free(session);
            sessions[i] = NULL;
        }
    }

    // Remove any null entries from the list of sessions
    int new_num_sessions = 0;
    for (int i = 0; i < num_sessions; i++) {
        if (sessions[i] != NULL) {
            sessions[new_num_sessions++] = sessions[i];
        }
    }

    // Refresh session metadata periodically to reduce the risk of stale data
    for (int i = 0; i < new_num_sessions; i++) {
        Session* session = sessions[i];
        if (session->authenticated) {
            refresh_session_metadata(session);
        }
    }
}

// Function to check if a session is within valid operational limits
bool is_session_within_limits(Session* session) {
    // Check if the session has been idle for too long and is within the timeout duration
    time_t current_time = time(NULL);
    int elapsed_time = current_time - session->last_access;
    return elapsed_time < session->timeout_duration;
}

// Function to check if a session has expired due to inactivity or exceeding the timeout duration
bool is_session_expired(Session* session) {
    // Check if the session has been idle for too long and has not been refreshed within the timeout duration
    time_t current_time = time(NULL);
    int elapsed_time = current_time - session->last_access;
    return elapsed_time >= session->timeout_duration || !session->authenticated;
}

// Function to refresh session metadata periodically
void refresh_session_metadata(Session* session) {
    // Update the last access time and timeout duration for the session
    time_t current_time = time(NULL);
    session->last_access = current_time;

    // Retrieve the updated authentication status from the database
    bool new_authenticated = retrieve_authentication_status(session->session_id);

    // Update the authenticated flag for the session if necessary
    if (new_authenticated != session->authenticated) {
        session->authenticated = new_authenticated;
    }
}

// Function to retrieve authentication status from the database
bool retrieve_authentication_status(int session_id) {
    // TODO: Implement a mechanism for retrieving the authentication status of a given session ID from the database.
    return true; // For demonstration purposes, assume the authentication status is always valid.
}
