    // Dynamically allocate memory for the array of data points
    data_point *arr = (data_point*)malloc(num_points * sizeof(data_point));
    if (!arr) {
        printf("Error: Failed to allocate memory for data point array\n");
        return;
    }

    // Initialize each data point with a random value within the specified range or a random vector of double precision numbers
    for (int i = 0; i < num_points; ++i) {
        if (num_dims == 1) {
            arr[i].value = (float)(rand() % 1000) / 100.0f; // Initialize a single float value within the specified range
        } else {
            double* vector = (double*)malloc(num_dims * sizeof(double));
            if (!vector) {
                printf("Error: Failed to allocate memory for data point %d's vector\n", i);
                return;
            }
            for (int j = 0; j < num_dims; ++j) {
                vector[j] = (double)(rand() % 1000) / 100.0f; // Initialize each element of the vector with a random value within the specified range
            }
            arr[i].vector = vector;
        }
    }
}

// Define the function to compute and print the sum of all elements in the array of data points if they are floats, or the sum of magnitudes of vectors if they are vectors
void sum_data(int num_points, int num_dims) {
    double sum = 0.0;
    for (int i = 0; i < num_points; ++i) {
        if (num_dims == 1) {
            sum += arr[i].value; // Add the single float value to the total sum
        } else {
            double* vector = arr[i].vector;
            for (int j = 0; j < num_dims; ++j) {
                sum += vector[j] * vector[j]; // Multiply each element of the vector by itself and add the result to the total sum
            }
        }
    }
    printf("Sum: %f\n", sum);
}
