#include <pthread.h>

typedef struct data_point {
    union {
        float value;
        double vector[10];
    };
} data_point;

void process_data(int num_points, char type, int range, int length, int seed) {
    // Initialize an array of 'data_point' structures to store the input data
    data_point *data = (data_point *)malloc(num_points * sizeof(data_point));
    if (data == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for data points\n");
        return;
    }

    // Initialize the array with random values within the specified range or vector length
    for (int i = 0; i < num_points; i++) {
        if (type == 'f') {
            data[i].value = (float)(rand() % range);
        } else {
            for (int j = 0; j < length; j++) {
                data[i].vector[j] = (double)(rand() % range) - 0.5;
            }
        }
    }

    // Compute the sum of all elements in the array or magnitudes of vectors
    if (type == 'f') {
        double sum = 0.0;
        for (int i = 0; i < num_points; i++) {
            sum += data[i].value;
        }
        printf("Sum: %lf\n", sum);
    } else {
        double sum = 0.0;
        for (int i = 0; i < num_points; i++) {
            for (int j = 0; j < length; j++) {
                sum += fabs(data[i].vector[j]);
            }
        }
        printf("Sum: %lf\n", sum);
    }

    // Free the memory allocated for the data points
    free(data);
}

void random_float(int range, int seed) {
    srand(seed);
    float value = (float)(rand() % range);
    printf("Random float: %f\n", value);
}

void random_vector(int length, int range, int seed) {
    srand(seed);
    double vector[length];
    for (int i = 0; i < length; i++) {
        vector[i] = (double)(rand() % range) - 0.5;
    }
    printf("Random vector: ");
    for (int i = 0; i < length; i++) {
        printf("%lf ", vector[i]);
    }
    printf("\n");
}

void compute_sum(data_point *data, int num_points) {
    if (type == 'f') {
        double sum = 0.0;
        for (int i = 0; i < num_points; i++) {
            sum += data[i].value;
        }
        printf("Sum: %lf\n", sum);
    } else {
        double sum = 0.0;
        for (int i = 0; i < num_points; i++) {
            for (int j = 0; j < length; j++) {
                sum += fabs(data[i].vector[j]);
            }
        }
        printf("Sum: %lf\n", sum);
    }
}

void test_module(char *module, char *test) {
    // Load the module using a dynamic loader
    void *handle = dlopen(module, RTLD_LAZY);
    if (handle == NULL) {
        fprintf(stderr, "Error: Failed to load module %s\n", module);
        return;
    }

    // Execute the test function using the loaded module
    void (*test_function)(int, char, int, int, int) = dlsym(handle, test);
    if (test_function == NULL) {
        fprintf(stderr, "Error: Failed to find symbol %s in module %s\n", test, module);
        return;
    }
    test_function(10, 'f', 100, 10, 20);

    // Reset the mocking library called 'blueslip' after each test
    void (*reset_mocks)() = dlsym(handle, "reset_mocks");
    if (reset_mocks == NULL) {
        fprintf(stderr, "Error: Failed to find symbol 'reset_mocks' in module %s\n", module);
        return;
    }
    reset_mocks();

    // Log test results, including the name of the module and the name of each test
    printf("Test result for module %s: Test %s passed\n", module, test);
