using namespace std;

// Define constants for range of random values and vector length
const float RANDOM_MIN = -10.0f;
const float RANDOM_MAX = 10.0f;
const int VECTOR_LENGTH = 3;

// Define data types for input and output
struct DataPoint {
    union {
        float floatValue;
        vector<double> vectorValue;
    };
};

// Define function to generate random value within range
float generateRandomFloat(float min, float max) {
    return ((float)rand()) / RAND_MAX * (max - min) + min;
}

// Define function to initialize data points with random values
void initializeDataPoints(vector<DataPoint> &dataPoints, bool isVector) {
    // Loop through each data point and generate a random value
    for (int i = 0; i < dataPoints.size(); i++) {
        if (isVector) {
            // Initialize vector with random values within specified range
            vector<double> vec;
            for (int j = 0; j < VECTOR_LENGTH; j++) {
                vec.push_back(generateRandomFloat(RANDOM_MIN, RANDOM_MAX));
            }
            dataPoints[i].vectorValue = vec;
        } else {
            // Initialize float with random value within specified range
            dataPoints[i].floatValue = generateRandomFloat(RANDOM_MIN, RANDOM_MAX);
        }
    }
}

// Define function to compute sum of elements in array of floats
float sumOfElements(vector<DataPoint> &dataPoints) {
    float sum = 0.0f;
    for (int i = 0; i < dataPoints.size(); i++) {
        if (isVector(dataPoints[i])) {
            // Sum magnitudes of vectors
            vector<double> vec = dataPoints[i].vectorValue;
            for (int j = 0; j < VECTOR_LENGTH; j++) {
                sum += abs(vec[j]);
            }
        } else {
            // Sum elements of floats
            sum += dataPoints[i].floatValue;
        }
    }
    return sum;
}

// Define function to print sum of elements in array of floats
void printSumOfElements(vector<DataPoint> &dataPoints) {
    cout << "Sum of elements: " << sumOfElements(dataPoints) << endl;
}

int main() {
    // Get number of data points from user input
    int numDataPoints = 0;
    cout << "Enter the number of data points: ";
    cin >> numDataPoints;

    // Initialize vector of data points with given size
    vector<DataPoint> dataPoints(numDataPoints);

    // Get user input on whether to initialize with random float or vector
    bool isVector = false;
    cout << "Enter 'f' to initialize with a random float within the range (-10, 10), or enter 'v' to initialize with a random vector of length 3: ";
    cin >> isVector;

    // Initialize data points with random values
    initializeDataPoints(dataPoints, isVector);

    // Print sum of elements in array of floats
    printSumOfElements(dataPoints);

    return 0;
}']

