// read from standard input and dynamically allocate memory for an array of 'DataPoint' structures
void processDataPoints(int numDataPoints, double threshold) {
    // Initialize an empty array of pointers to DataPoint structs
    struct DataPoint** dataPoints = (struct DataPoint**)malloc(numDataPoints * sizeof(struct DataPoint*));
    if (dataPoints == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    // Read input data points from standard input and store them in the array
    for (int i = 0; i < numDataPoints; i++) {
        double value;
        scanf("%lf", &value);
        struct DataPoint* point = (struct DataPoint*)malloc(sizeof(struct DataPoint));
        if (point == NULL) {
            printf("Memory allocation failed\n");
            return;
        }
        point->value = value;
        point->timestamp = generateRandomTimestamp();
        point->id = i + 1;
        point->category = determineCategory(value, threshold);
        dataPoints[i] = point;
    }

    // Compute average value and timestamp of the data points
    double sum = 0.0;
    time_t minTimestamp = dataPoints[0]->timestamp;
    for (int i = 0; i < numDataPoints; i++) {
        sum += dataPoints[i]->value;
        if (dataPoints[i]->timestamp < minTimestamp) {
            minTimestamp = dataPoints[i]->timestamp;
        }
    }
    double averageValue = sum / numDataPoints;
    time_t maxTimestamp = minTimestamp + 1000; // arbitrary large value to represent the maximum timestamp
    for (int i = 0; i < numDataPoints; i++) {
        if (dataPoints[i]->timestamp > maxTimestamp) {
            maxTimestamp = dataPoints[i]->timestamp;
        }
    }
    printf("Average value: %f\n", averageValue);
    printf("Minimum timestamp: %s\n", ctime(&minTimestamp));
    printf("Maximum timestamp: %s\n", ctime(&maxTimestamp));

    // Clean up memory
    for (int i = 0; i < numDataPoints; i++) {
        free(dataPoints[i]);
    }
    free(dataPoints);
}

// Helper function to generate random timestamps within specified ranges
time_t generateRandomTimestamp() {
    time_t minTimestamp = 0; // minimum timestamp in seconds since epoch
    time_t maxTimestamp = 1000000000; // maximum timestamp in seconds since epoch
    return (rand() % (maxTimestamp - minTimestamp)) + minTimestamp;
}

// Helper function to determine category of a data point based on threshold value
int determineCategory(double value, double threshold) {
    if (value <= threshold) {
        return 1;
    } else {
        return 2;
    }
}
