char* generate_random_integers(int num_records, int min_value, int max_value) {
    if (num_records <= 0 || min_value >= max_value) {
        return NULL;
    }

    // Create an array of records with the specified number of elements
    Record* records = malloc(sizeof(Record) * num_records);
    if (!records) {
        return NULL;
    }

    // Initialize each record's integer field to a random value within the specified range
    for (int i = 0; i < num_records; i++) {
        records[i].num = rand() % (max_value - min_value + 1) + min_value;
    }

    // Allocate memory for the output string and append each record's integer value to it
    int output_size = num_records * sizeof(int);
    char* output = malloc(output_size);
    if (!output) {
        free(records);
        return NULL;
    }

    for (int i = 0; i < num_records; i++) {
        sprintf(output + i * sizeof(int), "%d ", records[i].num);
    }

    // Free the array of records and return the output string
