char* modify_filename(const char* filename, const char* directory_path) {
    if (!filename || !directory_path) {
        return NULL;
    }

    // Allocate memory for the modified filename and append the directory path
    int dir_len = strlen(directory_path);
    int filename_len = strlen(filename);
    char* modified_filename = malloc((dir_len + filename_len + 1) * sizeof(char));
    if (!modified_filename) {
        return NULL;
    }

    sprintf(modified_filename, "%s%s", directory_path, filename);

    // Analyze the length and content of the filename to determine the number of digits to append
    int num_digits = 1;
    for (int i = filename_len - 1; i >= 0; i--) {
        if (!isdigit(filename[i])) {
            break;
        } else {
            num_digits++;
        }
    }

    // Append the file type suffix to the modified filename and return it
    sprintf(modified_filename + filename_len, "_%0*d.%s", MAX_DIGITS, num_digits, FILETYPE);
    return modified_filename;
}
