#define MAX_URL_LENGTH 1024
#define MAX_DOMAIN_LENGTH 256
#define MAX_PARAMS_LENGTH 512

struct URL {
    char* scheme;
    char* host;
    char* path;
};

struct Domain {
    char* name;
    struct in_addr address;
};

struct URLParams {
    char* params;
    size_t len;
};

struct URLModificationResult {
    char* modifiedURL;
    int status;
};

// Function to read a single URL from standard input
char* readURL() {
    char url[MAX_URL_LENGTH];
    fgets(url, MAX_URL_LENGTH, stdin);
    return strdup(url);
}

// Function to parse a URL into its components
struct URL parseURL(const char* url) {
    struct URL parsed;
    parsed.scheme = strtok(url, "://");
    if (parsed.scheme == NULL) {
        return parsed;
    }
    parsed.host = strtok(NULL, "/");
    parsed.path = strtok(NULL, "\n");
    return parsed;
}

// Function to extract domain name from a URL
char* getDomainName(const char* url) {
    struct URL parsed = parseURL(url);
    if (parsed.host == NULL) {
        return NULL;
    }
    char* domain = strtok(parsed.host, ":");
    return strdup(domain);
}

// Function to resolve a domain name to an IP address
struct Domain* resolveDomain(const char* domainName) {
    struct Domain* domain = malloc(sizeof(struct Domain));
    domain->name = strdup(domainName);
    if (inet_pton(AF_INET, domainName, &domain->address) <= 0) {
        return NULL;
    }
    return domain;
}

// Function to append parameters to a URL
struct URLParams appendParams(const char* url, const char* params) {
    struct URLParams parsed = {};
    parsed.params = strdup(url);
    size_t len = strlen(parsed.params);
    if (len > 0 && parsed.params[len-1] == '/') {
        len--;
    }
    char* newURL = malloc(len + strlen(params) + 2);
    sprintf(newURL, "%s?%s", parsed.params, params);
    return parsed;
}

// Function to modify a URL based on given criteria
struct URLModificationResult modifyURL(const char* url) {
    struct URLModificationResult result = {};
    struct URL parsed = parseURL(url);
    if (parsed.host == NULL || parsed.path == NULL) {
        return result;
    }
    struct Domain* domain = resolveDomain(parsed.host);
    if (domain == NULL) {
        return result;
    }
    char* newURL = malloc(strlen(url) + strlen(params) + 10);
    sprintf(newURL, "%s://%s/%s", parsed.scheme, domain->name, parsed.path);
    result.modifiedURL = newURL;
    result.status = 1;
    return result;
}

// Function to free resources allocated by modifyURL
void freeModificationResult(struct URLModificationResult* result) {
    if (result->modifiedURL != NULL) {
        free(result->modifiedURL);
    }
}

int main() {
    while (1) {
        char* url = readURL();
        struct URLModificationResult result = modifyURL(url);
        if (result.status == 1) {
            printf("%s\n", result.modifiedURL);
            freeModificationResult(&result);
        } else {
            printf("Invalid URL\n");
            free(url);
        }
    }
}']

