// Define a structure to store file metadata
typedef struct {
    char* filename;
    long size;
    time_t modified_time;
} file_info;

// Helper function to find the largest file size in the array of file_info records
long get_largest_file_size(file_info** files, int num_files) {
    long largest_size = 0;
    for (int i = 0; i < num_files; i++) {
        if (files[i]->size > largest_size) {
            largest_size = files[i]->size;
        }
    }
    return largest_size;
}

// Function to process a dynamic list of file paths received via standard input, managing memory allocation for an array of file_info structures to store metadata such as file name, size, and modification time.
void process_file_paths(char* path) {
    // Initialize the array of file_info records with NULL values
    int num_files = 10; // default capacity of the array
    file_info** files = (file_info**)malloc(num_files * sizeof(file_info*));
    for (int i = 0; i < num_files; i++) {
        files[i] = NULL;
    }

    // Read the input path and extract metadata
    char* current_path = path;
    while (*current_path != '\0') {
        // Allocate memory for a new file_info record
        file_info* temp = (file_info*)malloc(sizeof(file_info));

        // Initialize the fields of the record with metadata from the current file path
        temp->filename = strdup(current_path);
        struct stat file_stats;
        if (stat(current_path, &file_stats) == 0) {
            temp->size = file_stats.st_size;
            temp->modified_time = file_stats.st_mtime;
        } else {
            // Handle invalid file paths or missing metadata
            free(temp);
            continue;
        }

        // Check if the array needs to be resized
        if (num_files == 0) {
            num_files = 2 * num_files;
            file_info** temp = realloc(files, num_files * sizeof(file_info*));
            if (temp != NULL) {
                files = temp;
            } else {
                    free(temp); // Free the allocated memory in case of error
                    break;
            }
        }

        // Add the new record to the array
        files[num_files - 1] = temp;
        num_files--;
        current_path += strlen(current_path) + 1;
    }

    // Find and print the largest file size
    long largest_size = get_largest_file_size(files, num_files);
    printf("Largest file size: %ld\n", largest_size);

    // Free memory for the array of file_info records
    for (int i = 0; i < num_files; i++) {
        free(files[i]);
    }
    free(files);
}
