// Define the structure to store file metadata and checksums
typedef struct {
    char *filename;
    long size;
    time_t modification_time;
    unsigned char *checksum;
} file_info;

// Define the configuration parameters for the program
#define DEFAULT_NUM_FILES 10
#define HASHING_ALGORITHM SHA256

// Define the function to process a list of file paths from standard input
void process_file_paths(int num_files) {
    // Declare variables for dynamic memory allocation and error handling
    file_info *files = NULL;
    int i, j;
    unsigned char hash[SHA256_DIGEST_LENGTH];

    // Allocate memory for the array of 'file_info' structures
    files = (file_info *)malloc(sizeof(file_info) * num_files);
    if (files == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for file metadata\n");
        return;
    }

    // Initialize the array of 'file_info' structures with empty values
    for (i = 0; i < num_files; i++) {
        files[i].filename = NULL;
        files[i].size = -1;
        files[i].modification_time = -1;
        files[i].checksum = NULL;
    }

    // Read the list of file paths from standard input and populate the array of 'file_info' structures
    for (j = 0; j < num_files; j++) {
        char *path = NULL;
        if (!fgets(path, PATH_MAX, stdin)) {
            fprintf(stderr, "Error: failed to read file path from standard input\n");
            return;
        }
        struct stat buf;
        if (stat(path, &buf) == -1) {
            fprintf(stderr, "Error: failed to get metadata for file %s\n", path);
            continue;
        }
        files[j].filename = strdup(path);
        files[j].size = buf.st_size;
        files[j].modification_time = buf.st_mtime;
        // Compute the file checksum using the specified hashing algorithm
        SHA256_Init(&hash);
        SHA256_Update(&hash, (unsigned char *)path, strlen(path));
        SHA256_Final(files[j].checksum, &hash);
    }

    // Find and print the largest file size in the array of 'file_info' structures
    long max_size = -1;
    for (i = 0; i < num_files; i++) {
        if (files[i].size > max_size) {
            max_size = files[i].size;
        }
    }
    printf("Largest file size: %ld\n", max_size);

    // Free the memory allocated for the array of 'file_info' structures
    for (i = 0; i < num_files; i++) {
        free(files[i].filename);
        free(files[i].checksum);
    }
    free(files);
}

// Define the function to validate input sizes and handle memory allocation failures gracefully
void validate_input_sizes(int num_files) {
    if (num_files <= 0 || num_files > INT_MAX / sizeof(file_info)) {
        fprintf(stderr, "Error: invalid number of files specified\n");
        exit(EXIT_FAILURE);
    }
}

// Define the function to find and print the largest file size in the array of 'file_info' structures
void find_largest_file_size(file_info *files, int num_files) {
    // Declare variables for dynamic memory allocation and error handling
    long max_size = -1;
    int i;

    // Find the largest file size in the array of 'file_info' structures
    for (i = 0; i < num_files; i++) {
        if (files[i].size > max_size) {
            max_size = files[i].size;
        }
    }

    // Print the largest file size
    printf("Largest file size: %ld\n", max_size);
}

// Define the function to compute the file checksum using a specified hashing algorithm
void compute_file_checksum(file_info *files, int num_files) {
    // Declare variables for dynamic memory allocation and error handling
    unsigned char hash[SHA256_DIGEST_LENGTH];
    int i;

    // Compute the file checksum for each file in the array of 'file_info' structures using the specified hashing algorithm
    for (i = 0; i < num_files; i++) {
        SHA256_Init(&hash);
        SHA256_Update(&hash, (unsigned char *)files[i].filename, strlen(files[i].filename));
        SHA256_Final(files[i].checksum, &hash);
    }
}

// Define the function to manage memory allocation failures gracefully
void handle_memory_allocation_failure() {
    fprintf(stderr, "Error: failed to allocate memory for file metadata\n");
    exit(EXIT_FAILURE);
}

// Define the main function
int main(int argc, char *argv[]) {
    // Declare variables for dynamic memory allocation and error handling
    int num_files = DEFAULT_NUM_FILES;

    // Check command-line arguments for the number of files to initialize
    if (argc == 2) {
        num_files = atoi(argv[1]);
        validate_input_sizes(num_files);
    }

    // Process the list of file paths from standard input and populate an array of 'file_info' structures
    process_file_paths(num_files);

    // Find and print the largest file size in the array of 'file_info' structures
    find_largest_file_size(files, num_files);

    // Compute the file checksum using a specified hashing algorithm for each file in the array of 'file_info' structures
    compute_file_checksum(files, num_files);

    return 0;
}
