// Network address information structure
struct network_info {
    char *address;
    int type; // IPv4 or IPv6
    char *hostname;
    time_t last_seen;
    int reliability;
};

// Function to initialize the network address list
void init_network_list(struct network_info **list) {
    // Initialize the list as an empty pointer
    *list = NULL;
