// Struct to represent a transaction with multiple amounts and status code
struct Transaction {
    float amounts[3];
    char status;
};

// Function to dynamically allocate memory for and initialize three arrays:
// one for float precision values, one for char status codes, and another for an array of transaction structures
void init_arrays(int range, int step_size, struct Transaction transactions[], int num_transactions) {
    // Validate input sizes and handle memory allocation failures gracefully
    if (range < 1 || step_size <= 0 || num_transactions < 1) {
        printf("Invalid input sizes. Aborting initialization.\n");
        return;
    }

    // Allocate memory for the three arrays
    float *precision_values = (float *)malloc(sizeof(float) * range);
    char *status_codes = (char *)malloc(sizeof(char) * num_transactions);
    struct Transaction *transaction_array = (struct Transaction *)malloc(sizeof(struct Transaction) * num_transactions);

    // Check for memory allocation failures and handle them gracefully
    if (!precision_values || !status_codes || !transaction_array) {
        printf("Memory allocation failed. Aborting initialization.\n");
        free(precision_values);
        free(status_codes);
        free(transaction_array);
        return;
    }

    // Initialize the three arrays with random values within the specified range and step size
    for (int i = 0; i < range; i++) {
        precision_values[i] = ((float)rand() / RAND_MAX) * range + i * step_size;
    }

    for (int i = 0; i < num_transactions; i++) {
        status_codes[i] = 'N';
        for (int j = 0; j < 3; j++) {
            transaction_array[i].amounts[j] = ((float)rand() / RAND_MAX) * range + i * step_size;
        }
    }

    // Manage memory allocation for and initialize the arrays of transactions, validating input sizes and handling memory allocation failures gracefully
    free(precision_values);
    free(status_codes);
    free(transaction_array);
}
