    // Allocate memory for the records array
    *records = (Record *)malloc(sizeof(Record) * num_records);
    if (*records == NULL) {
        perror("Failed to allocate memory for records");
        fclose(file);
        return -1;
    }

    // Read the records from the file and store them in the array
    int i = 0;
    while (i < num_records && !feof(file)) {
        if (fscanf(file, "%d %ld", &(*records)[i].key, &(*records)[i].offset) != 2) {
            perror("Failed to read record");
            fclose(file);
            return -1;
