        }
    }
}

void generate_random_values(long* offset_arr, int* key_arr, struct record** data_arr, size_t num_records) {
    // Generate random values for the offset and key arrays
    srand(time(NULL));
    for (size_t i = 0; i < num_records; i++) {
        offset_arr[i] = rand() % 10000000;
        key_arr[i] = rand();
    }
}

void free_arrays(long* offset_arr, int* key_arr, struct record** data_arr, size_t num_records) {
