    for (size_t i = 0; i < num_records; i++) {
        free(data_arr[i]);
    }
    free(offset_arr);
    free(key_arr);
    free(data_arr);
}

void adjust_num_records(size_t* num_records, size_t total_space) {
    // Adjust the number of records based on available disk space
    if (total_space < *num_records) {
        printf("Not enough disk space available. Reducing number of records\n");
        *num_records = total_space / sizeof(struct record);
    }
}

