        perror("Failed to get disk usage information");
        return 1;
    }
    total_space = stat.f_bsize * stat.f_blocks;
    size_t num_records = total_space / sizeof(struct record);

    // Initialize the arrays with random values
    long* offset_arr = malloc(num_records * sizeof(long));
    int* key_arr = malloc(num_records * sizeof(int));
    struct record** data_arr = malloc(num_records * sizeof(struct record*));
