            printf("%d\n", records[i].data.i);
        } else {
            printf("%s\n", records[i].data.s);
        }
    }

    // Free the memory allocated for the array of records
    for (int i = 0; i < num_records; i++) {
        if (!init_random_str_len) {
            free(records[i].data.s);
        }
    }
    free(records);
}

// Define the function to determine the maximum integer value or the longest string among the records
void max_value_or_longest_string(record_t *records, int num_records) {
    // Initialize variables to keep track of the maximum integer value and the longest string length
    int max_int = 0;
    int longest_str_len = 0;

    // Iterate over the records and update the maximum integer value and the longest string length accordingly
    for (int i = 0; i < num_records; i++) {
        if (records[i].data.i > max_int) {
            max_int = records[i].data.i;
        }
        int str_len = strlen(records[i].data.s);
        if (str_len > longest_str_len) {
            longest_str_len = str_len;
        }
    }

    // Print the maximum integer value and the longest string length to standard output
    printf("Maximum integer value: %d\n", max_int);
    printf("Longest string length: %d\n", longest_str_len);
}

// Define a function to execute shell commands with input and output redirection, managing file path validation and permissions
void execute_shell_command(char *cmd) {
    // Validate the file path and permissions before executing the command
    if (access(cmd, X_OK)) {
        printf("Error: unable to access %s\n", cmd);
        return;
    }

    // Execute the shell command using system() function
    int status = system(cmd);
    if (status == -1) {
        printf("Error: unable to execute %s\n", cmd);
    } else if (!WIFEXITED(status)) {
        printf("Warning: %s did not terminate normally\n", cmd);
    } else if (WEXITSTATUS(status)) {
        printf("Error: %s returned with status code %d\n", cmd, WEXITSTATUS(status));
    }
}
