<?php
namespace RecordManager;

use Record\Record;
use ExternalAPI\Client;
use Logging\Log;

class Manager {
  private $records;
  private $client;

  public function __construct(array $options) {
    $this->records = [];
    $this->client = new Client($options['api_url']);
  }

  public function initialize(int $count, array $parameters): void {
    for ($i=0; $i < $count; $i++) {
      if (isset($parameters['integer'])) {
        $value = rand($parameters['integer']['min'], $parameters['integer']['max']);
      } elseif (isset($parameters['string'])) {
        $value = $this->randomString($parameters['string']['length']);
      }
      $record = new Record();
      $record->setValue($value);
      $this->records[] = $record;
    }
  }

  public function getRecords(): array {
    return $this->records;
  }

  public function filter(array $parameters): array {
    $filteredRecords = [];
    foreach ($this->records as $record) {
      if ($this->passesFilter($record, $parameters)) {
        $filteredRecords[] = $record;
      }
    }
    return $filteredRecords;
  }

  private function passesFilter(Record $record, array $parameters): bool {
    foreach ($parameters as $key => $value) {
      if (!$this->passesFilterKey($record, $key, $value)) {
        return false;
      }
    }
    return true;
  }

  private function passesFilterKey(Record $record, string $key, mixed $value): bool {
    $actualValue = $record->getValue();
    if ($key === 'integer') {
      return is_int($actualValue) && $actualValue >= $value;
    } elseif ($key === 'string') {
      return is_string($actualValue) && strlen($actualValue) >= $value;
    }
    return false;
  }

  public function update(string $id, array $requestBody): bool {
    if (!isset($this->records[$id])) {
      return false;
    }
    $record = $this->records[$id];
    foreach ($requestBody as $key => $value) {
      $record->setValue($key, $value);
    }
    return true;
  }

  public function delete(string $id): bool {
    if (!isset($this->records[$id])) {
      return false;
    }
    unset($this->records[$id]);
    return true;
  }

  private function randomString(int $length): string {
    $characters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    $string = '';
    for ($i=0; $i < $length; $i++) {
      $string .= $characters[rand(0, strlen($characters)-1)];
    }
    return $string;
  }
}
