#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>

// Define a structure to hold user-defined objects
typedef struct object {
    union {
        float f; // For floating-point numbers
        char *s; // For dynamically allocated strings
    };
} object_t;

// Define an array of objects
object_t *objects = NULL;
size_t num_objects = 0;

// Define a function to initialize the list with random values within a specified range or random strings of a specified length
void init(float min, float max) {
    // Allocate memory for the array of objects
    objects = malloc(sizeof(object_t) * num_objects);
    assert(objects != NULL);

    // Initialize each object with a random floating-point number within the specified range
    for (size_t i = 0; i < num_objects; ++i) {
        objects[i].f = min + ((float)rand() / RAND_MAX) * (max - min);
    }
}

// Define a function to initialize the list with random strings of a specified length
void init_strings(size_t len) {
    // Allocate memory for the array of objects
    objects = malloc(sizeof(object_t) * num_objects);
    assert(objects != NULL);

    // Initialize each object with a dynamically allocated string of the specified length
    for (size_t i = 0; i < num_objects; ++i) {
        char *str = malloc(len + 1);
        assert(str != NULL);
        memset(str, 'a', len);
        str[len] = '\0';
        objects[i].s = str;
    }
}

// Define a function to add an object to the list
void add_object(object_t obj) {
    // Reallocate memory for the array of objects if necessary
    if (num_objects == 0 || !(obj.f >= objects[0].f && obj.f <= objects[num_objects - 1].f)) {
        objects = realloc(objects, sizeof(object_t) * (num_objects + 1));
        assert(objects != NULL);
    }

    // Add the object to the end of the list
    objects[num_objects++] = obj;
}

// Define a function to delete an object from the list by its index
void delete_object(size_t idx) {
    // Reallocate memory for the array of objects if necessary
    if (num_objects == 0 || num_objects <= idx) {
        return;
    }

    // Shift all objects after the deleted object one position to the left
    for (size_t i = idx + 1; i < num_objects; ++i) {
        objects[i - 1] = objects[i];
    }

    // Decrement the number of objects
    num_objects--;
}

// Define a function to retrieve an object from the list by its index
object_t get_object(size_t idx) {
    // Return the object at the specified index if it exists
    return (idx < num_objects) ? objects[idx] : NULL;
}

// Define a function to filter the objects in the list based on specific criteria
void filter(float threshold, size_t len) {
    // Create a temporary array to store filtered objects
    object_t *filtered = malloc(sizeof(object_t) * num_objects);
    assert(filtered != NULL);

    // Initialize the number of filtered objects to 0
    size_t num_filtered = 0;

    // Iterate over all objects in the list
    for (size_t i = 0; i < num_objects; ++i) {
        object_t obj = objects[i];

        // If the object meets the filtering criteria, add it to the temporary array
        if (obj.f >= threshold || strlen(obj.s) >= len) {
            filtered[num_filtered++] = obj;
        }
    }

    // Reallocate memory for the array of objects based on the number of filtered objects
    objects = realloc(objects, sizeof(object_t) * num_filtered);
    assert(objects != NULL);

    // Copy the filtered objects to the beginning of the list
    memcpy(objects, filtered, num_filtered * sizeof(object_t));

    // Free the temporary array
    free(filtered);
}

// Define a function to calculate and return the average of all floating-point numbers in the list
float get_average() {
    float sum = 0;

    // Iterate over all objects in the list
    for (size_t i = 0; i < num_objects; ++i) {
        sum += objects[i].f;
    }

    return sum / num_objects;
}

// Define a function to calculate and return the longest common prefix among strings meeting the filtering criteria
char *get_longest_prefix() {
    // Create a temporary array to store the strings that meet the filtering criteria
    char **strings = malloc(sizeof(char *) * num_objects);
    assert(strings != NULL);

    // Initialize the number of strings to 0
    size_t num_strings = 0;

    // Iterate over all objects in the list
    for (size_t i = 0; i < num_objects; ++i) {
        object_t obj = objects[i];

        // If the object meets the filtering criteria, add it to the temporary array
        if (strlen(obj.s) >= len) {
            strings[num_strings++] = obj.s;
        }
    }

    // Reallocate memory for the array of objects based on the number of filtered objects
    strings = realloc(strings, sizeof(char *) * num_strings);
    assert(strings != NULL);

    // Calculate the longest common prefix among the filtered strings
    size_t len = 0;
    while (len < num_strings && strncmp(strings[0], strings[len], len) == 0) {
        ++len;
    }

    // Free the temporary array
    free(strings);

    return len > 0 ? malloc(len + 1) : NULL;
}

// Define a function to execute an external command using `system()` and capture its output with `popen()`
void system_exec(char *cmd, char **output) {
    FILE *fp = popen(cmd, "r");
    assert(fp != NULL);

    // Read the output of the command from the pipe
    size_t len = 0;
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), fp) != NULL) {
        len += strlen(buffer);
    }

    // Reallocate memory for the output string based on the length of the command's output
    *output = malloc(len + 1);
    assert(*output != NULL);

    // Copy the command's output to the output string
    rewind(fp);
    len = fread(*output, sizeof(char), len, fp);
    (*output)[len] = '\0';

    pclose(fp);
}
