#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include "database_connector.h"
#include "logging_framework.h"

typedef struct {
    int id;
    char* name;
} record;

void update_resource(int id, const char* request_body) {
    // Validate the input parameters
    if (id < 0 || request_body == NULL) {
        LOG_ERROR("Invalid input parameters");
        return;
    }

    // Allocate memory for the record
    record* rec = malloc(sizeof(record));
    if (rec == NULL) {
        LOG_ERROR("Failed to allocate memory for the record");
        return;
    }

    // Parse the request body and update the record
    char* name = strdup(request_body);
    rec->id = id;
    rec->name = name;

    // Update the record in the database
    int result = database_update_record(rec);
    if (result != 0) {
        LOG_ERROR("Failed to update the record in the database");
        return;
    }
}

void delete_resource(int id) {
    // Validate the input parameter
    if (id < 0) {
        LOG_ERROR("Invalid input parameters");
        return;
    }

    // Allocate memory for the record
    record* rec = malloc(sizeof(record));
    if (rec == NULL) {
        LOG_ERROR("Failed to allocate memory for the record");
        return;
    }

    // Delete the record from the database
    int result = database_delete_record(id);
    if (result != 0) {
        LOG_ERROR("Failed to delete the record from the database");
        return;
    }
}

int main() {
    // Initialize the database connector
    database_connector_init();

    // Read the number of records to be initialized
    int num_records = 0;
    scanf("%d", &num_records);

    // Dynamically allocate memory for the array of records
    record* records = malloc(sizeof(record) * num_records);
    if (records == NULL) {
        LOG_ERROR("Failed to allocate memory for the records");
        return 1;
    }

    // Initialize each record with a random value or string content
    for (int i = 0; i < num_records; i++) {
        records[i].id = rand() % 100 + 1;
        records[i].name = malloc(sizeof(char) * RAND_MAX);
        if (records[i].name == NULL) {
            LOG_ERROR("Failed to allocate memory for the record");
            return 1;
        }
        strcpy(records[i].name, "random string");
    }

    // Filter records based on specific criteria
    for (int i = 0; i < num_records; i++) {
        if (records[i].id > 50) {
            // Delete the record
            delete_resource(records[i].id);
        } else {
            // Update the record
            update_resource(records[i].id, "new name");
        }
    }

    // Find and print the largest integer in the array of records
    int max_int = INT_MIN;
    for (int i = 0; i < num_records; i++) {
        if (records[i].id > max_int) {
            max_int = records[i].id;
        }
    }
    printf("Largest integer in the array of records: %d\n", max_int);

    // Find and print the longest string in the array of records
    int max_str_len = 0;
    for (int i = 0; i < num_records; i++) {
        if (strlen(records[i].name) > max_str_len) {
            max_str_len = strlen(records[i].name);
        }
    }
    printf("Longest string in the array of records: %s\n", records[0].name);

    // Clean up
    for (int i = 0; i < num_records; i++) {
        free(records[i].name);
    }
    free(records);
    database_connector_cleanup();
}
