#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <arpa/inet.h>

// Define the maximum number of records to be processed
#define MAX_RECORDS 10000

// Define the maximum length of a single record (in bytes)
#define MAX_RECORD_LENGTH 256

// Define the maximum number of text files to be read concurrently
#define MAX_FILES 10

// Define the seed value for generating random values
#define SEED 42

// Define the type of data (integer or string)
typedef enum { INTEGER, STRING } DataType;

// Define the function to read a text file and process its contents
void processTextFile(char* filename, int numRecords, DataType dataType) {
    // Open the file for reading
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    // Allocate memory for the records
    char** records = (char**)malloc(sizeof(char*) * numRecords);
    if (records == NULL) {
        printf("Error: unable to allocate memory for records\n");
        fclose(fp);
        return;
    }

    // Read the contents of the file and process each line
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    int i = 0;
    while ((read = getline(&line, &len, fp)) != -1) {
        // Split the line into individual fields using whitespace as a delimiter
        char** fields = strtok(line, " ");
        if (fields == NULL) {
            printf("Error: unable to split line %d in file %s\n", i + 1, filename);
            break;
        }

        // Check the number of fields and process accordingly
        int numFields = 0;
        while (fields[numFields] != NULL) {
            if (dataType == INTEGER) {
                // Process an integer field
                int value = atoi(fields[numFields]);
                records[i][numFields] = value;
            } else if (dataType == STRING) {
                // Process a string field
                char* value = fields[numFields];
                records[i][numFields] = value;
            }
            numFields++;
        }

        // Compute the average of the last two fields and append to the end of the line
        if (numFields >= 2) {
            int sum = records[i][numFields - 2] + records[i][numFields - 1];
            float average = (float)sum / numFields;
            char buffer[64];
            snprintf(buffer, sizeof(buffer), "%.2f", average);
            records[i][numFields++] = strdup(buffer);
        } else if (numFields == 1) {
            // If there are only one field, use the value as is and append a zero for the average
            char buffer[64];
            snprintf(buffer, sizeof(buffer), "%d", records[i][0]);
            records[i][numFields++] = strdup(buffer);
        } else {
            // If there are no fields, use a default value of zero for the average
            records[i][numFields++] = strdup("0.00");
        }

        i++;
        if (i == numRecords) break;
    }

    // Close the file and free memory allocated for the records
    fclose(fp);
    for (int j = 0; j < numRecords; j++) {
        free(records[j]);
    }
    free(records);
}

// Define the function to process a single record and compute its average
void processRecord(char* record, int numFields, DataType dataType) {
    // Check the number of fields and process accordingly
    if (numFields >= 2) {
        int sum = 0;
        for (int i = 0; i < numFields - 1; i++) {
            if (dataType == INTEGER) {
                // Process an integer field
                int value = atoi(record[i]);
                sum += value;
            } else if (dataType == STRING) {
                // Process a string field
                char* value = record[i];
                sum += strlen(value);
            }
        }
        float average = (float)sum / numFields;
        printf("%.2f\n", average);
    } else if (numFields == 1) {
        // If there is only one field, use the value as is and print a zero for the average
        printf("0.00\n");
    } else {
        // If there are no fields, print a default value of zero for the average
        printf("0.00\n");
    }
}

// Define the function to compute the average of multiple records and append it to the end of each line
void computeAverage(char** records, int numRecords, DataType dataType) {
    // Process each record and compute its average
    for (int i = 0; i < numRecords; i++) {
        processRecord(records[i], strlen(records[i]), dataType);
    }
}

// Define the function to read a directory of text files and process their contents concurrently
void processDirectory(char* directory, int numFiles, DataType dataType) {
    // Open the directory for reading
    DIR* dir = opendir(directory);
    if (dir == NULL) {
        printf("Error: unable to open directory %s\n", directory);
        return;
    }

    // Allocate memory for the text files and their contents
    char** files = (char**)malloc(sizeof(char*) * numFiles);
    if (files == NULL) {
        printf("Error: unable to allocate memory for files\n");
        closedir(dir);
        return;
    }
    char** records = (char**)malloc(sizeof(char*) * MAX_RECORDS);
    if (records == NULL) {
        printf("Error: unable to allocate memory for records\n");
        free(files);
        closedir(dir);
        return;
    }

    // Read the contents of each text file and process its lines concurrently
    struct dirent* entry = NULL;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }
        char* filename = entry->d_name;
        int i = 0;
        while (i < numFiles && files[i] != NULL) {
            if (strcmp(filename, files[i]) == 0) {
                break;
            }
            i++;
        }
        if (i == numFiles) {
            // Allocate memory for the current text file and its contents
            files[i] = strdup(filename);
            records[i] = (char*)malloc(sizeof(char) * MAX_RECORD_LENGTH);
            if (records[i] == NULL) {
                printf("Error: unable to allocate memory for file %s\n", filename);
                free(files[i]);
                files[i] = NULL;
                break;
            }
        }
        // Read the contents of the text file and process each line
        FILE* fp = fopen(filename, "r");
        if (fp == NULL) {
            printf("Error: unable to open file %s\n", filename);
            continue;
        }
        char* line = NULL;
        size_t len = 0;
        ssize_t read;
        while ((read = getline(&line, &len, fp)) != -1) {
            // Process the current record and append its average to the end of the line
            processRecord(records[i], strlen(records[i]), dataType);
        }
        fclose(fp);
    }

    // Close the directory and free memory allocated for the text files and their contents
    closedir(dir);
    for (int i = 0; i < numFiles; i++) {
        if (files[i] != NULL) {
            free(files[i]);
            records[i] = NULL;
        }
    }
    free(files);
    free(records);
}

// Define the function to compute the average of multiple records and export them to a binary file
void exportAverage(char** records, int numRecords) {
    // Open the binary file for writing
    FILE* fp = fopen("output.bin", "wb");
    if (fp == NULL) {
        printf("Error: unable to open output file\n");
        return;
    }

    // Write the computed averages to the binary file
    for (int i = 0; i < numRecords; i++) {
        fwrite(records[i], strlen(records[i]), 1, fp);
    }

    // Close the binary file and free memory allocated for the records
    fclose(fp);
}

int main() {
    srand(SEED);

    // Read a directory of text files concurrently and process their contents
    processDirectory("data/", MAX_FILES, INTEGER);

    // Compute the average of multiple records and append it to the end of each line
    computeAverage(records, numRecords, INTEGER);

    // Export the processed records to a binary file for persistence
    exportAverage(records, numRecords);

    return 0;
}
