#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

// Define the record structure
typedef struct {
    int value;
    char* name;
    long* offset;
} record;

// Define the custom data structure for managing records
typedef struct {
    record** records; // Array of pointers to record structures
    size_t capacity; // Current capacity of the array
    size_t size; // Number of records in the array
    long* offsets; // Array of offsets used for quick lookup
} record_manager;

// Define functions for managing records
void init(record_manager* manager) {
    manager->records = NULL;
    manager->capacity = 0;
    manager->size = 0;
    manager->offsets = NULL;
}

int insert(record_manager* manager, int value, char* name, long offset) {
    // Check if the array needs to be reallocated
    if (manager->capacity == manager->size) {
        // Reallocate the array with a new capacity twice the current size
        manager->records = realloc(manager->records, 2 * manager->capacity * sizeof(record*));
        if (manager->records == NULL) {
            return -1;
        }
        // Update the capacity of the array
        manager->capacity *= 2;
    }
    // Allocate memory for a new record structure
    record* new_record = malloc(sizeof(record));
    if (new_record == NULL) {
        return -1;
    }
    // Initialize the fields of the new record structure
    new_record->value = value;
    new_record->name = name;
    new_record->offset = offset;
    // Insert the new record into the array
    manager->records[manager->size++] = new_record;
    // Update the offsets array with the new offset
    manager->offsets[manager->size - 1] = offset;
    return 0;
}

int delete(record_manager* manager, int index) {
    // Check if the index is valid
    if (index < 0 || index >= manager->size) {
        return -1;
    }
    // Free the memory allocated for the deleted record structure
    free(manager->records[index]);
    // Shift all the elements after the deleted element to the left
    memmove(&manager->records[index], &manager->records[index + 1], (manager->size - index - 1) * sizeof(record*));
    manager->size--;
    return 0;
}

int find(record_manager* manager, int key) {
    // Check if the array is empty
    if (manager->size == 0) {
        return -1;
    }
    // Use a binary search to find the index of the record with the given key
    size_t low = 0;
    size_t high = manager->size - 1;
    while (low <= high) {
        size_t mid = (low + high) / 2;
        if (manager->offsets[mid] == key) {
            return mid;
        } else if (manager->offsets[mid] < key) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    // If the key is not found, return an error code
    return -1;
}

void update(record_manager* manager, int index) {
    // Check if the index is valid
    if (index < 0 || index >= manager->size) {
        return;
    }
    // Update the offset field of the record structure at the given index
    manager->offsets[index] = rand() % 1000;
}

int main() {
    // Initialize the record manager
    record_manager manager;
    init(&manager);

    // Insert records into the array
    insert(&manager, 10, "John", 500);
    insert(&manager, 20, "Jane", 600);
    insert(&manager, 30, "Bob", 700);

    // Find a record with a given key
    int index = find(&manager, 600);
    if (index >= 0) {
        printf("Record found at index %d\n", index);
    } else {
        printf("Record not found\n");
    }

    // Delete a record from the array
    delete(&manager, 1);

    // Update an offset field in a record structure
    update(&manager, 0);

    // Free the memory allocated for the records and offsets arrays
    free(manager.records);
    free(manager.offsets);

    return 0;
}']

