class RecordManager {
 public:
  // Constructor that initializes the record manager with a specified number of slots.
  explicit RecordManager(int numSlots) : records_(numSlots) {}

  // Method to insert a new record into the collection, optionally overwriting an existing record if it exists.
  void insert(const std::string& name, int value, long* offset) {
    auto it = records_.find(name);
    if (it != records_.end()) {
      // If there is already a record with the given name, overwrite it.
      Record& record = *it->second;
      record.value = value;
      record.offset = offset;
    } else {
      // Otherwise, create a new record and add it to the collection.
      records_.emplace(name, std::make_unique<Record>(value, name, offset));
    }
  }

  // Method to delete a record from the collection by its key.
  void delete(const std::string& name) {
    auto it = records_.find(name);
    if (it != records_.end()) {
      // If there is a record with the given name, remove it from the collection.
      records_.erase(it);
    }
  }

  // Method to find a record in the collection by its key and return it.
  const Record* find(const std::string& name) {
    auto it = records_.find(name);
    if (it != records_.end()) {
      // If there is a record with the given name, return it.
      return &(*it->second);
    } else {
      // Otherwise, return nullptr.
