void orchestrateCombatSequence(int minValue, int maxValue, int minCooldown) {
    // Initialize vector of combat records
    std::vector<CombatRecord> records;

    // Generate a random attack number within the specified range
    int attack = rand() % (maxValue - minValue + 1) + minValue;

    // Calculate cooldown time based on minimum cooldown duration and attack pattern
    std::time_t cooldownTime = std::time(0) + minCooldown;

