// Define the record structure to hold a single integer value
typedef struct {
    int value;
} Record;

// Declare a function to initialize an array of records with random values
void init_records(Record* recs, int num_recs, int range) {
    // Initialize a random number generator seeded with the current time
    srand(time(NULL));

    // Iterate over each record and generate a random value within the specified range
    for (int i = 0; i < num_recs; ++i) {
        recs[i].value = rand() % range + 1;
    }
}

// Declare a function to find and print the median value of an array of records
void print_median(Record* recs, int num_recs) {
    // Sort the array in ascending order using insertion sort
    for (int i = 1; i < num_recs; ++i) {
        Record key = recs[i];
        int j = i - 1;

        while (j >= 0 && recs[j].value > key.value) {
            recs[j + 1] = recs[j];
            --j;
        }

        recs[j + 1] = key;
    }

    // Print the median value by taking the middle element of the sorted array
    if (num_recs % 2 == 0) {
        printf("Median: %d\n", (recs[num_recs / 2 - 1].value + recs[num_recs / 2].value) / 2);
    } else {
        printf("Median: %d\n", recs[num_recs / 2].value);
    }
}

// Declare a function to allocate and initialize an array of records dynamically
void dynamic_allocate(Record** recs, int num_recs) {
    // Allocate memory for the array of records
    *recs = (Record*) malloc(num_recs * sizeof(Record));

    if (*recs == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
