// Structure to represent historical temperature readings
struct TemperatureReading {
    time_t timestamp;
    double temperature;
};

// Function to dynamically allocate and manage memory for the data structures
void* fetchData(const char* url, const char* filename) {
    // Initialize CURL handle
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to initialize CURL handle\n");
        return NULL;
    }

    // Set URL and file name for data download
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_WRITE_FUNCTION, writeData);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, filename);

    // Set timeout and connection options
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);
    curl_easy_setopt(curl, CURLOPT_FAILONERROR, 1L);

    // Perform data download and close CURL handle
    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "CURL error: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        return NULL;
    }
    curl_easy_cleanup(curl);

    // Open file for reading and allocate memory for data structures
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Failed to open file %s\n", filename);
        return NULL;
    }
    double* values = malloc(sizeof(double) * 3);
    unsigned short* indices = malloc(sizeof(unsigned short));
    struct TemperatureReading* readings = malloc(sizeof(struct TemperatureReading));
    if (!values || !indices || !readings) {
        fprintf(stderr, "Failed to allocate memory for data structures\n");
        return NULL;
    }

    // Read data from file and populate data structures
    size_t count = 0;
    while (fscanf(file, "%lf,%hu,%lu-%lu", &values[0], &indices[0], &readings[0].timestamp, &readings[0].temperature) == 4) {
        values[1] = readings[0].temperature;
        indices[1] = readings[0].timestamp;
        count++;
    }
    fclose(file);

    // Clean up and return data structures
    free(values);
    free(indices);
    free(readings);
    return NULL;
}

// Callback function for CURLOPT_WRITEFUNCTION
size_t writeData(void* ptr, size_t size, size_t nmemb, void* userdata) {
    // Check for memory allocation errors
    if (!ptr || size == 0 || (nmemb * size) < 1) {
        return 0;
    }

    // Save data to file
    FILE* file = (FILE*)userdata;
    fwrite(ptr, size, nmemb, file);
    return size * nmemb;
}
```
