        offsets[i].value = (long)((double)offset_range * ((double)rand() / RAND_MAX));
    }

    // Allocate memory for the keys array
    key_t *keys = (key_t *)malloc(num_records * sizeof(key_t));
    if (!keys) {
        printf("Error: failed to allocate memory for keys\n");
        free(offsets);
        return;
    }

    // Initialize the keys array with random values within the specified range
    for (int i = 0; i < num_records; i++) {
        keys[i].value = (int)((double)key_range * ((double)rand() / RAND_MAX));
    }

    // Allocate memory for the records array
    record_t *records = (record_t *)malloc(num_records * sizeof(record_t));
    if (!records) {
        printf("Error: failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize the records array with random values within the specified range
    for (int i = 0; i < num_records; i++) {
        records[i].value = (int)((double)key_range * ((double)rand() / RAND_MAX));
    }

    // Allocate memory for the node pointers array
    node_t **nodes = (node_t **)malloc(num_records * sizeof(node_t *));
    if (!nodes) {
        printf("Error: failed to allocate memory for nodes\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    // Initialize the node pointers array with pointers to each record in the records array
    for (int i = 0; i < num_records; i++) {
        nodes[i] = &records[i];
    }

    // Log memory allocation events using an external logging library
#ifdef USE_EXTERNAL_LOGGING
    log_memory_allocation(num_records, offset_range, key_range);
#endif
}

void print_record(const record_t *record) {
    printf("Record: %d\n", record->value);
}

void print_node(const node_t *node) {
    printf("Node: %p (record = %p, next = %p)\n", node, node->record, node->next);
}

void iterate_records(void (*callback)(const record_t *)) {
    for (int i = 0; i < num_records; i++) {
        callback(&records[i]);
    }
}

void iterate_nodes(void (*callback)(const node_t *)) {
    for (int i = 0; i < num_records; i++) {
        callback(&nodes[i]);
    }
}

#ifdef USE_EXTERNAL_LOGGING
