// Structure to hold data points
typedef struct {
    float value;
    unsigned long timestamp;
    bool valid;
} dataPoint;

// Function to read and process floating-point numbers from standard input
void processDataPoints(int limit) {
    // Array of data points
    dataPoint *dataPoints = NULL;

    // Initialize the array with a maximum size of 10,000 elements
    dataPoints = (dataPoint *)malloc(sizeof(dataPoint) * limit);

    if (dataPoints == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for data points\n");
        exit(EXIT_FAILURE);
    }

    // Initialize each data point's numerical fields with random values within a specified range
    srand(time(NULL));
    for (int i = 0; i < limit; i++) {
        dataPoints[i].value = rand() % 1000 + 1;
        dataPoints[i].timestamp = time(NULL);
        dataPoints[i].valid = true;
    }

    // Read floating-point numbers from standard input and add them to the array of data points
    int index = 0;
    while (index < limit) {
        float value;
        scanf("%f", &value);

        if (!scanf("%*[^\n]")) {
            break;
        }

        // Check if the input is valid and add it to the array of data points
        if (value >= 0 && value <= 100) {
            dataPoints[index].value = value;
            dataPoints[index].timestamp = time(NULL);
            dataPoints[index++].valid = true;
        } else {
            fprintf(stderr, "Error: Invalid input\n");
            continue;
        }
    }

    // Compute and print the average value of all valid data points in the array of records
    float sum = 0.0f;
    int count = 0;

    for (int i = 0; i < index; i++) {
        if (dataPoints[i].valid) {
            sum += dataPoints[i].value;
            count++;
        }
    }

    if (count > 0) {
        printf("Average value: %f\n", sum / (float)count);
    } else {
        printf("No valid data points found\n");
