  struct stat metadata;
} file_entry;

// Function to dynamically process a list of file paths provided via standard input
void process_file_list(char **argv) {
  // Initialize an array to store the file entries
  file_entry *entries = NULL;

  // Calculate the total size of all files and identify the largest file
  long total_size = 0, largest_size = 0;
  for (int i = 1; i < argc; i++) {
    if (!file_exists(argv[i])) {
      printf("File %s does not exist\n", argv[i]);
      continue;
    }
    total_size += file_size(argv[i]);
    if (largest_size < file_size(argv[i])) {
      largest_size = file_size(argv[i]);
    }
  }

  // Allocate memory for the array of file entries
  entries = malloc(sizeof(file_entry) * argc);
  if (entries == NULL) {
    printf("Error: failed to allocate memory for file entries\n");
    return;
  }

  // Initialize each entry with the file path and metadata
  for (int i = 0; i < argc; i++) {
    entries[i].path = strdup(argv[i]);
    if (!entries[i].path) {
      printf("Error: failed to allocate memory for file path\n");
      return;
    }
    if (stat(argv[i], &entries[i].metadata)) {
      printf("Error: failed to retrieve metadata for file %s\n", argv[i]);
      free(entries[i].path);
      continue;
    }
  }

  // Print the total size of all files and the largest file
  printf("Total size of all files: %ld bytes\n", total_size);
  if (largest_size > 0) {
    printf("Largest file: %s, %ld bytes\n", entries[i].path, entries[i].metadata.st_size);
  }

  // Free memory for the array of file entries
  free(entries);
}

// Helper function to check if a file exists
int file_exists(const char *path) {
  struct stat buffer;
  return (stat(path, &buffer) == 0);
}

// Helper function to retrieve the size of a file in bytes
long file_size(const char *path) {
  struct stat buffer;
  if (stat(path, &buffer)) {
    return -1;
  }
  return buffer.st_size;
}
