int check_file_exist(const char* path) {
    struct stat buf;
    if (stat(path, &buf)) { // If stat() fails, return 0
        fprintf(stderr, "Failed to access file %s: %s\n", path, strerror(errno));
        return 0;
    }
    // Check for permission issues and log an error if any
