```
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <limits.h>

// Define a structure to hold an integer and its corresponding index in the array
struct record {
  int value;
  size_t index;
};

// Function to process a variable-sized list of integers provided via standard input
void process_input(size_t* num_records, struct record** records) {
  // Initialize memory for the array of records
  *num_records = 0;
  *records = NULL;

  // Read input from standard input until EOF is reached
  while (1) {
    int value;
    if (scanf("%d", &value) != 1) {
      break;
    }

    // If the array is not large enough to hold the next record, reallocate more memory
    if (*num_records >= *(records)) {
      size_t new_size = (*num_records + 1) * sizeof(struct record);
      struct record* new_records = realloc(*records, new_size);
      if (new_records == NULL) {
        // Handle allocation failure gracefully
        fprintf(stderr, "Error: failed to allocate memory for records\n");
        exit(EXIT_FAILURE);
      }
      *records = new_records;
    }

    // Store the value in the next available record
    (*records)[*num_records].value = value;
    (*records)[*num_records].index = *num_records;
    (*num_records)++;
  }
}

// Function to determine and print the largest integer within the array
void print_largest(struct record* records, size_t num_records) {
  if (num_records == 0) {
    return;
  }

  int largest = INT_MIN;
  for (size_t i = 0; i < num_records; i++) {
    if (records[i].value > largest) {
      largest = records[i].value;
    }
  }
  printf("The largest integer in the array is %d\n", largest);
}

int main(void) {
  // Initialize random number generator with a custom seed for consistent results
  srand(time(NULL));

  // Declare variables to hold the input and output of the function
  size_t num_records;
  struct record* records;

  // Call the processing function to read input from standard input and store it in an array of records
  process_input(&num_records, &records);

  // Print the largest integer within the array
  print_largest(records, num_records);

  // Clean up memory allocated for the array of records
  free(records);

