// Define a structure to store an integer value and its index in the array
typedef struct {
    int val;
    size_t idx;
} record;

// Function to process a variable-length list of integers received from a network stream
record* process_ints(size_t num_ints, int min_val, int max_val) {
    // Allocate memory for an array of `record` structures
    record* records = (record*)malloc(sizeof(record) * num_ints);
    if (!records) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Initialize each record with a random integer value within the specified range
    for (size_t i = 0; i < num_ints; i++) {
        records[i].val = (rand() % (max_val - min_val + 1)) + min_val;
        records[i].idx = i;
    }

    // Sort the array of records in ascending order based on their integer values
    qsort(records, num_ints, sizeof(record), compare_records);

    // Find and print the largest integer among all the records
    size_t max_idx = 0;
    for (size_t i = 1; i < num_ints; i++) {
        if (records[i].val > records[max_idx].val) {
            max_idx = i;
        }
    }
    printf("Largest integer: %d\n", records[max_idx].val);

    // Free the memory allocated for the `record` structures
    free(records);

    return NULL;
}

// Helper function to generate random values within a specified range
int rand_range(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Comparison function for sorting the `record` structures based on their integer values
int compare_records(const void* a, const void* b) {
    record* rec1 = (record*)a;
    record* rec2 = (record*)b;
    return rec1->val - rec2->val;
}
