            fgets(line, MAX_LINE_LENGTH, stdin);
            int j;
            for (j = 0; j < numTags; j++) {
                line = malloc(sizeof(char) * MAX_LINE_LENGTH);
                if (line == NULL) {
                    perror("malloc");
                    return docs;
                }
                fgets(line, MAX_LINE_LENGTH, stdin);
                char* tag = strdup(line);
                free(line);
                docs[i].metadata.tags[j] = tag;
            }
        }
    }

    // Close file stream if opened
    if (filename != NULL) {
        fclose(fp);
    }

    return docs;
}

// Function to search for documents by keyword in content and sort them by relevance
void searchDocuments(Document* docs, int numDocs, char* keyword) {
    // Initialize variables for memory management
    Document* results = malloc(sizeof(Document) * MAX_RESULTS);
    int i;
    int j;
    int count = 0;

    // Search for documents containing the keyword in content and sort them by relevance
    for (i = 0; i < numDocs; i++) {
        if (strstr(docs[i].content, keyword) != NULL) {
            results[count] = docs[i];
            count++;
        }
    }

    // Sort the search results by relevance
    for (j = 0; j < count - 1; j++) {
        int largest = j;
        for (int k = j + 1; k < count; k++) {
            if (strlen(results[k].content) > strlen(results[largest].content)) {
                largest = k;
            }
        }
        Document temp = results[j];
        results[j] = results[largest];
        results[largest] = temp;
    }

    // Print the search results
    for (i = 0; i < count; i++) {
        printf("%d. Title: %s\n", i + 1, results[i].title);
        printf("Content: %s\n", results[i].content);
        printf("Metadata:\n");
        printf("Author: %s\n", results[i].metadata.author);
        printf("Date: %s\n", ctime(&results[i].metadata.date));
        int j;
        for (j = 0; j < numTags; j++) {
            if (strcmp(results[i].metadata.tags[j], "") != 0) {
                printf("Tag: %s\n", results[i].metadata.tags[j]);
            }
        }
    }

    // Free memory allocated for search results
    free(results);
}

// Function to initialize the document structure
void initDocuments(Document* docs, int numDocs) {
    int i;
    for (i = 0; i < numDocs; i++) {
        docs[i].title = NULL;
        docs[i].content = NULL;
        docs[i].metadata.author = NULL;
        docs[i].metadata.date = 0;
        docs[i].metadata.tags = malloc(sizeof(char*) * MAX_TAGS);
    }
}

// Function to extract content from documents
void extractContent(Document* docs, int numDocs) {
    int i;
    for (i = 0; i < numDocs; i++) {
        docs[i].content = strdup(docs[i].title);
    }
}

// Function to free memory allocated for document structure
void freeDocuments(Document* docs, int numDocs) {
    int i;
    for (i = 0; i < numDocs; i++) {
        if (docs[i].title != NULL) {
            free(docs[i].title);
        }
        if (docs[i].content != NULL) {
            free(docs[i].content);
        }
        if (docs[i].metadata.author != NULL) {
            free(docs[i].metadata.author);
        }
        if (docs[i].metadata.tags != NULL) {
            int j;
            for (j = 0; j < MAX_TAGS; j++) {
                if (docs[i].metadata.tags[j] != NULL) {
                    free(docs[i].metadata.tags[j]);
                }
            }
        }
    }
}
