// Structures to represent each record
typedef struct {
    double value;
    char string[100];
} Record;

typedef struct {
    double value;
    char string[100];
    Record *next;
} Element;

// Function to dynamically allocate memory for records
Record* alloc_record(const char *string) {
    Record *record = malloc(sizeof(Record));
    if (record == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    strncpy(record->string, string, 100);
    record->string[99] = '\0'; // Ensure null-termination
    return record;
}

// Function to dynamically allocate memory for elements
Element* alloc_element(const char *string) {
    Element *element = malloc(sizeof(Element));
    if (element == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    strncpy(element->string, string, 100);
    element->string[99] = '\0'; // Ensure null-termination
    element->next = NULL;
    return element;
}

// Function to dynamically allocate memory for a linked list of elements
Element* alloc_elements(const char *string) {
    Element *head = malloc(sizeof(Element));
    if (head == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    strncpy(head->string, string, 100);
    head->string[99] = '\0'; // Ensure null-termination
    head->next = NULL;
    return head;
}

// Function to free memory for records and elements
void free_record(Record *record) {
    free(record);
}

void free_element(Element *element) {
    free(element);
}

void free_elements(Element *head) {
    Element *current = head;
    while (current != NULL) {
        Element *next = current->next;
        free_element(current);
        current = next;
    }
}

// Function to read records from a file and process them
void read_records(const char *filepath, int max_records) {
    FILE *fp = fopen(filepath, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file\n");
        return;
    }

    // Initialize variables to track progress and memory usage
    int num_records = 0;
    int total_memory = 0;
    Record *head = NULL;
    Element *current = NULL;

    // Read records from file and process them
    while (num_records < max_records) {
        // Allocate memory for a new record
        Record *record = alloc_record(NULL);
        if (record == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            break;
        }
        total_memory += sizeof(Record);
        num_records++;

        // Read double value from file and store in record
        fscanf(fp, "%lf", &record->value);
        if (feof(fp)) {
            break;
        }

        // Allocate memory for a new element
        Element *element = alloc_element(NULL);
        if (element == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            free_record(record);
            break;
        }
        total_memory += sizeof(Element);

        // Read string value from file and store in element
        char buffer[100];
        fscanf(fp, "%s", buffer);
        if (feof(fp)) {
            free_element(element);
            free_record(record);
            break;
        }
        strncpy(element->string, buffer, 100);
        element->string[99] = '\0'; // Ensure null-termination

        // Allocate memory for a new linked list of elements
        if (head == NULL) {
            head = alloc_elements(buffer);
            if (head == NULL) {
                fprintf(stderr, "Memory allocation failed\n");
                free_element(element);
                free_record(record);
                break;
            }
        } else {
            current->next = alloc_elements(buffer);
            if (current->next == NULL) {
                fprintf(stderr, "Memory allocation failed\n");
                free_elements(head);
                free_element(element);
                free_record(record);
                break;
            }
        }
        current = head;
        total_memory += sizeof(Element);

        // Add record and element to linked list
        current->next->value = record->value;
        current->next->string[99] = '\0'; // Ensure null-termination
        current->next->next = NULL;
    }

    // Flush in-memory data to disk periodically
    pthread_mutex_lock(&lock);
    if (num_records > 0) {
        flush_data(head);
    }
    pthread_mutex_unlock(&lock);

    // Release memory for records and elements
    free_elements(head);

    // Close file stream
    fclose(fp);
}

// Function to flush in-memory data to disk
void flush_data(Element *head) {
    FILE *fp = fopen("file.txt", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file\n");
        return;
    }

    // Write data to file and free memory for records and elements
    while (head != NULL) {
        fprintf(fp, "%lf,%s", head->value, head->string);
        if (head->next != NULL) {
            fprintf(fp, "\n");
        }
        Element *next = head->next;
        free_elements(head);
        head = next;
    }

    // Close file stream
    fclose(fp);
}
