// Custom memory pool for efficient memory management
struct mempool {
    size_t capacity;
    size_t used;
    void **free_list;
};

void init_mempool(struct mempool *pool, size_t capacity) {
    pool->capacity = capacity;
    pool->used = 0;
    pool->free_list = (void**)malloc(sizeof(void*) * capacity);
}

void* alloc_mem(struct mempool *pool) {
    if (pool->used == pool->capacity) {
        return NULL;
    }
    void *ret = pool->free_list[pool->used];
    pool->used++;
    return ret;
}

void free_mem(struct mempool *pool, void *ptr) {
    pool->free_list[--pool->used] = ptr;
}

