            free_mem(&pool, records);
            free_mem(&pool, keys);
            free_mem(&pool, offsets);
            return -1;
        }
    }

    // Initialize keys and offsets with random values within specified range
    for (int i = 0; i < num_threads; i++) {
        records[i].key = rand() % 100;
        offsets[i] = rand() % (strlen(strings[i]) - 2);
