// Define a function to manage memory for multiple dynamic data structures
Record* manageMemory(int numRecords, int numOffsetValues, int seed) {
    // Allocate memory for the arrays
    int* keys = malloc(numRecords * sizeof(int));
    long* offsets = malloc(numOffsetValues * sizeof(long));

    // Initialize an array of 'record' structures
    Record* records = malloc(numRecords * sizeof(Record));

    // Set a random seed for pseudo-random number generation
    srand(seed);

    // Fill the arrays with random values
    for (int i = 0; i < numRecords; i++) {
        keys[i] = rand() % 100;
        offsets[i] = rand() % 10000;

        records[i].key = keys[i];
        records[i].offset = offsets[i];
    }

    // Sort the records based on their 'int' key values in ascending order
    qsort(records, numRecords, sizeof(Record), compareKeys);

    return records;
}

// Define a custom comparison function for sorting records by 'int' key value
int compareKeys(const void* record1, const void* record2) {
    Record* r1 = (Record*)record1;
    Record* r2 = (Record*)record2;

    if (r1->key < r2->key) {
        return -1;
    } else if (r1->key > r2->key) {
        return 1;
    } else {
        return 0;
    }
}
