// Structure to represent a record with either an integer or string value
struct record {
  void* value; // Either int or char*
};

// Function to allocate memory for an array of records
struct record** allocate_records(size_t num_records) {
  struct record** records = malloc(num_records * sizeof(struct record*));
  if (!records) {
    fprintf(stderr, "Error: Failed to allocate memory for records\n");
    return NULL;
  }
  memset(records, 0, num_records * sizeof(struct record*));
  return records;
}

// Function to initialize a record with random integer value within specified range
int initialize_record_with_random_integer(struct record* record, int min, int max) {
  if (max < min || max > INT_MAX || min < INT_MIN) {
    fprintf(stderr, "Error: Invalid range for random integer\n");
    return -1;
  }
  record->value = malloc(sizeof(int));
  if (!record->value) {
    fprintf(stderr, "Error: Failed to allocate memory for random integer value\n");
    return -1;
  }
  *((int*)record->value) = (rand() % (max - min + 1)) + min;
  return 0;
}

// Function to initialize a record with random string value of specified length
char* initialize_record_with_random_string(struct record* record, size_t length) {
  if (length > INT_MAX || length == 0) {
    fprintf(stderr, "Error: Invalid length for random string\n");
    return NULL;
  }
  record->value = malloc(sizeof(char) * (length + 1));
  if (!record->value) {
    fprintf(stderr, "Error: Failed to allocate memory for random string value\n");
    return NULL;
  }
  char* random_string = malloc(sizeof(char) * length);
  if (!random_string) {
    free(record->value);
    record->value = NULL;
    fprintf(stderr, "Error: Failed to allocate memory for random string value\n");
    return NULL;
  }
  memset(random_string, 0, length + 1);
  size_t i;
  for (i = 0; i < length; ++i) {
    int c = rand() % 26 + 'a'; // Generate a random lowercase letter between 'a' and 'z'
    *((char*)record->value + i) = c;
    *(random_string + i) = c;
  }
  return random_string;
}

// Function to free memory for an array of records
void free_records(struct record** records, size_t num_records) {
  if (!records || num_records == 0) {
    fprintf(stderr, "Error: Invalid input for free_records\n");
    return;
  }
  size_t i;
  for (i = 0; i < num_records; ++i) {
    if (records[i]) {
      void* value = records[i]->value;
      free(value);
      records[i] = NULL;
    }
  }
  free(records);
}

// Function to find and print the largest integer in an array of records
int find_largest_integer(struct record** records, size_t num_records) {
  if (!records || num_records == 0) {
    fprintf(stderr, "Error: Invalid input for find_largest_integer\n");
    return -1;
  }
  int largest = INT_MIN;
  size_t i;
  for (i = 0; i < num_records; ++i) {
    if (records[i]) {
      void* value = records[i]->value;
      if (value && *(int*)value > largest) {
        largest = *(int*)value;
      }
    }
  }
  printf("Largest integer: %d\n", largest);
  return 0;
}

// Function to find and print the longest string in an array of records
char* find_longest_string(struct record** records, size_t num_records) {
  if (!records || num_records == 0) {
    fprintf(stderr, "Error: Invalid input for find_longest_string\n");
    return NULL;
  }
  char* longest = NULL;
  size_t i;
  for (i = 0; i < num_records; ++i) {
    if (records[i]) {
      void* value = records[i]->value;
      if (value && strlen(*(char**)value) > strlen(longest)) {
        longest = *(char**)value;
      }
    }
  }
  printf("Longest string: %s\n", longest);
  return longest;
}

// Function to refresh fields in a dialog
void refresh_fields(struct record** records, size_t num_records, char* field_names[]) {
  if (!records || num_records == 0 || !field_names) {
    fprintf(stderr, "Error: Invalid input for refresh_fields\n");
    return;
  }
  size_t i;
  for (i = 0; i < num_records; ++i) {
    if (records[i]) {
      void* value = records[i]->value;
      char* field_name = NULL;
      size_t j;
      for (j = 0; j < strlen(field_names); ++j) {
        if (strcmp(*(char**)value, field_names[j]) == 0) {
          field_name = *(char**)value;
          break;
        }
      }
      if (field_name) {
        // Send message to parent window with the field name
        printf("Refreshing field: %s\n", field_name);
      }
    }
  }
}
