// Function to initialize and read the list of strings from a file or stdin
int read_strings(char *filepath, struct document **docs, int num_docs) {
    // Check if the file exists and is readable
    FILE *fp = fopen(filepath, "r");
    if (fp == NULL) {
        printf("Error: File %s does not exist or is not readable\n", filepath);
        return -1;
    }

    // Read the lines from the file and store them in an array of strings
    char **lines = malloc(num_docs * sizeof(char*));
    int i, line_count = 0;
    while (fscanf(fp, "%ms", &lines[line_count]) == 1) {
        line_count++;
    }

    // Initialize the documents and allocate memory for each string
    *docs = malloc(num_docs * sizeof(struct document));
    for (i = 0; i < num_docs; i++) {
        (*docs)[i].str = malloc((strlen(lines[i]) + 1) * sizeof(char));
        strcpy((*docs)[i].str, lines[i]);
    }

    // Free the memory used for storing the lines from the file
    free(lines);

    return line_count;
}

// Function to find and print the longest string in an array of documents
void print_longest_string(struct document *docs, int num_docs) {
    // Initialize the longest string and its length
    struct document longest = docs[0];
    int longest_len = strlen(longest.str);

    // Iterate over each document and compare the lengths of the strings
    for (int i = 1; i < num_docs; i++) {
        if (strlen(docs[i].str) > longest_len) {
            longest = docs[i];
            longest_len = strlen(longest.str);
        }
    }

    // Print the longest string
    printf("Longest string: %s\n", longest.str);
}

// Function to randomly generate a string within a specified length range
char* random_string(int min_length, int max_length) {
    char *str = malloc((max_length + 1) * sizeof(char));
    for (int i = 0; i < max_length; i++) {
        str[i] = 'a' + rand() % 26;
    }
    str[max_length] = '\0';
    return str;
}

// Function to set the value of each document's char* field to a randomly generated string within a specified length range
void generate_random_strings(struct document *docs, int num_docs, int min_length, int max_length) {
    for (int i = 0; i < num_docs; i++) {
        docs[i].str = random_string(min_length, max_length);
    }
}

// Function to handle errors during file I/O and memory allocation
void error_handler(const char *error_msg) {
    printf("Error: %s\n", error_msg);
    exit(EXIT_FAILURE);
}

int main() {
    // Set the options for line delimiters and file path
    char *filepath = "input.txt";
    char line_delimiter[] = "\n";
    int num_docs = 10;

    // Initialize the documents and read the list of strings from a file or stdin
    struct document *docs = NULL;
    int num_lines = read_strings(filepath, &docs, num_docs);
    if (num_lines == -1) {
        error_handler("Error reading input");
    }

    // Find and print the longest string in the array of documents
    printf("Longest string: %s\n", docs[0].str);

    // Set the value of each document's char* field to a randomly generated string within a specified length range
    generate_random_strings(docs, num_docs, 5, 10);

    // Free the memory used for storing the documents
    free(docs);

    return 0;
}
