// Define the record structure
typedef struct {
    union {
        int value;
        char *string;
    };
} Record;

// Define the initialization function
void init_array(Record **array, size_t length) {
    // Allocate memory for the array of records
    *array = (Record *)malloc(length * sizeof(Record));
    if (*array == NULL) {
        printf("Error: Failed to allocate memory for the array.\n");
        exit(1);
    }
}

// Define the random value generation function
void generate_random_values(Record **array, size_t length, int min, int max) {
    // Generate random values within the specified range
    srand(time(NULL));
    for (size_t i = 0; i < length; ++i) {
        Record *record = &(*array)[i];
        record->value = rand() % (max - min + 1) + min;
    }
}

// Define the filtering function
void filter_records(Record **array, size_t length, int filter) {
    // Filter records based on the specified criteria
    for (size_t i = 0; i < length; ++i) {
        Record *record = &(*array)[i];
        if (filter == 1 && record->value % 2 != 0) {
            (*array)[i] = NULL;
        } else if (filter == 2 && record->value % 3 != 0) {
            (*array)[i] = NULL;
        }
    }
}

// Define the helper function for finding the largest integer in the array
int find_largest_integer(Record **array, size_t length) {
    // Initialize a variable to store the largest value
    int largest = INT_MIN;
    // Iterate through the records and compare values
    for (size_t i = 0; i < length; ++i) {
        Record *record = &(*array)[i];
        if (record->value > largest) {
            largest = record->value;
        }
    }
    return largest;
}

// Define the helper function for finding the longest string in the array
int find_longest_string(Record **array, size_t length) {
    // Initialize a variable to store the longest value
    int longest = 0;
    // Iterate through the records and compare values
    for (size_t i = 0; i < length; ++i) {
        Record *record = &(*array)[i];
        if (strlen(record->string) > longest) {
            longest = strlen(record->string);
        }
    }
    return longest;
}

// Define the main function for the program
int main() {
    // Declare variables to store the array of records and its length
    Record *array;
    size_t length;

    // Prompt the user for input on the number of records, filtering criteria, and data type
    printf("Enter the number of records: ");
    scanf("%lu", &length);
    int filter = 0;
    while (filter != 1 && filter != 2) {
        printf("Enter a filtering criterion (1 - even numbers only, 2 - multiples of 3 only): ");
        scanf("%d", &filter);
    }

    // Initialize the array of records with the specified length and filtering criteria
    init_array(&array, length);
    generate_random_values(array, length, INT_MIN, INT_MAX);
    filter_records(array, length, filter);

    // Find the largest integer in the array or the longest string in the array
    int largest;
    if (filter == 1) {
        largest = find_largest_integer(array, length);
    } else if (filter == 2) {
        largest = find_longest_string(array, length);
    }

    // Print the result of the function call
    printf("The largest value in the array is: %d\n", largest);

    // Free the memory allocated for the array of records
    free(array);

    return 0;
}
