// Structure to represent a document
typedef struct {
    char* text;
} Document;

// Function to read a list of strings from standard input and initialize an array of documents
int read_documents(Document** documents, int num_docs) {
    // Allocate memory for the array of documents
    *documents = malloc(num_docs * sizeof(Document));
    if (*documents == NULL) {
        return -1;
    }

    // Initialize each document with a null string
    for (int i = 0; i < num_docs; ++i) {
        (*documents)[i].text = NULL;
    }

    // Read each string from standard input and allocate memory for it
    for (int i = 0; i < num_docs; ++i) {
        char* text = malloc(1024);
        if (text == NULL) {
            return -1;
        }

        // Read the string from standard input and validate its size
        int bytes_read = fscanf(stdin, "%s", text);
        if (bytes_read != 1) {
            free(text);
            return -1;
        }

        (*documents)[i].text = text;
    }

    // Return the number of documents successfully read
    return num_docs;
}

// Function to find and print the longest string in an array of documents
void print_longest_string(Document* documents, int num_docs) {
    // Find the longest string in the array of documents
    Document longest = {NULL};
    for (int i = 0; i < num_docs; ++i) {
        if (documents[i].text != NULL && strlen(documents[i].text) > strlen(longest.text)) {
            longest = documents[i];
        }
    }

    // Print the longest string
    if (longest.text != NULL) {
        printf("Longest string: %s\n", longest.text);
    } else {
        printf("No strings found.\n");
    }
}

// Function to manage a dynamic list of tasks, each associated with a priority level, due dates, and resource requirements
typedef struct {
    int id;
    char* name;
    char* description;
    int priority;
    int due_date;
    int resource_requirements;
} Task;

// Function to load task data from a JSON file and return the total number of tasks
int read_tasks(Task** tasks, int num_tasks) {
    // Allocate memory for the array of tasks
    *tasks = malloc(num_tasks * sizeof(Task));
    if (*tasks == NULL) {
        return -1;
    }

    // Initialize each task with default values
    for (int i = 0; i < num_tasks; ++i) {
        (*tasks)[i].id = i + 1;
        (*tasks)[i].name = NULL;
        (*tasks)[i].description = NULL;
        (*tasks)[i].priority = 0;
        (*tasks)[i].due_date = 0;
        (*tasks)[i].resource_requirements = 0;
    }

    // Read the JSON file and parse each task
    FILE* json_file = fopen("tasks.json", "r");
    if (json_file == NULL) {
        return -1;
    }

    int bytes_read = fscanf(json_file, "%s %d %d %d %d %d", (*tasks)[0].name, &(*tasks)[0].priority, &(*tasks)[0].due_date, &(*tasks)[0].resource_requirements);
    for (int i = 1; i < num_tasks && bytes_read == 6; ++i) {
        char name[128];
        int priority, due_date, resource_requirements;
        bytes_read = fscanf(json_file, "%s %d %d %d", name, &priority, &due_date, &resource_requirements);
        if (bytes_read == 4) {
            (*tasks)[i].name = strdup(name);
            (*tasks)[i].priority = priority;
            (*tasks)[i].due_date = due_date;
            (*tasks)[i].resource_requirements = resource_requirements;
        } else {
            break;
        }
    }

    // Close the JSON file and return the number of tasks successfully read
    fclose(json_file);
    return i - 1;
}

// Function to sort tasks based on priority levels and due dates before returning the count
int sort_tasks(Task* tasks, int num_tasks) {
    // Sort the tasks in descending order of priority levels and due dates
    for (int i = 0; i < num_tasks; ++i) {
        for (int j = i + 1; j < num_tasks; ++j) {
            if (tasks[i].priority > tasks[j].priority || (tasks[i].priority == tasks[j].priority && tasks[i].due_date > tasks[j].due_date)) {
                Task temp = tasks[i];
                tasks[i] = tasks[j];
                tasks[j] = temp;
            }
