    int key;
    double value;
} record;

// Initialize the memory for the records
void init_records(int num_records) {
    // Allocate memory for the records
    record* records = (record*)malloc(sizeof(record) * num_records);
    if (!records) {
        printf("Error: Could not allocate memory for records\n");
        exit(1);
    }

    // Initialize the offset values to 0
    for (int i = 0; i < num_records; i++) {
        records[i].offset = 0;
    }
}

// Generate random key-value pairs for each record
void generate_random_values(record* records, int num_records) {
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % 100;
        records[i].value = (double)(rand() % 100) / 100.0;
    }
}

// Concurrency control using semaphores
void concurrency_control(record* records, int num_records) {
    // Create a semaphore to manage access to the records
    sem_t* sem = sem_open("records", O_CREAT | O_EXCL, 0644, num_records);
    if (sem == SEM_FAILED) {
        perror("Error: Could not create semaphore");
        exit(1);
    }

    // Acquire the semaphore before accessing a record
    int i;
    for (i = 0; i < num_records; i++) {
        if (sem_wait(sem) == -1) {
            perror("Error: Could not acquire semaphore");
            exit(1);
        }

        // Access the record and release the semaphore afterwards
        records[i].offset++;
        sem_post(sem);
    }
}

// Memory management using mmap
void memory_management(record* records, int num_records) {
    // Create a shared memory map for the records
    void* mem = mmap(NULL, sizeof(record) * num_records, PROT_READ | PROT_WRITE, MAP_SHARED, -1, 0);
    if (mem == MAP_FAILED) {
        perror("Error: Could not create shared memory map");
        exit(1);
    }

    // Write the records to the shared memory map
    for (int i = 0; i < num_records; i++) {
        memcpy(mem + i * sizeof(record), &records[i], sizeof(record));
    }
}

// Main function that initializes and generates random values for the records
void main(int argc, char** argv) {
    // Check if the number of arguments is valid
    if (argc != 2) {
        printf("Usage: %s <number_of_records>\n", argv[0]);
        exit(1);
    }

    // Convert the input argument to an integer
