    if (num_records <= 0) {
        printf("Error: Invalid number of records\n");
        exit(1);
    }

    // Initialize the memory for the records and generate random key-value pairs
    init_records(num_records);
    generate_random_values((record*)malloc(sizeof(record) * num_records), num_records);

    // Concurrency control using semaphores
    concurrency_control((record*)malloc(sizeof(record) * num_records), num_records);

    // Memory management using mmap
    memory_management((record*)malloc(sizeof(record) * num_records), num_records);
}
