// Define a function to perform DNS resolution for a given hostname
int resolve_dns(char* hostname, u_char* ip_address) {
    // Initialize variables
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    // Perform DNS resolution using getaddrinfo()
    int error = getaddrinfo(hostname, NULL, &hints, &res);
    if (error != 0) {
        fprintf(stderr, "DNS resolution failed: %s\n", gai_strerror(error));
        return -1;
    }

    // Convert the IP address to a string using inet_ntop()
    char* ip_string = inet_ntop(AF_INET, res->ai_addr->sa_data, NULL, 0);
    if (ip_string == NULL) {
        fprintf(stderr, "inet_ntop() failed: %s\n", strerror(errno));
        freeaddrinfo(res);
        return -1;
    }

    // Copy the IP address to the output buffer
    memcpy(ip_address, ip_string, strlen(ip_string));

    // Free resources and return success
    freeaddrinfo(res);
    return 0;
}

