    while ((read = getline(&line, &len, config_file)) != -1) {
        // Skip blank lines and comments
        if (strlen(line) == 0 || line[0] == '#') continue;

        // Extract the hostname and weight from the line
        char* token = strtok(line, " \t");
        char* hostname = token;
        int weight = atoi(token);

        // Allocate memory for the hostname and weight
        struct HostWeight* new_hostweight = malloc(sizeof(struct HostWeight));
        if (new_hostweight == NULL) {
            perror("malloc() failed");
            fclose(config_file);
            return -1;
        }

        // Copy the hostname and weight to the struct
        new_hostweight->hostname = strdup(hostname);
        new_hostweight->weight = weight;

        // Add the hostname and weight to the list of hosts
        *hostweights = realloc(*hostweights, sizeof(struct HostWeight*) * (*hostweights + 1));
        if (*hostweights == NULL) {
            perror("realloc() failed");
            fclose(config_file);
            return -1;
        }
        (*hostweights)[*hostweights - 1] = new_hostweight;
