// Define a function to compute the weighted average of two fields and append it to the end of each hostname's entry
int compute_weighted_average(struct HostWeight* hostweights, int num_hostweights) {
    // Initialize variables
    int total_weight = 0;
    int average = 0;

    // Compute the total weight of all hosts
    for (int i = 0; i < num_hostweights; i++) {
        total_weight += hostweights[i]->weight;
    }

    // If the number of fields is even, compute the average of the last two fields
    if (total_weight % 2 == 0) {
        int field1 = hostweights[num_hostweights - 2]->weight;
        int field2 = hostweights[num_hostweights - 1]->weight;
        average = (field1 + field2) / 2;
    } else { // Otherwise, use the last field and zero as the average
        int field1 = hostweights[num_hostweights - 1]->weight;
        average = field1;
    }

    // Append the average to each hostname's entry
    for (int i = 0; i < num_hostweights; i++) {
        char* new_entry = malloc(sizeof(char) * (strlen(hostweights[i]->hostname) + 1));
        sprintf(new_entry, "%s,%d", hostweights[i]->hostname, average);
        hostweights[i]->hostname = new_entry;
    }
}

