int getWeatherData(struct sensorData *sensor_data, int num_sensors) {
    // Initialize variables
    json_object *root = NULL;
    json_object *sensor_array = NULL;
    int i = 0;
    int j = 0;
    int k = 0;
    int ret_val = -1;

    // Retrieve JSON data from weather monitoring API
    root = json_tokener_parse(json_object_get_string(json_object_new_string("https://api.openweathermap.org/data/2.5/group?id=city1,city2")));
    if (root) {
        // Get array of sensors from JSON data
        sensor_array = json_object_get_array(json_object_get_object(root, "list"));
        if (sensor_array) {
            // Loop through each sensor in the array and extract its data
            for (i = 0; i < num_sensors; i++) {
                json_object *sensor = json_object_array_get_idx(sensor_array, i);
                if (sensor) {
                    // Extract temperature reading from JSON object
                    json_object *temperature_obj = json_object_object_get(sensor, "main");
                    if (temperature_obj) {
                        double temperature = json_object_get_double(temperature_obj);
                        sensor_data[i].temperature = temperature;
                    } else {
                        // Return error code if temperature reading is not found or invalid
                        ret_val = EINVAL;
                        break;
                    }

                    // Extract pressure measurement from JSON object
                    json_object *pressure_obj = json_object_object_get(sensor, "pressure");
                    if (pressure_obj) {
                        float pressure = json_object_get_float(pressure_obj);
                        sensor_data[i].pressure = pressure;
                    } else {
                        // Return error code if pressure reading is not found or invalid
                        ret_val = EINVAL;
                        break;
                    }

                    // Extract descriptor from JSON object
                    json_object *descriptor_obj = json_object_object_get(sensor, "description");
                    if (descriptor_obj) {
                        const char *descriptor = json_object_get_string(descriptor_obj);
                        strncpy(sensor_data[i].descriptor, descriptor, 256);
                    } else {
                        // Return error code if descriptor is not found or invalid
                        ret_val = EINVAL;
                        break;
                    }
                } else {
                    // Return error code if sensor object is not found or invalid
                    ret_val = ENOENT;
                    break;
                }
            }
        } else {
            // Return error code if sensor array is not found in JSON data
            ret_val = ENODATA;
        }
    } else {
        // Return error code if JSON parsing failed
        ret_val = EINVAL;
    }

    return ret_val;
}

int main(void) {
    struct sensorData *sensor_data = NULL;
    int num_sensors = 5;
    int i = 0;

    // Dynamically allocate memory for array of 'struct sensorData' structures
    if ((sensor_data = malloc(sizeof(struct sensorData) * num_sensors)) == NULL) {
        printf("Memory allocation failed\n");
        return -1;
    }

    // Get weather data from external API
    int ret_val = getWeatherData(sensor_data, num_sensors);
    if (ret_val == 0) {
        // Print sensor data to console
        for (i = 0; i < num_sensors; i++) {
            printf("Sensor %d: Temperature = %.2f C, Pressure = %.1f hPa, Descriptor = %s\n",
                   i + 1, sensor_data[i].temperature, sensor_data[i].pressure, sensor_data[i].descriptor);
        }
    } else {
        printf("Error: %d\n", ret_val);
    }

    free(sensor_data);
    return 0;
}']

