// Define the maximum memory limit for this function
#define MAX_MEMORY (10 * 1024 * 1024) // 10 MB

typedef struct record {
    int key;
    double timestamp;
    char* string;
} Record;

int initializeRecords(size_t numKeys, size_t offsetLength, size_t stringLengthMax, char** logBuffer) {
    // Calculate the total memory required for all records
    size_t totalMemory = sizeof(Record) * numKeys + sizeof(long) * offsetLength + sizeof(char) * stringLengthMax;

    if (totalMemory > MAX_MEMORY) {
        fprintf(stderr, "Error: Total memory required exceeds maximum limit of %d bytes\n", MAX_MEMORY);
        return -1;
    }

    // Allocate memory for the record array
    Record* records = malloc(totalMemory);
    if (records == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for %d records\n", numKeys);
        return -1;
    }

    // Allocate memory for the offset array
    long* offsets = malloc(sizeof(long) * offsetLength);
    if (offsets == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for %d offset values\n", offsetLength);
        free(records);
        return -1;
    }

    // Initialize the record array and populate it with random data
    srand(time(NULL));
    for (size_t i = 0; i < numKeys; ++i) {
        records[i].key = rand() % 100;
        records[i].timestamp = time(NULL);
        offsets[i] = rand() % stringLengthMax;
        records[i].string = malloc(offsets[i]);
        if (records[i].string == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for string of length %d\n", offsets[i]);
            free(records);
            free(offsets);
            return -1;
        }
    }

    // Free the offset array and the record array
    free(offsets);
    free(records);

    // Return the number of initialized records and a pointer to the log message buffer
    return numKeys;
}

int main() {
    char* logBuffer = malloc(1024);
    if (logBuffer == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for log buffer\n");
        return -1;
    }

    // Initialize 10 records with random data
    int numRecords = initializeRecords(10, 5, 20, logBuffer);
    if (numRecords < 0) {
        fprintf(stderr, "Error: Failed to initialize records\n");
        return -1;
    }

    // Print the log message buffer
    printf("%s", logBuffer);

    // Free the log message buffer
    free(logBuffer);

    return 0;
}']

