#include <stdlib.h>
#include <stdio.h>
#include <stdbool.h>
#include <string.h>
#include <limits.h>

#define MAX_RECORDS 1000
#define MIN_VALUE -1000
#define MAX_VALUE 1000

// Data structure to store a record
typedef struct {
    long offset;
    int key;
    int value;
} Record;

// Hash table for efficient key-to-record mapping
struct hash_table {
    int size;
    int count;
    Record** records;
};

// Initialize a new hash table with the given size
struct hash_table* init_hash_table(int size) {
    struct hash_table* table = (struct hash_table*)malloc(sizeof(struct hash_table));
    if (!table) {
        fprintf(stderr, "Failed to allocate memory for hash table\n");
        return NULL;
    }

    table->size = size;
    table->count = 0;
    table->records = (Record**)malloc(sizeof(Record*) * size);
    if (!table->records) {
        fprintf(stderr, "Failed to allocate memory for hash table records\n");
        free(table);
        return NULL;
    }

    return table;
}

// Resize the hash table if necessary
void resize_hash_table(struct hash_table* table) {
    int new_size = table->size * 2;
    Record** new_records = (Record**)malloc(sizeof(Record*) * new_size);
    if (!new_records) {
        fprintf(stderr, "Failed to allocate memory for resized hash table\n");
        return;
    }

    memcpy(new_records, table->records, sizeof(Record*) * table->count);
    free(table->records);
    table->records = new_records;
    table->size = new_size;
}

// Add a record to the hash table and update its mapping
void add_record(struct hash_table* table, Record* record) {
    int index = record->key % table->size;
    if (table->records[index] != NULL) {
        resize_hash_table(table);
        index = record->key % table->size;
    }

    table->count++;
    table->records[index] = record;
}

// Look up a record in the hash table by its key
Record* lookup_record(struct hash_table* table, int key) {
    int index = key % table->size;
    if (table->records[index] == NULL || table->records[index]->key != key) {
        return NULL;
    }

    return table->records[index];
}

// Randomly initialize a record's value within the given range
int random_value(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Initialize an array of 'record' structures with the given sizes
Record** init_records(int num_records, int num_keys) {
    Record** records = (Record**)malloc(sizeof(Record*) * num_records);
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for record array\n");
        return NULL;
    }

    for (int i = 0; i < num_records; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        if (!record) {
            fprintf(stderr, "Failed to allocate memory for record %d\n", i);
            free(records);
            return NULL;
        }

        // Initialize the offset and key values
        record->offset = 0;
        record->key = i + 1;

        // Randomly initialize the value within the given range
        int value = random_value(MIN_VALUE, MAX_VALUE);
        record->value = value;

        records[i] = record;
    }

    return records;
}

// Free an array of 'record' structures
void free_records(Record** records) {
    for (int i = 0; i < num_records; i++) {
        if (records[i]) {
            free(records[i]);
        }
    }
}

// Function to manage memory allocation and initialization of an array of 'record' structures
void init_memory(int num_records, int num_keys) {
    // Initialize a hash table for efficient key-to-record mapping
    struct hash_table* table = init_hash_table(num_records);
    if (!table) {
        fprintf(stderr, "Failed to initialize hash table\n");
        return;
    }

    // Allocate memory for the 'long' offsets and 'int' keys
    long* offsets = (long*)malloc(sizeof(long) * num_records);
    int* keys = (int*)malloc(sizeof(int) * num_keys);
    if (!offsets || !keys) {
        fprintf(stderr, "Failed to allocate memory for offset and key arrays\n");
        free_hash_table(table);
        return;
    }

    // Initialize the offsets and keys
    for (int i = 0; i < num_records; i++) {
        offsets[i] = 0;
    }

    for (int i = 0; i < num_keys; i++) {
        keys[i] = i + 1;
    }

    // Initialize the 'record' structures and add them to the hash table
    Record** records = init_records(num_records, num_keys);
    if (!records) {
        fprintf(stderr, "Failed to initialize record array\n");
        free(offsets);
        free(keys);
        free_hash_table(table);
        return;
    }

    for (int i = 0; i < num_records; i++) {
        add_record(table, records[i]);
    }

    // Randomly initialize the 'value' fields within the given range
    for (int i = 0; i < num_keys; i++) {
        int key = keys[i];
        Record* record = lookup_record(table, key);
        if (!record) {
            fprintf(stderr, "Failed to find record for key %d\n", key);
            continue;
        }

        int value = random_value(MIN_VALUE, MAX_VALUE);
        record->value = value;
    }

    // Correctly set the pointers to reference the corresponding offsets and keys
    for (int i = 0; i < num_records; i++) {
        Record* record = records[i];
        int key = record->key;
        Record* prev = lookup_record(table, key - 1);
        if (!prev) {
            fprintf(stderr, "Failed to find previous record for key %d\n", key);
            continue;
        }

        // Handle potential misalignment issues when setting the offset and key pointers
        int offset = prev->offset + sizeof(int);
        if (offset >= MAX_OFFSET) {
            fprintf(stderr, "Offset exceeds maximum value\n");
            continue;
        }

        record->offset = offset;
    }

    // Verify the integrity of the data structures after initialization
    for (int i = 0; i < num_records; i++) {
        Record* record = records[i];
        int key = record->key;
        Record* prev = lookup_record(table, key - 1);
        if (!prev) {
            fprintf(stderr, "Failed to find previous record for key %d\n", key);
            continue;
        }

        // Verify the pointer references and consistent key-value mappings
        if (record->offset != prev->offset + sizeof(int)) {
            fprintf(stderr, "Offset mismatch for record with key %d\n", key);
            continue;
        }

        if (record->key != i + 1) {
            fprintf(stderr, "Key mismatch for record with offset %ld\n", record->offset);
            continue;
        }
    }
}

int main() {
    init_memory(MAX_RECORDS, MAX_KEYS);
    return 0;
}
