        }
    }

    // Periodically flush the log buffer to a persistent storage system
    time_t last_flush = time(NULL);
    size_t current_mem = 0;
    while (current_mem < max_mem) {
        if (difftime(time(NULL), last_flush) >= 60 * 10 /* 10 minutes */) {
            // Flush the log buffer to a persistent storage system
            current_mem = 0;
            for (size_t i = 0; i < num_messages; i++) {
