    while (num_records < max_records && total_memory <= max_memory) {
        // Allocate memory for a new record
        try {
            offset_array = new long[max_records];
            key_array = new int[max_records];
            record_array = new record[max_records];
        } catch (std::bad_alloc& e) {
            // Handle memory allocation failure
            logging_available ? logger.log("Memory allocation failed: " + std::string(e.what())) : 0;
            memory_allocation_failed = true;
