// Function to add a task to the list
void add_task(TaskList *list, struct Task task) {
    // Check if the list is full
    if (list->num_tasks == list->capacity) {
        // Double the capacity of the list
        list->capacity *= 2;
        // Reallocate memory for the tasks array
        list->tasks = realloc(list->tasks, list->capacity * sizeof(struct Task));
    }
    // Add the task to the end of the list
    list->tasks[list->num_tasks++] = task;
}

// Function to update a task in the list
void update_task(TaskList *list, int index, struct Task task) {
    // Check if the index is valid
    if (index >= 0 && index < list->num_tasks) {
        // Update the task at the specified index
        list->tasks[index] = task;
    }
}

// Function to delete a task from the list
void delete_task(TaskList *list, int index) {
    // Check if the index is valid
    if (index >= 0 && index < list->num_tasks) {
        // Shift all tasks after the deleted task one position to the left
        for (int i = index; i < list->num_tasks - 1; i++) {
            list->tasks[i] = list->tasks[i + 1];
        }
        // Decrement the number of tasks
        list->num_tasks--;
