    }

    Entity *max_entity = &coll->entities[0];
    double max_double_value = -INFINITY;
    int max_string_length = 0;
    double max_distance_from_origin = 0;

    for (int i = 0; i < coll->num_entities; ++i) {
        Entity *entity = &coll->entities[i];
        if (entity->type == DOUBLE && entity->data.double_value > max_double_value) {
