            max_entity = entity;
        } else if (entity->type == STRING && entity->data.string_value != NULL && strlen(entity->data.string_value) > max_string_length) {
            max_string_length = strlen(entity->data.string_value);
            max_entity = entity;
        } else if (entity->type == POINT && hypot(entity->data.point.x, entity->data.point.y) > max_distance_from_origin) {
            max_distance_from_origin = hypot(entity->data.point.x, entity->data.point.y);
            max_entity = entity;
        }
    }

