void process_input(Record **records, size_t *num_records) {
    char buffer[BUFSIZ];
    int total_ints = 0;

    // Read the input from standard input in a loop
    while (fgets(buffer, BUFSIZ, stdin)) {
        // Tokenize the input into individual integers
        char *token = strtok(buffer, " ");
        while (token != NULL) {
            int val = atoi(token);
            if (*num_records < total_ints + 1) {
                // Reallocate memory for the records array if necessary
                *records = (Record *)realloc(*records, ((*num_records) * 2) * sizeof(Record));
                if (*records == NULL) {
                    fprintf(stderr, "Error: unable to reallocate memory for records\n");
                    return;
                }
            }
            // Store the integer in the current record
            (*records)[total_ints].value = val;
            total_ints++;

            // Get the next token
            token = strtok(NULL, " ");
        }
    }

    // Update the number of records to reflect the total number of integers processed
    *num_records = total_ints;
}

