void init_records(Record* records, size_t batch_size) {
    // Allocate memory for the records array
    records = (Record*) malloc(batch_size * sizeof(Record));

    // Initialize each record in the array with a default value of 0
    for (int i = 0; i < batch_size; i++) {
        records[i].value = 0;
    }
}

// Define the function to generate random values for the records
void gen_random(Record* records, size_t batch_size) {
    // Generate a random number between 1 and 100 for each record in the array
    srand(time(NULL));
    for (int i = 0; i < batch_size; i++) {
        records[i].value = rand() % 100 + 1;
    }
}

// Define the function to track the total number of integers processed
void update_counter(Record* records, size_t batch_size) {
    // Increment the counter for each record in the array
    for (int i = 0; i < batch_size; i++) {
        records[i].value++;
    }
}

// Define the function to identify and print the largest integer in the array
void find_largest(Record* records, size_t batch_size) {
    int largest = 0;
    for (int i = 0; i < batch_size; i++) {
        if (records[i].value > largest) {
            largest = records[i].value;
        }
    }
    printf("Largest integer: %d\n", largest);
}

