// Define the function to handle input in batches and track the total number of integers processed
void process_batch(Record* records, size_t batch_size) {
    // Read a line from standard input
    char* line = (char*) malloc(1024);
    if (!fgets(line, 1024, stdin)) {
        printf("Error: failed to read input\n");
        return;
    }

    // Split the line into individual integers
    char* token = strtok(line, " ");
    while (token != NULL) {
        int value = atoi(token);
        records[value].value++;
        token = strtok(NULL, " ");
    }
}

