    if (ext == NULL || !strcmp(ext, ".txt")) {
        // Process the input in text format
        process_batch(records, batch_size);
    } else if (!strcmp(ext, ".bin")) {
        // Process the input in binary format
        process_batch(records, batch_size);
    }
}

