    // Initialize the number of products to the minimum quantity
    catalog->num_products = min_quantity;
}

// Function to update a product in the catalog
void updateProduct(storeCatalog_t* catalog, size_t index, const char* name, int quantity, double price) {
    // Check if the index is within bounds
    if (index >= catalog->num_products) {
        fprintf(stderr, "Error: invalid product index %lu\n", (unsigned long)index);
        return;
    }

    // Update the name and quantity of the product
    catalog->products[index]->name = name;
    catalog->products[index]->quantity = quantity;

    // Update the price of the product
    catalog->products[index]->price = price;
}

// Function to add a new product to the catalog
void addProduct(storeCatalog_t* catalog, const char* name, int quantity, double price) {
    // Check if there is enough memory available to allocate a new product structure
    if (catalog->num_products >= SIZE_MAX / sizeof(product_t)) {
        fprintf(stderr, "Error: out of memory\n");
        return;
    }

    // Allocate memory for the new product structure
    catalog->products = realloc(catalog->products, (catalog->num_products + 1) * sizeof(product_t*));
    if (!catalog->products) {
        fprintf(stderr, "Error: failed to allocate memory for new product\n");
        return;
    }

    // Set the name, quantity, and price of the new product
    catalog->products[catalog->num_products] = malloc(sizeof(product_t));
    if (!catalog->products[catalog->num_products]) {
        fprintf(stderr, "Error: failed to allocate memory for new product\n");
        return;
    }
    catalog->products[catalog->num_products]->name = name;
    catalog->products[catalog->num_products]->quantity = quantity;
    catalog->products[catalog->num_products]->price = price;

    // Increment the number of products in the catalog
    catalog->num_products++;
}

// Function to remove a product from the catalog
void removeProduct(storeCatalog_t* catalog, size_t index) {
    // Check if the index is within bounds
    if (index >= catalog->num_products) {
        fprintf(stderr, "Error: invalid product index %lu\n", (unsigned long)index);
        return;
    }

    // Decrement the number of products in the catalog
    catalog->num_products--;

    // Free the memory allocated for the removed product structure
    free(catalog->products[index]);
    catalog->products[index] = NULL;

    // Shift the remaining products down one index
    for (size_t i = index; i < catalog->num_products; i++) {
        catalog->products[i] = catalog->products[i + 1];
    }
}

// Function to retrieve a product from the catalog by name
product_t* getProductByName(storeCatalog_t* catalog, const char* name) {
    // Iterate over the products in the catalog until the specified name is found
    for (size_t i = 0; i < catalog->num_products; i++) {
        if (strcmp(catalog->products[i]->name, name) == 0) {
            return catalog->products[i];
        }
    }
    return NULL;
}

// Function to retrieve a product from the catalog by index
product_t* getProductByIndex(storeCatalog_t* catalog, size_t index) {
    // Check if the index is within bounds
    if (index >= catalog->num_products) {
        fprintf(stderr, "Error: invalid product index %lu\n", (unsigned long)index);
        return NULL;
    }

    return catalog->products[index];
}
