// Define the structure for a task
typedef struct {
    char* command;
    int priority_level;
    pid_t process_id;
} task_t;

// Define the list of tasks
static task_t* tasks = NULL;

// Define the lock for concurrent access to the list of tasks
static pthread_mutex_t task_lock = PTHREAD_MUTEX_INITIALIZER;

// Define the condition variable for signaling when a new task is available
static pthread_cond_t task_available = PTHREAD_COND_INITIALIZER;

// Define the function to initialize the list of tasks
void init_tasks() {
    // Allocate memory for the list of tasks
    tasks = (task_t*) malloc(sizeof(task_t) * 10);
    if (!tasks) {
        perror("Failed to allocate memory for tasks");
        exit(EXIT_FAILURE);
    }
}

// Define the function to add a new task to the list
void add_task(char* command, int priority_level) {
    // Acquire the lock on the list of tasks
    pthread_mutex_lock(&task_lock);

    // Check if the list is full and needs to be resized
    if (num_tasks >= max_tasks) {
        // Double the size of the list
        max_tasks *= 2;
        tasks = realloc(tasks, sizeof(task_t) * max_tasks);
        if (!tasks) {
            perror("Failed to resize task list");
            exit(EXIT_FAILURE);
        }
    }

    // Add the new task to the end of the list
    tasks[num_tasks].command = command;
    tasks[num_tasks].priority_level = priority_level;
    tasks[num_tasks].process_id = 0;

    // Increment the number of tasks
    num_tasks++;

    // Signal that a new task is available
    pthread_cond_broadcast(&task_available);

    // Release the lock on the list of tasks
    pthread_mutex_unlock(&task_lock);
}

// Define the function to get the next task from the list
task_t* get_next_task() {
    // Acquire the lock on the list of tasks
    pthread_mutex_lock(&task_lock);

    // Wait for a new task to become available
    while (num_tasks == 0) {
        pthread_cond_wait(&task_available, &task_lock);
    }

    // Get the next task from the list and remove it
    task_t* task = tasks + (num_tasks - 1);
    num_tasks--;

    // Release the lock on the list of tasks
    pthread_mutex_unlock(&task_lock);

    return task;
}

// Define the function to set the priority level of a task randomly within a specified range
void set_priority_level(int min, int max) {
    // Acquire the lock on the list of tasks
    pthread_mutex_lock(&task_lock);

    // Loop through each task in the list
    for (int i = 0; i < num_tasks; i++) {
        // Set the priority level randomly within the specified range
        tasks[i].priority_level = min + (rand() % (max - min));
    }

    // Release the lock on the list of tasks
    pthread_mutex_unlock(&task_lock);
}
