import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class DynamicArray {
    private final ConcurrentHashMap<Integer, Double> map = new ConcurrentHashMap<>();
    private final ReentrantReadWriteLock rwLock = new ReentrantReadWriteLock();
    private final Lock readLock = rwLock.readLock();
    private final Lock writeLock = rwLock.writeLock();

    public void initialize() {
        // Initialize the map with random values within a specified range
        for (int i = 0; i < 1000; i++) {
            int key = generateRandomInt(1, 100);
            double value = generateRandomDouble();
            map.put(key, value);
        }
    }

    public void randomValueGeneration() {
        // Generate a random value within a specified range
        int key = generateRandomInt(1, 100);
        double value = generateRandomDouble();
        put(key, value);
    }

    public void concurrencyControl() {
        // Ensure thread-safe operations on the map
        readLock.lock();
        try {
            // Get a value from the map
            int key = generateRandomInt(1, 100);
            double value = map.get(key);
            System.out.println("Value: " + value);
        } finally {
            readLock.unlock();
        }
    }

    public void memoryManagement() {
        // Handle memory allocation failures and potential leaks
        try {
            // Allocate a new record with random values
            int key = generateRandomInt(1, 100);
            double value = generateRandomDouble();
            Record record = new Record(key, value);
            map.put(record.getKey(), record.getValue());
        } catch (OutOfMemoryError error) {
            System.out.println("Memory allocation failed: " + error.getMessage());
        } finally {
            // Free memory if necessary
            if (record != null) {
                record.free();
            }
        }
    }

    public void startServices() {
        // Start services with variable delays between starts
        Service service1 = new Service("Service 1", 50);
        Service service2 = new Service("Service 2", 100);
        Service service3 = new Service("Service 3", 150);
        ServiceManager serviceManager = new ServiceManager();
        serviceManager.add(service1);
        serviceManager.add(service2);
        serviceManager.add(service3);
    }

    public void stopServices() {
        // Stop services with variable delays between stops
        ServiceManager serviceManager = new ServiceManager();
        for (Service service : serviceManager.getServices()) {
            if (service.isRunning()) {
                service.stop(50);
            }
        }
    }

    public void put(int key, double value) {
        writeLock.lock();
        try {
            map.put(key, value);
        } finally {
            writeLock.unlock();
        }
    }

    public double get(int key) {
        readLock.lock();
        try {
            return map.get(key);
        } finally {
            readLock.unlock();
        }
    }

    private int generateRandomInt(int min, int max) {
        // Generate a random integer within the specified range
        Random rand = new Random();
        return rand.nextInt((max - min) + 1) + min;
    }

    private double generateRandomDouble() {
        // Generate a random double value within a specified range
        Random rand = new Random();
        return rand.nextDouble() * (max - min) + min;
    }
}
