int jpeg_to_pdf(char *jpeg_file, char *pdf_file) {
    // Open the JPEG file for reading
    FILE *jpg = fopen(jpeg_file, "rb");
    if (jpg == NULL) {
        return 1;
    }

    // Open the PDF file for writing
