    struct jpeg_decompress_struct cinfo;
    struct jpeg_error_mgr jerr;
    cinfo.err = jpeg_std_error(&jerr);
    if (jpeg_create_decompress(&cinfo) == JPEG_FAILURE) {
        return 1;
    }

    // Read the JPEG file and decompress it
    if (jpeg_read_header(&cinfo, TRUE) != JPEG_HEADER_OK) {
        return 1;
    }
    if (jpeg_start_decompress(&cinfo) != JPEG_SUCCESS) {
        return 1;
    }
    while (cinfo.output_scanline < cinfo.output_height) {
        JSAMPROW row[1];
        row[0] = (JSAMPROW)malloc(sizeof(JSAMPLE) * cinfo.output_width);
        if (jpeg_read_scanlines(&cinfo, &row, 1) != JPEG_SUCCESS) {
            return 1;
        }
        for (int i = 0; i < cinfo.output_width; i++) {
            fwrite(row[i], sizeof(JSAMPLE), 1, pdf);
        }
    }

    // Clean up and return success
    jpeg_finish_decompress(&cinfo);
    jpeg_destroy_decompress(&cinfo);
    fclose(jpg);
    fclose(pdf);
    return 0;
}

