Record* allocate_records(int num_records, int min_str_len, int max_str_len) {
    // Check if the input parameters are valid
    if (num_records <= 0 || min_str_len < 0 || max_str_len < 0 || max_str_len < min_str_len) {
        return NULL;
    }

    // Calculate the total memory required for the records and string buffers
    int total_mem = num_records * sizeof(Record) + num_records * (max_str_len - min_str_len) * sizeof(char);

    // Allocate the memory for the records and string buffers
    Record* records = malloc(total_mem);
    if (!records) {
        return NULL;
    }

    // Initialize the records with default values
