        free(records[i]);
    }

    // Free the array of records
    free(records);
}

// Function to pause and resume the initialization process
void pause_resume_init(int *paused, int num_datasets, record **records) {
    pthread_mutex_lock(&mutex);
    if (*paused) {
        // Resume initialization
        *paused = 0;
        for (int i = 0; i < num_datasets; ++i) {
            records[i]->offset = (long)rand() % key_range[i];
            records[i]->key = rand();
            strcpy(records[i]->str, prefixes[i]);
        }
    } else {
        // Pause initialization
        *paused = 1;
        for (int i = 0; i < num_datasets; ++i) {
            records[i]->offset = -1;
            records[i]->key = -1;
            records[i]->str = NULL;
        }
    }
    pthread_mutex_unlock(&mutex);
}

// Function to generate unique string sequences efficiently
char *generate_string(int num_datasets, record **records) {
    // Use a data structure to track previously generated strings and prevent duplicates
    char *generated_strings[num_datasets];
    for (int i = 0; i < num_datasets; ++i) {
        generated_strings[i] = NULL;
    }

    // Generate a unique string sequence using the data structure
    int index = 0;
    while (index < num_datasets) {
        char *prefix = (char *)malloc(128);
        if (!prefix) {
            fprintf(stderr, "Failed to allocate memory for string prefix\n");
            return NULL;
        }
        sprintf(prefix, "%s%d", prefixes[index], index);

        // Check if the generated string is a duplicate
        bool duplicate = false;
        for (int i = 0; i < num_datasets && !duplicate; ++i) {
            if (strcmp(generated_strings[i], prefix) == 0) {
                duplicate = true;
            }
        }

        // If the generated string is not a duplicate, add it to the data structure and return it
        if (!duplicate) {
            strcpy(generated_strings[index], prefix);
            free(prefix);
            return generated_strings[index];
        }

        // Free the memory allocated for the prefix string
        free(prefix);
    }

    // If no unique string is found, return NULL
    return NULL;
}

// Function to clean up memory allocation for each dataset's record
