typedef uint64_t offset_t;
typedef int32_t key_t;
typedef struct {
    key_t key;
    offset_t *offset;
    bool status;
} record_t;

// Define the initialization function for records
record_t* initialize_records(size_t count) {
    // Allocate memory for an array of records
    record_t *records = malloc(sizeof(record_t) * count);
    if (records == NULL) {
        printf("Error: Failed to allocate memory for records\n");
        return NULL;
    }

    // Initialize the records
    for (size_t i = 0; i < count; i++) {
        // Generate a random key within a specified range
        key_t random_key = generate_random_key(0, INT32_MAX);

        // Select a valid offset index from the offset array
        offset_t *random_offset = select_offset_index(i);
        if (random_offset == NULL) {
            printf("Error: Failed to select a random offset\n");
            return NULL;
        }

        // Set the record status as initialized
        records[i].status = true;

        // Assign the key and offset values
        records[i].key = random_key;
        records[i].offset = random_offset;
    }

    return records;
}

// Generate a random key within a specified range
key_t generate_random_key(int min, int max) {
    // Ensure the minimum value is less than or equal to the maximum value
    if (min > max) {
        int temp = min;
        min = max;
        max = temp;
    }

    // Generate a random key between the minimum and maximum values
    return rand() % (max - min + 1) + min;
}

// Select a valid offset index from an array of offsets
offset_t* select_offset_index(size_t count) {
    // Allocate memory for an array of offsets
    offset_t *offsets = malloc(sizeof(offset_t) * count);
    if (offsets == NULL) {
        printf("Error: Failed to allocate memory for offsets\n");
        return NULL;
    }

    // Initialize the offsets
    for (size_t i = 0; i < count; i++) {
        offsets[i] = generate_random_offset(0, UINT64_MAX);
    }

    // Select a random offset index from the array of offsets
    size_t random_index = rand() % count;

    return offsets + random_index;
}

// Generate a random offset within a specified range
offset_t generate_random_offset(uint64_t min, uint64_t max) {
    // Ensure the minimum value is less than or equal to the maximum value
    if (min > max) {
        uint64_t temp = min;
        min = max;
        max = temp;
    }

    // Generate a random offset between the minimum and maximum values
    return rand() % (max - min + 1) + min;
}
```
