        record->offset = rand() % max_size; // initialize offset with a random value within the specified range
        record->key = i; // initialize key with the current index in the dataset
        record->value = 0; // initialize value to zero
        if (record->dns_record) {
            free(record->dns_record);
        }
        record->dns_record = NULL;
    }

    // Read records from each file and add them to the dataset
    for (i = 0; i < num_files; i++) {
        FILE *file = fopen(files[i], "r");
        if (!file) {
            printf("Error: could not open file %s\n", files[i]);
            return -1;
        }
        char line[256];
        while (fgets(line, sizeof(line), file)) {
            Record *record = &dataset[num_records++];
            record->offset = rand() % max_size; // initialize offset with a random value within the specified range
            record->key = num_records - 1; // set key to the current index in the dataset
            sscanf(line, "%d,%d", &record->value); // read the integer value from the line
            if (record->dns_record) {
                free(record->dns_record);
            }
            record->dns_record = NULL;
        }
        fclose(file);
    }

    return num_records;
}

// Function to compute the average of the last two fields for each record in the dataset and append the value to the end of the line in a comma-separated format
void compute_averages(Record *dataset, int num_records) {
    // Iterate over each record in the dataset
    for (int i = 0; i < num_records; i++) {
        Record *record = &dataset[i];
        if (i >= 1) {
            int average = (record->value + dataset[i - 1].value) / 2;
            printf("%d,%d\n", record->key, average); // print the key and average value to stdout
        } else {
            printf("%d,%d\n", record->key, record->value); // print the key and value to stdout
        }
    }
}

// Function to export the processed records to a binary file for persistence
void export_records(Record *dataset, int num_records) {
    FILE *file = fopen("output.bin", "wb");
