['Here is a sample C function that dynamically reads a variable-sized list of integers from standard input, ensuring the input does not exceed a configurable maximum size of 5000 integers:
```
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

// Define constants for maximum number of records and integer values
#define MAX_RECORDS 5000
#define MAX_INTEGERS 100

// Structure to store 'record' data
typedef struct {
    long offset;
    int key;
    int field1;
    int field2;
    // ...
    int timestamp;
    int status;
} record_t;

int main() {
    // Initialize arrays for storing 'long' offsets, 'int' keys, and 'record' structures
    long *offsets = malloc(MAX_RECORDS * sizeof(long));
    int *keys = malloc(MAX_RECORDS * sizeof(int));
    record_t *records = malloc(MAX_RECORDS * sizeof(record_t));

    // Loop until end-of-file is reached
    while (1) {
        // Read next integer from standard input
        int value;
        if (scanf("%d", &value) != 1) {
            break;
        }

        // Check for overflow condition
        if (offsets == NULL || keys == NULL || records == NULL) {
            fprintf(stderr, "Memory allocation failed. Exiting...\n");
            exit(EXIT_FAILURE);
        }

        // Store integer value in array
        offsets[offsets_index] = value;
        keys[keys_index] = value * 2 + 1;
        records[records_index].offset = value;
        records[records_index].key = value * 3 + 2;
        records[records_index].field1 = value * 4 + 3;
        // ...
        records[records_index].timestamp = get_current_timestamp();
        records[records_index].status = VALID;

        // Increment indices for arrays
        offsets_index++;
        keys_index++;
        records_index++;
    }

    // Print error message and exit if maximum number of records is exceeded
    if (offsets_index >= MAX_RECORDS) {
        fprintf(stderr, "Maximum number of records (%d) exceeded. Exiting...\n", MAX_RECORDS);
        exit(EXIT_FAILURE);
    }

    // Print success message and return
    printf("Successfully read %d integers.\n", offsets_index);
    return 0;
}
```
