#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/types.h>
#include <netinet/in.h>
#include <arpa/inet.h>

typedef struct record {
    long offset;
    int key;
    int value;
} Record;

void init_record(Record* rec, int seed) {
    rec->value = rand_r(&seed) % 100;
}

double compute_average(Record* rec) {
    return (rec->offset + rec->key) / 2.0;
}

void process_record(Record* rec, int field_count) {
    if (field_count % 2 != 0) {
        rec->value = rec->offset;
    }
    double average = compute_average(rec);
    printf("%d,%f\n", rec->key, average);
}

void resolve_dns(char* hostname, u_char* ip) {
    struct addrinfo hints;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_DGRAM;
    struct addrinfo* result;
    if (getaddrinfo(hostname, NULL, &hints, &result) == 0) {
        memcpy(ip, &result->ai_addr->sa_data[2], sizeof(u_char));
    }
}

void process_record_with_dns(Record* rec, int field_count) {
    if (field_count % 2 != 0) {
        rec->value = rec->offset;
    }
    double average = compute_average(rec);
    printf("%d,%f\n", rec->key, average);
    u_char ip[4];
    resolve_dns(rec->hostname, ip);
}

void process_file(FILE* file) {
    int field_count = 0;
    Record record;
    while (fscanf(file, "%ld,%d", &record.offset, &record.key) == 2) {
        init_record(&record, time(NULL));
        if (field_count % 2 != 0) {
            process_record(&record, field_count);
        } else {
            process_record_with_dns(&record, field_count);
        }
        field_count++;
    }
}

void main(int argc, char* argv[]) {
    if (argc != 2) {
        printf("Usage: %s <input file>\n", argv[0]);
        return;
    }
    FILE* input_file = fopen(argv[1], "r");
    if (!input_file) {
        perror("fopen");
        return;
    }
    process_file(input_file);
    fclose(input_file);
}
