                entities[i].str = (char*)malloc(length);
                for (int j = 0; j < length; j++) {
                    entities[i].str[j] = rand() / (double)RAND_MAX;
                }
                break;
            case POINT:
                entities[i].p.x = rand() / (double)RAND_MAX;
                entities[i].p.y = rand() / (double)RAND_MAX;
                break;
        }
    }

    // Print the initialized entities
    for (int i = 0; i < num_entities; i++) {
        switch (entities[i].type) {
