#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <pthread.h>

// Struct to represent a record in the data structure
typedef struct {
    int value;
} Record;

// Struct to represent the entire data structure
typedef struct {
    long *offsets;  // Array of offset values
    int *keys;     // Array of keys
    Record **records;   // Array of record structures
    size_t capacity;   // Capacity of the data structure
    size_t count;      // Number of records in the data structure
    pthread_mutex_t mutex;  // Mutex for thread safety
} DataStructure;

// Initialize the data structure with a given capacity
bool init(DataStructure *ds, size_t capacity) {
    if (capacity == 0) {
        return false;
    }
    ds->offsets = malloc(sizeof(long) * capacity);
    ds->keys = malloc(sizeof(int) * capacity);
    ds->records = malloc(sizeof(Record *) * capacity);
    ds->capacity = capacity;
    ds->count = 0;
    ds->mutex = PTHREAD_MUTEX_INITIALIZER;
    return true;
}

// Add a new record to the data structure
bool add(DataStructure *ds, long offset, int key) {
    if (offset >= ds->capacity || key >= ds->capacity) {
        return false;
    }
    pthread_mutex_lock(&ds->mutex);
    // Check for duplicate keys
    for (int i = 0; i < ds->count; i++) {
        if (ds->keys[i] == key) {
            pthread_mutex_unlock(&ds->mutex);
            return false;
        }
    }
    // Add the new record to the data structure
    ds->offsets[ds->count] = offset;
    ds->keys[ds->count] = key;
    ds->records[ds->count] = malloc(sizeof(Record));
    memset(ds->records[ds->count], 0, sizeof(Record));
    ds->count++;
    pthread_mutex_unlock(&ds->mutex);
    return true;
}

// Update a record in the data structure
bool update(DataStructure *ds, long offset, int key, Record *record) {
    if (offset >= ds->capacity || key >= ds->capacity) {
        return false;
    }
    pthread_mutex_lock(&ds->mutex);
    // Find the record with the given key
    for (int i = 0; i < ds->count; i++) {
        if (ds->keys[i] == key) {
            // Update the record and return
            memcpy(ds->records[i], record, sizeof(Record));
            pthread_mutex_unlock(&ds->mutex);
            return true;
        }
    }
    // If no matching record found, add a new one
    if (add(ds, offset, key)) {
        memcpy(ds->records[ds->count - 1], record, sizeof(Record));
        pthread_mutex_unlock(&ds->mutex);
        return true;
    }
    // If no new record could be added, return false
    pthread_mutex_unlock(&ds->mutex);
    return false;
}

// Get a record from the data structure
Record *get(DataStructure *ds, long offset) {
    if (offset >= ds->capacity) {
        return NULL;
    }
    pthread_mutex_lock(&ds->mutex);
    // Find the record with the given offset
    for (int i = 0; i < ds->count; i++) {
        if (ds->offsets[i] == offset) {
            Record *record = malloc(sizeof(Record));
            memcpy(record, ds->records[i], sizeof(Record));
            pthread_mutex_unlock(&ds->mutex);
            return record;
        }
    }
    // If no matching record found, return NULL
    pthread_mutex_unlock(&ds->mutex);
    return NULL;
}

// Delete a record from the data structure
bool delete(DataStructure *ds, long offset) {
    if (offset >= ds->capacity) {
        return false;
    }
    pthread_mutex_lock(&ds->mutex);
    // Find the record with the given offset
    for (int i = 0; i < ds->count; i++) {
        if (ds->offsets[i] == offset) {
            // Delete the record and update the count
            free(ds->records[i]);
            ds->count--;
            pthread_mutex_unlock(&ds->mutex);
            return true;
        }
    }
    // If no matching record found, return false
    pthread_mutex_unlock(&ds->mutex);
    return false;
}

// Serialize the data structure to a file
bool serialize(DataStructure *ds, const char *filename) {
    if (ds == NULL || filename == NULL) {
        return false;
    }
    pthread_mutex_lock(&ds->mutex);
    // Open the file for writing and write the header
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        pthread_mutex_unlock(&ds->mutex);
        return false;
    }
    int32_t count = ds->count;
    fwrite(&count, sizeof(int32_t), 1, file);
    // Write the records to the file
    for (int i = 0; i < ds->count; i++) {
        long offset = ds->offsets[i];
        int key = ds->keys[i];
        Record *record = ds->records[i];
        fwrite(&offset, sizeof(long), 1, file);
        fwrite(&key, sizeof(int), 1, file);
        fwrite(record, sizeof(Record), 1, file);
    }
    // Close the file and return true
    fclose(file);
    pthread_mutex_unlock(&ds->mutex);
    return true;
}

// Deserialize the data structure from a file
bool deserialize(DataStructure *ds, const char *filename) {
    if (ds == NULL || filename == NULL) {
        return false;
    }
    pthread_mutex_lock(&ds->mutex);
    // Open the file for reading and read the header
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        pthread_mutex_unlock(&ds->mutex);
        return false;
    }
    int32_t count;
    fread(&count, sizeof(int32_t), 1, file);
    // Read the records from the file and add them to the data structure
    for (int i = 0; i < count; i++) {
        long offset;
        int key;
        Record *record;
        fread(&offset, sizeof(long), 1, file);
        fread(&key, sizeof(int), 1, file);
        record = malloc(sizeof(Record));
        memset(record, 0, sizeof(Record));
        fread(record, sizeof(Record), 1, file);
        add(ds, offset, key);
    }
    // Close the file and return true
    fclose(file);
    pthread_mutex_unlock(&ds->mutex);
    return true;
}
