```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the data structure to hold either a double value or a string
typedef struct {
    union {
        double d;
        char* s;
    } v;
} data;

// Function to initialize the dynamic array of data structures with random values
void init_data(data** d, int n) {
    // Allocate memory for the array of data structures
    *d = (data*)malloc(n * sizeof(data));
    if (*d == NULL) {
        printf("Error: Failed to allocate memory for the dynamic array\n");
        exit(1);
    }

    // Initialize each element of the array with a random double value within the specified range
    srand(time(NULL));
    for (int i = 0; i < n; ++i) {
        (*d)[i].v.d = rand() % (10 - (-10)) + (-10);
    }
}

// Function to generate random strings of the specified length
char* generate_string(int length) {
    char* s = malloc(length + 1);
    for (int i = 0; i < length; ++i) {
        s[i] = rand() % ('z' - 'a') + 'a';
    }
    s[length] = '\0';
    return s;
}

// Function to compute the average of all numeric entries in the array
double compute_average(data* d, int n) {
    double sum = 0.0;
    for (int i = 0; i < n; ++i) {
        if (d[i].v.d != 0.0) {
            sum += d[i].v.d;
        }
    }
    return sum / n;
}

// Function to determine the frequency of each unique string in the array
int* compute_frequency(data* d, int n) {
    int* freq = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; ++i) {
        if (d[i].v.s != NULL) {
            freq[i]++;
        }
    }
    return freq;
}

// Function to load data from a binary file and store it in the dynamic array
int load_data(data** d, int n, char* filename) {
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        printf("Error: Failed to open the input file\n");
        return 1;
    }

    // Read the data from the file and store it in the dynamic array
    for (int i = 0; i < n; ++i) {
        if (fread(&(*d)[i].v, sizeof(data), 1, fp) != 1) {
            printf("Error: Failed to read data from the input file\n");
            return 1;
        }
    }

    // Close the input file
    fclose(fp);
    return 0;
}

// Function to save the dynamic array of data structures to a binary file
int save_data(data* d, int n, char* filename) {
    FILE* fp = fopen(filename, "wb");
    if (fp == NULL) {
        printf("Error: Failed to open the output file\n");
        return 1;
    }

    // Write the data from the dynamic array to the file
    for (int i = 0; i < n; ++i) {
        if (fwrite(&d[i].v, sizeof(data), 1, fp) != 1) {
            printf("Error: Failed to write data to the output file\n");
            return 1;
        }
    }

    // Close the output file
    fclose(fp);
    return 0;
}

// Main function to process the variable-length list of floating-point numbers and strings
int main() {
    int n = -1;
    char* filename = NULL;
    data** d = NULL;

    // Get the number of entries from the user
    printf("Enter the number of entries (0 for random): ");
    scanf("%d", &n);

    // Initialize the dynamic array of data structures with random values if n is 0
    if (n == 0) {
        init_data(&d, n);
    } else {
        d = (data**)malloc(n * sizeof(data*));
        if (d == NULL) {
            printf("Error: Failed to allocate memory for the dynamic array\n");
            return 1;
        }
        for (int i = 0; i < n; ++i) {
            d[i] = (data*)malloc(sizeof(data));
            if (d[i] == NULL) {
                printf("Error: Failed to allocate memory for the data structure\n");
                return 1;
            }
        }
    }

    // Get the filename from the user
    printf("Enter the filename (NULL for standard input): ");
    scanf("%s", &filename);

    // Load the data from the file if a filename is specified
    if (filename != NULL) {
        load_data(&d, n, filename);
    }

    // Compute the average of all numeric entries in the array
    double avg = compute_average(d, n);
    printf("The average of all numeric entries is: %.2f\n", avg);

    // Determine the frequency of each unique string in the array
    int* freq = compute_frequency(d, n);
    for (int i = 0; i < n; ++i) {
        if (d[i].v.s != NULL) {
            printf("The frequency of string '%s' is: %d\n", d[i].v.s, freq[i]);
        }
    }

    // Save the data to a binary file if a filename is specified
    if (filename != NULL) {
        save_data(d, n, filename);
    }

    // Free the memory allocated for the dynamic array of data structures
    for (int i = 0; i < n; ++i) {
        free(d[i]);
    }
    free(d);

    return 0;
}
```
