// Structure definition for the record
typedef struct {
    int key;
    long offset;
} record_t;

// Function to dynamically allocate memory for a variable-length array of records
record_t* alloc_records(size_t count) {
    // Calculate the size of the memory block needed to store 'count' records
    size_t size = sizeof(record_t) * count;

    // Allocate memory for the array using malloc()
    record_t* records = (record_t*)malloc(size);

    // Check if allocation was successful
    if (!records) {
        fprintf(stderr, "Error: Failed to allocate memory for %zu records\n", count);
        return NULL;
    }

    // Initialize the array with default values
    memset(records, 0, size);

    // Return a pointer to the allocated memory block
    return records;
}
```
