// Define the record structure
typedef struct {
    int key;
    long offset;
} Record;

int load_resource_bundle(const char* filepath, size_t batch_size) {
    // Open the resource bundle file
    FILE* fp = fopen(filepath, "rb");
    if (fp == NULL) {
        printf("Error: unable to open resource bundle file\n");
        return -1;
    }

    // Get the number of records in the bundle
    size_t num_records = 0;
    fseek(fp, 0, SEEK_END);
    num_records = ftell(fp) / sizeof(Record);
    rewind(fp);

    // Allocate memory for the record array
    Record* records = malloc(num_records * sizeof(Record));
    if (records == NULL) {
        printf("Error: unable to allocate memory for record array\n");
        fclose(fp);
        return -1;
    }

    // Read the records from the file into the array
    size_t num_read = fread(records, sizeof(Record), num_records, fp);
    if (num_read < num_records) {
        printf("Error: unable to read all records from resource bundle file\n");
        free(records);
        fclose(fp);
        return -1;
    }

    // Close the file and return the number of records in the bundle
    fclose(fp);
    return num_records;
}

void deallocate_resource_bundle(Record* records, size_t num_records) {
    // Free the memory allocated for the record array
    free(records);
}
