['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <conio.h>
#include <pthread.h>

// Define a structure to represent a record
struct Record {
    int key;
    float value;
    char *string;
};

// Define a linked list node to store records in the memory pool
struct Node {
    struct Record record;
    struct Node *next;
};

// Memory pool for storing records
static struct Node *memory_pool = NULL;

// Function to allocate memory for a new record
struct Record *allocate_record() {
    // Check if there is space in the memory pool
    if (memory_pool == NULL) {
        // If there is no space, allocate a new block of memory
        memory_pool = (struct Node *)malloc(sizeof(struct Node));
        if (memory_pool == NULL) {
            // If allocation fails, return NULL
            return NULL;
        }
    } else {
        // If there is space in the memory pool, get the next available node
        struct Node *node = memory_pool->next;
        if (node != NULL) {
            // If there are more nodes in the pool, use the next one
            memory_pool = node;
        } else {
            // If there are no more nodes in the pool, allocate a new block of memory
            struct Node *new_memory = (struct Node *)malloc(sizeof(struct Node));
            if (new_memory == NULL) {
                // If allocation fails, return NULL
                return NULL;
            } else {
                // If allocation succeeds, add the new node to the end of the pool
                memory_pool->next = new_memory;
            }
        }
    }
    // Return the record stored in the allocated node
    return &memory_pool->record;
}

// Function to deallocate memory for a record
void deallocate_record(struct Record *record) {
    // Check if the record is NULL
    if (record == NULL) {
        // If the record is NULL, do nothing
        return;
    }
    // Get the node that stores the record
    struct Node *node = (struct Node *)((char *)record - offsetof(struct Node, record));
    // Check if the node is in the memory pool
    if (node == memory_pool) {
        // If the node is in the memory pool, remove it from the pool
        memory_pool = memory_pool->next;
    } else {
        // If the node is not in the memory pool, mark it as free
        node->next = NULL;
    }
}

// Function to add a new record to the collection
struct Record *add_record(int key, float value, char *string) {
    // Allocate memory for the new record
    struct Record *new_record = allocate_record();
    if (new_record == NULL) {
        // If allocation fails, return NULL
        return NULL;
    }
    // Set the values of the new record
    new_record->key = key;
    new_record->value = value;
    new_record->string = string;
    // Return the new record
    return new_record;
}

// Function to remove a record from the collection
void remove_record(struct Record *record) {
    // Check if the record is NULL
    if (record == NULL) {
        // If the record is NULL, do nothing
        return;
    }
    // Get the node that stores the record
    struct Node *node = (struct Node *)((char *)record - offsetof(struct Node, record));
    // Check if the node is in the memory pool
    if (node == memory_pool) {
        // If the node is in the memory pool, remove it from the pool
        memory_pool = memory_pool->next;
    } else {
        // If the node is not in the memory pool, mark it as free
        node->next = NULL;
    }
}

// Function to find a record in the collection by key
struct Record *find_record(int key) {
    // Check if the memory pool is empty
    if (memory_pool == NULL) {
        // If the memory pool is empty, return NULL
        return NULL;
    }
    // Get the first node in the memory pool
    struct Node *node = memory_pool;
    do {
        // Check if the key matches the record stored in the current node
        if (node->record.key == key) {
            // If the key matches, return the record
            return &node->record;
        }
        // Get the next node in the memory pool
        node = node->next;
    } while (node != NULL);
    // If no matching record is found, return NULL
    return NULL;
}

// Function to update a record in the collection by key
void update_record(int key, float value, char *string) {
    // Find the record with the specified key
    struct Record *record = find_record(key);
    if (record != NULL) {
        // If the record is found, update its values
        record->value = value;
        record->string = string;
    } else {
        // If the record is not found, add a new record with the specified key and values
        add_record(key, value, string);
    }
}

// Function to print all records in the collection
void print_records() {
    // Check if the memory pool is empty
    if (memory_pool == NULL) {
        // If the memory pool is empty, print a message indicating that there are no records
        printf("There are no records in the collection.\n");
    } else {
        // Print each record stored in the memory pool
        struct Node *node = memory_pool;
        do {
            // Print the key and values of the current node's record
            printf("Record: %d, Value: %f, String: %s\n", node->record.key, node->record.value, node->record.string);
            // Get the next node in the memory pool
            node = node->next;
        } while (node != NULL);
    }
}

// Function to free all records in the collection
void clear_records() {
    // Check if the memory pool is empty
    if (memory_pool == NULL) {
        // If the memory pool is empty, do nothing
        return;
    } else {
        // Get the first node in the memory pool
        struct Node *node = memory_pool;
        do {
            // Free each record stored in the current node
            deallocate_record(&node->record);
            // Get the next node in the memory pool
            node = node->next;
        } while (node != NULL);
    }
}

// Function to check if a record exists in the collection by key
int record_exists(int key) {
    // Find the record with the specified key
    struct Record *record = find_record(key);
    if (record == NULL) {
        // If no matching record is found, return 0
        return 0;
    } else {
        // If a matching record is found, return 1
        return 1;
    }
}

// Function to get the number of records in the collection
int get_num_records() {
    // Initialize a variable to keep track of the number of records
    int num_records = 0;
    // Check if the memory pool is empty
    if (memory_pool == NULL) {
        // If the memory pool is empty, return 0
        return 0;
    } else {
        // Get the first node in the memory pool
        struct Node *node = memory_pool;
        do {
            // Increment the number of records by 1 for each record stored in the current node
            num_records++;
            // Get the next node in the memory pool
            node = node->next;
        } while (node != NULL);
    }
    // Return the total number of records found
    return num_records;
}
```
