    struct LogFile* files = (struct LogFile*) malloc(num_files * sizeof(struct LogFile));

    for (int i = 0; i < num_files; ++i) {
        char* log_file = argv[i + 2];
        FILE* file = fopen(log_file, "r");

        if (file == NULL) {
            fprintf(stderr, "Failed to open %s\n", log_file);
            return 1;
        }

        int num_records = countRecords(file);
        files[i].file = file;
        files[i].num_records = num_records;
    }

    // Process the records in parallel
