// Define data structures for records
typedef struct Record {
    union {
        int integer_value;
        char *string_value;
    } value;
} Record;

// Function to dynamically allocate memory for arrays of long values
void allocate_array(long **arr, size_t n) {
    if (!arr) return;
    *arr = (long *)malloc(n * sizeof(long));
    if (*arr) memset(*arr, 0, n * sizeof(long));
}

// Function to dynamically allocate memory for arrays of int values
void allocate_array_int(int **arr, size_t n) {
    if (!arr) return;
    *arr = (int *)malloc(n * sizeof(int));
    if (*arr) memset(*arr, 0, n * sizeof(int));
}

// Function to dynamically allocate memory for arrays of Record structures
void allocate_array_record(Record **arr, size_t n) {
    if (!arr) return;
    *arr = (Record *)malloc(n * sizeof(Record));
    if (*arr) memset(*arr, 0, n * sizeof(Record));
}

// Function to initialize records with random integers within a specified range
void init_records_int(Record *records, size_t n, int min, int max) {
    for (size_t i = 0; i < n; ++i) {
        records[i].value.integer_value = rand() % (max - min + 1) + min;
    }
}

// Function to initialize records with random strings of a specified length
void init_records_string(Record *records, size_t n, int len) {
    for (size_t i = 0; i < n; ++i) {
        char str[len];
        for (int j = 0; j < len; ++j) {
            str[j] = 'a' + rand() % ('z' - 'a');
        }
        records[i].value.string_value = strdup(str);
    }
}

// Function to filter records based on predefined attributes
void filter_records(Record *records, size_t n, int attribute, int value) {
    if (!records || !n) return;
    for (size_t i = 0; i < n; ++i) {
        switch (attribute) {
            case 1: // integer value
                if (records[i].value.integer_value == value) {
                    printf("%d\n", records[i].value.integer_value);
                }
                break;
            case 2: // string value
                if (!strcmp(records[i].value.string_value, value)) {
                    printf("%s\n", records[i].value.string_value);
                }
                break;
        }
    }
