#include <arpa/inet.h>
#include <netdb.h>
#include <unistd.h>
#include <errno.h>
#include <pthread.h>
#include <semaphore.h>

#define PORT 8080
#define MAX_CONNECTIONS 10
#define BUFFER_SIZE 1024
#define RECORD_SIZE sizeof(struct record)

// Define the structure to store records
struct record {
    int value;
};

// Define the function prototypes
void* connection_handler(void* args);
void* data_processor(void* args);
int establish_connection(char* address, int port);
int process_data(int sockfd, struct record* records);

// Declare global variables
struct record* records; // Array of records to store data
sem_t semaphore; // Semaphore for synchronizing access to records
int connections = 0; // Number of active connections

int main(void) {
    int sockfd, newsockfd, portno;
    struct sockaddr_in serv_addr, cli_addr;
    socklen_t clilen;
    char buffer[BUFFER_SIZE];
    int n;

    // Create a socket
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("ERROR: Socket creation failed");
        exit(-1);
    }

    // Configure the socket
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(PORT);
    serv_addr.sin_addr.s_addr = INADDR_ANY;

    // Bind the socket to a specific IP address and port number
    if (bind(sockfd, (struct sockaddr*)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("ERROR: Socket binding failed");
        exit(-1);
    }

    // Listen for incoming connections on the socket
    listen(sockfd, MAX_CONNECTIONS);

    while (1) {
        clilen = sizeof(cli_addr);
        newsockfd = accept(sockfd, (struct sockaddr*)&cli_addr, &clilen);
        if (newsockfd < 0) {
            perror("ERROR: Socket connection failed");
            exit(-1);
        }

        // Handle the incoming connection in a separate thread
        pthread_t thread;
        if (pthread_create(&thread, NULL, connection_handler, (void*)&newsockfd) < 0) {
            perror("ERROR: Thread creation failed");
            exit(-1);
        }
    }

    return 0;
}

void* connection_handler(void* args) {
    int sockfd = *(int*)args;
    struct record* records = (struct record*)malloc(sizeof(struct record)*MAX_CONNECTIONS);
    while (1) {
        // Read data from the socket
        bzero(buffer, BUFFER_SIZE);
        n = read(sockfd, buffer, BUFFER_SIZE-1);
        if (n < 0) {
            perror("ERROR: Socket read failed");
            exit(-1);
        }
        // Process the data in a separate thread
        pthread_t thread;
        if (pthread_create(&thread, NULL, data_processor, (void*)&records) < 0) {
            perror("ERROR: Thread creation failed");
            exit(-1);
        }
    }
}

void* data_processor(void* args) {
    struct record** records = (struct record**)args;
    while (1) {
        // Wait for the semaphore to be available
        sem_wait(&semaphore);

        // Process the incoming data
        process_data(*records, *(int*)args);

        // Increment the number of connections
        connections++;

        // Signal the semaphore that it is available again
        sem_post(&semaphore);
    }
}

int establish_connection(char* address, int port) {
    int sockfd, newsockfd, portno;
    struct sockaddr_in serv_addr, cli_addr;
    socklen_t clilen;
    char buffer[BUFFER_SIZE];
    int n;

    // Create a socket
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("ERROR: Socket creation failed");
        exit(-1);
    }

    // Configure the socket
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(port);
    inet_pton(AF_INET, address, &serv_addr.sin_addr);

    // Connect to the server
    if (connect(sockfd, (struct sockaddr*)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("ERROR: Socket connection failed");
        exit(-1);
    }

    return sockfd;
}

int process_data(int sockfd, struct record* records) {
    char buffer[BUFFER_SIZE];
    int n;

    // Read data from the socket
    bzero(buffer, BUFFER_SIZE);
    n = read(sockfd, buffer, BUFFER_SIZE-1);
    if (n < 0) {
        perror("ERROR: Socket read failed");
        exit(-1);
    }

    // Process the data
    for (int i = 0; i < n/RECORD_SIZE; i++) {
        records[i].value = atoi(buffer+i*RECORD_SIZE);
    }
}
