int active_threads = 0;
int error_code = 0;

void *thread_func(void *arg) {
    int thread_id = (int) arg;
    printf("Thread %d started\n", thread_id);

    // Initialize semaphores with specific values
    for (int i = 0; i < 10; i++) {
        if (sem_init(&sem_vals[i], 0, sem_vals[i]) != 0) {
            perror("Error initializing semaphore");
            exit(EXIT_FAILURE);
        }
    }

    // Perform operations to manipulate semaphore states
    for (int i = 0; i < 10; i++) {
        if (sem_wait(&sem_vals[i]) != 0) {
            perror("Error waiting on semaphore");
            exit(EXIT_FAILURE);
        }
    }

    // Handle thread synchronization effectively
    pthread_mutex_lock(&mutex);
    active_threads++;
    pthread_mutex_unlock(&mutex);

    // Implement a mechanism to track the number of active threads
    if (active_threads == num_threads) {
        for (int i = 0; i < 10; i++) {
            if (sem_post(&sem_vals[i]) != 0) {
                perror("Error posting on semaphore");
                exit(EXIT_FAILURE);
            }
        }
    }

    // Asynchronously load a resource bundle from a specified distributed data source
    int num_items = 0;
