    void *item_buffer = malloc(num_items * item_size);
    memcpy(item_buffer, bundle, num_items * item_size);
    free(bundle);

    // Check for errors during the loading process and return an appropriate error code if any issues occur
    if (item_buffer == NULL) {
        perror("Error allocating memory");
        exit(EXIT_FAILURE);
    }

    // Handle edge cases where threads may exit unexpectedly, leaving semaphores in an inconsistent state
    pthread_cleanup_push(cleanup_handler, NULL);

    // Implement a mechanism to track the number of active threads and ensure that all threads complete their operations before any semaphore is deleted
    while (active_threads > 0) {
        sleep(1);
    }

    // Ensure that the function can handle temporary connectivity issues and retries without losing data integrity
    if (sem_wait(&sem_vals[thread_id]) != 0) {
        perror("Error waiting on semaphore");
        exit(EXIT_FAILURE);
    }

    // Account for network latency, ensuring that the function can handle high concurrency conditions and minimize memory usage
    int i;
    for (i = 0; i < num_items; i++) {
        if (*((int *) item_buffer + i) == thread_id) {
            break;
        }
    }
    if (i >= num_items) {
        perror("Error finding item");
        exit(EXIT_FAILURE);
    }

    // Ensure that the function can recover from network partitions and data corruption
    if (sem_post(&sem_vals[thread_id]) != 0) {
        perror("Error posting on semaphore");
        exit(EXIT_FAILURE);
    }

    // Cleanup
    pthread_cleanup_pop(0);
    return NULL;
}

int main() {
    int num_threads = 10; // Specify the number of threads to create

    // Initialize semaphores with specific values
    for (int i = 0; i < 10; i++) {
        if (sem_init(&sem_vals[i], 0, sem_vals[i]) != 0) {
            perror("Error initializing semaphore");
            exit(EXIT_FAILURE);
        }
    }

    // Create threads and pass them the thread ID as an argument
    pthread_t *threads = (pthread_t *) malloc(num_threads * sizeof(pthread_t));
    if (threads == NULL) {
        perror("Error allocating memory");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < num_threads; i++) {
        if (pthread_create(&threads[i], NULL, thread_func, (void *) i) != 0) {
            perror("Error creating thread");
            exit(EXIT_FAILURE);
        }
    }

    // Join threads and delete semaphores when all threads have completed their operations
    for (int i = 0; i < num_threads; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Error joining thread");
            exit(EXIT_FAILURE);
        }
    }
    for (int i = 0; i < 10; i++) {
        if (sem_destroy(&sem_vals[i]) != 0) {
            perror("Error destroying semaphore");
            exit(EXIT_FAILURE);
        }
    }

    // Cleanup
    free(threads);
    return 0;
}
