    time_t timestamp;
    int id;
    char* offset;
    char* key;
} DataPoint;

// Function to initialize the dynamic array of data points
void initDataPoints(DataPoint** dataPoints, int capacity) {
    // Allocate memory for the array on the heap
    *dataPoints = (DataPoint*)malloc(capacity * sizeof(DataPoint));
    if (*dataPoints == NULL) {
        printf("Error: Failed to allocate memory for data points\n");
        exit(1);
    }

    // Initialize the array with empty data points
    for (int i = 0; i < capacity; i++) {
        (*dataPoints)[i].value = 0.0;
        (*dataPoints)[i].timestamp = 0;
        (*dataPoints)[i].id = 0;
        (*dataPoints)[i].offset = NULL;
        (*dataPoints)[i].key = NULL;
    }
}

// Function to insert records into the dynamic array of data points
void insertDataPoint(DataPoint** dataPoints, int* count, DataPoint* dataPoint) {
    // Check if the array is full
    if (*count == capacity) {
        printf("Error: Array is full\n");
        return;
    }

    // Insert the data point into the array
    (*dataPoints)[(*count)++] = *dataPoint;
}

// Function to insert records into the dynamic array of data points in batches
void insertDataPoints(DataPoint** dataPoints, int* count, DataPoint* dataPointsBatch, int size) {
    // Check if the array is full
    if (*count + size > capacity) {
        printf("Error: Array is full\n");
        return;
    }

    // Insert the data points into the array
    memcpy(&(*dataPoints)[*count], dataPointsBatch, size * sizeof(DataPoint));
    *count += size;
}

// Function to iterate over all records in the dynamic array of data points
void iterateOverDataPoints(DataPoint** dataPoints, int count) {
    // Iterate over all records in the array
    for (int i = 0; i < count; i++) {
        printf("Record %d: offset=%s, key=%s, timestamp=%ld, id=%d\n", i + 1, (*dataPoints)[i].offset, (*dataPoints)[i].key, (*dataPoints)[i].timestamp, (*dataPoints)[i].id);
    }
}

// Function to compute the average value of all valid data points in the dynamic array of data points
double computeAverageValue(DataPoint** dataPoints, int count) {
    // Initialize variables for sum and number of valid data points
    double sum = 0.0;
    int numValid = 0;

    // Iterate over all records in the array
    for (int i = 0; i < count; i++) {
        if ((*dataPoints)[i].value != 0) {
            sum += (*dataPoints)[i].value;
            numValid++;
        }
    }

    // Return the average value of all valid data points
    return sum / (double)numValid;
}

// Main function for testing the dynamic array of data points
