typedef unsigned long long offset_t;
typedef enum {
    INITIALIZED,
    UNDERFLOW,
    OVERFLOW,
    INVALID_KEY
} status_t;

// Initialize an array of 'record' structures with a specified number of records and either random integers or strings
Record* initializeRecords(size_t numRecords, int minIntValue, int maxIntValue, size_t strLength) {
    // Allocate memory for the record array
    Record* records = (Record*)malloc(numRecords * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Error: unable to allocate memory for record array\n");
        return NULL;
    }

    // Initialize each record with a random integer value within the specified range or string length
    srand(time(NULL));
    for (size_t i = 0; i < numRecords; ++i) {
        records[i].key = rand() % (maxIntValue - minIntValue + 1) + minIntValue;
        if (strLength > 0) {
            // Allocate memory for the string value
            size_t len = strlen(records[i].value);
            records[i].value = (char*)malloc(len * sizeof(char));
            if (!records[i].value) {
                fprintf(stderr, "Error: unable to allocate memory for string value\n");
                return NULL;
            }
            // Generate a random string of the specified length
            for (size_t j = 0; j < len; ++j) {
                records[i].value[j] = rand() % ('z' - 'a') + 'a';
            }
        } else {
            // Initialize the string value to NULL
            records[i].value = NULL;
        }
    }

    // Set the key_t field of each record to a random value within the specified range
    for (size_t i = 0; i < numRecords; ++i) {
        int key = rand() % (maxIntValue - minIntValue + 1) + minIntValue;
        if (key < minIntValue || key > maxIntValue) {
            fprintf(stderr, "Error: invalid key value\n");
            return NULL;
        }
        records[i].key = key;
    }

    // Select a valid offset_t index from the 'offset_t' array while accounting for potential hotspots
    size_t numOffsets = (numRecords / 64) + 1;
    offset_t* offsets = (offset_t*)malloc(numOffsets * sizeof(offset_t));
    if (!offsets) {
        fprintf(stderr, "Error: unable to allocate memory for offset array\n");
        return NULL;
    }
    size_t index = 0;
    while (index < numRecords) {
        // Find the next valid offset_t index that is not a hotspot
        bool hotspot = false;
        while (hotspot) {
            offsets[index] = rand() % (numOffsets - 1);
            if (offsets[index] == 0 || offsets[index] == numOffsets - 1) {
                // Skip over hotspots
                continue;
            } else {
                hotspot = false;
            }
        }
        index++;
    }

    // Set the status_t flag of each record to indicate initialization
    for (size_t i = 0; i < numRecords; ++i) {
        records[i].status = INITIALIZED;
    }

    return records;
}

// Filter records based on specific criteria, such as selecting only those records containing integers greater than a specified threshold or strings longer than a certain length
Record* filterRecords(Record* records, size_t numRecords, int minIntValue, int maxIntValue, size_t strLength) {
    // Allocate memory for the filtered record array
    Record* filtered = (Record*)malloc(numRecords * sizeof(Record));
    if (!filtered) {
        fprintf(stderr, "Error: unable to allocate memory for filtered record array\n");
        return NULL;
    }

    // Iterate over each record and filter based on specified criteria
    size_t numFiltered = 0;
    for (size_t i = 0; i < numRecords; ++i) {
        if (records[i].key >= minIntValue && records[i].key <= maxIntValue) {
            // Copy the record to the filtered array
            filtered[numFiltered] = records[i];
            numFiltered++;
        } else if (strLength > 0 && strlen(records[i].value) >= strLength) {
            // Copy the record to the filtered array
            filtered[numFiltered] = records[i];
            numFiltered++;
        } else {
            // Skip over records that do not meet the specified criteria
        }
    }

    return filtered;
}

// Execute a command using Runtime.getRuntime().exec(String, String, File) and delete a file if it exists before executing
void executeCommand(const char* cmd, const char* file) {
    // Delete the file if it exists before executing the command
    FILE* fp = fopen(file, "r");
    if (fp != NULL) {
        fclose(fp);
        remove(file);
    }
    // Execute the command using Runtime.getRuntime().exec(String, String, File)
    int status = system(cmd);
    if (status < 0) {
        fprintf(stderr, "Error: unable to execute command\n");
    }
}

// Read the output and error streams of a process using BufferedReader
void readStreams(const char* file) {
    // Open the file for reading
    FILE* fp = fopen(file, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: unable to open output file\n");
        return;
    }

    // Read the output and error streams of the process using BufferedReader
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), fp) != NULL) {
        printf("%s", buffer);
    }

    // Close the file
    fclose(fp);
}
