int readRecords(Record** records, size_t* numRecords, size_t initialSize) {
    // validate input sizes
    if (initialSize == 0 || initialSize > SIZE_MAX / sizeof(Record)) {
        return -1;
    }

    // allocate memory for the array of records
    *records = malloc(initialSize * sizeof(Record));
    if (*records == NULL) {
        return -2;
    }

    // initialize the array of records
    *numRecords = 0;
    while (1) {
        int inputType = 0; // 0 for integer, 1 for string
        char* inputValue = NULL;
        size_t inputSize = 0;

        // read the next record from standard input
        scanf("%d", &inputType);
        if (inputType == 0) {
            int value = 0;
            scanf("%d", &value);
            (*records)[*numRecords].type = 0;
            (*records)[*numRecords].value.iValue = value;
        } else if (inputType == 1) {
            char* value = NULL;
            scanf("%ms", &value);
            (*records)[*numRecords].type = 1;
            (*records)[*numRecords].value.sValue = value;
        } else {
            break;
        }

        // validate the input size
        if (inputSize == 0 || inputSize > SIZE_MAX - sizeof(Record)) {
            return -3;
        }

        // grow the array of records if necessary
        if (*numRecords + 1 >= initialSize) {
            *records = realloc(*records, (initialSize *= 2) * sizeof(Record));
            if (*records == NULL) {
                return -4;
            }
        }

        // increment the number of records
        ++*numRecords;
    }

    return 0;
}

int filterRecords(const Record* records, size_t numRecords, int (*filter)(const Record*)) {
    // validate input sizes
    if (numRecords == 0 || records == NULL) {
        return -1;
    }

    // allocate memory for the filtered array of records
    Record* filteredRecords = malloc(numRecords * sizeof(Record));
    if (filteredRecords == NULL) {
        return -2;
    }

    // filter the array of records
    size_t numFilteredRecords = 0;
    for (size_t i = 0; i < numRecords; ++i) {
        if (filter(&records[i])) {
            filteredRecords[numFilteredRecords] = records[i];
            ++numFilteredRecords;
        }
    }

    // return the number of filtered records
    return numFilteredRecords;
}

int sumIntegers(const Record* records, size_t numRecords) {
    // validate input sizes
    if (numRecords == 0 || records == NULL) {
        return -1;
    }

    // initialize the sum to zero
