#include <algorithm>
#include <mutex>
#include <thread>
#include <future>
#include "logging.h"

using namespace std;

// Define the record structure to hold either an int or a string
struct Record {
    union {
        int i;
        char* s;
    };
    size_t size; // Store the size of the string or integer value
    bool isString; // Flag to indicate whether the field holds a string or not
};

// Define the function to initialize and fill the array of records with random values
void processRecords(size_t numRecords, size_t intRange, size_t strLength) {
    vector<Record> records; // Initialize an empty vector to store the records

    // Generate a random integer within the specified range or a random string of the specified length
    for (size_t i = 0; i < numRecords; ++i) {
        Record record;

        if (strLength > 0) {
            // Generate a random string with the specified length
            char* str = new char[strLength + 1];
            for (size_t j = 0; j < strLength; ++j) {
                str[j] = 'a' + rand() % 26;
            }
            str[strLength] = '\0';
            record.s = str;
            record.isString = true;
        } else if (intRange > 0) {
            // Generate a random integer within the specified range
            record.i = rand() % intRange + 1;
            record.isString = false;
        } else {
            // Invalid input, abort
            cout << "Invalid input" << endl;
            return;
        }

        records.push_back(record);
    }

    // Find and print the largest integer or longest string in the array of records
    findAndPrintLargest(records);

    // Release all allocated memory once the operation is complete
    for (auto& record : records) {
        if (record.isString) {
            delete[] record.s;
        }
    }
}

// Define the helper function to find and print the largest integer or longest string in the array of records
void findAndPrintLargest(vector<Record>& records) {
    // Initialize a mutex for concurrent access to the shared data
    static mutex mtx;

    // Find the largest integer or longest string in the array of records
    int maxInt = -1, maxStrLen = 0;
    bool isString = false;
    for (auto& record : records) {
        if (!record.isString) {
            if (record.i > maxInt) {
                maxInt = record.i;
            }
        } else {
            if (record.size > maxStrLen) {
                maxStrLen = record.size;
                isString = true;
            }
        }
    }

    // Print the largest integer or longest string in the array of records
    mtx.lock();
    cout << "Largest value: ";
    if (isString) {
        cout << records[records.size() - 1].s << endl;
    } else {
        cout << maxInt << endl;
    }
    mtx.unlock();
}

// Define the function to handle unexpected inputs and edge cases robustly
void processRecords(size_t numRecords, size_t intRange, size_t strLength) {
    if (numRecords == 0 || intRange == 0 && strLength == 0) {
        cout << "Invalid input" << endl;
