// Define the record structure
typedef struct {
    int type; // 0 for integer, 1 for string
    union {
        int iValue;
        char* sValue;
    };
} Record;

// Function to initialize a list of records with random values
void initRecords(Record* records, int numRecords, int range) {
    // Initialize the array of records
    for (int i = 0; i < numRecords; i++) {
        records[i].type = rand() % 2;
        if (records[i].type == 0) {
            records[i].iValue = rand() % range + 1;
        } else {
            int length = rand() % 16 + 8;
            records[i].sValue = malloc(length * sizeof(char));
            for (int j = 0; j < length; j++) {
                records[i].sValue[j] = rand() % 256;
            }
        }
    }
}

// Function to find the largest integer in a list of records
int findLargestInt(Record* records, int numRecords) {
    int max = INT_MIN;
    for (int i = 0; i < numRecords; i++) {
        if (records[i].type == 0 && records[i].iValue > max) {
            max = records[i].iValue;
        }
    }
    return max;
}

// Function to find the longest string in a list of records
int findLongestString(Record* records, int numRecords) {
    int maxLength = 0;
    for (int i = 0; i < numRecords; i++) {
        if (records[i].type == 1 && strlen(records[i].sValue) > maxLength) {
            maxLength = strlen(records[i].sValue);
        }
    }
    return maxLength;
}

// Function to release memory allocated for records
void freeRecords(Record* records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        if (records[i].type == 1) {
            free(records[i].sValue);
        }
    }
}
