                securityContext.SetEncryptionMode(CipherMode.ECB); // Replace with your desired encryption mode
                securityContext.SetKey(KEY); // Replace with your key
                securityContext.SetInitializationVector(INITIALIZATION_VECTOR); // Replace with your initialization vector

