#include <stdlib.h>
#include <stdio.h>
#include <stdint.h>

// Define custom data structure for records
typedef struct Record {
    int value;
} Record;

// Define constants for maximum number of records and keys
#define MAX_RECORDS 1000
#define MAX_KEYS 256

// Define hash function for mapping record values to key indices
uint32_t hash(int value) {
    return (value % MAX_KEYS);
}

// Define function to populate records with random integers within a specified range, associating each Record with a corresponding index in the keys array via a hash function derived from the Record's integer value
void populateRecords(Record** records, int* keys, int maxValue) {
    // Initialize arrays for records and keys
    *records = (Record*)malloc(MAX_RECORDS * sizeof(Record));
    if (*records == NULL) {
        printf("Error: memory allocation failed\n");
        return;
    }
    *keys = (int*)malloc(MAX_KEYS * sizeof(int));
    if (*keys == NULL) {
        printf("Error: memory allocation failed\n");
        free(*records);
        return;
    }

    // Initialize random number generator
    srand(time(NULL));

    // Populate records and keys
    for (int i = 0; i < MAX_RECORDS; i++) {
        Record* record = &(*records)[i];
        int keyIndex = hash(record->value);
        while (*keys[keyIndex] != NULL) {
            keyIndex = (keyIndex + 1) % MAX_KEYS;
        }
        *keys[keyIndex] = i;
        record->value = rand() % maxValue;
    }
}
