Task 1: Managing a Dynamic Data Structure
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <stdbool.h>
#include <limits.h>

// Define the data structure to hold the records
typedef struct {
    int key;
    long offset;
} Record;

// Define the hash table data structure
struct HashTable {
    // The number of buckets in the table
    size_t bucket_count;
    // The size of each bucket
    size_t bucket_size;
    // A pointer to an array of buckets
    Record **buckets;
};

// Define the record hash function
unsigned long record_hash(Record *record) {
    return (unsigned long)(record->key) % bucket_count;
}

// Define the record comparison function
bool record_equal(Record *record1, Record *record2) {
    return record1->key == record2->key && record1->offset == record2->offset;
}

// Define the hash table insertion function
int hash_table_insert(HashTable *ht, Record *record) {
    unsigned long hash = record_hash(record);
    // Check if the bucket is already full
    if (ht->buckets[hash] == NULL || ht->bucket_count < 0) {
        return -1;
    }
    // Insert the record into the bucket
    ht->buckets[hash] = record;
    return 0;
}

// Define the hash table lookup function
Record *hash_table_lookup(HashTable *ht, int key) {
    unsigned long hash = record_hash(&key);
    // Check if the bucket is empty
    if (ht->buckets[hash] == NULL || ht->bucket_count < 0) {
        return NULL;
    }
    // Look up the record in the bucket
    for (Record *record = ht->buckets[hash]; record != NULL; record = record->next) {
        if (record_equal(record, &key)) {
            return record;
        }
    }
    return NULL;
}

// Define the hash table deletion function
int hash_table_delete(HashTable *ht, int key) {
    unsigned long hash = record_hash(&key);
    // Check if the bucket is empty
    if (ht->buckets[hash] == NULL || ht->bucket_count < 0) {
        return -1;
    }
    // Find the record in the bucket and delete it
    for (Record **record = &ht->buckets[hash]; *record != NULL; *record = (*record)->next) {
        if (record_equal(*record, &key)) {
            *record = (*record)->next;
            return 0;
        }
    }
    return -1;
}

// Define the hash table initialization function
int hash_table_init(HashTable **ht) {
    // Allocate memory for the hash table
    *ht = (HashTable *)malloc(sizeof(HashTable));
    if (*ht == NULL) {
        return -1;
    }
    // Initialize the bucket count and size
    (*ht)->bucket_count = 0;
    (*ht)->bucket_size = 8;
    // Allocate memory for the buckets
    (*ht)->buckets = (Record **)calloc(sizeof(Record *), (*ht)->bucket_size);
    if ((*ht)->buckets == NULL) {
        free(*ht);
        return -1;
    }
    // Return successfully initialized hash table
    return 0;
}

// Define the hash table cleanup function
void hash_table_cleanup(HashTable *ht) {
    // Free memory for the buckets
    free(ht->buckets);
    // Free memory for the hash table
    free(ht);
}
