    // Check if the number of records is valid
    if (numRecords <= 0) {
        return NULL;
    }

    // Create an array to store the data points
    DataPoint* dataPoints = (DataPoint*)malloc(sizeof(DataPoint) * numRecords);
    if (!dataPoints) {
        return NULL;
    }

    // Initialize each data point with a random value and key
    for (int i = 0; i < numRecords; ++i) {
        dataPoints[i].value = rand() % (maxValue - minValue + 1) + minValue;
        dataPoints[i].key = 'A' + i;
    }

    // Calculate the maximum and minimum values encountered during initialization
    double maxValueEncountered = dataPoints[0].value;
    double minValueEncountered = dataPoints[0].value;
    for (int i = 1; i < numRecords; ++i) {
        if (dataPoints[i].value > maxValueEncountered) {
            maxValueEncountered = dataPoints[i].value;
        } else if (dataPoints[i].value < minValueEncountered) {
            minValueEncountered = dataPoints[i].value;
        }
    }

    // Print the maximum and minimum values encountered during initialization for statistical analysis
    printf("Maximum value encountered: %lf\n", maxValueEncountered);
    printf("Minimum value encountered: %lf\n", minValueEncountered);

    return dataPoints;
}

// Define the function to perform DNS resolution for a given hostname
int resolveDNS(char* hostname, u_char* ipAddress) {
    // Check if the hostname is valid
    if (!hostname || !ipAddress) {
        return -1;
    }

    // Perform DNS resolution using the standard library functions
    struct addrinfo hints, *result = NULL;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    if (getaddrinfo(hostname, NULL, &hints, &result) != 0) {
        return -1;
    }

    // Get the IP address from the first result
    struct in_addr* addr = &((struct sockaddr_in*)result->ai_addr)->sin_addr;
    memcpy(ipAddress, addr, sizeof(u_char) * 4);

    // Free the memory allocated for the results
    freeaddrinfo(result);

    return 0;
}

// Define the function to limit the capabilities of a process
int limitProcessCapabilities(pid_t pid, int numCores) {
    // Check if the PID is valid and the number of cores is within limits
    if (pid <= 0 || numCores < 1 || numCores > 4) {
        return -1;
    }

    // Set the CPU affinity for the process to only use a subset of the available cores
    cpu_set_t cpuset;
    CPU_ZERO(&cpuset);
    for (int i = 0; i < numCores; ++i) {
        CPU_SET(i, &cpuset);
    }
    if (sched_setaffinity(pid, sizeof(cpu_set_t), &cpuset) != 0) {
        return -1;
    }

    return 0;
}']

