#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>
#include <assert.h>

// Custom memory pool for efficient allocation and deallocation of records
struct MemoryPool {
  size_t capacity; // total number of records in the pool
  size_t used;     // number of records currently in use
  struct Record *records; // array of record structures
};

// Struct representing a single record in the array
struct Record {
  int value;
};

// Function to initialize the memory pool and allocate the initial set of records
void init_memory_pool(struct MemoryPool *pool, size_t initial_size) {
  // Allocate the initial set of records in the pool
  struct Record *records = malloc(initial_size * sizeof(struct Record));
  if (records == NULL) {
    printf("Error: unable to allocate memory for initial set of records\n");
    exit(1);
  }
  // Initialize the used counter and capacity
  pool->used = initial_size;
  pool->capacity = initial_size;
  pool->records = records;
}

// Function to add a new record to the memory pool, resizing if necessary
void add_record(struct MemoryPool *pool, int value) {
  // Check if the capacity of the pool has been reached
  if (pool->used == pool->capacity) {
    // Double the capacity of the pool
    size_t new_capacity = pool->capacity * 2;
    struct Record *new_records = realloc(pool->records, new_capacity * sizeof(struct Record));
    if (new_records == NULL) {
      printf("Error: unable to resize memory pool\n");
      exit(1);
    }
    pool->used = pool->used + 1;
    pool->capacity = new_capacity;
    pool->records = new_records;
  }
  // Add the new record to the end of the pool
  pool->records[pool->used].value = value;
  pool->used++;
}

// Function to remove a record from the memory pool, resizing if necessary
void remove_record(struct MemoryPool *pool, size_t index) {
  // Check if the index is out of bounds
  if (index >= pool->used || index < 0) {
    printf("Error: invalid index for removing record\n");
    exit(1);
  }
  // Decrement the used counter and shift all records after the removed record down by one
  pool->used--;
  for (size_t i = index; i < pool->used; i++) {
    pool->records[i] = pool->records[i + 1];
  }
}

// Function to get a record from the memory pool by its index
struct Record *get_record(struct MemoryPool *pool, size_t index) {
  // Check if the index is out of bounds
  if (index >= pool->used || index < 0) {
    printf("Error: invalid index for getting record\n");
    exit(1);
  }
  return &pool->records[index];
}

// Function to check if a record exists in the memory pool by its value
bool contains_record(struct MemoryPool *pool, int value) {
  // Iterate through all records and check if any match the given value
  for (size_t i = 0; i < pool->used; i++) {
    if (pool->records[i].value == value) {
      return true;
    }
  }
  return false;
}

// Function to update a record in the memory pool by its index, resizing if necessary
void update_record(struct MemoryPool *pool, size_t index, int value) {
  // Check if the index is out of bounds
  if (index >= pool->used || index < 0) {
    printf("Error: invalid index for updating record\n");
    exit(1);
  }
  // Update the value of the specified record and check for integrity
  pool->records[index].value = value;
  if (!check_record_integrity(pool, index)) {
    printf("Error: updated record does not match integrity check\n");
    exit(1);
  }
}

// Function to check the integrity of a single record in the memory pool by its index
bool check_record_integrity(struct MemoryPool *pool, size_t index) {
  // Calculate the expected value for the specified record based on its position and previous values
  int expected_value = calculate_expected_value(pool, index);
  // Check if the actual value of the specified record matches the expected value
  return pool->records[index].value == expected_value;
}

// Function to calculate the expected value for a single record in the memory pool by its index
int calculate_expected_value(struct MemoryPool *pool, size_t index) {
  // Calculate the sum of all previous values in the array up to the specified index
  int sum = 0;
  for (size_t i = 0; i < index; i++) {
    sum += pool->records[i].value;
  }
  return sum;
}

// Function to free all memory allocated by the memory pool
void destroy_memory_pool(struct MemoryPool *pool) {
  // Free the records array and reset the used and capacity counters
  free(pool->records);
  pool->used = 0;
  pool->capacity = 0;
}

// Function to handle edge cases for zero-sized arrays, negative indices, and out-of-memory situations
void handle_edge_cases(struct MemoryPool *pool) {
  // Check if the initial size of the memory pool is zero or negative
  if (pool->capacity == 0 || pool->capacity < 0) {
    printf("Error: invalid initial size for memory pool\n");
    exit(1);
  }
  // Check if any records have been added to the memory pool and resize if necessary
  if (pool->used > pool->capacity) {
    printf("Warning: resizing memory pool to accommodate new records\n");
    init_memory_pool(pool, pool->used);
  }
}

// Custom data structure for thread-safe concurrent access to the memory pool
struct ThreadSafeMemoryPool {
  struct MemoryPool *pool; // pointer to the actual memory pool
  pthread_mutex_t mutex;   // mutex for synchronizing access to the memory pool
};

// Function to create a new thread-safe memory pool and initialize it with the given initial size
struct ThreadSafeMemoryPool *create_thread_safe_memory_pool(size_t initial_size) {
  struct ThreadSafeMemoryPool *tsmp = malloc(sizeof(struct ThreadSafeMemoryPool));
  if (tsmp == NULL) {
    printf("Error: unable to allocate memory for thread-safe memory pool\n");
    exit(1);
  }
  tsmp->pool = malloc(sizeof(struct MemoryPool));
  if (tsmp->pool == NULL) {
    printf("Error: unable to allocate memory for underlying memory pool in thread-safe memory pool\n");
    exit(1);
  }
  init_memory_pool(tsmp->pool, initial_size);
  pthread_mutex_init(&tsmp->mutex, NULL); // initialize the mutex for synchronizing access to the memory pool
  return tsmp;
}

// Function to destroy a thread-safe memory pool and free all associated resources
void destroy_thread_safe_memory_pool(struct ThreadSafeMemoryPool *tsmp) {
  pthread_mutex_destroy(&tsmp->mutex); // destroy the mutex for synchronizing access to the memory pool
  free(tsmp->pool);                    // free the underlying memory pool
  free(tsmp);                          // free the thread-safe memory pool structure
}

// Function to add a new record to a thread-safe memory pool, resizing if necessary and synchronizing access with the mutex
void ts_add_record(struct ThreadSafeMemoryPool *tsmp, int value) {
  pthread_mutex_lock(&tsmp->mutex); // acquire the lock on the mutex for synchronizing access to the memory pool
  add_record(tsmp->pool, value);    // add the new record to the underlying memory pool
  pthread_mutex_unlock(&tsmp->mutex); // release the lock on the mutex for synchronizing access to the memory pool
}

// Function to remove a record from a thread-safe memory pool by its index, resizing if necessary and synchronizing access with the mutex
void ts_remove_record(struct ThreadSafeMemoryPool *tsmp, size_t index) {
  pthread_mutex_lock(&tsmp->mutex); // acquire the lock on the mutex for synchronizing access to the memory pool
  remove_record(tsmp->pool, index); // remove the record from the underlying memory pool
  pthread_mutex_unlock(&tsmp->mutex); // release the lock on the mutex for synchronizing access to the memory pool
}

// Function to get a record from a thread-safe memory pool by its index, synchronizing access with the mutex
struct Record *ts_get_record(struct ThreadSafeMemoryPool *tsmp, size_t index) {
  pthread_mutex_lock(&tsmp->mutex); // acquire the lock on the mutex for synchronizing access to the memory pool
  struct Record *record = get_record(tsmp->pool, index); // get the record from the underlying memory pool
  pthread_mutex_unlock(&tsmp->mutex); // release the lock on the mutex for synchronizing access to the memory pool
  return record;
}

// Function to check if a record exists in a thread-safe memory pool by its value, synchronizing access with the mutex
bool ts_contains_record(struct ThreadSafeMemoryPool *tsmp, int value) {
  pthread_mutex_lock(&tsmp->mutex); // acquire the lock on the mutex for synchronizing access to the memory pool
  bool contains = contains_record(tsmp->pool, value); // check if the record exists in the underlying memory pool
  pthread_mutex_unlock(&tsmp->mutex); // release the lock on the mutex for synchronizing access to the memory pool
  return contains;
}

// Function to update a record in a thread-safe memory pool by its index, resizing if necessary and synchronizing access with the mutex
void ts_update_record(struct ThreadSafeMemoryPool *tsmp, size_t index, int value) {
  pthread_mutex_lock(&tsmp->mutex); // acquire the lock on the mutex for synchronizing access to the memory pool
  update_record(tsmp->pool, index, value); // update the record in the underlying memory pool
  pthread_mutex_unlock(&tsmp->mutex); // release the lock on the mutex for synchronizing access to the memory pool
}

// Function to handle edge cases for thread-safe memory pools, including zero-sized arrays, negative indices, and out-of-memory situations
void ts_handle_edge_cases(struct ThreadSafeMemoryPool *tsmp) {
  pthread_mutex_lock(&tsmp->mutex); // acquire the lock on the mutex for synchronizing access to the memory pool
  handle_edge_cases(tsmp->pool);    // handle edge cases for the underlying memory pool
  pthread_mutex_unlock(&tsmp->mutex); // release the lock on the mutex for synchronizing access to the memory pool
}
