// Define the record structure
struct record {
    int type; // 0: integer, 1: string
    union {
        int i;
        char *s;
    } data;
};

// Function to initialize a record with a random integer within a specified range
void init_record_rand_int(struct record *rec, int min, int max) {
    rec->type = 0;
    rec->data.i = (rand() % (max - min + 1)) + min;
}

// Function to initialize a record with a random string of a specified length
void init_record_rand_string(struct record *rec, int len) {
    rec->type = 1;
    rec->data.s = (char *)malloc(len);
    for (int i = 0; i < len; i++) {
        rec->data.s[i] = 'a' + (rand() % 26);
    }
}

// Function to dynamically allocate memory for an array of records
struct record *alloc_records(size_t n) {
    struct record *records;
    if ((records = malloc(n * sizeof(struct record))) == NULL) {
        perror("malloc failed");
        exit(1);
    }
    return records;
}

// Function to initialize an array of records with a specified initializer function
void init_records(struct record *records, size_t n, void (*init_func)(struct record *)) {
    for (size_t i = 0; i < n; i++) {
        init_func(&records[i]);
    }
}

// Function to release memory for an array of records
void free_records(struct record *records) {
    for (size_t i = 0; i < n; i++) {
        if (records[i].type == 1) {
            free(records[i].data.s);
        }
    }
}

// Function to process a dataset of records using a graph database for managing vertex and edge relationships
void process_dataset(struct record *records, size_t n, void (*init_func)(struct record *), struct graph_database *db) {
    // Initialize the graph database with the number of vertices and edges in the dataset
    db->num_vertices = n;
    db->num_edges = 0;

    // Iterate over each record in the dataset and add it to the graph database
    for (size_t i = 0; i < n; i++) {
        init_func(&records[i]);
        if (records[i].type == 0) {
            db->edges[db->num_edges++] = records[i].data.i;
        } else {
            char *str = records[i].data.s;
            for (int j = 0; j < strlen(str); j++) {
                int c = str[j];
                if (c != ' ') {
                    db->edges[db->num_edges++] = c;
                }
            }
        }
    }
}

// Function to dynamically allocate memory for a graph database and initialize it with the number of vertices and edges in the dataset
