// Structure to represent a data point
typedef struct {
    float value; // Single float value
    double* vector; // Pointer to an array of doubles
} data_point_t;

// Function to initialize the arrays of offsets and keys
void init_arrays(int num_offsets, int num_keys) {
    long* offsets = malloc(num_offsets * sizeof(long));
    int* keys = malloc(num_keys * sizeof(int));

    // Initialize the arrays with random values
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = rand() % 10000;
    }

    for (int j = 0; j < num_keys; j++) {
        keys[j] = rand() % 10000;
    }
}

// Function to initialize the records array
void init_records(int num_records) {
    // Structure to represent a record
    typedef struct {
        int id; // Record ID
        float value; // Record value
        double* vector; // Record vector
        time_t timestamp; // Record timestamp
        char status; // Record status (0: success, 1: failure)
    } record_t;

    // Allocate memory for the records array
    record_t* records = malloc(num_records * sizeof(record_t));

    // Initialize the records with random values
    for (int i = 0; i < num_records; i++) {
        records[i].id = rand() % 10000;
        records[i].value = rand() % 10000;
        records[i].vector = malloc(rand() % 5 * sizeof(double));
        for (int j = 0; j < rand() % 5; j++) {
            records[i].vector[j] = rand() % 10000;
        }
        records[i].timestamp = time(NULL);
        records[i].status = rand() % 2;
    }
}

// Function to read and initialize the data points array
void init_data_points(int num_data_points) {
    // Structure to represent a data point
    typedef struct {
        float value; // Single float value
        double* vector; // Pointer to an array of doubles
    } data_point_t;

    // Allocate memory for the data points array
    data_point_t* data_points = malloc(num_data_points * sizeof(data_point_t));

    // Initialize the data points with random values
    for (int i = 0; i < num_data_points; i++) {
        data_points[i].value = rand() % 10000;
        data_points[i].vector = malloc(rand() % 5 * sizeof(double));
        for (int j = 0; j < rand() % 5; j++) {
            data_points[i].vector[j] = rand() % 10000;
        }
    }
}

// Function to compute the sum of all elements in an array of floats or vectors
double sum(data_point_t* data_points, int num_data_points) {
    double sum = 0.0;

    // Iterate through the array and compute the sum
    for (int i = 0; i < num_data_points; i++) {
        if (data_points[i].vector == NULL) {
            sum += data_points[i].value;
        } else {
            for (int j = 0; j < data_points[i].vector->length; j++) {
                sum += data_points[i].vector[j];
            }
        }
    }

    return sum;
}

// Function to print the sum of all elements in an array of floats or vectors
void print_sum(data_point_t* data_points, int num_data_points) {
    double sum = sum(data_points, num_data_points);

    // Print the sum
    printf("Sum: %f\n", sum);
}

int main() {
    // Initialize the arrays of offsets and keys
    int num_offsets = 10;
    int num_keys = 5;
    init_arrays(num_offsets, num_keys);

    // Initialize the records array
    int num_records = 20;
    init_records(num_records);

    // Read and initialize the data points array
    int num_data_points = 15;
    init_data_points(num_data_points);

    // Compute and print the sum of all elements in the data points array
    print_sum(data_points, num_data_points);

    return 0;
}
