// Structure to store records
typedef struct record {
    long *offset; // Pointer to a dynamically allocated long value representing an offset
    int key; // Integer key used for indexing into other data structures
    int *values; // Array of integers with size determined by the integer key, initialized with random values between 0 and 1000 (inclusive)
} record_t;

// Function to allocate memory for a record
record_t* create_record(int key) {
    record_t *record = malloc(sizeof(record_t));
    if (!record) {
        fprintf(stderr, "Failed to allocate memory for record\n");
        return NULL;
    }
    record->offset = malloc(sizeof(long));
    if (!record->offset) {
        fprintf(stderr, "Failed to allocate memory for offset\n");
        free(record);
        return NULL;
    }
    *(record->offset) = 0;
    record->key = key;
    int values_size = (key + 1) / sizeof(int);
    record->values = malloc(values_size * sizeof(int));
    if (!record->values) {
        fprintf(stderr, "Failed to allocate memory for values\n");
        free(record->offset);
        free(record);
        return NULL;
    }
    // Initialize values with random values between 0 and 1000 (inclusive)
    int i;
    for (i = 0; i < values_size; ++i) {
        record->values[i] = rand() % 1001;
    }
    return record;
}

// Function to free memory of a record
void destroy_record(record_t *record) {
    if (record == NULL) {
        return;
    }
    free(record->offset);
    free(record->values);
    free(record);
}

