    if (num_records == MAX_RECORDS) { // If the maximum number of records has been reached
        printf("Reached maximum number of records. Dropping new records...\n");
        free(arrays[MAX_RECORDS - 1]); // Drop the oldest record
    } else if (strlen(message) > MAX_MESSAGE_LENGTH) { // If the log message is too large to be stored
        printf("Log message exceeds maximum length. Truncating...\n");
        arrays[num_records]->message = strndup(message, MAX_MESSAGE_LENGTH); // Truncate the log message
    }
}

// Define the function to optimize memory usage and performance in high-load scenarios
void optimize_memory_usage(struct record **arrays, int num_records) {
    for (int i = 0; i < num_records - 1; i++) { // Loop through all records except the last one
        if (!strcmp(arrays[i]->message, arrays[i + 1]->message)) { // If the current and next records have the same log message
            free(arrays[i]); // Free the duplicate record
            arrays[i] = arrays[i + 1]; // Replace the duplicate record with the next record
        } else {
            break; // If the records are not duplicates, stop the loop
        }
    }
