// Function to print the average and largest signal strength in the array of records
void printSignalStrengthStats(int numRecords, NetworkConfig *configs) {
    double avgSignalStrength = 0.0;
    double largestSignalStrength = 0.0;

    for (int i = 0; i < numRecords; i++) {
        avgSignalStrength += configs[i].signalStrength;
        if (configs[i].signalStrength > largestSignalStrength) {
            largestSignalStrength = configs[i].signalStrength;
