#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/sha.h>

// Custom data structure to hold TIFF file information
typedef struct {
    int bitsPerSample;
    int samplePerPixel;
    int extraSamples;
    char* hash;
} TiffFileInfo;

// Function to process a TIFF image file and extract detailed information
TiffFileInfo processTiffFile(const char* filename) {
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        printf("Error: Failed to open TIFF file %s\n", filename);
        return;
    }

    // Read the TIFF header and check for errors
    TiffHeader header = readTiffHeader(fp);
    if (header.error != 0) {
        printf("Error: Failed to read TIFF header\n");
        fclose(fp);
        return;
    }

    // Extract the bits per sample, sample per pixel, and extra samples
    int bitsPerSample = header.bitsPerSample;
    int samplePerPixel = header.samplePerPixel;
    int extraSamples = 0;
    if (header.extraSamples != NULL) {
        extraSamples = header.extraSamples->length;
    }

    // Generate a SHA-256 hash of the file content
    char* hash = calloc(SHA256_DIGEST_LENGTH, sizeof(char));
    int numBytesRead = fread(hash, 1, SHA256_DIGEST_LENGTH, fp);
    if (numBytesRead != SHA256_DIGEST_LENGTH) {
        printf("Error: Failed to read %d bytes from TIFF file\n", numBytesRead);
        free(hash);
        return;
    }

    // Close the file and return the TiffFileInfo struct
    fclose(fp);
    TiffFileInfo info = {bitsPerSample, samplePerPixel, extraSamples, hash};
    return info;
}
```
This code uses the `readTiffHeader` function from the OpenSSL library to read the TIFF header and extract information about the bits per sample, sample per pixel, and any extra samples. It then generates a SHA-256 hash of the file content using the `fread` function to read the bytes in the file and the `SHA256_DIGEST_LENGTH` constant to determine how many bytes to read. Finally, it closes the file and returns a `TiffFileInfo` struct containing the extracted information and the SHA-256 hash of the file content.

This code also includes error handling to ensure that any errors encountered while reading the TIFF header or generating the SHA-256 hash are properly handled.']

