/*
 * Dynamic dataset manager for records with configurable dimensions
 */

#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <assert.h>

// Structure definition for a record
struct record {
    int value;
};

// Configuration parameters for the dataset manager
typedef struct {
    // Size of the two arrays (long offsets and int keys)
    size_t array_size;
    // Maximum number of records to store in the dataset
    size_t max_records;
} config_t;

// Global state for the dataset manager
static struct {
    // Arrays for storing long offsets and int keys
    long *offsets;
    int *keys;
    // Array of record structures
    struct record *records;
    // Number of records in the dataset
    size_t num_records;
} state = {0};

// Function to allocate and initialize memory for the two arrays and the record structures
static void init(const config_t *cfg) {
    assert(cfg != NULL);

    // Allocate memory for the two arrays and the record structures
    state.offsets = (long *)malloc(sizeof(long) * cfg->array_size);
    state.keys = (int *)malloc(sizeof(int) * cfg->max_records);
    state.records = (struct record *)malloc(sizeof(struct record) * cfg->max_records);

    // Initialize the arrays and the record structures
    for (size_t i = 0; i < cfg->array_size; i++) {
        state.offsets[i] = -1;
    }
    for (size_t i = 0; i < cfg->max_records; i++) {
        state.keys[i] = -1;
        state.records[i].value = -1;
    }

    // Set the number of records in the dataset to zero
    state.num_records = 0;
}

// Function to populate the records with unique random values within a specified range
static void populate(const config_t *cfg, int min_val, int max_val) {
    assert(cfg != NULL);
    assert(min_val <= max_val);

    // Generate random numbers within the specified range
    srand(time(NULL));
    for (size_t i = 0; i < cfg->max_records; i++) {
        int val = min_val + rand() % (max_val - min_val + 1);
        state.keys[i] = val;
        state.records[i].value = val;
    }
}

// Function to handle memory allocation failures gracefully
static void handle_error(const char *msg) {
    fprintf(stderr, "Memory allocation error: %s\n", msg);
    exit(EXIT_FAILURE);
}

// Function to synchronize access to shared resources
static void sync() {
#ifdef THREADSAFE
    // Lock the shared resources
    pthread_mutex_lock(&state.mutex);
#endif
}

// Function to release all allocated memory and reset any global state
static void cleanup() {
    if (state.offsets != NULL) {
        free(state.offsets);
        state.offsets = NULL;
    }
    if (state.keys != NULL) {
        free(state.keys);
        state.keys = NULL;
    }
    if (state.records != NULL) {
        free(state.records);
        state.records = NULL;
    }
#ifdef THREADSAFE
    // Unlock the shared resources
    pthread_mutex_unlock(&state.mutex);
#endif
}

