// Structure to represent a record
typedef struct {
    int key;
    long offset;
} Record;

// Function to allocate and initialize memory for the two arrays and the record structures
void init_memory(size_t num_records, size_t num_keys, size_t num_offsets) {
    // Allocate memory for the record array
    Record* records = malloc(num_records * sizeof(Record));
    if (records == NULL) {
        printf("Error: failed to allocate memory for the record array\n");
        exit(1);
    }
    memset(records, 0, num_records * sizeof(Record));

    // Allocate memory for the key array
    int* keys = malloc(num_keys * sizeof(int));
    if (keys == NULL) {
        printf("Error: failed to allocate memory for the key array\n");
        exit(1);
    }
    memset(keys, 0, num_keys * sizeof(int));

    // Allocate memory for the offset array
    long* offsets = malloc(num_offsets * sizeof(long));
    if (offsets == NULL) {
        printf("Error: failed to allocate memory for the offset array\n");
        exit(1);
    }
    memset(offsets, 0, num_offsets * sizeof(long));

    // Initialize the record structures
    for (size_t i = 0; i < num_records; i++) {
        records[i].key = keys[i];
        records[i].offset = offsets[i];
    }
}

// Function to populate the records with unique random values within a specified range
void populate_records(Record* records, size_t num_records, int min_value, int max_value) {
    // Seed the random number generator with the current time
    srand(time(NULL));

    // Iterate over each record and assign a unique random value within the specified range
    for (size_t i = 0; i < num_records; i++) {
        records[i].key = rand() % (max_value - min_value + 1) + min_value;
    }
}

// Function to release all allocated memory and reset any global state
void cleanup(Record* records, size_t num_records) {
    free(records);
    memset(records, 0, num_records * sizeof(Record));
}

int main() {
    // Initialize the number of records and keys
    const size_t num_records = 100;
    const size_t num_keys = 20;

    // Allocate and initialize memory for the record array
    init_memory(num_records, num_keys, num_records * sizeof(Record));

    // Populate the records with unique random values within a specified range
    populate_records(records, num_records, 0, 100);

    // Cleanup the memory
    cleanup(records, num_records);

    return 0;
}
