    int val;
    struct Node* next;
    struct Node* prev;
} Node;

// Initialize a new node with random integer value within specified range
Node* init_node(int numNodes, int valRange) {
    // Validate input sizes and allocate memory for nodes
    if (numNodes <= 0 || valRange <= 0) {
        return NULL;
    }

    Node* head = malloc(sizeof(Node));
    head->str = malloc(10 * sizeof(char));
    head->val = rand() % valRange + 1;
    head->next = NULL;
    head->prev = NULL;

    for (int i = 1; i < numNodes; i++) {
        Node* node = malloc(sizeof(Node));
        node->str = malloc(10 * sizeof(char));
        node->val = rand() % valRange + 1;
        node->next = head;
        node->prev = NULL;

        // Check for memory allocation failures and retry with exponential backoff
        if (node == NULL) {
            printf("Memory allocation failed. Retrying...\n");
            free(head);
            free(node);
            numNodes *= 2;
            i--;
            continue;
        }

        head->prev = node;
        head = node;
    }

    // Check for duplicate string values and retry with new random values if necessary
    int count = 0;
    Node* current = head;
    while (current != NULL) {
        current = current->next;
        count++;
    }

    if (count < numNodes) {
        printf("Duplicate string values found. Retrying...\n");
        free_list(head);
        return init_node(numNodes, valRange);
    }

    return head;
}

// Free all dynamically allocated memory in the linked list
void free_list(Node* head) {
    Node* current = head;

    while (current != NULL) {
        Node* next = current->next;
        free(current->str);
        free(current);
        current = next;
    }
}

// Cleanup routine to free all dynamically allocated memory upon function exit
void cleanup() {
    free_list(head);
}

