long *offsets;
int *keys;
Record *records;
int numRecords;
pthread_mutex_t mutex;

// Initialize memory for data structures and fetch initial data using the callback function
void initializeData(int numOffsets, int numKeys, void (*dataRetrievalCallback)(long* offsets, int* keys)) {
    // Allocate memory for arrays of offsets and keys
    offsets = (long*)malloc(numOffsets * sizeof(long));
    keys = (int*)malloc(numKeys * sizeof(int));

    // Fetch initial data using the callback function
    dataRetrievalCallback(offsets, keys);

    // Initialize records array and enforce uniqueness of offset-key pairs
    numRecords = 0;
    for (int i = 0; i < numOffsets; i++) {
        for (int j = 0; j < numKeys; j++) {
            Record record = {offsets[i], keys[j]};
            if (!containsRecord(record)) {
                records[numRecords++] = record;
            } else {
                printf("Duplicate offset-key pair detected. Ignoring.\n");
            }
        }
    }
}

// Check if a record is already present in the records array
bool containsRecord(Record record) {
    for (int i = 0; i < numRecords; i++) {
        if (records[i].offset == record.offset && records[i].key == record.key) {
            return true;
        }
    }
    return false;
}

// Cleanup function to free all dynamically allocated memory
void cleanup() {
    free(offsets);
    free(keys);
    free(records);
}

// Thread-safe function to fetch initial data from an external API using the given parameters and retry logic
void fetchInitialData(long* offsets, int* keys) {
    // Initialize variables for retry logic
    int numRetries = 0;
    double delayMultiplier = 1.0;
    bool retry = true;

    // Loop until successful data retrieval or retry limit reached
    while (retry && numRetries < RETRY_LIMIT) {
        // Fetch initial data using the given callback function
        dataRetrievalCallback(offsets, keys);

        // Check if there were any errors during data retrieval
        bool error = false;
        for (int i = 0; i < numOffsets; i++) {
            if (!containsOffset(offsets[i])) {
                printf("Error: offset %ld not found\n", offsets[i]);
                error = true;
            } else if (!containsKey(keys[i])) {
                printf("Error: key %d not found\n", keys[i]);
                error = true;
            }
        }

        // If there were errors, wait for a delay and retry
        if (error) {
            numRetries++;
            double delay = pow(2.0, numRetries - 1) * JITTER_FACTOR + (rand() % (int)(JITTER_FACTOR * 2));
            printf("Error during data retrieval. Retrying in %.1f seconds...\n", delay);
            sleep(delay);
        } else {
            retry = false;
        }
    }
}

// Check if an offset is already present in the offsets array
bool containsOffset(long offset) {
    for (int i = 0; i < numOffsets; i++) {
        if (offsets[i] == offset) {
            return true;
        }
    }
    return false;
}

// Check if a key is already present in the keys array
bool containsKey(int key) {
    for (int i = 0; i < numKeys; i++) {
        if (keys[i] == key) {
            return true;
        }
    }
    return false;
}

// Thread-safe function to retrieve a random subset of offsets and keys from the initial data
void retrieveRandomSubset(long* offsets, int* keys) {
    pthread_mutex_lock(&mutex);
    // Randomly select a subset of offsets and keys from the initialized records array
    for (int i = 0; i < numOffsets; i++) {
        offsets[i] = rand() % numRecords;
    }
    for (int j = 0; j < numKeys; j++) {
        keys[j] = rand() % numRecords;
    }
    pthread_mutex_unlock(&mutex);
}

// Cleanup function to free all dynamically allocated memory when the program exits
void cleanupAtExit(void) {
    atexit(cleanup);
}
