// Structures for weather stations, locations, and sensors
struct weather_station {
    char* name;
    int id;
    struct location* locations;
};

struct location {
    time_t timestamp;
    struct sensor* sensors;
};

struct sensor {
    float temperature;
    float humidity;
    float pressure;
};

// Function to dynamically allocate memory for weather stations, locations, and sensors
void allocate_weather_stations(int num_stations, int num_locations, int num_sensors) {
    // Allocate memory for the weather station array
    struct weather_station* stations = malloc(num_stations * sizeof(struct weather_station));
    if (stations == NULL) {
        printf("Error: Failed to allocate memory for weather stations\n");
        return;
    }

    // Initialize the weather station array
    for (int i = 0; i < num_stations; i++) {
        stations[i].name = malloc(sizeof(char) * 256);
        stations[i].id = i + 1;
        stations[i].locations = malloc(num_locations * sizeof(struct location));
    }

    // Allocate memory for the location array
    struct location* locations = malloc(num_stations * num_locations * sizeof(struct location));
    if (locations == NULL) {
        printf("Error: Failed to allocate memory for locations\n");
        return;
    }

    // Initialize the location array
    for (int i = 0; i < num_stations * num_locations; i++) {
        locations[i].timestamp = time(NULL);
        locations[i].sensors = malloc(num_sensors * sizeof(struct sensor));
    }

    // Allocate memory for the sensor array
    struct sensor* sensors = malloc(num_stations * num_locations * num_sensors * sizeof(struct sensor));
    if (sensors == NULL) {
        printf("Error: Failed to allocate memory for sensors\n");
        return;
    }

    // Initialize the sensor array
    for (int i = 0; i < num_stations * num_locations * num_sensors; i++) {
        sensors[i].temperature = 0.0f;
        sensors[i].humidity = 0.0f;
        sensors[i].pressure = 0.0f;
    }
}

// Function to dynamically free memory for weather stations, locations, and sensors
void free_weather_stations(struct weather_station* stations) {
    // Free the weather station array
    for (int i = 0; i < num_stations; i++) {
        free(stations[i].name);
        free(stations[i].locations);
    }
    free(stations);

    // Free the location array
    for (int i = 0; i < num_stations * num_locations; i++) {
        free(locations[i].sensors);
    }
    free(locations);

    // Free the sensor array
    for (int i = 0; i < num_stations * num_locations * num_sensors; i++) {
        free(sensors[i]);
    }
    free(sensors);
