// Define custom error codes
enum {
    DNS_SUCCESS = 0,
    DNS_QUERY_LIMIT_REACHED = 1,
    DNS_INVALID_HOSTNAME = 2,
    DNS_NETWORK_ERROR = 3,
    DNS_TIMEOUT = 4,
    DNS_UNSUPPORTED = 5,
};

// Define cache entry struct
struct CacheEntry {
    char* hostname;
    u_char ip[16];
    time_t expiration;
};

// Define caching mechanism
static struct CacheEntry** cache = NULL;
static int cacheSize = 0;
static int cacheCount = 0;

// Define query limit and max retries
#define MAX_QUERIES 100
#define RETRY_INTERVAL 250

// Function to resolve hostname and return IPv4 address as packed binary structure
u_char* resolveHostname(const char* hostname, int* err) {
    // Check if hostname is valid
    if (hostname == NULL || strlen(hostname) == 0) {
        *err = DNS_INVALID_HOSTNAME;
        return NULL;
    }

    // Check if cache exists and has room for new entry
    if (cache == NULL || cacheCount >= cacheSize) {
        // If cache is full, resize it by 25%
        if (cacheSize == 0) {
            cacheSize = 1;
        } else {
            cacheSize += cacheSize / 4;
        }
        cache = realloc(cache, sizeof(struct CacheEntry*) * cacheSize);
    }

    // Check if hostname is already cached
    for (int i = 0; i < cacheCount; i++) {
        if (strcmp(hostname, cache[i]->hostname) == 0) {
            // If cache hit, check expiration time and return IP address
            if (cache[i]->expiration > time(NULL)) {
                *err = DNS_SUCCESS;
                return cache[i]->ip;
            } else {
                // If cache entry is expired, remove it from the list
                struct CacheEntry* temp = cache[i];
                for (int j = i + 1; j < cacheCount; j++) {
                    cache[j - 1] = cache[j];
                }
                cacheCount--;
                free(temp);
            }
        }
    }

    // If cache miss, perform DNS query
    struct addrinfo* res = NULL;
    int retries = 0;
    while (retries < MAX_QUERIES) {
        if (getaddrinfo(hostname, NULL, NULL, &res) != 0) {
            *err = DNS_NETWORK_ERROR;
            break;
        }
        for (struct addrinfo* p = res; p != NULL; p = p->ai_next) {
            if (p->ai_family == AF_INET) {
                // If IPv4 address is found, store it in cache and return
                struct CacheEntry* newEntry = malloc(sizeof(struct CacheEntry));
                newEntry->hostname = strdup(hostname);
                memcpy(newEntry->ip, p->ai_addr, 16);
                newEntry->expiration = time(NULL) + CACHE_EXPIRATION;
                cache[cacheCount++] = newEntry;
                *err = DNS_SUCCESS;
                return newEntry->ip;
            } else if (p->ai_family == AF_INET6 && ipv6Only) {
                // If IPv6-only mode is enabled and an IPv6 address is found, store it in cache and return
                struct CacheEntry* newEntry = malloc(sizeof(struct CacheEntry));
                newEntry->hostname = strdup(hostname);
                memcpy(newEntry->ip, p->ai_addr, 16);
                newEntry->expiration = time(NULL) + CACHE_EXPIRATION;
                cache[cacheCount++] = newEntry;
                *err = DNS_SUCCESS;
                return newEntry->ip;
            }
        }
        freeaddrinfo(res);
        retries++;
        usleep(RETRY_INTERVAL * 1000); // Retry interval in microseconds
    }
    *err = DNS_TIMEOUT;
    return NULL;
}

// Function to refresh cache entry expiration time
void refreshCacheEntry(const char* hostname) {
    for (int i = 0; i < cacheCount; i++) {
        if (strcmp(hostname, cache[i]->hostname) == 0) {
            // Update cache entry expiration time and return
            cache[i]->expiration = time(NULL) + CACHE_EXPIRATION;
            break;
        }
    }
}

// Function to remove cache entry for a given hostname
void removeCacheEntry(const char* hostname) {
    for (int i = 0; i < cacheCount; i++) {
        if (strcmp(hostname, cache[i]->hostname) == 0) {
            // Remove cache entry and return
            struct CacheEntry* temp = cache[i];
            for (int j = i + 1; j < cacheCount; j++) {
                cache[j - 1] = cache[j];
            }
            cacheCount--;
            free(temp);
        }
    }
}

// Function to clean up cache entries that have expired
void cleanupCache() {
    time_t currentTime = time(NULL);
    for (int i = 0; i < cacheCount; i++) {
        if (cache[i]->expiration <= currentTime) {
            // Remove cache entry and return
            struct CacheEntry* temp = cache[i];
            for (int j = i + 1; j < cacheCount; j++) {
                cache[j - 1] = cache[j];
            }
            cacheCount--;
            free(temp);
        }
    }
}
