        record.value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        pool->records[i] = record;
    }
}

void destroy_memory_pool(struct memory_pool *pool) {
    free(pool->offsets);
    free(pool->keys);
    free(pool->records);
}

int add_record(struct memory_pool *pool, Record record) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->num_records >= MAX_RECORDS) {
        fprintf(stderr, "Error: unable to add record to pool\n");
        pthread_mutex_unlock(&pool->mutex);
        return -1;
    }
    int offset = pool->offset_index++;
    long key = pool->keys[pool->key_index++];
    if (pool->key_index == MAX_KEYS) {
        pool->key_index = 0;
    }
    pool->records[offset].value = record.value;
    pool->num_records++;
    pthread_mutex_unlock(&pool->mutex);
    return offset;
}

Record get_record(struct memory_pool *pool, int offset) {
    pthread_mutex_lock(&pool->mutex);
    Record record = pool->records[offset];
    pthread_mutex_unlock(&pool->mutex);
    return record;
}

void update_record(struct memory_pool *pool, int offset, Record record) {
    pthread_mutex_lock(&pool->mutex);
    pool->records[offset] = record;
    pthread_mutex_unlock(&pool->mutex);
}

void remove_record(struct memory_pool *pool, int offset) {
    pthread_mutex_lock(&pool->mutex);
    Record record = pool->records[offset];
    for (int i = offset; i < MAX_RECORDS - 1; i++) {
        pool->records[i] = pool->records[i + 1];
    }
    pool->num_records--;
    pthread_mutex_unlock(&pool->mutex);
}
