    if (num_records > 1000 || max_size > UINT_MAX) {
        return;
    }

    // Allocate memory for the arrays and records
    record_t *mem = malloc(sizeof(record_t) * num_records);
    if (!mem) {
        // Log an error message and return
        fprintf(stderr, "Failed to allocate memory\n");
        return;
    }
    memset(mem, 0, sizeof(record_t) * num_records);

    // Initialize the arrays and records
    for (size_t i = 0; i < num_records; i++) {
        mem[i].key = malloc(sizeof(int) * max_size);
        if (!mem[i].key) {
            fprintf(stderr, "Failed to allocate memory for key\n");
            return;
        }
        memset(mem[i].key, 0, sizeof(int) * max_size);

        mem[i].offset = malloc(sizeof(long) * max_size);
        if (!mem[i].offset) {
            fprintf(stderr, "Failed to allocate memory for offset\n");
            return;
        }
        memset(mem[i].offset, 0, sizeof(long) * max_size);
    }

    // Initialize the random number generator with the current time
    srand((unsigned int)time(NULL));

    // Populate the arrays and records with random values
    for (size_t i = 0; i < num_records; i++) {
        for (size_t j = 0; j < max_size; j++) {
            mem[i].key[j] = rand() % INT_MAX;
            mem[i].offset[j] = rand() % LONG_MAX;
        }
    }

    // Assign the pointers to the caller
    *records = mem;
}

void free_mem(record_t **records) {
    // Ensure input parameters are valid
    if (!records || !(*records)) {
        return;
    }

    // Free the memory allocated for the arrays and records
    for (size_t i = 0; i < (*records)->num_records; i++) {
        free((*records)[i].key);
        free((*records)[i].offset);
    }
    free(*records);
}
