#include <stdlib.h>
#include <pthread.h>
#include <string.h>

// Define a structure to represent a record in the collection
typedef struct {
  int value;
  void* key;
} Record;

// Define a linked list node to store records in the collection
typedef struct Node {
  Record record;
  struct Node* next;
} Node;

// Define a hash table to map keys to nodes in the collection
typedef struct {
  size_t capacity;
  size_t count;
  Node** buckets;
} HashTable;

// Define a synchronization mechanism for managing concurrent accesses
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a function to create a new node in the collection
Node* create_node(Record record) {
  Node* node = malloc(sizeof(Node));
  if (!node) {
    perror("create_node");
    exit(1);
  }
  memcpy(&node->record, &record, sizeof(Record));
  node->next = NULL;
  return node;
}

// Define a function to add a record to the collection
void insert(HashTable* hash_table, Record record) {
  pthread_mutex_lock(&mutex);
  // Check if the key already exists in the collection
  Node** bucket = &hash_table->buckets[record.key % hash_table->capacity];
  while (*bucket != NULL && (*bucket)->record.key != record.key) {
    bucket = &(*bucket)->next;
  }
  if (*bucket == NULL) {
    // Create a new node and add it to the end of the linked list
    Node* node = create_node(record);
    *bucket = node;
    hash_table->count++;
  } else {
    // Update the value of an existing node
    (*bucket)->record.value = record.value;
  }
  pthread_mutex_unlock(&mutex);
}

// Define a function to remove a record from the collection
void delete(HashTable* hash_table, void* key) {
  pthread_mutex_lock(&mutex);
  // Find the node corresponding to the given key
  Node** bucket = &hash_table->buckets[key % hash_table->capacity];
  while (*bucket != NULL && (*bucket)->record.key != key) {
    bucket = &(*bucket)->next;
  }
  if (*bucket == NULL) {
    pthread_mutex_unlock(&mutex);
    return;
  }
  // Remove the node from the linked list and free its memory
  Node* node = *bucket;
  *bucket = node->next;
  hash_table->count--;
  free(node);
  pthread_mutex_unlock(&mutex);
}

// Define a function to retrieve a record from the collection
void* get(HashTable* hash_table, void* key) {
  pthread_mutex_lock(&mutex);
  // Find the node corresponding to the given key
  Node** bucket = &hash_table->buckets[key % hash_table->capacity];
  while (*bucket != NULL && (*bucket)->record.key != key) {
    bucket = &(*bucket)->next;
  }
  if (*bucket == NULL) {
    pthread_mutex_unlock(&mutex);
    return NULL;
  }
  // Return the value of the found node
  Record* record = &(*bucket)->record;
  pthread_mutex_unlock(&mutex);
  return record->value;
}

// Define a function to resize the collection when its capacity is exceeded
void resize(HashTable* hash_table) {
  size_t new_capacity = hash_table->capacity * 2;
  HashTable* new_hash_table = malloc(sizeof(HashTable));
  if (!new_hash_table) {
    perror("resize");
    exit(1);
  }
  // Create a new linked list for each bucket in the new hash table
  new_hash_table->buckets = calloc(new_capacity, sizeof(Node*));
  if (!new_hash_table->buckets) {
    perror("resize");
    exit(1);
  }
  // Copy all records from the old hash table to the new one
  pthread_mutex_lock(&mutex);
  for (size_t i = 0; i < hash_table->capacity; i++) {
    Node* node = hash_table->buckets[i];
    while (node != NULL) {
      // Add the record to the new linked list and increment the count
      insert(new_hash_table, node->record);
      node = node->next;
    }
  }
  pthread_mutex_unlock(&mutex);
  free(hash_table->buckets);
  hash_table->capacity = new_capacity;
}

// Define a function to periodically compact the collection and reduce fragmentation
