// Define structure for event record
struct EventRecord {
    int id;
    long offset;
};

// Define hybrid data structure for storing events
struct HybridDataStructure {
    struct EventRecord* array;
    struct LinkedList* linked_list;
};

// Function to manage dynamic memory allocation for high-throughput event processing system
void manageDynamicMemoryAllocation(struct HybridDataStructure* ds, int id, long offset) {
    // Check if current load is above a certain threshold
    if (currentLoad > 80) {
        // If so, switch to linked list implementation
        ds->linked_list = malloc(sizeof(struct LinkedList));
        // Insert event record into linked list
        insertRecordIntoLinkedList(ds->linked_list, id, offset);
    } else {
        // Otherwise, switch to array implementation
        ds->array = realloc(ds->array, sizeof(struct EventRecord) * (currentSize + 1));
        // Insert event record into array
        insertRecordIntoArray(ds->array, id, offset);
    }

    // Update current load and size of hybrid data structure
    currentLoad += 1;
    currentSize += 1;
}

// Function to insert event record into linked list
void insertRecordIntoLinkedList(struct LinkedList* ll, int id, long offset) {
    // Create new node for event record
    struct Node* new_node = malloc(sizeof(struct Node));
    new_node->id = id;
    new_node->offset = offset;
    new_node->next = NULL;

    // Check if linked list is empty
    if (ll->head == NULL) {
        ll->head = new_node;
    } else {
        struct Node* curr_node = ll->head;
        while (curr_node->next != NULL) {
            curr_node = curr_node->next;
        }
        curr_node->next = new_node;
    }
}

// Function to insert event record into array
void insertRecordIntoArray(struct EventRecord* arr, int id, long offset) {
    // Check if array is full
    if (arr == NULL || arr[currentSize].id != 0) {
        arr = realloc(arr, sizeof(struct EventRecord) * (currentSize + 1));
    }
    // Insert event record into array
    arr[currentSize].id = id;
    arr[currentSize].offset = offset;
}

// Function to remove event record from hybrid data structure
void removeRecordFromHybridDataStructure(struct HybridDataStructure* ds, int id) {
    // Check if linked list implementation is in use
    if (ds->linked_list != NULL) {
        // Remove event record from linked list
        removeRecordFromLinkedList(ds->linked_list, id);
    } else {
        // Otherwise, check if array implementation is in use
        if (ds->array != NULL) {
            // Remove event record from array
            removeRecordFromArray(ds->array, id);
        }
    }
}

// Function to remove event record from linked list
void removeRecordFromLinkedList(struct LinkedList* ll, int id) {
    struct Node* prev_node = NULL;
    struct Node* curr_node = ll->head;

    // Check if head node is the target node
    if (curr_node != NULL && curr_node->id == id) {
        ll->head = curr_node->next;
        free(curr_node);
        return;
    }

    while (curr_node != NULL && curr_node->id != id) {
        prev_node = curr_node;
        curr_node = curr_node->next;
    }

    // Check if target node is in linked list
    if (curr_node == NULL) {
        return;
    }

    // Remove target node from linked list
    prev_node->next = curr_node->next;
    free(curr_node);
}

// Function to remove event record from array
void removeRecordFromArray(struct EventRecord* arr, int id) {
    // Check if array is empty
    if (arr == NULL || arr[currentSize].id != 0) {
        return;
    }
    // Remove event record from array
    for (int i = 0; i < currentSize; i++) {
        if (arr[i].id == id) {
            // Shift subsequent elements to fill the gap
            for (int j = i; j < currentSize - 1; j++) {
                arr[j] = arr[j + 1];
            }
            break;
