    if (node == NULL) {
        return;
    }
    // Remove record from cache
    for (int i = 0; i < current_cache_size; i++) {
        if (cache[i] == node) {
            // Shift subsequent records to fill the gap
            for (int j = i; j < current_cache_size - 1; j++) {
                cache[j] = cache[j + 1];
            }
            break;
        }
    }
}

// Function to remove least recently used record from caching layer
void removeLRURecordFromCache() {
    // Check if cache is empty
    if (current_cache_size == 0) {
        return;
    }
    // Remove least recently used record from cache
    struct Node* lru_node = cache[current_cache_size - 1];
    removeRecordFromCache(lru_node);
}
