#define MAX_OFFSET_ARRAY_SIZE 50000
#define MAX_KEY_ARRAY_SIZE 100000
#define MAX_RECORD_STRUCT_SIZE 2048
#define MAX_DATA_POINT_STRUCT_SIZE 65536
#define MAX_FREQUENCY_MAP_SIZE 1000000
#define MAX_DATA_POINTS_TO_INITIALIZE 10000000

struct offset {
    long value;
};

struct key {
    int value;
