typedef struct frequency_map {
    size_t size;
    pthread_mutex_t mutex;
    void** entries;
} frequency_map;

void init_frequency_map(frequency_map* map) {
    map->size = 0;
    map->entries = malloc(sizeof(void*) * MAX_FREQUENCY_MAP_SIZE);
    pthread_mutex_init(&(map->mutex), NULL);
}

void add_entry_to_frequency_map(frequency_map* map, void* entry) {
    pthread_mutex_lock(&(map->mutex));
    if (map->size == MAX_FREQUENCY_MAP_SIZE) {
        pthread_mutex_unlock(&(map->mutex));
        return;
    }
    map->entries[map->size++] = entry;
    pthread_mutex_unlock(&(map->mutex));
}

void remove_entry_from_frequency_map(frequency_map* map, void* entry) {
    pthread_mutex_lock(&(map->mutex));
    size_t i = 0;
    for (i = 0; i < map->size; i++) {
        if (map->entries[i] == entry) {
            memcpy(&(map->entries[i]), &(map->entries[i + 1]), sizeof(void*) * (map->size - i));
            map->size--;
            break;
        }
    }
    pthread_mutex_unlock(&(map->mutex));
}

