    pool->record_struct_size = 0;
    pool->data_point_struct_size = 0;
    pool->frequency_map_size = 0;
    pool->data_points_to_initialize = 0;
    pool->offsets = malloc(sizeof(struct offset) * MAX_OFFSET_ARRAY_SIZE);
    pool->keys = malloc(sizeof(struct key) * MAX_KEY_ARRAY_SIZE);
    pool->records = malloc(sizeof(struct record) * MAX_RECORD_STRUCT_SIZE);
    pool->data_points = malloc(sizeof(struct data_point) * MAX_DATA_POINT_STRUCT_SIZE);
    init_frequency_map(&(pool->frequency_map));
}

void add_offset_to_memory_pool(struct memory_pool* pool, long offset) {
    if (pool->offset_array_size == MAX_OFFSET_ARRAY_SIZE) {
        return;
    }
    pool->offsets[pool->offset_array_size++] = offset;
}

void add_key_to_memory_pool(struct memory_pool* pool, int key) {
    if (pool->key_array_size == MAX_KEY_ARRAY_SIZE) {
        return;
    }
    pool->keys[pool->key_array_size++] = key;
}

void add_record_to_memory_pool(struct memory_pool* pool, int value, float data_point) {
    if (pool->record_struct_size == MAX_RECORD_STRUCT_SIZE) {
        return;
    }
    pool->records[pool->record_struct_size++] = (struct record){value, data_point};
}

void add_data_point_to_memory_pool(struct memory_pool* pool, int index, double* vector) {
    if (pool->data_point_struct_size == MAX_DATA_POINT_STRUCT_SIZE) {
        return;
    }
    pool->data_points[pool->data_point_struct_size++] = (struct data_point){index, vector};
}

void add_entry_to_frequency_map(struct memory_pool* pool, void* entry) {
    add_entry_to_frequency_map(&(pool->frequency_map), entry);
}

void remove_entry_from_frequency_map(struct memory_pool* pool, void* entry) {
