// Define a record structure to hold either an int or char* value
typedef struct {
    void *value;
} record_t;

// Function to read the list of integers and strings from standard input, dynamically allocating memory for the array of records
int read_records(record_t **records, int *num_records) {
    // Define variables to store the number of records and the size of each record
    int num_records = 0;
    size_t record_size = sizeof(record_t);

    // Read the number of records from standard input
    scanf("%d", &num_records);

    // Allocate memory for the array of records
    *records = (record_t *)malloc(record_size * num_records);
    if (*records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        return -1;
    }

    // Initialize the array of records with random integers or strings
    int i;
    for (i = 0; i < num_records; i++) {
        if (rand() % 2 == 0) {
            (*records)[i].value = malloc(sizeof(int));
            *((int *)(*records)[i].value) = rand() % INT_MAX + 1;
        } else {
            size_t str_len = rand() % 20 + 1;
            char *str = (char *)malloc(str_len);
            memset(str, 'a', str_len - 1);
            str[str_len - 1] = '\0';
            (*records)[i].value = str;
        }
    }

    // Return the number of records and the array of records
    *num_records = num_records;
    return 0;
}

// Function to filter records based on specific criteria, such as selecting only those records containing integers greater than a specified threshold or strings longer than a certain length.
int filter_records(record_t **records, int *num_records, int threshold) {
    // Define variables to store the number of filtered records and the size of each record
    int num_filtered = 0;
    size_t record_size = sizeof(record_t);

    // Allocate memory for the array of filtered records
    *records = (record_t *)malloc(record_size * num_filtered);
    if (*records == NULL) {
        fprintf(stderr, "Failed to allocate memory for filtered records\n");
        return -1;
    }

    // Filter the records based on the specified criteria
    int i;
    for (i = 0; i < *num_records; i++) {
        if (threshold == INT_MAX) {
            (*records)[i].value = malloc(sizeof(int));
            *((int *)(*records)[i].value) = rand() % INT_MAX + 1;
        } else {
            size_t str_len = rand() % 20 + 1;
            char *str = (char *)malloc(str_len);
            memset(str, 'a', str_len - 1);
            str[str_len - 1] = '\0';
            (*records)[i].value = str;
        }
    }

    // Return the number of filtered records and the array of filtered records
    *num_filtered = num_filtered;
    return 0;
}

// Function to find and print the largest integer in the array of records if they are integers, or the longest string if they are strings.
int print_largest(record_t **records, int *num_records) {
    // Define variables to store the largest value and its type
    void *largest = NULL;
    char *type = "";

    // Iterate over the array of records and find the largest value
    int i;
    for (i = 0; i < *num_records; i++) {
        if (largest == NULL) {
            largest = (*records)[i].value;
            type = "int";
        } else {
            if (strcmp((*records)[i].value, largest) > 0) {
                largest = (*records)[i].value;
                type = "string";
            }
        }
    }

    // Print the largest value and its type
    printf("Largest %s is: ", type);
    if (type == "int") {
        printf("%d\n", *((int *)largest));
    } else {
        printf("%s\n", (char *)largest);
    }

    // Free the memory allocated for the array of records and return
    free(*records);
    *records = NULL;
    return 0;
}

// Function to execute a command using system or a similar POSIX function, delete a file if it exists before executing the command, and read the output and error streams using popen and fgets.
int execute_command(const char *command) {
    // Define variables to store the file descriptor for the output stream and the error stream
    FILE *output = NULL;
    FILE *error = NULL;

    // Check if the file exists before executing the command
    struct stat buffer;
    if (stat(command, &buffer) != 0) {
        fprintf(stderr, "File does not exist\n");
        return -1;
    }

    // Delete the file if it exists before executing the command
    int result = remove(command);
    if (result != 0) {
        fprintf(stderr, "Failed to delete file\n");
        return -1;
    }

    // Execute the command using system or a similar POSIX function
    output = popen(command, "r");
    if (output == NULL) {
        fprintf(stderr, "Failed to execute command\n");
        return -1;
    }

    // Read the output stream and print it to standard output
    char line[1024];
    while (fgets(line, 1024, output) != NULL) {
        printf("%s", line);
    }

    // Close the output stream and read the error stream using fgets
    pclose(output);
    error = popen("2>&1", "r");
    if (error == NULL) {
        fprintf(stderr, "Failed to read error stream\n");
        return -1;
    }
    while (fgets(line, 1024, error) != NULL) {
        printf("%s", line);
    }

    // Free the memory allocated for the output and error streams and return
    free(output);
    free(error);
    return 0;
}
