// Record structure to store integer values
typedef struct {
    int value;
} Record;

// Function to process a list of integers
void process_integers(int num_records, int min_value, int max_value) {
    // Validate input parameters
    if (num_records < 0 || min_value > max_value) {
        printf("Invalid input parameters\n");
        return;
    }

    // Allocate memory for the array of records
    Record *records = malloc(sizeof(Record) * num_records);
    if (records == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize each record with a random value within the specified range
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Calculate and print the count of records whose values exceed a specified threshold
    int threshold = 50;
    int count = 0;
    for (int i = 0; i < num_records; i++) {
        if (records[i].value > threshold) {
            count++;
        }
    }
    printf("Count of records with values exceeding %d: %d\n", threshold, count);

    // Free the memory allocated for the array of records
    free(records);
}

int main() {
    process_integers(10, 1, 100);
    return 0;
}
