std::mt19937 gen(rd());
std::uniform_int_distribution<> distr(0, 100);

// Function to initialize attack types and manage memory
void initAttackTypes(std::vector<std::string>& attackTypes) {
    // Read user-specified parameters for initializing attack types
    std::ifstream ifs("attack_types.txt");
    while (ifs >> attackType) {
        attackTypes.push_back(attackType);
    }
    ifs.close();

    // Allocate memory for attack types and fetch latest priorities from API
    std::vector<int> priorities = fetchAttackPriorities();

    // Initialize attack type cooldown periods and random number generator
    prevAttackTime = std::chrono::steady_clock::now();
    for (int i = 0; i < priorities.size(); ++i) {
        attackTypes[i].cooldownDuration = priorities[i] * 1000; // ms to s
        attackTypes[i].randomSeed = distr(gen);
    }
}

// Function to manage attack type selection and cooldown periods
std::string executeRandomAttackSequence(std::vector<std::string>& attackTypes) {
    std::unique_lock<std::mutex> lock(mtx);
    while (true) {
        // Sleep until the next cooldown period is over or a new attack is needed
        std::this_thread::sleep_until(prevAttackTime + std::chrono::seconds(9));

        // Select a random attack type and update the previous attack time
        int attackTypeIndex = distr(gen) % attackTypes.size();
        prevAttackTime = std::chrono::steady_clock::now();

        return attackTypes[attackTypeIndex].name;
    }
}

