        if (keys != NULL) {
            delete[] keys;
            keys = NULL;
        }
        if (offsets != NULL) {
            delete[] offsets;
            offsets = NULL;
        }
        if (records != NULL) {
            for (int i = 0; i < SIZE; i++) {
                Record* rec = records + i;
                if (rec->ptr_backref != NULL) {
                    delete rec->ptr_backref;
                }
            }
            delete[] records;
            records = NULL;
        }
    }
};

// Define Record struct for storing integer values and pointers to keys and offsets
struct Record {
    int value;
    int* ptr_backref;
    long* ptr_offset;
};

// Function to initialize and load state from file
MoSTState* initializeAndLoadState(int size, int seed) {
    MoSTState* state = new MoSTState();

    // Allocate memory for arrays
    state->keys = (int*)calloc(size, sizeof(int));
    state->offsets = (long*)calloc(size, sizeof(long));
    state->records = (Record*)calloc(size, sizeof(Record));

    // Initialize offsets and keys arrays using the provided seed
    srand(seed);
    for (int i = 0; i < size; i++) {
        state->offsets[i] = rand() % 1000 - 500;
        state->keys[i] = i + 1;
    }

    // Populate records array with random integer values within the range (-1000, 1000)
    for (int i = 0; i < size; i++) {
        Record* rec = state->records + i;
        rec->value = rand() % 2000 - 1000;
        rec->ptr_backref = state->keys + i;
        rec->ptr_offset = state->offsets + i;
    }

    // Load state from file using ObjectInputStream
    try {
        FileInputStream fis(filename);
        ObjectInputStream ois(fis);
        MoSTState* loaded_state = (MoSTState*)ois.readObject();
        if (loaded_state != NULL && loaded_state->getClass() == MoSTState::class) {
            delete state;
            return loaded_state;
        } else {
            throw IOException("Error loading state from file");
        }
    } catch (IOException& e) {
        // Handle exception by freeing allocated memory and returning NULL
        if (state != NULL) {
            delete[] state->keys;
            state->keys = NULL;
            delete[] state->offsets;
            state->offsets = NULL;
            for (int i = 0; i < size; i++) {
                Record* rec = state->records + i;
                if (rec->ptr_backref != NULL) {
                    delete rec->ptr_backref;
                }
            }
            delete[] state->records;
            state->records = NULL;
        }
        return NULL;
    }
}

// Function to manage theme caching for the mobile application
void manageThemeCaching(MoSTState* state) {
    // Check if a theme bitmap is recycled and set it to null if necessary
    Bitmap* theme_bitmap = (Bitmap*)state->recycle();
    if (theme_bitmap != NULL) {
        delete theme_bitmap;
        theme_bitmap = NULL;
    }

    // Verify if a default theme directory is set and initialize it with the specified default value if not set
    if (!state->defaultThemeDirSet()) {
        state->setDefaultThemeDir(DEFAULT_THEME_DIR);
    }

    // Parse a PNG file from the cache root directory and store it in the theme cache
    try {
        FileInputStream fis(filename);
        ObjectInputStream ois(fis);
        Bitmap* theme_bitmap = (Bitmap*)ois.readObject();
        state->setThemeCache(theme_bitmap);
    } catch (IOException& e) {
        // Handle exception by freeing allocated memory and returning NULL
        if (state != NULL) {
            delete[] state->keys;
            state->keys = NULL;
            delete[] state->offsets;
            state->offsets = NULL;
            for (int i = 0; i < size; i++) {
                Record* rec = state->records + i;
                if (rec->ptr_backref != NULL) {
                    delete rec->ptr_backref;
                }
            }
            delete[] state->records;
            state->records = NULL;
        }
        return NULL;
    }
}
