#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <float.h>
#include <math.h>
#include <sys/time.h>

typedef struct {
    int integer;
    float float_number;
    char *string;
} entry;

void read_input(int n, int num_types, entry **entries) {
    // Initialize the entries array with n elements
    (*entries) = (entry *)malloc(sizeof(entry) * n);

    for (int i = 0; i < n; i++) {
        // Read a line from standard input and store it in the current entry
        char line[1024];
        fgets(line, 1024, stdin);

        // Tokenize the line using spaces as delimiters
        char *token = strtok(line, " ");

        // Read the integer value from the token
        (*entries)[i].integer = atoi(token);

        // Advance to the next token and read the float value
        token = strtok(NULL, " ");
        (*entries)[i].float_number = (float)atof(token);

        // Advance to the next token and read the string value
        token = strtok(NULL, " ");
        (*entries)[i].string = (char *)malloc(strlen(token) + 1);
        strcpy((*entries)[i].string, token);
    }
}

void free_input(int n, entry **entries) {
    for (int i = 0; i < n; i++) {
        free((*entries)[i].string);
    }
    free(*entries);
}

entry *read_and_initialize_entries() {
    // Get the number of entries to initialize from standard input
    int n;
    scanf("%d", &n);

    // Initialize an array of entries with the specified number of elements
    entry *entries = (entry *)malloc(sizeof(entry) * n);

    read_input(n, 3, &entries);

    return entries;
}

void print_largest_integer(int num_entries, entry *entries) {
    int largest_integer = INT_MIN;

    for (int i = 0; i < num_entries; i++) {
        if ((*entries)[i].integer > largest_integer) {
            largest_integer = (*entries)[i].integer;
        }
    }

    printf("The largest integer is: %d\n", largest_integer);
}

void print_max_value(int num_entries, entry *entries) {
    float max_value = FLT_MIN;

    for (int i = 0; i < num_entries; i++) {
        if ((*entries)[i].float_number > max_value) {
            max_value = (*entries)[i].float_number;
        }
    }

    printf("The maximum value is: %f\n", max_value);
}

void print_largest_string(int num_entries, entry *entries) {
    char *largest_string = "";

    for (int i = 0; i < num_entries; i++) {
        if (strlen((*entries)[i].string) > strlen(largest_string)) {
            largest_string = (*entries)[i].string;
        }
    }

    printf("The longest string is: %s\n", largest_string);
}

void print_all_values(int num_entries, entry *entries) {
    for (int i = 0; i < num_entries; i++) {
        printf("Entry %d:\n", i + 1);
        printf("\tInteger: %d\n", (*entries)[i].integer);
        printf("\tFloat: %f\n", (*entries)[i].float_number);
        printf("\tString: %s\n", (*entries)[i].string);
    }
}

void set_random_values(int num_entries, entry *entries) {
    for (int i = 0; i < num_entries; i++) {
        // Generate a random integer value between 1 and 10
        (*entries)[i].integer = rand() % 10 + 1;

        // Generate a random float value between 1.0 and 10.0
        (*entries)[i].float_number = ((float)rand() / (RAND_MAX)) * 10.0f;

        // Generate a random string with length equal to the integer value
        char rand_string[(*entries)[i].integer];
        for (int j = 0; j < (*entries)[i].integer; j++) {
            rand_string[j] = 'a' + (rand() % 26);
        }
        (*entries)[i].string = (char *)malloc(strlen(rand_string) + 1);
        strcpy((*entries)[i].string, rand_string);
    }
}

void serialize_data(int num_entries, entry *entries, char *filepath) {
    // Open the file for writing in binary mode
    FILE *fp = fopen(filepath, "wb");

    if (fp == NULL) {
        printf("Error: Could not open file for writing\n");
        return;
    }

    // Write the number of entries to the beginning of the file
    int num_entries_written = fwrite(&num_entries, sizeof(int), 1, fp);

    if (num_entries_written != 1) {
        printf("Error: Could not write number of entries to file\n");
        return;
    }

    // Write the entries to the file
    for (int i = 0; i < num_entries; i++) {
        entry current_entry = (*entries)[i];
        int entry_written = fwrite(&current_entry, sizeof(entry), 1, fp);
        if (entry_written != 1) {
            printf("Error: Could not write entry %d to file\n", i + 1);
            return;
        }
    }

    // Close the file
    fclose(fp);
}

void deserialize_data(int *num_entries, entry **entries, char *filepath) {
    // Open the file for reading in binary mode
    FILE *fp = fopen(filepath, "rb");

    if (fp == NULL) {
        printf("Error: Could not open file for reading\n");
        return;
    }

    // Read the number of entries from the beginning of the file
    int num_entries_read = fread(num_entries, sizeof(int), 1, fp);

    if (num_entries_read != 1) {
        printf("Error: Could not read number of entries from file\n");
        return;
    }

    // Allocate memory for the entries array
    (*entries) = (entry *)malloc(sizeof(entry) * (*num_entries));

    // Read the entries from the file
    for (int i = 0; i < (*num_entries); i++) {
        entry current_entry = {};
        int entry_read = fread(&current_entry, sizeof(entry), 1, fp);
        if (entry_read != 1) {
            printf("Error: Could not read entry %d from file\n", i + 1);
            return;
        }
        (*entries)[i] = current_entry;
    }

    // Close the file
    fclose(fp);
}

void monitor_performance() {
    // Get the number of CPU cores available
    int num_cores = sysconf(_SC_NPROCESSORS_ONLN);

    // Get the current time in milliseconds
    struct timeval start, end;
    gettimeofday(&start, NULL);

    // Perform the task here

    // Get the current time in milliseconds
    gettimeofday(&end, NULL);

    // Calculate the elapsed time in seconds
    long seconds = (end.tv_sec - start.tv_sec) * 1000;
    long milliseconds = (end.tv_usec - start.tv_usec) / 1000;

    // Print the performance metrics
    printf("Elapsed time: %ld s, %ld ms\n", seconds, milliseconds);
}

int main() {
    int num_entries = 0;
    entry *entries = NULL;

    // Read and initialize the entries from standard input
    read_and_initialize_entries(&num_entries, &entries);

    monitor_performance();

    // Print the largest integer in the array of entries
    print_largest_integer(num_entries, entries);

    monitor_performance();

    // Print the maximum value across all data types stored within each entry
    print_max_value(num_entries, entries);

    monitor_performance();

    // Print the largest string in the array of entries
    print_largest_string(num_entries, entries);

    monitor_performance();

    // Print all values stored within each entry
    print_all_values(num_entries, entries);

    monitor_performance();

    // Set the value of each entry's fields to random values within specified ranges for each data type
    set_random_values(num_entries, &entries);

    monitor_performance();

    // Serialize the data to a file
    serialize_data(num_entries, &entries, "data.bin");

    monitor_performance();

    // Deserialize the data from the file
    deserialize_data(&num_entries, &entries, "data.bin");

    monitor_performance();

    // Print all values stored within each entry
    print_all_values(num_entries, entries);

    monitor_performance();

    // Free the memory allocated for the entries array
    free_input(num_entries, &entries);

    return 0;
}
