// Define the record structure
typedef struct {
    int key;
} Record;

int main(int argc, char **argv) {
    // Parse command line arguments
    if (argc < 2) {
        printf("Usage: %s [-v] [-o output_file] input_file\n", argv[0]);
        return 1;
    }

    int verbose = 0;
    char *output_file = NULL;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-v") == 0) {
            verbose = 1;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_file = argv[i + 1];
        } else if (input_file == NULL) {
            input_file = argv[i];
        } else {
            printf("Error: too many arguments\n");
            return 1;
        }
    }

    // Open the input file
    FILE *fp = fopen(input_file, "r");
    if (fp == NULL) {
        printf("Error: failed to open input file %s\n", input_file);
        return 1;
    }

    // Determine the number of lines in the file
    long num_lines = 0;
    char line[256];
    while (fgets(line, sizeof(line), fp) != NULL) {
        num_lines++;
    }

    // Allocate memory for the arrays
    long *offset_array = malloc(num_lines * sizeof(*offset_array));
    int *key_array = malloc(num_lines * sizeof(*key_array));
    Record *record_array = malloc(num_lines * sizeof(*record_array));
    if (offset_array == NULL || key_array == NULL || record_array == NULL) {
        printf("Error: failed to allocate memory\n");
        return 1;
    }

    // Initialize the arrays
    for (int i = 0; i < num_lines; i++) {
        offset_array[i] = -1;
        key_array[i] = -1;
        record_array[i].key = -1;
    }

    // Read the file line by line and process each line
    rewind(fp);
    for (int i = 0; i < num_lines; i++) {
        if (fgets(line, sizeof(line), fp) == NULL) {
            printf("Error: failed to read line %d\n", i + 1);
            return 1;
        }

        // Parse the line and extract the offset and key values
        char *offset_str = strtok(line, " ");
        char *key_str = strtok(NULL, " ");
        if (offset_str == NULL || key_str == NULL) {
            printf("Error: failed to parse line %d\n", i + 1);
            return 1;
        }

        // Convert the offset and key values to integers
        long offset = atol(offset_str);
        int key = atoi(key_str);

        // Store the values in the arrays
        offset_array[i] = offset;
        key_array[i] = key;
        record_array[i].key = key;
    }

    // Close the input file
    fclose(fp);

    // Print usage information if requested
    if (verbose) {
        printf("Input file: %s\n", input_file);
        printf("Number of lines: %ld\n", num_lines);
        printf("Offset array:\n");
        for (int i = 0; i < num_lines; i++) {
            printf("%ld ", offset_array[i]);
        }
        printf("\nKey array:\n");
        for (int i = 0; i < num_lines; i++) {
            printf("%d ", key_array[i]);
        }
        printf("\nRecord array:\n");
        for (int i = 0; i < num_lines; i++) {
            printf("(%d) ", record_array[i].key);
        }
    }

    // Free the memory allocated for the arrays
    free(offset_array);
    free(key_array);
    free(record_array);

    return 0;
}
