#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Custom allocator to manage memory efficiently under different system load conditions
struct MemoryPool {
  size_t size; // Size of the memory pool in bytes
  void* data; // Pointer to the start of the memory pool
};

void* myAlloc(size_t size) {
  struct MemoryPool* pool = &myMemoryPool;
  if (pool->data + pool->size - (char*)pool->data >= size) {
    void* ptr = pool->data;
    pool->data += size;
    return ptr;
  } else {
    return malloc(size);
  }
}

void myFree(void* ptr) {
  struct MemoryPool* pool = &myMemoryPool;
  if (ptr >= (char*)pool->data && ptr < (char*)pool->data + pool->size) {
    free(ptr);
  } else {
    free(ptr);
  }
}

