    while (current->next != NULL) {
      current = current->next;
    }
    current->next = new_node;
  }
}

// Function to delete a node from the linked list
void deleteNode(struct Node** head_ref, struct Node* node) {
  if (*head_ref == NULL) {
    return;
  } else if (node == *head_ref) {
    *head_ref = node->next;
  } else {
    struct Node* current = *head_ref;
    while (current->next != node) {
      current = current->next;
    }
    current->next = node->next;
  }
}

// Function to retrieve a node from the linked list
struct Node* getNode(struct Node** head_ref, int index) {
  if (*head_ref == NULL || index < 0) {
    return NULL;
  } else if (index == 0) {
    return *head_ref;
  } else {
    struct Node* current = *head_ref;
    for (int i = 1; i <= index && current != NULL; i++) {
      current = current->next;
    }
    if (current == NULL) {
      return NULL;
    } else {
      return current;
    }
  }
}

// Main function to demonstrate the usage of the linked list functions
int main() {
  struct Node* head = NULL; // Linked list header pointer
  struct MemoryPool myMemoryPool; // Custom memory pool for dynamic memory allocation

  // Initialize the custom allocator and the linked list header pointer
  myMemoryPool.size = 1024 * 1024; // 1 MB of memory pool size
  myMemoryPool.data = malloc(myMemoryPool.size);
  head = NULL;

  // Insert a new node into the linked list with randomly generated data
  struct Node* new_node = (struct Node*)myAlloc(sizeof(struct Node));
  initNode(new_node);
  insertNode(&head, new_node);

  // Retrieve and print the value of the first node in the linked list
  struct Node* current = head;
  printf("Value of first node: %lf\n", current->value);

  // Delete a node from the linked list
  deleteNode(&head, new_node);

  // Retrieve and print the value of the first node in the linked list
  // (should be NULL since we just deleted it)
  current = head;
  printf("Value of first node after deletion: %lf\n", current->value);

  // Insert a new node into the linked list with randomly generated data
  struct Node* new_node2 = (struct Node*)myAlloc(sizeof(struct Node));
  initNode(new_node2);
  insertNode(&head, new_node2);

  // Retrieve and print the value of the first node in the linked list
  current = head;
  printf("Value of first node after second insertion: %lf\n", current->value);

  // Free all memory allocated by the custom allocator
  myFree(head);
  myFree(new_node);
  myFree(new_node2);

  return 0;
}
