#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

typedef struct node {
    double value;
    char *str;
    struct node *next;
} Node;

void init_node(Node *node) {
    // Initialize a new node with randomly generated data
    node->value = (double)rand() / RAND_MAX;
    node->str = malloc(10); // Use 10 bytes for the string
    snprintf(node->str, 10, "%f", node->value);
    node->next = NULL;
}

void add_node(Node *node) {
    // Add a new node to the list
    Node *new_node = malloc(sizeof(Node));
    init_node(new_node);
    new_node->next = node->next;
    node->next = new_node;
}

void remove_node(Node *node) {
    // Remove a node from the list
    Node *tmp = node->next;
    node->next = tmp->next;
    free(tmp);
}

int serialize_data(FILE *file, Node *head) {
    // Serialize the data to a file
    fwrite(&head->value, sizeof(double), 1, file);
    char str[10];
    snprintf(str, 10, "%f", head->value);
    fwrite(str, sizeof(char), 9, file); // Write the string excluding the null terminator
    Node *curr = head;
    while (curr) {
        fwrite(&curr->next->value, sizeof(double), 1, file);
        snprintf(str, 10, "%f", curr->next->value);
        fwrite(str, sizeof(char), 9, file); // Write the string excluding the null terminator
        curr = curr->next;
    }
    return 0;
}

int deserialize_data(FILE *file, Node **head) {
    // Deserialize the data from a file
    if (fread(&((*head)->value), sizeof(double), 1, file) != 1) {
        return -1;
    }
    char str[10];
    fread(str, sizeof(char), 9, file); // Read the string excluding the null terminator
    (*head)->str = malloc(10);
    snprintf((*head)->str, 10, "%f", (*head)->value);
    Node *curr = *head;
    while (curr) {
        if (fread(&(curr->next->value), sizeof(double), 1, file) != 1) {
            return -1;
        }
        fread(str, sizeof(char), 9, file); // Read the string excluding the null terminator
        curr->next->str = malloc(10);
        snprintf(curr->next->str, 10, "%f", curr->next->value);
        curr = curr->next;
    }
    return 0;
}

int main() {
    // Test the serialization and deserialization functions
    Node *head = malloc(sizeof(Node));
    init_node(head);
    serialize_data(stdout, head);
    printf("\n");
    deserialize_data(stdin, &head);
    while (head) {
        printf("%f %s\n", head->value, head->str);
        head = head->next;
    }
    return 0;
}
```
