// Define structure for sensor data
typedef struct {
    long timestamp;
    double data_point;
    char status_code;
} sensor;

// Define function to calculate moving average of data points over sliding window of size 5
void calculate_moving_average(sensor* sensors, int num_sensors) {
    // Calculate number of data points in sliding window
    int window_size = 5;
    int num_windows = (num_sensors - window_size + 1);

    // Allocate memory for moving average array
    double* moving_average = (double*)malloc(sizeof(double) * num_windows);

    // Initialize moving average array
    memset(moving_average, 0, sizeof(double) * num_windows);

    // Iterate over windows in sensor data
    for (int i = 0; i < num_sensors - window_size + 1; i++) {
        // Calculate moving average of current window
        double sum = 0.0;
        for (int j = i; j < i + window_size; j++) {
            sum += sensors[j].data_point;
        }
        moving_average[i] = sum / window_size;
    }

    // Free memory for moving average array
    free(moving_average);
}

int main() {
    // Define arrays for timestamp, data point, and status code
    long* timestamps = (long*)malloc(sizeof(long) * 1000);
    double* data_points = (double*)malloc(sizeof(double) * 1000);
    char* status_codes = (char*)malloc(sizeof(char) * 1000);

    // Initialize arrays with dummy values
    for (int i = 0; i < 1000; i++) {
        timestamps[i] = i + 1;
        data_points[i] = i + 1.0;
        status_codes[i] = 'A';
    }

    // Define structure for sensor data
    sensor* sensors = (sensor*)malloc(sizeof(sensor) * 1000);

    // Initialize structure with dummy values
    for (int i = 0; i < 1000; i++) {
        sensors[i].timestamp = timestamps[i];
        sensors[i].data_point = data_points[i];
        sensors[i].status_code = status_codes[i];
    }

    // Calculate moving average of sensor data
    calculate_moving_average(sensors, 1000);

    return 0;
