// Define the session struct to hold information about each user session
typedef struct {
    int id;
    time_t last_activity;
    bool active;
    char* metadata;
} session_t;

// Define the list data structure to store all the sessions
typedef struct {
    session_t* sessions;
    size_t num_sessions;
    size_t capacity;
} session_list_t;

// Initialize a new session list with an initial capacity
session_list_t* init_session_list(size_t capacity) {
    session_list_t* list = (session_list_t*) malloc(sizeof(session_list_t));
    list->sessions = (session_t*) malloc(capacity * sizeof(session_t));
    list->num_sessions = 0;
    list->capacity = capacity;
    return list;
}

// Add a new session to the list, with a unique ID and an optional metadata field
void add_session(session_list_t* list, int id, char* metadata) {
    // Check if the list is full, and expand its capacity if necessary
    if (list->num_sessions == list->capacity) {
        list->capacity *= 2;
        list->sessions = (session_t*) realloc(list->sessions, list->capacity * sizeof(session_t));
    }
    // Create a new session struct and add it to the list
    session_t* session = &list->sessions[list->num_sessions++];
    session->id = id;
    session->last_activity = time(NULL);
    session->active = true;
    if (metadata) {
        size_t metadata_len = strlen(metadata);
        session->metadata = (char*) malloc(metadata_len + 1);
        memcpy(session->metadata, metadata, metadata_len + 1);
    } else {
        session->metadata = NULL;
    }
}

// Update the last activity timestamp of a session with a given ID
void update_last_activity(session_list_t* list, int id) {
    for (int i = 0; i < list->num_sessions; i++) {
        if (list->sessions[i].id == id) {
            list->sessions[i].last_activity = time(NULL);
            break;
        }
    }
}

// Remove a session with a given ID from the list
void remove_session(session_list_t* list, int id) {
    for (int i = 0; i < list->num_sessions; i++) {
        if (list->sessions[i].id == id) {
            // Shift all subsequent sessions to the left by one index
            for (int j = i + 1; j < list->num_sessions; j++) {
                memcpy(&list->sessions[j - 1], &list->sessions[j], sizeof(session_t));
            }
            // Decrease the number of sessions by one
            list->num_sessions--;
            break;
        }
    }
}

// Search for a session with a given ID in the list
int find_session(session_list_t* list, int id) {
    for (int i = 0; i < list->num_sessions; i++) {
        if (list->sessions[i].id == id) {
            return i;
        }
    }
    return -1;
}

// Remove expired sessions from the list based on their activity timestamps
void remove_expired_sessions(session_list_t* list) {
    time_t current_time = time(NULL);
    for (int i = 0; i < list->num_sessions; i++) {
        session_t* session = &list->sessions[i];
        if (!session->active && current_time - session->last_activity > EXPIRATION_TIME) {
            // Shift all subsequent sessions to the left by one index
            for (int j = i + 1; j < list->num_sessions; j++) {
                memcpy(&list->sessions[j - 1], &list->sessions[j], sizeof(session_t));
            }
            // Decrease the number of sessions by one
            list->num_sessions--;
        } else {
            // Update the last activity timestamp for all active sessions
            session->last_activity = current_time;
        }
    }
}

// Custom error handling mechanism to handle out-of-memory conditions gracefully
void handle_oom(session_list_t* list) {
    printf("Out of memory! Reallocating...\n");
    // Reallocate the list with a new capacity
    size_t new_capacity = list->num_sessions * 2;
    list->sessions = (session_t*) realloc(list->sessions, new_capacity * sizeof(session_t));
    if (!list->sessions) {
        printf("Failed to reallocate memory! Terminating...\n");
        exit(1);
    } else {
        list->capacity = new_capacity;
    }
}

// Background thread function to periodically check for expired sessions and remove them
void* background_thread(session_list_t* list) {
    while (true) {
        sleep(EXPIRATION_CHECK_INTERVAL);
        pthread_mutex_lock(&list->mutex);
        remove_expired_sessions(list);
        pthread_mutex_unlock(&list->mutex);
    }
}

// Main function to initialize and run the session management system
int main() {
    // Initialize the list with an initial capacity of 10 sessions
    session_list_t* list = init_session_list(10);
    // Start a background thread for periodically checking for expired sessions
    pthread_t bg_thread;
    pthread_create(&bg_thread, NULL, background_thread, (void*) list);
    // Run the session management system until terminated
    while (true) {
        int id = -1;
        char* metadata = NULL;
        // Read input from stdin and perform corresponding operations on the list
        printf("Enter a command: ");
        scanf("%d %s", &id, metadata);
        if (id == 0) {
            // Add a new session with a unique ID and optional metadata field
            add_session(list, id, metadata);
        } else if (id > 0) {
            // Update the last activity timestamp of the session with the given ID
            update_last_activity(list, id);
        } else if (id < 0) {
            // Remove the session with the given ID from the list
            remove_session(list, -id);
        }
    }
}
```
This code implements a simple session management system using a linked list data structure. It includes functions to add, update, and remove sessions, as well as a background thread that periodically checks for expired sessions and removes them. The system also includes custom error handling mechanism to handle out-of-memory conditions gracefully.

The `session_list_t` struct is used to store information about each session, including the unique session ID, last activity timestamp, status, and optional metadata field. The `init_session_list()` function initializes a new list with an initial capacity of 10 sessions, while the `add_session()` function adds a new session with a given ID and optional metadata field to the list. The `update_last_activity()` function updates the last activity timestamp for the session with the given ID, and the `remove_session()` function removes the session with the given ID from the list.

The background thread is implemented using a separate thread that periodically checks for expired sessions and removes them. This thread is started using the `pthread_create()` function and runs indefinitely until terminated. The `remove_expired_sessions()` function is called on the main thread to remove any expired sessions from the list.

The system also includes a custom error handling mechanism to handle out-of-memory conditions gracefully. When the list needs to be reallocated due to an increase in capacity, the `handle_oom()` function is called to print an error message and exit if the reallocation fails. This allows the system to continue running even when memory becomes scarce.

Overall, this code implements a simple session management system using a linked list data structure that can handle concurrent read and write access. The system also includes a background thread for periodically checking for expired sessions and a custom error handling mechanism to handle out-of-memory conditions gracefully.']

