// Function to handle command execution using system()
void executeCommand(char* command) {
    // Delete any existing temporary files before executing the command
    char* tmp_file = "/tmp/temp_file";
    if (remove(tmp_file)) {
        printf("Error: Failed to delete temporary file\n");
        return;
    }

    // Redirect input and output streams using file descriptors instead of BufferedReader
    int in_fd = open("/dev/stdin", O_RDONLY);
    int out_fd = open(tmp_file, O_WRONLY | O_CREAT, 0644);

    // Execute the command and read the output and error streams using FILE* pointers
    pid_t pid = fork();
    if (pid == 0) {
        dup2(in_fd, STDIN_FILENO);
        dup2(out_fd, STDOUT_FILENO);
        execl("/bin/sh", "sh", "-c", command, (char*)NULL);
        exit(EXIT_FAILURE);
    } else {
        waitpid(pid, NULL, 0);
        FILE* out = fopen(tmp_file, "r");
        if (!out) {
            printf("Error: Failed to read output stream\n");
            return;
        }
        char buffer[1024];
        while (fgets(buffer, sizeof(buffer), out)) {
            printf("%s", buffer);
        }
        fclose(out);
    }
}

