        Record* record = &records[i];
        freeMemoryFromPool(memPool, record->buffer);
    }
    if (memPool) {
        destroyMemoryPool(memPool);
    }
}

// Custom memory pool functions

MemoryPool* createMemoryPool(int minLength, int maxLength) {
    // Allocate memory for the memory pool structure
    MemoryPool* memPool = malloc(sizeof(MemoryPool));
    if (!memPool) {
        perror("malloc");
        return NULL;
    }

    // Initialize the memory pool with a random size between min and max lengths
    int poolSize = rand() % (maxLength - minLength + 1) + minLength;
    memPool->size = poolSize;

    // Allocate memory for the pool
    void* memory = malloc(poolSize);
    if (!memory) {
        perror("malloc");
        return NULL;
    }

    memPool->memory = memory;

    return memPool;
}

void destroyMemoryPool(MemoryPool* memPool) {
    free(memPool->memory);
    free(memPool);
}

void* allocateMemoryFromPool(MemoryPool* memPool, int minLength, int maxLength) {
    // Check if the pool has enough space for a new record
    if (memPool->size < maxLength) {
        perror("poolSize");
        return NULL;
    }

    // Allocate memory from the pool and update the pool size
    void* memory = memPool->memory;
    memPool->memory += minLength;
    memPool->size -= minLength;

    return memory;
}

void freeMemoryFromPool(MemoryPool* memPool, void* memory) {
    // Find the index of the memory in the pool
    int index = (char*)memory - (char*)memPool->memory;

    // Update the pool size and free the memory
    memPool->size += index * minLength;
    free(memory);
}
