            printf("Item key: %d\n", item->key);
            printf("Item value: %f\n", item->value);
            printf("Item name: %s\n", item->name);
            break;
        case TASK_TYPE_VERTEX:
            // Process a graph vertex
            struct vertex *vertex = task->data;
            printf("Vertex id: %d\n", vertex->id);
            break;
        case TASK_TYPE_EDGE:
            // Process a graph edge
            struct edge *edge = task->data;
            printf("Edge source: %d\n", edge->source);
            printf("Edge target: %d\n", edge->target);
            break;
        default:
            // Handle unknown tasks
            printf("Unknown task type: %d\n", task->type);
    }
}
