    // Close the file and log the event
    if (fclose(file)) {
        log_event("Failed to close file.\n");
    } else {
        log_event("State saved successfully.\n");
    }
}

// Define a function to resume processing from a partially processed state
void resume_processing(int num_records, int *keys, Record *records) {
    // Open the file for reading and read the current state
    FILE *file = fopen("partially_processed_records.bin", "rb");
    if (file == NULL) {
        log_event("Failed to open file for reading.\n");
        return;
    }

    // Read the number of records and their keys and values from the file
    fread(&num_records, sizeof(int), 1, file);
    fread(keys, sizeof(int), num_records, file);
    fread(records, sizeof(Record), num_records, file);

    // Close the file and log the event
    if (fclose(file)) {
        log_event("Failed to close file.\n");
    } else {
        log_event("State resumed successfully.\n");
    }
}

