function mergeSortedArrays(sortedArrays) {
  // Initialize an empty array for the merged result
  const mergedResult = [];

  // Create a custom min-heap to manage the merging process efficiently
  const heap = new MinHeap();

  // Add each sorted array to the heap
  for (const sortedArray of sortedArrays) {
    heap.add(sortedArray);
  }

  // Merge the arrays in chunks, streaming the result to reduce memory footprint
  while (heap.size() > 0) {
    const chunkSize = Math.min(10000, heap.size());
    for (let i = 0; i < chunkSize; i++) {
      mergedResult.push(heap.removeMin().pop());
    }
  }

  return mergedResult;
}
