    state.num_records = num_records;
    state.min_value = min_value;
    state.max_value = max_value;
    state.records = records;

    // Define the batch processing component
    int batch_size = 100;
    while (state.num_processed < num_records) {
        // Process each record in the current batch
        for (int i = 0; i < batch_size && state.num_processed < num_records; i++) {
            int index = state.num_processed % state.num_records;
