        data_pointers[i] = malloc(sizeof(double) * MAX_SIZE);
        if (data_pointers[i] == NULL) {
            // Handle memory allocation failure
            free(data_pointers);
            return;
        }
    }

    // Allocate memory for the payload strings
    char** payload_strings = malloc(sizeof(char*) * MAX_SIZE);
    if (payload_strings == NULL) {
        // Handle memory allocation failure
        free(data_pointers);
        return;
    }

    // Initialize the payload strings to NULL
    for (int i = 0; i < MAX_SIZE; i++) {
        payload_strings[i] = NULL;
    }

    // Allocate memory for each payload string
