        int payload_size = strlen(data_arrays[0][i].payload) + 1;
        payload_strings[i] = malloc(sizeof(char) * payload_size);
        if (payload_strings[i] == NULL) {
            // Handle memory allocation failure
            free(payload_strings);
            for (int j = 0; j < i; j++) {
                free(data_pointers[j]);
            }
            free(data_pointers);
            return;
        }
    }

    // Copy the payloads to their respective strings
    for (int i = 0; i < MAX_SIZE; i++) {
        strcpy(payload_strings[i], data_arrays[0][i].payload);
    }

    // Free the payload strings that are no longer needed
    for (int i = 0; i < MAX_SIZE; i++) {
        if (!data_arrays[1][i].status) {
            free(payload_strings[i]);
        }
    }

    // Update the data pointers to point to the new memory locations
    for (int i = 0; i < num_data_arrays; i++) {
        for (int j = 0; j < MAX_SIZE; j++) {
            if (i == 2) {
                // Free the payload strings that are no longer needed
                if (!data_arrays[1][j].status) {
                    free(payload_strings[j]);
                }
            } else {
                data_pointers[i][j] = &data_arrays[i][j];
            }
        }
    }

    // Free the memory allocated for the payload strings
    free(payload_strings);

    // Periodically clear old data from the payloads to maintain efficient memory usage
    while (true) {
        // Check if there are any old data packets that need to be cleared
        bool need_to_clear = false;
        for (int i = 0; i < MAX_SIZE; i++) {
            if (data_arrays[1][i].status && time(NULL) - data_arrays[1][i].timestamp > OLDEST_DATA_AGE) {
                need_to_clear = true;
                break;
            }
        }

        // If there are old data packets that need to be cleared, clear them and update the status flags
        if (need_to_clear) {
            for (int i = 0; i < MAX_SIZE; i++) {
                if (data_arrays[1][i].status && time(NULL) - data_arrays[1][i].timestamp > OLDEST_DATA_AGE) {
                    free(payload_strings[i]);
                    payload_strings[i] = NULL;
                    data_arrays[1][i].status = false;
                }
            }
        } else {
            break;
        }
    }

    // Free the memory allocated for the data pointers
    free(data_pointers);
}
