  const resource = Resource.findById(resourceId);

  // Update the resource with the updated data from the request body
  resource.data = req.body.data;

  // Save the updated resource to the database
  resource.save((err, result) => {
    if (err) {
      res.status(500).send({ message: 'Error updating resource' });
    } else {
      res.json(result);
    }
  });
});

app.delete('/resource/:id', authentication.authenticate(), authorization.authorize('admin'), (req, res) => {
  // Retrieve the resource from the database using the unique identifier
  const resourceId = req.params.id;
  const resource = Resource.findById(resourceId);

  // Replace the resource with default values
  resource.data = null;

  // Save the updated resource to the database
  resource.save((err, result) => {
    if (err) {
      res.status(500).send({ message: 'Error updating resource' });
    } else {
      res.json(result);
    }
  });
});

app.listen(3000, () => {
  console.log('Server started on port 3000');
});
