import json
from datetime import datetime
from typing import List, Dict

class Document:
    def __init__(self, id: str, user_id: int, content: str, metadata: dict):
        self.id = id
        self.user_id = user_id
        self.content = content
        self.metadata = metadata

    def to_json(self) -> Dict[str, str]:
        return {
            "id": self.id,
            "user_id": self.user_id,
            "content": self.content,
            "metadata": self.metadata
        }

    @classmethod
    def from_json(cls, json_data: Dict[str, str]) -> "Document":
        return cls(
            id=json_data["id"],
            user_id=json_data["user_id"],
            content=json_data["content"],
            metadata=json_data["metadata"]
        )

class DocumentManager:
    def __init__(self):
        self.documents = {} # type: Dict[str, Document]
        self.document_versions = {} # type: Dict[str, List[Document]]
        self.lock = threading.Lock()

    def upload(self, json_data: Dict[str, str]) -> str:
        with self.lock:
            document = Document.from_json(json_data)
            if "id" not in json_data or len(document.id) == 0:
                document.id = generate_unique_id() # type: ignore
            self.documents[document.id] = document
            self.document_versions[document.id].append(document)
            return document.id

    def download(self, id: str) -> Document:
        with self.lock:
            if id not in self.documents:
                raise ValueError("Document does not exist")
            return self.documents[id]

    def delete(self, id: str):
        with self.lock:
            if id not in self.documents:
                raise ValueError("Document does not exist")
            del self.documents[id]
            del self.document_versions[id]

    def version(self, id: str) -> List[Document]:
        with self.lock:
            if id not in self.document_versions:
                raise ValueError("No versions found for document")
            return self.document_versions[id][:]

    def search(self, query: str) -> List[Document]:
        with self.lock:
            results = []
            for id, document in self.documents.items():
                if query in document.content or query in document.metadata["name"]:
                    results.append(document)
            return results

class DocumentValidator:
    def validate(self, json_data: Dict[str, str]) -> bool:
        if "id" not in json_data or len(json_data["id"]) == 0:
            raise ValueError("Missing ID")
        if "user_id" not in json_data or len(json_data["user_id"]) == 0:
            raise ValueError("Missing user ID")
        if "content" not in json_data or len(json_data["content"]) == 0:
            raise ValueError("Missing content")
        if "metadata" not in json_data or len(json_data["metadata"]) == 0:
            raise ValueError("Missing metadata")
        return True

class DocumentCache:
    def __init__(self):
        self.cache = {} # type: Dict[str, Document]

    def get(self, id: str) -> Document:
        if id in self.cache:
            return self.cache[id]
        else:
            return None

    def set(self, id: str, document: Document):
        self.cache[id] = document

class DocumentBackup:
    def backup(self, id: str):
        with open(f"backups/{id}.json", "w") as file:
            json.dump(self.documents[id].to_json(), file)

class DocumentLogger:
    def log(self, document: Document, event: str):
        if event == "upload":
            self.log_upload(document)
        elif event == "download":
            self.log_download(document)
        elif event == "delete":
            self.log_delete(document)
        else:
            raise ValueError("Invalid log event")

    def log_upload(self, document: Document):
        print(f"Document uploaded: {document.id}")

    def log_download(self, document: Document):
        print(f"Document downloaded: {document.id}")

    def log_delete(self, document: Document):
        print(f"Document deleted: {document.id}")

class DocumentMonitor:
    def monitor(self):
        while True:
            with self.lock:
                for id in self.documents:
                    if len(self.document_versions[id]) > 10:
                        # Delete the oldest version
                        self.document_versions[id].pop(0)
                        print(f"Document {id} has too many versions, deleting oldest")
            time.sleep(3600) # Check every hour

class DocumentEncrypter:
    def encrypt(self, document: Document):
        return "encrypted_content"

    def decrypt(self, encrypted_content: str):
        return "decrypted_content"

def generate_unique_id() -> str:
    return str(uuid.uuid4())
