// Custom data structure to hold integer or string values
typedef struct record {
    int type;  // 0 for integer, 1 for string
    union {
        int value_int;
        char* value_str;
    } val;
} Record;

// Function to read mixed list of integers and strings from standard input
void read_mixed_list(Record** records, size_t* num_records) {
    // Variable to store the size of the array of records
    size_t arr_size = 0;

    // Initialize an empty array of records
    Record* record_arr = NULL;

    // Loop until EOF is reached or an error occurs
    while (1) {
        // Read a line from standard input
        char* line = readline();

        // If the line is empty, break out of the loop
        if (!line || strlen(line) == 0) {
            break;
        }

        // Try to convert the line to an integer
        int num_int = atoi(line);

        // If the conversion was successful, add a new record with the integer value
        if (num_int > 0) {
            Record* rec = malloc(sizeof(Record));
            rec->type = 0;
            rec->val.value_int = num_int;

            // If the array is not allocated, allocate it with size arr_size + 1
            if (!record_arr) {
                record_arr = malloc((arr_size + 1) * sizeof(Record));
            }

            // Add the new record to the array
            record_arr[arr_size++] = rec;
        } else {
            // If the conversion was not successful, try to convert the line to a string
            char* str = malloc(strlen(line) + 1);
            strcpy(str, line);

            Record* rec = malloc(sizeof(Record));
            rec->type = 1;
            rec->val.value_str = str;

            // If the array is not allocated, allocate it with size arr_size + 1
            if (!record_arr) {
                record_arr = malloc((arr_size + 1) * sizeof(Record));
            }

            // Add the new record to the array
            record_arr[arr_size++] = rec;
        }

        // Free the line buffer
        free(line);
    }

    // If the array is not empty, set the number of records and return it
    if (record_arr) {
        *num_records = arr_size;
        *records = record_arr;
    }
}

// Function to validate input sizes to prevent out-of-bounds access
void validate_input(Record** records, size_t num_records) {
    // Loop through all records and check for invalid values
    for (size_t i = 0; i < num_records; i++) {
        Record* rec = records[i];

        // If the record is an integer, check if it's within the valid range
        if (rec->type == 0 && !(rec->val.value_int >= INT_MIN && rec->val.value_int <= INT_MAX)) {
            fprintf(stderr, "Invalid integer value: %d\n", rec->val.value_int);
            exit(1);
        }

        // If the record is a string, check if it's not NULL and has a valid length
        if (rec->type == 1 && !(strlen(rec->val.value_str) > 0 && strlen(rec->val.value_str) < INT_MAX)) {
            fprintf(stderr, "Invalid string value: %s\n", rec->val.value_str);
            exit(1);
        }
    }
}

// Function to manage memory allocation failures gracefully
void handle_memory_allocation_failure() {
    fprintf(stderr, "Memory allocation failed\n");
    exit(1);
}

// Function to interface with an external logging service to log detailed information about memory allocations and deallocations
void log_mem_alloc(Record** records, size_t num_records) {
    // Log the memory allocation event using a custom function provided by the logging library
    log_mem_allocation(num_records * sizeof(Record));
}

// Function to interface with a third-party serialization library to support serializing the array of records to a file in a custom format
void serialize_data(Record** records, size_t num_records) {
    // Serialize the data using a custom function provided by the serialization library
    serialize(records, num_records);
}

// Function to find and print the largest integer in the array of records if they are integers, or the longest string if they are strings. Optimize this function for large datasets, minimizing unnecessary computations and memory usage.
void find_largest(Record** records, size_t num_records) {
    // Initialize a variable to store the largest value found so far
    int largest = INT_MIN;

    // Loop through all records and compare each value with the current largest one
    for (size_t i = 0; i < num_records; i++) {
        Record* rec = records[i];

        // If the record is an integer, check if it's larger than the current largest one
        if (rec->type == 0 && rec->val.value_int > largest) {
            largest = rec->val.value_int;
        }
    }

    // Print the largest value found so far
    printf("Largest integer: %d\n", largest);
