#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Define a custom record structure
struct record {
    int value;
};

void initializeDataStructures(int num_offsets, int num_keys, int num_records, int min_value, int max_value) {
    // Allocate memory for the offsets array
    long *offsets = malloc(num_offsets * sizeof(long));
    if (offsets == NULL) {
        printf("Error: failed to allocate memory for offsets\n");
        return;
    }

    // Initialize the offsets array with random values
    srand(time(NULL));
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = rand() % max_value + min_value;
    }

    // Allocate memory for the keys array
    int *keys = malloc(num_keys * sizeof(int));
    if (keys == NULL) {
        printf("Error: failed to allocate memory for keys\n");
        free(offsets);
        return;
    }

    // Initialize the keys array with unique random values between 0 and 1000000
    int key_value = rand() % 1000000 + min_value;
    for (int i = 0; i < num_keys; i++) {
        keys[i] = key_value++;
        if (key_value > max_value) {
            key_value = rand() % max_value + min_value;
        }
    }

    // Check for duplicate keys and free the memory if necessary
    int *unique_keys = malloc(num_keys * sizeof(int));
    int unique_count = 0;
    for (int i = 0; i < num_keys; i++) {
        bool found = false;
        for (int j = 0; j < i; j++) {
            if (keys[i] == keys[j]) {
                found = true;
                break;
            }
        }
        if (!found) {
            unique_keys[unique_count++] = keys[i];
        }
    }
    free(keys);
