typedef struct {
    offset_t *offsets;
    key_t *keys;
    record_t *records;
    size_t num_records;
    size_t file_size;
} data_set_t;

data_set_t* initialize_dataset(size_t file_size, size_t num_records, int seed, int range_limit) {
    // Check if the file size and number of records are valid
    if (file_size < 1 || num_records < 1) {
        return NULL;
    }

    // Allocate memory for the offsets, keys, and records
    offset_t *offsets = malloc(sizeof(offset_t) * file_size);
    key_t *keys = malloc(sizeof(key_t) * num_records);
    record_t *records = malloc(sizeof(record_t) * num_records);

    // Initialize the offsets and keys
    for (int i = 0; i < file_size; i++) {
        offsets[i] = i;
    }
    for (int i = 0; i < num_records; i++) {
        keys[i] = i;
    }

    // Initialize the records with unique values generated from the seed and range limit
    for (int i = 0; i < num_records; i++) {
        int value = generate_value(seed, range_limit);
        records[i].value = value;
    }

    // Create a data set structure to encapsulate all allocated resources
    data_set_t *data_set = malloc(sizeof(data_set_t));
    data_set->offsets = offsets;
    data_set->keys = keys;
    data_set->records = records;
    data_set->num_records = num_records;
    data_set->file_size = file_size;

    // Return the data set structure
    return data_set;
}

int generate_value(int seed, int range_limit) {
    // Generate a random value within the specified range
    srand(seed);
    int value = rand() % range_limit + 1;

    // Check if the value is within the valid range and not repeated
    while (value < 0 || value > range_limit || is_repeated(value, records)) {
        value = rand() % range_limit + 1;
    }

    return value;
}

int is_repeated(int value, record_t *records) {
    // Check if any record has the same value as the specified value
    for (int i = 0; i < num_records; i++) {
        if (records[i].value == value) {
            return 1;
        }
    }

    return 0;
}
```
