// Define the struct to hold the record data
typedef struct {
    int key;
    char *certificate;
} Record;

// Define the hash function for the records
unsigned long hash_function(Record *rec) {
    unsigned long hash = 0;
    // Use a more complex hash function to avoid collisions
    hash += (rec->key * rec->key) % (sizeof(unsigned long) * 8);
    return hash;
}

// Define the thread-safe queue for storing records
typedef struct {
    Record **records;
    size_t capacity;
    size_t num_records;
    pthread_mutex_t mutex;
} Queue;

void init_queue(Queue *q) {
    q->capacity = 0;
    q->num_records = 0;
    // Initialize the mutex for thread-safe access
    pthread_mutex_init(&q->mutex, NULL);
}

void enqueue(Queue *q, Record *rec) {
    // Check if the queue is full
    if (q->num_records == q->capacity) {
        return;
    }
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&q->mutex);
    // Add the record to the end of the queue
    q->records[q->num_records++] = rec;
    // Unlock the mutex
    pthread_mutex_unlock(&q->mutex);
}

Record *dequeue(Queue *q) {
    Record *rec = NULL;
    // Check if the queue is empty
    if (q->num_records == 0) {
        return rec;
    }
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&q->mutex);
    // Remove the record from the front of the queue
    rec = q->records[0];
    memmove(q->records, q->records + 1, (q->num_records - 1) * sizeof(Record *));
    q->num_records--;
    // Unlock the mutex
    pthread_mutex_unlock(&q->mutex);
    return rec;
}

