    struct Offset* offsets = malloc(num_offsets * sizeof(struct Offset));
    if (offsets == NULL) {
        fprintf(stderr, "Failed to allocate memory for offset array\n");
        return NULL;
    }

    // Initialize the offset values with a random seed
    srand(time(NULL));
    for (int i = 0; i < num_offsets; i++) {
        offsets[i].offset = rand() % INT_MAX;
    }

    return offsets;
}

// Define function to allocate memory for an array of keys
void* allocate_keys(struct Offset* offsets, int num_keys) {
    // Check if the number of keys is valid and prevent potential overflow
    if (num_keys < 0 || num_keys > INT_MAX / sizeof(int)) {
        return NULL;
    }

    // Allocate memory for the array of keys
    int* keys = malloc(num_keys * sizeof(int));
    if (keys == NULL) {
        fprintf(stderr, "Failed to allocate memory for key array\n");
        return NULL;
    }

    // Initialize the key values with a random seed and offset range
    srand(time(NULL));
    int min_offset = offsets[0].offset;
    int max_offset = offsets[num_offsets - 1].offset;
    for (int i = 0; i < num_keys; i++) {
        keys[i] = rand() % (max_offset - min_offset + 1) + min_offset;
    }

    return keys;
}

// Define function to allocate memory for an array of records
void* allocate_records(struct Offset* offsets, int num_records) {
    // Check if the number of records is valid and prevent potential overflow
    if (num_records < 0 || num_records > INT_MAX / sizeof(struct Record)) {
        return NULL;
    }

    // Allocate memory for the array of records
    struct Record* records = malloc(num_records * sizeof(struct Record));
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory for record array\n");
        return NULL;
    }

    // Initialize the record values with a random seed and offset range
    srand(time(NULL));
    int min_offset = offsets[0].offset;
    int max_offset = offsets[num_offsets - 1].offset;
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % INT_MAX;
        records[i].offset = &offsets[rand() % num_offsets];
    }

    return records;
}

// Define function to free memory for an array of offsets
void free_offsets(struct Offset* offsets) {
    // Check if the offsets pointer is valid and prevent potential errors
    if (offsets == NULL) {
        return;
    }

    // Free the memory allocated for the offset array
    free(offsets);
}

// Define function to free memory for an array of keys
void free_keys(int* keys) {
    // Check if the keys pointer is valid and prevent potential errors
    if (keys == NULL) {
        return;
    }

    // Free the memory allocated for the key array
    free(keys);
}

// Define function to free memory for an array of records
void free_records(struct Record* records) {
    // Check if the records pointer is valid and prevent potential errors
    if (records == NULL) {
        return;
    }

    // Free the memory allocated for the record array
    free(records);
}

// Define function to manage dynamic memory allocations for multiple data structures in a multi-threaded environment
void* manage_memory(int num_offsets, int num_keys, int num_records) {
    // Allocate memory for the offset array
    struct Offset* offsets = allocate_offsets(num_offsets);
    if (offsets == NULL) {
        return NULL;
    }

    // Allocate memory for the key array
    int* keys = allocate_keys(offsets, num_keys);
    if (keys == NULL) {
        free_offsets(offsets);
        return NULL;
    }

    // Allocate memory for the record array
    struct Record* records = allocate_records(offsets, num_records);
    if (records == NULL) {
        free_keys(keys);
        free_offsets(offsets);
        return NULL;
    }

    // Return a pointer to the memory allocated for the data structures
    return records;
}

// Define function to free all allocated memory upon function exit, considering the complexity of deallocation in a multi-threaded context to prevent race conditions
void free_memory(void* memory) {
    // Check if the memory pointer is valid and prevent potential errors
    if (memory == NULL) {
        return;
    }

    // Cast the memory pointer to the appropriate data structure type
    struct Record* records = memory;
    struct Offset* offsets = records[0].offset;
    int* keys = offsets[0].offset;

    // Free the memory allocated for the offset array
    free_offsets(offsets);

    // Free the memory allocated for the key array
    free_keys(keys);

    // Free the memory allocated for the record array
    free_records(records);
}
