// Define the struct for a transaction object
struct transaction {
    int id;
    long timestamp;
    float amount;
    char status[10]; // 10 bytes for the status string
};

// Function to initialize the transaction collection
void init_transactions(char* filename, int num_transactions) {
    // Open the file and check for errors
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file %s\n", filename);
        return;
    }

    // Allocate memory for the array of transaction structures
    struct transaction* transactions = malloc(sizeof(struct transaction) * num_transactions);
    if (transactions == NULL) {
        printf("Error allocating memory for transactions\n");
        fclose(file);
        return;
    }

    // Read the file and populate the transaction array with data
    int i = 0;
    while (fscanf(file, "%d %ld %f %s", &transactions[i].id, &transactions[i].timestamp, &transactions[i].amount, transactions[i].status) == 4) {
        // Set the status to a random value based on a probability distribution
        if (rand() / (float)RAND_MAX < 0.1) {
            strcpy(transactions[i].status, "FAILURE");
        } else {
            strcpy(transactions[i].status, "SUCCESS");
        }
        i++;
    }

    // Close the file and free memory
    fclose(file);
    free(transactions);
}

// Function to generate random values for the transaction amounts within a range
void generate_random_values(struct transaction* transactions, int num_transactions) {
    // Generate random values between 10 and 100 inclusive
    for (int i = 0; i < num_transactions; i++) {
        transactions[i].amount = (float)(rand() % 90 + 10);
    }
}

// Function to calculate the average transaction amount and print it to the console
void print_average(struct transaction* transactions, int num_transactions) {
    float total = 0;
    for (int i = 0; i < num_transactions; i++) {
        total += transactions[i].amount;
    }
    printf("Average transaction amount: %.2f\n", total / num_transactions);
}

// Function to calculate the number of successful transactions and print it to the console
void print_successful(struct transaction* transactions, int num_transactions) {
    int successful = 0;
    for (int i = 0; i < num_transactions; i++) {
        if (strcmp(transactions[i].status, "SUCCESS") == 0) {
            successful++;
        }
    }
    printf("Total number of successful transactions: %d\n", successful);
}

// Function to free all allocated memory
void free_memory() {
    // Free the memory allocated for the transaction array
    free(transactions);
