//  - csv_file: path to the CSV file
//  - num_data_points: maximum number of data points to be initialized (optional)
//  - random_value_range: range for generating random values (optional)
//  - max_processing_limit: maximum number of data points to process (optional)
// Outputs:
//  - data_array: array of 'DataPoint' structures containing the processed data
//  - num_data_points: actual number of data points processed
bool process_csv(const char* csv_file, int* num_data_points, DataPoint** data_array, double random_value_range, int max_processing_limit);

#endif // CSV_PROCESSOR_H

// Implementation File:
#include "csv_processor.h"

#define LOGGING 1 // Enable or disable logging (0 to disable, 1 to enable)

bool process_csv(const char* csv_file, int* num_data_points, DataPoint** data_array, double random_value_range, int max_processing_limit) {
    if (!csv_file || !num_data_points || !data_array) {
        return false; // Invalid input
    }

#if LOGGING
    // Initialize logging system
    log_init();
#endif

    // Open the CSV file and check for errors
    FILE* csv = fopen(csv_file, "r");
    if (!csv) {
        printf("Error: Failed to open CSV file '%s'\n", csv_file);
        return false;
    }

    // Read the header line of the CSV file
    char* header = read_line(csv);

    // Get the number of data points from the header (if specified)
    int num_header_cols = 0;
    if (num_data_points) {
        num_header_cols = get_num_columns(header);
        *num_data_points = num_header_cols - 1; // Ignore the first column (which is the timestamp)
    }

    // Allocate memory for the data array
    if (!(*data_array = malloc((*num_data_points) * sizeof(DataPoint)))) {
        printf("Error: Failed to allocate memory for data array\n");
#if LOGGING
        log_error("Failed to allocate memory for data array");
#endif
        fclose(csv);
        return false;
    }

    // Initialize the data array with random values within the specified range (if specified)
    if (random_value_range > 0 && max_processing_limit > 0) {
        for (int i = 0; i < *num_data_points; i++) {
            (*data_array)[i].value = random_double(random_value_range);
        }
    }

    // Read the data points from the CSV file and process them
    char* line = read_line(csv);
    int num_processed_points = 0;
    while (line && !feof(csv)) {
        if (num_processed_points >= max_processing_limit) {
            break; // Reach the maximum processing limit
        }

        // Parse the data point from the line
        DataPoint* data = parse_data_point(line, num_header_cols);

        // Check for errors in parsing the data point
        if (!data) {
            printf("Error: Failed to parse data point\n");
#if LOGGING
            log_error("Failed to parse data point");
#endif
            break; // Stop processing the file
        }

        // Add the data point to the array
        (*data_array)[num_processed_points++] = *data;

        // Free the memory allocated for the parsed data point
        free(data);

#if LOGGING
        log_debug("Processed data point");
#endif

        // Read the next line from the CSV file
        line = read_line(csv);
    }

    // Close the CSV file
    fclose(csv);

    // Calculate and print the average value of the array of data points (if specified)
    if (*num_data_points > 0 && num_processed_points > 0) {
        double sum = 0.0;
        for (int i = 0; i < num_processed_points; i++) {
            sum += (*data_array)[i].value;
        }
        printf("Average value: %.2f\n", sum / (double)num_processed_points);
    }

#if LOGGING
    log_close();
#endif

    return true; // Successful processing
}

// Helper function to read a line from the CSV file
char* read_line(FILE* csv) {
    char* line = NULL;
    size_t len = 0;
    ssize_t read;

    // Read the next line from the CSV file
    while ((read = getdelim(&line, &len, ',', csv)) != -1) {
        if (line[read - 1] == '\n') {
            break; // Reach the end of the line
        }
    }

    return line;
}

// Helper function to parse a data point from a CSV line
DataPoint* parse_data_point(char* line, int num_header_cols) {
    DataPoint* data = malloc(sizeof(DataPoint));
    if (!data) {
        return NULL; // Failed to allocate memory for the data point
    }

    // Parse the timestamp from the first column of the CSV line
    char* timestamp = strtok(line, ",");
    if (!timestamp) {
        free(data);
        return NULL; // Failed to parse the timestamp
    }

    // Ignore the timestamp and parse the data point value from the second column (if specified)
    if (num_header_cols > 1) {
        char* value = strtok(NULL, ",");
        if (!value) {
            free(data);
            return NULL; // Failed to parse the data point value
        }

        double parsed_value = atof(value);
        if (isnan(parsed_value) || isinf(parsed_value)) {
            free(data);
            return NULL; // Invalid input data (e.g., NaN or infinity)
        }

        data->value = parsed_value;
    }

    return data;
}

// Helper function to generate a random double value within the specified range
double random_double(double range) {
    return range * ((double)rand() / RAND_MAX);
}

