#include <semaphore.h>
#include <unistd.h>

typedef struct {
    time_t timestamp;
    int severity;
    char *message;
} log_entry;

log_entry *process_log_entries(int num_entries, char *input) {
    // Validate input format and count number of entries
    int entry_count = 0;
    for (int i = 0; i < strlen(input); i++) {
        if (input[i] == '\n') {
            entry_count++;
        }
    }
    // Initialize array of log entries
    log_entry *log_entries = malloc(sizeof(log_entry) * entry_count);
    if (!log_entries) {
        perror("Failed to allocate memory for log entries");
        return NULL;
    }
    // Parse input and populate log entries array
    int current_index = 0;
    char *line = strtok(input, "\n");
    while (line != NULL) {
        log_entry entry;
        if (sscanf(line, "%lld %d %m", &entry.timestamp, &entry.severity, &entry.message) == 3) {
            log_entries[current_index] = entry;
            current_index++;
        } else {
            fprintf(stderr, "Invalid input format: %s\n", line);
        }
        line = strtok(NULL, "\n");
    }
    return log_entries;
}

void free_log_entries(log_entry *log_entries) {
    for (int i = 0; i < sizeof(log_entries)/sizeof(log_entry); i++) {
        free(log_entries[i].message);
    }
    free(log_entries);
}

void process_log_entries_threadsafe(log_entry *log_entries, int num_threads) {
    // Create semaphore for synchronizing access to log entries array
    sem_t *sem = sem_open("semaphore", O_CREAT, 0644, 1);
    if (sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        return;
    }
    // Create threads for processing log entries
    pthread_t *threads = malloc(sizeof(pthread_t) * num_threads);
    if (!threads) {
        perror("Failed to allocate memory for thread IDs");
        sem_close(sem);
        return;
    }
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, process_log_entry, (void *)&log_entries[i]);
    }
    // Wait for all threads to complete
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }
    free(threads);
    sem_close(sem);
}

void *process_log_entry(void *arg) {
    // Get log entry from argument and lock semaphore for accessing shared data
    log_entry *log_entry = (log_entry *)arg;
    sem_wait(&sem);
    // Process log entry
    printf("Processing log entry: %lld, %d, %s\n", log_entry->timestamp, log_entry->severity, log_entry->message);
    // Release semaphore and return
    sem_post(&sem);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <number of threads>\n", argv[0]);
        return 1;
    }
    int num_threads = atoi(argv[1]);
    // Read log entries from file or network stream and process them in parallel using the specified number of threads
    char *input = read_log_entries();
    if (!input) {
        perror("Failed to read log entries");
        return 1;
    }
    log_entry *log_entries = process_log_entries(num_threads, input);
    free_log_entries(log_entries);
    return 0;
}
```
