static const int MIN_KEY = 0; // minimum value for generated keys
static const int MAX_KEY = 1000000; // maximum value for generated keys

void *generate_records(void *data) {
    long offset = (long)data;
    record_t *record = malloc(sizeof(record_t));
    if (!record) {
        printf("Failed to allocate memory for record\n");
        return NULL;
    }
    record->key = MIN_KEY + offset % (MAX_KEY - MIN_KEY);
    return record;
}

