// Header file: record_manager.h
#include <stdlib.h>
#include <stdint.h>
#include <stdio.h>
#include <math.h>

// Record structure for storing key, offset, and weight
typedef struct {
    int key;
    long offset;
    double weight;
} record_t;

// Function prototype
record_t* insert_record(int key, long offset, double weight);
record_t* update_record(int key, long offset, double weight);
record_t* delete_record(int key);
void print_records();

// Record manager function
record_t* record_manager(int op_type, int key, long offset, double weight) {
    switch (op_type) {
        case INSERT:
            return insert_record(key, offset, weight);
        case UPDATE:
            return update_record(key, offset, weight);
        case DELETE:
            return delete_record(key);
        default:
            printf("Invalid operation type\n");
    }
}

// Insert record function
record_t* insert_record(int key, long offset, double weight) {
    // Check if the key is unique and the weight is non-negative
    if (is_unique_key(key) && !isnan(weight)) {
        // Allocate memory for the record structure
        record_t* new_record = malloc(sizeof(record_t));
        if (new_record == NULL) {
            printf("Memory allocation failed\n");
            return NULL;
        }

        // Initialize the record with the given key, offset, and weight
        new_record->key = key;
        new_record->offset = offset;
        new_record->weight = weight;

        // Add the record to the linked list
        add_to_list(new_record);

        return new_record;
    } else {
        printf("Invalid key or weight\n");
        return NULL;
    }
}

// Update record function
record_t* update_record(int key, long offset, double weight) {
    // Check if the key is unique and the weight is non-negative
    if (is_unique_key(key) && !isnan(weight)) {
        // Find the record with the given key in the linked list
        record_t* record = find_record(key);
        if (record == NULL) {
            printf("Record not found\n");
            return NULL;
        }

        // Update the offset and weight of the record
        record->offset = offset;
        record->weight = weight;

        return record;
    } else {
        printf("Invalid key or weight\n");
        return NULL;
    }
}

// Delete record function
record_t* delete_record(int key) {
    // Find the record with the given key in the linked list
    record_t* record = find_record(key);
    if (record == NULL) {
        printf("Record not found\n");
        return NULL;
    }

    // Remove the record from the linked list
    remove_from_list(record);

    return record;
}

// Check if a key is unique in the linked list
bool is_unique_key(int key) {
    // Iterate through the linked list to check for duplicate keys
    record_t* current = head;
    while (current != NULL) {
        if (current->key == key) {
            return false;
        }
        current = current->next;
    }
    return true;
}

// Add a record to the linked list
void add_to_list(record_t* new_record) {
    // If the linked list is empty, set the head and tail pointers
    if (head == NULL && tail == NULL) {
        head = new_record;
        tail = new_record;
        return;
    }

    // Add the record to the end of the linked list
    tail->next = new_record;
    tail = new_record;
}

// Find a record in the linked list by key
record_t* find_record(int key) {
    // Iterate through the linked list to find the record with the given key
    record_t* current = head;
    while (current != NULL && current->key != key) {
        current = current->next;
    }
    return current;
}

// Remove a record from the linked list
void remove_from_list(record_t* record) {
    // If the record is the head, set the new head and update the tail if necessary
    if (head == record && tail == record) {
        head = NULL;
        tail = NULL;
        return;
    } else if (head == record) {
        head = record->next;
    }

    // If the record is not the head, find its predecessor and remove it from the linked list
    record_t* predecessor = head;
    while (predecessor != NULL && predecessor->next != record) {
        predecessor = predecessor->next;
    }
    if (predecessor == NULL) {
        printf("Record not found\n");
        return;
    }
    predecessor->next = record->next;
}

// Print all records in the linked list
void print_records() {
    // Iterate through the linked list and print each record
    record_t* current = head;
    while (current != NULL) {
        printf("Record: %d, Offset: %ld, Weight: %.2lf\n", current->key, current->offset, current->weight);
        current = current->next;
    }
}
