#include <stdlib.h>
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Structure to represent a record in the distributed data storage system
typedef struct {
    int key;   // Integer key for the record
    long value; // Long integer value for the record
} Record;

// Function to dynamically allocate memory and initialize multiple arrays for managing a distributed data storage system
void init_storage(int num_records, int max_key) {
    // Calculate the total size of the array needed to store all records
    long total_size = sizeof(Record) * num_records;

    // Allocate memory for the arrays using a single call to malloc()
    void* buffer = malloc(total_size);

    // Check if memory allocation failed
    if (buffer == NULL) {
        fprintf(stderr, "Failed to allocate memory for storage array\n");
        return;
    }

    // Initialize the arrays using memset()
    memset(buffer, 0, total_size);

    // Cast the buffer to a pointer to the Record struct and assign it to a local variable
    Record* records = (Record*)buffer;

    // Generate random integer values for each record within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % max_key + 1;
        records[i].value = rand() % 1000000;
    }

    // Verify uniqueness of all keys before proceeding
    for (int i = 0; i < num_records - 1; i++) {
        for (int j = i + 1; j < num_records; j++) {
            if (records[i].key == records[j].key) {
                fprintf(stderr, "Duplicate key detected in storage array\n");
                return;
            }
        }
    }

    // Initialize a mutex to protect the arrays from concurrent access
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Store the mutex and array in a global variable to make them accessible from other threads
    globals.lock = &lock;
    globals.records = records;
}

// Structure to store global variables needed by the storage system
struct {
    pthread_mutex_t* lock; // Mutex for protecting concurrent access to the arrays
    Record* records;       // Array of Records to store the data
} globals;

// Function to handle memory allocation failures gracefully
void handle_failure() {
    fprintf(stderr, "Memory allocation failure occurred\n");
    pthread_mutex_unlock(&globals.lock); // Unlock the mutex before returning
    return;
}

// Function to add a new record to the storage system
void add_record(int key, long value) {
    // Lock the mutex to prevent concurrent access to the arrays
    pthread_mutex_lock(&globals.lock);

    // Search for an empty slot in the array to store the new record
    Record* records = globals.records;
    for (int i = 0; i < num_records; i++) {
        if (records[i].key == 0) {
            records[i].key = key;
            records[i].value = value;
            break;
        }
    }

    // If no empty slot was found, reallocate the array with a larger size
    if (i == num_records) {
        num_records *= 2;
        total_size += sizeof(Record);
        records = realloc(records, total_size);
        if (records == NULL) {
            handle_failure();
            return;
        }
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&globals.lock);
}

// Function to retrieve a record from the storage system based on its key
Record get_record(int key) {
    // Lock the mutex to prevent concurrent access to the arrays
    pthread_mutex_lock(&globals.lock);

