    // Lock the mutex to prevent concurrent access to the arrays
    pthread_mutex_lock(&globals.lock);

    // Search for the requested record in the array
    Record* records = globals.records;
    for (int i = 0; i < num_records; i++) {
        if (records[i].key == key) {
            records[i].value = value;
            break;
        }
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&globals.lock);
}

// Function to delete a record from the storage system based on its key
