    // Lock the mutex to prevent concurrent access to the arrays
    pthread_mutex_lock(&globals.lock);

    // Search for the requested record in the array
    Record* records = globals.records;
    for (int i = 0; i < num_records; i++) {
        if (records[i].key == key) {
            // Shift all subsequent records to fill the gap created by deleting this record
            for (int j = i + 1; j < num_records; j++) {
                records[j - 1] = records[j];
            }
            break;
        }
    }

    // Reallocate the array with a smaller size to free up memory
    total_size -= sizeof(Record);
    records = realloc(records, total_size);
    if (records == NULL) {
        handle_failure();
        return;
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&globals.lock);
}
