#include <string.h>
#include <time.h>

// Third-party library for random number generation
#include "random_number_gen.h"

// Macro for defining the size of each record in bytes
#define RECORD_SIZE (sizeof(long) + sizeof(int) + sizeof(char*))

// Struct representing a single record
typedef struct {
    long offset;
    int key;
    char* string;
} Record;

// Function for initializing arrays of offsets, keys, and strings
void init_arrays(long num_records, int max_string_length) {
    // Calculate the total size required for all records in bytes
    long total_size = RECORD_SIZE * num_records;

    // Allocate memory for the arrays of offsets and keys
    long* offset_array = (long*)malloc(total_size);
    int* key_array = (int*)malloc(total_size);

    // Initialize the arrays with random values within a specified range
    srand(time(NULL));
    for (long i = 0; i < num_records; ++i) {
        offset_array[i] = rand() % total_size;
        key_array[i] = rand() % INT_MAX;
    }

    // Allocate memory for each string and fill it with random ASCII characters
    for (long i = 0; i < num_records; ++i) {
        Record* record = (Record*)offset_array[i];
        record->string = malloc(max_string_length + 1);
        if (!record->string) {
            // Handle memory allocation failure gracefully by freeing all allocated memory
            for (long j = 0; j < i; ++j) {
                Record* prev_record = (Record*)offset_array[j];
                free(prev_record->string);
            }
            free(offset_array);
            free(key_array);
            return;
        }
        for (int j = 0; j < max_string_length; ++j) {
            record->string[j] = rand() % 128 + '!';
        }
        record->string[max_string_length] = '\0';
    }
}

// Function for generating random values within a specified range
long get_random_value(long min, long max) {
    // Use the third-party library for generating random numbers
    return (rand() % (max - min + 1)) + min;
}

// Function for freeing memory allocated for arrays of offsets and keys
void free_arrays(long* offset_array, int* key_array) {
    // Free each string in the array
    for (long i = 0; i < num_records; ++i) {
        Record* record = (Record*)offset_array[i];
        free(record->string);
    }

    // Free the arrays of offsets and keys
    free(offset_array);
    free(key_array);
}
