#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <math.h>
#include "my_custom_library.h" // include third-party library for floating-point arithmetic

// Define struct for point coordinates
typedef struct {
  int x;
  int y;
} point;

// Define function to initialize arrays with random values
void init_arrays(double **doubles, unsigned long **timestamps, point **points, char ***strings, int num_points, int max_string_length, double min, double max) {
  // Allocate memory for arrays
  *doubles = malloc(num_points * sizeof(double));
  *timestamps = malloc(num_points * sizeof(unsigned long));
  *points = malloc(num_points * sizeof(point));
  *strings = malloc(num_points * max_string_length * sizeof(char));

  // Generate random values for floating-point array
  for (int i = 0; i < num_points; i++) {
    (*doubles)[i] = generate_random_double(min, max);
    (*timestamps)[i] = generate_random_ulong();
    (*points)[i].x = generate_random_int();
    (*points)[i].y = generate_random_int();
  }

  // Generate random ASCII characters for string array
  for (int i = 0; i < num_points * max_string_length; i++) {
    char c = generate_random_ascii();
    (*strings)[i] = malloc(sizeof(char));
    (*strings)[i][0] = c;
  }
}

// Define function to free memory allocated by init_arrays
void cleanup_arrays(double **doubles, unsigned long **timestamps, point **points, char ***strings) {
  // Free memory for arrays
  free(*doubles);
  free(*timestamps);
  free(*points);
  for (int i = 0; i < num_points * max_string_length; i++) {
    free((*strings)[i]);
  }
  free(*strings);
}

// Define function to generate random double within range
double generate_random_double(double min, double max) {
  return min + ((double)(rand() % (RAND_MAX + 1)) / RAND_MAX) * (max - min);
}

// Define function to generate random unsigned long integer
unsigned long generate_random_ulong() {
  return rand() % ULONG_MAX;
}

// Define function to generate random integer within range
int generate_random_int(int min, int max) {
  return min + ((int)(rand() % (RAND_MAX + 1)) / RAND_MAX) * (max - min);
}

// Define function to generate random ASCII character
char generate_random_ascii() {
  return '!' + rand() % 94; // ASCII characters from ! to ~
}
