#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Data structures for storing double precision floating point numbers and char data
typedef struct {
    double *data;
    size_t count;
} double_entry_t;

typedef struct {
    char *data;
    size_t count;
} char_entry_t;

// Data structure for storing references to 'data_entry' instances
typedef struct {
    double_entry_t *double_store;
    char_entry_t *char_store;
    pthread_mutex_t mutex;
} data_entry_collection_t;

// Function for populating the 'data_entry' collection with randomly generated data
void populate_data_entries(data_entry_collection_t *collection, size_t count) {
    // Initialize the mutex
    pthread_mutex_init(&collection->mutex, NULL);

    // Allocate memory for the double and char stores
    collection->double_store = malloc(count * sizeof(double_entry_t));
    collection->char_store = malloc(count * sizeof(char_entry_t));

    // Initialize the reference count for each 'data_entry' instance
    for (size_t i = 0; i < count; i++) {
        collection->double_store[i].count = 0;
        collection->char_store[i].count = 0;
    }

    // Populate the stores with randomly generated data
    srand(time(NULL));
    for (size_t i = 0; i < count; i++) {
        double random_double = ((double) rand() / (RAND_MAX)) * 10.0;
        collection->double_store[i].data = malloc(sizeof(double) * random_double);
        for (size_t j = 0; j < random_double; j++) {
            collection->double_store[i].data[j] = rand() / (RAND_MAX + 1.0);
        }

        char random_char[256];
        for (size_t j = 0; j < 256; j++) {
            random_char[j] = 'a' + (rand() % 26);
        }
        collection->char_store[i].data = strdup(random_char);
    }
}

// Function for adding a new 'data_entry' instance to the collection
void add_data_entry(data_entry_collection_t *collection, double data) {
    // Acquire the mutex
    pthread_mutex_lock(&collection->mutex);

    // Allocate memory for the new 'data_entry' instance
    collection->double_store = realloc(collection->double_store, (collection->count + 1) * sizeof(double_entry_t));
    collection->char_store = realloc(collection->char_store, (collection->count + 1) * sizeof(char_entry_t));

    // Initialize the new 'data_entry' instance
    collection->double_store[collection->count].data = malloc(sizeof(double) * data);
    for (size_t i = 0; i < data; i++) {
        collection->double_store[collection->count].data[i] = rand() / (RAND_MAX + 1.0);
    }

    // Initialize the reference count for the new 'data_entry' instance
    collection->double_store[collection->count].count = 0;
    collection->char_store[collection->count].count = 0;

    // Increment the reference count for all existing 'data_entry' instances
    for (size_t i = 0; i < collection->count; i++) {
        collection->double_store[i].count++;
        collection->char_store[i].count++;
    }

    // Release the mutex
    pthread_mutex_unlock(&collection->mutex);
}

// Function for removing an existing 'data_entry' instance from the collection
void remove_data_entry(data_entry_collection_t *collection, size_t index) {
    // Acquire the mutex
    pthread_mutex_lock(&collection->mutex);

    // Decrement the reference count for all existing 'data_entry' instances after the given index
    for (size_t i = index + 1; i < collection->count; i++) {
        collection->double_store[i].count--;
        collection->char_store[i].count--;
    }

    // Free the memory associated with the removed 'data_entry' instance
    free(collection->double_store[index].data);
    free(collection->char_store[index].data);

    // Shift all remaining 'data_entry' instances down to fill the gap
    for (size_t i = index; i < collection->count - 1; i++) {
        collection->double_store[i] = collection->double_store[i + 1];
        collection->char_store[i] = collection->char_store[i + 1];
    }

    // Decrement the count of 'data_entry' instances and free the memory associated with the removed instance
    collection->count--;
    collection->double_store = realloc(collection->double_store, collection->count * sizeof(double_entry_t));
    collection->char_store = realloc(collection->char_store, collection->count * sizeof(char_entry_t));

    // Release the mutex
    pthread_mutex_unlock(&collection->mutex);
}

// Function for safely freeing all allocated memory once the operation is complete
void cleanup_data_entries(data_entry_collection_t *collection) {
    // Acquire the mutex
    pthread_mutex_lock(&collection->mutex);

    // Free the memory associated with each 'data_entry' instance
    for (size_t i = 0; i < collection->count; i++) {
        free(collection->double_store[i].data);
        free(collection->char_store[i].data);
    }

    // Free the memory associated with the double and char stores
    free(collection->double_store);
    free(collection->char_store);

    // Release the mutex
    pthread_mutex_unlock(&collection->mutex);
