// Custom memory pool to reduce fragmentation and improve allocation speed
struct MemoryPool {
  void* memory;
  size_t size;
};

// Data structure for holding 'double' precision floating-point numbers
struct DoubleDataStore {
  double* data;
  size_t capacity;
};

// Data structure for holding 'char' data
struct CharDataStore {
  char* data;
  size_t capacity;
};

// Structure for tracking active references to 'data_entry' instances
struct ReferenceCounter {
  uint32_t count;
};

// Data entry structure containing both types of data along with a reference counter
struct DataEntry {
  double* doubleData;
  size_t doubleSize;
  char* charData;
  size_t charSize;
  ReferenceCounter refCount;
};

// Thread-safe collection for storing 'data_entry' instances
struct DataStore {
  pthread_mutex_t mutex;
  semaphore_t semaphore;
  struct DataEntry* entries[];
};

// Function to populate the data store with data from an external API call
int populateDataStore(struct DataStore* store, int size) {
  // Acquire lock on data store
  pthread_mutex_lock(&store->mutex);

  // Populate data store with new data
  for (int i = 0; i < size; i++) {
    struct DataEntry* entry = malloc(sizeof(struct DataEntry));
    if (!entry) {
      // Handle memory allocation error
      pthread_mutex_unlock(&store->mutex);
      return -1;
    }

    // Initialize reference counter to 0
    entry->refCount.count = 0;

    // Allocate memory for double and char data
    int err = allocData(entry, size);
    if (err) {
      free(entry);
      pthread_mutex_unlock(&store->mutex);
      return -1;
    }

    // Add entry to data store
    store->entries[i] = entry;
  }

  // Release lock on data store
  pthread_mutex_unlock(&store->mutex);
  return 0;
}

// Function for allocating memory for double and char data
int allocData(struct DataEntry* entry, int size) {
  // Allocate memory for double data
  void* mem = customAlloc(sizeof(double) * size);
  if (!mem) {
    return -1;
  }

  // Initialize double data
  entry->doubleData = (double*)mem;
  entry->doubleSize = sizeof(double) * size;

  // Allocate memory for char data
  mem = customAlloc(sizeof(char) * size);
  if (!mem) {
    return -1;
  }

  // Initialize char data
  entry->charData = (char*)mem;
  entry->charSize = sizeof(char) * size;

  return 0;
}

// Function for dynamically adding and removing 'data_entry' instances from the collection
int addEntry(struct DataStore* store, struct DataEntry* entry) {
  // Acquire lock on data store
  pthread_mutex_lock(&store->mutex);

  // Add entry to data store
  store->entries[store->size] = entry;
  store->size++;

  // Release lock on data store
  pthread_mutex_unlock(&store->mutex);
  return 0;
}

int removeEntry(struct DataStore* store, struct DataEntry* entry) {
  // Acquire lock on data store
  pthread_mutex_lock(&store->mutex);

  // Remove entry from data store
  for (int i = 0; i < store->size; i++) {
    if (store->entries[i] == entry) {
      free(store->entries[i]);
      store->entries[i] = NULL;
      break;
    }
  }

  // Release lock on data store
  pthread_mutex_unlock(&store->mutex);
  return 0;
}

// Function for safely freeing memory associated with 'data_entry' instances
void freeData(struct DataEntry* entry) {
  // Acquire lock on data store
  pthread_mutex_lock(&store->mutex);

  // Free double and char data
  customFree(entry->doubleData);
  customFree(entry->charData);

  // Release lock on data store
  pthread_mutex_unlock(&store->mutex);
}

// Custom memory allocation function for reducing fragmentation and improving allocation speed
void* customAlloc(size_t size) {
  void* mem = malloc(size);
  if (!mem) {
    return NULL;
  }

  // Initialize memory pool if necessary
  if (memoryPool == NULL) {
    memoryPool = malloc(sizeof(struct MemoryPool));
    if (!memoryPool) {
      free(mem);
      return NULL;
    }

    memoryPool->memory = mem;
    memoryPool->size = size;
  } else {
    // Check if there is enough space in the memory pool
    if (memoryPool->size - (char*)mem > size) {
      // If there is enough space, allocate from the pool
      void* result = mem;
      mem = (char*)mem + size;
      memoryPool->size -= size;

      return result;
    } else {
      // If there isn't enough space in the pool, allocate a new block of memory
      free(memoryPool);
      memoryPool = malloc(sizeof(struct MemoryPool));
      if (!memoryPool) {
        free(mem);
        return NULL;
      }

      memoryPool->memory = mem;
      memoryPool->size = size;
    }
  }

  return mem;
}

// Custom memory deallocation function for safely freeing memory
void customFree(void* mem) {
  // Check if the memory is in the pool
  if (memoryPool != NULL && memoryPool->memory <= mem && mem < (char*)memoryPool->memory + memoryPool->size) {
    // If it is, add it to the pool
    memoryPool->size += (char*)mem - memoryPool->memory;
    return;
  }

  // Otherwise, free the memory normally
  free(mem);
}
