    double timestamp;
    char *event_description;
};

// Function to dynamically allocate memory for arrays
void alloc_memory(int n, int m) {
    // Allocate memory for the arrays
    measurement *measurements = malloc(n * sizeof(struct measurement));
    unsigned short *identifiers = malloc(m * sizeof(unsigned short));
    char **metadata = malloc(n * sizeof(char *));
    struct log *logs = malloc(m * sizeof(struct log));

    // Initialize the arrays
    for (int i = 0; i < n; ++i) {
        measurements[i].temperature = NAN;
        measurements[i].humidity = NAN;
        measurements[i].notes = NULL;
        measurements[i].log_entry = NULL;
    }
    for (int i = 0; i < m; ++i) {
        identifiers[i] = 0;
        metadata[i] = NULL;
        logs[i].timestamp = 0.0;
        logs[i].event_description = NULL;
    }
}

// Function to read data from a compressed file and populate the arrays
void process_data(FILE *file, int n, int m) {
    // Read the input file line by line
    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        // Split the line into tokens using whitespace as delimiter
        char *tokens = strtok(line, " ");
        int count = 0;
        while (tokens != NULL) {
            if (count == 0) {
                // Parse the first token as an identifier
                unsigned short id = atoi(tokens);
                identifiers[id]++;
            } else if (count == 1) {
                // Parse the second token as a measurement value
                float value = atof(tokens);
                measurements[id].temperature += value;
            } else if (count == 2) {
                // Parse the third token as another measurement value
                float value = atof(tokens);
                measurements[id].humidity += value;
            } else if (count >= 3 && count <= 5) {
                // Skip additional tokens until we reach a newline character
                while (*tokens != '\n') {
                    tokens++;
                }
            } else if (count == 6) {
                // Parse the seventh token as a timestamp value
                double timestamp = atof(tokens);
                logs[id].timestamp = timestamp;
            } else if (count >= 7 && count <= 10) {
                // Skip additional tokens until we reach a newline character
                while (*tokens != '\n') {
                    tokens++;
                }
            } else if (count == 11) {
                // Parse the eleventh token as an event description
                char *event_description = strdup(tokens);
                logs[id].event_description = event_description;
            } else if (count >= 12 && count <= 15) {
                // Skip additional tokens until we reach a newline character
                while (*tokens != '\n') {
                    tokens++;
                }
            }
            // Increment the token count
            count++;
        }
    }
}

