    // Validate command-line arguments
    if (argc < 6) {
        printf("Usage: %s input_file output_file transformation_rules memory_limit lossless priority\n", argv[0]);
        return 1;
    }

    // Get command-line arguments
    char *input_file = argv[1];
    char *output_file = argv[2];
    char *rules_string = argv[3];
    int max_memory = atoi(argv[4]);
    bool lossless = (strcmp(argv[5], "lossless") == 0);
    priority_level_t level = (priority_level_t)atoi(argv[6]);

    // Parse transformation rules
    int num_rules = 0;
    transformation_rule_t *rules = parse_transformation_rules(rules_string, &num_rules);

    // Initialize memory limit
    if (max_memory < 1) {
        max_memory = 1;
    }

    // Create threads for concurrent read and write operations
    int num_threads = 0;
    pthread_t *threads = create_threads(num_threads, &level);

    // Process input file in parallel
    apply_transformation_rules(input_file, output_file, rules_string, max_memory, lossless, level);

    // Join threads
    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Log processing time and memory usage
    log_processing_time(input_file, output_file);
    log_memory_usage(input_file, output_file, max_memory);

    return 0;
}

// Function to create threads for concurrent read and write operations
pthread_t *create_threads(int num_threads, priority_level_t *level) {
    pthread_t *threads = (pthread_t *)malloc(num_threads * sizeof(pthread_t));
    if (!threads) {
        printf("Error: Unable to allocate memory for threads\n");
        return NULL;
    }

    // Create threads for parallel processing
    for (int i = 0; i < num_threads; ++i) {
        int *thread_id = malloc(sizeof(int));
        thread_id[i] = i;
        pthread_create(&threads[i], NULL, transform, (void *)thread_id);
    }

    return threads;
}

