        if (strlen(data[i]) > max_length) {
            max_length = strlen(data[i]);
        }
    }
    char *output_string = (char *)malloc(max_length * sizeof(char));

    // Apply transformation rules on each line of input file
    for (int i = 0; i < num_lines; ++i) {
        int rule_id = -1;
        if (!lossless) {
            rule_id = apply_transformation_rule(data[i], rules[i], output_string, max_length);
        } else {
            // Apply lossless transformation rule
        }
        write_to_output_file(output_file, output_string);
    }

    free(data);
    free(output_string);
}

// Function to parse input file and count number of lines
char **parse_input_file(char *input_file, int *num_lines) {
    // Open input file and read data line by line
    FILE *fp = fopen(input_file, "r");
    if (!fp) {
        printf("Error: Unable to open input file %s\n", input_file);
