        (*num_lines)++;
        data = realloc(data, (*num_lines) * sizeof(char *));
        if (!data) {
            printf("Error: Unable to allocate memory for data\n");
            return NULL;
        }
        data[*num_lines - 1] = (char *)malloc((strlen(buffer) + 1) * sizeof(char));
        strcpy(data[*num_lines - 1], buffer);
