    return rule.rule_id;
}

// Function to write output string to output file
void write_to_output_file(char *output_file, char *output_string) {
    // Open output file and write data line by line
    FILE *fp = fopen(output_file, "w");
    if (!fp) {
        printf("Error: Unable to open output file %s\n", output_file);
        return;
    }

    // Write output string to file
    fprintf(fp, "%s", output_string);
    fclose(fp);
