['package GameEngine;

import System.IO;

// XML file path for initial configuration settings
const string CONFIG_FILE_PATH = @"C:\GameConfig.xml";

public class ConfigurationManager {
    // Singleton instance to ensure only one instance of the manager is created
    private static readonly ConfigurationManager _instance = new ConfigurationManager();

    public static ConfigurationManager Instance {
        get { return _instance; }
    }

    private readonly Dictionary<string, object> _configurationSettings;

    // Private constructor to prevent direct instantiation
    private ConfigurationManager() {
        _configurationSettings = new Dictionary<string, object>();

        // Load initial configuration settings from XML file
        using (FileStream fs = File.OpenRead(CONFIG_FILE_PATH)) {
            XmlDocument doc = new XmlDocument();
            doc.Load(fs);
            foreach (XmlNode node in doc.DocumentElement.ChildNodes) {
                _configurationSettings[node.Name] = node.InnerText;
            }
        }
    }

    public void SetConfigurationValue(string key, object value) {
        // Update configuration settings
        _configurationSettings[key] = value;
    }

    public T GetConfigurationValue<T>(string key) {
        // Return configuration value for the given key
        return (T)_configurationSettings[key];
    }

    public void SaveConfiguration() {
        // Save current configuration settings to XML file
        using (FileStream fs = File.OpenWrite(CONFIG_FILE_PATH)) {
            XmlDocument doc = new XmlDocument();
            foreach (KeyValuePair<string, object> setting in _configurationSettings) {
                XmlElement element = doc.CreateElement(setting.Key);
                element.InnerText = setting.Value.ToString();
                doc.AppendChild(element);
            }
            doc.Save(fs);
        }
    }
}

// GameEngine class to manage dynamic configuration settings for game tiles, world dimensions, and camera speed
public class GameEngine {
    private readonly ConfigurationManager _configurationManager;

    public GameEngine() {
        _configurationManager = ConfigurationManager.Instance;
    }

    // Method to set game tile configuration
    public void SetTileConfiguration(int width, int height) {
        // Update configuration settings for game tiles
        _configurationManager.SetConfigurationValue("tileWidth", width);
        _configurationManager.SetConfigurationValue("tileHeight", height);
    }

    // Method to set world dimensions
    public void SetWorldDimensions(int width, int height) {
        // Update configuration settings for world dimensions
        _configurationManager.SetConfigurationValue("worldWidth", width);
        _configurationManager.SetConfigurationValue("worldHeight", height);
    }

    // Method to set camera speed
    public void SetCameraSpeed(float speed) {
        // Update configuration settings for camera speed
        _configurationManager.SetConfigurationValue("cameraSpeed", speed);
    }
}

