  }

  // Validate input data
  $id = isset($post['id']) ? sanitizeInput(htmlspecialchars($post['id'])) : null;
  $name = isset($post['name']) ? sanitizeInput(htmlspecialchars($post['name'])) : null;
  $email = isset($post['email']) ? sanitizeInput(htmlspecialchars($post['email'])) : null;
  $password = isset($post['password']) ? sanitizeInput(htmlspecialchars($post['password'])) : null;
  $subAction = isset($post['sub_action']) ? sanitizeInput(htmlspecialchars($post['sub_action'])) : null;

  // Handle updates and deletions
  if ($id !== null) {
    switch ($subAction) {
      case 'update':
        updateUser($id, $name, $email, $password);
        break;
      case 'delete':
        deleteUser($id);
        break;
      default:
        return false;
    }
  } else { // Handle user creation
    createUser($name, $email, $password);
  }

  // Cache frequently accessed user data for performance optimization
  cacheUserData($id);

  // Log all operations, including successful and failed transactions
  logOperation($id, $subAction, $name, $email, $password);

