import java.util.*;

public class BinarySearchTree {
  private Node root;

  public BinarySearchTree() {}

  public int search(int target) {
    return searchRecursive(root, target);
  }

  public void insert(int value) {
    root = new Node(value);
  }

  public void delete(int value) {
    root = deleteRecursive(root, value);
  }

  private class Node {
    int value;
    Node left, right;

    public Node(int value) {
      this.value = value;
    }
  }

  private int searchRecursive(Node node, int target) {
    if (node == null) {
      return -1;
    }

    int depth = searchRecursive(node.left, target);
    if (depth != -1) {
      return depth + 1;
    }

    if (node.value == target) {
      return 0;
    }

    return searchRecursive(node.right, target);
  }

  private Node deleteRecursive(Node node, int value) {
    if (node == null) {
      return null;
    }

    if (value < node.value) {
      node.left = deleteRecursive(node.left, value);
    } else if (value > node.value) {
      node.right = deleteRecursive(node.right, value);
    } else {
      // Node found, remove it from the tree
      if (node.left == null && node.right == null) {
        return null;
      }

      if (node.left == null) {
        return node.right;
      } else if (node.right == null) {
        return node.left;
      }

      Node minNode = findMin(node.right);
      minNode.right = deleteRecursive(node.right, minNode.value);
      minNode.left = node.left;
      return minNode;
    }

    // Update the root node value if necessary
    if (node.left != null && node.right != null) {
      int newRootValue = findMin(node.right).value;
      node.value = newRootValue;
    }

    return node;
  }

  private Node findMin(Node node) {
    while (node.left != null) {
      node = node.left;
    }

    return node;
  }
}
