};

function loadFile(fileName) {
  const script = document.createElement("script");
  script.src = fileName;
  return new Promise((resolve, reject) => {
    script.onload = () => resolve();
    script.onerror = () => reject(`Failed to load ${fileName}`);
    document.head.appendChild(script);
  });
}

function executeFile(fileName) {
  const script = document.createElement("script");
  script.src = fileName;
  return new Promise((resolve, reject) => {
    script.onload = () => resolve();
    script.onerror = () => reject(`Failed to execute ${fileName}`);
    document.head.appendChild(script);
  });
}

function loadAndExecuteFile(fileName) {
  return loadFile(fileName).then(() => executeFile(fileName));
}

async function run() {
  for (const fileName of fileOrder) {
    try {
      await loadAndExecuteFile(fileName);
    } catch (error) {
      console.log(`Error loading or executing ${fileName}: ${error}`);
    }
  }
}

run();
```
