import os
import time
from collections import OrderedDict
from threading import Thread
from queue import Queue

class ThemeCache:
    def __init__(self):
        self.cache = OrderedDict()
        self.queue = Queue()
        self.threads = []
        self.lock = threading.Lock()

    def get(self, key):
        with self.lock:
            if key in self.cache:
                value = self.cache[key]
                del self.cache[key]
                self.cache[key] = value
                return value
            else:
                return None

    def put(self, key, value):
        with self.lock:
            self.cache[key] = value

    def evict(self, num_elements=10):
        with self.lock:
            for i in range(num_elements):
                try:
                    key, value = self.queue.get_nowait()
                    del self.cache[key]
                except Queue.Empty:
                    break

    def update(self, key, value):
        with self.lock:
            if key in self.cache:
                self.cache[key] = value
            else:
                self.cache[key] = value

    def thread_worker(self):
        while True:
            try:
                key, value = self.queue.get()
                self.put(key, value)
            except Queue.Empty:
                break

    def start_threads(self, num_threads=4):
        for i in range(num_threads):
            t = Thread(target=self.thread_worker)
            t.daemon = True
            t.start()
            self.threads.append(t)

    def stop_threads(self):
        for t in self.threads:
            t.join()

class ThemeManager:
    def __init__(self, cache):
        self.cache = cache
        self.requests = []
        self.lock = threading.Lock()

    def get_theme(self, key):
        with self.lock:
            value = self.cache.get(key)
            if value is None:
                raise ThemeNotFoundError("Theme not found")
            else:
                return value

    def put_theme(self, key, value):
        with self.lock:
            self.cache.put(key, value)

    def update_theme(self, key, value):
        with self.lock:
            self.cache.update(key, value)

    def handle_request(self, request):
        with self.lock:
            self.requests.append(request)

    def process_requests(self):
        while True:
            try:
                request = self.requests.pop()
                key = request["key"]
                value = self.cache.get(key)
                if value is None:
                    raise ThemeNotFoundError("Theme not found")
                else:
                    return value
            except IndexError:
                break

