  private Map<String, Service> services = new HashMap<>();
  private Set<String> dependencies = new HashSet<>();
  private DependencyGraph graph = new DependencyGraph();

  public void startService(Service service) {
    logger.info("Starting microservice: " + service.getName());
    if (!services.containsKey(service.getName())) {
      services.put(service.getName(), service);
      dependencies.add(service.getName());
    } else {
      logger.warn("Service already started: " + service.getName());
    }
  }

  public void stopService(String name) {
    logger.info("Stopping microservice: " + name);
    if (services.containsKey(name)) {
      services.remove(name);
      dependencies.remove(name);
    } else {
      logger.warn("No such service found: " + name);
    }
  }

  public void addDependency(String parent, String child) {
    if (!dependencies.contains(parent)) {
      throw new IllegalArgumentException("Invalid dependency: " + parent);
    } else if (dependencies.contains(child)) {
      logger.warn("Dependency already exists: " + parent + " -> " + child);
    } else {
      graph.addEdge(parent, child);
    }
  }

  public void removeDependency(String parent, String child) {
    if (!dependencies.contains(parent)) {
      throw new IllegalArgumentException("Invalid dependency: " + parent);
    } else if (dependencies.contains(child)) {
      logger.warn("Dependency already exists: " + parent + " -> " + child);
    } else {
      graph.removeEdge(parent, child);
    }
  }

  public void run() {
    while (true) {
