        Thread.sleep(1000);
      } catch (InterruptedException e) {
        logger.error("Error running microservice manager", e);
      }
      for (String serviceName : services.keySet()) {
        Service service = services.get(serviceName);
        if (!graph.hasEdge(serviceName)) {
          continue;
        }
        List<String> dependencies = graph.getEdges(serviceName);
        logger.info("Checking dependencies for " + serviceName);
        for (String dependency : dependencies) {
          Service dependentService = services.get(dependency);
          if (!dependentService.isAvailable()) {
            logger.warn("Dependency " + dependency + " not available");
            notifyAlerts(serviceName, dependency);
            break;
          } else {
            logger.info("Dependency " + dependency + " is available");
          }
        }
      }
    }
  }

  private void notifyAlerts(String serviceName, String dependentService) {
