use std::process::Command;
use std::time::Instant;
use std::fs::File;
use std::io::{self, BufWriter};
use std::fmt::Write;

fn main() {
    let (exit_code, rss_before, rss_after) = compile();

    if exit_code != 0 {
        // Log error message
        log("Compilation failed with exit code {}", exit_code);
    } else {
        // Log compilation time and memory usage
        let duration = Instant::now().duration_since(rss_before).as_secs_f64();
        log("Compilation took {:.2} seconds and used {} bytes of RSS", duration, rss_after - rss_before);
    }
}

fn compile() -> (i32, u64, u64) {
    let mut cmd = Command::new("rustc");
    cmd.arg("--log-level=info");
    cmd.arg("--log-hook=hook_function");
    cmd.current_dir(".");

    // Measure time and RSS before compilation
    let rss_before = get_rss();
    let start = Instant::now();

    // Run the compiler
    let exit_code = cmd.status().unwrap();

    // Measure time and RSS after compilation
    let rss_after = get_rss();
    let duration = Instant::now().duration_since(start).as_secs_f64();

    (exit_code, rss_before, rss_after)
}

fn hook_function(level: i32, message: &str) {
    if level == 0 { // INFO level
        let log = format!("[{}][{}] {}", level, get_thread_id(), message);
        log(log.as_str());
    }
}

fn log(message: &str) {
    let mut file = File::create("log.txt").unwrap();
    writeln!(file, "{}", message).unwrap();
}

fn get_rss() -> u64 {
    use std::process::Command;
    let output = Command::new("ps")
        .arg("-o")
        .arg("rss")
        .arg(format!("{}", std::process::id()))
        .output()
        .unwrap();
    String::from_utf8(output.stdout).unwrap().trim().parse::<u64>().unwrap() * 1024
}

fn get_thread_id() -> u32 {
    use std::process::Command;
    let output = Command::new("ps")
        .arg("-o")
        .arg("tid")
        .arg(format!("{}", std::process::id()))
        .output()
        .unwrap();
    String::from_utf8(output.stdout).unwrap().trim().parse::<u32>().unwrap()
}
