public class CategoryManager {
    private static final ExecutorService executor = Executors.newFixedThreadPool(10);
    private static final Map<String, List<Long>> categoryProductMap = new HashMap<>();
    private static final Map<Long, String> productCategoryMap = new HashMap<>();

    public void addCategory(String name) {
        // Check if category already exists
        if (categoryProductMap.containsKey(name)) {
            throw new RuntimeException("Category already exists: " + name);
        }

        // Add new category to map
        categoryProductMap.put(name, new ArrayList<>());
    }

    public void updateCategoryName(String oldName, String newName) {
        // Check if category exists
        if (!categoryProductMap.containsKey(oldName)) {
            throw new RuntimeException("Category does not exist: " + oldName);
        }

        // Update category name in map
        categoryProductMap.put(newName, categoryProductMap.remove(oldName));
    }

    public void addProductToCategory(Long productId, String categoryName) {
        // Check if category exists
        if (!categoryProductMap.containsKey(categoryName)) {
            throw new RuntimeException("Category does not exist: " + categoryName);
        }

        // Add product to category in map
        List<Long> products = categoryProductMap.get(categoryName);
        products.add(productId);
        categoryProductMap.put(categoryName, products);

        // Update product-category mapping in map
        productCategoryMap.put(productId, categoryName);
    }

    public void removeProductFromCategory(Long productId, String categoryName) {
        // Check if category exists
        if (!categoryProductMap.containsKey(categoryName)) {
            throw new RuntimeException("Category does not exist: " + categoryName);
        }

        // Remove product from category in map
        List<Long> products = categoryProductMap.get(categoryName);
        products.remove(productId);
        if (products.isEmpty()) {
            categoryProductMap.remove(categoryName);
        } else {
            categoryProductMap.put(categoryName, products);
        }

        // Update product-category mapping in map
        productCategoryMap.remove(productId);
    }

    public void manageLowStockCategories() {
        List<String> lowStockCategories = new ArrayList<>();

        // Iterate over categories and check stock level
        for (String categoryName : categoryProductMap.keySet()) {
            int stockLevel = getCategoryStockLevel(categoryName);
            if (stockLevel < 20) {
                lowStockCategories.add(categoryName);
            }
        }

        // Prioritize categories with high demand-to-stock ratio
        lowStockCategories = lowStockCategories.stream().sorted((c1, c2) -> {
            int s1 = getCategoryStockLevel(c1);
            int s2 = getCategoryStockLevel(c2);
            if (s1 > s2) {
                return -1;
            } else if (s1 < s2) {
                return 1;
            } else {
                return c1.compareTo(c2);
            }
        }).collect(Collectors.toList());

        // Send notification to store managers for each category
        for (String categoryName : lowStockCategories) {
            int stockLevel = getCategoryStockLevel(categoryName);
            String message = "Low stock alert: Category '" + categoryName + "' has only " + stockLevel + " items in stock";
            sendNotificationToStoreManagers(message);
        }
    }

    public void sendNotificationToStoreManagers(String message) {
        // Implement notification sending logic here
    }

    private int getCategoryStockLevel(String categoryName) {
        return productCategoryMap.keySet().stream()
                .filter(productId -> productCategoryMap.get(productId).equals(categoryName))
                .mapToInt(productId -> {
                    // Check inventory service for real-time stock updates and update map
                    int stockLevel = getProductStockLevel(productId);
                    productCategoryMap.put(productId, categoryName);
                    return stockLevel;
                }).sum();
