#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <syslog.h>

// Macro for logging messages
#define LOG(format, ...) syslog(LOG_INFO, "%s: " format, __func__, ## __VA_ARGS__)

// Structure to represent a state in the list of states
typedef struct State {
  int id;
  int num_readings;
} State;

// Function to create and maintain a dynamic list of states from an FSA
void manageStates(int *states, int num_states, FSA fsa, int last_state,
                 int array_size, int timestamp_resolution,
                 int sensor_reading_range) {
  // Create a new state for each state in the given FSA
  State *new_states = malloc(sizeof(State) * num_states);
  for (int i = 0; i < num_states; i++) {
    new_states[i].id = states[i];
    new_states[i].num_readings = 0;
  }

  // Initialize the list of states with the new states created above
  State **state_list = malloc(sizeof(State *) * num_states);
  for (int i = 0; i < num_states; i++) {
    state_list[i] = &new_states[i];
  }

  // Allocate memory for the arrays of readings and timestamps
  int **readings = malloc(sizeof(int *) * array_size);
  long long **timestamps = malloc(sizeof(long long *) * array_size);
  for (int i = 0; i < array_size; i++) {
    readings[i] = malloc(sizeof(int) * num_states);
    timestamps[i] = malloc(sizeof(long long));
  }

  // Initialize the arrays of readings and timestamps with random data
  for (int i = 0; i < array_size; i++) {
    for (int j = 0; j < num_states; j++) {
      int reading = rand() % sensor_reading_range + 1;
      readings[i][j] = reading;
      long long timestamp = rand() % timestamp_resolution + 1;
      timestamps[i][j] = timestamp;
    }
  }

  // Loop through the list of states, updating the number of readings for each state
  for (int i = 0; i < num_states; i++) {
    State *current_state = &state_list[i];
    int reading_index = 0;
    while (reading_index < array_size) {
      // Check if the current state is in the list of states for this index
      bool found_state = false;
      for (int j = 0; j < num_states; j++) {
        if (current_state->id == states[j]) {
          found_state = true;
          break;
        }
      }
      // If the state is not in the list, skip to the next index
      if (!found_state) {
        reading_index++;
        continue;
      }

      // Update the number of readings for the current state
      current_state->num_readings += 1;

      // Get the next index in the array of readings
      int next_reading_index = (reading_index + 1) % array_size;

      // Check if the next index has data for the same state
      bool found_next_state = false;
      for (int j = 0; j < num_states; j++) {
        if (current_state->id == states[j]) {
          found_next_state = true;
          break;
        }
      }
      // If the next index has data for the same state, update the number of readings
      if (found_next_state) {
        current_state->num_readings += 1;
        reading_index = next_reading_index;
      } else {
        reading_index++;
      }
    }
  }

  // Free the memory allocated for the arrays of readings and timestamps
  for (int i = 0; i < array_size; i++) {
    free(readings[i]);
    free(timestamps[i]);
  }
  free(readings);
  free(timestamps);

  // Free the memory allocated for the list of states
  free(state_list);

  LOG("Exiting manageStates function");
}
