public class WebsiteManager
{
    private readonly string _directoryPath;
    private readonly string _siteName;
    private readonly Dictionary<string, Process> _processes = new Dictionary<string, Process>();
    private readonly Cache _cache = new Cache();

    public WebsiteManager(string directoryPath, string siteName)
    {
        _directoryPath = directoryPath;
        _siteName = siteName;
    }

    public void StartSite()
    {
        if (!Directory.Exists(_directoryPath))
            throw new Exception($"Directory '{_directoryPath}' does not exist.");

        if (!File.Exists(Path.Combine(_directoryPath, "web.config")))
            throw new Exception($"No 'web.config' file found in directory '{_directoryPath}'.");

        var process = new Process();
        process.StartInfo.FileName = "iisexpress";
        process.StartInfo.Arguments = $"/path:{_directoryPath} /site:{_siteName}";
        process.StartInfo.UseShellExecute = false;
        process.StartInfo.RedirectStandardOutput = true;
        process.Start();

        _processes[_siteName] = process;
    }

    public void StopSite()
    {
        if (!_processes.ContainsKey(_siteName))
            throw new Exception($"Site '{_siteName}' is not running.");

        var process = _processes[_siteName];
        process.StandardInput.WriteLine("exit");
        process.WaitForExit();
        process.Close();
        _processes.Remove(_siteName);
    }

    public void RefreshSite()
    {
        if (!_processes.ContainsKey(_siteName))
            throw new Exception($"Site '{_siteName}' is not running.");

        var process = _processes[_siteName];
        process.StandardInput.WriteLine("refresh");
    }

    public void RestartSite()
    {
        if (!_processes.ContainsKey(_siteName))
            throw new Exception($"Site '{_siteName}' is not running.");

        var process = _processes[_siteName];
        process.StandardInput.WriteLine("restart");
    }

    public void AddSite(string siteName)
    {
        if (_processes.ContainsKey(siteName))
            throw new Exception($"Site '{siteName}' already exists.");

        var site = GetWebConfiguration().Sites[siteName];
        if (site == null)
            throw new Exception($"Site '{siteName}' does not exist in IIS configuration.");

        var process = new Process();
        process.StartInfo.FileName = "iisexpress";
        process.StartInfo.Arguments = $"/path:{site.Path} /site:{siteName}";
        process.StartInfo.UseShellExecute = false;
        process.StartInfo.RedirectStandardOutput = true;
        process.Start();

        _processes[siteName] = process;
    }

    public void RemoveSite(string siteName)
    {
        if (!_processes.ContainsKey(siteName))
            throw new Exception($"Site '{siteName}' is not running.");

        var process = _processes[siteName];
        process.StandardInput.WriteLine("exit");
        process.WaitForExit();
        process.Close();
        _processes.Remove(siteName);
    }

    private Configuration GetWebConfiguration()
    {
        var configPath = Path.Combine(_directoryPath, "web.config");
        if (!File.Exists(configPath))
            throw new Exception($"No 'web.config' file found in directory '{_directoryPath}'.");

        return ConfigurationManager.OpenExeConfiguration(configPath);
    }

    private class Cache
    {
        private readonly Dictionary<string, Process> _processes = new Dictionary<string, Process>();

        public bool ContainsKey(string key) => _processes.ContainsKey(key);

        public void Add(string key, Process process) => _processes[key] = process;

        public Process GetValue(string key) => _processes[key];

        public void Remove(string key) => _processes.Remove(key);
    }
}
```
