    Record* records = malloc(num_records * sizeof(Record));
    if (records == NULL) {
        printf("Error: unable to allocate memory for record array\n");
        return false;
    }
    // Initialize the 'record' array with random values within a specified range
    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % INT32_MAX;
    }
    // Implement a caching strategy to minimize repeated allocations and deallocations of memory for frequently accessed records
    KeyValuePair* cache = malloc(num_keys * sizeof(KeyValuePair));
    if (cache == NULL) {
        printf("Error: unable to allocate memory for cache\n");
        return false;
