    // Implement synchronization mechanisms to prevent race conditions in a multi-threaded environment
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t condition = PTHREAD_COND_INITIALIZER;
    // Periodically update 'record' values based on the 'offset' and 'key' arrays, respecting predefined limits to avoid overwriting valid data
    while (true) {
