        // Wait for a condition variable to be signaled
        pthread_cond_wait(&condition, &mutex);
        // Release the lock on the mutex
        pthread_mutex_unlock(&mutex);
        // Update 'record' values based on the 'offset' and 'key' arrays
        for (int i = 0; i < num_keys; ++i) {
            if (offsets[i] >= records[i].value) {
                offsets[i] += 1;
                records[i].value = offsets[i];
            } else {
                break;
            }
        }
    }
    // Clean up resources and return success
    free(offsets);
    free(keys);
    free(records);
    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&condition);
    close(socket);
    return true;
}
