using System;
using System.Security.Cryptography;
using System.Threading.Tasks;
using System.Collections.Generic;
using System.IO;

namespace AES_CBC_Decryption
{
    public class DecryptionService
    {
        private readonly ICryptoTransform _decryptor;
        private readonly byte[] _key;
        private readonly bool _reproducible;

        public DecryptionService(byte[] key, bool reproducible = false)
        {
            _key = key;
            _reproducible = reproducible;
            _decryptor = new AesCryptoServiceProvider().CreateDecryptor();
        }

        // 1. Multi-segment decryption with IV and common key
        public async Task<byte[]> DecryptAsync(IEnumerable<byte[]> ciphertextSegments)
        {
            var result = new List<byte>();
            foreach (var segment in ciphertextSegments)
            {
                result.AddRange(_decryptor.TransformFinalBlock(segment, 0, segment.Length));
            }
            return result.ToArray();
        }

        // 2. Generate secure random IV for each encryption operation and allow users to specify a seed value for reproducibility
        public byte[] GenerateIV(int size = 16, int? seed = null)
        {
            var iv = new byte[size];
            if (seed != null)
            {
                using (var rng = new RandomNumberGenerator())
                {
                    rng.Initialize((ulong)seed);
                    rng.GetNonZeroBytes(iv);
                }
            }
            else
            {
                using (var rng = new RNGCryptoServiceProvider())
                {
                    rng.GetNonZeroBytes(iv);
                }
            }
            return iv;
        }

        // 3. Robust padding validation mechanism to ensure data integrity after decryption
        public bool ValidatePadding(byte[] plaintext)
        {
            var blockSize = _decryptor.BlockSize / 8;
            var lastByte = plaintext[plaintext.Length - 1];
            if (lastByte == 0x00 || lastByte > blockSize)
            {
                return false;
            }
            for (int i = plaintext.Length - lastByte; i < plaintext.Length; i++)
            {
                if (plaintext[i] != 0x00)
                {
                    return false;
                }
            }
            return true;
        }

        // 4. Verify an HMAC-SHA256 integrity tag provided alongside the ciphertext
        public bool ValidateHMAC(byte[] ciphertext, byte[] expectedTag)
        {
            using (var hmac = new HMACSHA256(_key))
            {
                var actualTag = hmac.ComputeHash(ciphertext);
                return expectedTag.SequenceEqual(actualTag);
            }
        }

        // 5. Minimize memory usage during decryption, especially for large files
        public async Task<byte[]> DecryptAsync(string filePath)
        {
            var buffer = new byte[1024];
            using (var stream = File.OpenRead(filePath))
            {
                var result = new List<byte>();
                int read;
                while ((read = await stream.ReadAsync(buffer, 0, buffer.Length)) > 0)
                {
                    var decrypted = _decryptor.TransformFinalBlock(buffer, 0, read);
                    result.AddRange(decrypted);
                }
                return result.ToArray();
            }
        }

        // 6. Design the class to decrypt files directly from a specified file path, reading in chunks to manage memory usage effectively
        public async Task<byte[]> DecryptAsync(string filePath)
        {
            var buffer = new byte[1024];
            using (var stream = File.OpenRead(filePath))
            {
                var result = new List<byte>();
                int read;
                while ((read = await stream.ReadAsync(buffer, 0, buffer.Length)) > 0)
                {
                    var decrypted = _decryptor.TransformFinalBlock(buffer, 0, read);
                    result.AddRange(decrypted);
                }
                return result.ToArray();
            }
        }

        // 7. Provide a flexible and secure interface for storing and retrieving the encryption key using a Key Management Service (KMS)
        public void StoreKey(byte[] key, string keyId)
        {
            using (var kms = new KMSClient())
            {
                kms.StoreKey(key, keyId);
            }
        }

        public byte[] RetrieveKey(string keyId)
        {
            using (var kms = new KMSClient())
            {
                return kms.RetrieveKey(keyId);
            }
        }

        // 8. Incorporate logging functionality to record decryption operations and any errors encountered
        public void LogDecryption(byte[] plaintext, string ciphertext)
        {
            var logger = new Logger();
            logger.Log("Decrypted " + ciphertext + " to " + plaintext);
        }
    }
}
