public class NetworkConfigurations {
    private int[] configurations;
    private int numConfigs;
    private int numRecords;

    public void InitializeAndDeserializeNetworkConfigurations(string filePath) {
        // Validate input path
        if (filePath == null || filePath.Length == 0) {
            throw new ArgumentException("Invalid file path", nameof(filePath));
        }

        // Load and decompress network configuration data from the given file path
        byte[] compressedData = File.ReadAllBytes(filePath);
        MemoryStream memoryStream = new MemoryStream(compressedData);
        using (var compressionStream = new GZipStream(memoryStream, CompressionMode.Decompress)) {
            this.numRecords = ReadInt32(compressionStream);
            this.configurations = new int[this.numRecords];
            for (int i = 0; i < this.numRecords; i++) {
                this.configurations[i] = ReadInt32(compressionStream);
            }
        }
    }

    public void DeserializeNetworkConfigurations(string filePath) {
        // Validate input path
        if (filePath == null || filePath.Length == 0) {
            throw new ArgumentException("Invalid file path", nameof(filePath));
        }

        // Load and deserialize network configuration data from the given file path
        byte[] data = File.ReadAllBytes(filePath);
        using (var stream = new MemoryStream(data)) {
            this.numRecords = ReadInt32(stream);
            this.configurations = new int[this.numRecords];
            for (int i = 0; i < this.numRecords; i++) {
                this.configurations[i] = ReadInt32(stream);
            }
        }
    }

    private int ReadInt32(Stream stream) {
        byte[] bytes = new byte[4];
        stream.Read(bytes, 0, 4);
        return BitConverter.ToInt32(bytes, 0);
    }

    public void PrintLargestInteger() {
        int largest = this.configurations[0];
        for (int i = 1; i < this.numRecords; i++) {
            if (this.configurations[i] > largest) {
                largest = this.configurations[i];
            }
        }
        Console.WriteLine($"Largest integer: {largest}");
    }
}
```
