#include <arpa/inet.h>

// Define structs for measurements and events
struct measurement {
    double temperature;
    double humidity;
};

struct event_log {
    time_t timestamp;
    int type_id;
    char *description;
};

// Function to dynamically allocate memory for data structures
void allocate_memory(int num_measurements, int num_events) {
    // Allocate memory for measurements
    struct measurement *measurements = (struct measurement *) malloc(num_measurements * sizeof(struct measurement));
    assert(measurements != NULL);

    // Initialize measurements with random values
    srand(time(NULL));
    for (int i = 0; i < num_measurements; i++) {
        measurements[i].temperature = (double) rand() / RAND_MAX;
        measurements[i].humidity = (double) rand() / RAND_MAX;
    }

    // Allocate memory for events
    struct event_log *events = (struct event_log *) malloc(num_events * sizeof(struct event_log));
    assert(events != NULL);

    // Initialize events with random values
    srand(time(NULL));
    for (int i = 0; i < num_events; i++) {
        events[i].timestamp = time(NULL);
        events[i].type_id = rand() % 10;
        events[i].description = (char *) malloc(sizeof(char) * 256);
        sprintf(events[i].description, "Event type: %d", events[i].type_id);
    }
}

// Function to read data from files and external sources
void read_data(int num_measurements, int num_events) {
    // Open CSV file for reading
    FILE *csv_file = fopen("input.csv", "r");
    assert(csv_file != NULL);

    // Read measurements from CSV file
    for (int i = 0; i < num_measurements; i++) {
        fscanf(csv_file, "%lf,%lf\n", &measurements[i].temperature, &measurements[i].humidity);
    }

    // Close CSV file
    fclose(csv_file);

    // Open JSON configuration file for reading
    FILE *json_file = fopen("config.json", "r");
    assert(json_file != NULL);

    // Read events from JSON file
    int num_events_read = 0;
    while (fscanf(json_file, "%d,%s\n", &events[num_events_read].type_id, events[num_events_read].description) != EOF) {
        num_events_read++;
    }

    // Close JSON file
    fclose(json_file);

    // Open WebSocket connection for real-time updates
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    assert(sock >= 0);

    struct sockaddr_in server;
    server.sin_family = AF_INET;
    server.sin_port = htons(12345);
    inet_pton(AF_INET, "127.0.0.1", &server.sin_addr);

    connect(sock, (struct sockaddr *) &server, sizeof(server));

    // Read events from WebSocket connection
    while (true) {
        char buf[256];
        int len = recv(sock, buf, 256, 0);
        if (len < 0) break;
        events[num_events_read++].timestamp = time(NULL);
        sscanf(buf, "Event type: %d", &events[num_events_read - 1].type_id);
    }

    // Close WebSocket connection
    close(sock);
}

// Function to process and display data in real-time
void process_data() {
    for (int i = 0; i < num_measurements; i++) {
        printf("Measurement %d: Temperature = %.2f, Humidity = %.2f\n", i + 1, measurements[i].temperature, measurements[i].humidity);
    }

    for (int i = 0; i < num_events; i++) {
        printf("Event %d: Timestamp = %s, Type = %d, Description = %s\n", i + 1, ctime(&events[i].timestamp), events[i].type_id, events[i].description);
    }
}

// Function to export data in various formats
void export_data() {
    // Export measurements to CSV file
    FILE *csv_file = fopen("output.csv", "w");
    assert(csv_file != NULL);

    for (int i = 0; i < num_measurements; i++) {
        fprintf(csv_file, "%lf,%lf\n", measurements[i].temperature, measurements[i].humidity);
    }

    // Close CSV file
    fclose(csv_file);

    // Export events to JSON file
    FILE *json_file = fopen("output.json", "w");
    assert(json_file != NULL);

    for (int i = 0; i < num_events; i++) {
        fprintf(json_file, "%d,%s\n", events[i].type_id, events[i].description);
    }

    // Close JSON file
    fclose(json_file);
}

int main() {
    // Read input from files and external sources
    read_data(num_measurements, num_events);

    // Process data in real-time
    process_data();

    // Export data to various formats
    export_data();

    return 0;
}
```
