        return NULL;
    }
    strcpy(new_node->file_path, file_path);

    // Initialize next pointer to NULL
    new_node->next = NULL;

    return new_node;
}

// Function to add a node to the linked list
bool add_node(Node *new_node) {
    pthread_mutex_lock(&lock);

    // Insert new node at the beginning of the linked list
    new_node->next = head;
    head = new_node;

    pthread_mutex_unlock(&lock);
    return true;
}

// Function to remove a node from the linked list by index
bool remove_node(int index) {
    pthread_mutex_lock(&lock);

    // Check if index is valid
    if (index < 0 || index >= get_size()) {
        fprintf(stderr, "Invalid index\n");
        return false;
    }

    // Find the node at the given index
    Node *current = head;
    for (int i = 0; i < index; i++) {
        current = current->next;
    }

    // Remove the node from the linked list
    if (current == head) {
        head = current->next;
    } else {
        Node *previous = head;
        while (previous->next != current) {
            previous = previous->next;
        }
        previous->next = current->next;
    }

    // Free the node's memory
    free(current->file_path);
    free(current);

    pthread_mutex_unlock(&lock);
    return true;
}

// Function to search for a node by file path in the linked list
Node* search_node(char *file_path) {
    pthread_mutex_lock(&lock);

    // Find the first node with the given file path
    Node *current = head;
    while (current != NULL && strcmp(current->file_path, file_path) != 0) {
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
    return current;
}

// Function to get the size of the linked list
int get_size() {
    int count = 0;
    Node *current = head;

    while (current != NULL) {
        count++;
        current = current->next;
    }

    return count;
}

// Function to clean up unused nodes in the linked list
void clean_up() {
    pthread_mutex_lock(&lock);

    // Remove all nodes with NULL file paths
    Node *current = head;
    while (current != NULL && current->file_path == NULL) {
        Node *next = current->next;
        free(current->file_path);
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&lock);
}

// Function to handle errors during file I/O operations
void handle_error() {
    perror("Error occurred");
    exit(EXIT_FAILURE);
}

int main() {
    // Test code for adding nodes and searching by file path
    Node *node1 = create_node(1, "file1.txt");
    add_node(node1);
    Node *node2 = create_node(2, "file2.txt");
    add_node(node2);
    Node *node3 = create_node(3, "file3.txt");
    add_node(node3);

    // Test code for removing nodes by index
    remove_node(0);
    remove_node(1);

    // Test code for searching by file path
    Node *node = search_node("file2.txt");
    if (node != NULL) {
        printf("Node with file path \"file2.txt\" found\n");
    } else {
        printf("Node with file path \"file2.txt\" not found\n");
    }

    // Test code for getting the size of the linked list
    int size = get_size();
    printf("Size of the linked list: %d\n", size);

    // Test code for cleaning up unused nodes
    clean_up();

    return 0;
}']

