/**
 * Gets the MD5 hash of a string. This function should be called for each received data point before adding it to the array.
 */
uint8_t* getMD5Hash(const char* input, size_t length) {
    // Calculate the MD5 hash of the input string
    uint8_t* hash = (uint8_t*)malloc(MD5_HASH_SIZE);
    if (hash != NULL) {
        int result = MD5((const unsigned char*)input, length, hash);
        if (result == 0) {
            // The hash is valid
            return hash;
        } else {
