    addDataPoint(value);

    // Check if it's time to flush the data to disk
    int64_t currentTime = (int64_t)time(NULL) * 1000;
    if (currentTime - lastFlushTime >= FLUSH_INTERVAL) {
        // Flush the data to disk
        flushDataToDisk();
    }
