    uint32_t digest_impl = 0;
    switch (profile->digest) {
        case MD5:
            digest_impl = EVP_md5();
            break;
        case SHA:
            digest_impl = EVP_sha();
            break;
        case SHA256:
            digest_impl = EVP_sha256();
            break;
    }

