    uint32_t mode = 0;
    switch (profile->mode) {
        case GCM:
            mode = EVP_CIPH_GCM_MODE;
            break;
    }

    // Initialize the cipher and digest objects
    EVP_CIPHER_CTX* cipher_ctx = EVP_CIPHER_CTX_new();
    EVP_MD_CTX* digest_ctx = EVP_MD_CTX_create();

    // Set the appropriate parameters for the cipher and digest objects based on the user-defined profile and environmental constraints
    switch (cipher_impl) {
        case AES_128:
            EVP_EncryptInit_ex(cipher_ctx, EVP_aes_128_cbc(), NULL, NULL, NULL);
            break;
        case AES_256:
