            break;
    }

    // Encrypt the input data using the appropriate cipher and digest objects
    uint8_t* encrypted = (uint8_t*)malloc(1024 * 1024);
    size_t output_len = EVP_EncryptUpdate(cipher_ctx, encrypted, 1024 * 1024, input, strlen((char*)input));
    if (mode == EVP_CIPH_GCM_MODE) {
        // If using GCM mode, encrypt the IV and tag in addition to the data
        uint8_t* iv = (uint8_t*)malloc(16);
