        // If using GCM mode, decrypt the IV and tag in addition to the data
        uint8_t* iv = (uint8_t*)malloc(16);
        uint8_t* tag = (uint8_t*)malloc(16);
        EVP_DecryptInit_ex(cipher_ctx, NULL, NULL, NULL, NULL);
        output_len += EVP_DecryptUpdate(cipher_ctx, iv, 16, iv, 16);
        output_len += EVP_DecryptFinal_ex(cipher_ctx, tag, 16);
    }

    // Compute the digest of the decrypted data and verify it against the expected digest
    uint8_t* computed_digest = (uint8_t*)malloc(EVP_MAX_MD_SIZE);
    size_t computed_digest_len = EVP_DigestFinal_ex(digest_ctx, computed_digest, EVP_MAX_MD_SIZE);
    if (computed_digest_len != profile->digest_size) {
        printf("Error: digest size mismatch\n");
        return;
    }
    if (memcmp(computed_digest, profile->expected_digest, computed_digest_len) != 0) {
        printf("Error: digest verification failed\n");
        return;
    }

    // Free the memory allocated for the cipher and digest objects
    EVP_CIPHER_CTX_free(cipher_ctx);
    EVP_MD_CTX_destroy(digest_ctx);
    free(decrypted);
    free(computed_digest);
}
```
This code defines a modular encryption framework in C that supports various cipher algorithms (AES-128, AES-256, ChaCha20, Camellia) and digest functions (MD5, SHA, SHA256). The framework also incorporates GCM mode for authenticated encryption and RSA encryption with PKCS#1 v1.5 padding. The implementation dynamically selects appropriate cipher and digest implementations based on user-defined profiles and environmental constraints, such as hardware capabilities and workload characteristics.

The framework leverages hardware acceleration APIs like Intel's SGX or AMD's ASL where applicable to optimize performance for both CPU-bound and GPU-accelerated tasks. Developers must consider trade-offs between parallel processing overhead and resource consumption, especially when handling large datasets or real-time encryption requirements.

