  char* identifier;
  int status;
  struct Event* next;
} Event;

// Thread-safe function to allocate and initialize memory for events
Event* event_alloc(int num_events) {
  // Allocate memory for the linked list of events
  Event* head = (Event*)malloc(sizeof(Event) * num_events);
  if (!head) {
    // Handle memory allocation failure gracefully
    return NULL;
  }

  // Initialize each event in the linked list with a timestamp, identifier, and status
  for (int i = 0; i < num_events; i++) {
    head[i].timestamp = 0.0f;
    head[i].identifier = NULL;
    head[i].status = 0;
    head[i].next = (i == num_events - 1) ? NULL : &head[i + 1];
  }

  return head;
}

// Thread-safe function to insert a new event into the linked list of events
void event_insert(Event* head, float timestamp, char* identifier, int status) {
  // Allocate memory for the new event and initialize it with the given values
  Event* new_event = (Event*)malloc(sizeof(Event));
  if (!new_event) {
    // Handle memory allocation failure gracefully
    return;
  }
  new_event->timestamp = timestamp;
  new_event->identifier = identifier;
  new_event->status = status;
  new_event->next = NULL;

  // Lock the linked list to prevent race conditions during insertion
  pthread_mutex_lock(&head->mutex);

  // Find the position where the new event should be inserted
  Event* current = head;
  while (current->next != NULL && current->timestamp <= timestamp) {
    current = current->next;
  }

  // Insert the new event into the linked list
  new_event->next = current->next;
  current->next = new_event;

  pthread_mutex_unlock(&head->mutex);
}

// Thread-safe function to delete an event from the linked list of events
void event_delete(Event* head, float timestamp) {
  // Lock the linked list to prevent race conditions during deletion
  pthread_mutex_lock(&head->mutex);

  // Find the position where the event should be deleted
  Event* current = head;
  while (current->next != NULL && current->timestamp < timestamp) {
    current = current->next;
  }

  // Delete the event from the linked list
  if (current->next == NULL) {
    // If the event to be deleted is not found, return immediately
    pthread_mutex_unlock(&head->mutex);
    return;
  }
  Event* next = current->next->next;
  free(current->next);
  current->next = next;

  pthread_mutex_unlock(&head->mutex);
}

// Thread-safe function to update an event in the linked list of events
void event_update(Event* head, float timestamp, char* identifier, int status) {
  // Lock the linked list to prevent race conditions during updates
  pthread_mutex_lock(&head->mutex);

  // Find the position where the event should be updated
  Event* current = head;
  while (current->next != NULL && current->timestamp < timestamp) {
    current = current->next;
  }

  // Update the event in the linked list
  if (current->next == NULL) {
    // If the event to be updated is not found, return immediately
    pthread_mutex_unlock(&head->mutex);
    return;
  }
  current->timestamp = timestamp;
  current->identifier = identifier;
  current->status = status;

  pthread_mutex_unlock(&head->mutex);
}

// Thread-safe function to retrieve an event from the linked list of events
Event* event_retrieve(Event* head, float timestamp) {
  // Lock the linked list to prevent race conditions during retrieval
  pthread_mutex_lock(&head->mutex);

  // Find the position where the event should be retrieved
  Event* current = head;
  while (current->next != NULL && current->timestamp < timestamp) {
    current = current->next;
  }

  // Retrieve the event from the linked list
  if (current->next == NULL) {
    // If the event to be retrieved is not found, return immediately
    pthread_mutex_unlock(&head->mutex);
    return NULL;
  }
  Event* next = current->next;

  pthread_mutex_unlock(&head->mutex);
  return next;
}
