    }

    public async Task ExecuteQueryAsync(string query)
    {
        string url = await GetDatabaseUrlAsync();
        _orm.ExecuteQuery(query, url);
        _logger.LogQuery(url, query);
    }

    public async Task<List<T>> QueryAsync<T>(string query)
    {
        string url = await GetDatabaseUrlAsync();
        List<T> results = _orm.Query<T>(query, url);
        _logger.LogQuery(url, query);
        return results;
    }

    public async Task UpdateAsync(string query)
    {
        string url = await GetDatabaseUrlAsync();
        _orm.Update(query, url);
        _logger.LogQuery(url, query);
