    free(themeBitmap);
    themeBitmap = NULL;
  }

  // Verify if a default theme directory is set
  const char *defaultThemeDir = "themes/";
  if (defaultThemeDir == NULL) {
    defaultThemeDir = "themes/default/";
  }

  // Parse a PNG file from the cache root directory and store it in the theme cache
  FILE *file = fopen("cache/theme.png", "rb");
  if (file != NULL) {
    struct stat st;
    if (fstat(fileno(file), &st) == 0 && S_ISREG(st.st_mode)) {
      themeBitmap = malloc(st.st_size);
      if (themeBitmap == NULL) {
        fclose(file);
        return;
      }
      int bytesRead = fread(themeBitmap, 1, st.st_size, file);
      if (bytesRead != st.st_size) {
