// Record structure
typedef struct {
    int key;
    long offset;
} record_t;

// Sorting algorithm types
enum sorting_algorithms {QUICKSORT, MERGESORT, HEAPSORT};

// Configuration parameters
static const int MAX_OFFSET = 1000;
static const int MIN_KEY = -1000;
static const int MAX_KEY = 1000;
static const int SORT_ENABLED = 1;
static const int SORT_DISABLED = 0;

// Function prototype
void allocateAndInitializeRecords(int numOffsets, int numKeys, record_t* records, enum sorting_algorithms algorithm);

// Logging mechanism
static FILE* logFile = NULL;
static pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;
void log(const char* message) {
    if (logFile != NULL) {
        pthread_mutex_lock(&logMutex);
        fprintf(logFile, "%s\n", message);
        fflush(logFile);
        pthread_mutex_unlock(&logMutex);
    }
}

// Function to dynamically select the sorting algorithm based on runtime conditions
void allocateAndInitializeRecords(int numOffsets, int numKeys, record_t* records, enum sorting_algorithms algorithm) {
    // Check for valid input parameters
    if (numOffsets <= 0 || numKeys <= 0 || records == NULL || algorithm < QUICKSORT || algorithm > HEAPSORT) {
        log("Invalid input parameters");
        return;
    }

    // Allocate memory for the arrays
    long* offsets = malloc(numOffsets * sizeof(long));
    int* keys = malloc(numKeys * sizeof(int));
    record_t* records = malloc(numRecords * sizeof(record_t));

    if (offsets == NULL || keys == NULL || records == NULL) {
        log("Memory allocation failed");
        return;
    }

    // Initialize the arrays
    for (int i = 0; i < numOffsets; i++) {
        offsets[i] = rand() % MAX_OFFSET + MIN_OFFSET;
    }

    for (int i = 0; i < numKeys; i++) {
        keys[i] = rand() % MAX_KEY + MIN_KEY;
    }

    for (int i = 0; i < numRecords; i++) {
        records[i].key = keys[i];
        records[i].offset = offsets[i];
    }

    // Sort the records if specified
    if (SORT_ENABLED) {
        switch(algorithm) {
            case QUICKSORT:
                quicksort(records, 0, numRecords - 1);
                break;
            case MERGESORT:
                mergesort(records, 0, numRecords - 1);
                break;
            case HEAPSORT:
                heapsort(records, 0, numRecords - 1);
                break;
        }
    }
}
```
