#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <stdbool.h>

struct Record {
    int value;
};

struct Arrays {
    long *offset_array;
    int *key_array;
    struct Record *record_array;
    size_t capacity;
    size_t size;
};

bool allocate_arrays(struct Arrays *arrays, size_t capacity) {
    arrays->offset_array = malloc(capacity * sizeof(long));
    if (arrays->offset_array == NULL) {
        fprintf(stderr, "Failed to allocate offset array\n");
        return false;
    }

    arrays->key_array = malloc(capacity * sizeof(int));
    if (arrays->key_array == NULL) {
        free(arrays->offset_array);
        fprintf(stderr, "Failed to allocate key array\n");
        return false;
    }

    arrays->record_array = malloc(capacity * sizeof(struct Record));
    if (arrays->record_array == NULL) {
        free(arrays->offset_array);
        free(arrays->key_array);
        fprintf(stderr, "Failed to allocate record array\n");
        return false;
    }

    arrays->capacity = capacity;
    arrays->size = 0;
    return true;
}

void deallocate_arrays(struct Arrays *arrays) {
    free(arrays->offset_array);
    free(arrays->key_array);
    free(arrays->record_array);
}

bool init_arrays(struct Arrays *arrays, size_t capacity) {
    if (!allocate_arrays(arrays, capacity)) {
        return false;
    }

    for (size_t i = 0; i < arrays->capacity; i++) {
        arrays->offset_array[i] = rand();
        arrays->key_array[i] = i;
        arrays->record_array[i].value = rand() % 100;
    }

    return true;
}

void free_arrays(struct Arrays *arrays) {
    deallocate_arrays(arrays);
    arrays->capacity = 0;
    arrays->size = 0;
}

bool fetch_new_data(struct Arrays *arrays, size_t capacity, int min_value, int max_value) {
    for (size_t i = 0; i < capacity; i++) {
        struct Record *record = &arrays->record_array[i];
        record->value = rand() % (max_value - min_value + 1) + min_value;
    }

    return true;
}

void print_arrays(struct Arrays *arrays, size_t capacity) {
    for (size_t i = 0; i < capacity; i++) {
        printf("offset: %ld\n", arrays->offset_array[i]);
        printf("key: %d\n", arrays->key_array[i]);
        printf("value: %d\n", arrays->record_array[i].value);
    }
}

int main() {
    struct Arrays arrays;
    size_t capacity = 100;
    if (!init_arrays(&arrays, capacity)) {
        fprintf(stderr, "Failed to initialize arrays\n");
        return EXIT_FAILURE;
    }

    // Fetch new data from an external API and update the key-value pairs.
    fetch_new_data(&arrays, capacity, 0, 100);

    print_arrays(&arrays, capacity);

    free_arrays(&arrays);

    return EXIT_SUCCESS;
}']

