        }
    }
    return num_hosts;
}

// Function to handle DNS resolution and integrate the IP addresses into the records
int resolve_dns(Record **records, int num_hosts) {
    // Perform DNS resolution for each hostname in the list
    for (int i = 0; i < num_hosts; i++) {
        if ((*records)[i].ip_addr == 0) {
            struct addrinfo *res = NULL;
            int rc = getaddrinfo((*hostnames)[i], NULL, NULL, &res);
            if (rc != 0) {
                fprintf(stderr, "Failed to resolve DNS for hostname '%s': %s\n", (*hostnames)[i], gai_strerror(rc));
                return -1;
            }
            // Extract the IP address from the resolved address information
            struct sockaddr_in *sa = (struct sockaddr_in *)res->ai_addr;
            (*records)[i].ip_addr = ntohl(sa->sin_addr.s_addr);
        }
    }
    return num_hosts;
}

// Function to find and print the largest integer in the array of records if they are IP addresses, or the longest string if they are hostnames
int find_largest(Record *records, int num_hosts) {
    // Initialize variables to keep track of the largest value and its corresponding index
    int largest = INT_MIN;
    int largest_index = -1;
    for (int i = 0; i < num_hosts; i++) {
        if (records[i].ip_addr > largest) {
            largest = records[i].ip_addr;
            largest_index = i;
        }
    }
    // Print the largest value and its corresponding hostname, or the longest string if they are IP addresses
    if (largest_index >= 0) {
        printf("Largest integer: %d\n", records[largest_index].ip_addr);
        printf("Hostname: %s\n", records[largest_index].hostname);
    } else {
        printf("Longest string: %s\n", records[largest_index].hostname);
    }
}

