        return -1;
    }
    rc = init_records(&records, num_hosts);
    if (rc < 0) {
        fprintf(stderr, "Failed to initialize records\n");
        return -1;
    }
    rc = resolve_dns(records, num_hosts);
    if (rc < 0) {
        fprintf(stderr, "Failed to resolve DNS for hostnames\n");
        return -1;
    }
    find_largest(records, num_hosts);
}
