    if (pthread_mutex_init(mutex_lock, NULL) != 0) {
        fprintf(stderr, "Error: failed to initialize mutex lock\n");
        return NULL;
    }

    // Create a context manager for proper memory deallocation upon function exit
    bool *context = allocate_memory(sizeof(bool));
    *context = true;
    pthread_cleanup_push((void *)free, (void *)hash_table);
    pthread_cleanup_push((void *)free, (void *)mutex_lock);
    pthread_cleanup_push((void *)free, (void *)context);

    // Check input parameters for size, range, and file paths
    if (file_offset_count < 1 || key_count < 1) {
        fprintf(stderr, "Error: invalid input parameters\n");
        pthread_exit(NULL);
    }

    // Open the file for reading
