        pthread_exit(NULL);
    }
    if (read(file, keys, sizeof(int) * key_count) == -1) {
        fprintf(stderr, "Error: failed to read file keys\n");
        pthread_exit(NULL);
    }

    // Close the file and release resources
    close(file);

    // Manage memory allocation and data handling for the multi-tiered storage system
    while (*context) {
        // Use mutex lock to protect critical sections
        pthread_mutex_lock(mutex_lock);

        // Update the hash table with new data from the streaming service
        // ...

        // Generate random numbers for the custom record structures
        // ...

        // Store the random numbers in the hash table
        // ...

        // Release mutex lock
        pthread_mutex_unlock(mutex_lock);
    }

    // Deallocate memory and return NULL
    free(offsets);
    free(keys);
    free(hash_table);
    pthread_cleanup_pop(1);
    pthread_cleanup_pop(1);
    pthread_cleanup_pop(1);
    return NULL;
}

