        } else if (strcmp(buffer, "POST") == 0) {
            // Create a new record in the hash table and update the external database system
            // ...

            // Send a confirmation message to the client socket
            send(client_sock, response, strlen(response), 0);
        } else {
            // Return an error message if the request method is not recognized
            char *error_message = "Error: invalid request method\n";
            send(client_sock, error_message, strlen(error_message), 0);
        }

        // Close the client socket and release resources
        close(client_sock);
    }
}
