            lzread(file, buf, size);
            free(buf);
        }
    } else if (compression_level == 4) {
        // Compress with ZLIB
        struct zlibfile* file = (struct zlibfile*)malloc(sizeof(struct zlibfile));
        zopen(&file, data->value, "rb");
        while (!zisend(file)) {
            int size = 1024;
            char* buf = (char*)malloc(size);
