// Define the resolve_dns_record function
int resolve_dns_record(char *hostname, struct in_addr *ip_address) {
    // Declare variables for DNS resolution parameters
    struct addrinfo hints;
    struct addrinfo *result;
    int status;

    // Initialize the addrinfo structure
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET; // IPv4 only
    hints.ai_socktype = SOCK_STREAM;

    // Perform DNS resolution
    status = getaddrinfo(hostname, NULL, &hints, &result);
    if (status != 0) {
        return status;
    }

    // Use the first IP address returned by DNS resolution
    struct in_addr *ip = &((struct sockaddr_in *)(result->ai_addr))->sin_addr;
    memcpy(ip_address, ip, sizeof(struct in_addr));

    freeaddrinfo(result);

    return 0;
}

