        return (min + static_cast<double>(rand()) / RAND_MAX * (max - min));
    }

    char *getRandomString(int length) {
        char *str = (char *)malloc(length + 1);
        for (int i = 0; i < length; i++) {
            str[i] = 'a' + rand() % ('z' - 'a');
