void *malloc_safe(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_safe(void *ptr) {
    if (ptr != NULL) {
        free(ptr);
    }
}

// Array Management Functions
struct operation **createOperationsArray(int size) {
    struct operation **arr = (struct operation **)malloc_safe(size * sizeof(struct operation));
    for (int i = 0; i < size; i++) {
        arr[i] = (struct operation *)malloc_safe(sizeof(struct operation));
    }
    return arr;
}

void destroyOperationsArray(struct operation **arr, int size) {
    for (int i = 0; i < size; i++) {
        free_safe(arr[i]);
    }
    free_safe(arr);
}

