        fp = fopen("log.txt", "w");
        if (fp == NULL) {
            perror("fopen");
            exit(EXIT_FAILURE);
        }
    }

    ~Logger() {
        fclose(fp);
    }

    void log(const char *message) {
        fprintf(fp, "%s\n", message);
    }
};

// Main Function
int main(int argc, char **argv) {
    // Initialize configuration manager and logging mechanism
    ConfigManager config;
    Logger logger;

    // Get input size from command line arguments
