    for (int i = 0; i < size; i++) {
        arr[i]->d = config.getRandomDouble(config.min, config.max);
        arr[i]->s = config.getRandomString(rand() % 20);
        arr[i]->e = config.getRandomElement(rand() % 100);
    }

    // Periodically check and optimize memory usage
    // ...

    // Clean up resources
    destroyOperationsArray(arr, size);

    return 0;
}
