// Function to dynamically allocate memory for and initialize multiple polygons
Geometry* create_polygons(int num_polygons, int max_vertices) {
    // Allocate memory for an array of geometries
    Geometry* geometries = (Geometry*)malloc(num_polygons * sizeof(Geometry));
    if (geometries == NULL) {
        return NULL;
    }

    // Initialize each geometry with an array of vertices and a zero area
    for (int i = 0; i < num_polygons; ++i) {
        geometries[i].vertices = (Vertex*)malloc(max_vertices * sizeof(Vertex));
        geometries[i].area = 0.0;
    }

    // Calculate the total area of each polygon and store it in its geometry structure
    for (int i = 0; i < num_polygons; ++i) {
        double area = calculate_area(geometries[i].vertices, max_vertices);
        geometries[i].area = area;
    }

    return geometries;
}

// Function to calculate the total area of a polygon
double calculate_area(Vertex* vertices, int num_vertices) {
    // Calculate the total area of the polygon using the shoelace formula
    double area = 0.5 * fabs(determinant(vertices, num_vertices));
    return area;
}

// Function to calculate the determinant of a matrix formed by two vectors
double determinant(Vertex* v1, int n) {
    // Calculate the determinant of the matrix formed by v1 and v2
    double det = 0.0;
    for (int i = 0; i < n; ++i) {
        Vertex v2 = v1[i];
        double term = v1->x * v2.y - v2.x * v1->y;
        det += term;
    }
    return det;
}
