        records[i].cost = (float)rand() / RAND_MAX;
    }

    // Allocate memory for the Metadata array
    Metadata *metadata = (Metadata *)malloc(num_metadata * sizeof(Metadata));
    if (metadata == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for metadata\n");
        exit(EXIT_FAILURE);
