// C source file: array_of_records.c
#include "array_of_records.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <assert.h>
#include <time.h>
#include <math.h>

void init_array(record **arr, size_t capacity) {
    assert(capacity > 0);
    *arr = (record *)malloc(sizeof(record) * capacity);
    if (*arr == NULL) {
        fprintf(stderr, "Failed to allocate memory for array\n");
        exit(EXIT_FAILURE);
    }
}

void destroy_array(record **arr) {
    free(*arr);
    *arr = NULL;
}

void print_largest_integer(const record *arr, size_t n) {
    int largest = arr[0].value;
    for (size_t i = 1; i < n; i++) {
        if (arr[i].value > largest) {
            largest = arr[i].value;
        }
    }
    printf("Largest integer in the array is: %d\n", largest);
}

bool filter_records(const record *arr, size_t n, int threshold) {
    bool any_matched = false;
    for (size_t i = 0; i < n; i++) {
        if (arr[i].value >= threshold) {
            any_matched = true;
            break;
        }
    }
    return any_matched;
}

void set_random_values(record *arr, size_t n, int min, int max) {
    srand(time(NULL));
    for (size_t i = 0; i < n; i++) {
        arr[i].value = rand() % (max - min + 1) + min;
    }
}

// Example usage:
int main() {
    record *arr = NULL;
    size_t capacity = 5;
    init_array(&arr, capacity);

    // Set random values within a specified range for each record
    int min = 0;
    int max = 10;
    set_random_values(arr, capacity, min, max);

    // Print the largest integer in the array
    print_largest_integer(arr, capacity);

    // Filter records that meet or exceed a specified threshold value
    int threshold = 5;
    bool any_matched = filter_records(arr, capacity, threshold);
    printf("Any record matched the threshold: %d\n", any_matched ? "true" : "false");

    // Clean up resources
    destroy_array(&arr);
    return 0;
}
