    // Initialize each station's record using the specified initialization method
    for (i = 0; i < numStations; i++) {
        switch (initMethods[i]) {
            case RANDOM_INT:
                stations[i].data.temperature = (float)(rand() % 100);
                stations[i].data.humidity = (float)(rand() % 100);
                break;
            case RANDOM_FLOAT:
                stations[i].data.temperature = (float)rand() / (float)RAND_MAX;
                stations[i].data.humidity = (float)rand() / (float)RAND_MAX;
                break;
            case STRING:
                stations[i].data.descriptor = strdup(descriptors[i]);
                break;
            case EXTERNAL_WEATHER_SERVICE:
                // Make an asynchronous API call to retrieve current temperature and humidity values for the station
                // Handle potential rate limits and network latency gracefully
                stations[i].data.temperature = -1;
                stations[i].data.humidity = -1;
                break;
            default:
                printf("Error: Invalid initialization method specified.\n");
                return;
        }
    }
}

// Clean up memory allocation for all stations
void envMonitorCleanup(int numStations) {
    int i;
    for (i = 0; i < numStations; i++) {
        free(stations[i].data.descriptor);
    }
    free(stations);
}
