import json
from collections import defaultdict
from concurrent.futures import ThreadPoolExecutor

class ServiceRegistry:
    def __init__(self):
        self.services = defaultdict(lambda: defaultdict())

    def add_service(self, name, config):
        self.services[name] = config

    def remove_service(self, name):
        del self.services[name]

    def get_service(self, name):
        return self.services[name]

class ConfigManager:
    def __init__(self):
        self.configs = {}

    def add_config(self, config):
        self.configs[config["id"]] = config

    def remove_config(self, id):
        del self.configs[id]

    def get_config(self, id):
        return self.configs[id]

def generate_unique_id():
    # Generate a unique ID for each configuration
    return "".join(random.choice("abcdefghijklmnopqrstuvwxyz") for _ in range(6))

def process_configs(configs, num_configs, randomize=False):
    config_ids = []
    config_dict = {}
    for i in range(num_configs):
        # Generate a unique ID for each configuration
        id = generate_unique_id()
        config_ids.append(id)
        # Set the configuration parameters to random values or fixed defaults
        if randomize:
            config_dict[id] = {
                "param1": random.randint(0, 10),
                "param2": random.choice(["option1", "option2"]),
                "param3": random.randint(0, 10)
            }
        else:
            config_dict[id] = {
                "param1": 5,
                "param2": "option1",
                "param3": 8
            }
    # Apply filtering criteria based on key-value pairs
    filtered_configs = []
    for id in config_ids:
        if config_dict[id]["param1"] > 5 and config_dict[id]["param2"] == "option1":
            filtered_configs.append(id)
    return filtered_configs

def handle_config_requests(service_registry, config_manager):
    # Handle HTTP requests for service configurations
    if request.method == 'GET':
        # Get all service configurations
        service_list = []
        for service in service_registry.services:
            service_list.append(service)
        return jsonify({"services": service_list})
    elif request.method == 'POST':
        # Add a new service configuration
        service_name = request.json["service"]
        config_dict = request.json["config"]
        service_registry.add_service(service_name, config_dict)
        return jsonify({"message": f"Service {service_name} added successfully."})
    elif request.method == 'PUT':
        # Update an existing service configuration
        service_name = request.json["service"]
        config_id = request.json["configId"]
        config_dict = request.json["config"]
        config_manager.update_config(config_id, config_dict)
        return jsonify({"message": f"Service {service_name} updated successfully."})
    elif request.method == 'DELETE':
        # Delete a service configuration
        service_name = request.json["service"]
        config_id = request.json["configId"]
        service_registry.remove_service(service_name)
        return jsonify({"message": f"Service {service_name} deleted successfully."})

if __name__ == '__main__':
    # Initialize the service registry and config manager
    service_registry = ServiceRegistry()
    config_manager = ConfigManager()

    # Add some initial configurations to the registry
    service_registry.add_service("service1", {"param1": 5, "param2": "option1", "param3": 8})
    service_registry.add_service("service2", {"param1": 7, "param2": "option2", "param3": 9})

    # Set up a thread pool for concurrent requests
    with ThreadPoolExecutor() as executor:
        while True:
            request = input("Enter a HTTP request (GET/POST/PUT/DELETE): ")
            if request.lower() == "quit":
                break
            elif request.lower() == "get":
                # Get all service configurations
                service_list = []
                for service in service_registry.services:
                    service_list.append(service)
                print(jsonify({"services": service_list}))
            else:
                # Handle other HTTP requests
                executor.submit(handle_config_requests, service_registry, config_manager, request)
