  // Initialize each record with random values or strings
  size_t i;
  for (i = 0; i < nrecords; ++i) {
    if (init_type == RANDOM_INT) {
      generate_random(&(*records)[i], min, max);
    } else if (init_type == RANDOM_STR) {
      size_t length = strlen(rand_str(10));
      char* data = malloc(length + 1);
      memset(data, '\0', length + 1);
      (*records)[i].data = data;
      (*records)[i].size = length;
      (*records)[i].type = STRING;
    } else {
      // Invalid init type specified
      printf("Error: Invalid initialization type specified\n");
      exit(1);
    }
  }
}

// Define function to generate random values within a range
void generate_random(record_t* record, int min, int max) {
  if (min > max || min == INT_MAX || max == INT_MIN) {
    // Invalid range specified
    printf("Error: Invalid range of integers specified\n");
    exit(1);
  }

  // Generate random integer within specified range
  record->data = malloc(sizeof(int));
  if (record->data == NULL) {
    printf("Error: Failed to allocate memory for integer value\n");
    exit(1);
  }
  *((int*)record->data) = rand() % (max - min + 1) + min;
}

// Define function to filter records based on user-defined criteria
int filter_records(record_t* records, size_t nrecords, int criterion) {
  // Check if criterion is valid
  if (criterion != GREATER_THAN && criterion != LONGER_THAN) {
    printf("Error: Invalid filtering criterion specified\n");
    return 1;
  }

  // Filter records based on criteria
  size_t i;
  for (i = 0; i < nrecords; ++i) {
    if (criterion == GREATER_THAN && ((int*)records[i].data) > min) {
      // Move record to filtered list
      records[i] = records[nrecords - 1];
      --nrecords;
    } else if (criterion == LONGER_THAN && strlen((char*)records[i].data) > min) {
      // Move record to filtered list
      records[i] = records[nrecords - 1];
      --nrecords;
    }
  }

  return nrecords;
}

// Define function to find largest integer or longest string among filtered records
size_t find_largest(record_t* records, size_t nrecords) {
  // Check if there are any filtered records
  if (nrecords == 0) {
    return -1;
  }

  // Find largest integer or longest string among filtered records
  int i = 0;
  while (i < nrecords - 1) {
    if (criterion == GREATER_THAN && ((int*)records[i].data) > min) {
      // Move record to largest list
      records[i] = records[nrecords - 1];
      --nrecords;
    } else if (criterion == LONGER_THAN && strlen((char*)records[i].data) > min) {
      // Move record to longest string list
      records[i] = records[nrecords - 1];
      --nrecords;
    } else {
      ++i;
    }
  }

  return nrecords;
}

// Define function to run external script on filtered records
int run_script(const char* script_path, const char* input_file, const char* output_file) {
  // Check if script path is valid
  if (script_path == NULL) {
    printf("Error: Invalid script path specified\n");
    return 1;
  }

  // Run external script on filtered records
  FILE* fp = popen(script_path, "w");
  if (fp == NULL) {
    printf("Error: Failed to run external script\n");
    return 1;
  }

  // Write input file contents to standard input of script
  char buffer[BUFSIZ];
  size_t i = 0;
  while (fgets(buffer, BUFSIZ, fp)) {
    if (i < nrecords) {
      fputs(buffer, stdout);
    } else {
      // Output buffer is larger than number of filtered records
      printf("Error: Output buffer size exceeded\n");
      return 1;
    }
  }

  // Read output file contents from standard output of script
  FILE* fp2 = popen(output_file, "r");
  if (fp2 == NULL) {
    printf("Error: Failed to read external script output\n");
    return 1;
  }

  // Process output file contents
  char buffer[BUFSIZ];
  size_t i = 0;
  while (fgets(buffer, BUFSIZ, fp2)) {
    if (i < nrecords) {
      fputs(buffer, stdout);
    } else {
      // Output buffer is larger than number of filtered records
      printf("Error: Output buffer size exceeded\n");
      return 1;
    }
  }

  // Clean up
  pclose(fp2);
  pclose(fp);
}

