      }
    } else { // Character pointer
      if (strlen(records[i].c) == 0) {
        free(records[i].c);
        records[i].c = NULL;
      }
    }
  }

  // Synchronize access to the array of records using a mutex
  pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
  pthread_mutex_lock(&lock);
  for (unsigned long i = 0; i < num_records; ++i) {
    if (records[i].type == -1) { // Invalid record
      continue;
    } else if (records[i].type == 0) { // Integer value
      printf("Record %lu: %d\n", i, records[i].i);
    } else { // Character pointer
      printf("Record %lu: %s\n", i, records[i].c);
    }
  }
  pthread_mutex_unlock(&lock);
}

// Main function to process the dataset
int main(int argc, char *argv[]) {
  // Declare and initialize variables for input validation
  const char *file = NULL;
  const char *network = NULL;
  const char *feed = NULL;
  unsigned long num_records = 0;

  // Validate input arguments and set default values
  if (argc < 3) {
    fprintf(stderr, "Usage: %s file network feed [num_records]\n", argv[0]);
    return 1;
  }
  file = argv[1];
  network = argv[2];
  feed = argv[3];
  if (argc > 4) {
    num_records = atol(argv[4]);
  } else {
    num_records = 100; // Default value for number of records
  }

  // Process the dataset using a separate thread to handle input streams
  pthread_t thread;
  if (pthread_create(&thread, NULL, process_dataset, argv[1])) {
    fprintf(stderr, "Error: Failed to create thread for processing dataset.\n");
    return 1;
  }
  process_dataset(file, network, feed, num_records);
  pthread_join(thread, NULL);

  // Clean up and exit
  free(records);
  return 0;
}
