// Function to dynamically allocate memory for an array of transactions
transaction** read_transactions(const char* filepath, size_t* num_transactions) {
    // Open the CSV file and retrieve its size
    FILE* fp = fopen(filepath, "r");
    if (!fp) {
        perror("Failed to open file");
        return NULL;
    }
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    rewind(fp);

    // Allocate memory for the array of transactions and read the data from the file
    transaction** transactions = (transaction**)malloc(sizeof(transaction*) * file_size / 256);
    size_t i = 0;
    while (!feof(fp)) {
        // Allocate memory for the current transaction
        transaction* curr_trans = (transaction*)malloc(sizeof(transaction));

        // Read the description and validate it
        fgets(curr_trans->description, 256, fp);
        if (!strchr(curr_trans->description, '\n')) {
            perror("Description exceeds maximum length");
            continue;
        }

        // Read the amount and validate it
        curr_trans->amount = strtod(fgets(NULL, 256, fp), NULL);
        if (curr_trans->amount == HUGE_VAL || curr_trans->amount == -HUGE_VAL) {
            perror("Invalid amount");
            continue;
        }

        // Read the timestamp and validate it
        strptime(fgets(NULL, 256, fp), "%d/%m/%Y %H:%M", &curr_trans->timestamp);
        if (curr_trans->timestamp < 0 || curr_trans->timestamp > time(NULL)) {
            perror("Invalid timestamp");
            continue;
        }

        transactions[i++] = curr_trans;
    }
    fclose(fp);

    // Return the array of transactions and the number of transactions read from the file
    *num_transactions = i;
    return transactions;
}

int main() {
    size_t num_transactions = 0;
    transaction** transactions = read_transactions("transactions.csv", &num_transactions);
    if (!transactions) {
        perror("Failed to read transactions");
        return 1;
    }

    // Print the contents of the transactions array
    for (size_t i = 0; i < num_transactions; ++i) {
        printf("%s, %f, %s\n", transactions[i]->description, transactions[i]->amount, ctime(&transactions[i]->timestamp));
    }

    // Deallocate memory for the array of transactions and return success
    free(transactions);
    return 0;
}
