#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

// Define structure for task information
struct task {
    int priority;
    time_t deadline;
    enum status {PENDING, OVERDUE, COMPLETED};
};

// Define locking strategy
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define custom memory pool for frequent allocations and deallocations of task structures
struct mempool {
    struct task *tasks;
    size_t capacity;
};

void init_mempool(struct mempool *pool) {
    pool->tasks = NULL;
    pool->capacity = 0;
}

void destroy_mempool(struct mempool *pool) {
    free(pool->tasks);
    pool->tasks = NULL;
    pool->capacity = 0;
}

void add_task(struct task **tasks, size_t *capacity, struct task new_task) {
    pthread_mutex_lock(&mutex);
    // Check if capacity is exceeded
    if (*capacity == SIZE_MAX || *capacity >= 10000) {
        // Reallocate memory if necessary
        size_t new_capacity = *capacity > 0 ? 2 * *capacity : 1;
        struct task *new_tasks = realloc(*tasks, new_capacity * sizeof(struct task));
        if (new_tasks == NULL) {
            // Handle error
            pthread_mutex_unlock(&mutex);
            return;
        }
        *tasks = new_tasks;
        *capacity = new_capacity;
    }
    // Add task to list
    (*tasks)[*capacity] = new_task;
    *capacity += 1;
    pthread_mutex_unlock(&mutex);
}

void remove_task(struct task **tasks, size_t *capacity, struct task *to_remove) {
    pthread_mutex_lock(&mutex);
    // Find index of task to be removed
    size_t index = 0;
    while (index < *capacity && &(*tasks)[index] != to_remove) {
        index++;
    }
    // Check if task was found
    if (index == *capacity) {
        pthread_mutex_unlock(&mutex);
        return;
    }
    // Shift remaining tasks down
    for (size_t i = index + 1; i < *capacity; i++) {
        (*tasks)[i - 1] = (*tasks)[i];
    }
    // Decrement capacity
    *capacity -= 1;
    pthread_mutex_unlock(&mutex);
}

void update_task(struct task **tasks, size_t *capacity, struct task *to_update) {
    pthread_mutex_lock(&mutex);
    // Find index of task to be updated
    size_t index = 0;
    while (index < *capacity && &(*tasks)[index] != to_update) {
        index++;
    }
    // Check if task was found
    if (index == *capacity) {
        pthread_mutex_unlock(&mutex);
        return;
    }
    // Update task
    (*tasks)[index] = to_update;
    pthread_mutex_unlock(&mutex);
}

void validate_deadline(struct task *task) {
    // Check if deadline has passed
    time_t current_time = time(NULL);
    if (current_time >= task->deadline) {
        task->status = OVERDUE;
    } else {
        task->status = PENDING;
    }
}

void update_tasks(struct task **tasks, size_t *capacity) {
    pthread_mutex_lock(&mutex);
    // Iterate over list and update each task's status based on its deadline
    for (size_t i = 0; i < *capacity; i++) {
        validate_deadline(&(*tasks)[i]);
    }
    pthread_mutex_unlock(&mutex);
}

void get_statistics(struct task **tasks, size_t *capacity, struct statistics *stats) {
    pthread_mutex_lock(&mutex);
    // Calculate number of tasks overdue, pending, and completed
    for (size_t i = 0; i < *capacity; i++) {
        switch ((*tasks)[i].status) {
            case OVERDUE:
                stats->overdue += 1;
                break;
            case PENDING:
                stats->pending += 1;
                break;
            case COMPLETED:
                stats->completed += 1;
                break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void realtime_notification(struct task **tasks, size_t *capacity) {
    pthread_mutex_lock(&mutex);
    // Iterate over list and notify users when a task's deadline is within one day of expiring
    for (size_t i = 0; i < *capacity; i++) {
        if ((*tasks)[i].deadline - time(NULL) <= 86400) { // One day in seconds
            // Notify user using callback mechanism
        }
    }
    pthread_mutex_unlock(&mutex);
}

void task_management_system(struct task **tasks, size_t *capacity) {
    while (1) {
        update_tasks(tasks, capacity);
        get_statistics(tasks, capacity, &stats);
        realtime_notification(tasks, capacity);
        // Sleep for a short period of time to prevent high CPU usage
        sleep(1);
    }
}
