    transaction_t* transactions_ptr = malloc(total_size);
    if (transactions_ptr == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for transactions\n");
        return;
    }

    // Initialize the structures in a contiguous block
    for (size_t i = 0; i < num_transactions; ++i) {
        transaction_t* current_transaction = transactions_ptr + i;
        current_transaction->string = NULL;
        current_transaction->num_amounts = 0;
        current_transaction->amounts = NULL;
        current_transaction->key = 0;
    }

    // Log the allocation of memory for each transaction
    if (log) {
        fprintf(stdout, "Logging memory allocation for transactions:\n");
        for (size_t i = 0; i < num_transactions; ++i) {
            transaction_t* current_transaction = transactions_ptr + i;
            size_t str_len = strlen(current_transaction->string);
            fprintf(stdout, "    Transaction %zu: string (%zu bytes), amounts array (%zu floats), key (%d)\n",
                    i, str_len, current_transaction->num_amounts, current_transaction->key);
        }
    }
}

// Define a function to free memory for multiple arrays and structures
void free_memory(transaction_t** transactions, size_t num_transactions) {
    // Free the strings in each transaction
    for (size_t i = 0; i < num_transactions; ++i) {
