    // Free the keys arrays in each transaction
    for (size_t i = 0; i < num_transactions; ++i) {
        transaction_t* current_transaction = transactions[i];
        free(current_transaction->key);
    }

    // Free the structures in a contiguous block
    size_t total_size = sizeof(transaction_t) * num_transactions;
    free(transactions);
}
