            return;
        }
        records = temp_records;

        // Reallocate memory for the offsets array with the new size
        void* temp_offsets = realloc(offsets, sizeof(int) * num_unique_keys);
        if (temp_offsets == NULL) {
            LOG_ERROR("Failed to reallocate memory for offsets");
            return;
        }
        offsets = temp_offsets;

        // Reallocate memory for the keys array with the new size
        void* temp_keys = realloc(keys, sizeof(int) * num_unique_keys);
        if (temp_keys == NULL) {
            LOG_ERROR("Failed to reallocate memory for keys");
            return;
        }
        keys = temp_keys;
    }

    // Update the offsets array with the new size
    int new_size = num_unique_keys * sizeof(int);
    memset(offsets, 0, new_size);

    // Update the keys array with the unique keys from the data
    for (int i = 0; i < initial_records; i++) {
        int key = ((int*)data)[i];
        if (key == 0) {
            continue;
        }
        int index = get_index(keys, num_unique_keys, key);
        offsets[index]++;
    }

    // Update the metadata structure for each key with the new size and cumulative sum
    for (int i = 0; i < num_unique_keys; i++) {
        int key = keys[i];
        int total_records = offsets[i] / sizeof(int);
        int cumulative_sum = 0;
        for (int j = 0; j < total_records; j++) {
            cumulative_sum += ((int*)data)[j + i * sizeof(int)];
        }
        metadatas[i].total_records = total_records;
        metadatas[i].cumulative_sum = cumulative_sum;
    }
}

// Function to get the initial size of the records array from the configuration manager
int get_initial_records() {
    return CONFIG_MANAGER.get_int("initial_records");
}

// Function to get the number of unique keys from an array of integers
int get_num_unique_keys(int* keys, int size) {
    int num_unique = 0;
    for (int i = 0; i < size; i++) {
        if (keys[i] != 0) {
            num_unique++;
        }
    }
    return num_unique;
}

// Function to get the index of a key in an array of integers
int get_index(int* keys, int size, int key) {
    for (int i = 0; i < size; i++) {
        if (keys[i] == key) {
            return i;
        }
    }
    return -1;
}

