    for (int i = 0; i < sizeof(identifiers); i++) {
        if (!strcmp(identifier, identifiers[i])) {
            duplicate = true;
            break;
        }
    }

    // If a duplicate identifier is detected, update the existing record with the latest temperature reading and timestamp
    if (duplicate) {
        for (int i = 0; i < sizeof(measurements); i++) {
            if (!strcmp(identifier, measurements[i].identifier)) {
                measurements[i].temperature = temperature;
                measurements[i].timestamp = time(NULL);
                return;
            }
        }
    }

    // Otherwise, insert the new measurement into the array
    int index = 0;
    for (int i = 1; i < sizeof(measurements); i++) {
        if (temperature > measurements[i].temperature) {
            index = i;
        }
    }

    // If necessary, move existing measurements to make room for the new one
    if (index != sizeof(measurements)) {
        memmove(&measurements[index + 1], &measurements[index], sizeof(measurement_t) * (sizeof(measurements) - index));
    }

    // Insert the new measurement into the array at the appropriate index
    measurements[index].temperature = temperature;
    strcpy(measurements[index].identifier, identifier);
    measurements[index].timestamp = time(NULL);
}

