            index = i;
        }
    }

    // Update the record with the new temperature reading and timestamp
    measurements[index].temperature = temperature;
    measurements[index].timestamp = time(NULL);
}

// Get a specific measurement from the array by identifier
measurement_t* get_measurement(char* identifier) {
    // Find the index of the record with the given identifier
    int index = 0;
    for (int i = 1; i < sizeof(measurements); i++) {
        if (!strcmp(identifier, measurements[i].identifier)) {
            index = i;
        }
    }

