// Define a function to initialize the product database
void initializeProductDatabase(size_t num_products, size_t max_memory) {
    // Allocate memory for the three arrays
    double* prices = malloc(num_products * sizeof(double));
    char** ids = malloc(num_products * sizeof(char*));
    Product* products = malloc(num_products * sizeof(Product));

    // Initialize the arrays with random values within the specified range
    for (int i = 0; i < num_products; i++) {
        prices[i] = rand() % max_memory;
        ids[i] = generate_product_id();
        products[i].price = prices[i];
        products[i].id = ids[i];
    }

    // Log the number of entries successfully created and any memory allocation failures
    int num_entries = 0;
    bool has_failure = false;
    for (int i = 0; i < num_products; i++) {
        if (prices[i] == NULL || ids[i] == NULL || products[i].price == 0.0 || products[i].id == NULL) {
            has_failure = true;
            break;
        } else {
            num_entries++;
        }
    }
    if (has_failure) {
        printf("ERROR: Memory allocation failure for %d out of %d products.\n", num_products - num_entries, num_products);
    } else {
        printf("SUCCESS: Initialized product database with %d entries.\n", num_entries);
    }

    // Free the allocated memory at the end of the function
    free(prices);
    for (int i = 0; i < num_products; i++) {
