        (*records)[i]->value = rand() % (max - min + 1) + min;
    }

    // Limit memory usage to a specified budget
    struct mallinfo meminfo = mallinfo();
    long total_memory = meminfo.uordblks;
    if (total_memory > MEMORY_BUDGET) {
        fprintf(stderr, "Memory usage exceeded budget\n");
