    string deadline;
    map<string, int> resources;
};

vector<Task> loadTasks(ifstream& input) {
    vector<Task> tasks;
    json::value root = json::parse(input);
    for (auto& task : root.get_array()) {
        Task t;
        t.priority = task["priority"].as_number().to_int();
        t.deadline = task["deadline"].as_string();
        for (auto& resource : task["resources"].as_object()) {
            t.resources[resource.first] = resource.second.as_number().to_int();
        }
        tasks.push_back(t);
    }
    return tasks;
}

void printTaskSummary(const vector<Task>& tasks) {
    cout << "Total number of tasks: " << tasks.size() << endl;
    int overdueTasks = 0;
    for (auto& task : tasks) {
