    pthread_t threads[10]; // Array of 10 threads for concurrent access to the record array
    char key_value_pairs[10][2][256]; // Array of 10 key-value pairs for populating the record array
    int i;
    for (i = 0; i < 10; i++) { // Initialize key-value pairs for populating the record array
        sprintf(key_value_pairs[i][0], "value%d", i);
        sprintf(key_value_pairs[i][1], "%d", i * i);
    }
    pthread_mutex_lock(&record_lock); // Acquire lock for thread-safe access to record array
    for (i = 0; i < 10; i++) { // Create threads for concurrent access to the record array
        if (pthread_create(&threads[i], NULL, handle_concurrent_access, (void *)key_value_pairs[i])) {
            printf("Error: unable to create thread\n"); // Output error message if thread creation failed
        }
    }
    for (i = 0; i < 10; i++) { // Wait for threads to complete
        pthread_join(threads[i], NULL);
    }
    log_usage(); // Log memory usage and performance bottlenecks
    printf("Records in array: %zu\n", get_count()); // Output the number of records in the array
    return 0;
}
