// Structure for storing information about each transaction
typedef struct {
    int id;
    char *item_name;
    double price;
} Transaction;

// Function to initialize a new transaction array with the given size
Transaction **init_transactions(int size) {
    // Allocate memory for the transaction array
    Transaction **transactions = (Transaction**) malloc(size * sizeof(Transaction*));
    if (transactions == NULL) {
        fprintf(stderr, "Failed to allocate memory for transactions\n");
        return NULL;
    }

    // Initialize each transaction with default values
    for (int i = 0; i < size; i++) {
        Transaction *transaction = (Transaction*) malloc(sizeof(Transaction));
        if (transaction == NULL) {
            fprintf(stderr, "Failed to allocate memory for transaction %d\n", i);
            return NULL;
        }

        transaction->id = i;
        transaction->item_name = "";
        transaction->price = 0.0;

        transactions[i] = transaction;
    }

    return transactions;
}

// Function to add a new transaction to the array
void add_transaction(Transaction **transactions, int size, Transaction *new_transaction) {
    // If the array is full, resize it by 50%
    if (size == 0 || size >= transactions[0]->id) {
        int new_size = size + (size >> 1);
        Transaction **new_transactions = (Transaction**) realloc(transactions, new_size * sizeof(Transaction*));
        if (new_transactions == NULL) {
            fprintf(stderr, "Failed to resize transaction array\n");
            return;
        }

        transactions = new_transactions;
    }

    // Add the new transaction to the end of the array
    Transaction *transaction = (Transaction*) malloc(sizeof(Transaction));
    if (transaction == NULL) {
        fprintf(stderr, "Failed to allocate memory for new transaction\n");
        return;
    }

    memcpy(transaction, new_transaction, sizeof(Transaction));
    transactions[size++] = transaction;
}

// Function to update a transaction in the array
void update_transaction(Transaction **transactions, int size, Transaction *updated_transaction) {
    // Find the index of the transaction to update
    int i;
    for (i = 0; i < size && transactions[i]->id != updated_transaction->id; i++);

    // If the transaction was not found, return
    if (i == size) {
        fprintf(stderr, "Failed to find transaction %d\n", updated_transaction->id);
        return;
    }

    // Update the transaction with the new values
    transactions[i]->item_name = updated_transaction->item_name;
    transactions[i]->price = updated_transaction->price;
}

// Function to print all transactions in the array
void print_transactions(Transaction **transactions, int size) {
    for (int i = 0; i < size; i++) {
        printf("Transaction %d: item = %s, price = %.2f\n", transactions[i]->id, transactions[i]->item_name, transactions[i]->price);
    }
}

// Function to clean up the transaction array
void free_transactions(Transaction **transactions, int size) {
    for (int i = 0; i < size; i++) {
        free(transactions[i]);
    }
    free(transactions);
}
