    // Allocate memory for arrays and structures
    int *keys = malloc(num_records * sizeof(int));
    double *data = malloc(num_records * sizeof(double));
    Offset **offsets = malloc(num_records * sizeof(Offset*));

    // Initialize keys, data, and offsets
    for (int i = 0; i < num_records; i++) {
