    if (file != NULL) {
        char line[1024];
        while (fgets(line, 1024, file) != NULL) {
            long offset;
            sscanf(line, "%ld", &offset);
            offsets[i].value = offset;
        }
    }

    // Handle memory allocation failures gracefully
    if (keys == NULL || data == NULL || offsets == NULL) {
        printf("Memory allocation failed. Exiting...\n");
        exit(1);
    }
}

// Function to clean up arrays and structures
void free_arrays() {
    free(keys);
    free(data);
    for (int i = 0; i < num_records; i++) {
        free(offsets[i]);
    }
    free(offsets);
}
