#include <string.h>
#include <sys/types.h>
#include <unistd.h>
#include <errno.h>
#include <syslog.h>

int process_file_and_execute(char *filename, char *command, int max_length, char *log_file_path) {
    // Check if the filename is valid and does not exceed the maximum length
    if (!validate_filename(filename, max_length)) {
        syslog(LOG_WARNING, "Invalid filename: %s\n", filename);
        return 0;
    }

    // Create a new filename by appending digits and the file type based on the length of the original filename
    char *modified_filename = create_new_filename(filename, max_length);
    if (!modified_filename) {
        syslog(LOG_ERR, "Failed to create modified filename: %s\n", strerror(errno));
        return 0;
    }

    // Execute the command in the background using asynchronous I/O or threads
    int exec_status = execute_command(modified_filename, command);
    if (exec_status == 0) {
        syslog(LOG_INFO, "Command executed successfully\n");
    } else {
        syslog(LOG_ERR, "Failed to execute command: %s\n", strerror(errno));
    }

    // Clean up resources and return the execution status
    free(modified_filename);
    return exec_status;
}

int validate_filename(char *filename, int max_length) {
    // Check if the filename is empty or contains invalid characters (e.g., double periods)
    if (strlen(filename) == 0 || strchr(filename, '.') != NULL) {
        return 0;
    }

    // Check if the filename exceeds the maximum length
    if (strlen(filename) > max_length) {
        return 0;
    }

    // The filename is valid and does not exceed the maximum length
    return 1;
}

char *create_new_filename(char *filename, int max_length) {
    char *modified_filename = malloc(max_length + 1);
    if (!modified_filename) {
        return NULL;
    }

    // Append digits and the file type based on the length of the original filename
    sprintf(modified_filename, "%s%08d", filename, getpid());
    strcat(modified_filename, ".out");

    return modified_filename;
}

int execute_command(char *modified_filename, char *command) {
    // Create a new process and execute the command in the background using asynchronous I/O or threads
    pid_t pid = fork();
    if (pid == 0) {
        // Child process executes the command
        execl("/bin/sh", "sh", "-c", command, modified_filename, NULL);
        syslog(LOG_ERR, "Failed to execute command: %s\n", strerror(errno));
        return 0;
    } else if (pid < 0) {
        // Error forking process
        syslog(LOG_ERR, "Failed to fork process: %s\n", strerror(errno));
        return 0;
    }

    // Parent process waits for the command to complete
    waitpid(pid, NULL, 0);

    // Check if the command executed successfully
    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        return 1;
    } else {
        syslog(LOG_ERR, "Command execution failed: %s\n", strerror(errno));
        return 0;
    }
}

void cleanup() {
    // Clean up resources and close log file
    free(modified_filename);
    closelog();
}']

