// Define the structs for items and transactions
typedef struct {
  int id;
  char *name;
  double value;
  int category_id;
} item;

typedef struct {
  time_t timestamp;
  char *transaction_id;
  int num_items;
  item *items;
} transaction;

// Function to initialize transactions
void init_transactions(int num_transactions, int num_items_per_transaction) {
  // Allocate memory for the transactions array
  transaction *transactions = malloc(num_transactions * sizeof(transaction));
  if (transactions == NULL) {
    printf("Failed to allocate memory for transactions\n");
    return;
  }

  // Initialize each transaction with a unique ID and timestamp
  for (int i = 0; i < num_transactions; i++) {
    transaction *transaction = &transactions[i];

    // Generate a unique transaction ID using a hash function
    unsigned long long int hash = (unsigned long long int)time(NULL);
    sprintf(transaction->transaction_id, "%llx", hash);

    // Set the timestamp for this transaction
    transaction->timestamp = time(NULL);

    // Allocate memory for the items in this transaction
    transaction->num_items = num_items_per_transaction;
    transaction->items = malloc(num_items_per_transaction * sizeof(item));
    if (transaction->items == NULL) {
      printf("Failed to allocate memory for items in transaction %d\n", i);
      return;
    }
  }

  // Initialize each item with a category ID and value
  for (int i = 0; i < num_transactions; i++) {
    transaction *transaction = &transactions[i];

    for (int j = 0; j < transaction->num_items; j++) {
      item *item = &transaction->items[j];

      // Generate a random category ID
      int category_id = rand() % 10 + 1;

      // Set the category ID for this item
      item->category_id = category_id;

      // Set the value for this item
      double value = (double)rand() / RAND_MAX * 1000;
      item->value = value;
    }
  }

  // Print the transactions and their items
  printf("Initialized %d transactions with %d items each\n", num_transactions, num_items_per_transaction);
  for (int i = 0; i < num_transactions; i++) {
    transaction *transaction = &transactions[i];
    printf("Transaction %d:\n", i + 1);
    printf("\tID: %s\n", transaction->transaction_id);
    printf("\tTimestamp: %ld\n", transaction->timestamp);
    printf("\tItems:\n");
    for (int j = 0; j < transaction->num_items; j++) {
      item *item = &transaction->items[j];
      printf("\t\t%d: Category ID: %d, Value: %.2f\n", j + 1, item->category_id, item->value);
    }
  }

  // Free the memory for the transactions and items
  free(transactions);
}
