['Here is a possible implementation of the modular media processing library in C:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ffmpeg/avcodec.h>
#include <ffmpeg/avformat.h>
#include <ffmpeg/avutil.h>
#include <ffmpeg/avfilter.h>

// Configuration file format:
// [media_process]
//   mp4_parser = ffmpeg, libmp4v2
//   h264_decoder = ffmpeg, -c:v libx264
//   aac_decoder = ffmpeg, -c:a libfdk_aac
//   webp_encoder = ffmpeg, -c:v libwebp

#define BUFFER_SIZE 1024*1024 // 1MB buffer size

typedef struct media_process_context {
    AVFormatContext *format_ctx;
    AVCodecContext *video_decoder;
    AVCodecContext *audio_decoder;
    AVFilterContext *filter_ctx;
} media_process_context_t;

void media_process_init(media_process_context_t *context, const char *config_file) {
    // Initialize FFmpeg library
    av_register_all();
    avformat_network_init();

    // Open configuration file and read parameters
    FILE *config = fopen(config_file, "r");
    if (!config) {
        printf("Error: unable to open configuration file\n");
        return;
    }

    char mp4_parser[BUFFER_SIZE];
    char h264_decoder[BUFFER_SIZE];
    char aac_decoder[BUFFER_SIZE];
    char webp_encoder[BUFFER_SIZE];

    while (!feof(config)) {
        fgets(buffer, BUFFER_SIZE, config);

        if (strncmp(buffer, "media_process", 13) == 0) {
            // Parse media processing parameters from configuration file
            sscanf(buffer, "%*[^\"]\"%s\"", mp4_parser);
            sscanf(buffer, "%*[^=]=%*[^;]\";%s\",", h264_decoder);
            sscanf(buffer, "%*[^=]=%*[^;];%s\",", aac_decoder);
            sscanf(buffer, "%*[^=]=%*[^;];%s\",", webp_encoder);
        }
    }

    // Initialize media processing components using FFmpeg APIs
    context->format_ctx = avformat_alloc_context();
    if (!context->format_ctx) {
        printf("Error: unable to allocate media process context\n");
        return;
    }

    AVCodecParameters *codecpar;
    codecpar = avcodec_parameters_alloc();
    if (!codecpar) {
        printf("Error: unable to allocate codec parameters\n");
        return;
    }

    // MP4 parser component
    context->format_ctx->oformat = AV_NE(AV_NE(mp4_parser));
    if (context->format_ctx->oformat == NULL) {
        printf("Error: unable to open output format %s\n", mp4_parser);
        return;
    }

    // H.264/HEVC video decoder component
    context->video_decoder = avcodec_alloc_context3(NULL);
    if (!context->video_decoder) {
        printf("Error: unable to allocate video decoder\n");
        return;
    }

    codecpar = avcodec_parameters_alloc();
    if (!codecpar) {
        printf("Error: unable to allocate video codec parameters\n");
        return;
    }

    // AAC audio decoder component
    context->audio_decoder = avcodec_alloc_context3(NULL);
    if (!context->audio_decoder) {
        printf("Error: unable to allocate audio decoder\n");
        return;
    }

    codecpar = avcodec_parameters_alloc();
    if (!codecpar) {
        printf("Error: unable to allocate audio codec parameters\n");
        return;
    }

    // WebP image encoder component
    context->filter_ctx = avfilter_graph_alloc_filter(NULL, NULL);
    if (!context->filter_ctx) {
        printf("Error: unable to allocate filter context\n");
        return;
    }

    // Initialize media processing components using FFmpeg APIs
    int ret = avcodec_open2(context->video_decoder, NULL, NULL);
    if (ret < 0) {
        printf("Error: unable to open video decoder\n");
        return;
    }

    ret = avcodec_open2(context->audio_decoder, NULL, NULL);
    if (ret < 0) {
        printf("Error: unable to open audio decoder\n");
        return;
    }

    ret = avfilter_graph_create_filter(&context->filter_ctx, NULL, "scale", NULL, NULL, 0, NULL, NULL);
    if (ret < 0) {
        printf("Error: unable to create scale filter\n");
        return;
    }

    // Initialize thread pool for resource management
    context->thread_pool = av_tp_alloc(NULL);
    if (!context->thread_pool) {
        printf("Error: unable to allocate thread pool\n");
        return;
    }
}

void media_process_deinit(media_process_context_t *context) {
    // Deinitialize media processing components using FFmpeg APIs
    avcodec_close(context->video_decoder);
    avcodec_free_context(&context->video_decoder);

    avcodec_close(context->audio_decoder);
    avcodec_free_context(&context->audio_decoder);

    avfilter_graph_destroy(context->filter_ctx);
    av_tp_release(context->thread_pool);
}

void media_process_run(media_process_context_t *context, const char *input_file) {
    // Run media processing pipeline using FFmpeg APIs
    AVPacket packet;
    while (av_read_frame(context->format_ctx, &packet) >= 0) {
        AVFrame *decoded_frame = NULL;
        int ret = avcodec_decode_video2(&context->video_decoder, NULL, NULL, NULL);
        if (ret < 0) {
            printf("Error: unable to decode video frame\n");
            return;
        }

        decoded_frame = av_frame_alloc();
        if (!decoded_frame) {
            printf("Error: unable to allocate video frame\n");
            return;
        }

        ret = avcodec_decode_video2(&context->video_decoder, NULL, decoded_frame);
        if (ret < 0) {
            printf("Error: unable to decode video frame\n");
            return;
        }

        int scaled_width = 1920;
        int scaled_height = 1080;
        AVFrame *scaled_frame = av_frame_alloc();
        if (!scaled_frame) {
            printf("Error: unable to allocate scaled video frame\n");
            return;
        }

        ret = av_tp_run(context->thread_pool, NULL, NULL);
        if (ret < 0) {
            printf("Error: unable to run thread pool\n");
            return;
        }
    }
}
