// Data structure for storing records of data_entry objects
typedef struct record {
    int key;
    float value;
    bool status;
} record;

// Database-like structure to store records of data_entry objects
typedef struct database {
    int num_records;
    record* records;
} database;

// Initialize a new database
database* init_database() {
    // Allocate memory for the database structure
    database* db = (database*) malloc(sizeof(database));
    if (db == NULL) {
        return NULL;
    }

    // Set the number of records to 0
    db->num_records = 0;

    // Allocate memory for the array of record pointers
    db->records = (record**) malloc(sizeof(record*) * INITIAL_RECORD_ARRAY_SIZE);
    if (db->records == NULL) {
        free(db);
        return NULL;
    }

    // Initialize each record pointer to NULL
    for (int i = 0; i < INITIAL_RECORD_ARRAY_SIZE; i++) {
        db->records[i] = NULL;
    }

    // Return the initialized database structure
    return db;
}

// Add a new record to the database
bool add_record(database* db, int key, float value) {
    // Check if the database is NULL or if it has reached its maximum capacity
    if (db == NULL || db->num_records >= MAX_RECORD_COUNT) {
        return false;
    }

    // Generate a random status indicator
    bool status = ((rand() % 2) == 0);

    // Allocate memory for the new record
    record* new_record = (record*) malloc(sizeof(record));
    if (new_record == NULL) {
        return false;
    }

    // Set the key, value, and status of the new record
    new_record->key = key;
    new_record->value = value;
    new_record->status = status;

    // Add the new record to the database
    db->records[db->num_records++] = new_record;

    // Return success
    return true;
}

// Remove a record from the database
bool remove_record(database* db, int key) {
    // Check if the database is NULL or if it has no records
    if (db == NULL || db->num_records == 0) {
        return false;
    }

    // Find the index of the record with the given key
    int i = find_record(db, key);
    if (i < 0) {
        return false;
    }

    // Remove the record from the database
    db->num_records--;
    for (int j = i; j < db->num_records; j++) {
        db->records[j] = db->records[j + 1];
    }

    // Free the memory of the removed record
    free(db->records[i]);
    db->records[i] = NULL;

    // Return success
    return true;
}

// Find a record in the database with the given key
int find_record(database* db, int key) {
    // Check if the database is NULL or has no records
    if (db == NULL || db->num_records == 0) {
        return -1;
    }

    // Iterate through the records and compare the keys
    for (int i = 0; i < db->num_records; i++) {
        if (db->records[i]->key == key) {
            return i;
        }
    }

    // Return -1 if the record is not found
    return -1;
}

// Update a record in the database with the given key
bool update_record(database* db, int key, float value) {
    // Check if the database is NULL or has no records
    if (db == NULL || db->num_records == 0) {
        return false;
    }

    // Find the index of the record with the given key
    int i = find_record(db, key);
    if (i < 0) {
        return false;
    }

    // Update the value of the record
    db->records[i]->value = value;

    // Return success
    return true;
}

// Iterate through all records in the database and perform a callback function on each one
void iterate_records(database* db, void (*callback)(record*)) {
    // Check if the database is NULL or has no records
    if (db == NULL || db->num_records == 0) {
        return;
    }

    // Iterate through each record and perform the callback function
    for (int i = 0; i < db->num_records; i++) {
        callback(db->records[i]);
    }
}

// Free the memory of a database structure and all its records
void free_database(database* db) {
    // Check if the database is NULL
    if (db == NULL) {
        return;
    }

    // Iterate through each record and free its memory
    for (int i = 0; i < db->num_records; i++) {
        free(db->records[i]);
        db->records[i] = NULL;
    }

    // Free the memory of the record array
    free(db->records);
    db->records = NULL;

    // Free the memory of the database structure
    free(db);
    db = NULL;
}
