#include <pthread.h>

// Define the record structure to store int values
typedef struct {
    int value;
} record;

// Define the function that will dynamically allocate memory for arrays of long, int and record structures
void allocate_memory(long* offset, int* key, record** records, int num_records) {
    // Calculate the total size of memory needed to store the arrays
    size_t total_size = sizeof(long) * num_records + sizeof(int) * num_records + sizeof(record) * num_records;

    // Check if the total size is within the allowed limit
    if (total_size > 0.5 * get_system_memory()) {
        printf("Error: Total memory usage exceeds 50%% of available system memory\n");
        return;
    }

    // Allocate memory for the arrays using malloc
    long* offset_ptr = (long*)malloc(sizeof(long) * num_records);
    int* key_ptr = (int*)malloc(sizeof(int) * num_records);
    record** records_ptr = (record**)malloc(sizeof(record) * num_records);

    // Check if memory allocation was successful
    if (!offset_ptr || !key_ptr || !records_ptr) {
        printf("Error: Memory allocation failed\n");
        return;
    }

    // Initialize the arrays using data from the input arrays
    for (int i = 0; i < num_records; i++) {
        offset_ptr[i] = offset[i];
        key_ptr[i] = key[i];
        records_ptr[i] = (record*)malloc(sizeof(record));
        records_ptr[i]->value = 0; // Set the initial value to 0
    }

    // Define a mutex to handle concurrent access to shared resources
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Define a function to free all allocated memory upon completion
    void free_memory() {
        for (int i = 0; i < num_records; i++) {
            free(records_ptr[i]);
        }
        free(offset_ptr);
        free(key_ptr);
        free(records_ptr);
    }

    // Define a function to update the value of each record within the specified range
    void update_value(int key, int minValue, int maxValue) {
        for (int i = 0; i < num_records; i++) {
            if (key == key_ptr[i]) {
                pthread_mutex_lock(&mutex);
                records_ptr[i]->value += offset_ptr[i];
                pthread_mutex_unlock(&mutex);
            }
        }
    }

    // Define a function to retrieve the value of each record within the specified range
    int get_value(int key) {
        for (int i = 0; i < num_records; i++) {
            if (key == key_ptr[i]) {
                return records_ptr[i]->value;
            }
        }
        return -1; // Return -1 if the key is not found in any record
    }
}

