// Function to read a file line by line and process each line
void process_file(FILE* input) {
    // Define variables for the offset and key arrays
    long* offsets = NULL;
    int* keys = NULL;

    // Allocate memory for the offset and key arrays
    size_t num_lines = 0;

    while (getline(&input, &num_lines) != -1) {
        // Increment the line count and allocate more memory if necessary
        if (num_lines > 0) {
            offsets = realloc(offsets, num_lines * sizeof(long));
            keys = realloc(keys, num_lines * sizeof(int));

            if (offsets == NULL || keys == NULL) {
                fprintf(stderr, "Memory allocation failed\n");
                exit(EXIT_FAILURE);
            }
        }

        // Parse the line and extract the offset and key values
        char* line = input;
        char* token = strtok(line, ",");
        long offset = atol(token);
        int key = atoi(strtok(NULL, "\n"));

        // Add the offset and key to the arrays
        offsets[num_lines] = offset;
        keys[num_lines] = key;

        num_lines++;
    }

    free(offsets);
    free(keys);
}

// Function to handle memory allocation failures gracefully
void handle_memory_allocation_failure() {
    fprintf(stderr, "Memory allocation failed\n");
    exit(EXIT_FAILURE);
}

