        fprintf(stderr, "Usage: %s input_file\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    // Open the input file and check for errors
    FILE* input = fopen(argv[1], "r");
    if (input == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
