        owner_map[i] = malloc(num_projects * sizeof(char*));
        if (owner_map[i] == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }
    }

    // Populate the ownership map
    for (size_t i = 0; i < num_projects; i++) {
        owner_map[i][i] = projects[i]->owner;
        for (size_t j = i + 1; j < num_projects; j++) {
            if (strcmp(projects[i]->tags, projects[j]->tags) == 0) {
