// Struct to hold information about each hash function or cipher
struct HashCipherInfo {
    char *name;
    void (*impl_func)(void*);
    void* params;
};

// Array of pointers to structs holding information about each available hash function or cipher
struct HashCipherInfo **hash_ciphers = NULL;
int num_hash_ciphers = 0;

// Function to check if a given hash function or cipher is supported by the system
int isHashCipherSupported(char* name) {
    // Check if the given name is in the list of available hash functions or ciphers
    for (int i = 0; i < num_hash_ciphers; ++i) {
        if (!strcmp(name, hash_ciphers[i]->name)) {
            return 1;
        }
    }
    return 0;
}

// Function to get a list of available cryptographic hash functions and block ciphers
void getHashCipherList(char*** list, int* num_hash_ciphers) {
    // Initialize the list with space for all supported hash functions and ciphers
    *list = (char**) malloc((num_hash_ciphers + 1) * sizeof(char*));

    // Fill in the list of available hash functions and ciphers
    int count = 0;
    for (int i = 0; i < num_hash_ciphers; ++i) {
        if (isHashCipherSupported(hash_ciphers[i]->name)) {
            (*list)[count] = hash_ciphers[i]->name;
            count++;
        }
    }
    *num_hash_ciphers = count;
}

// Function to dynamically allocate memory for the list of available hash functions and ciphers
void initHashCipherList() {
    // Initialize the array of pointers to structs holding information about each available hash function or cipher
    hash_ciphers = (struct HashCipherInfo**) malloc(num_hash_ciphers * sizeof(struct HashCipherInfo*));

    // Dynamically allocate memory for each struct and fill it with the necessary information
    for (int i = 0; i < num_hash_ciphers; ++i) {
        hash_ciphers[i] = (struct HashCipherInfo*) malloc(sizeof(struct HashCipherInfo));
        hash_ciphers[i]->name = (char*) malloc(128 * sizeof(char));
        hash_ciphers[i]->impl_func = NULL;
        hash_ciphers[i]->params = NULL;
    }
}

// Function to release resources allocated for the list of available hash functions and ciphers
void freeHashCipherList() {
    // Release memory for each struct in the array
    for (int i = 0; i < num_hash_ciphers; ++i) {
        free(hash_ciphers[i]->name);
        free(hash_ciphers[i]);
    }

    // Release memory for the array of pointers to structs
    free(hash_ciphers);
}
```
