// Structure to represent a custom data structure in the linked list
typedef struct {
    char* string;
    int key;
} custom_data_t;

// Linked list node structure for the custom data structures
typedef struct Node {
    custom_data_t data;
    struct Node* next;
} node_t;

// Function to insert a new custom data structure into the linked list
void insert_node(custom_data_t data) {
    // Allocate memory for the new node
    node_t* new_node = malloc(sizeof(node_t));
    assert(new_node != NULL);

    // Initialize the new node with the given data
    new_node->data = data;
    new_node->next = NULL;

    // If the list is empty, set the head pointer to point to the new node
    if (head == NULL) {
        head = new_node;
    } else {
        // Find the last node in the list and insert the new node after it
        node_t* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

// Function to traverse the linked list in ascending order based on the integer key
void traverse_list() {
    // If the list is empty, return
    if (head == NULL) {
        return;
    }

    // Start at the head node and traverse the list until the end is reached
    node_t* current = head;
    while (current != NULL) {
        printf("%d: %s\n", current->data.key, current->data.string);
        current = current->next;
    }
}

// Function to sort the linked list based on the integer key in ascending order
void sort_list() {
    // If the list is empty or has only one node, return
    if (head == NULL || head->next == NULL) {
        return;
    }

    // Start at the head node and traverse the list until the end is reached
    node_t* current = head;
    while (current != NULL) {
        // If the next node has a smaller key, swap them
        if (current->next != NULL && current->data.key > current->next->data.key) {
            custom_data_t temp = current->data;
            current->data = current->next->data;
            current->next->data = temp;
        }
        current = current->next;
    }
}

// Function to integrate with an external data source that provides initial data for the collection
void populate_list(const char* filename) {
    // Open the file in read mode
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        return;
    }

    // Read each line of the file and parse it as a custom data structure
    while (!feof(file)) {
        char buffer[1024];
        fgets(buffer, 1024, file);
        int key = atoi(strtok(buffer, " "));
        char* string = strtok(NULL, "\n");
        custom_data_t data = {string, key};
        insert_node(data);
    }

    // Close the file
    fclose(file);
}
