// Structure to represent a single transaction
typedef struct {
    char* string;
    int key;
    double value;
} Transaction;

// Linked list node for storing transactions
typedef struct Node {
    Transaction data;
    struct Node* next;
} Node;

// Head pointer for the linked list of transactions
static Node* head = NULL;

// Function to insert a new transaction into the linked list
void insertTransaction(Transaction transaction) {
    // Create a new node for the transaction
    Node* newNode = malloc(sizeof(Node));
    newNode->data = transaction;
    newNode->next = head;

    // Update the head pointer to point to the new node
    head = newNode;
}

// Function to traverse the linked list and print all transactions
void traverseTransactions() {
    Node* current = head;
    while (current != NULL) {
        printf("%d: %s, %.2f\n", current->data.key, current->data.string, current->data.value);
        current = current->next;
    }
}

// Function to filter transactions based on a given key value
void filterTransactions(int key) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.key == key) {
            printf("%d: %s, %.2f\n", current->data.key, current->data.string, current->data.value);
        }
        current = current->next;
    }
}

// Function to sort transactions based on their keys in ascending order
void sortTransactions() {
    Node* current = head;
    while (current != NULL) {
        if (current->data.key < current->next->data.key) {
            // Swap the nodes if the current key is less than the next node's key
            Node* temp = current->next;
            current->next = temp->next;
            temp->next = current;
        }
        current = current->next;
    }
}

// Function to update the linked list after a modification has been made
void updateList(Transaction transaction) {
    // Find the node that needs to be updated
    Node* current = head;
    while (current != NULL && current->data.key != transaction.key) {
        current = current->next;
    }

    // Update the data in the node if it exists
    if (current != NULL) {
        current->data = transaction;
    } else {
        // If the key does not exist, insert a new node
        Node* newNode = malloc(sizeof(Node));
        newNode->data = transaction;
        newNode->next = head;
        head = newNode;
    }
}
