MemoryManager* init_memory(char** input_strings, int num_inputs) {
    // Check for empty or null inputs and handle accordingly
    if (num_inputs == 0 || input_strings[0] == NULL) {
        return NULL;
    }

    // Determine the maximum string length and cap at 1024 characters to prevent excessive memory allocation
    int max_length = 0;
    for (int i = 0; i < num_inputs; i++) {
        if (strlen(input_strings[i]) > max_length) {
            max_length = strlen(input_strings[i]);
        }
    }
    if (max_length > 1024) {
        max_length = 1024;
    }

    // Allocate memory for the arrays of long, int, and record structures
    long* offsets = malloc(sizeof(long) * num_inputs);
    int* keys = malloc(sizeof(int) * num_inputs);
    struct record* records = malloc(sizeof(struct record) * max_length);

    // Initialize the memory manager structure and return a pointer to it
    MemoryManager* mm = malloc(sizeof(MemoryManager));
    mm->offsets = offsets;
    mm->keys = keys;
    mm->records = records;

    // Log detailed information about the allocation process
    printf("Allocated memory for arrays of long, int, and record structures\n");
    printf("Number of input strings: %d\n", num_inputs);
    printf("Maximum string length: %d\n", max_length);
    printf("Memory usage: %lu bytes\n", (unsigned long)((sizeof(long) * num_inputs + sizeof(int) * num_inputs + sizeof(struct record) * max_length)));

    return mm;
}

void free_memory(MemoryManager* mm) {
    // Check for null inputs and handle accordingly
    if (mm == NULL || mm->offsets == NULL || mm->keys == NULL || mm->records == NULL) {
        return;
    }

    // Free the memory allocated for the arrays of long, int, and record structures
    free(mm->offsets);
    free(mm->keys);
    free(mm->records);

    // Log information about the deallocation process
    printf("Deallocated memory for arrays of long, int, and record structures\n");

    // Free the memory manager structure and set it to NULL
    free(mm);
}

void update_memory(MemoryManager* mm) {
    // Check for null inputs and handle accordingly
    if (mm == NULL || mm->offsets == NULL || mm->keys == NULL || mm->records == NULL) {
        return;
    }

    // Acquire the mutex lock to ensure thread-safe access to the memory manager structure
    pthread_mutex_lock(&mm->lock);

    // Update the arrays of long, int, and record structures with new data
    for (int i = 0; i < mm->num_inputs; i++) {
        mm->offsets[i]++;
        mm->keys[i]++;
        mm->records[mm->offsets[i]].value++;
        mm->records[mm->offsets[i]].substring = mm->records[mm->offsets[i]].substring + 1;
    }

    // Release the mutex lock and return
    pthread_mutex_unlock(&mm->lock);
}

void read_memory(MemoryManager* mm) {
    // Check for null inputs and handle accordingly
    if (mm == NULL || mm->offsets == NULL || mm->keys == NULL || mm->records == NULL) {
        return;
    }

    // Acquire the lock-free mutex to ensure thread-safe access to the memory manager structure
    pthread_mutex_lock(&mm->lock);

    // Read from the arrays of long, int, and record structures without using locks
    for (int i = 0; i < mm->num_inputs; i++) {
