class CustomDataManager {
private:
    // Hash table to store custom data structures
    std::unordered_map<std::string, CustomData> dataMap;

    // Balanced binary search tree for ordered traversal
    std::map<int, CustomData> sortedData;

    // Mutex to synchronize access to the hash table and balanced BST
    std::mutex mutex;

public:
    // Constructor to initialize the data structures
    CustomDataManager() {
        // Initialize the hash table and balanced BST with an empty state
        dataMap.clear();
        sortedData.clear();
    }

    // Function to add a new custom data structure to the collection
    void addCustomData(const std::string& key, int value, double weight) {
        std::lock_guard<std::mutex> lock(mutex);
        CustomData data(key, value, weight);
        dataMap[key] = data;
        sortedData.insert({value, data});
    }

    // Function to retrieve a custom data structure by its key
    CustomData getCustomData(const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex);
        return dataMap[key];
    }

    // Function to remove a custom data structure from the collection
    void removeCustomData(const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex);
        dataMap.erase(key);
        sortedData.erase(dataMap[key].value);
    }

    // Function to retrieve all custom data structures in the collection
    std::vector<CustomData> getAllCustomData() {
        std::lock_guard<std::mutex> lock(mutex);
        return dataMap.values();
    }

    // Function to update a custom data structure by its key
