// Function to generate prime numbers within a specified range
int get_prime(short num) {
    int is_prime = 0;
    for (int i = 2; i < sqrt(num); i++) {
        if (num % i == 0) {
            is_prime = 1;
            break;
        }
    }
    if (!is_prime) {
        return num;
    } else {
        return -1;
    }
}

// Function to generate normalized random numbers between 0 and 1
float normalized_random() {
    float rand = (float)rand() / RAND_MAX;
    return rand * (1.0 - EPSILON) + EPSILON;
}
