int init_and_populate(long *offsets, int *keys, record_t **records, size_t num_records) {
    // Validate input sizes
    if (num_records == 0 || num_records > SIZE_MAX / sizeof(record_t)) {
        errno = EINVAL;
        return -1;
    }

    // Allocate memory for the arrays
    offsets = malloc(num_records * sizeof(long));
    keys = malloc(num_records * sizeof(int));
    records = malloc(num_records * sizeof(record_t*));
    if (offsets == NULL || keys == NULL || records == NULL) {
        errno = ENOMEM;
        return -1;
    }

    // Populate the arrays with random values
    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = rand() % SIZE_MAX;
        keys[i] = rand();
        records[i] = malloc(sizeof(record_t));
        if (records[i] == NULL) {
            errno = ENOMEM;
            return -1;
        }
        records[i]->value = 0;
    }

    // Return successfully
    return 0;
}

// Cleanup function to release memory allocated by init_and_populate()
void cleanup(long *offsets, int *keys, record_t **records) {
    for (size_t i = 0; i < num_records; ++i) {
