// Function to dynamically allocate and manage memory for the flexible data structure
void initialize_records(struct Records* records, size_t record_count) {
    // Validate user-specified parameters
    if (record_count <= 0) {
        fprintf(stderr, "Invalid record count: %zu\n", record_count);
        return;
    }

    // Allocate memory for the records
    records->records = malloc(sizeof(struct Record) * record_count);
    if (records->records == NULL) {
        fprintf(stderr, "Failed to allocate memory for %zu records\n", record_count);
        return;
    }

    // Initialize the offset values based on the sum of the previous two records' offsets
    size_t i = 0;
    while (i < record_count) {
        if (i == 0) {
            records->records[i].offset = 0;
        } else if (i == 1) {
            records->records[i].offset = records->records[i - 1].offset + 1;
        } else {
            records->records[i].offset = records->records[i - 2].offset + records->records[i - 1].offset;
        }
        i++;
    }

    // Generate prime numbers within the specified range for the keys
    srand(time(NULL));
    for (size_t i = 0; i < record_count; i++) {
        records->records[i].key = generate_prime_number();
    }

    // Initialize normalized random float values between 0 and 1 for the values
    for (size_t i = 0; i < record_count; i++) {
        records->records[i].value = (float)rand() / (float)(RAND_MAX);
    }

    // Set the error flag to indicate successful initialization
    records->error_flag = false;
}

// Function to generate prime numbers within a specified range
int generate_prime_number() {
    int min = 2, max = 1000;
    while (true) {
        if (is_prime(min)) {
            return min;
        }
        min++;
        if (max < min) {
            break;
        }
    }
    return -1;
}

// Function to check if a number is prime
bool is_prime(int num) {
    for (int i = 2; i <= sqrt(num); i++) {
        if (num % i == 0) {
            return false;
        }
    }
    return true;
}

// Function to release the memory allocated for the records
void free_records(struct Records* records) {
    free(records->records);
}
```
This function uses a modular design that separates memory allocation, data generation, validation, and error handling. It validates user-specified parameters, allocates memory for the records, initializes the offset values based on the sum of the previous two records' offsets, generates prime numbers within the specified range for the keys, initializes normalized random float values between 0 and 1 for the values, sets the error flag to indicate successful initialization, and finally releases the memory allocated for the records.

