// Function to create a new directory with a given name and set an environment variable to the path of the directory
fn create_directory(name: &str) -> Result<String, String> {
    // Check if the environment variable is already set
    let env_var = std::env::var("DIRECTORY_PATH").unwrap_or_else(|_| "".to_string());
    if !env_var.is_empty() {
        return Ok(env_var);
    }

    // Create a new directory with the given name
    let mut path = std::path::PathBuf::new();
    path.push(".");
    path.push(name);
    if !path.exists() {
        match std::fs::create_dir(&path) {
            Ok(_) => (),
            Err(e) => return Err(format!("Error creating directory: {}", e)),
        }
    }

    // Set the environment variable to the path of the new directory
    match std::env::set_var("DIRECTORY_PATH", &path.to_string_lossy()) {
        Ok(_) => (),
        Err(e) => return Err(format!("Error setting environment variable: {}", e)),
    }

    // Return the path of the new directory
    Ok(path.to_string_lossy().into_owned())
}

// Function to handle concurrent access to create_directory and set_env_var
fn create_directory_and_set_env_var(name: &str) -> Result<String, String> {
    // Create a lock for the directory creation function
    let mutex = std::sync::Mutex::new(());
    let lock = mutex.lock().unwrap();

    // Check if the environment variable is already set
    let env_var = std::env::var("DIRECTORY_PATH").unwrap_or_else(|_| "".to_string());
    if !env_var.is_empty() {
        return Ok(env_var);
    }

    // Create a new directory with the given name inside the lock
    let mut path = std::path::PathBuf::new();
    path.push(".");
    path.push(name);
    if !path.exists() {
        match std::fs::create_dir(&path) {
            Ok(_) => (),
            Err(e) => return Err(format!("Error creating directory: {}", e)),
        }
    }

    // Set the environment variable to the path of the new directory inside the lock
    match std::env::set_var("DIRECTORY_PATH", &path.to_string_lossy()) {
        Ok(_) => (),
        Err(e) => return Err(format!("Error setting environment variable: {}", e)),
    }

    // Return the path of the new directory
    Ok(path.to_string_lossy().into_owned())
}

// Function to handle memory allocation failures robustly
fn allocate_memory<T>(size: usize) -> Result<Vec<T>, String> {
    // Try to allocate memory for the vector
    match Vec::with_capacity(size) {
        Ok(v) => (),
        Err(_) => return Err("Memory allocation failed".to_string()),
    }

    // Initialize the vector with a default value
    v.resize(size, Default::default());

    // Return the initialized vector
    Ok(v)
}']

