// Function to process a sequence of network packets received through a socket connection
void process_packets(int sockfd, struct sockaddr_in* client_addr) {
  // Packet metadata structure to store packet identifier, timestamp, source IP, destination IP, and payload size
  typedef struct {
    uint32_t id;
    uint64_t ts;
    char src_ip[INET_ADDRSTRLEN];
    char dst_ip[INET_ADDRSTRLEN];
    int payload_size;
  } packet_metadata_t;

  // Dynamic array to store all packets with their metadata
  packet_metadata_t* packet_array = custom_malloc(sizeof(packet_metadata_t) * MAX_PACKETS);
  size_t num_packets = 0;

  while (1) {
    // Receive a network packet from the socket connection
    char buffer[MAX_BUFFER];
    int bytes_received = recvfrom(sockfd, buffer, MAX_BUFFER, 0, client_addr, sizeof(*client_addr));

    if (bytes_received < 0) {
      // Handle I/O errors gracefully
      perror("recvfrom failed");
      break;
    }

    // Extract packet metadata from the received buffer
    struct iphdr* ip_header = (struct iphdr*)buffer;
    uint32_t id = ntohl(ip_header->id);
    uint64_t ts = ntohl(ip_header->timestamp);
    char src_ip[INET_ADDRSTRLEN];
    char dst_ip[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &ip_header->saddr, src_ip, INET_ADDRSTRLEN);
    inet_ntop(AF_INET, &ip_header->daddr, dst_ip, INET_ADDRSTRLEN);
    int payload_size = ntohs(ip_header->tot_len) - sizeof(struct iphdr);

    // Add the packet metadata to the dynamic array
    packet_array[num_packets].id = id;
    packet_array[num_packets].ts = ts;
    strncpy(packet_array[num_packets].src_ip, src_ip, INET_ADDRSTRLEN);
    strncpy(packet_array[num_packets].dst_ip, dst_ip, INET_ADDRSTRLEN);
    packet_array[num_packets].payload_size = payload_size;
    num_packets++;
  }

  // Calculate and print the average packet size
  uint64_t total_payload_size = 0;
  for (size_t i = 0; i < num_packets; i++) {
    total_payload_size += packet_array[i].payload_size;
  }
  printf("Average packet size: %lu bytes\n", total_payload_size / num_packets);

  // Print all packets with their metadata
  for (size_t i = 0; i < num_packets; i++) {
    printf("%d: ID=%u, TS=%llu, SRC=%s, DST=%s, PAYLOAD=%d bytes\n",
      i + 1, packet_array[i].id, packet_array[i].ts, packet_array[i].src_ip, packet_array[i].dst_ip, packet_array[i].payload_size);
  }
}
