#define ERROR_INVALID_ARGUMENT -1
#define ERROR_MEMORY_ALLOCATION_FAILED -2
#define ERROR_NETWORK_ERROR -3
#define ERROR_API_RATE_LIMIT_EXCEEDED -4
#define ERROR_CONNECTION_INTERRUPTED -5

// Define the status indicators for the record
