    SYSTEM_HEALTHY,
    SYSTEM_UNHEALTHY,
};

// Function to initialize the arrays and retrieve metrics from an external monitoring API
int getMetrics(Arrays *arrays, int num_records, int frequency, enum logging_level level) {
    // Validate the input arguments
    if (arrays == NULL || num_records <= 0 || frequency < 0 || level < LOG_DEBUG || level > LOG_NONE) {
        return ERROR_INVALID_ARGUMENT;
    }

    // Initialize the arrays
    for (int i = 0; i < num_records; i++) {
        // Allocate memory for the record
        Record *record = malloc(sizeof(Record));
        if (record == NULL) {
            return ERROR_MEMORY_ALLOCATION_FAILED;
        }

        // Initialize the record
        record->key = i + 1;
        record->temperature_reading = 0;
        record->energy_consumption = 0.0;
        record->indicator = SYSTEM_HEALTHY;

        // Add the record to the array
        arrays->records[i] = record;
    }

    // Set the number of records in the array
    arrays->num_records = num_records;

    // Retrieve the metrics from the external monitoring API
    for (int i = 0; i < frequency; i++) {
        // Connect to the API and retrieve the metrics
        int ret = connectToAPI(arrays, level);
        if (ret != ERROR_SUCCESS) {
            return ret;
        }

        // Update the records with the retrieved metrics
        for (int j = 0; j < num_records; j++) {
            Record *record = arrays->records[j];
            record->temperature_reading += retrieveTemperature(arrays, j);
            record->energy_consumption += retrieveEnergyConsumption(arrays, j);
        }
    }

    // Return success
    return ERROR_SUCCESS;
}

// Connect to the external monitoring API and retrieve the metrics
int connectToAPI(Arrays *arrays, enum logging_level level) {
    // Initialize the socket
    int sock = 0;
    if (sock == 0) {
        return ERROR_NETWORK_ERROR;
    }

    // Send a request to the API for the metrics
    char *request = "GET /metrics HTTP/1.1\r\nHost: api.example.com\r\n\r\n";
    int ret = send(sock, request, strlen(request), 0);
    if (ret < 0) {
        return ERROR_NETWORK_ERROR;
    }

    // Receive the response from the API
    char *response = malloc(sizeof(char) * BUFFER_SIZE);
    ret = recv(sock, response, BUFFER_SIZE, 0);
    if (ret < 0) {
        return ERROR_NETWORK_ERROR;
    }

    // Parse the response and update the records with the metrics
    for (int i = 0; i < arrays->num_records; i++) {
        Record *record = arrays->records[i];
        char *metric = strstr(response, "temperature");
        if (metric == NULL) {
            return ERROR_API_RATE_LIMIT_EXCEEDED;
        }
        record->temperature_reading += atoi(metric);
        metric = strstr(response, "energy_consumption");
        if (metric == NULL) {
            return ERROR_CONNECTION_INTERRUPTED;
        }
        record->energy_consumption += atof(metric);
    }

    // Return success
    return ERROR_SUCCESS;
}

// Retrieve the temperature reading for a given record
int retrieveTemperature(Arrays *arrays, int index) {
    if (index < 0 || index >= arrays->num_records) {
        return -1;
    }
    Record *record = arrays->records[index];
    return record->temperature_reading;
}

// Retrieve the energy consumption for a given record
double retrieveEnergyConsumption(Arrays *arrays, int index) {
    if (index < 0 || index >= arrays->num_records) {
        return -1.0;
    }
    Record *record = arrays->records[index];
    return record->energy_consumption;
}

