int storeCertificatePEM(long key, const char* pem) {
    // Check if the input parameters are valid
    if (!pem || strlen(pem) == 0) {
        logError("Missing certificate PEM");
        return -1;
    }

    // Lock the mutex to prevent concurrent access from multiple threads
    pthread_mutex_lock(&lock);

    // Allocate memory for the new certificate using a memory pool
    char* new_pem = allocateMemory(strlen(pem) + 1);
    if (!new_pem) {
        logError("Failed to allocate memory for certificate PEM");
        return -1;
    }
    strcpy(new_pem, pem);

    // Check if the key already exists in the store and return an error if so
    for (int i = 0; i < MAX_CERTIFICATES; ++i) {
        if (certificate_store[i].key == key) {
            logError("Certificate with key %d already exists", key);
            free(new_pem);
            return -1;
        }
    }

    // Store the new certificate in the store and update the offset array
    for (int i = 0; i < MAX_CERTIFICATES; ++i) {
        if (certificate_store[i].key == 0) {
            certificate_store[i].key = key;
            certificate_store[i].pem = new_pem;
            key_offsets[i].key = key;
            key_offsets[i].offset = i * sizeof(struct Certificate);
            break;
        }
    }

    // Unlock the mutex to allow concurrent access from multiple threads
    pthread_mutex_unlock(&lock);

    return 0;
}

int retrieveCertificatePEM(long key, char* buffer) {
