    if (!buffer || strlen(buffer) == 0) {
        logError("Missing output buffer");
        return -1;
    }

    // Lock the mutex to prevent concurrent access from multiple threads
    pthread_mutex_lock(&lock);

    // Find the index of the certificate with the specified key in the store
    int index = -1;
    for (int i = 0; i < MAX_CERTIFICATES; ++i) {
        if (certificate_store[i].key == key) {
            index = i;
            break;
        }
    }

    // Return an error if the certificate does not exist in the store
    if (index == -1) {
        logError("Certificate with key %d does not exist", key);
        return -1;
    }

    // Copy the PEM representation of the certificate to the output buffer
    strcpy(buffer, certificate_store[index].pem);

    // Unlock the mutex to allow concurrent access from multiple threads
    pthread_mutex_unlock(&lock);

    return 0;
}

int generateUniqueKey() {
    // Generate a random key using OpenSSL's RAND_bytes function
    unsigned char buffer[sizeof(long)];
    int ret = RAND_bytes(buffer, sizeof(long));
    if (ret != 1) {
        logError("Failed to generate random bytes: %d", ret);
        return -1;
    }
    long key = *((long*) buffer);

    // Check if the generated key already exists in the store and regenerate a new key if so
    for (int i = 0; i < MAX_CERTIFICATES; ++i) {
        if (certificate_store[i].key == key) {
            key = generateUniqueKey();
            break;
        }
    }

    return key;
}

int allocateArray(void* array, int size) {
    // Allocate memory for the specified array using a memory pool
    void** pool_ptr = &memory_pool;
    while (*pool_ptr < (unsigned char*) memory_pool + MEMORY_POOL_SIZE) {
        *(void**) pool_ptr += size;
        if ((void*) *pool_ptr >= array && (void*) *pool_ptr + size <= (void*) memory_pool + MEMORY_POOL_SIZE) {
            memcpy(*pool_ptr, array, size);
            return 0;
        }
    }

    logError("Failed to allocate memory for array");
    return -1;
}

