void read_input(int nrecords, int min_val, int max_val, int str_len) {
    // Allocate memory for the array of records
    Record* records = malloc(nrecords * sizeof(Record));
    assert(records != NULL);

    // Initialize each record with a random value within the specified range or string length
    for (int i = 0; i < nrecords; i++) {
        if (min_val == max_val) {
            records[i].num_type = 0;
            records[i].value.i = min_val;
        } else {
            records[i].num_type = 1;
            char* str = malloc(str_len + 1);
            assert(str != NULL);
            for (int j = 0; j < str_len; j++) {
                str[j] = 'a' + rand() % ('z' - 'a');
            }
            str[str_len] = '\0';
            records[i].value.s = str;
        }
    }

    // Filter the records based on specific criteria
    for (int i = 0; i < nrecords; i++) {
        if (records[i].num_type == 0 && records[i].value.i > min_val) {
            printf("Record %d: %d\n", i, records[i].value.i);
        } else if (records[i].num_type == 1 && strlen(records[i].value.s) > str_len) {
            printf("Record %d: %s\n", i, records[i].value.s);
        }
    }

    // Find and print the largest integer in the array of records if they are integers
    int max = INT_MIN;
    for (int i = 0; i < nrecords; i++) {
        if (records[i].num_type == 0 && records[i].value.i > max) {
            max = records[i].value.i;
        }
    }
    printf("Largest integer: %d\n", max);

    // Find and print the longest string in the array of records if they are strings
    char* longest = "";
    for (int i = 0; i < nrecords; i++) {
        if (records[i].num_type == 1 && strlen(records[i].value.s) > strlen(longest)) {
            longest = records[i].value.s;
        }
    }
    printf("Longest string: %s\n", longest);

    // Free the memory allocated for the array of records and the strings
    for (int i = 0; i < nrecords; i++) {
        if (records[i].num_type == 1) {
            free(records[i].value.s);
        }
    }
    free(records);
}

