const fs = require('fs');
const util = require('util');
const exec = util.promisify(require('child_process').exec);
const maxCacheSize = 100; // in MB
const cacheEvictionPolicy = 'least-recently-used'; // or 'random'
let cache = {};

async function executeCommand(command, args) {
  const startTime = Date.now();
  try {
    const result = await exec(command, args);
    if (result.stderr) {
      console.log(`[ERROR] Failed to execute command: ${command}`);
      console.log(`[ERROR] ${result.stderr}`);
      return null;
    }
    const endTime = Date.now();
    const executionTime = endTime - startTime;
    console.log(`[INFO] Executed command in ${executionTime} ms`);
    return result.stdout;
  } catch (error) {
    console.log(`[ERROR] Failed to execute command: ${command}`);
    console.log(error);
    return null;
  }
}

async function cacheCommand(command, args, result) {
  if (!result) {
    return;
  }
  const key = `${command}${args.join()}`;
  const value = result.stdout;
  console.log(`[INFO] Caching command: ${key} -> ${value}`);
  cache[key] = value;
  if (Object.keys(cache).length > maxCacheSize) {
    evictCache();
  }
}

async function evictCache() {
  const keysToEvict = Object.keys(cache).sort((a, b) => a - b);
  for (const key of keysToEvict) {
    delete cache[key];
    console.log(`[INFO] Evicted cached command: ${key}`);
  }
}

async function executeCachedCommand(command, args) {
  const key = `${command}${args.join()}`;
  if (cache[key]) {
    return cache[key];
  } else {
    const result = await executeCommand(command, args);
    await cacheCommand(command, args, result);
    return result;
  }
}

async function runCommands() {
  // Example commands to be executed:
  const commands = [
    ['ls', '-l'],
    ['pwd'],
    ['df -h'],
    ['echo "hello world"']
  ];

  for (const command of commands) {
    const args = command.slice(1);
    console.log(`[INFO] Executing command: ${command[0]} ${args.join(' ')}`);
    const result = await executeCachedCommand(command[0], args);
    if (result === null) {
      console.log(`[ERROR] Failed to execute command: ${command[0]} ${args.join(' ')}`);
    } else {
      console.log(`[INFO] Command executed successfully.`);
      console.log(result);
    }
  }
}
```
