#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <stdbool.h>

struct data {
    char array[10]; // custom data structure with a char array and an unsigned long timestamp
};

struct key {
    short key; // integer key for identifying data
};

struct value {
    double value; // floating point value to be stored
};

struct resourceManager {
    struct data *data; // pointer to the data structure
    struct key *keys; // pointer to the keys structure
    struct value *values; // pointer to the values structure
    size_t capacity; // current capacity of the resources
    size_t size; // current size of the resources
};

void resourceManagerInit(struct resourceManager *manager) {
    manager->data = NULL;
    manager->keys = NULL;
    manager->values = NULL;
    manager->capacity = 0;
    manager->size = 0;
}

bool resourceManagerAddData(struct resourceManager *manager, struct data *data) {
    if (manager->size == manager->capacity) {
        // resize the resources if necessary
        size_t newCapacity = manager->capacity ? manager->capacity * 2 : 10;
        void *newData = realloc(manager->data, sizeof(struct data) * newCapacity);
        void *newKeys = realloc(manager->keys, sizeof(struct key) * newCapacity);
        void *newValues = realloc(manager->values, sizeof(struct value) * newCapacity);
        if (newData == NULL || newKeys == NULL || newValues == NULL) {
            // allocation failure, handle gracefully
            return false;
        }
        manager->data = newData;
        manager->keys = newKeys;
        manager->values = newValues;
        manager->capacity = newCapacity;
    }

    manager->size++;
    manager->data[manager->size - 1] = *data;
    return true;
}

bool resourceManagerAddKey(struct resourceManager *manager, struct key *key) {
    if (manager->size == manager->capacity) {
        // resize the resources if necessary
        size_t newCapacity = manager->capacity ? manager->capacity * 2 : 10;
        void *newKeys = realloc(manager->keys, sizeof(struct key) * newCapacity);
        void *newValues = realloc(manager->values, sizeof(struct value) * newCapacity);
        if (newKeys == NULL || newValues == NULL) {
            // allocation failure, handle gracefully
            return false;
        }
        manager->keys = newKeys;
        manager->values = newValues;
        manager->capacity = newCapacity;
    }

    manager->size++;
    manager->keys[manager->size - 1] = *key;
    return true;
}

bool resourceManagerAddValue(struct resourceManager *manager, struct value *value) {
    if (manager->size == manager->capacity) {
        // resize the resources if necessary
        size_t newCapacity = manager->capacity ? manager->capacity * 2 : 10;
        void *newValues = realloc(manager->values, sizeof(struct value) * newCapacity);
        if (newValues == NULL) {
            // allocation failure, handle gracefully
            return false;
        }
        manager->values = newValues;
        manager->capacity = newCapacity;
    }

    manager->size++;
    manager->values[manager->size - 1] = *value;
    return true;
}

void resourceManagerFree(struct resourceManager *manager) {
    free(manager->data);
    free(manager->keys);
    free(manager->values);
}
