#include <pthread.h>

// Struct to represent a record
struct Record {
    int value;
    uint64_t timestamp;
    bool status;
};

// Enum for metadata tags
enum MetadataTag {
    TIMESTAMP,
    STATUS,
    NUM_METADATA_TAGS
};

// Struct to represent metadata
struct Metadata {
    uint64_t timestamp;
    bool status;
};

// Structure for a cache of allocated memory blocks
struct MemoryCache {
    void* block;
    size_t size;
};

// Define the maximum number of records and metadata tags
#define MAX_RECORDS 1000000
#define NUM_METADATA_TAGS (sizeof(MetadataTag) * CHAR_BIT)

// Global variables for memory management
static size_t total_memory = 0;
static size_t max_memory = SIZE_MAX;
static pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the memory cache and allocate memory for the components
void init(size_t num_records, size_t max_memory) {
    // Initialize the memory cache
    total_memory = 0;
    pthread_mutex_lock(&memory_lock);

    // Allocate memory for the list of offsets and the array of keys
    size_t num_offsets = sizeof(long) * num_records;
    size_t num_keys = sizeof(int) * num_records;
    void* offset_mem = malloc(num_offsets);
    void* key_mem = malloc(num_keys);

    // Check for memory allocation failures
    if (!offset_mem || !key_mem) {
        printf("Memory allocation failure\n");
        return;
    }

    // Allocate memory for the records and metadata
    size_t record_size = sizeof(struct Record);
    size_t num_records_per_metadata = (num_records + NUM_METADATA_TAGS - 1) / NUM_METADATA_TAGS;
    size_t num_metadatas = num_records_per_metadata * NUM_METADATA_TAGS;
    size_t metadata_size = sizeof(struct Metadata);
    void* record_mem = malloc(record_size * num_records_per_metadata);
    void* metadata_mem = malloc(metadata_size * num_metadatas);

    // Check for memory allocation failures
    if (!record_mem || !metadata_mem) {
        printf("Memory allocation failure\n");
        return;
    }

    // Initialize the cache and add the allocated memory blocks to it
    MemoryCache* cache = malloc(sizeof(MemoryCache));
    cache->block = offset_mem;
    cache->size = num_offsets;
    total_memory += num_offsets;
    memcpy(&cache->next, metadata_mem, sizeof(MemoryCache));

    // Add the remaining memory blocks to the cache
    MemoryCache* current = cache;
    while (current->next != NULL) {
        current = current->next;
    }
    current->block = record_mem;
    current->size = record_size * num_records_per_metadata;
    total_memory += current->size;
    memcpy(&current->next, key_mem, sizeof(MemoryCache));
    current->next = NULL;

    // Set the maximum memory limit
    if (max_memory == 0) {
        max_memory = SIZE_MAX;
    } else {
        max_memory = num_records * record_size;
    }

    pthread_mutex_unlock(&memory_lock);
}

// Function to allocate memory for a new record and update the cache
void* alloc(size_t size) {
    // Check if there is enough memory available
    if (total_memory + size > max_memory) {
        printf("Out of memory\n");
        return NULL;
    }

    // Acquire the memory lock and allocate memory for the record
    pthread_mutex_lock(&memory_lock);
    void* block = malloc(size);
    total_memory += size;

    // Check for memory allocation failures
    if (!block) {
        printf("Memory allocation failure\n");
        return NULL;
    }

    // Add the allocated memory block to the cache
    MemoryCache* current = malloc(sizeof(MemoryCache));
    current->block = block;
    current->size = size;

    // Check if there is a cache entry available for reuse
    if (cache != NULL) {
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = cache;
        cache = current;
    } else {
        cache = current;
    }

    pthread_mutex_unlock(&memory_lock);
    return block;
}

// Function to free memory for a record and update the cache
void free(void* block) {
    // Acquire the memory lock and remove the allocated memory block from the cache
    pthread_mutex_lock(&memory_lock);
    MemoryCache* current = cache;
    while (current->next != NULL) {
        if (current->block == block) {
            total_memory -= current->size;
            current->next = current->next->next;
            free(current);
            break;
        } else {
            current = current->next;
        }
    }
    pthread_mutex_unlock(&memory_lock);
}

// Function to generate random values for the keys and metadata
void rand_values(void* record, size_t num_records) {
    // Generate random values for the keys
    int* keys = (int*) malloc(sizeof(int) * num_records);
    for (size_t i = 0; i < num_records; i++) {
        keys[i] = rand() % INT_MAX;
    }

    // Generate random values for the metadata
    Metadata* metadatas = (Metadata*) malloc(sizeof(Metadata) * num_records);
    for (size_t i = 0; i < num_records; i++) {
        metadatas[i].timestamp = rand() % UINT64_MAX;
        metadatas[i].status = true;
    }
}

// Function to create a new record and update the cache
void create(size_t index) {
    // Allocate memory for the record
    struct Record* record = (struct Record*) alloc(sizeof(struct Record));
    if (!record) {
        printf("Memory allocation failure\n");
        return;
    }

    // Initialize the record with a random value and metadata
    rand_values(record, 1);
    record->value = rand() % INT_MAX;

    // Add the record to the cache
    MemoryCache* current = malloc(sizeof(MemoryCache));
    current->block = record;
    current->size = sizeof(struct Record);

    // Check if there is a cache entry available for reuse
    if (cache != NULL) {
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = cache;
        cache = current;
    } else {
        cache = current;
    }
}

// Function to update the value of a record and metadata
void update(size_t index, int value) {
    // Get the record from the cache
    MemoryCache* current = cache;
    while (current->next != NULL) {
        if (((struct Record*) current->block)->index == index) {
            ((struct Record*) current->block)->value = value;
            break;
        } else {
            current = current->next;
        }
    }
}

// Function to retrieve the value of a record and metadata
int get_value(size_t index) {
    // Get the record from the cache
    MemoryCache* current = cache;
    while (current->next != NULL) {
        if (((struct Record*) current->block)->index == index) {
            return ((struct Record*) current->block)->value;
        } else {
            current = current->next;
        }
    }
}
