        pthread_create(&threads[i], NULL, processRecordsThread, &numRecords);
    }
    // Wait for all threads to finish
    for (int i = 0; i < numThreads; ++i) {
        pthread_join(threads[i], NULL);
    }
    // Free the memory allocated to the thread arguments
    free(threads);
    return 0;
}
