            // Allocate memory for the first log entry
            entries = malloc(sizeof(log_entry));
            max_length = strlen(entries[num_entries].message);
        } else {
            // Reallocate memory for subsequent log entries to avoid fragmentation
            entries = realloc(entries, (num_entries + 1) * sizeof(log_entry));
            max_length = max(max_length, strlen(entries[num_entries].message));
        }

        // Set the severity level of each log entry based on a predefined mapping of message lengths
        if (strlen(entries[num_entries].message) < threshold) {
            entries[num_entries].severity = LOW;
