    }

    // Print the longest message in the log entries
    if (max_length > 0) {
        printf("Longest message: %s\n", entries[argc - 1].message);
    }

    // Free memory for the log entry array and any allocated messages
    for (int i = 0; i < num_entries; i++) {
        free(entries[i].message);
    }
    free(entries);
