        int longest = 0;
        for (int i = 1; i < num_entries; i++) {
            if (strlen(entries[i].message) > strlen(entries[longest].message)) {
                longest = i;
            }
        }

        // Print the longest message
        printf("Longest message: %s\n", entries[longest].message);
    }
}

