    time_t modified;
    unsigned char hash[16]; // Assuming a 128-bit hash value
};

// Function to initialize the array of file entries
void init_file_entries(struct file_entry **entries, int num_files) {
    for (int i = 0; i < num_files; i++) {
        struct file_entry *entry = malloc(sizeof(struct file_entry));
        if (!entry) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }
        entry->name = NULL;
        entry->size = 0;
        entry->modified = 0;
        memset(entry->hash, 0, sizeof(unsigned char) * 16);
        entries[i] = entry;
    }
}

// Function to extract metadata for each file entry
void extract_file_metadata(struct file_entry *entry, const char *path) {
    struct stat buf;
    if (stat(path, &buf)) {
        perror("stat");
        return;
    }
    entry->name = strdup(path);
    entry->size = buf.st_size;
    entry->modified = buf.st_mtime;
}

// Function to allocate memory safely and handle failure gracefully
void *safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    return ptr;
}

// Function to deallocate memory safely and handle failure gracefully
void safe_free(void *ptr) {
    if (ptr) {
        free(ptr);
    }
}

// Function to calculate the total size of all files in the array
long calculate_total_size(struct file_entry **entries, int num_files) {
    long total = 0;
    for (int i = 0; i < num_files; i++) {
        total += entries[i]->size;
    }
    return total;
}

// Function to print the total size of all files in the array
void print_total_size(struct file_entry **entries, int num_files) {
    long total = calculate_total_size(entries, num_files);
    printf("Total size: %ld\n", total);
}

// Function to filter file entries based on specified criteria
void filter_file_entries(struct file_entry **entries, int num_files, int size_range) {
    for (int i = 0; i < num_files; i++) {
        if ((size_range == 0 || entries[i]->size >= size_range) && (size_range == -1 || entries[i]->size <= size_range)) {
            // Remove the file entry from the array if it does not meet the criteria
            memmove(&entries[i], &entries[i + 1], sizeof(struct file_entry *) * (num_files - i));
        }
    }
}

// Function to sort the file entries based on their last modified timestamp
void sort_file_entries(struct file_entry **entries, int num_files) {
    for (int i = 0; i < num_files; i++) {
        for (int j = i + 1; j < num_files; j++) {
            if (entries[i]->modified > entries[j]->modified) {
                struct file_entry *temp = entries[i];
                entries[i] = entries[j];
                entries[j] = temp;
            }
        }
    }
}

// Function to display the file entries based on their last modified timestamp
void display_file_entries(struct file_entry **entries, int num_files) {
    for (int i = 0; i < num_files; i++) {
        printf("%s\n", entries[i]->name);
    }
}

// Function to handle file access permission issues without proceeding if necessary permissions are lacking
void handle_file_access(const char *path, struct file_entry *entry) {
    struct stat buf;
    if (stat(path, &buf)) {
        perror("stat");
        return;
    }
    entry->name = strdup(path);
    entry->size = buf.st_size;
    entry->modified = buf.st_mtime;
}

// Main function to process the dynamically allocated list of file paths from standard input
int main() {
    // Initialize an array of file entries
    struct file_entry **entries = NULL;
    int num_files = 0;

    // Extract metadata for each file entry and allocate memory safely
    while (scanf("%s", path) != EOF) {
        if (num_files == 10000) {
            fprintf(stderr, "Reached maximum number of files\n");
            break;
        }
        struct file_entry *entry = safe_malloc(sizeof(struct file_entry));
        if (!entry) {
            fprintf(stderr, "Memory allocation failed\n");
            return -1;
        }
        extract_file_metadata(entry, path);
        entries[num_files] = entry;
        num_files++;
    }

    // Filter file entries based on specified criteria and sort them based on their last modified timestamp
    int size_range = 0;
    if (scanf("%d", &size_range) != EOF) {
        filter_file_entries(entries, num_files, size_range);
        sort_file_entries(entries, num_files);
    }

    // Display the file entries based on their last modified timestamp
    display_file_entries(entries, num_files);

    // Deallocate memory safely and handle failure gracefully
    for (int i = 0; i < num_files; i++) {
        safe_free(entries[i]->name);
        free(entries[i]);
    }
    free(entries);
    return 0;
}
