        i++;
    }

    // Return an error if the record is not found
    if (i == arr->capacity) {
        return -1;
    }

    // Lock the mutex to prevent data races
    pthread_mutex_lock(&arr->mutex);

    // Update the record with the specified key
    arr->records[i].offset = arr->count * sizeof(struct record);
    arr->count++;

    // Unlock the mutex and return success
    pthread_mutex_unlock(&arr->mutex);
    return 0;
}

// Function to release all allocated memory and reset any global state
void cleanup(struct array *arr) {
    if (arr->count > 0) {
        free(arr->records);
    }

    pthread_mutex_destroy(&arr->mutex);
