        struct record *record = &(*records)[i];
        record->value = rand() % (max_value - min_value + 1) + min_value;
        record->buffer = (char *)malloc(sizeof(char) * 20); // Ensure buffer is large enough to hold the formatted integer value
        snprintf(record->buffer, 20, "%d", record->value);
    }
}

