// Define the structure to store elements in the collection
typedef struct element {
    double d;
    int i;
    char *s;
} element_t;

// Define the function to initialize a collection with n elements
void init_collection(element_t **elements, size_t n) {
    // Allocate memory for the array of elements
    *elements = (element_t *)malloc(n * sizeof(element_t));
    if (*elements == NULL) {
        fprintf(stderr, "Failed to allocate memory for collection\n");
        return;
    }

    // Initialize each element with a random value and unique identifier
    size_t i = 0;
    while (i < n) {
        (*elements)[i].d = ((double)rand() / RAND_MAX);
        (*elements)[i].i = rand() % 10;
        (*elements)[i].s = NULL;
        i++;
    }
}

// Define the function to add new elements to the collection
void add_element(element_t **elements, size_t n) {
    // Allocate memory for the new element
    element_t *new_element = (element_t *)malloc(sizeof(element_t));
    if (new_element == NULL) {
        fprintf(stderr, "Failed to allocate memory for new element\n");
        return;
    }

    // Initialize the new element with a random value and unique identifier
    new_element->d = ((double)rand() / RAND_MAX);
    new_element->i = rand() % 10;
    new_element->s = NULL;

    // Add the new element to the collection
    (*elements)[n].d = new_element->d;
    (*elements)[n].i = new_element->i;
    (*elements)[n].s = new_element->s;
}

// Define the function to sort the collection based on the double field
void sort_collection(element_t **elements, size_t n) {
    // Use a stable sorting algorithm (e.g., quicksort) to sort the collection
    for (size_t i = 0; i < n; i++) {
        for (size_t j = i + 1; j < n; j++) {
            if ((*elements)[i].d > (*elements)[j].d) {
                element_t temp = (*elements)[i];
                (*elements)[i] = (*elements)[j];
                (*elements)[j] = temp;
            }
        }
    }
}

// Define the function to free memory allocated for the collection
void free_collection(element_t **elements) {
    // Free each element in the collection
    size_t i = 0;
    while (i < n) {
        free((*elements)[i].s);
        i++;
    }

    // Free the array of elements
    free(*elements);
}

int main() {
    element_t *elements;
    size_t n = 10;
    init_collection(&elements, n);
    add_element(&elements, n + 1);
    sort_collection(&elements, n + 1);
    free_collection(&elements);
    return 0;
}
