void fetchData(int numOffsets, int numKeys, void* dataRetrievalCallback) {
    // Implement the mechanism for handling network latency and exponential backoff retries
    while (1) {
        try {
            // Fetch the initial data from the external API
            element_t* data = (element_t*)dataRetrievalCallback(numOffsets, numKeys);

            // Check for duplicates in the pre-existing dataset of records
            for (int i = 0; i < numOffsets * numKeys; i++) {
                element_t record = data[i];

                if (record.offset == 0 && record.key == 0) {
                    continue;
                }

                bool isDuplicate = false;

                for (int j = 0; j < i; j++) {
                    element_t existingRecord = data[j];

                    if (record.offset == existingRecord.offset && record.key == existingRecord.key) {
                        isDuplicate = true;
                        break;
                    }
                }

                if (isDuplicate) {
                    // Log the error and attempt retrieval again after a delay
                    printf("Duplicate record found! Retrying...\n");
