// JavaScript code to handle HTTP POST requests
function updateElement(elementId, value) {
    // Make an AJAX request to the server to update the element
    const xhr = new XMLHttpRequest();
    xhr.open("POST", "/update", true);
    xhr.setRequestHeader("Content-Type", "application/x-www-form-urlencoded");
    xhr.onload = function() {
        if (xhr.status === 200) {
            // Update the element in the UI
            const element = document.getElementById(elementId);
            element.innerHTML = value;
        } else {
            console.log("Error: unable to update element");
        }
    };
    xhr.send(`element_id=${elementId}&value=${value}`);
}
