    // If the element doesn't exist in the cache, update it and add it to the cache
    elements[num_elements] = malloc(sizeof(element_t));
    if (elements[num_elements] == NULL) {
        printf("Error: unable to allocate memory for new element\n");
        return;
    }
    elements[num_elements]->value = value;
    elements[num_elements]->id = atoi(elementId);
    recordSizes[numRecordSizes] = atoi(elementId);
    numRecordSizes++;
    if (numRecordSizes == MAX_RECORD_SIZE) {
        // If the cache is full, remove the oldest element and add a new one
        int oldestElement = 0;
        for (int i = 1; i < numRecordSizes; i++) {
            if (recordSizes[i] < recordSizes[oldestElement]) {
                oldestElement = i;
            }
        }
        elements[oldestElement] = NULL;
        free(elements[oldestElement]);
        num_elements--;
    }
}
```
