// Structure to store records
typedef struct Record {
    int field1;
    char* field2;
} Record;

// Function to process a record
void process_record(Record* rec) {
    // Compute the average of the last two fields
    int sum = rec->field1 + rec->field2;
    int avg = sum / 2;

    // Append the average value to the end of the line
    char buffer[100];
    sprintf(buffer, "%d", avg);
    strcat(rec->field2, buffer);

    // Print the record in a comma-separated format
    printf("%s, %s\n", rec->field1, rec->field2);
}

// Function to read and process text files concurrently
void read_and_process(const char* file) {
    // Open the file for reading
    int fd = open(file, O_RDONLY);
    if (fd == -1) {
        perror("Error opening file");
        return;
    }

    // Allocate memory for each line of the file
    char* line = malloc(sizeof(char) * 100);
    if (!line) {
        perror("Error allocating memory for line");
        close(fd);
        return;
    }

    // Read each line and process it
    while (read(fd, line, sizeof(char) * 100) > 0) {
        Record rec = parse_line(line);
        process_record(&rec);
    }

    // Close the file
    close(fd);
}

// Function to parse a line of text and extract values
Record parse_line(const char* line) {
    Record rec;
    sscanf(line, "%d,%s", &rec.field1, &rec.field2);
    return rec;
}

// Function to resolve DNS for a given hostname
void resolve_hostname(const char* hostname) {
    // Use the standard library functions to resolve the hostname
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        perror("Error resolving hostname");
        return;
    }

    // Print the IP address for the resolved hostname
    printf("%s has IP address %s\n", hostname, res->ai_addr->sa_data);
}

int main(int argc, char** argv) {
    // Check if enough arguments are provided
    if (argc < 2) {
        fprintf(stderr, "Usage: %s [text files]\n", argv[0]);
        return 1;
    }

    // Process each text file concurrently using a thread pool
    pthread_t* threads = malloc(sizeof(pthread_t) * (argc - 1));
    for (int i = 1; i < argc; i++) {
        pthread_create(&threads[i], NULL, read_and_process, argv[i]);
    }

    // Wait for all threads to complete before exiting
    for (int i = 0; i < argc - 1; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free the thread pool and return success
    free(threads);
    return 0;
}
