void populate_data(float *values, char **labels, struct Metric *metrics) {
    /* Input validation: Ensure values array size falls within allowed range (1-50,000) */
    if (values == NULL || labels == NULL || metrics == NULL) {
        return;
    }
    if (sizeof(values) / sizeof(*values) < 1 || sizeof(values) / sizeof(*values) > 50000) {
        fprintf(stderr, "Invalid values array size. Size must be between 1 and 50,000.\n");
        return;
    }
    if (sizeof(labels) / sizeof(*labels) < 1 || sizeof(labels) / sizeof(*labels) != (values - 1) / 2) {
        fprintf(stderr, "Invalid labels array size. Size must be half the size of the values array.\n");
        return;
    }

    /* Initialize the labels array with sequential strings starting from "Label0" */
    for (int i = 0; i < sizeof(labels) / sizeof(*labels); i++) {
        char label[16];
        sprintf(label, "Label%d", i);
        strcpy(labels[i], label);
    }

    /* Populate the values array with random floating-point numbers within specified range (-100.0 to 100.0) */
    srand(time(NULL));
    for (int i = 0; i < sizeof(values) / sizeof(*values); i++) {
        float value = rand() % 200 - 100;
        values[i] = value;
    }

    /* Populate the metrics array with random integers within specified range (0 to 1000) */
    for (int i = 0; i < sizeof(metrics) / sizeof(*metrics); i++) {
        int id = rand() % 1000;
        float *value = malloc(sizeof(float));
        *value = rand() % 200 - 100;
        metrics[i].id = id;
        metrics[i].value = value;
    }

    /* Memory management: Allocate memory for the labels array and populate it with sequential strings */
    char **labels_array = malloc(sizeof(char *) * sizeof(labels) / sizeof(*labels));
    if (labels_array == NULL) {
        fprintf(stderr, "Error allocating memory for labels array.\n");
        return;
    }
    for (int i = 0; i < sizeof(labels_array) / sizeof(*labels_array); i++) {
        char label[16];
        sprintf(label, "Label%d", i);
        strcpy(labels_array[i], label);
    }

    /* Memory management: Allocate memory for the values array and populate it with random floating-point numbers */
    float *values_array = malloc(sizeof(float) * sizeof(values) / sizeof(*values));
    if (values_array == NULL) {
        fprintf(stderr, "Error allocating memory for values array.\n");
        return;
    }
    for (int i = 0; i < sizeof(values_array) / sizeof(*values); i++) {
        float value = rand() % 200 - 100;
        values_array[i] = value;
    }

    /* Memory management: Allocate memory for the metrics array and populate it with random integers within specified range (0 to 1000) */
    struct Metric *metrics_array = malloc(sizeof(struct Metric) * sizeof(metrics) / sizeof(*metrics));
    if (metrics_array == NULL) {
        fprintf(stderr, "Error allocating memory for metrics array.\n");
        return;
    }
    for (int i = 0; i < sizeof(metrics_array) / sizeof(*metrics); i++) {
        int id = rand() % 1000;
        float *value = malloc(sizeof(float));
        *value = rand() % 200 - 100;
        metrics_array[i].id = id;
        metrics_array[i].value = value;
    }

    /* Memory management: Free memory for labels array, values array, and metrics array */
    free(labels_array);
    free(values_array);
    for (int i = 0; i < sizeof(metrics_array) / sizeof(*metrics); i++) {
        free(metrics_array[i].value);
    }
    free(metrics_array);
}

