// Define constants for maximum key and offset values
#define MAX_KEY ((1 << 15) - 1)
#define MIN_KEY (-(1 << 15))
#define MAX_OFFSET ((1LL << 63) - 1)
#define MIN_OFFSET (-(1LL << 63))

// Define a structure to represent a record in the data processing system
typedef struct {
    long *offset;
    int key;
    int *values;
} Record;

// Define a hash table to store records in the system
typedef struct {
    size_t capacity;
    size_t count;
    Record **records;
} HashTable;

// Define a function to initialize the hash table
void init_hash_table(HashTable *ht, size_t capacity) {
    ht->capacity = capacity;
    ht->count = 0;
    ht->records = (Record **)calloc(capacity, sizeof(Record *));
}

// Define a function to add a record to the hash table
void add_record(HashTable *ht, long offset, int key, int values[]) {
    // Check if the hash table is full before adding a new record
    if (ht->count == ht->capacity) {
        printf("Error: hash table is full\n");
        return;
    }

    // Create a new record and populate it with the given values
    Record *rec = (Record *)calloc(1, sizeof(Record));
    rec->offset = offset;
    rec->key = key;
    for (int i = 0; i < key; i++) {
        rec->values[i] = values[i];
    }

    // Insert the new record into the hash table
    ht->records[ht->count++] = rec;
}

// Define a function to retrieve a record from the hash table
Record *get_record(HashTable *ht, long offset) {
    // Iterate through the records in the hash table to find the one with the given offset
    for (size_t i = 0; i < ht->count; i++) {
        if (ht->records[i]->offset == offset) {
            return ht->records[i];
        }
    }

    // Return NULL if no record with the given offset is found
    return NULL;
}

// Define a function to delete a record from the hash table
void del_record(HashTable *ht, long offset) {
    // Iterate through the records in the hash table to find the one with the given offset
    for (size_t i = 0; i < ht->count; i++) {
        if (ht->records[i]->offset == offset) {
            free(ht->records[i]);
            ht->records[i] = NULL;
            break;
        }
    }
}

// Define a function to process a record in the hash table
void process_record(HashTable *ht, long offset) {
