    } else {
        printf("Error: no record found with offset %ld\n", offset);
    }
}

// Define a function to process all records in the hash table
void process_all_records(HashTable *ht) {
    // Iterate through each record in the hash table and process it
    for (size_t i = 0; i < ht->count; i++) {
        Record *rec = ht->records[i];
        process_record(ht, rec->offset);
    }
}

// Define a function to handle incoming data records and add them to the hash table
void handle_incoming_data(HashTable *ht, int key, long offset) {
    // Create an array of integers to store the record's values
    int values[key];

    // Initialize the values with random numbers between 0 and 1000
    for (int i = 0; i < key; i++) {
        values[i] = rand() % 1000;
    }

    // Add the record to the hash table
    add_record(ht, offset, key, values);
}

// Define a function to handle outgoing data records and retrieve them from the hash table
void handle_outgoing_data(HashTable *ht, long offset) {
    // Retrieve the record from the hash table with the given offset
    Record *rec = get_record(ht, offset);

    // Check if a record was found with the given offset
    if (rec != NULL) {
        // Process the record's values and perform any necessary operations
        for (int i = 0; i < rec->key; i++) {
            printf("Value %d: %d\n", i, rec->values[i]);
        }
    } else {
        printf("Error: no record found with offset %ld\n", offset);
    }
}

// Define a function to handle periodic background tasks and suggest optimization strategies
void handle_background_tasks(HashTable *ht) {
    // Analyze the data usage patterns in the hash table and suggest optimization strategies
    for (size_t i = 0; i < ht->count; i++) {
        Record *rec = ht->records[i];
        int max_value = -1;
        int min_value = INT_MAX;

        // Find the maximum and minimum values in the record's array of integers
        for (int j = 0; j < rec->key; j++) {
            if (rec->values[j] > max_value) {
                max_value = rec->values[j];
            }
            if (rec->values[j] < min_value) {
                min_value = rec->values[j];
            }
        }

        // Suggest an optimization strategy based on the maximum and minimum values
        if (max_value > 100 && min_value < -100) {
            printf("Optimization strategy: normalize record values\n");
        } else if (max_value > 50 && min_value < -50) {
            printf("Optimization strategy: scale record values\n");
        } else {
            printf("No optimization strategy suggested\n");
        }
    }
}

int main() {
