    HashTable ht;
    init_hash_table(&ht, 1000000);

    // Handle incoming data records and add them to the hash table
    while (1) {
        int key = rand() % 256 + 1;
        long offset = rand() % MAX_OFFSET + MIN_OFFSET;
        handle_incoming_data(&ht, key, offset);
    }

    // Handle outgoing data records and retrieve them from the hash table
    while (1) {
        long offset = rand() % MAX_OFFSET + MIN_OFFSET;
        handle_outgoing_data(&ht, offset);
    }

    // Handle periodic background tasks to analyze data usage patterns and suggest optimization strategies
    while (1) {
        handle_background_tasks(&ht);
    }
}
