// Define a record structure that contains an integer value and a reference count
typedef struct {
    int key;
    int value;
    int ref_count;
} Record;

// Define a linked list node for the records
typedef struct Node {
    Record *record;
    struct Node *next;
} Node;

// Define a hash table structure that contains a linked list of nodes and a hash function
typedef struct {
    Node **nodes;
    int size;
    int (*hash_function)(int key);
} HashTable;

// Create a new record with the given integer value and initial reference count
Record *new_record(int value) {
    Record *record = malloc(sizeof(Record));
    record->value = value;
    record->ref_count = 1;
    return record;
}

// Create a new hash table with the given size and hash function
HashTable *new_hashtable(int size, int (*hash_function)(int key)) {
    HashTable *hashtable = malloc(sizeof(HashTable));
    hashtable->nodes = malloc(size * sizeof(Node*));
    hashtable->size = size;
    hashtable->hash_function = hash_function;
    return hashtable;
}

// Insert a record into the hash table with the given key and value
void insert_record(HashTable *hashtable, int key, int value) {
    // Find the appropriate bucket for the record
    int bucket = hashtable->hash_function(key);
    Node *node = malloc(sizeof(Node));
    node->record = new_record(value);
    node->next = hashtable->nodes[bucket];
    hashtable->nodes[bucket] = node;
}

// Search for a record in the hash table with the given key
Record *search_record(HashTable *hashtable, int key) {
    // Find the appropriate bucket for the record
    int bucket = hashtable->hash_function(key);
    Node *node = hashtable->nodes[bucket];
    while (node != NULL) {
        if (node->record->key == key) {
            return node->record;
        }
        node = node->next;
    }
    return NULL;
}

// Increment the reference count of a record
void increment_reference(Record *record) {
    record->ref_count++;
}

// Decrement the reference count of a record and free it if necessary
void decrement_reference(Record *record) {
    record->ref_count--;
    if (record->ref_count == 0) {
        free(record);
    }
}

// Free all memory associated with the hash table
void free_hashtable(HashTable *hashtable) {
    for (int i = 0; i < hashtable->size; i++) {
        Node *node = hashtable->nodes[i];
        while (node != NULL) {
            Record *record = node->record;
            decrement_reference(record);
            node = node->next;
        }
    }
}
