// Add a record to the cache if it doesn't already exist
void add_to_cache(Cache* cache, struct Record* record) {
    // Check if the record already exists in the cache
    for (size_t i = 0; i < cache->count; i++) {
        if (cache->records[i]->offset == record->offset &&
            cache->records[i]->key == record->key) {
            return;
        }
    }

    // If the record doesn't exist, add it to the cache
    if (cache->count < cache->capacity) {
        cache->records = realloc(cache->records, sizeof(struct Record*) * (cache->count + 1));
        cache->records[cache->count] = record;
        cache->count++;
    }
}

// Remove a record from the cache if it exists
void remove_from_cache(Cache* cache, struct Record* record) {
    for (size_t i = 0; i < cache->count; i++) {
        if (cache->records[i]->offset == record->offset &&
