// Define the structure of a node in the data structure
struct node {
    double data;
    char* string;
    struct node* next;
};

// Initialize a new node with randomly generated data
void init_node(struct node** node) {
    *node = malloc(sizeof(struct node));
    if (*node == NULL) {
        perror("Failed to allocate memory for new node");
        return;
    }
    (*node)->data = rand() % 100;
    (*node)->string = malloc(256);
    if ((*node)->string == NULL) {
        perror("Failed to allocate memory for string data");
        free(*node);
        return;
    }
    strcpy((*node)->string, "Random String");
    (*node)->next = NULL;
}

// Free a node and its associated memory
void free_node(struct node** node) {
    if (*node != NULL) {
        free((*node)->string);
        free(*node);
        *node = NULL;
    }
}

// Add a new node to the end of the data structure
void add_node(struct node** head, struct node* node) {
    if (*head == NULL) {
        // If the list is empty, set the head to the new node
        *head = node;
    } else {
        // Otherwise, traverse the list until the end is reached and add the new node there
        struct node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }
}

// Remove a node from the data structure
void remove_node(struct node** head, struct node* node) {
    if (*head == NULL) {
        // If the list is empty, do nothing
        return;
    } else if (*head == node) {
        // If the head node is the one to be removed, set the new head to the next node
        *head = (*head)->next;
    } else {
        // Otherwise, traverse the list until the node to be removed is found and remove it
        struct node* current = *head;
        while (current->next != NULL && current->next != node) {
            current = current->next;
        }
        if (current->next == node) {
            current->next = node->next;
        } else {
            printf("Node not found in the list\n");
        }
    }
}

// Serialize a node to a binary file
void serialize_node(struct node* node, FILE* fp) {
    fwrite(&node->data, sizeof(double), 1, fp);
    fwrite(node->string, strlen(node->string), 1, fp);
}

// Deserialize a node from a binary file
void deserialize_node(struct node** node, FILE* fp) {
    *node = malloc(sizeof(struct node));
    if (*node == NULL) {
        perror("Failed to allocate memory for new node");
        return;
    }
    fread(&(*node)->data, sizeof(double), 1, fp);
    (*node)->string = malloc(256);
    if ((*node)->string == NULL) {
        perror("Failed to allocate memory for string data");
        free(*node);
        return;
    }
    fread((*node)->string, strlen((*node)->string), 1, fp);
}
