        free(nodes);
    }
}

// Function to handle concurrent access from multiple threads without causing data corruption or race conditions
void thread_safe_init_records(int num_records, int value_range) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    Node **nodes = malloc(num_records * sizeof(Node*));
    if (nodes == NULL) {
        printf("Error: Failed to allocate memory for linked list nodes\n");
        return;
    }

    int i = 0;
    while (i < num_records) {
        pthread_mutex_lock(&mutex);
        Record *record = malloc(sizeof(Record));
        if (record == NULL) {
            printf("Error: Failed to allocate memory for record %d\n", i);
            return;
        }

        // Generate a random value within the specified range
        int random_value = rand() % value_range + 1;

        // Initialize the record with the generated value and a string of 0s
        record->value = random_value;
        record->str = calloc(1, sizeof(char) * 20);

        // Create a new linked list node to store the record
        Node *node = malloc(sizeof(Node));
        if (node == NULL) {
            printf("Error: Failed to allocate memory for linked list node %d\n", i);
            return;
        }

        // Add the record to the linked list
        node->data = *record;
        node->next = head;
        head = node;

        pthread_mutex_unlock(&mutex);

        // Increment the index and move on to the next record
        i++;
    }

    if (nodes != NULL) {
        free(nodes);
    }
}

// Function to serialize the linked list into a binary file format
void serialize_records(Node *head, char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        printf("Error: Failed to open file %s for serialization\n", filename);
        return;
    }

    // Write the number of records in the linked list to the file
    int num_records = 0;
    Node *current = head;
    while (current != NULL) {
        num_records++;
        current = current->next;
    }
    fwrite(&num_records, sizeof(int), 1, file);

    // Write each record to the file
    current = head;
    while (current != NULL) {
        Record *record = &(current->data);
        fwrite(record, sizeof(Record), 1, file);
        current = current->next;
    }

    fclose(file);
}
