import json
import logging
import os
import shutil
import time
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime
from pathlib import Path

class DocumentManager:
    def __init__(self, directory):
        self.directory = directory
        self.cache = {}

    def get_file_size(self, file_path):
        return os.stat(file_path).st_size

    def get_document_info(self, document_id):
        return {
            "id": document_id,
            "name": f"{document_id}.json",
            "size": self.get_file_size(os.path.join(self.directory, f"{document_id}.json")),
            "last_modified": datetime.utcfromtimestamp(os.path.getmtime(os.path.join(self.directory, f"{document_id}.json"))).isoformat() + "Z"),
        }

    def get_documents(self):
        return [self.get_document_info(d) for d in os.listdir(self.directory)]

    def download_document(self, document_id, destination=None):
        if not destination:
            destination = self.directory
        shutil.copyfile(os.path.join(self.directory, f"{document_id}.json"), os.path.join(destination, f"{document_id}.json"))

    def upload_document(self, document_id, file_path):
        with open(file_path, "rb") as f:
            content = f.read()
        self.cache[document_id] = json.loads(content)
        with open(os.path.join(self.directory, f"{document_id}.json"), "wb") as f:
            f.write(content)

    def delete_document(self, document_id):
        os.remove(os.path.join(self.directory, f"{document_id}.json"))
        self.cache.pop(document_id, None)

    def get_cached_document(self, document_id):
        return self.cache.get(document_id)

    def set_cached_document(self, document_id, content):
        self.cache[document_id] = json.loads(content)

    def validate_document(self, document_id):
        if not os.path.exists(os.path.join(self.directory, f"{document_id}.json")):
            return False
        with open(os.path.join(self.directory, f"{document_id}.json"), "rb") as f:
            try:
                json.loads(f.read())
            except json.JSONDecodeError:
                return False
        return True

    def save_cached_document(self, document_id):
        with open(os.path.join(self.directory, f"{document_id}.json"), "wb") as f:
            f.write(json.dumps(self.cache[document_id]).encode())

    def backup_documents(self, interval):
        while True:
            time.sleep(interval)
            for document in os.listdir(self.directory):
                with open(os.path.join(self.directory, document), "rb") as f:
                    content = f.read()
                backup_file = f"{document}.bak"
                while os.path.exists(os.path.join(self.directory, backup_file)):
                    backup_file = f"{document}_{datetime.now().strftime('%Y-%m-%d-%H:%M:%S')}.bak"
                with open(os.path.join(self.directory, backup_file), "wb") as f:
                    f.write(content)

logging.basicConfig(level=logging.INFO)
document_manager = DocumentManager("./documents")

@app.route("/documents", methods=["GET"])
def get_documents():
    documents = document_manager.get_documents()
    return jsonify(documents)

@app.route("/documents/<string:document_id>", methods=["GET"])
def get_document(document_id):
    document = document_manager.get_cached_document(document_id)
    if not document:
        document = document_manager.download_document(document_id)
    return jsonify(document)

@app.route("/documents/<string:document_id>", methods=["POST"])
def upload_document(document_id):
    file_path = request.files["file"].read()
    document_manager.upload_document(document_id, file_path)
    return jsonify({"message": f"Document {document_id} uploaded successfully."})

@app.route("/documents/<string:document_id>", methods=["DELETE"])
def delete_document(document_id):
    document_manager.delete_document(document_id)
    return jsonify({"message": f"Document {document_id} deleted successfully."})
