    int i = 0;
    while (fgets(line, sizeof(line), csv)) {
        // Ignore empty lines or lines that start with a comment character
        if (strlen(line) == 0 || line[0] == '#') {
            continue;
        }

        // Parse the float value and identifier from the line
        char* id = strchr(line, ',');
        if (id == NULL) {
