        *value_end++ = 0;
        char identifier = id[0];

        // Generate a random string of the specified length
        int len = strtol(value_end, NULL, 10);
        if (len <= 0) {
            printf("Error: unable to generate item string\n");
            break;
        }
        char* string = malloc(sizeof(char) * len);
        if (string == NULL) {
            printf("Error: unable to allocate memory for item string\n");
            break;
        }
        memset(string, 0, len);
        srand((unsigned int)time(NULL));
        for (int j = 0; j < len; j++) {
            string[j] = 'A' + (rand() % ('Z' - 'A'));
        }

        // Store the item in the array
        items[i].value = value;
        items[i].id = identifier;
        items[i].string = string;
        i++;
    }

    // Close the CSV file and free any dynamically allocated memory
    fclose(csv);
    for (int j = 0; j < i; j++) {
        free(items[j].string);
    }
    free(items);
}

int main() {
    initialize_items("file.csv");
