// Data structure for storing metadata entries
typedef struct {
    int error_code;
    bool status_flag;
} metadata_t;

// Data structure for storing record entries
typedef struct {
    long offset;
    int key;
    metadata_t metadata;
    time_t timestamp;
} record_t;

// Linked list node for storing records
typedef struct linked_list_node {
    record_t *record;
    struct linked_list_node *next;
} linked_list_node_t;

// Global variables for managing the memory pool and the linked list
static metadata_t *metadata_pool = NULL;
static linked_list_node_t *linked_list_head = NULL;
static pthread_mutex_t mutex;

// Function for dynamically managing memory for the data structure
void dynamic_memory_manager(record_t *record) {
    // Acquire a lock on the linked list and metadata pool
    pthread_mutex_lock(&mutex);

    // If the record is NULL, allocate a new record in the metadata pool
    if (record == NULL) {
        metadata_pool = realloc(metadata_pool, sizeof(metadata_t));
        record = (record_t *)malloc(sizeof(record_t));
        record->offset = 0;
        record->key = 0;
        record->metadata = metadata_pool[0];
        record->timestamp = time(NULL);
    }

    // If the record is not NULL, add it to the linked list
    else {
        linked_list_node_t *new_node = (linked_list_node_t *)malloc(sizeof(linked_list_node_t));
        new_node->record = record;
        new_node->next = NULL;
        if (linked_list_head == NULL) {
            linked_list_head = new_node;
        } else {
            linked_list_node_t *current = linked_list_head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = new_node;
        }
    }

    // Release the lock on the linked list and metadata pool
    pthread_mutex_unlock(&mutex);
}

// Function for searching a record by its key in constant average time complexity
record_t *search_record(int key) {
    pthread_mutex_lock(&mutex);
    linked_list_node_t *current = linked_list_head;
    while (current != NULL) {
        if (current->record->key == key) {
            // Return the record found
            record_t *record = current->record;
            pthread_mutex_unlock(&mutex);
            return record;
        }
        current = current->next;
    }
    // If no record was found, return NULL
    pthread_mutex_unlock(&mutex);
    return NULL;
}

// Function for updating a record's value based on its key, ensuring thread safety and atomicity
void update_record(int key, void *value) {
    // Acquire a lock on the linked list
    pthread_mutex_lock(&mutex);

    // Search for the record with the given key
    linked_list_node_t *current = linked_list_head;
    while (current != NULL) {
        if (current->record->key == key) {
            current->record->value = value;
            break;
        }
        current = current->next;
    }

    // Release the lock on the linked list
    pthread_mutex_unlock(&mutex);
}
```
