                "required": ["title", "description"]
            }
        }
        validate(instance=payload, schema=schema)
        return payload
    except ValidationError as e:
        raise HTTPException(status_code=400, detail="Invalid JSON payload") from e

def upload_document(session: Session, user_id: int, document: dict):
    try:
        doc = Document(user_id=user_id, content=document)
        session.add(doc)
        session.commit()
        return jsonify({"message": "Document uploaded successfully"}), 201
    except IntegrityError as e:
        raise HTTPException(status_code=400, detail="Invalid document") from e

def download_document(session: Session, user_id: int, doc_id: str):
    try:
        doc = session.query(Document).filter(Document.user_id == user_id, Document.id == doc_id).first()
        if not doc:
            raise HTTPException(status_code=404, detail="Document not found")
        return jsonify({"content": doc.content})
    except IntegrityError as e:
        raise HTTPException(status_code=500, detail="Internal server error") from e

def delete_document(session: Session, user_id: int, doc_id: str):
    try:
        doc = session.query(Document).filter(Document.user_id == user_id, Document.id == doc_id).first()
        if not doc:
            raise HTTPException(status_code=404, detail="Document not found")
        session.delete(doc)
        session.commit()
        return jsonify({"message": "Document deleted successfully"}), 200
    except IntegrityError as e:
        raise HTTPException(status_code=500, detail="Internal server error") from e

@app.post("/documents/upload", status_code=201)
def upload_document():
    payload = validate_json(request.json())
    user_id = request.args.get("user_id")
    document = payload["file"]
    with Session() as session:
        return upload_document(session, user_id, document)

@app.get("/documents/download", status_code=200)
def download_document():
    doc_id = request.args.get("doc_id")
    user_id = request.args.get("user_id")
    with Session() as session:
        return download_document(session, user_id, doc_id)

@app.delete("/documents/delete", status_code=200)
def delete_document():
    doc_id = request.args.get("doc_id")
    user_id = request.args.get("user_id")
    with Session() as session:
        return delete_document(session, user_id, doc_id)
```
