// Function to handle concurrent access from multiple threads using synchronization mechanisms
void* thread_safe(void* (*func)(void*), void* arg) {
  // Check if input parameters are valid
  if (!func || !arg) {
    return NULL;
  }

  // Initialize mutex and condition variable for synchronizing threads
  pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
  pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

  // Declare function variables
  void* result = NULL;

  // Lock the mutex and wait for a signal from another thread
  pthread_mutex_lock(&mutex);
  while (!result) {
    pthread_cond_wait(&cond, &mutex);
  }

  // Unlock the mutex and call the function
  result = func(arg);

  return result;
}

// Function to handle logging of initialization process and any errors encountered
void log(int verbosity, const char* format, ...) {
  // Check if input parameters are valid
  if (verbosity < 0 || !format) {
    return;
  }

  // Initialize variable for the formatted string
  va_list args;
  va_start(args, format);

  // Log the formatted string to the console or file
  vfprintf(stderr, format, args);

  // Clean up variable and return
  va_end(args);
}
