// Memory management constants
#define MAX_MEMORY_USAGE 1024 * 1024 // 1 MB
#define MEMORY_POOL_SIZE 1024 * 1024 * 32 // 32 MB
#define CACHE_LINE_SIZE 64

// Sensor metadata structure
typedef struct {
    char device_id[32];
    uint32_t timestamp;
} sensor_metadata_t;

// Temperature reading structure
typedef struct {
    float temperature;
    sensor_metadata_t metadata;
} temperature_reading_t;

// Memory pool and slab allocator
struct memory_pool {
    size_t used_memory; // Used memory in bytes
    size_t total_memory; // Total memory allocated in bytes
    void* free_list[MEMORY_POOL_SIZE / CACHE_LINE_SIZE]; // Free list of memory blocks
};

// Memory management functions
void* allocate_memory(size_t size) {
    struct memory_pool* pool = get_memory_pool();

    // Check if the requested size exceeds the maximum memory usage limit
    if (size > MAX_MEMORY_USAGE) {
        errno = ENOMEM;
        return NULL;
    }

    // Allocate a new block of memory from the pool
    void* memory = malloc(size);
    if (!memory) {
        return NULL;
    }

    // Add the newly allocated memory to the free list
    pool->free_list[pool->used_memory++] = memory;

    // Update the total memory usage
    pool->total_memory += size;

    return memory;
}

void free_memory(void* memory) {
    struct memory_pool* pool = get_memory_pool();

    // Search for the specified memory block in the free list
    int i;
    for (i = 0; i < pool->used_memory && pool->free_list[i] != memory; ++i) {}

    if (i >= pool->used_memory) {
        return;
    }

    // Remove the memory block from the free list
    --pool->used_memory;
    for (int j = i; j < pool->used_memory; ++j) {
        pool->free_list[j] = pool->free_list[j + 1];
    }

    // Update the total memory usage
    pool->total_memory -= size;
}

// Concurrency management functions
void* lock(pthread_mutex_t* mutex) {
    int ret = pthread_mutex_lock(mutex);
    if (ret != 0) {
        return NULL;
    }

    return mutex;
}

