// Function to generate temperature readings based on a Gaussian distribution
float generate_temperature(float mean, float standard_deviation, sensor_metadata_t metadata) {
    // Generate a random number between 0 and 1
    double random_number = (double)rand() / RAND_MAX;

    // Calculate the value of sigma (standard deviation) squared
    double sigma_squared = standard_deviation * standard_deviation;

    // Calculate the exponent and return the result
    float temperature = exp(-(random_number * random_number) / (2 * sigma_squared)) * mean;

    return temperature;
}

// Function to initialize the temperature and sensor metadata tables
void initialize_tables() {
    // Initialize memory pool and slab allocator
    struct memory_pool* pool = get_memory_pool();

    // Allocate memory for the temperature and sensor metadata tables
    int i;
    for (i = 0; i < MEMORY_POOL_SIZE / CACHE_LINE_SIZE; ++i) {
        void* temperature_reading = allocate_memory(sizeof(temperature_reading_t));
        if (!temperature_reading) {
            break;
        }

        void* sensor_metadata = allocate_memory(sizeof(sensor_metadata_t));
        if (!sensor_metadata) {
            free_memory(temperature_reading);
            break;
        }

        // Initialize the temperature reading and sensor metadata
        ((temperature_reading_t*)temperature_reading)->temperature = generate_temperature(0, 1, *(sensor_metadata_t*)sensor_metadata);
    }
}
