// Entry structure for storing strings and their lengths
typedef struct {
    char *str;
    int len;
} entry_t;

// Initialization function to allocate memory for an array of entries
entry_t* init_entries(int num_entries) {
    // Allocate memory for the array of entries
    entry_t *entries = (entry_t*) malloc(num_entries * sizeof(entry_t));
    if (!entries) {
        perror("Failed to allocate memory for entries");
        return NULL;
    }

    // Initialize each entry with a default string and length
    for (int i = 0; i < num_entries; i++) {
        entries[i].str = "default";
        entries[i].len = strlen(entries[i].str);
    }

    return entries;
}

// String manipulation function to process incoming messages from the socket
entry_t* process_incoming_messages(int sock, int *num_entries) {
    // Read a message from the socket
    char buffer[BUFSIZ];
    read(sock, buffer, BUFSIZ);

    // Parse the message into an array of strings
    char **str_array = strtok(buffer, "\n");
    if (!str_array) {
        fprintf(stderr, "Failed to parse incoming message\n");
        return NULL;
    }

    // Allocate memory for the array of entries
    entry_t *entries = init_entries(num_entries);
    if (!entries) {
        perror("Failed to allocate memory for entries");
        return NULL;
    }

    // Populate each entry with a string and length
    int i = 0;
    while (str_array[i] != NULL && i < num_entries) {
        entries[i].str = strdup(str_array[i]);
        if (!entries[i].str) {
            perror("Failed to allocate memory for string");
            return NULL;
        }

        entries[i].len = strlen(str_array[i]);
        i++;
    }

    // Handle case where fewer strings are received than expected
    if (i < num_entries) {
        int j = 0;
        while (j < i) {
            free(entries[j].str);
            entries[j].str = NULL;
            j++;
        }

        free(entries);
        return NULL;
    }

    // Log the longest string across all processed entries
    int max_len = 0;
    char *longest_str = NULL;
    for (i = 0; i < num_entries; i++) {
        if (entries[i].len > max_len) {
            max_len = entries[i].len;
            longest_str = strdup(entries[i].str);
        }
    }

    // Clean up memory allocated for the string array
    for (int j = 0; j < num_entries; j++) {
        free(str_array[j]);
    }
    free(str_array);

    return entries;
}

// Memory management function to clean up memory allocated for an array of entries
void free_entries(entry_t *entries, int num_entries) {
    // Free each entry's string field and the memory allocated for the array
    for (int i = 0; i < num_entries; i++) {
        free(entries[i].str);
    }

    free(entries);
}

// Helper function to identify and log the longest string across all processed entries
void log_longest_string(entry_t *entries, int num_entries) {
    // Find the longest string in the array of entries
    int max_len = 0;
    char *longest_str = NULL;
    for (int i = 0; i < num_entries; i++) {
        if (entries[i].len > max_len) {
            max_len = entries[i].len;
            longest_str = strdup(entries[i].str);
        }
    }

    // Log the longest string
    printf("Longest string: %s\n", longest_str);

    // Clean up memory allocated for the longest string
    free(longest_str);
}
```
