public class RecordArray {
    private int numRecords;
    private int dataType; // 0 = numerical, 1 = string
    private Object[] records;

    public RecordArray(int numRecords, int dataType) {
        this.numRecords = numRecords;
        this.dataType = dataType;
        this.records = new Object[numRecords];
    }

    // Initialize the array with custom initialization criteria
    public void initialize(int initValue) {
        if (this.dataType == 0) {
            for (int i = 0; i < numRecords; i++) {
                records[i] = new NumericalRecord(initValue);
            }
        } else if (this.dataType == 1) {
            for (int i = 0; i < numRecords; i++) {
                records[i] = new StringRecord("");
            }
        }
    }

    // Add a record to the array with custom initialization criteria
    public void add(Object record) {
        if (this.dataType == 0) {
            ((NumericalRecord) record).setValue((int) initValue);
        } else if (this.dataType == 1) {
            ((StringRecord) record).setValue("");
        }
        records[numRecords++] = record;
    }

    // Get the number of records in the array
    public int getNumRecords() {
        return numRecords;
    }

    // Get a specific record from the array
    public Object getRecord(int index) {
        if (index < 0 || index >= numRecords) {
            throw new IndexOutOfBoundsException("Invalid index");
        }
        return records[index];
    }
}
