public class JsonParser {
    private static final int DEFAULT_CACHE_SIZE = 100;
    private Map<String, Object> cache = new HashMap<>();
    private List<Object> records = new ArrayList<>();

    public void parse(String json) throws IOException {
        if (cache.containsKey(json)) {
            return cache.get(json);
        }

        // Parse the JSON string and populate the records list
        ObjectMapper mapper = new ObjectMapper();
        JsonNode root = mapper.readTree(json);
        for (JsonNode node : root) {
            records.add(mapper.convertValue(node, Record.class));
        }

        // Cache the parsed JSON string for future use
        cache.put(json, records);
    }

    public List<Object> getRecords() {
        return records;
    }
}
