public class RecordFilter {
    private int threshold;
    private int maxLength;

    public RecordFilter(int threshold, int maxLength) {
        this.threshold = threshold;
        this.maxLength = maxLength;
    }

    // Filter records based on custom criteria
    public List<Object> filterRecords(List<Object> records) {
        List<Object> filteredRecords = new ArrayList<>();
        for (Object record : records) {
            if (record instanceof NumericalRecord && ((NumericalRecord) record).getValue() > threshold) {
                filteredRecords.add(record);
            } else if (record instanceof StringRecord && ((StringRecord) record).getLength() > maxLength) {
                filteredRecords.add(record);
            }
        }
        return filteredRecords;
    }
}
