```java
public class Logging {
    private static final String LOG_FILE = "log.txt";
    private static final boolean USE_LOGGING_LEVELS = true;

    public static void log(String message) {
        // Check system resources for memory and CPU constraints
        if (isSystemResourceLimited()) {
            throw new RuntimeException("System resource limitations reached");
        }

        // Buffer the log message to reduce the frequency of writes
        List<String> buffer = new ArrayList<>();
        buffer.add(message);

        // Write the buffered log messages to the log file in a background thread
        Thread writerThread = new Thread(() -> {
            try (BufferedWriter writer = new BufferedWriter(new FileWriter(LOG_FILE))) {
                for (String message : buffer) {
                    writer.write(message);
                    writer.newLine();
                }
            } catch (IOException e) {
                System.err.println("Error writing to log file");
            }
        });
        writerThread.start();
    }
}
```
