void process_lists(int *list_sizes, int num_lists, int threshold) {
    // Initialize an array of pointers to hold the largest integer from each list
    Record **records = malloc(sizeof(Record *) * num_lists);
    if (!records) {
        fprintf(stderr, "Error: Failed to allocate memory for records\n");
        return;
    }

    // Validate the input sizes and manage memory allocation failures gracefully
    for (int i = 0; i < num_lists; i++) {
        if (list_sizes[i] <= 0) {
            fprintf(stderr, "Error: List size must be positive\n");
            free(records);
            return;
        }
        records[i] = malloc(sizeof(Record) * list_sizes[i]);
        if (!records[i]) {
            fprintf(stderr, "Error: Failed to allocate memory for record %d\n", i);
            free(records);
            return;
        }
    }

    // Initialize the records with random values and validate the input sizes
    srand(time(NULL));
    for (int i = 0; i < num_lists; i++) {
        for (int j = 0; j < list_sizes[i]; j++) {
            records[i][j].value = rand() % 100;
        }
    }

    // Process the records in batches, up to the threshold value
    int num_records = 0;
    for (int i = 0; i < num_lists; i++) {
        num_records += list_sizes[i];
        if (num_records > threshold) {
            printf("Processing batch of %d records\n", threshold);
            process_batch(records, threshold);
            num_records -= threshold;
        }
    }

    // Process any remaining records in a final batch
    if (num_records > 0) {
        printf("Processing final batch of %d records\n", num_records);
        process_batch(records, num_records);
    }

    // Free the memory allocated for the array of pointers and the records themselves
