#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

// Structure to store coordinates (x and y)
struct point {
    double x;
    double y;
};

// Function to dynamically allocate memory for arrays
void allocate_arrays(int num_files, int max_size) {
    // Allocate memory for the three arrays
    double* doubles = (double*)malloc(num_files * max_size * sizeof(double));
    char** strings = (char**)malloc(num_files * max_size * sizeof(char*));
    struct point* points = (struct point*)malloc(num_files * max_size * sizeof(struct point));

    // Initialize the arrays
    for (int i = 0; i < num_files * max_size; ++i) {
        doubles[i] = NAN;
        strings[i] = NULL;
        points[i].x = NAN;
        points[i].y = NAN;
    }
}

// Function to read input from multiple CSV files and populate the arrays
void read_input(char* directory, int num_files, int max_size) {
    // Open the files in the directory
    FILE** files = (FILE**)malloc(num_files * sizeof(FILE*));
    for (int i = 0; i < num_files; ++i) {
        char file_name[1024];
        sprintf(file_name, "%s/%d.csv", directory, i);
        files[i] = fopen(file_name, "r");
    }

    // Read the input from each file and populate the arrays
    for (int i = 0; i < num_files; ++i) {
        char line[1024];
        while (fgets(line, sizeof(line), files[i])) {
            double* doubles_ptr = &doubles[i * max_size];
            char** strings_ptr = &strings[i * max_size];
            struct point* points_ptr = &points[i * max_size];

            // Parse the line and populate the arrays
            for (int j = 0; j < max_size; ++j) {
                if (!fscanf(files[i], "%lf %s", doubles_ptr++, strings_ptr++)) {
                    break;
                } else if (j == 0) {
                    points_ptr->x = doubles_ptr[-1];
                    points_ptr->y = doubles_ptr[-2];
                } else {
                    points_ptr++;
                }
            }
        }
    }
}

// Function to calculate the Euclidean distance between two points
double euclidean_distance(struct point p1, struct point p2) {
    return sqrt((p1.x - p2.x) * (p1.x - p2.x) + (p1.y - p2.y) * (p1.y - p2.y));
}

// Function to calculate the Euclidean distance between all pairs of points and store the results in a separate array
void calculate_distances(int num_files, int max_size) {
    // Allocate memory for the distances array
    double* distances = (double*)malloc(num_files * max_size * sizeof(double));

    // Initialize the distances array
    for (int i = 0; i < num_files * max_size; ++i) {
        distances[i] = NAN;
    }

    // Calculate the Euclidean distance between each pair of points and store the results in the distances array
    for (int i = 0; i < num_files * max_size - 1; ++i) {
        for (int j = i + 1; j < num_files * max_size; ++j) {
            distances[i] += euclidean_distance(points[i], points[j]);
        }
    }
}

// Function to free the memory allocated for the arrays
void free_arrays() {
    // Free the memory allocated for the three arrays
    free(doubles);
    free(strings);
    free(points);
