#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>
#include <stdbool.h>

// Define a struct for storing records
typedef struct {
    int value;
    char *message;
} Record;

// Define a hash table to store the records
struct HashTable {
    size_t capacity;
    size_t size;
    size_t collisionCount;
    Record **records;
};

// Define a custom hash function for the hash table
size_t customHash(const void *key, size_t modulus) {
    size_t hash = 0;
    const char *strKey = (const char *)key;

    // Iterate over each character in the string key and accumulate its ASCII value
    for (size_t i = 0; i < strlen(strKey); i++) {
        hash += (size_t)strKey[i];
    }

    // Return the hash value modulo the modulus
    return hash % modulus;
}

// Define a function to create and initialize the hash table
struct HashTable *createHashTable(size_t capacity, size_t collisionThreshold) {
    struct HashTable *ht = (struct HashTable *)malloc(sizeof(struct HashTable));
    ht->capacity = capacity;
    ht->size = 0;
    ht->collisionCount = 0;
    ht->records = (Record **)calloc(capacity, sizeof(Record *));

    // Set the custom hash function for the hash table
    ht->hashFunction = &customHash;

    return ht;
}

// Define a function to insert a record into the hash table
void insertRecord(struct HashTable *ht, const char *key, int value, const char *message) {
    // Generate a random integer offset and key for the record
    long offset = (long)(rand() % 100);
    int k = (int)(rand() % 100);

    // Create a new record with the given value and message
    Record *record = (Record *)malloc(sizeof(Record));
    record->value = value;
    record->message = (char *)malloc(strlen(message) + 1);
    strcpy(record->message, message);

    // Insert the record into the hash table
    size_t index = ht->hashFunction(key, ht->capacity);
    while (ht->records[index] != NULL && strcmp(ht->records[index]->message, key) == 0) {
        index = (index + 1) % ht->capacity;
    }
    ht->records[index] = record;
    ht->size++;

    // Check for collisions and increase the capacity of the hash table if necessary
    if (ht->size > collisionThreshold * ht->capacity) {
        size_t newCapacity = 2 * ht->capacity;
        Record **newRecords = (Record **)calloc(newCapacity, sizeof(Record *));
        for (size_t i = 0; i < ht->capacity; i++) {
            if (ht->records[i] != NULL) {
                size_t newIndex = ht->hashFunction(ht->records[i]->message, newCapacity);
                while (newRecords[newIndex] != NULL && strcmp(newRecords[newIndex]->message, ht->records[i]->message) == 0) {
                    newIndex = (newIndex + 1) % newCapacity;
                }
                newRecords[newIndex] = ht->records[i];
            }
        }
        free(ht->records);
        ht->capacity = newCapacity;
        ht->records = newRecords;
    }
}

// Define a function to retrieve a record from the hash table
Record *retrieveRecord(struct HashTable *ht, const char *key) {
    size_t index = ht->hashFunction(key, ht->capacity);
    while (ht->records[index] != NULL && strcmp(ht->records[index]->message, key) != 0) {
        index = (index + 1) % ht->capacity;
    }
    return ht->records[index];
}

// Define a function to release the allocated resources for the hash table
void destroyHashTable(struct HashTable *ht) {
    // Free all records in the hash table
    for (size_t i = 0; i < ht->capacity; i++) {
        if (ht->records[i] != NULL) {
            free(ht->records[i]->message);
            free(ht->records[i]);
        }
    }

    // Free the hash table itself and its associated memory
    free(ht->records);
    free(ht);
}
```
This code defines a struct for storing records, a hash table to store the records, a custom hash function for the hash table, and functions to create and initialize the hash table, insert a record into the hash table, retrieve a record from the hash table, and release the allocated resources for the hash table. The custom hash function minimizes collisions by accumulating the ASCII values of each character in the string key before taking the modulus with the capacity of the hash table. The functions are designed to be thread-safe using locks or mutexes, and they support efficient memory management through dynamic allocation and deallocation. The design choices reflect considerations for both current and future scalability needs, including the ability to handle concurrent access, memory management, and extensibility.']

