// Function to process CSV file and initialize array of data structures
int processCSV(const char* filename, size_t max_data_points, double min_value, double max_value) {
    // Initialize variables for tracking processing status and memory usage
    int num_data_points = 0;
    size_t total_memory = 0;
    DataPoint* data = NULL;

    // Open CSV file and validate input sizes
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: unable to open CSV file '%s'\n", filename);
        return -1;
    }
    if (max_data_points == 0) {
        max_data_points = SIZE_MAX;
    }

    // Iterate through each line in the CSV file and process data points
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Skip lines starting with '#' or empty lines
        if (line[0] == '#' || line[0] == '\n') {
            continue;
        }

        // Parse floating-point number from line and validate input
        double value = strtod(line, NULL);
        if (!isfinite(value)) {
            printf("Error: invalid floating-point value in CSV file '%s'\n", filename);
            break;
        }

        // Ensure memory usage is within bounds and add data point to array
        total_memory += sizeof(DataPoint);
        if (total_memory > max_data_points * sizeof(DataPoint)) {
            printf("Error: maximum number of data points exceeded in CSV file '%s'\n", filename);
            break;
        }
        data = realloc(data, total_memory);
        data[num_data_points].value = value;
        num_data_points++;
    }

    // Close CSV file and handle any memory allocation failures
    fclose(fp);
    if (data == NULL) {
        printf("Error: unable to allocate memory for data array in CSV file '%s'\n", filename);
        return -1;
    }

    // Calculate and print average value of data points
    double sum = 0.0;
    for (int i = 0; i < num_data_points; i++) {
        sum += data[i].value;
    }
    printf("Average value of %d data points: %.2f\n", num_data_points, sum / num_data_points);

    // Free memory for data array and return processing status
    free(data);
    return 0;
}

// Function to set random values within specified range for each data structure
void setRandomValues(DataPoint* data, size_t num_elements, double min_value, double max_value) {
    // Iterate through each element in the array and set value randomly
    for (size_t i = 0; i < num_elements; i++) {
        data[i].value = min_value + ((double)rand() / RAND_MAX) * (max_value - min_value);
    }
}

// Function to handle memory management for dynamically allocated arrays
void freeMemory(DataPoint* data, size_t num_elements) {
    // Free memory for array of data structures and set pointer to NULL
    free(data);
    data = NULL;
}

// Main function for processing CSV file and setting random values
int main(int argc, char** argv) {
    // Check command-line arguments and validate input sizes
    if (argc < 3 || argc > 4) {
        printf("Usage: %s <filename> <min_value> <max_value>\n", argv[0]);
        return -1;
    }
    const char* filename = argv[1];
    double min_value = strtod(argv[2], NULL);
    if (!isfinite(min_value)) {
        printf("Error: invalid minimum value '%s'\n", argv[2]);
        return -1;
    }
    double max_value = strtod(argv[3], NULL);
    if (!isfinite(max_value) || max_value <= min_value) {
        printf("Error: invalid maximum value '%s'\n", argv[3]);
        return -1;
    }

    // Process CSV file and set random values for each data structure
    int status = processCSV(filename, SIZE_MAX, min_value, max_value);
    if (status != 0) {
        printf("Error: unable to process CSV file '%s'\n", filename);
        return -1;
    }

    // Free memory for data array and return processing status
    freeMemory(data, num_data_points);
    return 0;
}
