// Function to dynamically allocate memory for the data structures
void *allocate_data_structures(int num_identifiers, int range) {
  // Allocate memory for the array of double precision floating-point numbers
  double* doubles = (double*)malloc(num_identifiers * sizeof(double));

  // Initialize the array with random values within the specified range
  for (int i = 0; i < num_identifiers; i++) {
    doubles[i] = (rand() % range) + 1;
  }

  // Allocate memory for the array of char strings representing unique identifiers
  char** ids = (char**)malloc(num_identifiers * sizeof(char*));

  // Generate unique identifiers within the specified range
  for (int i = 0; i < num_identifiers; i++) {
    ids[i] = (char*)malloc(10);
    sprintf(ids[i], "id%d", i + 1);
  }

  // Allocate memory for the array of struct elements containing a float and a bool
  struct* structs = (struct*)malloc(num_identifiers * sizeof(struct));

  // Initialize the array with random values within the specified range
  for (int i = 0; i < num_identifiers; i++) {
    structs[i].f = (rand() % range) + 1;
    structs[i].b = rand() % 2 == 0 ? true : false;
  }

  // Allocate memory for the array of record structures
  record* records = (record*)malloc(num_identifiers * sizeof(record));

  // Populate the record structures with descriptive strings assigned to each identifier
  for (int i = 0; i < num_identifiers; i++) {
    records[i].value = doubles[i];
    records[i].identifier = ids[i];
    records[i].s.f = structs[i].f;
    records[i].s.b = structs[i].b;
  }

  // Allocate memory for the balanced binary search tree (BST) to efficiently retrieve records based on their unique identifiers
  BST* bst = (BST*)malloc(sizeof(BST));
  bst->root = NULL;
  bst->size = 0;

  // Insert all the record structures into the BST
  for (int i = 0; i < num_identifiers; i++) {
    bst_insert(bst, records[i]);
  }

  return bst;
}

// Function to manage the data structures in a way that supports concurrent access from multiple threads, ensuring thread safety
void *manage_data_structures(BST* bst) {
  pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
  pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

  while (true) {
    // Acquire the lock on the BST
    pthread_mutex_lock(&mutex);

    // Check if there are any records to process
    if (bst->size > 0) {
      // Process the record with the largest value
      record* max = bst_max(bst);
      printf("Processing record with id %s and value %.2f\n", max->identifier, max->value);

      // Remove the processed record from the BST
      bst_remove(bst, max);
    } else {
      // Wait for new records to be inserted into the BST
      pthread_cond_wait(&cond, &mutex);
    }

    // Release the lock on the BST
    pthread_mutex_unlock(&mutex);
  }
}

// Function to resize the data structures if the number of identifiers exceeds the initial capacity
void *resize_data_structures(BST* bst, int new_capacity) {
  // Double the size of the arrays to accommodate the new records
  double* doubles = realloc(bst->doubles, new_capacity * sizeof(double));
  char** ids = realloc(bst->ids, new_capacity * sizeof(char*));
  struct* structs = realloc(bst->structs, new_capacity * sizeof(struct));
  record* records = realloc(bst->records, new_capacity * sizeof(record));

  // Update the pointers in the BST
  bst->doubles = doubles;
  bst->ids = ids;
  bst->structs = structs;
  bst->records = records;
}

// Function to release all resources allocated by the data structures
void free_data_structures(BST* bst) {
  // Free the memory allocated for the arrays of double precision floating-point numbers, char strings, struct elements, and record structures
  free(bst->doubles);
  free(bst->ids);
  free(bst->structs);
  free(bst->records);

  // Free the memory allocated for the balanced binary search tree (BST)
  free(bst);
}
