    timestamp timestamp;
    char* user_name;
    char* description;
} event_list;

void create_events(int num_events, int max_id, double* measurements, char** usernames, timestamp* timestamps, event** events, index** index) {
    // Allocate memory for the event list and the index
    *events = (event*)malloc(num_events * sizeof(event));
    *index = (index*)malloc(sizeof(index));

    // Initialize the event list and index
    int i;
    for (i = 0; i < num_events; ++i) {
        (*events)[i].id = rand() % max_id;
        (*events)[i].timestamp = timestamps[i];
        (*events)[i].user_name = usernames[rand() % 100000];
        (*events)[i].description = measurements[rand() % 100000] > 0 ? "event occurred" : "event did not occur";
    }

    // Initialize the index
    (*index)->count = num_events;
    (*index)->events = *events;
}

void destroy_events(event** events, index** index) {
    // Free memory allocated for the event list and the index
    free(*events);
    free(*index);
    *events = NULL;
    *index = NULL;
}

