record_t records[MAX_RECORDS];

int main(int argc, char** argv) {
    // Check input parameters
    if (argc < 3 || argc > 4) {
        printf("Usage: %s <number of records> <file names...>\n", argv[0]);
        return 1;
    }

    num_records = atoi(argv[1]);

    // Validate input parameters
    if (num_records > MAX_RECORDS) {
        printf("Number of records must be less than %d\n", MAX_RECORDS);
        return 2;
    }

    for (int i = 0; i < num_records; i++) {
        file_names[i] = argv[i + 2];
    }

    // Initialize semaphore and mutex
    if ((sem = sem_open("sem", O_CREAT, 0644, MAX_RECORDS)) == SEM_FAILED) {
        handle_error("sem_open", "Failed to create semaphore");
    }

    // Create and start threads for each file name
    pthread_t* threads = (pthread_t*) malloc(sizeof(pthread_t) * num_records);
    for (int i = 0; i < num_records; i++) {
        if (pthread_create(&threads[i], NULL, process_records, file_names[i]) != 0) {
            handle_error("pthread_create", "Failed to create thread");
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < num_records; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            handle_error("pthread_join", "Failed to join thread");
        }
    }

    // Clean up semaphore and mutex
    if (sem_close(sem) == -1) {
        handle_error("sem_close", "Failed to close semaphore");
    }
    free(threads);

    return 0;
}

void* process_records(void* arg) {
    // Get file name from argument and open file for reading
    char* file_name = (char*) arg;
    FILE* fp = fopen(file_name, "r");

    // Check if file opened successfully
    if (fp == NULL) {
        handle_error("fopen", "Failed to open file");
    }

    int num_fields;
    char buffer[BUFFER_SIZE];

    while ((num_fields = read_record(fp, records)) != 0) {
        // Parse record and compute average if necessary
        for (int i = 0; i < num_fields; i++) {
            parse_record(&records[i], &records[i]);
            compute_average(&records[i]);
        }

        // Write updated record to output file
        write_record(records, fp);
    }

    // Close file and return
    fclose(fp);
    pthread_exit(NULL);
}

int read_record(FILE* fp, record_t* record) {
    char buffer[BUFFER_SIZE];
    size_t len = 0;
    while ((len = getline(&buffer, &BUFFER_SIZE, fp)) > 0) {
        if (buffer[len - 1] == '\n') {
            buffer[--len] = '\0';
        }
        break;
    }

    // Check for EOF or error
    if (len == 0 || len == -1) {
        return 0;
    }

    // Parse record and store in `record`
    char* data = buffer;
    size_t fields[MAX_FIELDS];
    int field_index = 0;
    while (*data != '\0') {
        if (*data == ',' || *data == '\n') {
            *data++ = '\0';
            fields[field_index++] = strlen(fields);
        } else {
            data++;
        }
    }

    return field_index;
}

int parse_record(char* record, record_t* fields) {
    char* data = record;
    size_t len = 0;
    while (*data != '\0') {
        if (*data == ',' || *data == '\n') {
            *data++ = '\0';
            len++;
        } else {
            data++;
        }
    }

    // Check for invalid record format
    if (len % 2 != 0) {
        return -1;
    }

    int field_index = 0;
    while (*data != '\n') {
        if (field_index == MAX_FIELDS) {
            break;
        }
        if (*data == ',' || *data == '\0') {
            data++;
            continue;
        } else if (*data == 'i' && *(data + 1) == ':') {
            // Parse integer field
            int num = atoi(++data);
            fields[field_index].num.value = num;
            data += strlen(data);
        } else if (*data == 's' && *(data + 1) == ':') {
            // Parse string field
            string_t* str = &fields[field_index].str;
            data += 2;
            len = strlen(data);
            if ((str->data = malloc(len + 1)) == NULL) {
                handle_error("malloc", "Failed to allocate memory for string");
            }
            strncpy(str->data, data, len);
            str->len = len;
            data += len;
        } else {
            return -1;
        }
        field_index++;
    }

    return 0;
}

void compute_average(record_t* record) {
    // Compute average of last two fields if necessary
    size_t num_fields = record->len / sizeof(field_data_t);
    if (num_fields < 2) {
        return;
    }

    field_data_t* data1 = &record->fields[num_fields - 2];
    field_data_t* data2 = &record->fields[num_fields - 1];
    if (data1->num.value == 0 || data2->num.value == 0) {
        // Use average of last field and zero as the average if any of the values is zero
        record->fields[num_fields].num.value = (data1->num.value + data2->num.value) / 2;
    } else {
        record->fields[num_fields].num.value = (data1->num.value + data2->num.value) / 2;
    }
}

int write_record(record_t* record, FILE* fp) {
    // Write updated record to output file
    size_t len = sizeof(field_data_t) * (record->len + 1);
    char* buffer = malloc(len);
    if (buffer == NULL) {
        handle_error("malloc", "Failed to allocate memory for record");
    }

    // Write record to output file
    field_data_t* data = record->fields;
    int i = 0;
    while (*data != '\0') {
        if (i == MAX_FIELDS) {
            break;
        }
        if (*data == 's' && *(data + 1) == ':') {
            // Write string field
            string_t* str = &data->str;
            int str_len = str->len;
            buffer[i++] = 's';
            buffer[i++] = ':';
            memcpy(&buffer[i], str->data, str_len);
            i += str_len;
        } else {
            // Write integer field
            int num = data->num.value;
            snprintf(&buffer[i], len - i, "%d", num);
            i += snprintf(&buffer[i], len - i, "%d", num);
        }
        data++;
    }
    buffer[i] = '\n';

    fputs(buffer, fp);
    free(buffer);

    return 0;
}

int resolve_hostname(const char* hostname, u_char addr[]) {
    // Use standard library functions to perform DNS resolution
    struct addrinfo hints = {0};
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    struct addrinfo* result = NULL;
    if (getaddrinfo(hostname, NULL, &hints, &result) != 0) {
        handle_error("getaddrinfo", "Failed to resolve hostname");
    }
    memcpy(addr, result->ai_addr->sa_data + 2, IPV4_ADDR_LEN);
    freeaddrinfo(result);

    return 0;
}

void handle_error(const char* func, const char* msg) {
    perror(func);
    printf("Error: %s\n", msg);
    exit(EXIT_FAILURE);
}
