DirectoryNode* create_directory(const char* directory_name) {
    DirectoryNode* new_directory = malloc(sizeof(DirectoryNode));
    if (!new_directory) {
        printf("Error: Failed to allocate memory for the directory\n");
        return NULL;
    }
    new_directory->directory_name = strdup(directory_name);
    new_directory->num_files = 0;
    new_directory->num_directories = 0;
    new_directory->files = NULL;
    new_directory->directories = NULL;
    pthread_mutex_init(&new_directory->mutex, NULL);
    return new_directory;
}

void delete_directory(DirectoryNode* directory) {
    if (!directory) {
        printf("Error: Trying to delete a null pointer\n");
        return;
    }
    pthread_mutex_lock(&directory->mutex);
    DirectoryNode* current = directory;
    while (current != NULL) {
        FileNode* file = current->files;
        while (file != NULL) {
            FileNode* next = file->next;
            free(file->filename);
            free(file);
            file = next;
        }
        DirectoryNode* child_directory = current->directories;
        while (child_directory != NULL) {
            delete_directory(child_directory);
            child_directory = child_directory->next;
        }
        free(current->directory_name);
        free(current);
        current = directory->next;
    }
    pthread_mutex_unlock(&directory->mutex);
}

