        return -1;
    }
    new_directory->next = directory->directories;
    directory->directories = new_directory;
    directory->num_directories++;
    pthread_mutex_unlock(&directory->mutex);
    return 0;
}

int remove_file(DirectoryNode* directory, const char* filename) {
    if (!directory || !filename) {
        printf("Error: Trying to remove a null pointer\n");
        return -1;
    }
    pthread_mutex_lock(&directory->mutex);
    FileNode* current = directory->files;
    while (current != NULL) {
        if (strcmp(current->filename, filename) == 0) {
            directory->num_files--;
            FileNode* next = current->next;
            free(current->filename);
            free(current);
            current = next;
        } else {
            current = current->next;
        }
    }
    pthread_mutex_unlock(&directory->mutex);
    return 0;
}

int remove_directory(DirectoryNode* directory, const char* directory_name) {
    if (!directory || !directory_name) {
        printf("Error: Trying to remove a null pointer\n");
        return -1;
    }
    pthread_mutex_lock(&directory->mutex);
    DirectoryNode* current = directory->directories;
    while (current != NULL) {
        if (strcmp(current->directory_name, directory_name) == 0) {
            directory->num_directories--;
            DirectoryNode* next = current->next;
            delete_directory(current);
            current = next;
        } else {
            current = current->next;
        }
    }
    pthread_mutex_unlock(&directory->mutex);
    return 0;
}

int traverse_directory(DirectoryNode* directory, void (*callback)(const char* filename)) {
    if (!directory || !callback) {
        printf("Error: Trying to traverse a null pointer\n");
        return -1;
    }
    pthread_mutex_lock(&directory->mutex);
    FileNode* current = directory->files;
    while (current != NULL) {
        callback(current->filename);
        current = current->next;
    }
    DirectoryNode* child = directory->directories;
    while (child != NULL) {
        traverse_directory(child, callback);
        child = child->next;
    }
    pthread_mutex_unlock(&directory->mutex);
    return 0;
}
