#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <assert.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/ipc.h>
#include <sys/shm.h>

// Define the structure for the records
typedef struct {
    int value;
} record_t;

// Define the shared memory segment identifier
static int shmid;

// Define the lock for synchronizing access to the shared memory segment
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

/**
 * Initializes the dynamic array of records.
 * @param num_records The number of records to initialize.
 */
void init_array(int num_records) {
    // Allocate shared memory segment for the array of records
    shmid = shmget(IPC_PRIVATE, sizeof(record_t) * num_records, 0644 | IPC_CREAT);

    if (shmid < 0) {
        perror("Error creating shared memory segment");
        exit(EXIT_FAILURE);
    }
}

/**
 * Adds a new record to the dynamic array.
 * @param value The value of the new record.
 */
void add_record(int value) {
    // Lock the shared memory segment before updating it
    pthread_mutex_lock(&lock);

    // Get the pointer to the shared memory segment
    record_t* records = (record_t*)shmat(shmid, NULL, 0);

    // Check if the shared memory segment is valid
    if (records == (void*)-1) {
        perror("Error attaching to shared memory segment");
        exit(EXIT_FAILURE);
    }

    // Increment the number of records in the array
    records->value = value;

    // Unlock the shared memory segment after updating it
    pthread_mutex_unlock(&lock);
}

/**
 * Prints the smallest and largest integers in the dynamic array.
 */
void print_min_max() {
    // Lock the shared memory segment before reading from it
    pthread_mutex_lock(&lock);

    // Get the pointer to the shared memory segment
    record_t* records = (record_t*)shmat(shmid, NULL, 0);

    // Check if the shared memory segment is valid
    if (records == (void*)-1) {
        perror("Error attaching to shared memory segment");
        exit(EXIT_FAILURE);
    }

    // Find the smallest and largest integers in the array
    int min = INT_MAX;
    int max = INT_MIN;

    for (int i = 0; i < records->value; i++) {
        if (records[i].value < min) {
            min = records[i].value;
        }

        if (records[i].value > max) {
            max = records[i].value;
        }
    }

    // Print the smallest and largest integers
    printf("Smallest integer: %d\n", min);
    printf("Largest integer: %d\n", max);

    // Unlock the shared memory segment after reading from it
    pthread_mutex_unlock(&lock);
}

/**
 * Frees the dynamic array of records.
 */
void free_array() {
    // Lock the shared memory segment before updating it
    pthread_mutex_lock(&lock);

    // Get the pointer to the shared memory segment
    record_t* records = (record_t*)shmat(shmid, NULL, 0);

    // Check if the shared memory segment is valid
    if (records == (void*)-1) {
        perror("Error attaching to shared memory segment");
        exit(EXIT_FAILURE);
    }

    // Free the shared memory segment
    shmdt((char*)records);
    shmctl(shmid, IPC_RMID, NULL);

    // Unlock the shared memory segment after updating it
    pthread_mutex_unlock(&lock);
}

int main() {
    // Initialize the dynamic array of records
    init_array(10);

    // Add records to the array
    add_record(5);
    add_record(7);
    add_record(2);
    add_record(9);

    // Print the smallest and largest integers in the array
    print_min_max();

    // Free the dynamic array of records
    free_array();

    return 0;
}']

