#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>

// Define the structure for storing sensor data records
typedef struct {
    time_t timestamp; // Timestamp in seconds since epoch
    float temperature; // Temperature reading
} sensorRecord;

// Function to initialize the sensor data processing function
void initSensorDataProcessing(int initialCapacity, int maxSize) {
    // Allocate memory for the array of records
    sensorRecord* recordArray = (sensorRecord*)malloc(initialCapacity * sizeof(sensorRecord));

    // Initialize the record array with null values
    for (int i = 0; i < initialCapacity; i++) {
        recordArray[i].timestamp = -1;
        recordArray[i].temperature = NAN;
    }

    // Set the maximum size of the input list and the number of records to process
    maxSize = (maxSize > 0) ? maxSize : INT_MAX;
    int numRecords = initialCapacity;

    // Create a mutex for synchronizing access to the record array
    pthread_mutex_t* mutex = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t));
    pthread_mutex_init(mutex, NULL);

    // Initialize the average temperature tracker
    float avgTemp = 0;
    int numRecordsProcessed = 0;

    return;
}

// Function to insert a new sensor data record into the record array
void insertSensorDataRecord(sensorRecord* record) {
    // Acquire the mutex for synchronizing access to the record array
    pthread_mutex_lock(mutex);

    // Check if the record array is full and needs to be reallocated
    if (numRecords == maxSize) {
        numRecords = maxSize * 2;
        sensorRecord* newArray = (sensorRecord*)realloc(recordArray, numRecords * sizeof(sensorRecord));
        if (newArray != NULL) {
            recordArray = newArray;
        } else {
            // Handle error condition by reallocating memory or aborting the program
        }
    }

    // Update the timestamp and temperature in the next available slot in the record array
    int index = 0;
    while (index < numRecords && recordArray[index].timestamp != -1) {
        index++;
    }
    recordArray[index] = *record;

    // Update the average temperature tracker with the new record
    avgTemp += record->temperature;
    numRecordsProcessed++;

    // Release the mutex for synchronizing access to the record array
    pthread_mutex_unlock(mutex);
}

// Function to calculate and print the average temperature over the dataset
void printAverageTemperature() {
    // Acquire the mutex for synchronizing access to the record array
    pthread_mutex_lock(mutex);

    // Calculate the average temperature over the processed records
    float avgTemp = 0;
    if (numRecordsProcessed > 0) {
        avgTemp = avgTemp / numRecordsProcessed;
    }

    // Print the average temperature to standard output
    printf("Average temperature: %f\n", avgTemp);

    // Release the mutex for synchronizing access to the record array
    pthread_mutex_unlock(mutex);
}

// Function to handle dynamic input sizes for the arrays and records, and allow the user to define the range within which the temperature readings should fall
void processSensorDataStream(int initialCapacity, int maxSize, float minTemperature, float maxTemperature) {
    // Initialize the sensor data processing function with the specified parameters
    initSensorDataProcessing(initialCapacity, maxSize);

    // Set the minimum and maximum temperature values for filtering the record array
    float* minTemp = (float*)malloc(sizeof(float));
    *minTemp = minTemperature;
    float* maxTemp = (float*)malloc(sizeof(float));
    *maxTemp = maxTemperature;

    // Create a buffer for reading in the sensor data stream
    char* buffer = (char*)malloc(1024 * sizeof(char));

    // Loop until the end of the input file is reached
    while (!feof(stdin)) {
        // Read a line from the input stream and parse it as a sensor data record
        fgets(buffer, 1024, stdin);
        char* token = strtok(buffer, ",");
        time_t timestamp = (time_t)strtol(token, NULL, 10);
        token = strtok(NULL, "\n");
        float temperature = (float)strtod(token, NULL);

        // Check if the temperature reading falls within the specified range and insert it into the record array if so
        if (temperature >= *minTemp && temperature <= *maxTemp) {
            sensorRecord record;
            record.timestamp = timestamp;
            record.temperature = temperature;
            insertSensorDataRecord(&record);
        }
    }

    // Print the average temperature over the processed records
    printAverageTemperature();

    return;
}

// Main function to demonstrate the sensor data processing function
int main() {
    // Set the initial capacity and maximum size of the record array, as well as the minimum and maximum temperature values for filtering
    int initialCapacity = 100;
    int maxSize = 200;
