// Global variables for state management
int input_size;
int record_count;
int range_min;
int range_max;
int average_processing_time;
long long total_processing_time;
struct record {
    int value;
    struct sockaddr_in source;
} *records;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Initialize the function with input parameters
void initialize(int input_size, int record_count, int range_min, int range_max) {
    this->input_size = input_size;
    this->record_count = record_count;
    this->range_min = range_min;
    this->range_max = range_max;

    // Allocate memory for records array
    records = (struct record *) malloc(sizeof(struct record) * record_count);
}

// Generate random integer values within the specified range
int generate_random() {
    return rand() % (range_max - range_min + 1) + range_min;
}

// Add a new record to the records array
void add_record(struct sockaddr_in source, int value) {
    pthread_mutex_lock(&mutex);
    // Check if there is enough memory to allocate a new record
    if (input_size > 0) {
        records[record_count].source = source;
        records[record_count].value = value;
        input_size--;
        record_count++;
    } else {
        // If there is no more memory, free the oldest record and add a new one
        free(records);
        records = (struct record *) realloc(records, sizeof(struct record) * (record_count + 1));
        records[record_count].source = source;
        records[record_count].value = value;
        input_size--;
        record_count++;
    }
    pthread_mutex_unlock(&mutex);
}

// Process a network stream and add new records to the records array
void process_stream(int socket) {
    struct sockaddr_in source;
    int value;

    // Read data from the network stream
    while (1) {
        // Check if there is enough memory to allocate a new record
        if (input_size > 0) {
            // Receive data from the socket
            recvfrom(socket, &value, sizeof(int), 0, &source, NULL);
            add_record(source, value);
        } else {
            // If there is no more memory, free the oldest record and add a new one
            free(records);
            records = (struct record *) realloc(records, sizeof(struct record) * (record_count + 1));
            recvfrom(socket, &value, sizeof(int), 0, &source, NULL);
            add_record(source, value);
        }
    }
}

// Print the records array and calculate the average processing time
void print_records() {
    int i;
    double total = 0.0;
    pthread_mutex_lock(&mutex);
    for (i = 0; i < record_count; i++) {
        printf("%d: %d\n", records[i].source, records[i].value);
        total += records[i].value;
    }
    pthread_mutex_unlock(&mutex);
    average_processing_time = total / record_count;
}

// Free memory for the records array and reset state variables
void cleanup() {
    free(records);
    input_size = 0;
    record_count = 0;
    range_min = 0;
    range_max = 0;
    average_processing_time = 0.0;
    total_processing_time = 0;
}

// Main function that manages the records array and processes a network stream
void manage_records(int socket) {
    // Initialize state variables
    initialize(input_size, record_count, range_min, range_max);

    // Process the network stream in a separate thread
    pthread_t process_stream_thread;
    pthread_create(&process_stream_thread, NULL, (void *) process_stream, socket);

    // Print the records array and calculate the average processing time
    print_records();

    // Clean up state variables
    cleanup();
}

// Error handling function for network I/O operations
void error(const char *msg) {
    perror(msg);
    exit(0);
}

int main(int argc, char *argv[]) {
    // Check command line arguments
    if (argc < 5) {
        fprintf(stderr, "Usage: %s <input_size> <record_count> <range_min> <range_max>\n", argv[0]);
        return 1;
    }

    // Initialize state variables from command line arguments
    input_size = atoi(argv[1]);
    record_count = atoi(argv[2]);
    range_min = atoi(argv[3]);
    range_max = atoi(argv[4]);

    // Create a socket for communication with the network stream
    int socket;
    struct sockaddr_in server, client;
    if ((socket = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        error("Socket creation failed");
    }

    // Bind the socket to a specific IP and port
    memset(&server, 0, sizeof(server));
    server.sin_family = AF_INET;
    server.sin_addr.s_addr = INADDR_ANY;
    server.sin_port = htons(12345);
    if (bind(socket, (struct sockaddr *) &server, sizeof(server)) < 0) {
        error("Bind failed");
    }

    // Listen for incoming connections and process the stream in a separate thread
    while (1) {
        listen(socket, 3);
        struct sockaddr_in client;
        int client_size = sizeof(client);
        if ((accept(socket, (struct sockaddr *) &client, (socklen_t *) &client_size)) < 0) {
            error("Accept failed");
        }
        manage_records(socket);
    }

    return 0;
}']

