void init_records(Record** records, size_t size) {
    // Allocate memory for the array of records
    *records = (Record*)malloc(size * sizeof(Record));
    if (*records == NULL) {
        fprintf(stderr, "Error: Could not allocate memory for records\n");
        exit(EXIT_FAILURE);
    }

    // Initialize each record's value to a random integer within the specified range
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < size; i++) {
        (*records)[i].value = rand() % INT_MAX;
    }
}

// Function to generate random integers within a specified range
int generate_random_integer(int min, int max) {
    return min + (rand() % (max - min));
}

// Function to find and print the largest integer in an array of records
void find_largest_integer(Record* records, size_t size) {
    // Initialize the variable to store the largest value
    int largest = INT_MIN;

    // Loop through each record and compare its value to the current largest value
    for (size_t i = 0; i < size; i++) {
        if (records[i].value > largest) {
            largest = records[i].value;
        }
    }

    // Print the largest value
    printf("Largest integer: %d\n", largest);
}

// Function to free memory allocated for an array of records
void free_records(Record** records) {
    if (*records != NULL) {
        free(*records);
        *records = NULL;
    }
}

// Main function to handle the input and output of the program
int main() {
    // Declare variables for the array of records and its size
    Record* records = NULL;
    size_t size = 0;

    // Read the number of records from the user
    printf("Enter the number of records: ");
    scanf("%zu", &size);

    // Initialize the array of records with the given size
    init_records(&records, size);

    // Generate random integers within a specified range for each record's value
    for (size_t i = 0; i < size; i++) {
        records[i].value = generate_random_integer(1, 100);
    }

    // Find and print the largest integer in the array of records
    find_largest_integer(records, size);

    // Free memory allocated for the array of records
    free_records(&records);

    return 0;
}']

