void init_configs(int num_configs, int max_threshold) {
    // Allocate memory for the array of configurations
    config **configs = malloc(num_configs * sizeof(config*));
    if (configs == NULL) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        exit(1);
    }

    // Initialize each configuration structure with default values
