        if (configs[i] == NULL) {
            fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
            exit(1);
        }
        configs[i]->ip_address = "127.0.0.1";
        configs[i]->port = 80;
    }
}

// Function to parse the configuration files and fill the array of configurations
void parse_configs(char **filepaths, int num_files) {
    // Initialize an array of pointers to hold the file contents
    char **file_contents = malloc(num_files * sizeof(char*));
    if (file_contents == NULL) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        exit(1);
    }

    // Read the file contents and extract the IP addresses and ports
    for (int i = 0; i < num_files; i++) {
        FILE *fp = fopen(filepaths[i], "r");
        if (fp == NULL) {
            fprintf(stderr, "Error opening file %s: %s\n", filepaths[i], strerror(errno));
            exit(1);
        }

        // Read the file line by line and extract the IP addresses and ports
        while (!feof(fp)) {
            char line[256];
            fgets(line, 256, fp);
            if (strncmp(line, "IP=", 3) == 0) {
                // Extract the IP address from the line
                int ip_len = strcspn(line + 3, "\n");
                char *ip_address = malloc(ip_len + 1);
                if (ip_address == NULL) {
                    fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
                    exit(1);
                }
                strncpy(ip_address, line + 3, ip_len);
                ip_address[ip_len] = '\0';

                // Add the IP address to the array of configurations
                configs[i]->ip_address = ip_address;
            } else if (strncmp(line, "PORT=", 5) == 0) {
                // Extract the port number from the line
                int port_len = strcspn(line + 5, "\n");
                char *port = malloc(port_len + 1);
                if (port == NULL) {
                    fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
                    exit(1);
                }
                strncpy(port, line + 5, port_len);
                port[port_len] = '\0';

                // Add the port number to the array of configurations
                configs[i]->port = atoi(port);
            }
        }
        fclose(fp);
    }
}

// Function to release memory for the array of configurations
void free_configs(int num_configs) {
    // Release memory for each configuration structure
    for (int i = 0; i < num_configs; i++) {
        free(configs[i]->ip_address);
        configs[i]->port = 0;
        free(configs[i]);
    }
}

// Function to validate the input format and handle memory allocation failures gracefully
void validate_input(char **filepaths, int num_files) {
    // Validate the file paths and check if they exist
    for (int i = 0; i < num_files; i++) {
        if (!file_exists(filepaths[i])) {
            fprintf(stderr, "Error: File %s does not exist\n", filepaths[i]);
            exit(1);
        }
    }
}

// Function to read the file contents and extract the IP addresses and ports
void process_configs(char **filepaths, int num_files) {
    // Initialize the array of configurations with default values
    init_configs(num_files, 10);

    // Parse the configuration files and fill the array of configurations
    parse_configs(filepaths, num_files);

    // Release memory for the array of configurations when done
    free_configs(num_files);
}

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s num_configs file1 [file2 ...]\n", argv[0]);
        return 1;
    }
    int num_configs = atoi(argv[1]);
    char **filepaths = malloc((argc - 2) * sizeof(char*));
    for (int i = 0; i < argc - 2; i++) {
        filepaths[i] = argv[i + 2];
    }

    // Validate the input format and handle memory allocation failures gracefully
    validate_input(filepaths, num_configs);

    // Process the configuration files and fill the array of configurations
    process_configs(filepaths, num_configs);

    // Release memory for the array of file paths when done
    free(filepaths);
}
