    // Generate unique integer values for each record
    for (size_t i = 0; i < length; i++) {
        offsets[i] = rand() % MEM_POOL_SIZE;
        keys[i] = rand() % INT_MAX;

        if (keys[i] > max) {
            max = keys[i];
        } else if (keys[i] < min) {
            min = keys[i];
        }
    }

    return 0;
}

// Function to optimize memory allocation for the record array
int optimizeMemoryAllocation(long* offsets, int* keys, size_t length) {
    // Check input parameters
    if (offsets == NULL || keys == NULL || length > MAX_RECORD_COUNT) {
        fprintf(stderr, "Invalid input parameter\n");
