        }
    }
}

void deserialize_dataset(FILE* fp) {
    // Deserialize the double array
    int i;
    for (i = 0; i < num_data; i++) {
        fread(&double_array[i], sizeof(double), 1, fp);
    }

    // Deserialize the unsigned long array
