        char identifier[256];
        int value;
        if (!fread(identifier, sizeof(char), 256, fp)) {
            break;
        }
        data_entry_t* entry = (data_entry_t*)malloc(sizeof(data_entry_t));
        strcpy(entry->identifier, identifier);
        if (!fread(&value, sizeof(int), 1, fp)) {
            break;
        }
        entry->value = value;
        data_entries[i] = entry;
    }

    // Deserialize the metadata
