using namespace std;

class Item {
public:
    explicit Item(const string& type) : type_(type) {}
    virtual ~Item() = default;

    const string& getType() const { return type_; }
    void setValue(int value) { value_ = value; }
    void setValue(double value) { value_ = value; }
    void setValue(const string& value) { value_ = value; }
    int getValueAsInt() const { return value_; }
    double getValueAsDouble() const { return value_; }
    const string& getValueAsString() const { return value_; }

private:
    string type_;
    string value_;
};

class ItemCollection {
public:
    explicit ItemCollection(size_t size) : items_(size) {}
    virtual ~ItemCollection() = default;

    void addItem(const shared_ptr<Item>& item) { items_.push_back(item); }
    const vector<shared_ptr<Item>>& getItems() const { return items_; }
    void removeItem(size_t index) { items_.erase(items_.begin() + index); }
    size_t size() const { return items_.size(); }

private:
    vector<shared_ptr<Item>> items_;
};

class CommandExecutor {
public:
    explicit CommandExecutor(const string& command) : command_(command) {}
    virtual ~CommandExecutor() = default;

    void execute() const { system(command_.c_str()); }

private:
    string command_;
};

