        getline(stream_, line);
        return line;
    }

private:
    istream& stream_;
};

class Logger {
public:
    explicit Logger(const string& module) : module_(module) {}
    virtual ~Logger() = default;

    void log(const string& message) const { cout << "[" << module_ << "] " << message << endl; }

private:
    string module_;
};

class MemoryOptimizer {
public:
    explicit MemoryOptimizer(size_t maxMemoryUsage) : maxMemoryUsage_(maxMemoryUsage) {}
    virtual ~MemoryOptimizer() = default;

    void optimizeMemoryUsage() const {
        // TODO: Implement the memory optimization mechanism here.
    }

private:
    size_t maxMemoryUsage_;
};

class ItemManager {
public:
    explicit ItemManager(size_t initialSize) : collection_(initialSize), optimizer_(100 * 1024 * 1024) {}
    virtual ~ItemManager() = default;

    void initItems(const vector<string>& itemTypes, const vector<int>& ranges) {
        // Initialize the items with random values within specified ranges.
        for (size_t i = 0; i < collection_.getSize(); ++i) {
            shared_ptr<Item> item = make_shared<Item>(itemTypes[i % itemTypes.size()]);
            if (ranges[i] == -1) {
                // Initialize the value with a random integer within the range [-10, 10].
                int value = rand() % 20 - 10;
                item->setValue(value);
            } else {
                // Initialize the value with a random integer within the specified range.
                int value = rand() % ranges[i];
                item->setValue(value);
            }
            collection_.addItem(item);
        }
    }

    void filterItemsByType(const vector<string>& types) {
        // Filter the items based on their type.
        vector<shared_ptr<Item>> filteredItems;
        for (const shared_ptr<Item>& item : collection_.getItems()) {
            if (find(types.begin(), types.end(), item->getType()) != types.end()) {
                filteredItems.push_back(item);
            }
        }
        collection_.clear();
        for (const shared_ptr<Item>& item : filteredItems) {
            collection_.addItem(item);
        }
    }

    void filterItemsByValue(int minValue, int maxValue) {
        // Filter the items based on their value.
        vector<shared_ptr<Item>> filteredItems;
        for (const shared_ptr<Item>& item : collection_.getItems()) {
            if (item->getValueAsInt() >= minValue && item->getValueAsInt() <= maxValue) {
                filteredItems.push_back(item);
            }
        }
        collection_.clear();
        for (const shared_ptr<Item>& item : filteredItems) {
            collection_.addItem(item);
        }
    }

    void filterItemsByValue(double minValue, double maxValue) {
        // Filter the items based on their value.
        vector<shared_ptr<Item>> filteredItems;
        for (const shared_ptr<Item>& item : collection_.getItems()) {
            if (item->getValueAsDouble() >= minValue && item->getValueAsDouble() <= maxValue) {
                filteredItems.push_back(item);
            }
        }
        collection_.clear();
        for (const shared_ptr<Item>& item : filteredItems) {
            collection_.addItem(item);
        }
    }

    void executeCommand(const string& command, const string& outputFile) {
        // Execute the specified command and write its output to a file.
        FileDeleter deleter(outputFile);
        CommandExecutor executor(command);
        StringStreamReader reader;
        Logger logger("ItemManager");

        try {
            executor.execute();
            reader = StringStreamReader(ifstream(outputFile));
            string line;
            while (getline(reader, line)) {
                logger.log(line);
            }
        } catch (const std::exception& e) {
            logger.log("Error executing command: " + to_string(e.what()));
        }
    }

private:
    ItemCollection collection_;
    MemoryOptimizer optimizer_;
};

int main() {
    // Test the ItemManager class.
    ItemManager manager(10);

    // Initialize items with random values within specified ranges.
    vector<string> itemTypes = {"int", "double", "string"};
    vector<int> ranges = {-1, 5, -1};
    manager.initItems(itemTypes, ranges);

    // Filter the items based on their type.
    vector<string> types = {"int", "string"};
    manager.filterItemsByType(types);

    // Filter the items based on their value.
    int minValue = 5;
    int maxValue = 10;
    manager.filterItemsByValue(minValue, maxValue);

    // Execute a command and write its output to a file.
    string command = "echo 'Hello World!'";
    string outputFile = "output.txt";
    manager.executeCommand(command, outputFile);

    return 0;
}
