// Log entry structure
typedef struct {
    char* message;
    int severity_level;
    time_t timestamp;
} LogEntry;

// Function to insert log entries into the array, handling memory fragmentation and minimizing cache misses
void insert_log_entry(LogEntry* log_entries, size_t* current_size, size_t* max_size, const char* message, int severity_level) {
    // Check if we need to resize the array
    if (*current_size >= *max_size) {
        // Reallocate memory with a larger size
        *max_size = *max_size > 0 ? 2 * *max_size : 1;
        log_entries = realloc(log_entries, *max_size * sizeof(LogEntry));
    }

    // Insert the new entry
    LogEntry* entry = &log_entries[*current_size];
    entry->message = strdup(message);
    entry->severity_level = severity_level;
    entry->timestamp = time(NULL);

    // Increment the current size
    (*current_size)++;
}

// Function to iterate over all records, retrieving both the message and timestamp associated with each log entry
void iterate_log_entries(LogEntry* log_entries, size_t count) {
    for (int i = 0; i < count; i++) {
        LogEntry* entry = &log_entries[i];
        printf("%s: %d\n", entry->message, entry->severity_level);
    }
}

// Function to clear all allocated memory and free the array
void clear_log_entries(LogEntry* log_entries) {
    for (size_t i = 0; i < *max_size; i++) {
        LogEntry* entry = &log_entries[i];
        free(entry->message);
    }
    free(log_entries);
}

int main() {
    // Initialize the log entries array and allocate memory for 100,000 elements
    size_t current_size = 0;
    size_t max_size = 100000;
    LogEntry* log_entries = malloc(max_size * sizeof(LogEntry));

    // Set up the timestamp generation helper function
    time_t start_timestamp = time(NULL);
    void (*update_timestamp)(LogEntry*) = &update_timestamp_helper;

    // Initialize the average computation helper function
    int total_severity_level = 0;
    size_t valid_log_entries = 0;
    void (*compute_average_severity_level)() = &compute_average_severity_level_helper;

    // Process the log entries in batches of 10, handling network disconnections and resizing the array as needed
    while (true) {
        int count = 0;
        char* message;
        int severity_level;
        while ((message = get_next_log_entry(&severity_level)) != NULL && count < 10) {
            insert_log_entry(log_entries, &current_size, &max_size, message, severity_level);
            update_timestamp(log_entries + current_size - 1);
            total_severity_level += severity_level;
            valid_log_entries++;
            count++;
        }
        // Handle network disconnections and reconnections
        if (count > 0) {
            iterate_log_entries(log_entries, current_size);
            compute_average_severity_level();
        }
    }

    // Clear all allocated memory and free the array
    clear_log_entries(log_entries);

    return 0;
}

// Helper function to generate timestamps based on the current system time
void update_timestamp_helper(LogEntry* entry) {
    entry->timestamp = time(NULL);
}

// Helper function to compute and print the average severity level of all valid log entries
void compute_average_severity_level_helper() {
    if (valid_log_entries > 0) {
        printf("Average Severity Level: %d\n", total_severity_level / valid_log_entries);
    } else {
        printf("No log entries processed.\n");
    }
}
