// Metric sample structure
struct MetricSample {
    double value; // floating-point value
    time_t timestamp; // timestamp
    int category; // category identifier
};

// Function to dynamically allocate and manage memory for an array of metric samples
void* allocMetricSamples(size_t num_samples) {
    size_t struct_size = sizeof(struct MetricSample);
    size_t aligned_size = (struct_size + 64 - 1) / 64 * 64; // align to 64 bytes
    void* memory = malloc(num_samples * aligned_size);
    if (memory == NULL) {
        printf("Error: Could not allocate enough memory for %zu metric samples\n", num_samples);
        return NULL;
    }
    memset(memory, 0, num_samples * aligned_size); // initialize the memory to zero
    return memory;
}

// Function to insert individual metric samples
void insertMetricSample(struct MetricSample* sample) {
    struct MetricSample** samples = (struct MetricSample**)sample;
    size_t num_samples = 1;
    void* memory = allocMetricSamples(num_samples);
    if (memory == NULL) {
        return; // error: could not allocate enough memory for the sample
    }
    samples[0] = memory;
}

// Function to insert batch of metric samples
void insertBatchMetricSample(struct MetricSample* samples, size_t num_samples) {
    void* memory = allocMetricSamples(num_samples);
    if (memory == NULL) {
        return; // error: could not allocate enough memory for the sample
    }
    memcpy(memory, samples, num_samples * sizeof(struct MetricSample));
}

// Function to iterate over all records and retrieve value, timestamp, and category
void iterateMetricSamples(struct MetricSample* samples, size_t num_samples) {
    for (size_t i = 0; i < num_samples; i++) {
        printf("Value: %f\n", samples[i].value);
        printf("Timestamp: %lld\n", samples[i].timestamp);
        printf("Category: %d\n", samples[i].category);
    }
}

// Function to efficiently clear all allocated memory
void clearMetricSamples(struct MetricSample* samples, size_t num_samples) {
    free(samples);
}

// Helper function to generate timestamps based on the current system time
time_t getCurrentTimestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (time_t)ts.tv_sec;
}

// Helper function to initialize the `time_t` fields of the structures accordingly
void initMetricSamples(struct MetricSample* samples, size_t num_samples) {
    for (size_t i = 0; i < num_samples; i++) {
        samples[i].timestamp = getCurrentTimestamp();
    }
}

// Helper function to compute and print the mean, median, and standard deviation of the metric values
void computeStats(struct MetricSample* samples, size_t num_samples) {
    double sum = 0;
    for (size_t i = 0; i < num_samples; i++) {
        sum += samples[i].value;
    }
    double mean = sum / num_samples;
    printf("Mean: %f\n", mean);
    if (num_samples >= 2) {
        // compute median
        size_t median_index = (num_samples - 1) / 2;
        double median = samples[median_index].value;
        printf("Median: %f\n", median);
    }
    if (num_samples >= 3) {
        // compute standard deviation
        double variance = 0;
        for (size_t i = 0; i < num_samples; i++) {
            double diff = samples[i].value - mean;
            variance += diff * diff;
        }
        variance /= num_samples - 1;
        double stddev = sqrt(variance);
        printf("Standard Deviation: %f\n", stddev);
    }
}
