    long* offsets;
    Record** records;
};

struct ManageMemoryResult manageMemory(int n, int m) {
    struct ManageMemoryResult result = {NULL, NULL};

    // Allocate memory for offsets
    result.offsets = (long*) malloc(n * sizeof(long));
    if (!result.offsets) {
        printf("Error: failed to allocate memory for offsets\n");
        return result;
    }

    // Allocate memory for keys
    result.records = (Record**) malloc(m * sizeof(Record*));
    if (!result.records) {
        printf("Error: failed to allocate memory for records\n");
        free(result.offsets);
        return result;
    }

    // Initialize array of records
    for (int i = 0; i < m; i++) {
        if (i >= n) {
            result.records[i] = NULL;
        } else {
            result.records[i] = (Record*) malloc(sizeof(Record));
            if (!result.records[i]) {
                printf("Error: failed to allocate memory for record %d\n", i);
                free(result.offsets);
                free(result.records);
                return result;
            }
        }
    }

    // Initialize random values for records
    srand(time(NULL));
    for (int i = 0; i < m; i++) {
        if (i >= n) {
            result.records[i]->key = NULL;
        } else {
            int value = rand() % 1000;
            result.records[i]->value = value;
        }
    }

    // Free memory if any allocation failed
    for (int i = 0; i < m; i++) {
        if (!result.records[i]) {
            free(result.offsets);
            free(result.records);
            return result;
        }
    }

    // Return the structure containing offsets and records
    return result;
}
