#include <errno.h>

// Define a structure to store the offset values and records
typedef struct {
    long *offsets;
    int **keys;
    record **records;
} Result;

// Define a function to allocate memory for multiple data structures
Result* alloc_memory(int n, int m) {
    // Check if the input parameters are valid
    if (n <= 0 || m <= 0) {
        return NULL;
    }

    // Allocate memory for the offsets and initialize them to 0
    long *offsets = malloc(sizeof(long) * n);
    if (!offsets) {
        fprintf(stderr, "Error: Out of memory when allocating offsets\n");
        return NULL;
    }
    memset(offsets, 0, sizeof(long) * n);

    // Allocate memory for the keys and initialize them to NULL
    int **keys = malloc(sizeof(int *) * m);
    if (!keys) {
        fprintf(stderr, "Error: Out of memory when allocating keys\n");
        free(offsets);
        return NULL;
    }
    memset(keys, 0, sizeof(int *) * m);

    // Allocate memory for the records and initialize them to NULL
    record **records = malloc(sizeof(record *) * n);
    if (!records) {
        fprintf(stderr, "Error: Out of memory when allocating records\n");
        free(offsets);
        free(keys);
        return NULL;
    }
    memset(records, 0, sizeof(record *) * n);

    // Initialize the offsets and keys to their initial values
    for (int i = 0; i < n; i++) {
        offsets[i] = i * 1000 + rand() % 1000;
        if (i < m) {
            keys[i] = malloc(sizeof(int));
            if (!keys[i]) {
                fprintf(stderr, "Error: Out of memory when allocating key for index %d\n", i);
                free(offsets);
                free(keys);
                return NULL;
            }
            *keys[i] = i;
        } else {
            keys[i] = NULL;
        }
    }

    // Allocate memory for the records and initialize them to their initial values
    for (int i = 0; i < n; i++) {
        if (!records[i]) {
            records[i] = malloc(sizeof(record));
            if (!records[i]) {
                fprintf(stderr, "Error: Out of memory when allocating record for index %d\n", i);
                free(offsets);
                free(keys);
                return NULL;
            }
        }
        records[i]->key = keys[i];
        records[i]->value = offsets[i] * 1000 + rand() % 1000;
    }

    // Create a new Result structure and populate it with the allocated memory
    Result *result = malloc(sizeof(Result));
    if (!result) {
        fprintf(stderr, "Error: Out of memory when allocating result\n");
        free(offsets);
        free(keys);
        return NULL;
    }
    result->offsets = offsets;
    result->keys = keys;
    result->records = records;

    return result;
}

// Define a function to free the memory allocated for multiple data structures
void free_memory(Result *result) {
    // Check if the input parameter is valid
    if (!result) {
        return;
    }

    // Free the offsets and keys
    free(result->offsets);
    free(result->keys);

    // Free each record in the records array
    for (int i = 0; i < result->n; i++) {
        if (result->records[i]) {
            free(result->records[i]);
        }
    }

    // Free the records array
    free(result->records);

    // Free the Result structure
    free(result);
}

// Define a function to update the values of existing records without reallocating the entire record array
void update_record_values(Result *result) {
    // Check if the input parameter is valid
    if (!result) {
        return;
    }

    // Iterate over each record and update its value using atomic updates
    for (int i = 0; i < result->n; i++) {
        int old_value = __atomic_load_n(result->records[i]->value, __ATOMIC_SEQ_CST);
        do {
            int new_value = old_value + rand() % 1000;
            old_value = __atomic_compare_exchange_n(result->records[i]->value, &old_value, new_value, false, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST);
        } while (old_value != new_value);
    }
}

// Define a function to update the values of existing records by bulk updating the entire record array
void update_record_values_bulk(Result *result) {
    // Check if the input parameter is valid
    if (!result) {
        return;
    }

    // Allocate memory for a temporary buffer to store the updated values
    int *new_values = malloc(sizeof(int) * result->n);
    if (!new_values) {
        fprintf(stderr, "Error: Out of memory when allocating new values\n");
        return;
    }

    // Iterate over each record and update its value using bulk updates
    for (int i = 0; i < result->n; i++) {
        int old_value = __atomic_load_n(result->records[i]->value, __ATOMIC_SEQ_CST);
        new_values[i] = old_value + rand() % 1000;
    }

    // Bulk update the values of all records using atomic operations
    __atomic_store_n(result->records, new_values, __ATOMIC_SEQ_CST);

    // Free the temporary buffer
    free(new_values);
}

// Define a function to resize the record array by dynamically allocating more memory
void resize_record_array(Result *result) {
    // Check if the input parameter is valid
    if (!result) {
        return;
    }

    // Allocate more memory for the records array
    int new_size = result->n + 10;
    record **new_records = malloc(sizeof(record *) * new_size);
    if (!new_records) {
        fprintf(stderr, "Error: Out of memory when resizing the records array\n");
        return;
    }

    // Copy the contents of the original records array to the new one
    memcpy(new_records, result->records, sizeof(record *) * result->n);

    // Free the original records array and update the Result structure with the new one
    free(result->records);
    result->records = new_records;
    result->n = new_size;
}

// Define a function to support concurrent access to the Result structure from multiple threads
void *thread_func(void *args) {
    // Check if the input parameter is valid
    if (!args) {
        return NULL;
    }

    // Cast the input parameter to a pointer to the Result structure
    Result *result = (Result *) args;

