        __atomic_store_n(result->records[i]->value, rand() % 1000, __ATOMIC_SEQ_CST);
    }

    return NULL;
}

// Define a function to handle cases where m is greater than n by setting the corresponding key pointers to NULL
void handle_key_overflow(Result *result) {
