typedef struct {
    int value;
} Record;

// Define a function to allocate memory for a specified number of records
Record* allocateRecords(int numRecords) {
    // Allocate memory for the array of records
    Record* records = (Record*) malloc(numRecords * sizeof(Record));

    // If memory allocation failed, return NULL
    if (records == NULL) {
        return NULL;
    }

    // Initialize each record's integer value to a random number within the given range
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        records[i].value = rand() % 100;
    }

    return records;
}

// Define a function to serialize the records to a file using a custom binary format
void serializeRecords(Record* records, int numRecords, const char* filename) {
    // Open the output file in binary mode
    FILE* fp = fopen(filename, "wb");

    // If the file cannot be opened, return an error message
    if (fp == NULL) {
        printf("Error: unable to open file %s for serialization\n", filename);
        return;
    }

    // Write the number of records to the file
    fwrite(&numRecords, sizeof(int), 1, fp);

    // Write each record's integer value to the file
    for (int i = 0; i < numRecords; i++) {
        fwrite(&records[i].value, sizeof(int), 1, fp);
    }

    // Close the output file
    fclose(fp);
}

// Define a function to deserialize the records from a file using a custom binary format
void deserializeRecords(Record* records, int numRecords, const char* filename) {
    // Open the input file in binary mode
    FILE* fp = fopen(filename, "rb");

    // If the file cannot be opened, return an error message
    if (fp == NULL) {
        printf("Error: unable to open file %s for deserialization\n", filename);
        return;
    }

    // Read the number of records from the file
    fread(&numRecords, sizeof(int), 1, fp);

    // Read each record's integer value from the file
    for (int i = 0; i < numRecords; i++) {
        fread(&records[i].value, sizeof(int), 1, fp);
    }

    // Close the input file
    fclose(fp);
}

// Define a function to manage a dynamic collection of records
void manageRecords(Record** records, int* numRecords) {
    // Allocate memory for the array of records
    *records = allocateRecords(*numRecords);

    // If memory allocation failed, return an error message
    if (*records == NULL) {
        printf("Error: unable to allocate memory for %d records\n", *numRecords);
        return;
    }

    // Serialize the records to a file using a custom binary format
    serializeRecords(*records, *numRecords, "records.bin");

    // Deserialize the records from the file using a custom binary format
    deserializeRecords(*records, *numRecords, "records.bin");

    // Free the memory allocated for the array of records
    free(*records);
}']

