#include <stdlib.h>
#include <stdio.h>
#include <string.h>

// Define a struct to hold the data for each item
struct item {
    double value;
    char *description;
    size_t index;
};

// Define a function to dynamically allocate memory for an array of items
struct item* initializeItems(size_t numItems, size_t descLen) {
    // Check if the input sizes are valid
    if (numItems <= 0 || descLen <= 0) {
        fprintf(stderr, "Invalid input sizes\n");
        return NULL;
    }

    // Calculate the total size of memory needed for the array and its elements
    size_t totalSize = numItems * sizeof(struct item);
    totalSize += numItems * descLen;

    // Allocate memory for the array
    struct item *items = malloc(totalSize);
    if (items == NULL) {
        fprintf(stderr, "Failed to allocate memory\n");
        return NULL;
    }

    // Initialize each item in the array with a value derived from its index
    for (size_t i = 0; i < numItems; i++) {
        items[i].value = pow(2, i); // Replace with your own polynomial function
        items[i].description = malloc(descLen);
        snprintf(items[i].description, descLen, "%lu", (unsigned long)i);
        items[i].index = i;
    }

    return items;
}

// Define a function to free the memory allocated for an array of items
void freeItems(struct item *items) {
    if (items == NULL) {
        return;
    }

    // Free the description string for each item
    for (size_t i = 0; i < numItems; i++) {
        free(items[i].description);
    }

    // Free the memory allocated for the array of items
    free(items);
}
