struct data_point {
    double value;
    short id;
    enum status flag;
};

int init_data(struct data_point **data, size_t num_points) {
    *data = (struct data_point *)malloc(num_points * sizeof(**data));
    if (*data == NULL) {
        return -ENOMEM;
    }

    for (size_t i = 0; i < num_points; ++i) {
        (*data)[i].value = 0.0;
        (*data)[i].id = 0;
        (*data)[i].flag = STATUS_INITIALIZED;
    }

    return 0;
}

int update_data(struct data_point *data, size_t num_points) {
    // Periodically retrieve new sensor readings from an external data source.
    double new_value = get_sensor_reading();
    short new_id = get_sensor_id();
    enum status new_flag = get_status();

    for (size_t i = 0; i < num_points; ++i) {
        data[i].value = new_value;
        data[i].id = new_id;
        data[i].flag = new_flag;
    }

    return 0;
}

int free_data(struct data_point *data) {
    if (data == NULL) {
        return -EINVAL;
    }
    free(data);
    return 0;
}
