#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Define the data structures
typedef struct {
    int value;
} record;

// Function to manage memory allocation for three separate data structures: an array of long offset values, an array of int keys, and an array of record structures
void* allocateMemory(int numOffsets, int numKeys, int numRecords) {
    // Calculate the total size needed for the arrays
    int totalSize = (numOffsets + numKeys + numRecords) * sizeof(record);

    // Allocate memory for the arrays using malloc()
    void* memory = malloc(totalSize);
    if (!memory) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    // Initialize all elements in the arrays to zero, except for the record structures which should have their int fields set to random values within the range of -1,000,000 to 1,000,000
    long* offsets = (long*)memory;
    int* keys = (int*)(offsets + numOffsets);
    record* records = (record*)(keys + numKeys);
    for (int i = 0; i < numRecords; i++) {
        records[i].value = rand() % 2000000 - 1000000;
    }

    // Initialize the arrays with random values within the range of -1,000,000 to 1,000,000 for the record structures
    srand(time(NULL));
    for (int i = 0; i < numOffsets; i++) {
        offsets[i] = rand() % 2000000 - 1000000;
    }
    for (int i = 0; i < numKeys; i++) {
        keys[i] = rand() % 5000 - 2500;
    }

    // Return a pointer to the first element of the record array
    return records;
}

// Function to clean up dynamically allocated memory
void deallocateMemory(void* memory) {
    free(memory);
}
