// Data structures
typedef struct {
    int key;
    int value;
} Record;

typedef struct {
    long offset;
    int key;
    Record record;
} Entry;

// Global variables
int num_records = 0;
long max_offset = LONG_MAX;
Entry *entries = NULL;

void init_data_structures(int capacity) {
    // Initialize the offset array
    long *offsets = malloc(capacity * sizeof(long));
    if (!offsets) {
        printf("Error: failed to allocate memory for offsets\n");
        return;
    }
    memset(offsets, 0, capacity * sizeof(long));

    // Initialize the key array
    int *keys = malloc(capacity * sizeof(int));
    if (!keys) {
        printf("Error: failed to allocate memory for keys\n");
        free(offsets);
        return;
    }
    memset(keys, 0, capacity * sizeof(int));

    // Initialize the record array
    Record *records = malloc(capacity * sizeof(Record));
    if (!records) {
        printf("Error: failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return;
    }
    memset(records, 0, capacity * sizeof(Record));

    // Initialize the hash table
    entries = malloc(capacity * sizeof(Entry));
    if (!entries) {
        printf("Error: failed to allocate memory for entries\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }
    memset(entries, 0, capacity * sizeof(Entry));

    // Set the initial values of the data structures
    num_records = 0;
}

void add_record(int key, int value) {
    // Check if there is enough space for a new record
    if (num_records >= max_offset) {
        printf("Error: maximum number of records reached\n");
        return;
    }

    // Allocate memory for the new record
    long offset = entries[num_records].offset;
    Record *record = &entries[num_records].record;
    if (!offset || !record) {
        printf("Error: failed to allocate memory for new record\n");
        return;
    }

    // Update the offset and key arrays
    entries[num_records].key = key;
    entries[num_records].value = value;
    offsets[num_records] = offset;
    keys[num_records] = key;

    // Increment the number of records
    num_records++;
}

void update_record(int key, int new_value) {
    // Find the index of the record with the specified key
    for (int i = 0; i < num_records; i++) {
        if (keys[i] == key) {
            entries[i].value = new_value;
            break;
        }
    }
}

void delete_record(int key) {
    // Find the index of the record with the specified key
    for (int i = 0; i < num_records; i++) {
        if (keys[i] == key) {
            // Remove the record from the data structures
            long offset = entries[i].offset;
            Record *record = &entries[i].record;
            if (!offset || !record) {
                printf("Error: failed to delete record\n");
                return;
            }
            free(offset);
            free(record);
            num_records--;

            // Update the offset and key arrays
            for (int j = i; j < num_records; j++) {
                entries[j].offset = offsets[j + 1];
                entries[j].key = keys[j + 1];
                entries[j].record = records[j + 1];
            }
            break;
        }
    }
}

void print_records() {
    // Print the contents of the record array
    for (int i = 0; i < num_records; i++) {
        printf("Record %d: key=%d, value=%d\n", i + 1, entries[i].key, entries[i].value);
    }
}

void free_data_structures() {
    // Free the memory allocated for the data structures
    free(offsets);
    free(keys);
    free(records);
    free(entries);
}
```
