Here's a sample C function that manages a dynamic list of custom `Item` structures within an embedded system:
```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Define the structure for our items
typedef struct {
    int value;
    struct Item* next;
} Item;

// Function to initialize the list with a specified number of items
void init_list(int num_items) {
    // Allocate memory for the list head and tail pointers
    Item* list_head = malloc(sizeof(Item));
    Item* list_tail = malloc(sizeof(Item));
    if (list_head == NULL || list_tail == NULL) {
        printf("Memory allocation failed!\n");
        return;
    }

    // Initialize the head and tail pointers to the same item
    list_head->next = list_tail;
    list_tail->next = NULL;

    // Allocate memory for each item and populate it with the specified value
    Item* current = list_head;
    for (int i = 0; i < num_items; ++i) {
        Item* new_item = malloc(sizeof(Item));
        if (new_item == NULL) {
            printf("Memory allocation failed!\n");
            return;
        }
        current->next = new_item;
        current = new_item;
    }
}

// Function to append a new item to the list while maintaining order based on value
void add_item(int value) {
    // Find the position where the new item should be inserted
    Item* insertion_point = list_head;
    while (insertion_point->next != NULL && insertion_point->value < value) {
        insertion_point = insertion_point->next;
    }

    // Allocate memory for the new item and populate it with the specified value
    Item* new_item = malloc(sizeof(Item));
    if (new_item == NULL) {
        printf("Memory allocation failed!\n");
        return;
    }
    new_item->value = value;
    new_item->next = insertion_point->next;
    insertion_point->next = new_item;
}

// Function to traverse the list and print the integer values in descending order
void print_list() {
    // Iterate through the list from the tail to the head
    Item* current = list_tail;
    while (current != NULL) {
        printf("%d ", current->value);
        current = current->next;
    }
}

// Function to free all memory allocated for the list items and head/tail pointers
void cleanup() {
    // Iterate through the list from the tail to the head and free each item's memory
    Item* current = list_tail;
    while (current != NULL) {
        Item* next = current->next;
        free(current);
        current = next;
    }

    // Free the head and tail pointers
    free(list_head);
    free(list_tail);
}
```
