```
// Source file: data_point.c
#include "data_point.h"

#define MIN_CAPACITY 16
#define CLEANUP_INTERVAL 5000

struct data_point_list_s {
    DataPoint **points;
    size_t capacity, count;
};

struct data_point_list_s *data_point_list = NULL;

void initDataPoint(DataPoint *dp) {
    dp->value = 0.0;
    dp->status = STATUS_FLAG_OK;
    dp->flags = STATUS_FLAG_OK;
}

bool addDataPoint(double value, short status, DataPoint **dp) {
    if (data_point_list == NULL) {
        data_point_list = malloc(sizeof(*data_point_list));
        if (data_point_list == NULL) {
            return false;
        }
        data_point_list->points = calloc(MIN_CAPACITY, sizeof(*data_point_list->points));
        if (data_point_list->points == NULL) {
            free(data_point_list);
            data_point_list = NULL;
            return false;
        }
        data_point_list->capacity = MIN_CAPACITY;
        data_point_list->count = 0;
    } else if (data_point_list->count == data_point_list->capacity) {
        DataPoint **new_points = realloc(data_point_list->points, 2 * data_point_list->capacity * sizeof(*data_point_list->points));
        if (new_points == NULL) {
            return false;
        }
        data_point_list->points = new_points;
        data_point_list->capacity *= 2;
    }
    DataPoint *new_dp = malloc(sizeof(*new_dp));
    if (new_dp == NULL) {
        return false;
    }
    initDataPoint(new_dp);
    new_dp->value = value;
    new_dp->status = status;
    data_point_list->points[data_point_list->count++] = new_dp;
    *dp = new_dp;
    return true;
}

bool updateDataPoint(DataPoint *dp, double value, short status) {
    dp->value = value;
    dp->status = status;
    return true;
}

bool removeDataPoint(DataPoint *dp) {
    size_t i;
    for (i = 0; i < data_point_list->count; i++) {
        if (data_point_list->points[i] == dp) {
            break;
        }
    }
    if (i == data_point_list->count) {
        return false;
    }
    free(dp);
    for (size_t j = i; j < data_point_list->count - 1; j++) {
        data_point_list->points[j] = data_point_list->points[j + 1];
    }
    data_point_list->count--;
    return true;
}

void freeDataPointList() {
    if (data_point_list == NULL) {
        return;
    }
    for (size_t i = 0; i < data_point_list->capacity; i++) {
        free(data_point_list->points[i]);
    }
    free(data_point_list->points);
    free(data_point_list);
}

void cleanupDataPointList() {
    size_t unused_count = 0;
    for (size_t i = 0; i < data_point_list->count; i++) {
        if (data_point_list->points[i]->flags == STATUS_FLAG_ERROR) {
            unused_count++;
        }
    }
    if (unused_count >= CLEANUP_INTERVAL) {
        for (size_t i = 0; i < data_point_list->count; i++) {
            if (data_point_list->points[i]->flags == STATUS_FLAG_ERROR) {
                freeDataPoint(data_point_list->points[i]);
            }
        }
    }
}
```
