#include <string.h>

// Custom node structure for the dynamic linked list
typedef struct Node {
    char *data;
    int priority;
    struct Node *next;
} Node;

// Function to manage memory allocation for a dynamic linked list of custom nodes
Node* allocateMemory(int capacity, const char *data, int priority) {
    // Check if the given data is valid
    if (data == NULL || strlen(data) == 0) {
        printf("Invalid input\n");
        return NULL;
    }

    // Allocate memory for the node and initialize it
    Node *node = malloc(sizeof(Node));
    node->data = malloc(strlen(data) + 1);
    strcpy(node->data, data);
    node->priority = priority;
    node->next = NULL;

    // Check if the memory allocation was successful
    if (node == NULL || node->data == NULL) {
        printf("Memory allocation failed\n");
        free(node);
        return NULL;
    }

    // Return a pointer to the head of the linked list
    return node;
}

// Function to insert a new node into the dynamic linked list with sorted priority
void insertNode(Node **head_ref, const char *data, int priority) {
    // Check if the given data is valid
    if (data == NULL || strlen(data) == 0) {
        printf("Invalid input\n");
        return;
    }

    // Create a new node and allocate memory for it
    Node *new_node = allocateMemory(1, data, priority);
    if (new_node == NULL) {
        printf("Failed to allocate memory for the new node\n");
        return;
    }

    // If the list is empty, set the new node as head
    if (*head_ref == NULL) {
        *head_ref = new_node;
        return;
    }

    // Set the new node as head and update the priority of the first node
    Node *temp = *head_ref;
    *head_ref = new_node;
    (*head_ref)->priority = priority;

    // Traverse the list until a suitable position is found to insert the new node
    while (temp->next != NULL) {
        if (temp->next->priority > priority) {
            break;
        }
        temp = temp->next;
    }

    // Insert the new node at the suitable position
    new_node->next = temp->next;
    temp->next = new_node;
}

// Function to delete a node from the dynamic linked list with sorted priority
void deleteNode(Node **head_ref, const char *data) {
    // Check if the given data is valid
    if (data == NULL || strlen(data) == 0) {
        printf("Invalid input\n");
        return;
    }

    // If the list is empty or the node to be deleted is not found, return
    if (*head_ref == NULL || strcmp((*head_ref)->data, data) != 0) {
        return;
    }

    // Delete the first node in the list
    Node *temp = *head_ref;
    *head_ref = temp->next;
    free(temp);
}

// Function to traverse the dynamic linked list and print all nodes with sorted priority
void traverseList(Node **head_ref) {
    // If the list is empty, return
    if (*head_ref == NULL) {
        printf("List is empty\n");
        return;
    }

    // Traverse the list and print all nodes with sorted priority
    Node *temp = *head_ref;
    while (temp != NULL) {
        printf("%s: %d\n", temp->data, temp->priority);
        temp = temp->next;
    }
}
```
