            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }
    }

    return arr;
}

// Function to dynamically allocate memory for an array of integers
int **allocate_int_array(size_t size) {
    // Allocate memory for the array of pointers
    int **arr = malloc(sizeof(int *) * size);
    if (arr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Initialize each pointer in the array to NULL
    for (size_t i = 0; i < size; i++) {
        arr[i] = NULL;
    }

    // Allocate memory for each integer element and initialize it to 0
    for (size_t i = 0; i < size; i++) {
        arr[i] = malloc(sizeof(int));
        if (arr[i] == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }
    }

    return arr;
}

// Function to dynamically allocate memory for an array of records
record_t **allocate_record_array(size_t size) {
    // Allocate memory for the array of pointers
    record_t **arr = malloc(sizeof(record_t *) * size);
    if (arr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Initialize each pointer in the array to NULL
    for (size_t i = 0; i < size; i++) {
        arr[i] = NULL;
    }

    // Allocate memory for each record element and initialize it to 0
    for (size_t i = 0; i < size; i++) {
        arr[i] = malloc(sizeof(record_t));
        if (arr[i] == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }
    }

    return arr;
}

// Function to randomly populate an array of integers with values between a minimum and maximum value
int *populate_int_array(int *arr, size_t size, int min, int max) {
    // Randomly generate a value within the specified range for each integer element in the array
    srand(time(NULL));
    for (size_t i = 0; i < size; i++) {
        arr[i] = rand() % (max - min + 1) + min;
    }

    return arr;
}

// Function to sort an array of records based on the values stored in their pointers to long integers
void sort_record_array(record_t **arr, size_t size) {
    // Use a bubble sort algorithm to sort the array of records
    for (size_t i = 0; i < size - 1; i++) {
        for (size_t j = i + 1; j < size; j++) {
            if (*(arr[i]->offset) > *(arr[j]->offset)) {
                record_t temp = *(arr[i]);
                *(arr[i]) = *(arr[j]);
                *(arr[j]) = temp;
            }
        }
    }
}

// Function to free memory for an array of long integers, integers, and records
void free_arrays(long **long_arr, int **int_arr, record_t **record_arr) {
    // Free memory for each integer element in the arrays
    for (size_t i = 0; i < size; i++) {
        if (long_arr[i] != NULL) {
            free(long_arr[i]);
        }
        if (int_arr[i] != NULL) {
            free(int_arr[i]);
        }
        if (record_arr[i] != NULL) {
            free(record_arr[i]->offset);
            free(record_arr[i]->key);
            free(record_arr[i]);
        }
    }
}

