    printf("Do you want to allow duplicate keys? (y/n): ");
    char input = getchar();
    if (input == 'y') {
        allow_duplicates = true;
    } else if (input == 'n') {
        allow_duplicates = false;
    } else {
        printf("Invalid input, aborting\n");
        return 1;
    }

    // Allocate memory for arrays of long integers, integers, and records
    long **long_arr = allocate_long_array(arr_size);
    int **int_arr = allocate_int_array(arr_size);
    record_t **record_arr = allocate_record_array(arr_size);
    if (long_arr == NULL || int_arr == NULL || record_arr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    // Populate arrays with random values
    populate_int_array(long_arr, arr_size, min_val, max_val);
    populate_int_array(int_arr, arr_size, min_val, max_val);
    for (size_t i = 0; i < arr_size; i++) {
        record_arr[i]->offset = long_arr[i];
        record_arr[i]->key = int_arr[i];
    }

    // Sort the array of records based on the values stored in their pointers to long integers
    sort_record_array(record_arr, arr_size);

    // Free memory for arrays of long integers, integers, and records
    free_arrays(long_arr, int_arr, record_arr);

    return 0;
}
