    float transmission_latency; // The latency of the transmission
    float bandwidth_utilization; // The utilization of the bandwidth
    int cpu_resource_allocation; // The allocation of CPU resources for encoding and decoding
    int gpu_resource_allocation; // The allocation of GPU resources for encoding and decoding
};

