void log(struct config *config, struct stats *stats, int level, char *format, ...) {
    // Check if the logging level is less than or equal to the desired level
    if (level <= config->log_level) {
        // Allocate a buffer to hold the message
        va_list args;
        va_start(args, format);
        char *buffer = malloc(1024);

        // Format the message and append it to the buffer
        vsnprintf(buffer, 1024, format, args);

        // Print the log message
        printf("%s\n", buffer);

        // Free the buffer
        free(buffer);
    }
}

// Define the function to encode a video frame using FFmpeg
void encode_video_frame(struct config *config, struct stats *stats, AVFrame *frame) {
    // Set up the FFmpeg context for encoding
    AVCodecContext *encoder = avcodec_alloc_context3(NULL);
    encoder->width = frame->width;
    encoder->height = frame->height;
    encoder->time_base.num = 1;
    encoder->time_base.den = config->fps;
    avcodec_open2(encoder, avcodec_find_encoder(AV_CODEC_ID_H264), NULL);

    // Set up the FFmpeg filter for encoding
    AVFilterContext *filter = av_buffersink_get_avfilter(encoder->filter_ctx);
    avfilter_init_str("scale", filter, "1920:1080");

    // Allocate memory for the encoded video frame
    AVPacket packet;
    av_init_packet(&packet);

    // Encode the video frame and write it to the output file
    int ret = avcodec_send_frame(encoder, frame);
    while (ret >= 0) {
        ret = avcodec_receive_packet(encoder, &packet);
        if (ret == AVERROR_EOF || ret == AVERROR(EAGAIN)) {
            break;
        } else if (ret < 0) {
            log(config, stats, LOG_LEVEL_ERROR, "Error encoding video frame: %s", av_err2str(ret));
        } else {
            // Write the encoded frame to the output file
            fwrite(packet.data, packet.size, 1, stdout);

            // Update the transmission latency and bandwidth utilization statistics
            stats->transmission_latency += (float)packet.duration * 1000 / encoder->time_base.den;
            stats->bandwidth_utilization += packet.size * 8;
        }
    }

    // Free the FFmpeg context and filter
    avcodec_free_context(&encoder);
    avfilter_uninit(&filter);
}

