#include "logging_service.h"

// Function to process and execute a command
int process_and_execute_command(char* filename, char* command, int max_len, int concurrency_limit, logging_service* logger) {
    // Check if the filename is empty or contains invalid characters
    if (filename == NULL || strchr(filename, '..') != NULL) {
        return -1;
    }

    // Extract the file type from the filename
    char* file_type = strrchr(filename, '.');
    if (file_type == NULL) {
        return -1;
    }

    // Construct a modified filename with a unique sequence of digits and file type
    int len = strlen(filename);
    char* modified_filename = malloc(max_len * sizeof(char));
    sprintf(modified_filename, "%.*s%ld%s", len - (file_type - filename), filename, getpid(), file_type);

    // Sanitize the command by sanitizing input and constructing the command dynamically without using string concatenation operators like strcat or sprintf
    char* sanitized_command = malloc((strlen(command) + 20) * sizeof(char));
    sprintf(sanitized_command, "sh -c 'echo \"%s\" | md5sum'", command);

    // Run the provided command in the background using fork and wait system calls
    pid_t child = fork();
    if (child == 0) {
        // Child process executes the sanitized command
        int status = execl("/bin/sh", "sh", "-c", sanitized_command, NULL);
        if (status < 0) {
            perror("execl");
            return -1;
        }
    } else {
        // Parent process waits for the command to finish
        int status = waitpid(child, NULL, 0);
        if (status < 0) {
            perror("waitpid");
            return -1;
        }
    }

    // Free memory allocated for sanitized_command and modified_filename
    free(sanitized_command);
    free(modified_filename);

    // Log the execution of the command along with its success/failure status and any relevant error messages
    logger->log_execution(child, command, status == 0 ? "success" : "failure", errno);

    return status;
}

// Function to process a stream of incoming network connection requests from a specified log file
void process_requests(char* filename, logging_service* logger) {
    // Open the log file in read-only mode
    int fd = open(filename, O_RDONLY);
    if (fd < 0) {
        perror("open");
        return;
    }

    // Dynamically allocate memory for an array of 'session' structures
    struct session* sessions = malloc(sizeof(struct session));
    if (sessions == NULL) {
        perror("malloc");
        return;
    }

    // Initialize each session structure with metadata such as client IP address, port number, request timestamp, and connection duration
    for (int i = 0; i < concurrency_limit; i++) {
        sessions[i].client_ip = malloc(16 * sizeof(char));
        if (sessions[i].client_ip == NULL) {
            perror("malloc");
            return;
        }
        sessions[i].port = 0;
        sessions[i].timestamp = malloc(24 * sizeof(char));
        if (sessions[i].timestamp == NULL) {
            perror("malloc");
            return;
        }
        sessions[i].duration = 0;
    }

    // Read each line of the log file and process it as a request
    char buffer[4096];
    while (read(fd, buffer, sizeof(buffer)) > 0) {
        // Parse the log entry to extract client IP address, port number, request timestamp, and connection duration
        int i = 0;
        while (i < concurrency_limit && strlen(sessions[i].client_ip) > 0) {
            i++;
        }
        if (i == concurrency_limit) {
            fprintf(stderr, "Concurrency limit reached\n");
            break;
        }
        char* token = strtok(buffer, " ");
        while (token != NULL) {
            if (strcmp(token, "client") == 0) {
                token = strtok(NULL, " ");
                strcpy(sessions[i].client_ip, token);
            } else if (strcmp(token, "port") == 0) {
                token = strtok(NULL, " ");
                sessions[i].port = atoi(token);
            } else if (strcmp(token, "timestamp") == 0) {
                token = strtok(NULL, " ");
                strcpy(sessions[i].timestamp, token);
            } else if (strcmp(token, "duration") == 0) {
                token = strtok(NULL, " ");
                sessions[i].duration = atoi(token);
            }
            token = strtok(NULL, " ");
        }

        // Process the request using process_and_execute_command() function
        char* command = malloc((strlen(buffer) + 20) * sizeof(char));
        sprintf(command, "%.*s", (int)(strchr(buffer, ' ') - buffer), buffer);
        int status = process_and_execute_command(filename, command, max_len, concurrency_limit, logger);
        if (status < 0) {
            perror("process_and_execute_command");
            return;
        }
    }

    // Free memory allocated for sessions and close the log file
    for (int i = 0; i < concurrency_limit; i++) {
        free(sessions[i].client_ip);
        free(sessions[i].timestamp);
    }
    free(sessions);
    close(fd);
}']

