typedef struct {
    long *offset;
    int *key;
    struct record *record;
} RecordArray;

void createRecordArray(RecordArray *ra, size_t size) {
    ra->offset = malloc(sizeof(long) * size);
    ra->key = malloc(sizeof(int) * size);
    ra->record = malloc(sizeof(struct record) * size);
}

void destroyRecordArray(RecordArray *ra) {
    free(ra->offset);
    free(ra->key);
    free(ra->record);
}

// Randomly populates each record's int field with a value between the user-specified minimum and maximum, inclusive.
void populateIntKeys(RecordArray *ra, size_t min, size_t max) {
    for (size_t i = 0; i < ra->size; i++) {
        ra->record[i].int = rand() % (max - min + 1) + min;
    }
}

// Sorts the record array based on the long integer values stored in their pointers, ensuring stability if multiple records have identical offset values.
void sortByOffset(RecordArray *ra) {
    qsort(ra->record, ra->size, sizeof(struct record), compareRecords);
}

// Implements a compare function for the qsort function to sort the record array based on their offsets.
int compareRecords(const void *a, const void *b) {
    struct record *ra = (struct record *)a;
    struct record *rb = (struct record *)b;
    return ra->offset - rb->offset;
}

// Handles potential race conditions if the function is called concurrently from multiple threads.
void handleRaceConditions(RecordArray *ra) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);
    // Mutual exclusion section:
    createRecordArray(ra, size);
    populateIntKeys(ra, min, max);
    sortByOffset(ra);
    destroyRecordArray(ra);
    pthread_mutex_unlock(&mutex);
}

int main() {
    RecordArray ra;
    size_t size = 10000;
    size_t min = 0;
    size_t max = 100;

    createRecordArray(&ra, size);
    populateIntKeys(&ra, min, max);
    sortByOffset(&ra);
    destroyRecordArray(&ra);

    return 0;
}
```
