// Custom record structure for the array of custom records
typedef struct {
    int random_num;
} Record;

// Function to manage dynamic memory allocation for three distinct arrays:
// an array of long type representing file offsets, an array of int type used as keys for indexing the offsets array, and an array of custom record structures containing an int field for storing random numbers within a specified range and frequency.
void allocate_memory(size_t offset_array_size, size_t key_array_size, size_t record_array_size) {
    // Input validation: ensure that the input sizes are non-negative and not zero
    if (offset_array_size == 0 || offset_array_size < 0 ||
        key_array_size == 0 || key_array_size < 0 ||
        record_array_size == 0 || record_array_size < 0) {
        fprintf(stderr, "Invalid input size: %zu\n", offset_array_size);
        return;
    }

    // Assess system resources to determine the optimal allocation strategy that minimizes resource usage while maintaining performance
    size_t total_memory = offset_array_size * sizeof(long) + key_array_size * sizeof(int) + record_array_size * sizeof(Record);
    if (total_memory > get_available_memory()) {
        fprintf(stderr, "Insufficient memory available: %zu\n", total_memory);
        return;
    }

    // Allocate memory for the three arrays using a single block of contiguous memory
    void* mem = malloc(total_memory);
    if (!mem) {
        fprintf(stderr, "Failed to allocate memory: %s\n", strerror(errno));
        return;
    }

    // Initialize the three arrays using a pointer offset from the start of the allocated memory block
    long* offsets = (long*)mem;
    int* keys = (int*)(offsets + offset_array_size);
    Record* records = (Record*)(keys + key_array_size);

    // Initialize the three arrays with default values
    for (size_t i = 0; i < offset_array_size; i++) {
        offsets[i] = -1;
    }
    for (size_t i = 0; i < key_array_size; i++) {
        keys[i] = -1;
    }
    for (size_t i = 0; i < record_array_size; i++) {
        records[i].random_num = -1;
    }

    // Track and handle duplicate keys in the keys array using a hash table
    struct HashTable {
        int key;
        size_t index;
    };
    struct HashTable* hash_table = (struct HashTable*)calloc(key_array_size, sizeof(struct HashTable));
    if (!hash_table) {
        fprintf(stderr, "Failed to allocate memory for hash table: %s\n", strerror(errno));
        free(mem);
        return;
    }
    for (size_t i = 0; i < key_array_size; i++) {
        struct HashTable* entry = &hash_table[i];
        if (!entry) {
            fprintf(stderr, "Failed to allocate memory for hash table entry: %s\n", strerror(errno));
            free(mem);
            return;
        }
        entry->key = keys[i];
        entry->index = i;
    }

    // Read the file and populate the arrays using a fallback strategy if memory constraints are encountered
    size_t line_number = 0;
    FILE* file = fopen("file.txt", "r");
    if (!file) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        free(mem);
        return;
    }
    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        // Parse the line and extract the offset, key, and random number
        long offset;
        int key;
        Record record;
        if (sscanf(line, "%ld %d %d", &offset, &key, &record.random_num) != 3) {
            fprintf(stderr, "Failed to parse line %zu: %s\n", line_number, strerror(errno));
            free(mem);
            return;
        }

        // Ensure that the key is unique by checking for duplicates in the hash table
        struct HashTable* entry = find_entry_by_key(hash_table, key);
        if (entry) {
            fprintf(stderr, "Duplicate key %d found on line %zu\n", key, line_number);
            free(mem);
            return;
        }

        // Add the entry to the hash table and update the corresponding array indices
        entry = &hash_table[key_array_size + line_number];
        if (!entry) {
            fprintf(stderr, "Failed to allocate memory for hash table entry: %s\n", strerror(errno));
            free(mem);
            return;
        }
        entry->key = key;
        entry->index = line_number + offset_array_size;

        // Update the corresponding arrays with the extracted values
        offsets[line_number] = offset;
        keys[line_number] = key;
        records[line_number] = record;

        line_number++;
    }
    fclose(file);

    // Clean up and return
    free(hash_table);
    return mem;
}

// Find an entry in the hash table by key
struct HashTable* find_entry_by_key(struct HashTable* hash_table, int key) {
    for (size_t i = 0; i < key_array_size; i++) {
        if (hash_table[i].key == key) {
            return &hash_table[i];
        }
    }
    return NULL;
}
