  // allocation and initialization.
  for (int i = 0; i < numRecords; i++) {
    (*keys)[i] = rand() % maxLimit + 1;
    if ((offsetSum += (*keys)[i]) > maxLimit) {
      fprintf(stderr, "Key value exceeds maximum limit\n");
      free(*offsets);
      free(*keys);
      free(*records);
      free(*statusFlags);
      return;
