  }

  // Initialize each 'bool' status flag to true. Ensure that the sum of all status flags
  // does not exceed the specified maximum limit. Implement bounds checking to prevent
  // out-of-bounds access during memory allocation and initialization.
  for (int i = 0; i < numRecords; i++) {
    (*statusFlags)[i] = true;
    if ((offsetSum += (*statusFlags)[i]) > maxLimit) {
      fprintf(stderr, "Status flag value exceeds maximum limit\n");
      free(*offsets);
      free(*keys);
      free(*records);
      free(*statusFlags);
      return;
    }
  }

  // Iterate over the records and update the 'int' value of each record based on the
  // difference between its 'long' offset and the current index, ensuring that the
  // updated value remains within the valid range. If an overflow occurs, adjust the
  // value accordingly without causing program failure. Consider the performance implications
