#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <numa.h>

// Structure definitions
struct config_params {
    int buffer_size;
    void *connection_pool;
    struct event_queue *event_queue;
};

struct configuration {
    struct config_params *config_param_arr;
    size_t num_config_params;
};

// NUMA-aware memory allocation functions
void* alloc_numa_memory(size_t size, int node) {
    void *ptr = NULL;
    if (node >= 0 && node < numa_num_nodes()) {
        ptr = numa_alloc_onnode(size, node);
    } else {
        ptr = malloc(size);
    }
    return ptr;
}

void free_numa_memory(void *ptr) {
    if (ptr != NULL) {
        int node = numa_get_membind(ptr);
        if (node >= 0 && node < numa_num_nodes()) {
            numa_free(ptr, node);
        } else {
            free(ptr);
        }
    }
}

// Configuration management functions
void add_config_param(struct configuration *config, struct config_params *param) {
    if (config->num_config_params == 0) {
        config->config_param_arr = malloc(sizeof(struct config_params));
    } else {
        config->config_param_arr = realloc(config->config_param_arr, sizeof(struct config_params) * (config->num_config_params + 1));
    }
    assert(config->config_param_arr != NULL);
    config->config_param_arr[config->num_config_params++] = param;
}

void remove_config_param(struct configuration *config, size_t idx) {
    if (idx < config->num_config_params) {
        memmove(&config->config_param_arr[idx], &config->config_param_arr[idx + 1], sizeof(struct config_params) * (config->num_config_params - idx));
        config->num_config_params--;
    }
}

// Validation functions
int validate_buffer_size(int buffer_size) {
    return buffer_size >= 1024 * 1024 ? buffer_size : -1;
}

int validate_connection_pool_size(void *connection_pool) {
    return connection_pool != NULL ? 1 : -1;
}

// Error handling functions
void handle_error(struct configuration *config, int error_code, const char* message) {
    if (error_code == 0) {
        printf("Configuration update successful\n");
    } else {
        printf("Error updating configuration: %s\n", message);
        remove_config_param(config, idx);
    }
}

// Adjustment functions
void adjust_buffer_size(struct configuration *config, int new_buffer_size) {
    if (new_buffer_size >= 1024 * 1024) {
        for (int i = 0; i < config->num_config_params; i++) {
            struct config_params *param = &config->config_param_arr[i];
            if (param->buffer_size > new_buffer_size) {
                param->buffer_size = new_buffer_size;
            }
        }
    }
}

void adjust_connection_pool_size(struct configuration *config, int new_connection_pool_size) {
    if (new_connection_pool_size > 0 && new_connection_pool_size <= config->num_config_params) {
        for (int i = 0; i < config->num_config_params; i++) {
            struct config_params *param = &config->config_param_arr[i];
            if (param->connection_pool != NULL && param->buffer_size > new_connection_pool_size) {
                free_numa_memory(param->connection_pool);
                param->connection_pool = alloc_numa_memory(new_connection_pool_size, numa_get_membind(param->connection_pool));
            }
        }
    }
}

// Configuration update function
void update_configuration(struct configuration *config, struct config_params *new_param) {
    int error_code = 0;
    for (int i = 0; i < config->num_config_params; i++) {
        struct config_params *param = &config->config_param_arr[i];
        if (param == new_param) continue;
        if (strcmp(param->type, new_param->type) == 0) {
            // validate new parameter value
            switch (new_param->type) {
                case 'B': error_code = validate_buffer_size(new_param->value); break;
                case 'P': error_code = validate_connection_pool_size(new_param->value); break;
            }
            if (error_code == 0) {
                // update parameter value
                switch (new_param->type) {
                    case 'B': param->buffer_size = new_param->value; break;
                    case 'P': param->connection_pool = new_param->value; break;
                }
            } else {
                // handle error
                handle_error(config, error_code, "Invalid parameter value");
            }
        }
    }
}

// Periodic adjustment function
void periodic_adjustment(struct configuration *config) {
    int new_buffer_size = validate_buffer_size(config->num_config_params);
    if (new_buffer_size > 0) {
        // adjust buffer size
        adjust_buffer_size(config, new_buffer_size);
    }
}

// Edge case handling functions
void handle_null_pointer(struct configuration *config, int idx) {
    if (idx < config->num_config_params) {
        struct config_params *param = &config->config_param_arr[idx];
        param->connection_pool = alloc_numa_memory(1024 * 1024, numa_get_membind(param->connection_pool));
    }
}

void handle_out_of_bounds(struct configuration *config, int idx) {
    if (idx < config->num_config_params) {
        struct config_params *param = &config->config_param_arr[idx];
        if (param->buffer_size > 1024 * 1024) {
            // adjust buffer size
            adjust_buffer_size(config, param->buffer_size);
        } else {
            // handle error
            handle_error(config, -1, "Buffer size out of bounds");
        }
    }
}

// Recovery functions
void recover_from_transient_error(struct configuration *config) {
    for (int i = 0; i < config->num_config_params; i++) {
        struct config_params *param = &config->config_param_arr[i];
        if (param->connection_pool == NULL) {
            // recreate connection pool
            param->connection_pool = alloc_numa_memory(1024 * 1024, numa_get_membind(param->connection_pool));
        }
    }
}

void recover_from_degraded_performance(struct configuration *config) {
    for (int i = 0; i < config->num_config_params; i++) {
        struct config_params *param = &config->config_param_arr[i];
        if (param->buffer_size > 1024 * 1024) {
            // adjust buffer size
            adjust_buffer_size(config, param->buffer_size);
        } else {
            // handle error
            handle_error(config, -1, "Buffer size out of bounds");
        }
    }
}
