#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>
#include <math.h>

// Define the data structure to hold a list of records
typedef struct record_t {
    int type; // 0 for integer, 1 for double, 2 for string
    union {
        int i;
        double d;
        char *s;
    } value;
} record_t;

// Define the list data structure
typedef struct record_list_t {
    size_t num_records;
    record_t *records;
} record_list_t;

// Initialize a new record list with the given number of records and random value ranges
record_list_t* init_record_list(size_t num_records, int integer_min, int integer_max, double double_min, double double_max, size_t string_length) {
    // Allocate memory for the list structure and its records
    record_list_t *list = malloc(sizeof(record_list_t));
    list->num_records = num_records;
    list->records = malloc(num_records * sizeof(record_t));

    // Initialize each record with a random value within the specified range
    for (size_t i = 0; i < num_records; i++) {
        record_t *record = &list->records[i];

        // Generate a random integer, double or string
        int random_value = rand() % (integer_max - integer_min + 1) + integer_min;
        if (rand() % 2 == 0) {
            record->type = 0;
            record->value.i = random_value;
        } else {
            record->type = 1;
            record->value.d = (double)random_value / (double)(integer_max - integer_min + 1) * double_max + double_min;
        }

        if (string_length > 0) {
            record->type = 2;
            // Generate a random string with the specified length
            char *str = malloc(string_length + 1);
            for (size_t j = 0; j < string_length; j++) {
                str[j] = 'a' + rand() % 26;
            }
            str[string_length] = '\0';
            record->value.s = str;
        }
    }

    return list;
}

// Free the memory allocated for a record list
void free_record_list(record_list_t *list) {
    if (list != NULL) {
        for (size_t i = 0; i < list->num_records; i++) {
            record_t *record = &list->records[i];

            // Free the string value if it exists
            if (record->type == 2 && record->value.s != NULL) {
                free(record->value.s);
            }
        }

        // Free the list structure and its records
        free(list->records);
        free(list);
    }
}

// Serialize a record list to a binary file
void serialize_record_list(const char *filename, const record_list_t *list) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        printf("Error: Failed to open file %s\n", filename);
        return;
    }

    // Write the number of records in the list
    size_t num_records = list->num_records;
    fwrite(&num_records, sizeof(size_t), 1, file);

    // Write each record
    for (size_t i = 0; i < list->num_records; i++) {
        const record_t *record = &list->records[i];

        // Write the type of the record
        int type = record->type;
        fwrite(&type, sizeof(int), 1, file);

        // Write the value of the record
        switch (record->type) {
            case 0: // integer
                fwrite(&record->value.i, sizeof(int), 1, file);
                break;
            case 1: // double
                fwrite(&record->value.d, sizeof(double), 1, file);
                break;
            case 2: // string
                size_t length = strlen(record->value.s);
                fwrite(&length, sizeof(size_t), 1, file);
                fwrite(record->value.s, length, 1, file);
                break;
        }
    }

    // Close the file
    fclose(file);
}

// Deserialize a record list from a binary file
void deserialize_record_list(const char *filename, record_list_t **list) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Error: Failed to open file %s\n", filename);
        return;
    }

    // Read the number of records in the list
    size_t num_records;
    fread(&num_records, sizeof(size_t), 1, file);

    // Allocate memory for the list structure and its records
    record_list_t *new_list = malloc(sizeof(record_list_t));
    new_list->num_records = num_records;
    new_list->records = malloc(num_records * sizeof(record_t));

    // Read each record
    for (size_t i = 0; i < num_records; i++) {
        record_t *record = &new_list->records[i];

        // Read the type of the record
        int type;
        fread(&type, sizeof(int), 1, file);
        record->type = type;

        // Read the value of the record
        switch (record->type) {
            case 0: // integer
                fread(&record->value.i, sizeof(int), 1, file);
                break;
            case 1: // double
                fread(&record->value.d, sizeof(double), 1, file);
                break;
            case 2: // string
                size_t length;
                fread(&length, sizeof(size_t), 1, file);

                // Allocate memory for the string value
                char *str = malloc(length + 1);
                fread(str, length, 1, file);
                str[length] = '\0';
                record->value.s = str;
                break;
        }
    }

    // Close the file
    fclose(file);

    // Assign the deserialized list to the output parameter
    *list = new_list;
}

// Sort a record list based on a specified attribute (integer, double or string)
void sort_record_list(record_list_t *list, int attribute) {
    if (attribute == 0 || attribute == 1) { // integer or double
        // Use the appropriate comparison function for integers and doubles
        int (*comp)(const void*, const void*) = (attribute == 0) ? compare_integers : compare_doubles;

        // Sort the records using qsort
        qsort(list->records, list->num_records, sizeof(record_t), comp);
    } else if (attribute == 2) { // string
        // Use the strcmp function to compare strings
        int (*comp)(const void*, const void*) = compare_strings;

        // Sort the records using qsort
        qsort(list->records, list->num_records, sizeof(record_t), comp);
    } else {
        printf("Error: Invalid attribute %d\n", attribute);
    }
}

// Compare two integers based on their absolute value
int compare_integers(const void *a, const void *b) {
    const record_t *record1 = a;
    const record_t *record2 = b;

    return abs(record1->value.i) - abs(record2->value.i);
}

// Compare two doubles based on their absolute value
int compare_doubles(const void *a, const void *b) {
    const record_t *record1 = a;
    const record_t *record2 = b;

    return abs(record1->value.d) - abs(record2->value.d);
}

// Compare two strings lexicographically
int compare_strings(const void *a, const void *b) {
    const record_t *record1 = a;
    const record_t *record2 = b;

    return strcmp(record1->value.s, record2->value.s);
}']

