```c
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

// Define structure to hold record information
typedef struct Record {
    int key;
    long offset;
    char* content;
} Record;

// Define data block structure for variable-length content
typedef struct DataBlock {
    void* data;
    size_t size;
    struct DataBlock* next;
} DataBlock;

// Define data store structure to hold records and data blocks
typedef struct DataStore {
    Record* records;
    size_t record_count;
    DataBlock* data_blocks;
    size_t data_block_count;
} DataStore;

// Define function for initializing a new data store
DataStore* init_data_store(size_t capacity) {
    DataStore* store = (DataStore*) malloc(sizeof(DataStore));
    if (!store) return NULL;

    // Allocate memory for records and data blocks
    size_t record_count = 0;
    size_t data_block_count = 0;
    Record* records = (Record*) calloc(capacity, sizeof(Record));
    DataBlock* data_blocks = (DataBlock*) malloc(sizeof(DataBlock) * capacity);
    if (!records || !data_blocks) {
        free(store);
        return NULL;
    }

    store->records = records;
    store->record_count = record_count;
    store->data_blocks = data_blocks;
    store->data_block_count = data_block_count;

    // Initialize mutex for synchronizing access to data store
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_setpshared(&attr, PTHREAD_PROCESS_SHARED);
    pthread_mutex_init(&store->lock, &attr);

    return store;
}

// Define function for inserting a new record into the data store
int insert_record(DataStore* store, int key, long offset, char* content) {
    // Lock mutex to synchronize access to data store
    pthread_mutex_lock(&store->lock);

    // Check if there is enough space in the data store for new record
    size_t record_count = store->record_count;
    size_t capacity = store->capacity;
    if (record_count == capacity) {
        pthread_mutex_unlock(&store->lock);
        return -1; // Data store is full, can't insert new record
    }

    // Allocate memory for new record and copy key and offset values
    Record* new_record = (Record*) malloc(sizeof(Record));
    if (!new_record) {
        pthread_mutex_unlock(&store->lock);
        return -1; // Failed to allocate memory for new record
    }

    new_record->key = key;
    new_record->offset = offset;
    new_record->content = content;

    // Add new record to data store and increment record count
    store->records[record_count] = new_record;
    store->record_count++;

    // Unlock mutex and return success
    pthread_mutex_unlock(&store->lock);
    return 0; // Successfully inserted new record into data store
}

// Define function for updating a record in the data store
int update_record(DataStore* store, int key, long offset, char* content) {
    // Lock mutex to synchronize access to data store
    pthread_mutex_lock(&store->lock);

    // Find record with matching key and update its offset value
    size_t index = 0;
    while (index < store->record_count && store->records[index].key != key) {
        index++;
    }
    if (index == store->record_count) {
        pthread_mutex_unlock(&store->lock);
        return -1; // No record with matching key found, can't update
    }

    Record* record = &store->records[index];
    record->offset = offset;
    record->content = content;

    // Unlock mutex and return success
    pthread_mutex_unlock(&store->lock);
    return 0; // Successfully updated record in data store
}

// Define function for retrieving a record from the data store
Record* retrieve_record(DataStore* store, int key) {
    // Lock mutex to synchronize access to data store
    pthread_mutex_lock(&store->lock);

    // Find record with matching key and return it
    size_t index = 0;
    while (index < store->record_count && store->records[index].key != key) {
        index++;
    }
    if (index == store->record_count) {
        pthread_mutex_unlock(&store->lock);
        return NULL; // No record with matching key found, can't retrieve
    }

    Record* record = &store->records[index];

    // Unlock mutex and return record
    pthread_mutex_unlock(&store->lock);
    return record;
}

// Define function for deleting a record from the data store
int delete_record(DataStore* store, int key) {
    // Lock mutex to synchronize access to data store
    pthread_mutex_lock(&store->lock);

    // Find record with matching key and delete it
    size_t index = 0;
    while (index < store->record_count && store->records[index].key != key) {
        index++;
    }
    if (index == store->record_count) {
        pthread_mutex_unlock(&store->lock);
        return -1; // No record with matching key found, can't delete
    }

    Record* deleted_record = &store->records[index];
    store->records[index] = store->records[--store->record_count];

    // Free memory for deleted record and decrement data block count if necessary
    free(deleted_record);
    DataBlock* deleted_data_block = (DataBlock*)deleted_record->content;
    if (deleted_data_block) {
        store->data_blocks[--store->data_block_count] = deleted_data_block;
    }

    // Unlock mutex and return success
    pthread_mutex_unlock(&store->lock);
    return 0; // Successfully deleted record from data store
}

// Define function for processing a record through a user-defined callback function
int process_record(DataStore* store, int key, void (*callback)(Record*)) {
    // Lock mutex to synchronize access to data store
    pthread_mutex_lock(&store->lock);

    // Find record with matching key and call user-defined callback function
    size_t index = 0;
    while (index < store->record_count && store->records[index].key != key) {
        index++;
    }
    if (index == store->record_count) {
        pthread_mutex_unlock(&store->lock);
        return -1; // No record with matching key found, can't process
    }

    Record* record = &store->records[index];
    callback(record);

    // Unlock mutex and return success
    pthread_mutex_unlock(&store->lock);
    return 0; // Successfully processed record through user-defined callback function
}

// Define function for cleaning up data store resources on program termination
void cleanup(DataStore* store) {
    // Lock mutex to synchronize access to data store
    pthread_mutex_lock(&store->lock);

    // Free all memory allocated for records and data blocks
    size_t record_count = store->record_count;
    while (record_count-- > 0) {
        free(store->records[record_count].content);
    }
    size_t data_block_count = store->data_block_count;
    while (data_block_count-- > 0) {
        free(store->data_blocks[data_block_count]);
    }

    // Unlock mutex and return success
    pthread_mutex_unlock(&store->lock);
}
