#include <stdlib.h>
#include <time.h>

// Define a struct for storing data with a float value and a variable-length char array
typedef struct {
    float value;
    char *str;
} Data;

// Define a function to dynamically allocate memory for the three arrays
void dynamic_arrays(double **doubles, unsigned long **keys, Data ***data) {
    // Allocate memory for the double array
    *doubles = (double *)malloc(sizeof(double) * 3);
    if (*doubles == NULL) {
        printf("Error: Failed to allocate memory for the double array.\n");
        return;
    }

    // Allocate memory for the unsigned long key array
    *keys = (unsigned long *)malloc(sizeof(unsigned long) * 3);
    if (*keys == NULL) {
        printf("Error: Failed to allocate memory for the unsigned long key array.\n");
        free(*doubles);
        return;
    }

    // Allocate memory for the struct data array
    *data = (Data **)malloc(sizeof(Data *) * 3);
    if (*data == NULL) {
        printf("Error: Failed to allocate memory for the struct data array.\n");
        free(*doubles);
        free(*keys);
        return;
    }

    // Initialize the double array with random numbers within a specified range
    srand(time(NULL));
    for (int i = 0; i < 3; i++) {
        (*doubles)[i] = ((double)rand() / RAND_MAX) * 10.0;
    }

    // Initialize the unsigned long key array with random numbers within a specified range
    for (int i = 0; i < 3; i++) {
        (*keys)[i] = rand() % 100;
    }

    // Initialize the struct data array with random string values and allocate memory for each string
    for (int i = 0; i < 3; i++) {
        (*data)[i] = malloc(sizeof(Data));
        if ((*data)[i] == NULL) {
            printf("Error: Failed to allocate memory for struct data.\n");
            free(*doubles);
            free(*keys);
            return;
        }
        (*data)[i]->value = rand() % 100;
        int str_len = rand() % 10 + 5;
        (*data)[i]->str = malloc(sizeof(char) * (str_len + 1));
        if ((*data)[i]->str == NULL) {
            printf("Error: Failed to allocate memory for struct data str.\n");
            free(*doubles);
            free(*keys);
            return;
        }
        (*data)[i]->str[0] = '\0';
    }
}

// Define a function to free the allocated memory
void free_memory(double **doubles, unsigned long **keys, Data ***data) {
    // Free the double array
    if (*doubles != NULL) {
        free(*doubles);
    }

    // Free the unsigned long key array
    if (*keys != NULL) {
        free(*keys);
    }

    // Free the struct data array
    if (*data != NULL) {
        for (int i = 0; i < 3; i++) {
            if ((*data)[i] != NULL) {
                free((*data)[i]->str);
                free(*data);
            }
        }
    }
}

// Test the function by populating and freeing the arrays
int main() {
    double *doubles = NULL;
    unsigned long *keys = NULL;
    Data **data = NULL;
    dynamic_arrays(&doubles, &keys, &data);
    for (int i = 0; i < 3; i++) {
        printf("Double %d: %lf\n", i, doubles[i]);
        printf("Key %d: %lu\n", i, keys[i]);
        printf("Struct data %d: %f, \"%s\"\n", i, data[i]->value, data[i]->str);
    }
    free_memory(&doubles, &keys, &data);
    return 0;
}
```
