// Define the MetricSample structure
typedef struct {
    double value;
    time_t timestamp;
    int category;
} MetricSample;

// Define the memory management functions
void *allocate(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        printf("Error: Out of memory\n");
        exit(1);
    }
    return ptr;
}

void free_memory(MetricSample **samples, int size) {
    for (int i = 0; i < size; ++i) {
        free(samples[i]);
    }
    free(samples);
}

// Define the initialization function
void initialize(int buffer_size, MetricSample ***samples, pthread_mutex_t *lock) {
    // Allocate memory for the array of pointers
    *samples = allocate(sizeof(MetricSample *) * buffer_size);

    // Initialize the timestamp fields
    time_t now = time(NULL);
    for (int i = 0; i < buffer_size; ++i) {
        (*samples)[i] = allocate(sizeof(MetricSample));
        (*samples)[i]->timestamp = now + i * 1000; // 1 second interval
    }

    // Initialize the lock for thread-safe access to the buffer
    pthread_mutex_init(&lock, NULL);
}

// Define the insertion function for individual samples
void insert(MetricSample **samples, int size, double value, time_t timestamp, int category) {
    // Acquire the lock to prevent concurrent access
    pthread_mutex_lock(&lock);

    // Insert the new sample into the buffer
    for (int i = 0; i < size; ++i) {
        if (!samples[i]) {
            break;
        } else if (samples[i]->timestamp <= timestamp) {
            samples[i] = allocate(sizeof(MetricSample));
            samples[i]->value = value;
            samples[i]->timestamp = timestamp;
            samples[i]->category = category;
            break;
        }
    }

    // Release the lock to allow other threads to access the buffer
    pthread_mutex_unlock(&lock);
}

// Define the insertion function for batched samples
void batch_insert(MetricSample **samples, int size, double *values, time_t *timestamps, int *categories) {
    // Acquire the lock to prevent concurrent access
    pthread_mutex_lock(&lock);

    // Insert the new batch of samples into the buffer
    for (int i = 0; i < size; ++i) {
        insert(samples, size, values[i], timestamps[i], categories[i]);
    }

    // Release the lock to allow other threads to access the buffer
    pthread_mutex_unlock(&lock);
}

// Define the iteration function for accessing all records
void iterate(MetricSample **samples, int size) {
    // Acquire the lock to prevent concurrent access
    pthread_mutex_lock(&lock);

    // Iterate over all samples in the buffer
    for (int i = 0; i < size; ++i) {
        if (!samples[i]) {
            continue;
        } else {
            printf("Value: %f\n", samples[i]->value);
            printf("Timestamp: %lu\n", samples[i]->timestamp);
            printf("Category: %d\n", samples[i]->category);
        }
    }

    // Release the lock to allow other threads to access the buffer
    pthread_mutex_unlock(&lock);
}

// Define the callback function for post-initialization operations
void process(MetricSample *sample) {
    printf("Value: %f\n", sample->value);
    printf("Timestamp: %lu\n", sample->timestamp);
    printf("Category: %d\n", sample->category);
}

// Define the statistical computation functions
double compute_mean(MetricSample **samples, int size) {
    double mean = 0;
    for (int i = 0; i < size; ++i) {
        if (!samples[i]) {
            continue;
        } else {
            mean += samples[i]->value / size;
        }
    }
    return mean;
}

double compute_median(MetricSample **samples, int size) {
    double median = 0;
    for (int i = 0; i < size; ++i) {
        if (!samples[i]) {
            continue;
        } else {
            median += samples[i]->value / size;
        }
    }
    return median;
}

double compute_stddev(MetricSample **samples, int size) {
    double mean = compute_mean(samples, size);
    double stddev = 0;
    for (int i = 0; i < size; ++i) {
        if (!samples[i]) {
            continue;
        } else {
            stddev += ((samples[i]->value - mean) * (samples[i]->value - mean)) / size;
        }
    }
    return sqrt(stddev);
}

// Define the logging mechanism for tracking number of samples processed and errors encountered
void log_metric(MetricSample *sample, int status) {
    if (status == 0) {
        printf("Successfully inserted metric sample with value %f\n", sample->value);
    } else {
        printf("Error inserting metric sample: Out of memory\n");
    }
}

// Define the main function for testing and evaluation
