    // Set the buffer size and category mappings
    int buffer_size = 1000000;
    int num_categories = 5;
    char *category_mappings[num_categories] = {"Category A", "Category B", "Category C", "Category D", "Category E"};

    // Initialize the MetricSample structures and lock for thread-safe access to the buffer
