    time_t timestamp = time(NULL);
    int category = 0;
    MetricSample *sample = allocate(sizeof(MetricSample));
    sample->value = value;
    sample->timestamp = timestamp;
    sample->category = category;
    insert(samples, buffer_size, value, timestamp, category);
    free(sample);
    batch_insert(samples, buffer_size, &value, &timestamp, &category);

    // Test the iteration function
    iterate(samples, buffer_size);

    // Test the statistical computation functions
