import java.util.*;
import java.time.Instant;
import java.time.format.DateTimeFormatter;

public class ScalableDataProcessing {
  private static final int DEFAULT_NUM_RECORDS = 10;
  private static final List<String> DEFAULT_DATA_TYPES = Arrays.asList("int", "float", "double");
  private static final Map<String, Integer> DEFAULT_RANDOM_VALUE_GENERATION_PARAMS = new HashMap<>();
  private static final String MISSING_METADATA_FIELD = "-";
  private static final int NUM_FIELDS_MULTIPLE_OF_FOUR = 4;
  private static final double REPRODUCIBILITY_SEED = 0.0;
  private static final String CENTRALIZED_MESSAGE_BROKER_URL = "https://example.com/message-broker";
  private static final DateTimeFormatter DATE_TIME_FORMATTER = DateTimeFormatter.ISO_INSTANT;

  public static void main(String[] args) {
    // Initialize the system with default values if no arguments are provided
    int numRecords = DEFAULT_NUM_RECORDS;
    List<String> dataTypes = DEFAULT_DATA_TYPES;
    Map<String, Integer> randomValueGenerationParams = DEFAULT_RANDOM_VALUE_GENERATION_PARAMS;
    if (args.length > 0) {
      // Override default values with user-provided arguments
      numRecords = Integer.parseInt(args[0]);
      dataTypes = Arrays.asList(args[1].split(","));
      randomValueGenerationParams = new HashMap<>();
      for (int i = 2; i < args.length; i += 2) {
        randomValueGenerationParams.put(args[i], Integer.parseInt(args[i + 1]));
      }
    }

    // Set up a centralized message broker client for forwarding processed messages
    MessageBrokerClient messageBrokerClient = new MessageBrokerClient();
    messageBrokerClient.setUrl(CENTRALIZED_MESSAGE_BROKER_URL);

    // Initialize a pool of worker threads to process incoming messages concurrently
    ExecutorService threadPool = Executors.newFixedThreadPool(numRecords / NUM_FIELDS_MULTIPLE_OF_FOUR);

    // Set up a queue for storing incoming messages and their corresponding metadata
    BlockingQueue<Message> messageQueue = new LinkedBlockingQueue<>();

    // Start the thread pool and message broker client
    threadPool.execute(new MessageProcessorThread(messageQueue, dataTypes, randomValueGenerationParams));
    messageBrokerClient.start();

    // Continuously receive messages from external messaging services and process them concurrently
    while (true) {
      List<Message> incomingMessages = retrieveIncomingMessagesFromExternalServices();
      for (Message incomingMessage : incomingMessages) {
        messageQueue.add(incomingMessage);
      }
    }
  }

  private static class MessageProcessorThread implements Runnable {
    private BlockingQueue<Message> messageQueue;
    private List<String> dataTypes;
    private Map<String, Integer> randomValueGenerationParams;

    public MessageProcessorThread(BlockingQueue<Message> messageQueue, List<String> dataTypes, Map<String, Integer> randomValueGenerationParams) {
      this.messageQueue = messageQueue;
      this.dataTypes = dataTypes;
      this.randomValueGenerationParams = randomValueGenerationParams;
    }

    @Override
    public void run() {
      while (true) {
        try {
          Message incomingMessage = messageQueue.take();
          processIncomingMessage(incomingMessage, dataTypes, randomValueGenerationParams);
        } catch (InterruptedException e) {
          // Handle interruption and stop processing messages
        }
      }
    }
  }

  private static void processIncomingMessage(Message incomingMessage, List<String> dataTypes, Map<String, Integer> randomValueGenerationParams) {
    String metadata = extractMetadata(incomingMessage);
    if (metadata == null) {
      return;
    }

    // Compute a moving average of the last ten fields and append it to the message before forwarding it to the centralized message broker
    List<Object> fields = incomingMessage.getFields();
    int numFields = fields.size();
    if (numFields % NUM_FIELDS_MULTIPLE_OF_FOUR != 0) {
      // Fill any gaps with default values to ensure the total number of fields is a multiple of four
      fields.addAll(Collections.nCopies((NUM_FIELDS_MULTIPLE_OF_FOUR - numFields) % NUM_FIELDS_MULTIPLE_OF_FOUR, DEFAULT_DATA_TYPES.get(0)));
    }

    Object[] fieldValues = fields.toArray();
    double movingAverage = computeMovingAverage(fieldValues);
    incomingMessage.setField("moving_average", movingAverage);

    // Forward the processed message to the centralized message broker in a standardized format
    messageBrokerClient.sendMessage(incomingMessage.toStandardFormat());
  }

  private static String extractMetadata(Message incomingMessage) {
    try {
      return incomingMessage.getMetadata();
    } catch (Exception e) {
      // Handle missing or corrupted messages gracefully and provide clear feedback
      System.out.println("Missing metadata in message: " + incomingMessage);
      return null;
    }
  }

  private static double computeMovingAverage(Object[] fieldValues) {
    int numFields = fieldValues.length / NUM_FIELDS_MULTIPLE_OF_FOUR;
    if (numFields == 0) {
      return 0.0;
    }

    double movingAverage = 0.0;
    for (int i = 0; i < numFields; i++) {
      Object fieldValue = fieldValues[i];
      if (fieldValue instanceof Integer) {
        movingAverage += (Integer) fieldValue;
      } else if (fieldValue instanceof Float) {
        movingAverage += (Float) fieldValue;
      } else if (fieldValue instanceof Double) {
        movingAverage += (Double) fieldValue;
      } else {
        // Handle out-of-range inputs and resource allocation failures gracefully
        System.out.println("Invalid data type in message: " + fieldValue);
        return 0.0;
      }
    }

    movingAverage /= numFields;
    return movingAverage;
  }
}
