// Struct to hold a data point with a timestamp
typedef struct {
    double value;
    time_t timestamp;
} DataPoint;

// Function to read data points from standard input and allocate memory for the array
DataPoint* readDataPoints(int num_data_points) {
    // Check if number of data points is valid
    if (num_data_points <= 0) {
        fprintf(stderr, "Error: invalid number of data points\n");
        return NULL;
    }

    // Allocate memory for the array of DataPoints
    DataPoint* data_points = malloc(sizeof(DataPoint) * num_data_points);
    if (data_points == NULL) {
        fprintf(stderr, "Error: failed to allocate memory\n");
        return NULL;
    }

    // Read data points from standard input
    for (int i = 0; i < num_data_points; ++i) {
        // Read value and timestamp from standard input
        double value;
        time_t timestamp;
        scanf("%lf %ld", &value, &timestamp);

        // Store the data point in the array
        data_points[i].value = value;
        data_points[i].timestamp = timestamp;
    }

    return data_points;
}

// Function to compute and print the average value of all data points
void computeAverage(DataPoint* data_points, int num_data_points) {
    // Initialize variables for computing the average
    double sum = 0.0;
    int count = 0;

    // Compute the average by iterating over the data points and summing their values
    for (int i = 0; i < num_data_points; ++i) {
        sum += data_points[i].value;
        count++;
    }

    // Print the average value
    printf("Average: %lf\n", sum / count);
}

