    // Allocate memory for the array of DataPoints
    DataPoint* data_points = malloc(sizeof(DataPoint) * num_data_points);
    if (data_points == NULL) {
        fprintf(stderr, "Error: failed to allocate memory\n");
        return;
    }

    // Initialize the timestamp of each data point with the current time
    for (int i = 0; i < num_data_points; ++i) {
        data_points[i].timestamp = getTimestamp();
    }
