#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a structure to store the records
typedef struct {
    int int_value;
    double double_value;
} record;

// Function to initialize and populate an array of 'record' structures
void init_records(record** records, size_t num_records) {
    // Dynamically allocate memory for the array of records
    *records = (record*)malloc(num_records * sizeof(record));
    if (*records == NULL) {
        printf("Memory allocation failed!\n");
        return;
    }

    // Initialize each record with a random integer and double value
    for (size_t i = 0; i < num_records; i++) {
        (*records)[i].int_value = rand() % INT_MAX;
        (*records)[i].double_value = ((double)rand()) / RAND_MAX;
    }
}

// Function to find and print the largest integer and smallest double in an array of 'record' structures
void find_largest_smallest(const record* records, size_t num_records) {
    // Initialize variables to store the largest and smallest values
    int largest_int = INT_MIN;
    double smallest_double = DBL_MAX;

    // Iterate over each record and update the largest and smallest values as needed
    for (size_t i = 0; i < num_records; i++) {
        if ((*records)[i].int_value > largest_int) {
            largest_int = (*records)[i].int_value;
        }
        if ((*records)[i].double_value < smallest_double) {
            smallest_double = (*records)[i].double_value;
        }
    }

    // Print the results
    printf("Largest integer: %d\n", largest_int);
    printf("Smallest double: %f\n", smallest_double);
}

// Function to validate input sizes and handle memory allocation failures gracefully
void process_input(const int* num_records, size_t max_records) {
    // Validate the number of records is within the allowed range
    if (*num_records < 1 || *num_records > max_records) {
        printf("Invalid number of records: %d\n", *num_records);
        return;
    }

    // Allocate memory for the array of records
    record* records = (record*)malloc(*num_records * sizeof(record));
    if (records == NULL) {
        printf("Memory allocation failed!\n");
        return;
    }

    // Initialize and populate the array of records
    init_records(&records, *num_records);

    // Find and print the largest integer and smallest double in the array of records
    find_largest_smallest(records, *num_records);

    // Free the memory allocated for the array of records
    free(records);
}

// Main function to demonstrate usage of the process_input function
int main() {
    int num_records = 10;
    process_input(&num_records, 50);
    return 0;
}
