int manage_memory(int numOffsets, int numKeys, int numRecords) {
    // Validate input parameters
    if (numOffsets < 0 || numKeys < 0 || numRecords < 0) {
        return -1;
    }

    // Allocate memory for offsets array
    long *offsets = malloc(sizeof(long) * numOffsets);
    if (!offsets) {
        return -2;
    }

    // Initialize offsets to 0
    memset(offsets, 0, sizeof(long) * numOffsets);

    // Allocate memory for keys array
    int *keys = malloc(sizeof(int) * numKeys);
    if (!keys) {
        free(offsets);
        return -3;
    }

    // Initialize keys to unique sequential integers starting from 1
    for (int i = 0; i < numKeys; i++) {
        keys[i] = i + 1;
    }

    // Allocate memory for record array
    struct record *records = malloc(sizeof(struct record) * numRecords);
    if (!records) {
        free(offsets);
        free(keys);
        return -4;
    }

    // Initialize records with random values between 1 and 1000, and valid offsets
    for (int i = 0; i < numRecords; i++) {
        int value = rand() % 1000 + 1;
        unsigned long offset = i % numOffsets;
        records[i].value = value;
        records[i].offset = offset;
    }

    // Return the pointer to the first element of the record array, or an error code if allocation fails
    return (void *)records;
}

