// MemoryPool.h
#ifndef MEMORY_POOL_H
#define MEMORY_POOL_H

#include <stdlib.h>
#include <string.h>
#include <stdint.h>

typedef struct {
    void* data;
    size_t capacity;
    size_t size;
} MemoryPool;

void memoryPoolCreate(MemoryPool* pool, size_t capacity);
void memoryPoolDestroy(MemoryPool* pool);
void* memoryPoolAllocate(MemoryPool* pool, size_t size);
void memoryPoolFree(MemoryPool* pool, void* data);

#endif // MEMORY_POOL_H

// MemoryPool.c
#include "MemoryPool.h"

#define DEFAULT_CAPACITY 1024

void memoryPoolCreate(MemoryPool* pool, size_t capacity) {
    pool->capacity = (capacity == 0) ? DEFAULT_CAPACITY : capacity;
    pool->size = 0;
    pool->data = malloc(pool->capacity * sizeof(char));
}

void memoryPoolDestroy(MemoryPool* pool) {
    free(pool->data);
}

void* memoryPoolAllocate(MemoryPool* pool, size_t size) {
    if (pool->size + size > pool->capacity) {
        // Reallocate the memory pool to ensure enough space for the allocation
        pool->capacity *= 2;
        pool->data = realloc(pool->data, pool->capacity * sizeof(char));
    }

    void* data = pool->data + pool->size;
    pool->size += size;

    return data;
}

void memoryPoolFree(MemoryPool* pool, void* data) {
    // Nothing to do, since we don't keep track of individual allocations
}

