void arrayCreate(Array* array, size_t initialCapacity) {
    array->capacity = (initialCapacity == 0) ? 1 : initialCapacity;
    array->count = 0;
    array->data = malloc(array->capacity * sizeof(char));
}

void arrayDestroy(Array* array) {
    free(array->data);
}

size_t arraySize(const Array* array) {
    return array->count;
}

void* arrayGet(const Array* array, size_t index) {
    if (index < 0 || index >= array->count) {
        return NULL;
    }

    return (char*)array->data + index * sizeof(char);
}

void arrayAdd(Array* array, void* value) {
    // Check if the current capacity is sufficient to hold the new element
    if (array->count == array->capacity) {
        // Reallocate the memory pool to ensure enough space for the addition
        array->capacity *= 2;
        array->data = realloc(array->data, array->capacity * sizeof(char));
    }

    memcpy((char*)array->data + (array->count++) * sizeof(char), value, sizeof(char));
}

