void insertSensorReading(const struct SensorReading* reading) {
  // Dynamically allocate memory for the new reading
  size_t readingsCapacity = sizeof(struct SensorReading) * 50000000;
  void* readingsMemory = malloc(readingsCapacity);
  if (readingsMemory == NULL) {
    // Handle error: unable to allocate memory for the readings
    return;
  }

  // Update the readings buffer with the new reading
  struct SensorReading* readings = readingsMemory;
  size_t numReadings = sizeof(readings) / sizeof(struct SensorReading);
  if (numReadings >= 50000000) {
    // Handle error: exceeded maximum capacity for the readings buffer
    return;
  }
  readings[numReadings++] = *reading;

  // Update the metadata buffer with the new reading's metadata
  size_t metadataCapacity = sizeof(char*) * 50000000;
  void* metadataMemory = malloc(metadataCapacity);
  if (metadataMemory == NULL) {
    // Handle error: unable to allocate memory for the metadata buffer
    return;
  }

  char** metadata = metadataMemory;
  size_t numMetadata = sizeof(metadata) / sizeof(char*);
  if (numMetadata >= 50000000) {
    // Handle error: exceeded maximum capacity for the metadata buffer
    return;
  }
  metadata[numMetadata++] = reading->metadata;

  // Update the timestamp buffer with the new reading's timestamp
  size_t timestampCapacity = sizeof(time_t) * 50000000;
  void* timestampMemory = malloc(timestampCapacity);
  if (timestampMemory == NULL) {
    // Handle error: unable to allocate memory for the timestamp buffer
    return;
  }

  time_t* timestamps = timestampMemory;
  size_t numTimestamps = sizeof(timestamps) / sizeof(time_t);
  if (numTimestamps >= 50000000) {
    // Handle error: exceeded maximum capacity for the timestamp buffer
    return;
  }
  timestamps[numTimestamps++] = reading->timestamp;

  // Update the sensor ID buffer with the new reading's sensor ID
  size_t sensorIDCapacity = sizeof(uint32_t) * 50000000;
  void* sensorIDMemory = malloc(sensorIDCapacity);
  if (sensorIDMemory == NULL) {
    // Handle error: unable to allocate memory for the sensor ID buffer
    return;
  }

  uint32_t* sensorIDs = sensorIDMemory;
  size_t numSensorIDs = sizeof(sensorIDs) / sizeof(uint32_t);
  if (numSensorIDs >= 50000000) {
    // Handle error: exceeded maximum capacity for the sensor ID buffer
    return;
  }
  sensorIDs[numSensorIDs++] = reading->sensorID;
}
