void process_strings(int max_len) {
    // Initialize an array of records with the given maximum length
    Record *records = malloc(sizeof(Record) * max_len);
    if (records == NULL) {
        printf("Error: Out of memory\n");
        return;
    }

    // Read input strings and store them in the records array
