        records[i].str = strdup(str);
        records[i].len = strlen(records[i].str);
    }

    // Validate the input strings and handle memory allocation failures
    for (int i = 0; i < max_len; i++) {
        if (records[i].str == NULL) {
            printf("Error: Out of memory\n");
            break;
        } else if (records[i].len > max_len) {
            printf("Error: String length exceeds maximum size\n");
            break;
        }
    }

    // Print the longest string in the array of records
    Record *longest = NULL;
    for (int i = 0; i < max_len; i++) {
        if (records[i].len > longest) {
            longest = &records[i];
        }
    }
    printf("Longest string: %s\n", longest->str);

    // Sort the records based on their string lengths in descending order
    qsort(records, max_len, sizeof(Record), compare_length);

    // Allow the user to specify a subset size of records to process
    int subset = 0;
    printf("Enter subset size (0 for all): ");
    scanf("%d", &subset);
    if (subset == 0) {
        subset = max_len;
    } else if (subset > max_len) {
        printf("Error: Subset size exceeds total number of records\n");
        return;
    }

    // Serialize the sorted subset of records to disk using a custom binary format
    FILE *file = fopen("records.bin", "wb");
    if (file == NULL) {
        printf("Error: Failed to open file for writing\n");
        return;
    }
    fwrite(records, sizeof(Record), subset, file);
    fclose(file);

    // Incorporate a helper function to identify and print the longest string in the array of records
    printf("Longest string: %s\n", get_longest_string(records, subset));

    // Free memory allocated for the records array
    free(records);
}

// Helper function to sort records based on their string lengths in descending order
int compare_length(const void *a, const void *b) {
    Record *record_a = (Record *)a;
    Record *record_b = (Record *)b;
    return record_a->len - record_b->len;
}

// Helper function to identify and print the longest string in the array of records
char *get_longest_string(Record *records, int subset) {
    Record *longest = NULL;
    for (int i = 0; i < subset; i++) {
        if (records[i].len > longest->len) {
            longest = &records[i];
        }
    }
    return longest->str;
}
