#include <pthread.h>

// Define the record structure to hold either an integer or a string
typedef struct {
    int type; // 0 for integer, 1 for string
    union {
        int i;
        char *s;
    };
} Record;

// Define the data structure to hold all records
typedef struct {
    int num_records;
    int min_value;
    int max_value;
    int string_length;
    Record *records;
} DataStructure;

// Define the function prototype for serialization
void serialize(DataStructure *ds, const char *filename);

// Define the function prototype for deserialization
void deserialize(const char *filename, DataStructure **ds);

// Define the function to initialize a new record with random values
void init_record(Record *r, int type, int min_value, int max_value, int string_length, unsigned seed) {
    // Initialize the record's type
    r->type = type;

    // Generate a random value within the specified range
    if (type == 0) {
        r->i = rand_r(&seed) % (max_value - min_value + 1) + min_value;
    } else {
        char *s = malloc(string_length);
        for (int i = 0; i < string_length; i++) {
            s[i] = rand_r(&seed) % ('Z' - 'A') + 'A';
        }
        r->s = s;
    }
}

// Define the function to allocate memory for a new record
void alloc_record(Record *r, int type, int min_value, int max_value, int string_length) {
    // Allocate memory for the integer or string
    if (type == 0) {
        r->i = malloc(sizeof(int));
    } else {
        r->s = malloc(string_length * sizeof(char));
    }
}

// Define the function to free memory for a record
void free_record(Record *r, int type) {
    // Free the integer or string
    if (type == 0) {
        free(r->i);
    } else {
        free(r->s);
    }
}

// Define the function to allocate memory for all records in a data structure
void alloc_records(DataStructure *ds, int num_records, int min_value, int max_value, int string_length) {
    // Allocate memory for each record
    ds->records = malloc(num_records * sizeof(Record));
    for (int i = 0; i < num_records; i++) {
        alloc_record(&ds->records[i], ds->type, min_value, max_value, string_length);
    }
}

// Define the function to free memory for all records in a data structure
void free_records(DataStructure *ds) {
    // Free each record's memory
    for (int i = 0; i < ds->num_records; i++) {
        free_record(&ds->records[i], ds->type);
    }
}

// Define the function to initialize a data structure with random records
void init_data(DataStructure *ds, int num_records, int min_value, int max_value, int string_length, unsigned seed) {
    // Initialize the data structure's properties
    ds->num_records = num_records;
    ds->min_value = min_value;
    ds->max_value = max_value;
    ds->string_length = string_length;

    // Allocate memory for all records
    alloc_records(ds, num_records, min_value, max_value, string_length);

    // Initialize each record with a random value
    for (int i = 0; i < ds->num_records; i++) {
        init_record(&ds->records[i], ds->type, min_value, max_value, string_length, seed + i);
    }
}

// Define the function to free a data structure's memory
void free_data(DataStructure *ds) {
    // Free each record's memory
    free_records(ds);
}

// Define the function to serialize a data structure to a file
void serialize(DataStructure *ds, const char *filename) {
    // Open the output file for writing
    FILE *out = fopen(filename, "w");

    // Write the number of records to the file
    fprintf(out, "%d\n", ds->num_records);

    // Write each record to the file
    for (int i = 0; i < ds->num_records; i++) {
        if (ds->type == 0) {
            fprintf(out, "%d ", ds->records[i].i);
        } else {
            fprintf(out, "%s", ds->records[i].s);
        }
    }

    // Close the output file
    fclose(out);
}

// Define the function to deserialize a data structure from a file
void deserialize(const char *filename, DataStructure **ds) {
    // Open the input file for reading
    FILE *in = fopen(filename, "r");

    // Read the number of records from the file
    int num_records;
    fscanf(in, "%d", &num_records);

    // Allocate memory for the data structure
    *ds = malloc(sizeof(DataStructure));
    (*ds)->num_records = num_records;
    alloc_records(*ds, num_records);

    // Read each record from the file and store it in the data structure
    for (int i = 0; i < num_records; i++) {
        if ((*ds)->type == 0) {
            fscanf(in, "%d", &(*ds)->records[i].i);
        } else {
            fscanf(in, "%s", (*ds)->records[i].s);
        }
    }

    // Close the input file
    fclose(in);
}
