#include <atomic>

struct record {
    int value;
};

struct sensor_metadata {
    char device_id[10];
    uint32_t timestamp;
};

struct temperature_reading {
    float reading;
};

struct data_structures {
    long *offset_array;
    int *key_array;
    struct record *record_array;
    struct sensor_metadata *sensor_metadata;
    float *temperature_readings;
};

struct data_structures allocate_memory(int num_records, int seed) {
    // Initialize random number generator with the given seed
    srand(seed);

    // Allocate memory for offset array
    long *offset_array = (long *)malloc(num_records * sizeof(long));
    if (offset_array == NULL) {
        printf("Memory allocation failed for offset array\n");
        exit(1);
    }

    // Allocate memory for key array
    int *key_array = (int *)malloc(num_records * sizeof(int));
    if (key_array == NULL) {
        printf("Memory allocation failed for key array\n");
        free(offset_array);
        exit(1);
    }

    // Allocate memory for record array
    struct record *record_array = (struct record *)malloc(num_records * sizeof(struct record));
    if (record_array == NULL) {
        printf("Memory allocation failed for record array\n");
        free(offset_array);
        free(key_array);
        exit(1);
    }

    // Allocate memory for sensor metadata
    struct sensor_metadata *sensor_metadata = (struct sensor_metadata *)malloc(num_records * sizeof(struct sensor_metadata));
    if (sensor_metadata == NULL) {
        printf("Memory allocation failed for sensor metadata\n");
        free(offset_array);
        free(key_array);
        free(record_array);
        exit(1);
    }

    // Allocate memory for temperature readings
    float *temperature_readings = (float *)malloc(num_records * sizeof(float));
    if (temperature_readings == NULL) {
        printf("Memory allocation failed for temperature readings\n");
        free(offset_array);
        free(key_array);
        free(record_array);
        free(sensor_metadata);
        exit(1);
    }

    // Initialize offset array with random values
    for (int i = 0; i < num_records; ++i) {
        offset_array[i] = rand() % 100 + 1;
    }

    // Initialize key array with random values
    for (int i = 0; i < num_records; ++i) {
        key_array[i] = rand() % 100 + 1;
    }

    // Initialize record array with random values
    for (int i = 0; i < num_records; ++i) {
        record_array[i].value = rand() % 100 + 1;
    }

    // Initialize sensor metadata array with random values
    for (int i = 0; i < num_records; ++i) {
        snprintf(sensor_metadata[i].device_id, sizeof(sensor_metadata[i].device_id), "device%d", i);
        sensor_metadata[i].timestamp = time(NULL);
    }

    // Initialize temperature readings array with random values based on a Gaussian distribution
    for (int i = 0; i < num_records; ++i) {
        temperature_readings[i] = rand() % 100 + 1 + ((double)rand() / (RAND_MAX)) * 5 - 2.5;
    }

    struct data_structures data = {
        .offset_array = offset_array,
        .key_array = key_array,
        .record_array = record_array,
        .sensor_metadata = sensor_metadata,
        .temperature_readings = temperature_readings
    };

    return data;
}

void free_memory(struct data_structures *data) {
    // Free memory for offset array
    if (data->offset_array != NULL) {
        free(data->offset_array);
    }

    // Free memory for key array
    if (data->key_array != NULL) {
        free(data->key_array);
    }

    // Free memory for record array
    if (data->record_array != NULL) {
        free(data->record_array);
    }

    // Free memory for sensor metadata array
    if (data->sensor_metadata != NULL) {
        free(data->sensor_metadata);
    }

    // Free memory for temperature readings array
    if (data->temperature_readings != NULL) {
        free(data->temperature_readings);
    }
}

void update_record(struct data_structures *data, int index, struct record new_record) {
    // Lock the record to prevent race conditions
    pthread_mutex_lock(&data->record_array[index].mutex);

    // Update the record with the new value
    data->record_array[index] = new_record;

    // Unlock the record to allow other threads to access it
    pthread_mutex_unlock(&data->record_array[index].mutex);
}

void update_sensor_metadata(struct data_structures *data, int index, struct sensor_metadata new_metadata) {
    // Lock the metadata to prevent race conditions
    pthread_mutex_lock(&data->sensor_metadata[index].mutex);

    // Update the metadata with the new values
    data->sensor_metadata[index] = new_metadata;

    // Unlock the metadata to allow other threads to access it
    pthread_mutex_unlock(&data->sensor_metadata[index].mutex);
}

void update_temperature_reading(struct data_structures *data, int index, float new_reading) {
    // Lock the temperature reading to prevent race conditions
    sem_wait(&data->temperature_readings[index].semaphore);

    // Update the temperature reading with the new value
    data->temperature_readings[index] = new_reading;

    // Signal that the temperature reading is available for other threads to access
    sem_post(&data->temperature_readings[index].semaphore);
}

int main() {
    struct data_structures data = allocate_memory(10, 42);

    // Update record at index 5 with a new value
    update_record(&data, 5, (struct record){.value = 10});

    // Update sensor metadata at index 3 with a new device ID and timestamp
    update_sensor_metadata(&data, 3, (struct sensor_metadata){.device_id = "device5", .timestamp = time(NULL)});

    // Update temperature reading at index 8 with a new value
    update_temperature_reading(&data, 8, 20.0f);

    free_memory(&data);

    return 0;
}
