    // Allocate memory for the array of activities
    activities = (Activity *)malloc(numActivities * sizeof(Activity));
    if (!activities) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize the array of activities with default values
    for (int i = 0; i < numActivities; i++) {
        activities[i].timestamp = -1;
        activities[i].eventType = -1;
        activities[i].priorityLevel = defaultPriorityLevel;
    }

    // Set the rolling time window for generating timestamps
    long currentTime = time(NULL);
    long oldestAllowedTimestamp = currentTime - rollingTimeWindow;

    // Iterate over the array of activities and update their timestamps
    for (int i = 0; i < numActivities; i++) {
        if (activities[i].timestamp == -1 || activities[i].timestamp < oldestAllowedTimestamp) {
            activities[i].timestamp = currentTime;
        }
    }

    // Free the memory allocated for the array of activities
    free(activities);
}

