Here is a sample implementation of the C function that dynamically allocates memory for and initializes three arrays: one for 'long' offset values, one for 'int' keys, and another for 'record' structures containing a 'double' value and a 'char' status flag. The function also allows the user to specify the number of records to be initialized, the minimum and maximum values for the random range, and manages memory allocation failures gracefully.
```c
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Structure for record data
typedef struct {
    double value;
    char status;
} record_t;

// Function to initialize the arrays and populate with random values
void init_arrays(int num_records, int min_value, int max_value) {
    // Allocate memory for offset array
    long *offset_arr = malloc(num_records * sizeof(long));
    if (!offset_arr) {
        printf("Error: Failed to allocate memory for offset array\n");
        return;
    }

    // Initialize offset array with random values
    srand((unsigned int)time(NULL));
    for (int i = 0; i < num_records; i++) {
        offset_arr[i] = min_value + rand() % (max_value - min_value + 1);
    }

    // Allocate memory for key array
    int *key_arr = malloc(num_records * sizeof(int));
    if (!key_arr) {
        printf("Error: Failed to allocate memory for key array\n");
        free(offset_arr);
        return;
    }

    // Initialize key array with random values
    for (int i = 0; i < num_records; i++) {
        key_arr[i] = rand() % max_value + 1;
    }

    // Allocate memory for record structures and populate with random values
    record_t *record_arr = malloc(num_records * sizeof(record_t));
    if (!record_arr) {
        printf("Error: Failed to allocate memory for record array\n");
        free(offset_arr);
        free(key_arr);
        return;
    }

    // Initialize record structures with random values and status flags
    for (int i = 0; i < num_records; i++) {
        record_arr[i].value = offset_arr[i] + key_arr[i];
        if (record_arr[i].value % 2 == 0) {
            record_arr[i].status = 'A'; // active
        } else {
            record_arr[i].status = 'I'; // inactive
        }
    }

    // Free memory for arrays and return
    free(offset_arr);
    free(key_arr);
    free(record_arr);
}
