function getPrimeNumber($max) {
  // Initialize an empty array to store the prime numbers
  $primeNumbers = [];

  // Loop through each number between MIN_RANGE and MAX_RANGE
  for ($i = MIN_RANGE; $i <= $max; $i++) {
    // Check if the current number is a prime number
