      // Add the prime number to the array
      $primeNumbers[] = $i;
    }
  }

  return $primeNumbers;
}

// Define a function to check if a number is a prime number
function isPrimeNumber($num) {
  // Check if the current number is divisible by any other number between MIN_RANGE and MAX_RANGE
  for ($i = MIN_RANGE; $i <= sqrt($num); $i++) {
    if ($num % $i == 0) {
      return false;
    }
  }

  return true;
}

// Define a function to generate random numeric values between 0 and 1
