  // Initialize an empty array to store the filtered records
  $matches = [];

  // Loop through each filter criterion and check if it matches the current record
  foreach ($filterCriteria as $criterion) {
    // Check if the current record matches the specified filter criteria
    if (matchFilterCriterion($record, $criterion)) {
      // Add the record to the filtered records array
      $matches[] = $record;
    }
  }

  return $matches;
}

// Define a function to check if a record matches a specific filter criterion
function matchFilterCriterion($record, $criterion) {
  // Check if the current record's attribute matches the specified value
  if ($record[$criterion['attribute']] == $criterion['value']) {
    return true;
  }

  return false;
}

// Define a function to update an existing record with new values
function updateRecord($record, $attributes) {
  // Initialize an empty array to store the updated attributes
  $updatedAttributes = [];

  // Loop through each attribute and check if it needs to be updated
  foreach ($attributes as $attribute => $value) {
    // Check if the current attribute exists in the record
    if (isset($record[$attribute])) {
      // Update the current attribute with the new value
      $updatedAttributes[$attribute] = $value;
    } else {
      // Add the new attribute to the updated attributes array
      $updatedAttributes[$attribute] = $value;
    }
  }

  return $updatedAttributes;
}

// Define a function to delete an existing record and retrieve its default values
function deleteRecord($record) {
  // Initialize an empty array to store the deleted attributes
  $deletedAttributes = [];

  // Loop through each attribute and check if it needs to be deleted
  foreach ($record as $attribute => $value) {
    // Check if the current attribute is a primary key
    if (isPrimaryKey($attribute)) {
      // Delete the current attribute from the record
      unset($record[$attribute]);

      // Add the deleted attribute to the array
      $deletedAttributes[] = $attribute;
    }
  }

  return $deletedAttributes;
}

// Define a function to check if an attribute is a primary key
function isPrimaryKey($attribute) {
  // Check if the current attribute ends with "ID" or "PK"
  if (endsWith($attribute, 'ID') || endsWith($attribute, 'PK')) {
    return true;
  }

  return false;
}

// Define a function to check if a string ends with another string
function endsWith($string, $endString) {
  // Check if the current string ends with the specified end string
  if (strpos($string, $endString) === strlen($string) - strlen($endString)) {
    return true;
  }

  return false;
}
