// Define the record structure to hold either an int or a string
typedef struct {
    void* data; // Pointer to either an int or a string
    size_t size; // Size of the data in bytes
} Record;

// Function to initialize an array of records from a network socket connection
void init_records(int fd, size_t num_records, bool randomize, bool use_strings, int range, size_t string_length) {
    // Check the input parameters for validity
    assert(num_records > 0 && range >= 0 && string_length > 0);

    // Allocate memory for the array of records
    Record* records = malloc(sizeof(Record) * num_records);

    // Initialize each record with either a random integer or a random string
    for (size_t i = 0; i < num_records; ++i) {
        if (use_strings) {
            char* str = malloc(string_length + 1);
            if (randomize) {
                // Generate a random string within the specified range
                for (size_t j = 0; j < string_length; ++j) {
                    str[j] = 'a' + rand() % ('z' - 'a');
                }
            } else {
                // Initialize the string with a specific length
                memset(str, 'a', string_length);
                str[string_length] = '\0';
            }
            records[i].data = str;
            records[i].size = string_length;
        } else {
            int* num = malloc(sizeof(int));
            if (randomize) {
                // Generate a random integer within the specified range
                *num = rand() % range;
            } else {
                // Initialize the integer with a specific value
                *num = 0;
            }
            records[i].data = num;
            records[i].size = sizeof(int);
        }
    }

    // Filter the records based on specific criteria
    if (use_strings && string_length > 0) {
        for (size_t i = 0; i < num_records; ++i) {
            char* str = (char*)records[i].data;
            size_t len = records[i].size;
            if (len <= string_length && str[len] == '\0') {
                // Filter out strings that are shorter than the specified length
                free(str);
                records[i].data = NULL;
                records[i].size = 0;
            } else if (len > string_length) {
                // Truncate longer strings to the specified length
                str[string_length] = '\0';
            }
        }
    } else if (!use_strings && range > 0) {
        for (size_t i = 0; i < num_records; ++i) {
            int* num = (int*)records[i].data;
            size_t len = records[i].size;
            if (*num >= range || *num <= -range) {
                // Filter out numbers that are outside the specified range
                free(num);
                records[i].data = NULL;
                records[i].size = 0;
            } else {
                // Truncate larger numbers to fit within the specified range
                *num = *num % range;
            }
        }
    }

    // Find and print the largest integer in the array of records if they are integers, or the longest string if they are strings
    size_t max_index = 0;
    for (size_t i = 1; i < num_records; ++i) {
        if (use_strings && records[max_index].size == 0 && records[i].size > 0) {
            // If we are filtering out strings, the longest string is the largest index
            max_index = i;
        } else if (!use_strings && records[max_index].data != NULL && records[i].data == NULL) {
            // If we are filtering out integers, the largest integer is the largest index
            max_index = i;
        } else if (records[max_index].size > 0 && records[i].size > 0) {
            // Compare the sizes of the current record and the previous maximum
            size_t curr_len = records[i].size;
            size_t prev_len = records[max_index].size;
            if (curr_len > prev_len) {
                max_index = i;
            }
        } else if (records[max_index].data != NULL && records[i].data != NULL) {
            // Compare the values of the current record and the previous maximum
            int* curr_num = (int*)records[i].data;
            int* prev_num = (int*)records[max_index].data;
            if (*curr_num > *prev_num) {
                max_index = i;
            }
        }
    }
    // Print the largest integer or string in the array of records
    if (use_strings && records[max_index].size > 0) {
        printf("%s\n", (char*)records[max_index].data);
    } else if (!use_strings && records[max_index].data != NULL) {
        printf("%d\n", *(int*)records[max_index].data);
    }
}

// Helper function to free the memory allocated for an array of records
void free_records(Record* records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        void* data = records[i].data;
        if (data != NULL) {
            free(data);
        }
    }
    free(records);
}
