int processList(char* inputString, int numRecords, Record** records) {
    // Split the input string into individual integers
    char* token = strtok(inputString, ",");
    while (token != NULL) {
        // Allocate memory for a new record structure and initialize it with the current integer value
        Record* record = malloc(sizeof(Record));
