char* read_line(FILE* fp) {
    char* line = NULL;
    size_t len = 0;
    ssize_t read;

    // Allocate memory for the line
    if ((read = getline(&line, &len, fp)) == -1) {
        return NULL;
    }

    // Remove newline character from end of line
