    char* line = malloc(strlen(r->name) + 20);
    sprintf(line, "%s,%f", r->name, avg);

    // Print the processed record
    printf("%s\n", line);
}

// Function to read and process records from multiple text files concurrently
void read_and_process_records(int num_files, char** file_names) {
    // Open all the files for reading
    FILE* fp[num_files];
    for (int i = 0; i < num_files; i++) {
        if ((fp[i] = fopen(file_names[i], "r")) == NULL) {
            perror("fopen");
            exit(EXIT_FAILURE);
        }
    }

    // Read and process records concurrently from all files
    while (1) {
        // Read a line from each file
        char* lines[num_files];
        for (int i = 0; i < num_files; i++) {
            lines[i] = read_line(fp[i]);
            if (!lines[i]) {
                break;
            }
        }

        // Process the records
        for (int i = 0; i < num_files; i++) {
            Record* r = malloc(sizeof(Record));
            sscanf(lines[i], "%d %s", &r->id, r->name);
            process_record(r);
            free(r);
        }
    }
}
```
This function takes the number of text files to read from as an argument, and an array of file names. It opens each file for reading using `fopen`, reads a line at a time using `read_line` and `getline`, processes the records using `process_record`, and frees the memory used by the records using `free`. The function also includes error handling to handle cases where the files cannot be opened, lines cannot be read, or there are issues with memory allocation.

Here is an example of how to use this function:
