memory_pool create_memory_pool(int numOffsets, int minKey, int maxKey) {
    // Validate input parameters
    if (numOffsets <= 0 || minKey >= maxKey) {
        printf("Invalid input parameters\n");
        return NULL;
    }

    // Initialize memory pool
    memory_pool* pool = malloc(sizeof(memory_pool));
    if (!pool) {
        printf("Failed to allocate memory for memory pool\n");
        return NULL;
    }

    // Allocate memory for offsets array
    pool->offsets = malloc(numOffsets * sizeof(long));
    if (!pool->offsets) {
        printf("Failed to allocate memory for offsets array\n");
        free(pool);
        return NULL;
    }

    // Initialize offsets array with unique sequential values starting from 0
    int i;
    for (i = 0; i < numOffsets; i++) {
        pool->offsets[i] = i;
    }

    // Allocate memory for keys array
    pool->keys = malloc(numOffsets * sizeof(int));
    if (!pool->keys) {
        printf("Failed to allocate memory for keys array\n");
        free(pool->offsets);
        free(pool);
        return NULL;
    }

    // Initialize keys array with random values within the specified range
    srand((unsigned int)time(NULL));
    for (i = 0; i < numOffsets; i++) {
        pool->keys[i] = rand() % (maxKey - minKey + 1) + minKey;
    }

    // Allocate memory for records array
    pool->records = malloc(numOffsets * sizeof(record*));
    if (!pool->records) {
        printf("Failed to allocate memory for records array\n");
        free(pool->offsets);
        free(pool->keys);
        free(pool);
        return NULL;
    }

    // Initialize records array with pointers to offsets and keys values
    for (i = 0; i < numOffsets; i++) {
        pool->records[i] = malloc(sizeof(record));
        if (!pool->records[i]) {
            printf("Failed to allocate memory for record %d\n", i);
            free(pool->offsets);
            free(pool->keys);
            free(pool);
            return NULL;
        }
        pool->records[i]->offset = &(pool->offsets[i]);
        pool->records[i]->key = pool->keys[i];
    }

    // Return the initialized memory pool
    return pool;
}

void destroy_memory_pool(memory_pool* pool) {
    if (!pool) {
        return;
    }

    // Free offsets array and keys array
    free(pool->offsets);
    free(pool->keys);

    // Free records array and the structures it contains
    int i;
    for (i = 0; i < pool->numOffsets; i++) {
        free(pool->records[i]);
    }
    free(pool->records);

    // Free memory pool
    free(pool);
}
```
