using namespace std;

struct CombatRecord {
    int attackNumber;
};

void orchestrateCombatSequence(int minValue, int maxValue, int minCooldown, int maxCharacters) {
    // Initialize vector of CombatRecord objects
    vector<CombatRecord> combatRecords(maxCharacters);

    // Generate random attack numbers within specified range
    for (int i = 0; i < maxCharacters; i++) {
        combatRecords[i].attackNumber = rand() % (maxValue - minValue + 1) + minValue;
    }

    // Implement cooldown mechanism
    int currentAttack = 0;
    time_t lastUsedTime = time(nullptr);
    while (true) {
        // Check if cooldown period has passed
        if ((time(nullptr) - lastUsedTime) >= minCooldown) {
            // Select new attack number
            currentAttack = rand() % (maxValue - minValue + 1) + minValue;
            while (currentAttack == combatRecords[currentAttack].attackNumber) {
                currentAttack = rand() % (maxValue - minValue + 1) + minValue;
            }
            lastUsedTime = time(nullptr);
        }

        // Print selected attack number and timestamp to console
        cout << "Attack #" << combatRecords[currentAttack].attackNumber << " at " << ctime(&lastUsedTime) << endl;

        // Wait for next turn
    }
}
