    for (size_t i = 0; i < n; i++) {
        // allocate memory for each string dynamically
        large_arr[i] = rand() % 100000000;
        small_arr[i] = rand() % 100;
        node_arr[i] = malloc(sizeof(struct node));
        if (node_arr[i] == NULL) {
            // handle memory allocation failure gracefully
            printf("Memory allocation failed for element %zu\n", i);
            exit(1);
        }
        node_arr[i]->str = malloc(sizeof(char) * 256);
        if (node_arr[i]->str == NULL) {
            // handle memory allocation failure gracefully
            printf("Memory allocation failed for string element %zu\n", i);
            exit(1);
        }
        // initialize the string with a unique value derived from a base string and a random number
        int len = snprintf(node_arr[i]->str, 256, "base-%d", large_arr[i]);
        if (len < 0 || len >= 256) {
            // handle string length overflow gracefully
            printf("String length overflow for element %zu\n", i);
            exit(1);
        }
        // compute the checksum of each unique string using SHA-256
        node_arr[i]->val = rand() % 100;
