['#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define struct for dynamic array
typedef struct {
    void **data;
    size_t count, capacity;
} DynamicArray;

// Initialize a new dynamic array with the given capacity
DynamicArray *newDynamicArray(size_t capacity) {
    DynamicArray *arr = malloc(sizeof(DynamicArray));
    arr->data = malloc(capacity * sizeof(void*));
    arr->count = 0;
    arr->capacity = capacity;
    return arr;
}

// Resize the dynamic array to the given capacity
void resizeDynamicArray(DynamicArray *arr, size_t capacity) {
    arr->data = realloc(arr->data, capacity * sizeof(void*));
    arr->capacity = capacity;
}

// Append a new value to the end of the dynamic array
void appendDynamicArray(DynamicArray *arr, void *value) {
    if (arr->count == arr->capacity) {
        resizeDynamicArray(arr, arr->capacity * 2);
    }
    arr->data[arr->count++] = value;
}

// Free the memory used by the dynamic array
void freeDynamicArray(DynamicArray *arr) {
    for (size_t i = 0; i < arr->count; i++) {
        void *value = arr->data[i];
        if (value != NULL) {
            switch (getDataType(value)) {
                case DT_INT:
                    free((int*)value);
                    break;
                case DT_FLOAT:
                    free((float*)value);
                    break;
                case DT_STRING:
                    free((char*)value);
                    break;
            }
        }
    }
    free(arr->data);
    free(arr);
}

// Return the data type of the given value
int getDataType(void *value) {
    if (value == NULL) return DT_VOID;
    switch (*(int*)value) {
        case 0:
            return DT_INT;
        case 0.0f:
            return DT_FLOAT;
        default:
            return DT_STRING;
    }
}

// Populate the dynamic array with random values for integers and floats within the specified ranges, and for strings, allocate memory and initialize them with random content up to the specified length
void populateDynamicArray(DynamicArray *arr, size_t intRange, float floatRange, size_t stringLength) {
    for (size_t i = 0; i < arr->capacity; i++) {
        void *value = NULL;
        switch (getDataType(value)) {
            case DT_INT:
                int randomInt = rand() % intRange + 1;
                value = malloc(sizeof(int));
                *(int*)value = randomInt;
                break;
            case DT_FLOAT:
                float randomFloat = (float)(rand() % (RAND_MAX / floatRange)) + 1.0f;
                value = malloc(sizeof(float));
                *(float*)value = randomFloat;
                break;
            case DT_STRING:
                char *randomString = malloc(stringLength + 1);
                for (size_t j = 0; j < stringLength; j++) {
                    int randomChar = rand() % ('z' - 'a') + 'a';
                    randomString[j] = (char)randomChar;
                }
                randomString[stringLength] = '\0';
                value = randomString;
                break;
            case DT_VOID:
                break;
        }
        appendDynamicArray(arr, value);
    }
}

int main() {
    // User input: capacity of the dynamic array
    size_t capacity;
    printf("Enter capacity of the dynamic array: ");
    scanf("%zu", &capacity);

    // Initialize the dynamic array with the given capacity
    DynamicArray *arr = newDynamicArray(capacity);

    // User input: range for integers and floats
    size_t intRange, floatRange;
    printf("Enter range for integers and floats: ");
    scanf("%zu", &intRange);
    printf("Enter range for floats: ");
    scanf("%zu", &floatRange);

    // User input: maximum length for strings
    size_t stringLength;
    printf("Enter maximum length for strings: ");
    scanf("%zu", &stringLength);

    // Populate the dynamic array with random values for integers and floats within the specified ranges, and for strings, allocate memory and initialize them with random content up to the specified length
    populateDynamicArray(arr, intRange, floatRange, stringLength);

    // Print the contents of the dynamic array
    printf("Contents of the dynamic array:\n");
    for (size_t i = 0; i < arr->count; i++) {
        void *value = arr->data[i];
        switch (getDataType(value)) {
            case DT_INT:
                printf("%d\n", *(int*)value);
                break;
            case DT_FLOAT:
                printf("%.2f\n", *(float*)value);
                break;
            case DT_STRING:
                printf("%s\n", (char*)value);
                break;
        }
    }

    // Free the memory used by the dynamic array
    freeDynamicArray(arr);

    return 0;
}']

