// Define data types to be used in the storage system
typedef enum {
    INTEGER, FLOATING_POINT, STRING, FILE_PATH, DIRECTORY_NAME
} data_type;

typedef struct {
    data_type type;
    union {
        int integer;
        float floating_point;
        char *string;
        char file_path[PATH_MAX];
        char directory_name[PATH_MAX];
    } value;
} data_record;

// Function to initialize the storage system
void init_storage(int num_records, bool randomize) {
    // Allocate memory for the array of data records
    data_record *records = (data_record *) malloc(num_records * sizeof(data_record));
    if (!records) {
        fprintf(stderr, "Error: Failed to allocate memory for %d records\n", num_records);
        exit(EXIT_FAILURE);
    }

    // Initialize the data records with random values or custom inputs
    if (randomize) {
        srand(time(NULL));
        for (int i = 0; i < num_records; i++) {
            switch (rand() % 4) {
                case INTEGER:
                    records[i].type = INTEGER;
                    records[i].integer = rand();
                    break;
                case FLOATING_POINT:
                    records[i].type = FLOATING_POINT;
                    records[i].floating_point = (float)rand() / RAND_MAX;
                    break;
                case STRING:
                    records[i].type = STRING;
                    snprintf(records[i].string, PATH_MAX, "random string %d", i);
                    break;
                default:
                    records[i].type = FILE_PATH;
                    strcpy(records[i].file_path, "/");
            }
        }
    } else {
        for (int i = 0; i < num_records; i++) {
            printf("Enter value for record %d: ", i);
            switch (rand() % 4) {
                case INTEGER:
                    scanf("%d", &(records[i].integer));
                    break;
                case FLOATING_POINT:
                    scanf("%f", &(records[i].floating_point));
                    break;
                case STRING:
                    scanf("%s", records[i].string);
                    break;
                default:
                    scanf("%s", records[i].file_path);
            }
        }
    }

    // Initialize the storage system with the initialized data records
}

// Function to read and return a data record from the storage system
data_record *read_record(int index) {
    if (index < 0 || index >= num_records) {
        fprintf(stderr, "Error: Index %d is out of bounds\n", index);
        exit(EXIT_FAILURE);
    }
    return &(records[index]);
}

// Function to write a data record into the storage system
void write_record(int index, data_record *record) {
    if (index < 0 || index >= num_records) {
        fprintf(stderr, "Error: Index %d is out of bounds\n", index);
        exit(EXIT_FAILURE);
    }
    records[index] = *record;
}

// Function to traverse a directory and list files and their paths up to a specified depth
void traverse_directory(const char *path, int depth) {
    if (depth < 0) {
        fprintf(stderr, "Error: Depth %d is out of bounds\n", depth);
        exit(EXIT_FAILURE);
    }
    DIR *dir = opendir(path);
    if (!dir) {
        perror("Error opening directory");
        exit(EXIT_FAILURE);
    }
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(".", entry->d_name) == 0 || strcmp("..", entry->d_name) == 0) {
            continue;
        }
        printf("%s\n", entry->d_name);
        char full_path[PATH_MAX];
        snprintf(full_path, PATH_MAX, "%s/%s", path, entry->d_name);
        if (strlen(full_path) > PATH_MAX - 1) {
            fprintf(stderr, "Error: Path %s is too long\n", full_path);
            exit(EXIT_FAILURE);
        }
        switch (entry->d_type) {
            case DT_DIR:
                traverse_directory(full_path, depth - 1);
                break;
            case DT_REG:
                printf("File: %s\n", full_path);
                break;
            default:
                fprintf(stderr, "Error: Unknown file type for %s\n", full_path);
                exit(EXIT_FAILURE);
        }
    }
}

// Function to manage memory allocation failures gracefully
void handle_memory_allocation_failure() {
    fprintf(stderr, "Error: Failed to allocate memory\n");
    exit(EXIT_FAILURE);
}

// Main function for the storage system
int main() {
    // Initialize the storage system with random values or custom inputs
    init_storage(num_records, randomize);

    // Read and write data records to the storage system
    while (true) {
        printf("Enter command: ");
        char input[1024];
        fgets(input, 1024, stdin);
        switch (*input) {
            case 'r':
                int index = atoi(input + 1);
                data_record *record = read_record(index);
                print_data_record(record);
                break;
            case 'w':
                int index = atoi(input + 1);
                data_record record;
                printf("Enter value for record %d: ", index);
                switch (rand() % 4) {
                    case INTEGER:
                        scanf("%d", &(record.integer));
                        break;
                    case FLOATING_POINT:
                        scanf("%f", &(record.floating_point));
                        break;
                    case STRING:
                        scanf("%s", record.string);
                        break;
                    default:
                        scanf("%s", record.file_path);
                }
                write_record(index, &record);
                break;
            case 't':
                traverse_directory("./", 10);
                break;
            default:
                fprintf(stderr, "Error: Unknown command %s\n", input);
        }
    }
    return 0;
}
```
