#include <errno.h>

typedef struct {
    double value;
    int timestamp;
    char type;
} DataPoint;

void processData(int socket_fd, size_t num_data_points, size_t num_keys, size_t num_records) {
    // Initialize memory management structures
    size_t mem_usage = 0;
    size_t mem_limit = 10 * 1024 * 1024; // 10 MB limit
    size_t* offsets = malloc(num_data_points * sizeof(size_t));
    int* keys = malloc(num_keys * sizeof(int));
    DataPoint* records = malloc(num_records * sizeof(DataPoint));

    // Initialize random seed for generating random numbers
    srand((unsigned)time(NULL));

    // Process data stream from network socket
    size_t curr_data_point = 0;
    while (curr_data_point < num_data_points) {
        // Read data point from socket
        double value;
        if (!read_double(socket_fd, &value)) {
            printf("Error reading double value from network socket\n");
            break;
        }
        int timestamp = rand() % 1000000000; // Generate random number between 0 and 1 billion
        char type = 'A'; // Assign arbitrary type for now

        // Store data point in memory
        DataPoint new_record = { value, timestamp, type };
        records[curr_data_point] = new_record;
        offsets[curr_data_point] = mem_usage;
        mem_usage += sizeof(DataPoint);
        curr_data_point++;

        // Check for memory usage and fragmentation
        if (mem_usage > mem_limit) {
            printf("Memory limit exceeded, releasing unused memory\n");
            break;
        } else if (mem_usage >= 0.9 * mem_limit) {
            printf("Memory nearing full, defragmenting...\n");
            defrag_memory(offsets, records, num_data_points);
        }
    }

    // Print average value of all valid data points
    double total = 0;
    size_t valid_count = 0;
    for (size_t i = 0; i < curr_data_point; i++) {
        if (records[i].value != -1) {
            total += records[i].value;
            valid_count++;
        }
    }
    printf("Average value: %f\n", total / valid_count);

    // Clean up memory and exit
    free(offsets);
    free(keys);
    free(records);
}

// Read double value from network socket, return false if error occurs
bool read_double(int socket_fd, double* value) {
    char buffer[1024];
    ssize_t bytes_read = recv(socket_fd, buffer, sizeof(buffer), 0);
    if (bytes_read < 0) {
        perror("recv");
        return false;
    } else if (bytes_read == 0) {
        return false;
    }
    // Parse double value from buffer
    *value = atof(buffer);
    return true;
}

// Defragment memory by releasing unused chunks and updating offset array
void defrag_memory(size_t* offsets, DataPoint* records, size_t num_data_points) {
    // Find smallest non-zero offset
    size_t min_offset = SIZE_MAX;
    for (size_t i = 0; i < num_data_points; i++) {
        if (offsets[i] > 0 && offsets[i] < min_offset) {
            min_offset = offsets[i];
        }
    }
    // Release all chunks before minimum offset
    size_t released_mem = 0;
    for (size_t i = 0; i < num_data_points; i++) {
        if (offsets[i] <= min_offset) {
            records[i].value = -1; // Mark as invalid
            released_mem += sizeof(DataPoint);
        } else {
            break;
        }
    }
    printf("Released %zu bytes of memory\n", released_mem);
}
```
