// Structure for record data
typedef struct {
    int key;
    double value;
    char* string;
} Record;

// Function to safely free all allocated memory
void freeMemory(Record** records, long* offsets, int* keys, double* values) {
    // Free the record strings
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (records[i].string != NULL) {
            free(records[i].string);
        }
    }

    // Free the arrays of pointers
    free(records);
    free(offsets);
    free(keys);
    free(values);
}

