    // Set the initial values for the arrays of pointers
    *records = malloc(sizeof(Record*) * MAX_RECORDS);
    *offsets = malloc(OFFSET_SIZE);
    *keys = malloc(KEY_SIZE);
    *values = malloc(VALUE_SIZE);

    // Initialize the arrays of pointers to NULL
    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i] = NULL;
        offsets[i] = -1;
        keys[i] = -1;
        values[i] = -1.0;
