    if (!records) {
        fprintf(stderr, "Failed to allocate memory for %d records\n", num_records);
        return NULL;
    }

    // initialize the record array
    for (int i = 0; i < num_records; ++i) {
        records[i].key = -1;
        records[i].offset = MIN_OFFSET;
        records[i].status = INITIALIZED;
    }

    return records;
}

int generate_random_key(void) {
