use std::sync::Mutex;
use std::thread;
use std::time::Instant;
use std::fs;
use std::path::Path;
use std::error::Error;
use std::io::{self, Write};

// Define the data structures to be initialized
struct Record {
    key: i32,
    value: i64,
}

struct ErrorLog {
    message: String,
}

fn initialize_data_structures(
    num_records: usize,
    range: i64,
) -> Result<(), Box<dyn Error>> {
    // Initialize the arrays using a loop
    let mut long_offsets = Vec::with_capacity(num_records);
    for _ in 0..num_records {
        long_offsets.push(rand::random::<i64>() % range + 1);
    }

    let mut int_keys = Vec::with_capacity(num_records);
    for i in 0..num_records {
        int_keys.push((long_offsets[i] as i32) * 10 + i as i32);
    }

    let mut record_structures = Vec::with_capacity(num_records);
    for _ in 0..num_records {
        record_structures.push(Record {
            key: rand::random::<i32>() % range + 1,
            value: rand::random::<i64>() % range + 1,
        });
    }

    // Initialize the string arrays
    let mut filenames = Vec::with_capacity(num_records);
    for _ in 0..num_records {
        let filename = format!("file-{}.txt", rand::random::<i32>() % range + 1);
        filenames.push(filename.to_string());
    }

    let mut error_logs = Vec::with_capacity(num_records);
    for _ in 0..num_records {
        let message = format!("error-{}.txt", rand::random::<i32>() % range + 1);
        error_logs.push(message.to_string());
    }

    // Use a mutex to ensure thread safety during initialization
    let mutex = Mutex::new(());
    let num_threads = 5;
    let handle = thread::spawn(move || {
        for i in 0..num_records {
            let mutex_guard = mutex.lock().unwrap();
            record_structures[i].key += long_offsets[i] as i32;
            record_structures[i].value *= int_keys[i];
            fs::write(Path::new(&filenames[i]), &record_structures[i].to_string()).unwrap();
        }
    });

    // Measure the initial process resource usage
    let start = Instant::now();
    handle.join().unwrap();
    let end = start.elapsed();

    println!("Initialization complete in {:?}", end);

    Ok(())
}

fn main() {
    // Define the input parameters for the function
    let num_records: usize = 5;
    let range: i64 = 100;

    // Install a custom logging hook to redirect error messages to a log file
    let mutex = Mutex::new(());
    let handle = thread::spawn(move || {
        if let Err(e) = initialize_data_structures(num_records, range) {
            let message = e.to_string();
            fs::write("error.log", &message).unwrap();
        }
    });

    handle.join().unwrap();
}
```
