int initRecords(int numRecords, int numStrings, size_t* sizes) {
    // Check if the input parameters are valid
    if (numRecords <= 0 || numStrings <= 0) {
        return -1;
    }

    // Calculate the total memory usage
    size_t totalMemoryUsage = recordSize * numRecords + stringSize * numStrings;

    // Check if the total memory usage exceeds the maximum allowed
    if (totalMemoryUsage > maxMemoryUsage) {
        return -2;
    }

    // Allocate memory for the records and strings
    Record* records = malloc(recordSize * numRecords);
    char** strings = malloc(stringSize * numStrings);

    // Check if the memory allocation failed
