class RandomValueGenerator {
 public:
  RandomValueGenerator(int min, int max) : min_(min), max_(max) {}

  int generateRandomInt() {
    std::uniform_int_distribution<> distribution(min_, max_);
    return distribution(random_engine_);
  }

  long generateRandomLong() {
    std::uniform_int_distribution<long> distribution(min_, max_);
    return distribution(random_engine_);
  }

  void setMin(int min) { min_ = min; }
  void setMax(int max) { max_ = max; }

 private:
  int min_;
  int max_;
  std::mt19937 random_engine_;
};

std::vector<Record> initializeRecords(int numRecords, int rangeMin, int rangeMax, long startTimestamp) {
  // Initialize the random value generator
  RandomValueGenerator generator(rangeMin, rangeMax);

  // Create vectors to store the offset and key values
  std::vector<long> offsets(numRecords);
  std::vector<int> keys(numRecords);
  std::vector<Record> records(numRecords);

  // Generate random values for the offset and key arrays
  for (int i = 0; i < numRecords; ++i) {
    offsets[i] = generator.generateRandomLong();
    keys[i] = generator.generateRandomInt();
  }

  // Initialize the timestamp for each record
  std::chrono::time_point<std::chrono::system_clock> currentTimestamp = startTimestamp;
  for (int i = 0; i < numRecords; ++i) {
    records[i].key = keys[i];
    records[i].offset = offsets[i];
    records[i].timestamp = currentTimestamp;
    currentTimestamp += std::chrono::milliseconds(1);
  }

  return records;
}
