    float avg = (float)sum_array(arr, n) / n;
    return avg;
}

// Define a function to find the median of an array of integers
int median(int *arr, int n) {
    if (n % 2 == 0) {
        // even number of elements
        return (arr[n / 2 - 1] + arr[n / 2]) / 2;
    } else {
        // odd number of elements
        return arr[n / 2];
    }
}

// Define a function to find the mode of an array of integers
int mode(int *arr, int n) {
    // create a hash map to store the frequency of each integer
    std::unordered_map<int, int> freq;
    for (int i = 0; i < n; i++) {
        freq[arr[i]]++;
    }
    // find the mode by looking for the key with the highest frequency
    int max_freq = 0;
    int mode = 0;
    for (auto it = freq.begin(); it != freq.end(); it++) {
        if (it->second > max_freq) {
            max_freq = it->second;
            mode = it->first;
        }
    }
    return mode;
}

// Define a function to find the standard deviation of an array of integers
float std_dev(int *arr, int n) {
    float avg = (float)sum_array(arr, n) / n;
    float sum = 0;
    for (int i = 0; i < n; i++) {
        sum += pow((arr[i] - avg), 2);
    }
    return sqrt(sum / (n - 1));
}

// Define a function to find the range of an array of integers
int range(int *arr, int n) {
    int min = arr[0];
    int max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max) {
            max = arr[i];
        } else if (arr[i] < min) {
            min = arr[i];
        }
    }
    return max - min;
}

