record* allocate_records(int size) {
    record* records = malloc(size * sizeof(record));
    if (!records) {
        printf("Error: failed to allocate memory for records\n");
        exit(1);
    }
    return records;
}

// Function to deallocate an array of records
void deallocate_records(record* records, int size) {
    free(records);
}

// Function to find and print the largest integer or longest string in the array
void find_largest_or_longest(record* records, int size) {
    int largest = INT_MIN;
    char* longest = "";
    for (int i = 0; i < size; i++) {
        if (records[i].value > largest) {
            largest = records[i].value;
        }
        if (strlen(records[i].string) > strlen(longest)) {
            longest = records[i].string;
        }
    }
    printf("Largest value: %d\n", largest);
    printf("Longest string: %s\n", longest);
}

// Main function that reads the list of integers and strings from standard input
int main() {
    // Initialize an array of records with a size of 10
    int size = 10;
    record* records = allocate_records(size);

    // Read the values from standard input and initialize each record
    for (int i = 0; i < size; i++) {
        printf("Enter value #%d: ", i + 1);
        scanf("%d", &records[i].value);
        printf("Enter string #%d: ", i + 1);
        scanf("%s", records[i].string, sizeof(records[i].string));
    }

    // Find and print the largest integer or longest string in the array
    find_largest_or_longest(records, size);

    // Deallocate the memory for the array of records
    deallocate_records(records, size);

    return 0;
}
