using namespace std;

// Define a structure to represent each record
struct Record {
  int integer_field;
  char* string_field;
};

int main() {
  // Initialize variables for number of records and data type
  int num_records = 0;
  char data_type = 'i'; // can be 'i' or 's' for integers or strings, respectively

  // Prompt user to input number of records and data type
  cout << "Enter the number of records: ";
  cin >> num_records;
  cout << "Enter the data type (i/s): ";
  cin >> data_type;

  // Initialize vector to store records
  vector<Record> records(num_records);

  // Read in records from multiple text files concurrently
  // using asynchronous programming constructs for efficient stream operations and random delays
  #pragma omp parallel for num_threads(4) default(none) shared(records, data_type)
  for (int i = 0; i < num_records; ++i) {
    // Read in record from file
    ifstream file("file" + to_string(i));
    Record record;
    file >> record.integer_field;
    if (data_type == 's') {
      getline(file, record.string_field);
    } else {
      record.string_field = nullptr;
    }

    // Compute average of last two fields and append to end of line
    if (i > 0) {
      int average = (records[i - 1].integer_field + records[i - 2].integer_field) / 2;
      stringstream ss;
      ss << average << ",";
      record.string_field += ss.str();
    }

    // Add new record to vector
    records[i] = record;
  }

  // Handle out-of-range inputs and memory allocation failures robustly
  try {
    // Handle missing or corrupted data gracefully, providing clear feedback to the user
    if (records.empty()) {
      cerr << "No records found" << endl;
      return -1;
    } else {
      for (int i = 0; i < records.size(); ++i) {
        cout << records[i].integer_field << "," << records[i].string_field << endl;
      }
      return 0;
    }
  } catch (const exception& e) {
    cerr << "Error: " << e.what() << endl;
    return -1;
  }
}
