#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>

// Helper function to determine the maximum value in an array of integers or floats
void max_value(void* arr, int size, int type) {
    if (type == 0) { // integer
        int max = ((int*)arr)[0];
        for (int i = 1; i < size; i++) {
            if (((int*)arr)[i] > max) {
                max = ((int*)arr)[i];
            }
        }
        printf("Maximum value: %d\n", max);
    } else { // float
        float max = ((float*)arr)[0];
        for (int i = 1; i < size; i++) {
            if (((float*)arr)[i] > max) {
                max = ((float*)arr)[i];
            }
        }
        printf("Maximum value: %f\n", max);
    }
}

// Helper function to determine the longest string in an array of strings
void longest_string(char** arr, int size) {
    char* longest = arr[0];
    for (int i = 1; i < size; i++) {
        if (strlen(arr[i]) > strlen(longest)) {
            longest = arr[i];
        }
    }
    printf("Longest string: %s\n", longest);
}

// Function to read data from standard input and populate a dynamic array
void* read_data(int num_entries, int type) {
    // Initialize variables
    void* arr = NULL;
    int i = 0;
    char str[1024];

    // Allocate memory for the array
    arr = malloc(num_entries * sizeof(void*));
    if (arr == NULL) {
        syslog(LOG_ERR, "Memory allocation failed");
        return NULL;
    }

    // Read data from standard input
    while (i < num_entries && fgets(str, 1024, stdin)) {
        if (type == 0) { // integer
            arr[i] = malloc(sizeof(int));
            *((int*)arr[i]) = atoi(str);
        } else if (type == 1) { // float
            arr[i] = malloc(sizeof(float));
            *((float*)arr[i]) = atof(str);
        } else if (type == 2) { // string
            int len = strlen(str);
            arr[i] = malloc(len + 1);
            memcpy(arr[i], str, len + 1);
        }
        i++;
    }

    return arr;
}

// Function to generate random values for the array
void generate_random(int num_entries, int type) {
    // Initialize variables
    void* arr = NULL;
    srand(time(NULL));

    // Allocate memory for the array
    arr = malloc(num_entries * sizeof(void*));
    if (arr == NULL) {
        syslog(LOG_ERR, "Memory allocation failed");
        return;
    }

    // Generate random values
    for (int i = 0; i < num_entries; i++) {
        if (type == 0) { // integer
            arr[i] = malloc(sizeof(int));
            *((int*)arr[i]) = rand() % 100;
        } else if (type == 1) { // float
            arr[i] = malloc(sizeof(float));
            *((float*)arr[i]) = ((float)(rand() % 100) / 100.0);
        } else if (type == 2) { // string
            int len = rand() % 10 + 5;
            arr[i] = malloc(len + 1);
            for (int j = 0; j < len; j++) {
                arr[i][j] = 'a' + (rand() % 26);
            }
            arr[i][len] = '\0';
        }
    }
}

// Main function to read data from standard input and populate a dynamic array
int main(void) {
    // Initialize variables
    int num_entries = 0;
    int type = 0;
    void* arr = NULL;
    char str[1024];

    // Read number of entries and data type from standard input
    printf("Enter the number of entries: ");
    fgets(str, 1024, stdin);
    num_entries = atoi(str);
    printf("Enter the data type (0 for integer, 1 for float, 2 for string): ");
    fgets(str, 1024, stdin);
    type = atoi(str);

    // Read data from standard input and populate the array
    arr = read_data(num_entries, type);
    if (arr == NULL) {
        syslog(LOG_ERR, "Error reading data");
        return 1;
    }

    // Print maximum value in the array
    max_value(arr, num_entries, type);

    // Free memory allocated for the array
    free(arr);

    return 0;
}']

