Here is a C function that manages a flexible and scalable collection of task objects, each containing a title, description, due date, and priority level:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Structure to represent a task
struct Task {
    char *title;
    char *description;
    time_t due_date;
    int priority;
};

// Function to add a new task to the collection
void add_task(struct Task **tasks, struct Task *new_task) {
    // Check if there is enough space for the new task
    if (tasks == NULL || (*tasks)->capacity == 0) {
        fprintf(stderr, "Error: no more space in tasks array\n");
        return;
    }

    // Add the new task to the end of the array
    *tasks = realloc(*tasks, sizeof(**tasks) + (1));
    (*tasks)[*tasks->capacity].title = new_task->title;
    (*tasks)[*tasks->capacity].description = new_task->description;
    (*tasks)[*tasks->capacity].due_date = new_task->due_date;
    (*tasks)[*tasks->capacity].priority = new_task->priority;
    (*tasks)->capacity++;
}

// Function to update a task in the collection
void update_task(struct Task **tasks, int index, struct Task *updated_task) {
    // Check if the task exists and is not already updated
    if (index < 0 || index >= (*tasks)->capacity || (*tasks)[index].title == updated_task->title &&
            (*tasks)[index].description == updated_task->description && (*tasks)[index].due_date == updated_task->due_date &&
            (*tasks)[index].priority == updated_task->priority) {
        fprintf(stderr, "Error: task does not exist or has already been updated\n");
        return;
    }

    // Update the task with the new values
    (*tasks)[index].title = updated_task->title;
    (*tasks)[index].description = updated_task->description;
    (*tasks)[index].due_date = updated_task->due_date;
    (*tasks)[index].priority = updated_task->priority;
}

// Function to delete a task from the collection
void delete_task(struct Task **tasks, int index) {
    // Check if the task exists
    if (index < 0 || index >= (*tasks)->capacity) {
        fprintf(stderr, "Error: task does not exist\n");
        return;
    }

    // Remove the task from the array
    for (int i = index; i < (*tasks)->capacity - 1; i++) {
        (*tasks)[i].title = (*tasks)[i + 1].title;
        (*tasks)[i].description = (*tasks)[i + 1].description;
        (*tasks)[i].due_date = (*tasks)[i + 1].due_date;
        (*tasks)[i].priority = (*tasks)[i + 1].priority;
    }
    (*tasks)->capacity--;
}

// Function to filter tasks based on criteria
struct Task *filter_tasks(struct Task **tasks, struct FilterCriteria *criteria) {
    // Create a new array of tasks that match the criteria
    struct Task *filtered_tasks = malloc(sizeof(**tasks));
    int filtered_capacity = 0;

    for (int i = 0; i < (*tasks)->capacity; i++) {
        if ((*tasks)[i].title == criteria->title && (*tasks)[i].description == criteria->description &&
                (*tasks)[i].due_date == criteria->due_date && (*tasks)[i].priority == criteria->priority) {
            // Add the task to the filtered array
            filtered_tasks = realloc(filtered_tasks, sizeof(**tasks) + (1));
            filtered_tasks[filtered_capacity].title = (*tasks)[i].title;
            filtered_tasks[filtered_capacity].description = (*tasks)[i].description;
            filtered_tasks[filtered_capacity].due_date = (*tasks)[i].due_date;
            filtered_tasks[filtered_capacity].priority = (*tasks)[i].priority;
            filtered_capacity++;
        }
    }

    // Reallocate the filtered tasks array to the correct size
    filtered_tasks = realloc(filtered_tasks, sizeof(**tasks) + (filtered_capacity * sizeof(struct Task)));

    return filtered_tasks;
}

// Function to sort tasks by multiple attributes
void sort_tasks(struct Task **tasks, struct SortCriteria *criteria) {
    // Check if there are any tasks to sort
    if ((*tasks)->capacity == 0) {
        fprintf(stderr, "Error: no tasks to sort\n");
        return;
    }

    // Define the sorting function
    int (*sort_function)(const void *a, const void *b);

    // Check if the user wants to sort by due date or priority
    if (criteria->sort_by == SORT_BY_DUE_DATE) {
        sort_function = compare_tasks_due_date;
    } else if (criteria->sort_by == SORT_BY_PRIORITY) {
        sort_function = compare_tasks_priority;
    } else {
        fprintf(stderr, "Error: invalid sorting criteria\n");
        return;
    }

    // Sort the tasks array using the defined function
    qsort(*tasks, (*tasks)->capacity, sizeof(**tasks), sort_function);
}

// Function to generate a summary report of all tasks
struct SummaryReport *generate_summary_report(struct Task **tasks) {
    // Create a new summary report object
    struct SummaryReport *report = malloc(sizeof(*report));

    // Initialize the summary report fields
    report->total_number_of_tasks = 0;
    report->average_priority = 0.0;
    report->number_of_overdue_tasks = 0;

    // Iterate over all tasks and update the summary report fields
    for (int i = 0; i < (*tasks)->capacity; i++) {
        report->total_number_of_tasks++;
        report->average_priority += (*tasks)[i].priority;
        if ((*tasks)[i].due_date <= time(NULL)) {
            report->number_of_overdue_tasks++;
        }
    }

    // Calculate the average priority and return the summary report object
    report->average_priority /= report->total_number_of_tasks;

    return report;
}
