    // Check if the tasks have priorities
    if (a->priority == 0 || b->priority == 0) {
        return 0;
    }

    // Compare the tasks based on their priorities
    return a->priority < b->priority ? -1 : (a->priority > b->priority ? 1 : 0);
}
