    // Allocate memory for the linked list
    item *head = NULL;
    item **current = &head;

    // Initialize random values within specified ranges
    for (int i = 0; i < num_items; i++) {
        // Allocate memory for the current item
        *current = malloc(sizeof(item));
        if (*current == NULL) {
