        sprintf((*current)->string, string_format, random_integer, random_double);

        // Initialize the next pointer to NULL
        (*current)->next = NULL;

        // Move the current pointer to the next node in the linked list
        current = &(*current)->next;
    }

    return head;
}

// Function to read initial values for the structs from an external file
item* read_items(const char *filepath, int min_integer, int max_integer,
