        return NULL;
    }

    // Read the number of items from the first line of the file
    int num_items;
    char *line = fgets(filepath, 1024, fp);
    if (line == NULL) {
        printf("Error: File is empty\n");
        return NULL;
    }

    // Initialize the linked list of items
    item *head = NULL;
    item **current = &head;

    // Read and initialize each struct from the file
    while (fscanf(fp, "%d %lf %s", &num_items, &min_integer, &max_integer, &min_double, &max_double) == 5) {
        *current = malloc(sizeof(item));
        if (*current == NULL) {
            printf("Error: Memory allocation failed\n");
            return NULL;
        }

        // Initialize integer and double values randomly within specified ranges
        int random_integer = min_integer + rand() % (max_integer - min_integer);
        double random_double = min_double + ((double)rand()) / RAND_MAX * (max_double - min_double);
        sprintf((*current)->string, string_format, random_integer, random_double);

        // Initialize the next pointer to NULL
        (*current)->next = NULL;

        // Move the current pointer to the next node in the linked list
        current = &(*current)->next;
    }

    fclose(fp);

    return head;
}

// Function to free memory for a linked list of items
void free_items(item *head) {
    item *current = head;
    while (current != NULL) {
        // Free the current node and move to the next one
        item *next = current->next;
        free(current);
        current = next;
    }
}
