```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

// Structure to represent a product
typedef struct {
    char name[128];
    int quantity;
    float price;
} Product;

// Dynamic array of products
Product *products = NULL;
int num_products = 0;

// Function to add a new product to the collection
void add_product(const char *name, int quantity, float price) {
    // Allocate memory for the new product
    Product *new_product = malloc(sizeof(Product));
    if (!new_product) {
        printf("Error: failed to allocate memory for new product\n");
        return;
    }

    // Copy the name and quantity from the input arguments
    strncpy(new_product->name, name, 128);
    new_product->quantity = quantity;
    new_product->price = price;

    // Add the product to the end of the products array
    if (num_products == 0) {
        products = malloc(sizeof(Product));
    } else {
        products = realloc(products, sizeof(Product) * (num_products + 1));
    }

    // Increment the number of products and return
    num_products++;
}

// Function to remove a product from the collection by its name
void remove_product(const char *name) {
    int i;
    for (i = 0; i < num_products; i++) {
        if (strcmp(products[i].name, name) == 0) {
            // Remove the product from the array by shifting all subsequent elements
            memmove(&products[i], &products[i + 1], sizeof(Product) * (num_products - i));
            num_products--;
            break;
        }
    }
}

// Function to update a product's quantity or price
void update_product(const char *name, int quantity, float price) {
    int i;
    for (i = 0; i < num_products; i++) {
        if (strcmp(products[i].name, name) == 0) {
            products[i].quantity = quantity;
            products[i].price = price;
            break;
        }
    }
}

// Function to iterate over all products and print their details in a user-friendly format
void print_products() {
    int i;
    for (i = 0; i < num_products; i++) {
        printf("Product %d: Name = %s, Quantity = %d, Price = %.2f\n", i + 1, products[i].name, products[i].quantity, products[i].price);
    }
}
```
