// Function to initialize the arrays for 'long' offset values and 'int' keys
void init_arrays(record_t** long_offsets, record_t** int_keys, size_t n) {
    // Allocate memory for the arrays of records
    *long_offsets = (record_t*)malloc(n * sizeof(record_t));
    *int_keys = (record_t*)malloc(n * sizeof(record_t));

    if (*long_offsets == NULL || *int_keys == NULL) {
        // Handle memory allocation failure gracefully
        printf("Error: Failed to allocate memory for the arrays\n");
        return;
    }

    // Initialize the records with random values within the specified range
    srand(time(NULL));
    for (size_t i = 0; i < n; i++) {
        (*long_offsets)[i].key = rand() % 100;
        (*int_keys)[i].key = rand() % 100;
    }
}

// Function to generate random values within a specified range
void generate_random_values(record_t* records, size_t n, int min_val, int max_val) {
    // Ensure the specified range is valid
    if (min_val > max_val || min_val < 0 || max_val < 0) {
        printf("Error: Invalid range for random values\n");
        return;
    }

    srand(time(NULL));
    for (size_t i = 0; i < n; i++) {
        records[i].key = rand() % (max_val - min_val + 1) + min_val;
    }
}

// Function to filter records based on specific criteria
void filter_records(record_t* records, size_t n, int threshold) {
    // Ensure the specified threshold is valid
    if (threshold < 0 || threshold > 100) {
        printf("Error: Invalid threshold for filtering\n");
        return;
    }

    // Initialize a temporary array to store filtered records
    record_t* temp = (record_t*)malloc(n * sizeof(record_t));

    if (temp == NULL) {
        printf("Error: Failed to allocate memory for the temporary array\n");
        return;
    }

    // Copy the filtered records into the temporary array
    size_t new_size = 0;
    for (size_t i = 0; i < n; i++) {
        if (records[i].key > threshold) {
            temp[new_size++] = records[i];
        }
    }

    // Reallocate memory for the temporary array to match the filtered size
    temp = (record_t*)realloc(temp, new_size * sizeof(record_t));

    if (temp == NULL) {
        printf("Error: Failed to reallocate memory for the temporary array\n");
        return;
    }

    // Update the original records with the filtered values
    memcpy(records, temp, new_size * sizeof(record_t));
}

// Function to find and print the largest integer in an array of 'int' values
void print_largest_integer(record_t* records, size_t n) {
    // Ensure the array is not empty
    if (n == 0) {
        printf("Error: Empty array\n");
        return;
    }

    int largest = -1;
    for (size_t i = 0; i < n; i++) {
        if (records[i].key > largest) {
            largest = records[i].key;
        }
    }

    printf("Largest integer: %d\n", largest);
}

// Function to find and print the longest string in an array of 'char*' strings
void print_longest_string(record_t* records, size_t n) {
    // Ensure the array is not empty
    if (n == 0) {
        printf("Error: Empty array\n");
        return;
    }

    int longest = -1;
    for (size_t i = 0; i < n; i++) {
        if (records[i].value != NULL && strlen((char*)records[i].value) > longest) {
            longest = strlen((char*)records[i].value);
        }
    }

    printf("Longest string: %s\n", (char*)records[longest].value);
}

// Function to execute a command and print the output and error streams
void execute_command(const char* cmd, const char* file) {
    // Ensure the target file exists and is not empty
    FILE* fp = fopen(file, "r");
    if (fp == NULL || !feof(fp)) {
        printf("Error: Failed to open or read the file\n");
        return;
    }

    // Delete the target file before executing the command
    remove(file);

    // Execute the command and capture the output and error streams
    FILE* output = popen(cmd, "r");
    char buffer[1024];
    size_t n;

    while ((n = fread(buffer, 1, sizeof(buffer), output)) > 0) {
        printf("%s", buffer);
    }

    int status = pclose(output);
    if (status == -1) {
        printf("Error: Failed to execute the command\n");
        return;
    }
}

