// Function to initialize and allocate memory for an array of SensorData structures.
void init_sensor_data(SensorData **data, int buffer_size) {
    // Allocate memory for the array of SensorData structures.
    *data = (SensorData *)malloc(buffer_size * sizeof(SensorData));
    if (*data == NULL) {
        printf("Error: Out of memory!\n");
        exit(1);
    }

    // Initialize the metadata for each SensorData structure.
    for (int i = 0; i < buffer_size; i++) {
        (*data)[i].temperature = NAN;
        (*data)[i].humidity = NAN;
        (*data)[i].pressure = NAN;
        strcpy((*data)[i].device_id, "");
        (*data)[i].timestamp = 0;
        (*data)[i].sensor_status = 0;
    }
}

// Function to process a continuous stream of sensor data over a network.
void process_sensor_data(SensorData **data, int buffer_size, int num_connections) {
    // Loop through each connection and process the incoming data.
    for (int i = 0; i < num_connections; i++) {
        SensorData *current_data = &(*data)[i];

        // Check if there is any new data available to read.
        if (current_data->sensor_status == 1) {
            // Read the next batch of data from the network connection.
            int num_read = read(current_data->socket, current_data->buffer, BUFFER_SIZE);
            if (num_read > 0) {
                // Update the metadata for each SensorData structure.
                current_data->timestamp = time(NULL);
                current_data->sensor_status = 2;
            } else {
                // Handle network disconnections and memory allocation failures gracefully.
                if (num_read == -1) {
                    printf("Error: Network connection error!\n");
                    current_data->sensor_status = 0;
                } else if (num_read == -2) {
                    printf("Error: Out of memory!\n");
                    current_data->sensor_status = 0;
                }
            }
        }

        // Check for out-of-bounds access and handle accordingly.
        if (current_data->temperature > MAX_TEMP || current_data->temperature < MIN_TEMP) {
            printf("Error: Temperature reading is out of bounds!\n");
            current_data->sensor_status = 0;
        } else if (current_data->humidity > MAX_HUMIDITY || current_data->humidity < MIN_HUMIDITY) {
            printf("Error: Humidity reading is out of bounds!\n");
            current_data->sensor_status = 0;
        } else if (current_data->pressure > MAX_PRESSURE || current_data->pressure < MIN_PRESSURE) {
            printf("Error: Pressure reading is out of bounds!\n");
            current_data->sensor_status = 0;
        }

        // Retry logic for handling network errors and memory allocation failures.
        if (current_data->sensor_status == 0) {
            printf("Retrying...\n");
            sleep(5); // Pause for 5 seconds before retrying.
            process_sensor_data(data, buffer_size, num_connections);
        }
    }
}

// Function to compute and print the highest temperature reading in the array of SensorData structures.
void find_highest_temperature(SensorData **data, int buffer_size) {
    float highest = NAN;
    for (int i = 0; i < buffer_size; i++) {
        if (!isnan((*data)[i].temperature)) {
            if (highest == NAN || (*data)[i].temperature > highest) {
                highest = (*data)[i].temperature;
            }
        }
    }
    printf("Highest temperature: %f\n", highest);
}

// Function to compute and print the average of the temperature, humidity, and pressure readings in the array of SensorData structures.
void calculate_average(SensorData **data, int buffer_size) {
    float avg_temperature = 0;
    float avg_humidity = 0;
    float avg_pressure = 0;
    for (int i = 0; i < buffer_size; i++) {
        if (!isnan((*data)[i].temperature)) {
            avg_temperature += (*data)[i].temperature;
        }
        if (!isnan((*data)[i].humidity)) {
            avg_humidity += (*data)[i].humidity;
        }
        if (!isnan((*data)[i].pressure)) {
            avg_pressure += (*data)[i].pressure;
        }
    }
    avg_temperature /= buffer_size;
    avg_humidity /= buffer_size;
    avg_pressure /= buffer_size;
    printf("Average temperature: %f\n", avg_temperature);
    printf("Average humidity: %f\n", avg_humidity);
    printf("Average pressure: %f\n", avg_pressure);
}

// Function to identify anomalies in the temperature, humidity, and pressure readings based on predefined thresholds.
void detect_anomalies(SensorData **data, int buffer_size) {
    for (int i = 0; i < buffer_size; i++) {
        if ((*data)[i].temperature > MAX_TEMP || (*data)[i].temperature < MIN_TEMP) {
            printf("Temperature anomaly detected!\n");
        } else if ((*data)[i].humidity > MAX_HUMIDITY || (*data)[i].humidity < MIN_HUMIDITY) {
            printf("Humidity anomaly detected!\n");
        } else if ((*data)[i].pressure > MAX_PRESSURE || (*data)[i].pressure < MIN_PRESSURE) {
            printf("Pressure anomaly detected!\n");
        }
    }
}
```
This code defines a `SensorData` structure that contains temperature, humidity, and pressure readings along with metadata such as device ID, timestamp, and sensor status. The `init_sensor_data` function is used to dynamically allocate memory for an array of `SensorData` structures, and initialize the metadata for each structure.

The `process_sensor_data` function processes a continuous stream of sensor data over a network using a loop that iterates through each connection and reads incoming data. The function checks for out-of-bounds access and handles it accordingly. It also implements retry logic to handle network errors and memory allocation failures gracefully.

The `find_highest_temperature`, `calculate_average`, and `detect_anomalies` functions are used to compute and print the highest temperature reading, average of temperature, humidity, and pressure readings, and identify anomalies based on predefined thresholds.

The code is modularized into separate components for initialization, data validation, timestamp generation, memory management, and statistical analysis, allowing for easier maintenance and future extensions. It also includes helper functions to validate input sizes, initialize numerical fields with default values, and generate timestamps based on the current system time.']

