// Define the function to perform DNS resolution for a given hostname using standard library functions
u_char *dns_resolve(const char *hostname, size_t *ip_length) {
    // Initialize the DNS resolver library
    res_state res = res_init();
    if (!res) {
        perror("Failed to initialize DNS resolver");
        return NULL;
    }

    // Perform the DNS resolution for the given hostname
    struct addrinfo hints, *result;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags |= AI_CANONNAME;
    int status = getaddrinfo(hostname, NULL, &hints, &result);
    if (status != 0) {
        perror("Failed to perform DNS resolution");
        res_finish(res);
        return NULL;
    }

    // Allocate memory for the IP address
    u_char *ip = malloc(IP_LENGTH);
    if (!ip) {
        perror("Failed to allocate memory for IP address");
        freeaddrinfo(result);
        res_finish(res);
        return NULL;
    }

    // Copy the IP address from the DNS resolution result into the allocated buffer
    memcpy(ip, &((struct sockaddr_in *)result->ai_addr)->sin_addr, IP_LENGTH);

    // Free the DNS resolution result
    freeaddrinfo(result);

    // Finish using the DNS resolver library
    res_finish(res);

    *ip_length = IP_LENGTH;
    return ip;
}

// Define the function to dynamically read a large text file, efficiently managing memory to avoid excessive consumption
void dynamic_read_file(const char *filename) {
    // Open the file for reading
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    // Allocate memory for the buffer
    size_t buffer_size = BUFFER_SIZE;
    char *buffer = malloc(buffer_size);
    if (!buffer) {
        perror("Failed to allocate memory for buffer");
        fclose(file);
        return;
    }

    // Read the file in chunks, dynamically allocating memory as necessary
    while (fgets(buffer, buffer_size, file)) {
        size_t length = strlen(buffer);

        // If the buffer is full, double its size and reallocate memory
        if (length == buffer_size - 1) {
            buffer_size *= 2;
            char *new_buffer = realloc(buffer, buffer_size);
            if (!new_buffer) {
                perror("Failed to reallocate memory for buffer");
                fclose(file);
                free(buffer);
                return;
            }
            buffer = new_buffer;
        }
    }

    // Close the file and free the buffer
    fclose(file);
    free(buffer);
}

// Define the function to process each line in the input file, computing the average of the last two fields and appending this value to the end of the line in a comma-separated format
void process_line(char *line) {
    // Split the line into an array of fields using the specified delimiter
    char **fields = strtok(line, FIELD_DELIMITER);
    if (!fields) {
        perror("Failed to split line into fields");
        return;
    }

    // Determine the number of fields in the line
    int num_fields = 0;
    while (fields[num_fields]) {
        num_fields++;
    }

    // If the total number of fields is not even, use the average of the last field and zero instead
    if (num_fields % 2 != 0) {
        double average = (atoi(fields[num_fields - 1]) + 0.0) / 2;
        char *new_field = malloc(sizeof(char) * ROUNDING_PRECISION);
        if (!new_field) {
            perror("Failed to allocate memory for new field");
            return;
        }
        sprintf(new_field, "%.4f", average);
        fields[num_fields - 1] = new_field;
    }

    // Compute the average of the last two fields and append it to the end of the line
    int i = num_fields - 2;
    double sum = atoi(fields[i]) + atoi(fields[i + 1]);
    double average = (sum + 0.0) / 2;
    char *new_field = malloc(sizeof(char) * ROUNDING_PRECISION);
    if (!new_field) {
        perror("Failed to allocate memory for new field");
        return;
    }
    sprintf(new_field, "%.4f", average);
    fields[i + 1] = new_field;

    // Join the array of fields back into a single line using the specified delimiter
    char *joined_line = strjoinv(fields, FIELD_DELIMITER);
    if (!joined_line) {
        perror("Failed to join fields into line");
        return;
    }

    // Print the processed line
    printf("%s\n", joined_line);

    // Free the memory allocated for the new field and the joined line
    free(new_field);
    free(joined_line);
}

// Define the function to handle concurrent access from multiple threads, ensuring the system can scale to support thousands of concurrent requests without performance degradation
void *concurrent_handler(void *args) {
    // Cast the input argument to a string pointer and extract the filename
    char *filename = (char *)args;
    const char *input_file = strtok(filename, " ");

    // Open the file for reading in binary mode
    FILE *file = fopen(input_file, "rb");
    if (!file) {
        perror("Failed to open input file");
        return NULL;
    }

