    char *buffer = malloc(buffer_size);
    if (!buffer) {
        perror("Failed to allocate memory for buffer");
        fclose(file);
        return NULL;
    }

    // Read the file in chunks, dynamically allocating memory as necessary
    while (fread(buffer, sizeof(char), buffer_size, file)) {
        size_t length = strlen(buffer);

        // If the buffer is full, double its size and reallocate memory
        if (length == buffer_size - 1) {
            buffer_size *= 2;
            char *new_buffer = realloc(buffer, buffer_size);
            if (!new_buffer) {
                perror("Failed to reallocate memory for buffer");
                fclose(file);
                free(buffer);
                return NULL;
            }
            buffer = new_buffer;
        }
    }

    // Close the file and free the buffer
    fclose(file);
    free(buffer);

    // Dynamicly read the large text file and process each line in the input file, computing the average of the last two fields and appending this value to the end of the line in a comma-separated format
    char *line = strtok(buffer, "\n");
    while (line) {
        process_line(line);
        line = strtok(NULL, "\n");
    }

    // Return NULL to indicate that no error occurred
    return NULL;
}

// Define the function to handle errors, returning an appropriate error code if necessary
int handle_errors(int status) {
    if (status != 0) {
        perror("Error");
        return -1;
    }
    return 0;
}

// Define the main function for the program
int main(int argc, char **argv) {
    // Check the number of input arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s [input file]\n", argv[0]);
        return INVALID_INPUT;
    }

    // Initialize the thread pool and mutex
    pthread_pool_init(&pool);
    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&cond, NULL);

    // Create a new thread for each task in the queue
    int num_threads = 0;
    while (total_tasks_pending > 0) {
        total_tasks_completed++;
        if (num_active_threads < MAX_THREADS) {
            pthread_t thread;
            pthread_create(&thread, NULL, concurrent_handler, argv[1]);
            num_active_threads++;
            total_tasks_pending--;
        } else {
            pthread_cond_wait(&cond, &mutex);
        }
    }

    // Wait for all threads to complete
    while (num_active_threads > 0) {
        pthread_cond_wait(&cond, &mutex);
    }

    // Clean up the thread pool and mutex
    pthread_pool_destroy(pool);
