// Struct to store records
typedef struct record {
    void* data;
    size_t size;
} record_t;

// Function to initialize the dynamic array of records
record_t* init_records(size_t num_records, int randomize) {
    // Allocate memory for the array of records
    record_t* records = (record_t*)malloc(sizeof(record_t) * num_records);
    if (!records) {
        printf("Error: unable to allocate memory for records\n");
        return NULL;
    }

    // Initialize the array of records
    for (size_t i = 0; i < num_records; ++i) {
        records[i].data = NULL;
        records[i].size = 0;
    }

    if (randomize) {
        srand(time(NULL));
        // Generate random integers within the range
        for (size_t i = 0; i < num_records; ++i) {
            int rand_int = rand() % INT_MAX;
            records[i].data = malloc(sizeof(rand_int));
            if (!records[i].data) {
                printf("Error: unable to allocate memory for record %zu\n", i);
                return NULL;
            }
            memcpy(records[i].data, &rand_int, sizeof(rand_int));
        }
    } else {
        // Generate random strings of specified length
        const size_t string_length = 10;
        for (size_t i = 0; i < num_records; ++i) {
            char* rand_string = malloc(sizeof(char) * string_length);
            if (!rand_string) {
                printf("Error: unable to allocate memory for record %zu\n", i);
                return NULL;
            }
            for (size_t j = 0; j < string_length; ++j) {
                rand_string[j] = 'a' + (rand() % 26);
            }
            records[i].data = rand_string;
        }
    }

    return records;
}

// Function to find and print the largest integer or longest string among the records
void find_largest(record_t* records, size_t num_records) {
    // Initialize variables for finding the largest value
    int largest_int = INT_MIN;
    char* largest_string = NULL;
    size_t largest_length = 0;

    // Loop through each record and compare values
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i].data == NULL) continue;
        void* data = records[i].data;
        size_t size = records[i].size;
        if (size == sizeof(int)) {
            int* int_ptr = (int*)data;
            if (*int_ptr > largest_int) {
                largest_int = *int_ptr;
            }
        } else if (size == sizeof(char) * string_length) {
            char* string_ptr = (char*)data;
            size_t length = strlen(string_ptr);
            if (length > largest_length) {
                largest_length = length;
                largest_string = string_ptr;
            }
        }
    }

    // Print the largest value found
    if (largest_int == INT_MIN && largest_string == NULL) {
        printf("No records found\n");
    } else if (largest_int != INT_MIN) {
        printf("Largest integer: %d\n", largest_int);
    } else {
        printf("Largest string: ");
        for (size_t i = 0; i < largest_length; ++i) {
            printf("%c", largest_string[i]);
        }
        printf("\n");
    }
}

// Testing framework to evaluate the function under various conditions
void test(record_t* records, size_t num_records, int randomize) {
    // Initialize the array of records with the given parameters
    record_t* test_records = init_records(num_records, randomize);
    if (!test_records) return;

    // Find and print the largest integer or longest string among the records
    find_largest(test_records, num_records);

    // Free memory allocated for the array of records
    free(test_records);
}

// Test the function with different parameters
void test_all() {
    // Test with random integers
    printf("Testing with random integers...\n");
    test(init_records(10, 1), 10, 1);

    // Test with random strings of length 10
    printf("Testing with random strings of length 10...\n");
    test(init_records(10, 0), 10, 0);

    // Test with large dataset and high concurrency level
    printf("Testing with large dataset and high concurrency level...\n");
    test(init_records(10000, 1), 10000, 1);
}

int main() {
    // Test the function under various conditions
    test_all();

    return 0;
}
