// Function to manage memory for an array of custom data structures
void manageMemory(char* filepath, int numRecords, int recordSize) {
    // Initialize variables for buffer management
    int bufferSize = 1024 * 1024; // 1 MB buffer size
    char* buffer = (char*)malloc(bufferSize);
    if (buffer == NULL) {
        printf("Error: failed to allocate memory for buffer\n");
        return;
    }

    // Initialize variables for asynchronous data loading
    int numLoadedRecords = 0;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Initialize variables for logging
    int numProcessedRecords = 0;
    struct timeval startTime, endTime;
    double totalTimeTaken;
    char* logFilepath = "log.txt";
    FILE* logFile = fopen(logFilepath, "a");

    // Read data from the file and process it asynchronously
    while (fgets(buffer, bufferSize, file) != NULL) {
        // Allocate memory for a new record
        struct CustomData* record = (struct CustomData*)malloc(recordSize);
        if (record == NULL) {
            printf("Error: failed to allocate memory for record\n");
            return;
        }

        // Initialize the values in the record
        sscanf(buffer, "%d %f %c", &record->i, &record->f, &record->c);
        pthread_mutex_lock(&mutex);
        numLoadedRecords++;
        if (numLoadedRecords == numRecords) {
            pthread_cond_broadcast(&cond);
        } else {
            pthread_cond_signal(&cond);
        }
        pthread_mutex_unlock(&mutex);
    }

    // Wait for all records to be loaded before proceeding
    pthread_mutex_lock(&mutex);
    while (numLoadedRecords < numRecords) {
        pthread_cond_wait(&cond, &mutex);
    }
    pthread_mutex_unlock(&mutex);

    // Validate the data and log any errors or invalid records
    for (int i = 0; i < numRecords; i++) {
        if (!validateRecord(records[i])) {
            printf("Error: failed to validate record %d\n", i);
            fprintf(logFile, "Error: failed to validate record %d\n", i);
        } else {
            numProcessedRecords++;
            fprintf(logFile, "%d records processed\n", numProcessedRecords);
        }
    }

    // Free the memory allocated for the records
    free(records);

    // Log the total time taken and close the log file
    gettimeofday(&endTime, NULL);
    totalTimeTaken = (double)(endTime.tv_sec - startTime.tv_sec) + (double)(endTime.tv_usec - startTime.tv_usec) / 1000000;
    fprintf(logFile, "Total time taken: %.3lf seconds\n", totalTimeTaken);
    fclose(logFile);
}

// Function to validate a record and log any errors or invalid records
bool validateRecord(struct CustomData* record) {
    // Check if the int field is within the specified range
    if (record->i < 0 || record->i > 100) {
        printf("Error: int value out of range\n");
        return false;
    }

    // Check if the float field is within the specified range
    if (record->f < -1.0 || record->f > 1.0) {
