```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure to represent a record with a long offset value, an int key, and a char array for variable-length data
typedef struct {
    long offset;
    int key;
    char *data;
} record;

// Function to dynamically allocate memory for an array of records, each containing a long offset value, an int key, and a char array for variable-length data
record* allocate_records(int num_records) {
    // Validate the input parameter
    if (num_records <= 0 || num_records > 1000) {
        fprintf(stderr, "Error: Invalid number of records specified. Must be between 1 and 1000.\n");
        return NULL;
    }

    // Calculate the size of each record in bytes
    int record_size = sizeof(long) + sizeof(int) + strlen(data) + 1;

    // Allocate memory for the array of records
    record *records = (record *)malloc(num_records * record_size);
    if (records == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for %d records.\n", num_records);
        return NULL;
    }

    // Initialize each record with the appropriate data
    int i = 0;
    while (i < num_records) {
        record *current_record = &records[i];
        current_record->offset = i;
        current_record->key = i + 1;
        current_record->data = malloc(strlen(data) + 1);
        strcpy(current_record->data, data);
        i++;
    }

    return records;
}

// Function to free the memory allocated for an array of records
void free_records(record *records) {
    // Free each record's data member
    int i = 0;
    while (i < num_records) {
        record *current_record = &records[i];
        free(current_record->data);
        i++;
    }

    // Free the memory allocated for the array of records
    free(records);
}
```
