    // Initialize the number of events to be allocated initially
    *count = INITIAL_EVENT_COUNT;

    // Allocate memory for the initial array of events
    *events = (event_t*) malloc(sizeof(event_t) * (*count));

    // Check if allocation was successful
    if (*events == NULL) {
        fprintf(stderr, "Failed to allocate memory for events\n");
        return;
    }

    // Initialize the timestamp and identifier for each event
    for (size_t i = 0; i < *count; i++) {
        (*events)[i].timestamp = 0;
        (*events)[i].identifier = 0;
    }
}

void expand_events(event_t** events, size_t* count) {
    // Increase the number of events to be allocated dynamically
    *count += INITIAL_EVENT_COUNT;

    // Reallocate memory for the array of events
    event_t* new_events = (event_t*) realloc(*events, sizeof(event_t) * (*count));

    // Check if reallocation was successful
    if (new_events == NULL) {
        fprintf(stderr, "Failed to expand memory for events\n");
        return;
    }

    // Update the pointer to the array of events
    *events = new_events;
}

void handle_allocation_failure(event_t** events, size_t* count) {
    // Retry allocation up to a maximum of three times
    for (size_t i = 0; i < ALLOCATION_RETRIES; i++) {
        *count += INITIAL_EVENT_COUNT;

        // Reallocate memory for the array of events
        event_t* new_events = (event_t*) realloc(*events, sizeof(event_t) * (*count));

        // Check if reallocation was successful
        if (new_events != NULL) {
            // Update the pointer to the array of events
            *events = new_events;
            break;
        }
    }
}

void free_events(event_t** events, size_t* count) {
    // Free memory for the array of events
    free(*events);
    *count = 0;
}
