// Custom memory pool implementation
#define POOL_SIZE 1024*1024 // 1 MB
#define BLOCK_SIZE 64*1024 // 64 KB

typedef struct {
    void *memory;
    size_t size;
} pool_t;

// Function to initialize the memory pool
void initPool(pool_t *pool) {
    pool->memory = mmap(NULL, POOL_SIZE, PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
    if (pool->memory == NULL) {
        printf("Error: unable to initialize memory pool. errno = %d\n", errno);
        exit(1);
    }
    pool->size = POOL_SIZE;
}

// Function to allocate memory from the pool
void *allocateFromPool(pool_t *pool, size_t size) {
    void *memory = NULL;
    if (size > BLOCK_SIZE) {
        // Allocate a larger block of memory
        memory = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
        if (memory == NULL) {
            printf("Error: unable to allocate %zu bytes from pool. errno = %d\n", size, errno);
            return NULL;
        }
    } else {
        // Allocate a block of memory from the pool
        void *pool_memory = mmap(NULL, BLOCK_SIZE, PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
        if (pool_memory == NULL) {
            printf("Error: unable to allocate %zu bytes from pool. errno = %d\n", BLOCK_SIZE, errno);
            return NULL;
        }
        memory = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
        if (memory == NULL) {
            printf("Error: unable to allocate %zu bytes from pool. errno = %d\n", size, errno);
            return NULL;
        }
        memcpy(memory, pool_memory, BLOCK_SIZE);
    }
    return memory;
}

// Function to free memory allocated from the pool
void freeFromPool(pool_t *pool, void *memory) {
    if (memory == NULL) {
        // Ignore NULL pointers
        return;
    }
    size_t size = munmap(memory, BLOCK_SIZE);
    if (size != 0) {
        printf("Error: unable to free memory from pool. errno = %d\n", errno);
    }
}

// Function to resize the memory pool
void resizePool(pool_t *pool, size_t new_size) {
    void *new_memory = mmap(NULL, new_size, PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
    if (new_memory == NULL) {
        printf("Error: unable to resize memory pool. errno = %d\n", errno);
        return;
    }
    memcpy(new_memory, pool->memory, pool->size);
    size_t size = munmap(pool->memory, pool->size);
    if (size != 0) {
        printf("Error: unable to free memory from pool. errno = %d\n", errno);
        return;
    }
    pool->memory = new_memory;
    pool->size = new_size;
}

