struct record {
    long offset; // offset value
    int key; // unique identifier
    char* data; // variable-length data field
};

// Function to dynamically manage memory for and initialize multiple data structures
void process_records(char** buffers, size_t buffer_sizes, struct record** records) {
    // Initialize variables
    int num_records = 0;
    long total_data_size = 0;
    char* current_buffer = NULL;
    struct record* current_record = NULL;

    // Iterate over each buffer and process its contents
    for (int i = 0; i < buffer_sizes; i++) {
        // Get the current buffer pointer and size
        current_buffer = buffers[i];
        int buffer_size = strlen(current_buffer);

        // Initialize a new record structure
        struct record* new_record = (struct record*)malloc(sizeof(struct record));
        if (!new_record) {
            printf("Failed to allocate memory for record\n");
            exit(1);
        }

        // Get the offset and key values from the current buffer
        char* token = strtok(current_buffer, " ");
        new_record->offset = atol(token);
        token = strtok(NULL, " ");
        new_record->key = atoi(token);

        // Allocate memory for the variable-length data field
        int data_size = buffer_size - (strlen(new_record->offset) + strlen(new_record->key));
        new_record->data = malloc(data_size + 1);
        if (!new_record->data) {
            printf("Failed to allocate memory for data field\n");
            exit(1);
        }
        memcpy(new_record->data, token, data_size);
        new_record->data[data_size] = '\0';

        // Add the new record to the records array
        records[num_records++] = new_record;

        // Update the total data size and allocate memory for the next buffer
        total_data_size += data_size + 1;
    }
}

