    for (size_t i = 0; i < num_records; ++i) {
        records[i].key = rand() % 100;
    }

    // Fill the character string with random ASCII characters up to a user-defined length
    for (size_t i = 0; i < num_records; ++i) {
        records[i].str = (char *)malloc(max_string_length + 1);
        if (!records[i].str) {
            fprintf(stderr, "Error: Failed to allocate memory for string in record %zu\n", i);
            free(records);
            return NULL;
        }
        memset(records[i].str, 0, max_string_length + 1);
        for (size_t j = 0; j < max_string_length; ++j) {
            records[i].str[j] = rand() % 256;
        }
    }

    return records;
}

