// Define the structure for a project
typedef struct {
    char *name;
    double estimated_hours;
    enum status status;
    struct tm start_date;
} project;

// Define the maximum number of projects that can be initialized at once
#define MAX_PROJECTS 100

// Function to initialize a collection of projects
project **initialize_projects(size_t num_projects) {
    // Check if the input size is valid and less than the maximum
    if (num_projects > MAX_PROJECTS) {
        fprintf(stderr, "Error: number of projects exceeds maximum allowed\n");
        return NULL;
    }

    // Allocate memory for the project structures
    project **projects = malloc(sizeof(project *) * num_projects);
    if (!projects) {
        fprintf(stderr, "Error: failed to allocate memory for projects\n");
        return NULL;
    }

    // Initialize each project structure with a default value
    for (size_t i = 0; i < num_projects; i++) {
        projects[i] = malloc(sizeof(project));
        if (!projects[i]) {
            fprintf(stderr, "Error: failed to allocate memory for project %zu\n", i);
            return NULL;
        }
        projects[i]->name = "";
        projects[i]->estimated_hours = 0.0;
        projects[i]->status = STATUS_UNSPECIFIED;
        projects[i]->start_date = {0};
    }

    // Return the initialized project structures
    return projects;
}

// Function to sort projects by estimated hours
void sort_projects_by_estimated_hours(project **projects, size_t num_projects) {
    for (size_t i = 0; i < num_projects - 1; i++) {
        for (size_t j = i + 1; j < num_projects; j++) {
            if (projects[i]->estimated_hours > projects[j]->estimated_hours) {
                project *tmp = projects[i];
                projects[i] = projects[j];
                projects[j] = tmp;
            }
        }
    }
}

// Function to filter projects by status and date range
void filter_projects(project **projects, size_t num_projects, enum status status, struct tm start_date) {
    for (size_t i = 0; i < num_projects; i++) {
        if (projects[i]->status != status || projects[i]->start_date < start_date) {
            free(projects[i]);
            memmove(&projects[i], &projects[i + 1], (num_projects - i - 1) * sizeof(project));
        }
    }
}

// Function to free the memory allocated for a collection of projects
void free_projects(project **projects, size_t num_projects) {
    for (size_t i = 0; i < num_projects; i++) {
        free(projects[i]);
    }
    free(projects);
}
