// C header file
#ifndef DYNAMIC_COLLECTION_H
#define DYNAMIC_COLLECTION_H

#include <stdbool.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* string;
    int integer;
} Data;

// Dynamic collection structure
struct DynamicCollection {
    // Array of data structures
    Data** data;

    // Number of elements in the collection
    size_t count;

    // Maximum number of elements that can be stored in the collection
    size_t capacity;
};

// Initialize a dynamic collection with an initial capacity
struct DynamicCollection* dynamic_collection_init(size_t capacity);

// Add a data structure to the collection
bool dynamic_collection_add(struct DynamicCollection* collection, char* string, int integer);

// Set the string and integer values of a data structure in the collection
bool dynamic_collection_set(struct DynamicCollection* collection, size_t index, char* string, int integer);

// Sort the collection by integer value
void dynamic_collection_sort(struct DynamicCollection* collection);

// Search for a specific string in the collection and return its index if found
size_t dynamic_collection_search(struct DynamicCollection* collection, char* string);

// Serialize the state of the collection to a file
bool dynamic_collection_serialize(struct DynamicCollection* collection, const char* filename);

// Deserialize the state of the collection from a file
bool dynamic_collection_deserialize(struct DynamicCollection* collection, const char* filename);

#endif // DYNAMIC_COLLECTION_H

// C source file
#include "dynamic_collection.h"

struct DynamicCollection* dynamic_collection_init(size_t capacity) {
    struct DynamicCollection* collection = malloc(sizeof(struct DynamicCollection));
    if (collection == NULL) {
        return NULL;
    }

    // Initialize array of data structures with the given capacity
    Data** data = malloc(capacity * sizeof(Data*));
    if (data == NULL) {
        free(collection);
        return NULL;
    }

    collection->data = data;
    collection->count = 0;
    collection->capacity = capacity;

    return collection;
}

bool dynamic_collection_add(struct DynamicCollection* collection, char* string, int integer) {
    if (collection == NULL || string == NULL) {
        return false;
    }

    // Check if the collection is full
    if (collection->count >= collection->capacity) {
        return false;
    }

    Data* data = malloc(sizeof(Data));
    if (data == NULL) {
        return false;
    }

    data->string = string;
    data->integer = integer;

    // Add the data structure to the end of the array
    collection->data[collection->count++] = data;

    return true;
}

bool dynamic_collection_set(struct DynamicCollection* collection, size_t index, char* string, int integer) {
    if (collection == NULL || string == NULL) {
        return false;
    }

    // Check if the index is valid
    if (index >= collection->count) {
        return false;
    }

    Data* data = collection->data[index];
    if (data == NULL) {
        return false;
    }

    free(data->string);
    data->string = string;
    data->integer = integer;

    return true;
}

void dynamic_collection_sort(struct DynamicCollection* collection) {
    if (collection == NULL) {
        return;
    }

    // Sort the array of data structures using a custom comparison function
    qsort(collection->data, collection->count, sizeof(Data*), compare_data);
}

size_t dynamic_collection_search(struct DynamicCollection* collection, char* string) {
    if (collection == NULL || string == NULL) {
        return SIZE_MAX;
    }

    // Search for the specified string in the array of data structures using a custom comparison function
    size_t i = 0;
    while (i < collection->count) {
        Data* data = collection->data[i];
        if (strcmp(data->string, string) == 0) {
            return i;
        }
        ++i;
    }

    // Return SIZE_MAX if the string is not found
    return SIZE_MAX;
}

bool dynamic_collection_serialize(struct DynamicCollection* collection, const char* filename) {
    if (collection == NULL || filename == NULL) {
        return false;
    }

    // Open the file in binary write mode
    FILE* fp = fopen(filename, "wb");
    if (fp == NULL) {
        return false;
    }

    // Write the number of elements in the collection to the file
    size_t num_elements = collection->count;
    if (fwrite(&num_elements, sizeof(size_t), 1, fp) != 1) {
        fclose(fp);
        return false;
    }

    // Write each data structure in the collection to the file
    for (size_t i = 0; i < num_elements; ++i) {
        Data* data = collection->data[i];

        // Write the string length and the string itself
        size_t string_length = strlen(data->string);
        if (fwrite(&string_length, sizeof(size_t), 1, fp) != 1) {
            fclose(fp);
            return false;
        }
        if (fwrite(data->string, string_length, 1, fp) != 1) {
            fclose(fp);
            return false;
        }

        // Write the integer value of the data structure
        if (fwrite(&data->integer, sizeof(int), 1, fp) != 1) {
            fclose(fp);
            return false;
        }
    }

    // Close the file and return true on success
    fclose(fp);
    return true;
}

bool dynamic_collection_deserialize(struct DynamicCollection* collection, const char* filename) {
    if (collection == NULL || filename == NULL) {
        return false;
    }

    // Open the file in binary read mode
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        return false;
    }

    // Read the number of elements in the collection from the file
    size_t num_elements = 0;
    if (fread(&num_elements, sizeof(size_t), 1, fp) != 1) {
        fclose(fp);
        return false;
    }

    // Resize the collection to fit the number of elements read from the file
    bool resized = dynamic_collection_resize(collection, num_elements);
    if (!resized) {
        fclose(fp);
        return false;
    }

    // Read each data structure in the collection from the file
    for (size_t i = 0; i < num_elements; ++i) {
        Data* data = collection->data[i];

        // Read the string length and allocate memory for the string
        size_t string_length = 0;
        if (fread(&string_length, sizeof(size_t), 1, fp) != 1) {
            fclose(fp);
            return false;
        }
        data->string = malloc(string_length + 1);
        if (data->string == NULL) {
            fclose(fp);
            return false;
        }

        // Read the string itself and set it to the allocated memory
        char* buffer = malloc(string_length + 1);
        if (buffer == NULL) {
            fclose(fp);
            return false;
        }
        if (fread(buffer, string_length, 1, fp) != 1) {
            free(data->string);
            fclose(fp);
            return false;
        }
        strncpy(data->string, buffer, string_length);
        data->string[string_length] = '\0';
        free(buffer);

        // Read the integer value of the data structure and set it
        if (fread(&data->integer, sizeof(int), 1, fp) != 1) {
            free(data->string);
            fclose(fp);
            return false;
        }
    }

    // Close the file and return true on success
    fclose(fp);
    return true;
}

// Custom comparison function for sorting data structures by integer value
int compare_data(const void* a, const void* b) {
    Data* da = *((Data**)a);
    Data* db = *((Data**)b);
    return da->integer - db->integer;
}

// Custom comparison function for searching data structures by string value
int compare_string(const void* a, const void* b) {
    char* sa = ((Data*)a)->string;
    char* sb = ((Data*)b)->string;
    return strcmp(sa, sb);
}

