}

// Function to serialize the current state of transactions to a file
void serialize_transactions(FILE* fp) {
    for (int i = 0; i < num_transactions; i++) {
        transaction_t* txn = &transactions[i];
        fwrite(&txn->id, sizeof(int), 1, fp);
        fwrite(&txn->timestamp, sizeof(time_t), 1, fp);
        for (int j = 0; j < num_items; j++) {
            item_t* item = txn->items[j];
            fwrite(&item->id, sizeof(int), 1, fp);
            fwrite(&item->price, sizeof(float), 1, fp);
        }
    }
}

// Function to deserialize transactions from a file
void deserialize_transactions(FILE* fp) {
    for (int i = 0; i < num_transactions; i++) {
        transaction_t* txn = &transactions[i];
        fread(&txn->id, sizeof(int), 1, fp);
        fread(&txn->timestamp, sizeof(time_t), 1, fp);
        for (int j = 0; j < num_items; j++) {
            item_t* item = txn->items[j];
            fread(&item->id, sizeof(int), 1, fp);
            fread(&item->price, sizeof(float), 1, fp);
        }
    }
}

// Function to track total memory usage and provide graceful error recovery for invalid input sizes and memory allocation failures
void track_memory_usage() {
