    size_t new_total_memory = 0;
    for (int i = 0; i < num_transactions; i++) {
        transaction_t* txn = &transactions[i];
        new_total_memory += sizeof(transaction_t) + sizeof(item_t*) * num_items; // Calculate the memory usage for each transaction and its associated items
    }
    total_memory = new_total_memory;
}

// Function to halt new allocations when the memory threshold is exceeded
void check_memory_threshold() {
    if (total_memory > memory_threshold * get_system_memory()) {
        printf("Memory threshold exceeded. Halt new allocations.\n");
        return;
    }
}

// Function to handle errors and recover gracefully from failed allocations
void error_recovery(int error) {
