using System.Threading;
using System.Threading.Tasks;

namespace DataProcessingManager
{
    public class Record
    {
        public int Value { get; set; }
    }

    public class DataProcessingManager
    {
        private const int MAX_CONCURRENT_CONNECTIONS = 10000;
        private const int MAX_DATASET_SIZE = 1000000000; // 1 GB per connection
        private const int MIN_THREADS_PER_CPU = 2;
        private const int MAX_THREADS_PER_CPU = 8;
        private const int MAX_RECORDS_PER_SECOND = 100000; // peak performance conditions

        private static readonly object SyncRoot = new object();
        private static readonly Dictionary<int, List<Record>> Dataset = new Dictionary<int, List<Record>>();
        private static readonly SemaphoreSlim ConnectionsSemaphore = new SemaphoreSlim(MAX_CONCURRENT_CONNECTIONS, MAX_CONCURRENT_CONNECTIONS);
        private static readonly SemaphoreSlim DataProcessingSemaphore = new SemaphoreSlim(0, int.MaxValue);
        private static readonly List<Thread> Threads = new List<Thread>();

        public static void ProcessData(int connectionId, string sqlCommand, IDataReader dataReader)
        {
            // Validate input parameters
            if (connectionId <= 0 || connectionId > MAX_CONCURRENT_CONNECTIONS)
                throw new ArgumentOutOfRangeException("connectionId");
            if (string.IsNullOrEmpty(sqlCommand))
                throw new ArgumentNullException("sqlCommand");
            if (dataReader == null)
                throw new ArgumentNullException("dataReader");

            // Acquire connection semaphore
            ConnectionsSemaphore.Wait();

            try
            {
                // Check if dataset exists for the given connectionId
                if (!Dataset.ContainsKey(connectionId))
                {
                    Dataset.Add(connectionId, new List<Record>());
                }

                var dataset = Dataset[connectionId];

                while (dataReader.Read())
                {
                    // Process record
                    var record = new Record();
                    record.Value = dataReader.GetInt32(0);
                    dataset.Add(record);

                    // Throttle data processing
                    DataProcessingSemaphore.Wait();
                }
            }
            finally
            {
                ConnectionsSemaphore.Release();
            }
        }

        public static void StartThreads()
        {
            for (int i = 0; i < Environment.ProcessorCount * MIN_THREADS_PER_CPU; i++)
            {
                var thread = new Thread(ProcessDataset);
                thread.Start();
                Threads.Add(thread);
            }
        }

        public static void StopThreads()
        {
            foreach (var thread in Threads)
            {
                thread.Abort();
            }
        }

        private static void ProcessDataset()
        {
            while (true)
            {
                // Acquire dataset semaphore
                ConnectionsSemaphore.Wait();

                try
                {
                    foreach (var connectionId in Dataset.Keys)
                    {
                        var dataset = Dataset[connectionId];

                        if (dataset.Count >= MAX_DATASET_SIZE)
                        {
                            // Throttle data processing
                            DataProcessingSemaphore.Wait();

                            // Process dataset
                            foreach (var record in dataset)
                            {
                                // Process record
                                Console.WriteLine($"Record: {record.Value}");
                            }

                            // Remove processed dataset
                            Dataset.Remove(connectionId);
                        }
                    }
                }
                finally
                {
                    ConnectionsSemaphore.Release();
                }
            }
        }
    }
}
```
