// Define a function to dynamically read a list of filenames and directory paths from standard input, modifying the file's extension by appending a sequence of digits and a file type based on specific criteria derived from the original filename
void modify_file_extensions(char **filenames, int num_files) {
    // Declare variables to store the length and content of the filenames
    int filename_len;
    char *filename;

    // Iterate over each filename
    for (int i = 0; i < num_files; i++) {
        // Extract the filename from the list of filenames
        filename = filenames[i];

        // Get the length of the filename
        filename_len = strlen(filename);

        // Check if the filename is empty or contains invalid characters
        if (filename_len == 0 || !is_valid_filename(filename)) {
            printf("Invalid filename: %s\n", filename);
            continue;
        }

        // Determine the number of digits to append to the filename based on its length and content
        int num_digits = determine_num_digits(filename, filename_len);

        // Create a new string buffer for the modified filename
        char *modified_filename = (char *) malloc((filename_len + num_digits + 1) * sizeof(char));
        if (!modified_filename) {
            printf("Memory allocation failed!\n");
            exit(1);
        }

        // Append the digits and file type suffix to the modified filename
        sprintf(modified_filename, "%s%0*d.txt", filename, num_digits, i);

        // Free the original filename buffer
        free(filenames[i]);

        // Set the modified filename in the list of filenames
        filenames[i] = modified_filename;
    }
}

// Define a function to determine the number of digits to append to a filename based on its length and content
int determine_num_digits(char *filename, int filename_len) {
    // Declare variables to store the maximum number of digits that can be appended to the filename
    int max_digits = 10;

    // Iterate over each character in the filename
    for (int i = 0; i < filename_len; i++) {
        // Check if the current character is a digit
        if (!isdigit(filename[i])) {
            max_digits--;
        }
    }

    // Return the maximum number of digits that can be appended to the filename
    return max_digits;
}

// Define a function to check if a filename is valid
int is_valid_filename(char *filename) {
    // Declare variables to store the length and content of the filename
    int filename_len = strlen(filename);

    // Iterate over each character in the filename
    for (int i = 0; i < filename_len; i++) {
        // Check if the current character is a reserved character or not
        if (is_reserved_character(filename[i])) {
            return 0;
        }
    }

    // Return 1 if the filename is valid, 0 otherwise
    return 1;
}

// Define a function to check if a character is a reserved character in a filename
int is_reserved_character(char c) {
    // Return 1 if the character is a reserved character, 0 otherwise
    return (c == '.' || c == '/' || c == '\\');
}
