```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    union {
        int i;
        char* s;
    } value;
} record;

void read_records(int num_records, int min_value, int max_value, int string_length) {
    // Create an array to store the records
    record** records = malloc(num_records * sizeof(record*));

    if (records == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for records\n");
        exit(EXIT_FAILURE);
    }

    // Initialize the array of records
    for (int i = 0; i < num_records; i++) {
        records[i] = malloc(sizeof(record));

        if (records[i] == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for record %d\n", i);
            exit(EXIT_FAILURE);
        }
    }

    // Read the records from standard input
    for (int i = 0; i < num_records; i++) {
        char buffer[1024];

        if (fgets(buffer, sizeof(buffer), stdin) == NULL) {
            fprintf(stderr, "Error: Failed to read record %d from standard input\n", i);
            exit(EXIT_FAILURE);
        }

        // Check if the buffer contains a string or an integer
        char* endptr = NULL;
        int value = strtol(buffer, &endptr, 10);

        if (value == 0 && endptr == buffer) {
            // Buffer contains a string
            records[i]->value.s = malloc(string_length + 1);

            if (records[i]->value.s == NULL) {
                fprintf(stderr, "Error: Failed to allocate memory for record %d\n", i);
                exit(EXIT_FAILURE);
            }

            strncpy(records[i]->value.s, buffer, string_length + 1);
        } else {
            // Buffer contains an integer
            records[i]->value.i = value;
        }
    }
}

int main() {
    int num_records = 10;
    int min_value = 0;
    int max_value = 10;
    int string_length = 20;

    read_records(num_records, min_value, max_value, string_length);

    // Find the largest integer in the array of records
    int largest_integer = -1;
    for (int i = 0; i < num_records; i++) {
        if (records[i]->value.i > largest_integer) {
            largest_integer = records[i]->value.i;
        }
    }

    // Find the longest string in the array of records
    int longest_string = -1;
    for (int i = 0; i < num_records; i++) {
        if (strlen(records[i]->value.s) > longest_string) {
            longest_string = strlen(records[i]->value.s);
        }
    }

    // Print the largest integer and longest string
    printf("Largest integer: %d\n", largest_integer);
    printf("Longest string: %s\n", records[longest_string]->value.s);

    // Clean up memory
    for (int i = 0; i < num_records; i++) {
        free(records[i]);
    }

    free(records);

    return 0;
