            arr[i].type = rand() % 3;
            switch (arr[i].type) {
                case 0: // Integer
                    arr[i].value = malloc(sizeof(int));
                    *(int*)arr[i].value = rand();
                    break;
                case 1: // Float
                    arr[i].value = malloc(sizeof(float));
                    *(float*)arr[i].value = frac * (rand() % INT_MAX);
                    break;
                case 2: // String
                    arr[i].value = malloc((str_len + 1) * sizeof(char));
                    sprintf(arr[i].value, "%.*s", str_len, buf);
            }
        } else {
            // Initialize records with specified input
            if (sscanf(buf, "%d", &arr[i].type) == 1) {
