            max_int = *(int*)arr[i].value;
        } else if (arr[i].type == 1 && *(float*)arr[i].value < min_float) {
            min_float = *(float*)arr[i].value;
        } else if (arr[i].type == 2 && strlen((char*)arr[i].value) > max_str_len) {
            max_str_len = strlen((char*)arr[i].value);
        }
    }
    printf("Largest integer: %d\n", max_int);
    printf("Smallest float: %f\n", min_float);
