        float f;
        double d;
        unsigned long ul;
        struct point p;
    };
    char* s;
} record;

void init_records(record* records, size_t num_records, size_t max_string_len, int precision) {
    // Initialize the array of records with random values.
    for (size_t i = 0; i < num_records; i++) {
        switch ((rand() % 5)) {
            case 0:
                records[i].i = rand();
                break;
            case 1:
                records[i].f = frand(precision);
                break;
            case 2:
                records[i].d = drand(precision);
                break;
            case 3:
                records[i].ul = (unsigned long)rand();
                break;
            case 4:
                records[i].p.x = rand() % INT_MAX;
                records[i].p.y = rand() % INT_MAX;
                break;
        }

        // Initialize the string field with a random string of specified length.
        records[i].s = malloc(max_string_len + 1);
        for (size_t j = 0; j < max_string_len; j++) {
            records[i].s[j] = 'a' + rand() % ('z' - 'a');
        }
        records[i].s[max_string_len] = '\0';
    }
}

