// Structure to represent a record with either int or string value
typedef struct {
    union {
        int i;
        char* s;
    } v;
} Record;

// Function to generate random integers within a specified range
int rand_int(int min, int max) {
    return min + (rand() % (max - min));
}

// Function to generate random strings of a specified length
char* rand_str(int len) {
    char* s = malloc(len + 1);
    for (int i = 0; i < len; i++) {
        s[i] = 'a' + (rand() % 26);
    }
    s[len] = '\0';
    return s;
}

// Function to read and initialize records from standard input
void read_records(int num_records, int max_size, int* int_field, char** str_field) {
    // Allocate memory for the array of records
    Record* records = malloc(sizeof(Record) * num_records);

    // Initialize the array of records with random values
    for (int i = 0; i < num_records; i++) {
        if (rand() % 2 == 0) {
            // Random integer value
            int val = rand_int(INT_MIN, INT_MAX);
            records[i].v.i = val;
            *int_field += val;
        } else {
            // Random string value
            char* s = rand_str(max_size - 1);
            records[i].v.s = s;
            strcpy(*str_field, s);
        }
    }

    // Free the memory allocated for the array of records
    free(records);
}

// Function to release unused memory and reset memory usage monitoring
void release_memory() {
    // Release any unused memory allocated by the function
    free(*int_field);
    *int_field = 0;
    free(*str_field);
    *str_field = NULL;
}

// Function to monitor memory usage in real-time and generate alerts if necessary
void check_memory(long threshold) {
    // Calculate the current memory usage in bytes
    long mem_usage = (long)(*int_field + strlen(*str_field));

    // Check if the memory usage exceeds the specified threshold
    if (mem_usage > threshold) {
        // Release unused memory and reset memory usage monitoring
        release_memory();
    }
}

