// Header file:
#ifndef RECORD_H
#define RECORD_H

#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Macros for error handling and logging:
#define LOG(LEVEL, ...)                          \
  do {                                          \
    if (log_level >= LEVEL) {                   \
      fprintf(stderr, __VA_ARGS__);             \
    }                                           \
  } while (0)

#define ERROR(...) LOG(LOG_ERROR, __VA_ARGS__)
#define WARN(...) LOG(LOG_WARNING, __VA_ARGS__)
#define INFO(...) LOG(LOG_INFO, __VA_ARGS__)
#define DEBUG(...) LOG(LOG_DEBUG, __VA_ARGS__)

// Struct for records:
typedef struct record {
  union {
    int integer;
    char* string;
  };
} record_t;

// Function prototypes:
record_t* init_records(size_t num_records, size_t value_range);
void destroy_records(record_t* records, size_t num_records);
bool process_record(record_t* record, bool print_largest);
void print_largest(record_t* records, size_t num_records);

// Function implementations:

record_t* init_records(size_t num_records, size_t value_range) {
  // Allocate memory for the array of records:
  record_t* records = (record_t*)malloc(num_records * sizeof(record_t));
  if (!records) {
    ERROR("Failed to allocate memory for %zu records\n", num_records);
    return NULL;
  }

  // Initialize the array of records:
  size_t i;
  for (i = 0; i < num_records; ++i) {
    if ((i + 1) % value_range == 0) {
      records[i].integer = i + 1;
    } else {
      char* string = (char*)malloc(value_range * sizeof(char));
      if (!string) {
        ERROR("Failed to allocate memory for string of length %zu\n", value_range);
        free(records);
        return NULL;
      }
      snprintf(string, value_range, "String %d", i + 1);
      records[i].string = string;
    }
  }

  // Return the initialized array of records:
  return records;
}

void destroy_records(record_t* records, size_t num_records) {
  // Free the memory for each record in the array:
  size_t i;
  for (i = 0; i < num_records; ++i) {
    if (records[i].string != NULL) {
      free(records[i].string);
    }
  }

  // Free the memory for the array of records:
  free(records);
}

bool process_record(record_t* record, bool print_largest) {
  if (print_largest && record->integer > largest_value) {
    largest_value = record->integer;
    return true;
  } else {
    return false;
  }
}

void print_largest(record_t* records, size_t num_records) {
  printf("Largest integer: %d\n", largest_value);
}
