#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>
#include <assert.h>

// Constants for random value generation
#define MIN_INT 0
#define MAX_INT 100
#define MIN_STR_LEN 5
#define MAX_STR_LEN 20

// Struct to represent a record in the list
typedef struct {
    int type; // 0 for integer, 1 for string
    void* value; // Either an int or a char*
    float temperature;
    char location[50];
} Record;

// Function to generate random values within range
int generateRandomValue(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Function to generate a string of random length
char* generateRandomString(int len) {
    char* str = malloc(len * sizeof(char));
    for (int i = 0; i < len; ++i) {
        str[i] = 'a' + rand() % 26;
    }
    return str;
}

// Function to create a list of records
Record* createList(int numRecords, int type, void* value, float temperature, char* location) {
    Record* list = malloc(numRecords * sizeof(Record));
    for (int i = 0; i < numRecords; ++i) {
        list[i].type = type;
        list[i].value = value;
        list[i].temperature = temperature;
        strcpy(list[i].location, location);
    }
    return list;
}

// Function to filter records based on criteria
Record* filterRecords(Record* list, int numRecords, int type, void* value) {
    Record* filteredList = malloc(numRecords * sizeof(Record));
    int count = 0;
    for (int i = 0; i < numRecords; ++i) {
        if (list[i].type == type && list[i].value == value) {
            filteredList[count] = list[i];
            count++;
        }
    }
    return filteredList;
}

// Function to find the largest integer in a list of integers
int findLargestInteger(Record* list, int numRecords) {
    int largest = list[0].value;
    for (int i = 1; i < numRecords; ++i) {
        if (list[i].type == 0 && (int)list[i].value > largest) {
            largest = list[i].value;
        }
    }
    return largest;
}

// Function to find the longest string in a list of strings
char* findLongestString(Record* list, int numRecords) {
    char* longest = (char*)list[0].value;
    for (int i = 1; i < numRecords; ++i) {
        if (list[i].type == 1 && strlen((char*)list[i].value) > strlen(longest)) {
            longest = list[i].value;
        }
    }
    return longest;
}

// Function to print a list of records
void printList(Record* list, int numRecords) {
    for (int i = 0; i < numRecords; ++i) {
        printf("%d - %s - %.2f - %s\n", list[i].type, list[i].value, list[i].temperature, list[i].location);
    }
}

// Test function to test the functionality of the createList function
void testCreateList() {
    int numRecords = 5;
    Record* list = createList(numRecords, 0, &generateRandomValue(MIN_INT, MAX_INT), (float)generateRandomValue(10, 20), "Location");
    assert(list != NULL);
    free(list);
}

// Test function to test the functionality of the filterRecords function
void testFilterRecords() {
    int numRecords = 5;
    Record* list = createList(numRecords, 0, &generateRandomValue(MIN_INT, MAX_INT), (float)generateRandomValue(10, 20), "Location");
    assert(list != NULL);
    Record* filteredList = filterRecords(list, numRecords, 0, &generateRandomValue(MIN_INT, MAX_INT));
    assert(filteredList != NULL);
    free(list);
}

// Test function to test the functionality of the findLargestInteger and findLongestString functions
void testFindLargestAndLongest() {
    int numRecords = 5;
    Record* list = createList(numRecords, 0, &generateRandomValue(MIN_INT, MAX_INT), (float)generateRandomValue(10, 20), "Location");
    assert(list != NULL);
    int largestInteger = findLargestInteger(list, numRecords);
    char* longestString = findLongestString(list, numRecords);
    assert(largestInteger > 0 && longestString != NULL);
    free(list);
}

// Main function to test the entire module
int main() {
    testCreateList();
    testFilterRecords();
    testFindLargestAndLongest();
    return 0;
}
