void init_list(char* filename, struct entry** entries, int* num_entries) {
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error opening file %s: %s\n", filename, strerror(errno));
        return;
    }

    // Read the CSV file line by line and add each entry to the list
    char line[1024];
    while (fgets(line, sizeof(line), fp) != NULL) {
        // Skip empty lines or lines starting with a # character
        if (strlen(line) == 0 || line[0] == '#') {
            continue;
        }

        // Tokenize the line into timestamp and value fields, separated by commas
        char* token = strtok(line, ",");
        long timestamp = atol(token);
        token = strtok(NULL, ",");
        double value = atof(token);

        // Add the entry to the list
        struct entry* new_entry = malloc(sizeof(struct entry));
        if (new_entry == NULL) {
            printf("Error allocating memory for new entry\n");
            return;
        }
        new_entry->timestamp = timestamp;
        new_entry->value = value;
        *entries = realloc(*entries, (*num_entries + 1) * sizeof(struct entry));
        if (*entries == NULL) {
            printf("Error allocating memory for list\n");
            return;
        }
        (*entries)[*num_entries] = new_entry;
        (*num_entries)++;
