int init_configs(const char* config_files[], int num_configs, int max_batch_size) {
    // Initialize arrays for storing configurations and records
    Configuration *configs = malloc(sizeof(Configuration) * num_configs);
    Record *records = malloc(sizeof(Record) * max_batch_size);
    if (configs == NULL || records == NULL) {
        printf("Error: memory allocation failed.\n");
        return 1;
    }

    // Read and parse configuration files
    for (int i = 0; i < num_configs; i++) {
        Configuration *config = &configs[i];
        Record *record = &records[i];

        if (!read_configuration(config, config_files[i])) {
            printf("Error: failed to read configuration file %s\n", config_files[i]);
            return 1;
