            printf("Error: failed to parse configuration file %s\n", config_files[i]);
            return 1;
        }

        // Initialize array of records with random integer values
        for (int j = 0; j < config->num_records; j++) {
            record = &records[j];
            record->value = generate_random_integer(config->min_value, config->max_value);
        }
