}

int read_configuration(Configuration *config, const char* file) {
    // Open configuration file
    FILE *fp = fopen(file, "r");
    if (fp == NULL) {
        printf("Error: failed to open configuration file %s\n", file);
        return 0;
    }

    // Read and parse configuration data
    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, fp) != NULL) {
        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\n') {
            continue;
        }

        // Parse configuration data
        sscanf(line, "%d %d", &config->min_value, &config->max_value);
    }

    fclose(fp);
    return 1;
}

int parse_configuration(Configuration *config) {
    // Validate configuration data
    if (config->min_value > config->max_value) {
        printf("Error: minimum value cannot be greater than maximum value\n");
        return 0;
    }
    return 1;
}

int generate_random_integer(int min, int max) {
    // Generate random integer between min and max (inclusive)
    int range = (max - min) + 1;
    int random_number = ((double)rand() / RAND_MAX) * range + min;
    return random_number;
}

