// Define a struct to hold sensor data
typedef struct {
    float temperature;
    time_t timestamp;
    char identifier;
} sensor_data_t;

// Define a list of sensor structures to store the data
static sensor_data_t *sensor_list = NULL;

// Define a function to initialize the list from multiple CSV files
void init_sensor_list(int num_files, char **file_names) {
    // Allocate memory for the list
    sensor_list = malloc(sizeof(sensor_data_t) * 10);

    // Iterate over the files and read data into the list
    for (int i = 0; i < num_files; ++i) {
        FILE *file = fopen(file_names[i], "r");
        if (!file) {
            printf("Error opening file %s\n", file_names[i]);
            continue;
        }
        while (!feof(file)) {
            float temperature;
            time_t timestamp;
            char identifier;
            fscanf(file, "%c,%d,%f\n", &identifier, &timestamp, &temperature);
            // Add the data to the list if it is within a reasonable range
            if (temperature >= -273.15 && temperature <= 100) {
                sensor_list[i].identifier = identifier;
                sensor_list[i].timestamp = timestamp;
                sensor_list[i].temperature = temperature;
                ++i;
            } else {
                printf("Invalid temperature reading: %f\n", temperature);
            }
        }
        fclose(file);
    }
}

// Define a function to validate the data against typical temperature ranges
void validate_data() {
    // Iterate over the list and remove any entries with invalid readings
    for (int i = 0; i < 10; ++i) {
        if (sensor_list[i].temperature < -273.15 || sensor_list[i].temperature > 100) {
            printf("Invalid temperature reading: %f\n", sensor_list[i].temperature);
            sensor_list[i] = (sensor_data_t){0};
        }
    }
}

// Define a function to detect and log any missing data points or inconsistencies in the timestamp sequence
void check_timestamp_sequence() {
    // Iterate over the list and detect any gaps in the timestamps
    for (int i = 0; i < 10; ++i) {
        if (sensor_list[i].temperature == 0) continue;
        int j = i + 1;
        while (j < 10 && sensor_list[j].timestamp - sensor_list[i].timestamp != 1) {
            printf("Missing data point between %d and %d\n", sensor_list[i].timestamp, sensor_list[j].timestamp);
            ++j;
        }
    }
}

// Define a function to calculate the moving average of temperature readings over a specified window size
void update_moving_average(int window_size) {
    // Calculate the sum of the temperatures over the given window
    float total = 0;
    for (int i = 0; i < window_size; ++i) {
        total += sensor_list[i].temperature;
    }
    // Update the temperature field of each entry to reflect the moving average
    for (int i = 0; i < window_size; ++i) {
        sensor_list[i].temperature -= total / window_size;
    }
}

// Define a function to handle concurrent updates and reads efficiently
void update_sensor_data(float temperature, time_t timestamp, char identifier) {
    // Find the entry for the given identifier in the list
    sensor_data_t *entry = NULL;
    for (int i = 0; i < 10; ++i) {
        if (sensor_list[i].identifier == identifier) {
            entry = &sensor_list[i];
            break;
        }
    }
    // If the entry was not found, create a new one and add it to the list
    if (!entry) {
        entry = &sensor_list[10];
        sensor_list[10].identifier = identifier;
        ++10;
    }
    // Update the temperature and timestamp for the given identifier
    entry->temperature = temperature;
    entry->timestamp = timestamp;
}

// Define a function to provide meaningful error messages for any file I/O issues
void handle_file_errors(char *file_name, int error) {
    if (error == EINVAL || error == EMFILE) {
        printf("Error opening file %s: %s\n", file_name, strerror(error));
    } else if (error == ENOENT) {
        printf("File %s does not exist or cannot be accessed.\n", file_name);
    }
}
