#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <limits.h>
#include <float.h>
#include <math.h>
#include <time.h>

// Configuration file parsing library
#include "configparser.h"

// Logging framework
#include "logging.h"

// Structures for entry data and configuration settings
struct Entry {
    long timestamp;
    double value;
    char *metadata; // optional key-value pairs, separated by commas
};

struct ConfigSettings {
    int min_entries;
    int max_entries;
    long min_timestamp;
    long max_timestamp;
};

// Function to initialize the list of entries from a CSV file
void init_entry_list(char *filename, struct Entry **entry_list) {
    // Open the CSV file for reading
    FILE *file = fopen(filename, "r");
    if (!file) {
        log_error("Error opening file: %s", strerror(errno));
        return;
    }

    // Initialize an empty list of entries
    *entry_list = NULL;

    // Read the file line by line and parse each line as a timestamp-value pair
    char *line = NULL;
    size_t len = 0;
    while (getline(&line, &len, file) != -1) {
        // Skip empty lines or comments
        if (!line || line[0] == '#') continue;

        // Tokenize the line into timestamp and value fields
        char *timestamp_str = strtok(line, ",");
        char *value_str = strtok(NULL, ",\n");
        long timestamp = atol(timestamp_str);
        double value = atof(value_str);

        // Allocate memory for the entry structure
        struct Entry *entry = malloc(sizeof(struct Entry));
        if (!entry) {
            log_error("Error allocating memory for entry");
            break;
        }

        // Initialize the entry fields
        entry->timestamp = timestamp;
        entry->value = value;
        entry->metadata = NULL;

        // Add the entry to the list
        *entry_list = realloc(*entry_list, sizeof(struct Entry *) * (++len));
        (*entry_list)[len - 1] = entry;
    }

    // Close the file
    fclose(file);
}

// Function to calculate the average value of all entries in the list
double calculate_average(struct Entry **entry_list) {
    int len = 0;
    double sum = 0.0;
    while (*entry_list) {
        // Ignore invalid or corrupted entries
        if ((*entry_list)->timestamp < 0 || (*entry_list)->value < 0.0) break;

        sum += (*entry_list)->value;
        len++;
        entry_list = &(*entry_list)->next;
    }
    return (len > 0) ? sum / len : 0.0;
}

// Function to update the value field of each entry based on its difference from the average
void adjust_entries(struct Entry **entry_list, double average) {
    while (*entry_list) {
        // Ignore invalid or corrupted entries
        if ((*entry_list)->timestamp < 0 || (*entry_list)->value < 0.0) break;

        // Calculate the difference between the original value and the average
        double diff = (*entry_list)->value - average;

        // Update the entry's value field with the new adjusted value
        (*entry_list)->value = diff;
        entry_list = &(*entry_list)->next;
    }
}

// Function to validate an entry against a set of configuration settings
int validate_entry(struct Entry *entry, struct ConfigSettings *config) {
    // Check the timestamp and value fields for validity
    if (entry->timestamp < config->min_timestamp || entry->timestamp > config->max_timestamp) return 0;
    if (entry->value < 0.0) return 0;

    // Check the metadata key-value pairs according to specified rules
    char *metadata = strtok(entry->metadata, ",");
    while (metadata) {
        // Check for invalid characters in the key or value
        if (strpbrk(metadata, "=,") || strchr(metadata, '=')) return 0;
        metadata = strtok(NULL, ",");
    }

    return 1;
}

// Function to handle file I/O errors gracefully
void handle_io_error(char *filename) {
    log_warning("Error reading file: %s", filename);
}

// Function to handle memory allocation failures during list initialization
void handle_memory_error() {
    log_error("Memory allocation failure");
}

// Function to detect and handle corrupted data entries in the CSV file
int handle_corruption(struct Entry *entry, struct ConfigSettings *config) {
    // Check the timestamp and value fields for validity
    if (entry->timestamp < config->min_timestamp || entry->timestamp > config->max_timestamp) return 0;
    if (entry->value < 0.0) return 0;

    // Check the metadata key-value pairs according to specified rules
    char *metadata = strtok(entry->metadata, ",");
    while (metadata) {
        // Check for invalid characters in the key or value
        if (strpbrk(metadata, "=,") || strchr(metadata, '=')) return 0;
        metadata = strtok(NULL, ",");
    }

    return 1;
}

// Function to provide feedback on number of valid and invalid entries processed
void report_entry_counts(struct Entry **entry_list) {
    int valid_entries = 0;
    int invalid_entries = 0;
    while (*entry_list) {
        if (validate_entry(*entry_list)) valid_entries++;
        else invalid_entries++;
        entry_list = &(*entry_list)->next;
    }
    log_info("Valid entries: %d", valid_entries);
    log_info("Invalid entries: %d", invalid_entries);
}

// Function to manage a dynamic list of 'entry' structures
struct Entry *manage_entry_list(char *filename, struct ConfigSettings *config) {
    // Initialize the entry list from the CSV file
    struct Entry **entry_list = NULL;
    init_entry_list(filename, &entry_list);

    // Validate and handle corrupted data entries in the list
    int corrupted_entries = 0;
    while (*entry_list) {
        if (!handle_corruption(*entry_list, config)) corrupted_entries++;
        entry_list = &(*entry_list)->next;
    }
    log_info("Corrupted entries: %d", corrupted_entries);

    // Calculate the average value of all valid entries in the list
    double average = calculate_average(entry_list);

    // Update the value field of each entry based on its difference from the average
    adjust_entries(entry_list, average);

    // Report number of valid and invalid entries processed
    report_entry_counts(entry_list);

    return entry_list;
}
