    // Dynamically allocate memory for the array of records
    *records = (Record *)malloc(num_records * sizeof(Record));

    // Initialize each record with a null value
    for (size_t i = 0; i < num_records; i++) {
        (*records)[i].value.str = NULL;
    }
}

// Define a function to generate random integers within a given range
int rand_range(int min, int max) {
    return min + (rand() % (max - min + 1));
}

// Define a function to generate random strings of a specified length
char *rand_string(size_t len) {
    char *str = malloc(len + 1);
    for (size_t i = 0; i < len; i++) {
        str[i] = 'a' + rand() % 26;
    }
    str[len] = '\0';
    return str;
}

// Define a function to populate the records with random values
void populate_records(Record *records, size_t num_records) {
    // Initialize a random number generator seeded with the current time
    srand((unsigned int)time(NULL));

