function getUserLocation($ipAddress) {
  // Try to retrieve data from cache
  $cacheKey = "user-location-$ipAddress";
  if ($cachedData = $this->getCacheData($cacheKey)) {
    return $cachedData;
  }

  // Fetch location data from third-party API
  $apiResponse = $this->fetchLocationDataFromAPI($ipAddress);

  // Cache location data for future use
  $this->setCacheData($cacheKey, $apiResponse);

  return $apiResponse;
}

// C function for capturing TCP SYN packets and extracting IP address
void captureTCPPackets(int socket) {
  while (1) {
    // Receive a packet from the socket
    char* buffer = new char[65536];
    int bytesReceived = recv(socket, buffer, 65536, 0);

    if (bytesReceived <= 0) {
      break;
    }

    // Check if the packet is a SYN packet
    if (buffer[12] == 0x06 && buffer[13] == 0x04) {
      // Extract IP address from packet
      uint32_t* ipAddress = (uint32_t*) (buffer + 26);

      // Pass IP address to PHP function for location data retrieval
      $userLocation = getUserLocation(inet_ntoa(*ipAddress));

      // Handle packet fragmentation and reassembly
      if (buffer[14] & 0x01) {
        int moreFragments = buffer[14] >> 5;
        while (moreFragments > 0) {
          bytesReceived = recv(socket, buffer + bytesReceived, sizeof(char), 0);
          if (bytesReceived <= 0) {
            break;
          }

          moreFragments--;
        }
      }
    }

    // Handle packet error
    if (buffer[14] & 0x08) {
      printf("Packet error: %s\n", strerror(errno));
    }
  }
}
```
