    int dir_len = strlen(directory);

    // Determine the number of digits to append based on the file size and directory structure
    int num_digits = 0;
    if (filename_len > dir_len) {
        num_digits = filename_len - dir_len;
    } else {
        num_digits = dir_len - filename_len;
    }

