// Define the structure for records
typedef struct record {
    int value;
    char status;
} Record;

// Define a dynamic list of record pointers
typedef struct record_list {
    Record **records;
    size_t num_records;
    size_t capacity;
    pthread_mutex_t lock;
} RecordList;

// Function to initialize the record lists
RecordList *initialize_record_lists(size_t arraySize, int minValue, int maxValue) {
    // Validate input parameters
    if (minValue > maxValue) {
        return NULL;
    }

    // Allocate memory for the two arrays and initialize them to zero
    long *offset_array = calloc(arraySize, sizeof(long));
    int *key_array = calloc(arraySize, sizeof(int));
    RecordList *record_list = malloc(sizeof(RecordList));
    record_list->records = NULL;
    record_list->num_records = 0;
    record_list->capacity = arraySize;
    pthread_mutex_init(&record_list->lock, NULL);

    // Initialize the dynamic list of records with an initial capacity
    record_list->records = calloc(arraySize, sizeof(Record *));

    // Generate random values for each record's int field within the specified range
    srand(time(NULL));
    for (int i = 0; i < arraySize; ++i) {
        int random_value = rand() % (maxValue - minValue + 1) + minValue;
        offset_array[i] = random_value;
        key_array[i] = random_value;
        record_list->records[i] = malloc(sizeof(Record));
        record_list->records[i]->value = random_value;
        record_list->records[i]->status = 'A';
    }

    // Track the number of records added to the dynamic list
    record_list->num_records = arraySize;

    return record_list;
}

// Function to add a new record to the dynamic list
void add_record(RecordList *record_list, int value) {
    pthread_mutex_lock(&record_list->lock);
    if (record_list->num_records >= record_list->capacity) {
        // Reallocate memory for the dynamic list of records
        size_t new_capacity = record_list->capacity * 2;
        Record **new_records = realloc(record_list->records, new_capacity * sizeof(Record *));
        if (new_records == NULL) {
            pthread_mutex_unlock(&record_list->lock);
            return;
        }
        record_list->records = new_records;
        record_list->capacity = new_capacity;
    }
    // Add a new record to the dynamic list
    Record *new_record = malloc(sizeof(Record));
    if (new_record == NULL) {
        pthread_mutex_unlock(&record_list->lock);
        return;
    }
    new_record->value = value;
    new_record->status = 'A';
    record_list->records[record_list->num_records++] = new_record;
    pthread_mutex_unlock(&record_list->lock);
}

// Function to retrieve a record from the dynamic list by its key
Record *get_record(RecordList *record_list, int key) {
    pthread_mutex_lock(&record_list->lock);
    for (int i = 0; i < record_list->num_records; ++i) {
        if (record_list->records[i]->value == key) {
            Record *record = malloc(sizeof(Record));
            memcpy(record, record_list->records[i], sizeof(Record));
            pthread_mutex_unlock(&record_list->lock);
            return record;
        }
    }
    pthread_mutex_unlock(&record_list->lock);
    return NULL;
}

// Function to update a record in the dynamic list by its key
void update_record(RecordList *record_list, int key, int value) {
    pthread_mutex_lock(&record_list->lock);
    for (int i = 0; i < record_list->num_records; ++i) {
        if (record_list->records[i]->value == key) {
            record_list->records[i]->value = value;
            pthread_mutex_unlock(&record_list->lock);
            return;
        }
    }
    pthread_mutex_unlock(&record_list->lock);
}

// Function to delete a record from the dynamic list by its key
void delete_record(RecordList *record_list, int key) {
    pthread_mutex_lock(&record_list->lock);
    for (int i = 0; i < record_list->num_records; ++i) {
        if (record_list->records[i]->value == key) {
            Record *record = record_list->records[i];
            // Shift remaining records to fill the gap
            for (int j = i; j < record_list->num_records - 1; ++j) {
                record_list->records[j] = record_list->records[j + 1];
            }
            --record_list->num_records;
            pthread_mutex_unlock(&record_list->lock);
            return;
        }
    }
    pthread_mutex_unlock(&record_list->lock);
}

// Function to cleanup the record lists and free all allocated memory
void cleanup_record_lists(RecordList *record_list) {
    for (int i = 0; i < record_list->num_records; ++i) {
        Record *record = record_list->records[i];
        free(record);
    }
    free(record_list->records);
    pthread_mutex_destroy(&record_list->lock);
}
