#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <limits.h>

#define MAX_PROJECTS 10000
#define MAX_STATUS 5
#define STATUS_RANGE 0,MAX_STATUS-1
#define MIN_ESTIMATED_HOURS 0
#define MAX_ESTIMATED_HOURS INT_MAX
#define MIN_DEADLINE 0
#define MAX_DEADLINE INT_MAX

typedef struct {
    int priority;
    int deadline;
    int status;
    char *name;
    int estimated_hours;
    time_t start_date;
} project;

void init_projects(int num_projects, project **projects) {
    // check input validity
    if (num_projects < 0 || num_projects > MAX_PROJECTS) {
        fprintf(stderr, "Invalid number of projects\n");
        return;
    }

    // allocate memory for the project array
    *projects = malloc(sizeof(project) * num_projects);
    if (*projects == NULL) {
        fprintf(stderr, "Failed to allocate memory for projects\n");
        return;
    }

    // initialize each project with a random status and estimated hours
    srand(time(NULL));
    for (int i = 0; i < num_projects; ++i) {
        (*projects)[i].priority = rand() % MAX_PRIORITY + 1;
        (*projects)[i].deadline = rand() % MAX_DEADLINE + 1;
        (*projects)[i].status = rand() % MAX_STATUS;
        (*projects)[i].name = malloc(strlen("project") + 1);
        strcpy((*projects)[i].name, "project");
        (*projects)[i].estimated_hours = rand() % (MAX_ESTIMATED_HOURS - MIN_ESTIMATED_HOURS) + MIN_ESTIMATED_HOURS;
        (*projects)[i].start_date = time(NULL);
    }
}

void free_projects(int num_projects, project **projects) {
    // check input validity
    if (num_projects < 0 || projects == NULL) {
        fprintf(stderr, "Invalid input for freeing projects\n");
        return;
    }

    // free each project's name and the project array
    for (int i = 0; i < num_projects; ++i) {
        free((*projects)[i].name);
    }
    free(*projects);
}

void save_projects(const char *filename, int num_projects, project **projects) {
    // check input validity
    if (num_projects < 0 || projects == NULL) {
        fprintf(stderr, "Invalid input for saving projects\n");
        return;
    }

    // open the file in write mode
    FILE *fp = fopen(filename, "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    // write each project to the file
    for (int i = 0; i < num_projects; ++i) {
        fprintf(fp, "%d %d %d %s %d %ld\n", (*projects)[i].priority, (*projects)[i].deadline, (*projects)[i].status, (*projects)[i].name, (*projects)[i].estimated_hours, (*projects)[i].start_date);
    }

    // close the file
    fclose(fp);
}

void load_projects(const char *filename, int num_projects, project **projects) {
    // check input validity
    if (num_projects < 0 || projects == NULL) {
        fprintf(stderr, "Invalid input for loading projects\n");
        return;
    }

    // open the file in read mode
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for reading\n");
        return;
    }

    // read each project from the file
    for (int i = 0; i < num_projects; ++i) {
        char line[128];
        if (fgets(line, sizeof(line), fp) == NULL) {
            break;
        }
        sscanf(line, "%d %d %d %s %d %ld", &(*projects)[i].priority, &(*projects)[i].deadline, &(*projects)[i].status, (*projects)[i].name, &(*projects)[i].estimated_hours, &(*projects)[i].start_date);
    }

    // close the file
    fclose(fp);
}
