    printf("Largest integer: %d\n", max.max_id);
    printf("Longest string: %s\n", max.max_name);
  } else {
    printf("No records to process.\n");
  }

  // Clean up memory and exit
  free_memory(&input);
  return 0;
}

// Function definitions
void init(InputData *input) {
  input->num_records = 0;
  input->records = NULL;
}

void generate_random_values(InputData *input, enum DistributionType dist_type) {
  // Implement random value generation based on the distribution type
  if (dist_type == UNIFORM) {
    // Generate uniform random values between 0 and 1
    for (int i = 0; i < input->num_records; i++) {
      input->records[i].id = rand() % 10 + 1;
      input->records[i].name = "random";
    }
  } else if (dist_type == GAUSSIAN) {
    // Generate Gaussian random values with mean 5 and standard deviation 2
    for (int i = 0; i < input->num_records; i++) {
      input->records[i].id = round(randn(5, 2));
      input->records[i].name = "random";
    }
  } else if (dist_type == CUSTOM) {
    // Implement custom distribution logic here
  }
}

void sort_records(InputData *input) {
  // Sort the records by integer value or string length in ascending order
  for (int i = 0; i < input->num_records - 1; i++) {
    for (int j = i + 1; j < input->num_records; j++) {
      if (input->records[i].id > input->records[j].id) {
        Record temp = input->records[i];
        input->records[i] = input->records[j];
        input->records[j] = temp;
      } else if (strlen(input->records[i].name) > strlen(input->records[j].name)) {
        Record temp = input->records[i];
        input->records[i] = input->records[j];
        input->records[j] = temp;
      }
    }
  }
}

void filter_records(InputData *input, int id_range[2], char prefix[2]) {
  // Filter the records based on custom criteria (integer ranges or string prefixes)
  int start_idx = 0;
  int end_idx = input->num_records - 1;

  if (id_range[0] > 0) {
    while (start_idx < end_idx && input->records[start_idx].id <= id_range[0]) {
      start_idx++;
    }

    while (end_idx >= start_idx && input->records[end_idx].id >= id_range[1]) {
      end_idx--;
    }
  } else if (strlen(prefix) > 0) {
    while (start_idx < end_idx && strncmp(input->records[start_idx].name, prefix, strlen(prefix)) == 0) {
      start_idx++;
    }

    while (end_idx >= start_idx && strcmp(input->records[end_idx].name, prefix) > 0) {
      end_idx--;
    }
  } else {
    return;
  }

  int new_num_records = end_idx - start_idx + 1;
  Record *new_records = malloc(new_num_records * sizeof(Record));

  if (new_records == NULL) {
    fprintf(stderr, "Error: failed to allocate memory for filtered records\n");
    return;
  }

  memcpy(new_records, input->records + start_idx, new_num_records * sizeof(Record));
  free(input->records);
  input->records = new_records;
  input->num_records = new_num_records;
}

void free_memory(InputData *input) {
  // Free memory allocated for the records and reset the state
  if (input->records != NULL) {
    free(input->records);
    input->records = NULL;
  }

  input->num_records = 0;
}
