// Function to dynamically allocate and initialize memory for two arrays:
// one for 'long' offset values and another for 'int' keys.
void *initialize_record_arrays(size_t num_records, size_t key_range) {
    // Calculate the total size of the record array based on the number of records
    // and the size of the int data type
    size_t record_size = sizeof(Record) * num_records;
    size_t key_size = sizeof(int) * num_records;
    size_t total_size = record_size + key_size;

    // Check for maximum available system resources and prevent overflow
    if (total_size > SIZE_MAX) {
        fprintf(stderr, "Total size of arrays exceeds maximum system resources");
        return NULL;
    }

    // Allocate memory for the record array and initialize it with random values
    Record *record_array = malloc(record_size);
    if (!record_array) {
        fprintf(stderr, "Failed to allocate memory for record array");
        return NULL;
    }
    for (size_t i = 0; i < num_records; i++) {
        record_array[i].value = random() % key_range;
    }

    // Allocate memory for the key array and initialize it with random values
    int *key_array = malloc(key_size);
    if (!key_array) {
        fprintf(stderr, "Failed to allocate memory for key array");
        free(record_array);
        return NULL;
    }
    for (size_t i = 0; i < num_records; i++) {
        key_array[i] = random() % key_range;
    }

    // Create a custom memory pool to manage allocations and deallocations
    MemoryPool *pool = create_memory_pool();
    if (!pool) {
        fprintf(stderr, "Failed to create memory pool");
        free(record_array);
        free(key_array);
        return NULL;
    }

    // Initialize the memory pool with the allocated memory for the record and key arrays
    initialize_memory_pool(pool, record_array, key_array);

    // Serialize the record array to disk in binary format
    FILE *record_file = fopen("record_array.bin", "wb");
    if (!record_file) {
        fprintf(stderr, "Failed to open file for serialization of record array");
        free_memory_pool(pool);
        return NULL;
    }
    size_t bytes_written = fwrite(record_array, sizeof(Record), num_records, record_file);
    if (bytes_written != num_records) {
        fprintf(stderr, "Failed to write all records to file");
        fclose(record_file);
        free_memory_pool(pool);
        return NULL;
    }
    fclose(record_file);

    // Serialize the key array to disk in text format
    FILE *key_file = fopen("key_array.txt", "w");
    if (!key_file) {
        fprintf(stderr, "Failed to open file for serialization of key array");
        free_memory_pool(pool);
        return NULL;
    }
    for (size_t i = 0; i < num_records; i++) {
        fprintf(key_file, "%d\n", key_array[i]);
    }
    fclose(key_file);

    // Free the memory allocated for the record and key arrays
    free(record_array);
    free(key_array);

    return pool;
}

// Function to deserialize a serialized record array from disk
void *deserialize_record_array(const char *file_path) {
    // Check if the file exists and is not empty
    struct stat st = {0};
    if (stat(file_path, &st) == -1 || st.st_size == 0) {
        fprintf(stderr, "File does not exist or is empty");
        return NULL;
    }

    // Allocate memory for the record array and initialize it with random values
    Record *record_array = malloc(sizeof(Record) * st.st_size);
    if (!record_array) {
        fprintf(stderr, "Failed to allocate memory for record array");
        return NULL;
    }

    // Deserialize the record array from disk in binary format
    FILE *record_file = fopen(file_path, "rb");
    if (!record_file) {
        fprintf(stderr, "Failed to open file for deserialization of record array");
        free(record_array);
        return NULL;
    }
    size_t bytes_read = fread(record_array, sizeof(Record), st.st_size, record_file);
    if (bytes_read != st.st_size) {
        fprintf(stderr, "Failed to read all records from file");
        fclose(record_file);
        free(record_array);
        return NULL;
