}

// Function to add a new node with a random key and allocated value to the list
void insert_node(node_t **list, int max_length) {
  // Allocate memory for the new node
  node_t *new_node = (node_t *)malloc(sizeof(node_t));

  // Set the key to a random integer within the specified range
  new_node->key = rand() % max_length;

  // Allocate memory for the value based on the maximum length
  new_node->value = (char *)malloc(max_length + 1);

  // Initialize the value as an empty string
  *new_node->value = '\0';

  // Set the next pointer of the new node to the head node
  new_node->next = *list;

  // Set the list pointer to the new node
  *list = new_node;
}

// Function to traverse the list and print each node's key and value
void traverse_list(node_t **list) {
  node_t *current = *list;

  while (current != NULL) {
    printf("Key: %d, Value: %s\n", current->key, current->value);
    current = current->next;
  }
}

// Function to delete a node from the list and free its memory
void delete_node(node_t **list) {
  node_t *current = *list;
  node_t *previous = NULL;

  while (current != NULL) {
    if (current->next == NULL) {
      // If the current node is the last node in the list, free its memory and set the list pointer to NULL
      free(current->value);
      free(current);
      *list = NULL;
      break;
    } else {
      // If the current node is not the last node in the list, delete it and update the next pointer of the previous node
      previous->next = current->next;
      free(current->value);
      free(current);
      current = previous->next;
    }
  }
}

// Function to resize the list by allocating new memory for a larger list and copying the nodes from the old list to the new one
void resize_list(node_t **list, int max_length) {
  // Allocate memory for the new list
  node_t *new_list = (node_t *)malloc(sizeof(node_t));

  // Set the key to a random integer within the specified range
  new_list->key = rand() % max_length;

  // Initialize the value as an empty string
  new_list->value = malloc(1);
  *new_list->value = '\0';

  // Set the next pointer of the head node to NULL
  new_list->next = NULL;

  // Copy the nodes from the old list to the new one, starting with the head node
  node_t *current = *list;
  while (current != NULL) {
    node_t *new_node = (node_t *)malloc(sizeof(node_t));
    new_node->key = current->key;
    new_node->value = malloc(strlen(current->value) + 1);
    strcpy(new_node->value, current->value);
    new_node->next = NULL;

    // Add the new node to the end of the list
    if (*list == NULL) {
      *list = new_node;
    } else {
      node_t *previous = *list;
      while (previous->next != NULL) {
        previous = previous->next;
      }
      previous->next = new_node;
    }

    current = current->next;
  }

  // Free the old list and set the list pointer to the new one
  free(*list);
  *list = new_list;
}
