Here is a sample implementation of a dynamically expandable hash table that supports storing custom 'entry' structures in C:
```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>
#include <time.h>

// Define the entry structure to store a unique integer key, floating-point value, and dynamically allocated string for description
typedef struct {
    int key;
    float value;
    char *description;
} Entry;

// Define the hash table structure to hold a list of entries
typedef struct {
    int size; // current size of the hash table
    int capacity; // maximum capacity of the hash table
    Entry **entries; // array of entry pointers
} HashTable;

// Initialize a new empty hash table with specified capacity and max string length
HashTable* init_hash_table(int capacity, int max_string_length) {
    HashTable *ht = (HashTable*) malloc(sizeof(HashTable));
    ht->size = 0;
    ht->capacity = capacity;
    ht->entries = (Entry**) calloc(capacity, sizeof(Entry*));
    return ht;
}

// Insert a new entry into the hash table
void insert_entry(HashTable *ht, int key, float value, char *description) {
    // Generate a random integer key within the specified range
    if (key < 0 || key >= ht->capacity) {
        srand(time(NULL));
        key = rand() % ht->capacity;
    }

    // Allocate memory for the entry description based on the max string length
    int len = strlen(description);
    if (len > max_string_length) {
        len = max_string_length;
    }
    char *desc = (char*) malloc((len + 1) * sizeof(char));
    memcpy(desc, description, len);
    desc[len] = '\0';

    // Create a new entry and add it to the hash table
    Entry *e = (Entry*) malloc(sizeof(Entry));
    e->key = key;
    e->value = value;
    e->description = desc;
    ht->entries[key] = e;
    ht->size++;
}

// Retrieve an entry from the hash table by its key
Entry* get_entry(HashTable *ht, int key) {
    if (key < 0 || key >= ht->capacity || !ht->entries[key]) {
        return NULL;
    }
    return ht->entries[key];
}

// Delete an entry from the hash table by its key
void delete_entry(HashTable *ht, int key) {
    if (key < 0 || key >= ht->capacity || !ht->entries[key]) {
        return;
    }
    Entry *e = ht->entries[key];
    free(e->description);
    free(e);
    ht->entries[key] = NULL;
    ht->size--;
}

// Increase the size of the hash table by a factor of 2 to accommodate additional entries
void resize_hash_table(HashTable *ht, int new_capacity) {
    // Allocate memory for the new entries array and copy over existing entries
    Entry **new_entries = (Entry**) calloc(new_capacity, sizeof(Entry*));
    memcpy(new_entries, ht->entries, ht->size * sizeof(Entry*));

    // Free the old entries array and update the hash table's capacity and size
    free(ht->entries);
    ht->capacity = new_capacity;
    ht->size = ht->size * 2;
    ht->entries = new_entries;
}

// Implement thread-safe access to the hash table by using a mutex lock
void* mutex = (void*) malloc(sizeof(pthread_mutex_t));
pthread_mutex_init(mutex, NULL);

void insert_entry_lock(HashTable *ht, int key, float value, char *description) {
    pthread_mutex_lock(mutex);
    insert_entry(ht, key, value, description);
    pthread_mutex_unlock(mutex);
}

void delete_entry_lock(HashTable *ht, int key) {
    pthread_mutex_lock(mutex);
    delete_entry(ht, key);
    pthread_mutex_unlock(mutex);
}
```
The hash table is implemented as an array of entry pointers, where each entry pointer points to a dynamically allocated structure that holds the integer key, floating-point value, and string description. The hash table size is doubled when it reaches 75% capacity to accommodate additional entries while maintaining a high load factor.

The `insert_entry` function generates a random integer key within the specified range if the given key is not valid. It then allocates memory for the entry description based on the maximum string length and copies over the description. Finally, it creates a new entry structure and adds it to the hash table. The `get_entry` function retrieves an entry from the hash table by its key, returning NULL if the key is not found or the entry is null. The `delete_entry` function deletes an entry from the hash table by its key, freeing the memory allocated for the entry description and setting the entry pointer to NULL.

The `resize_hash_table` function increases the size of the hash table by a factor of 2 to accommodate additional entries while maintaining a high load factor. It does this by allocating memory for the new entries array, copying over existing entries, and freeing the old entries array.

The `insert_entry_lock`, `delete_entry_lock` functions implement thread-safe access to the hash table by using a mutex lock. This ensures that multiple threads can safely insert or delete entries in parallel without conflicts."]

