    char* new_filename = malloc((len + suffix_len + 1) * sizeof(char));
    if (!new_filename) {
        fprintf(stderr, "Error: failed to allocate memory for new filename\n");
        exit(EXIT_FAILURE);
    }
    strncpy(new_filename, filename, len + suffix_len + 1);
    strcpy(new_filename + len, suffix);
}

// Function to determine the appropriate number of digits to append to a filename
static size_t get_num_digits(char* filename) {
    size_t num_digits = 0;
    // Check if the filename has a suffix and count the number of digits
    char* ext = strrchr(filename, '.');
    if (ext) {
        size_t len = strlen(ext + 1);
        for (size_t i = 0; i < len; i++) {
            if (isdigit(ext[i])) {
                num_digits++;
            } else {
                break;
            }
        }
    }
    return num_digits;
}

// Function to determine the file type suffix for a filename
static char* get_file_type(char* filename) {
    // Check if the filename has an extension and determine the corresponding file type
    char* ext = strrchr(filename, '.');
    if (ext) {
        size_t len = strlen(ext + 1);
        for (size_t i = 0; i < NUM_SUFFIXES; i++) {
            if (!strcmp(ext + 1, SUFFIXES[i])) {
                return SUFFIXES[i];
            }
        }
    }
    return "";
}

// Function to create a directory path recursively
static void create_directory(char* directory_path) {
    // Check if the directory exists and create it if necessary
    struct stat sb;
    if (stat(directory_path, &sb) == -1 && errno == ENOENT) {
        char* parent = strrchr(directory_path, PATH_SEP);
        if (!parent || !parent[1]) {
            fprintf(stderr, "Error: invalid directory path\n");
            exit(EXIT_FAILURE);
        }
        // Create the parent directory recursively
        create_directory(parent + 1);
        // Create the current directory
        if (mkdir(directory_path, S_IRWXU) == -1) {
            fprintf(stderr, "Error: failed to create directory %s\n", directory_path);
            exit(EXIT_FAILURE);
        }
    } else if (sb.st_mode & S_IFDIR) {
        // The directory exists and is a directory
        return;
    } else {
        fprintf(stderr, "Error: %s is not a directory\n", directory_path);
        exit(EXIT_FAILURE);
    }
}

// Function to process a file entry
static void process_file_entry(FileEntry* entry) {
    // Validate the original filename and normalize it
    char* orig_filename = entry->original_filename;
    if (strlen(orig_filename) > MAX_DIGITS || !isdigit(orig_filename[0])) {
        fprintf(stderr, "Error: invalid original filename %s\n", orig_filename);
        exit(EXIT_FAILURE);
    }
    char* norm_filename = strdup(orig_filename);
    // Determine the appropriate number of digits to append to the filename
    size_t num_digits = get_num_digits(norm_filename);
    if (num_digits > MAX_DIGITS) {
        fprintf(stderr, "Error: too many digits in original filename %s\n", orig_filename);
        exit(EXIT_FAILURE);
    }
    // Append the file type suffix to the filename
    char* suffix = get_file_type(norm_filename);
    append_suffix(norm_filename, suffix);
    entry->modified_filename = norm_filename;
    // Validate and normalize the directory path
    char* dir_path = strdup(entry->directory_path);
    trim_whitespace(dir_path);
    if (strlen(dir_path) == 0 || !isalpha(dir_path[0]) || strchr(dir_path, PATH_SEP)) {
        fprintf(stderr, "Error: invalid directory path %s\n", dir_path);
        exit(EXIT_FAILURE);
    }
    create_directory(dir_path);
    entry->directory_path = dir_path;
}

// Function to process multiple file entries in parallel with minimal overhead
static void process_files(char** files, size_t num_files) {
    // Create a thread pool for processing the file entries
    pthread_t* threads = malloc(num_files * sizeof(pthread_t));
    if (!threads) {
        fprintf(stderr, "Error: failed to allocate memory for thread pool\n");
        exit(EXIT_FAILURE);
    }
    // Create a buffer for passing file entries to the threads
    FileEntry* buffer = malloc(num_files * sizeof(FileEntry));
    if (!buffer) {
        fprintf(stderr, "Error: failed to allocate memory for buffer\n");
        exit(EXIT_FAILURE);
    }
    // Initialize the threads and start processing the file entries
    size_t num_threads = 0;
    for (size_t i = 0; i < num_files; i++) {
        buffer[i].original_filename = files[i];
        if (pthread_create(&threads[num_threads++], NULL, process_file_entry, &buffer[i])) {
            fprintf(stderr, "Error: failed to create thread\n");
            exit(EXIT_FAILURE);
        }
    }
    // Join the threads and retrieve the file entries from the buffer
    for (size_t i = 0; i < num_threads; i++) {
        if (pthread_join(threads[i], NULL)) {
            fprintf(stderr, "Error: failed to join thread\n");
            exit(EXIT_FAILURE);
        }
    }
}

int main() {
    // Read the filenames and directory paths from standard input
    char** files = malloc(BUFFER_SIZE * sizeof(char*));
    size_t num_files = 0;
    read_filenames(stdin, files, &num_files);

    // Process the file entries in parallel with minimal overhead
    process_files(files, num_files);

    return EXIT_SUCCESS;
}
