    measurement_t** measurements[MAX_SENSORS]; // Measurements for each sensor
};

// Function to read the log file and process the data
void process_log_file(const char* filename, struct sensor_measurements* measurements) {
    FILE* fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    // Initialize the measurements structure
    for (int i = 0; i < MAX_SENSORS; ++i) {
        measurements->num_sensors = 0;
        measurements->num_measurements[i] = 0;
        measurements->measurements[i] = NULL;
    }

    // Read the log file line by line and process the data
    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, fp)) {
        char* token = strtok(buffer, ",");
        if (!token) continue; // Skip invalid lines

        // Extract the timestamp and sensor identifier from the line
        char* timestamp = token;
        int sensor_id = atoi(strtok(NULL, ",\n"));

        // Check if the sensor is already in the measurements structure
        bool found_sensor = false;
        for (int i = 0; i < MAX_SENSORS; ++i) {
            if (measurements->num_sensors > i && measurements->measurements[i] != NULL) {
                if (measurements->measurements[i]->sensor_id == sensor_id) {
                    found_sensor = true;
                    break;
                }
            }
        }

        // If the sensor is not in the measurements structure, allocate memory for it
        if (!found_sensor) {
            measurements->num_sensors++;
            measurement_t* new_measurement = (measurement_t*) malloc(sizeof(measurement_t));
            new_measurement->sensor_id = sensor_id;
            measurements->measurements[measurements->num_sensors - 1] = new_measurement;
        }

        // Extract the metadata from the line and add it to the measurement structure
        double metadata = atof(strtok(NULL, "\n"));
        measurement_t* current_measurement = measurements->measurements[sensor_id - 1];
        current_measurement->metadata = metadata;

        // Increment the number of measurements for this sensor
        measurements->num_measurements[sensor_id - 1]++;
    }

    fclose(fp);
}

// Function to validate the incoming data and check if it matches the predefined schema
bool validate_data(const char* filename, const char* schema) {
