    char *buffer;
    bool flag;
} record;

// Function to initialize and allocate memory for an array of records
record* init_records(int num_records, int max_buffer_size) {
    // Validate input sizes
    if (num_records <= 0 || max_buffer_size <= 0) {
        printf("Invalid input size\n");
        return NULL;
    }

    // Allocate memory for the array of records
    record *records = malloc(sizeof(record) * num_records);
    if (records == NULL) {
        printf("Failed to allocate memory for %d records\n", num_records);
        return NULL;
    }

    // Initialize each record with default values
    for (int i = 0; i < num_records; i++) {
        records[i].key = -1;
        records[i].timestamp = -1.0;
        records[i].buffer = malloc(max_buffer_size);
        if (records[i].buffer == NULL) {
            printf("Failed to allocate memory for record %d\n", i);
            return NULL;
        }
        records[i].flag = false;
    }

    // Return the initialized array of records
    return records;
}
