    char *json_string = malloc(len + 1);
    if (json_string == NULL) {
        perror("Error allocating memory for JSON string");
        fclose(file);
        return NULL;
    }

    size_t read_bytes = fread(json_string, 1, len, file);
    if (read_bytes != len) {
        perror("Error reading from configuration file");
        free(json_string);
        fclose(file);
        return NULL;
    }

    json_string[len] = '\0'; // Add null terminator to the end of the string
