    assert(flexible_data_structure != NULL);
    assert(num_records > 0);

    // Allocate memory for the data structure
    flexible_data_structure->data = malloc(sizeof(DataPoint) * num_records);
    if (flexible_data_structure->data == NULL) {
        perror("Error allocating memory for data structure");
        return;
    }

    // Initialize each record with a random value
    size_t i;
    for (i = 0; i < num_records; i++) {
        DataPoint *data_point = &flexible_data_structure->data[i];
        if (rand() % 2 == 0) { // Randomly decide whether to use an integer or string
            data_point->len = 0;
            int *int_ptr = malloc(sizeof(int));
            *int_ptr = rand(); // Assign a random integer value
            data_point->data = int_ptr;
        } else {
            char *str = malloc(10); // Assign a random string with length 10
            sprintf(str, "%d", rand()); // Fill the string with a random integer
            data_point->len = strlen(str);
            data_point->data = str;
        }
    }
}

// Function to print the maximum value among integers and the longest string among strings
void print_results(FlexibleDataStructure *flexible_data_structure) {
    assert(flexible_data_structure != NULL);

    size_t i;
    int max_int = INT_MIN; // Initialize maximum integer to minimum value
    char *longest_str = ""; // Initialize longest string to empty string

    for (i = 0; i < flexible_data_structure->num_records; i++) {
        DataPoint *data_point = &flexible_data_structure->data[i];
        if (data_point->len > 0) { // If the data point is a string
            if (strlen(data_point->data) > strlen(longest_str)) {
                longest_str = data_point->data;
            }
        } else { // If the data point is an integer
            int *int_ptr = data_point->data;
            if (*int_ptr > max_int) {
                max_int = *int_ptr;
            }
        }
    }

    printf("Maximum integer: %d\n", max_int);
    printf("Longest string: %s\n", longest_str);
}

