// Function to allocate memory from the memory pool
void* alloc_mem(struct mem_pool* pool, size_t size) {
    void* ptr;
    pthread_mutex_lock(&pool->mutex);
    if (pool->size - (char*)pool->buffer >= size) {
        ptr = pool->buffer;
        pool->buffer += size;
        pool->size -= size;
    } else {
        // Out of memory, reclaim unused memory
        pthread_mutex_unlock(&pool->mutex);
        return NULL;
    }
    pthread_mutex_unlock(&pool->mutex);
    return ptr;
}

// Function to deallocate memory from the memory pool
void free_mem(struct mem_pool* pool, void* ptr) {
    pthread_mutex_lock(&pool->mutex);
    pool->buffer -= (char*)ptr - pool->buffer;
    pool->size += sizeof(void*);
    pthread_mutex_unlock(&pool->mutex);
}

// Function to create a new linked list node with the given key and value
struct node* create_node(int key, long value) {
    struct node* node = malloc(sizeof(struct node));
    if (node == NULL) {
        return NULL;
    }
    node->data.key = key;
    node->data.value = value;
    node->next = NULL;
    return node;
}

// Function to insert a new key-value pair into the linked list
void insert_kv(struct node** head, int key, long value) {
    struct node* node = create_node(key, value);
    if (node == NULL) {
        return;
    }
    // Insert the node at the beginning of the linked list
    node->next = *head;
    *head = node;
}

// Function to remove a key-value pair from the linked list
struct kv* remove_kv(struct node** head, int key) {
    struct node* current = *head;
    struct node* previous = NULL;
    while (current != NULL && current->data.key != key) {
        previous = current;
        current = current->next;
    }
    if (current == NULL) {
        return NULL;
    }
    // Remove the node from the linked list
    if (previous == NULL) {
        *head = current->next;
    } else {
        previous->next = current->next;
    }
    struct kv* kv = &current->data;
    free(current);
    return kv;
}

// Function to update a key-value pair in the linked list
void update_kv(struct node** head, int key, long value) {
    struct node* current = *head;
    while (current != NULL && current->data.key != key) {
        current = current->next;
    }
    if (current == NULL) {
        return;
    }
    // Update the value of the key-value pair
    current->data.value = value;
}

// Function to retrieve a key-value pair from the linked list
struct kv* get_kv(struct node** head, int key) {
    struct node* current = *head;
    while (current != NULL && current->data.key != key) {
        current = current->next;
    }
    if (current == NULL) {
        return NULL;
    }
    return &current->data;
}

// Function to retrieve the value of a key-value pair from the linked list
long get_value(struct node** head, int key) {
    struct kv* kv = get_kv(head, key);
    if (kv == NULL) {
        return -1;
    }
    return kv->value;
}

// Function to update the value of a key-value pair in the linked list
void set_value(struct node** head, int key, long value) {
    struct kv* kv = get_kv(head, key);
    if (kv == NULL) {
        return;
    }
    kv->value = value;
}

// Function to iterate over the linked list and print each key-value pair
void iterate_print(struct node** head) {
    struct node* current = *head;
    while (current != NULL) {
        printf("%d: %ld\n", current->data.key, current->data.value);
        current = current->next;
    }
}

// Function to delete the linked list
void free_list(struct node** head) {
    struct node* current = *head;
    while (current != NULL) {
        struct node* next = current->next;
        free(current);
        current = next;
    }
}
```
The `init_mem_pool` function initializes a memory pool for efficient allocation and deallocation of resources. The `alloc_mem` function allocates memory from the memory pool, while the `free_mem` function frees the allocated memory back to the memory pool.

The `create_node` function creates a new linked list node with the given key and value, while the `insert_kv`, `remove_kv`, `update_kv`, and `get_kv` functions insert, remove, update, and retrieve key-value pairs from the linked list respectively. The `get_value` function retrieves the value of a key-value pair from the linked list, while the `set_value` function updates the value of a key-value pair in the linked list.

The `iterate_print` function iterates over the linked list and prints each key-value pair, while the `free_list` function deletes the entire linked list.

This implementation uses a custom memory pool to manage memory allocation and deallocation, ensuring minimal fragmentation while supporting rapid allocation and deallocation of resources. The memory pool is periodically reclaimed to optimize performance over extended operation periods.']

