    // Open the file for writing in binary mode
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        fprintf(stderr, "Error: Failed to open file '%s' for writing\n", filename);
        exit(EXIT_FAILURE);
    }

    // Write the array of records to the file
    size_t num_written = fwrite(records, sizeof(struct record), num_records, file);
    if (num_written != num_records) {
        fprintf(stderr, "Error: Failed to write %zu bytes to file '%s'\n", num_records * sizeof(struct record), filename);
        exit(EXIT_FAILURE);
    }

    // Close the file
    if (fclose(file) != 0) {
        fprintf(stderr, "Error: Failed to close file '%s'\n", filename);
        exit(EXIT_FAILURE);
    }
}

// Function to deserialize data from a file and initialize an array of 'long', 'int', and 'float'
void deserialize_data(const char *filename, struct record **records) {
    // Open the file for reading in binary mode
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        fprintf(stderr, "Error: Failed to open file '%s' for reading\n", filename);
        exit(EXIT_FAILURE);
    }

    // Get the size of the file in bytes
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);

    // Allocate memory for the array of records
    *records = malloc(file_size / sizeof(struct record));
    if (*records == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for records\n");
        exit(EXIT_FAILURE);
    }

    // Read the array of records from the file
    size_t num_read = fread(*records, sizeof(struct record), file_size / sizeof(struct record), file);
    if (num_read != file_size / sizeof(struct record)) {
        fprintf(stderr, "Error: Failed to read %zu bytes from file '%s'\n", file_size, filename);
        exit(EXIT_FAILURE);
    }

    // Close the file
    if (fclose(file) != 0) {
        fprintf(stderr, "Error: Failed to close file '%s'\n", filename);
        exit(EXIT_FAILURE);
    }
}
