#include <stdlib.h>
#include <string.h>
#include <assert.h>

// Define the record structure
typedef struct {
    long offset;
    int key;
    float data;
} record;

// Define the array of records
record* records = NULL;
size_t num_records = 0;

// Function to allocate memory for the array of records
void allocate_memory(size_t num_records) {
    // Allocate memory for the array of records
    records = (record*)malloc(num_records * sizeof(record));
    assert(records != NULL);
}

// Function to release memory for the array of records
void release_memory() {
    // Release memory for the array of records
    free(records);
    records = NULL;
}

// Function to update a record in the array
void update_record(size_t index, long offset, int key, float data) {
    assert(index < num_records);
    records[index].offset = offset;
    records[index].key = key;
    records[index].data = data;
}

// Function to retrieve a record from the array
record get_record(size_t index) {
    assert(index < num_records);
    return records[index];
}

// Function to add a new record to the array
void add_record(long offset, int key, float data) {
    // Check if there is enough memory for the new record
    if (num_records >= 1000000) {
        // Archive infrequently accessed records to a separate storage medium
        archive_records();
    }
    update_record(num_records, offset, key, data);
    num_records++;
}

// Function to remove a record from the array
void remove_record(size_t index) {
    assert(index < num_records);
    // Shift all records after the removed record back by one index
    for (int i = index + 1; i < num_records; i++) {
        update_record(i - 1, records[i].offset, records[i].key, records[i].data);
    }
    // Reduce the number of records by one
    num_records--;
}

// Function to archive infrequently accessed records to a separate storage medium
void archive_records() {
    // Implement archiving process here
}
```
