    for (int i = 0; i < num_records; i++) {
        // Generate random values within the specified range
        if (rand() % 2 == 0) {  // generate an integer value
            arr[i].is_integer = 1;
            arr[i].value.integer = generate_random_integer(min_value, max_value);
        } else {  // generate a string value
            arr[i].is_integer = 0;
            arr[i].value.string = generate_random_string(string_length);
        }
    }
    return arr;
}

