    int largest = INT_MIN;
    for (int i = 0; i < num_records; i++) {
        if (arr[i].is_integer && arr[i].value.integer > largest) {
            largest = arr[i].value.integer;
        }
    }
    return largest;
}

// Function to find the longest string in an array of records
char* find_longest_string(record* arr, int num_records) {
    char* longest = NULL;
    for (int i = 0; i < num_records; i++) {
        if (!arr[i].is_integer && arr[i].value.string > longest) {
            longest = arr[i].value.string;
        }
    }
    return longest;
}

// Function to free an array of records
void free_array(record* arr, int num_records) {
    for (int i = 0; i < num_records; i++) {
        if (!arr[i].is_integer) {
            free(arr[i].value.string);
        }
    }
    free(arr);
}

// Main function to demonstrate usage of the functions
