    new_task->documents = (struct Document*) malloc(sizeof(struct Document) * MAX_NUM_DOCUMENTS);
    init_documents(&new_task->documents, MAX_NUM_DOCUMENTS);
}

// Function to create a new state in the FSA with the given parameters
struct State* create_state(int id) {
    // Check if input is valid
    assert(id > 0);

    // Create a new state in the FSA with the given parameters
    struct State *new_state = (struct State*) malloc(sizeof(struct State));
    new_state->id = id;
    new_state->documents = (struct Document*) malloc(sizeof(struct Document) * MAX_NUM_DOCUMENTS);
    init_documents(&new_state->documents, MAX_NUM_DOCUMENTS);
}

// Function to create a new document in the JSON feed with the given parameters
struct Document* create_document(char *text) {
    // Check if input is valid
    assert(text != NULL);

    // Create a new document in the JSON feed with the given parameters
    struct Document *new_document = (struct Document*) malloc(sizeof(struct Document));
    new_document->text = text;
}

// Function to update a task in the JSON feed with the given parameters
void update_task(struct Task *task, int priority, char *name) {
    // Check if input is valid
    assert(task != NULL);
    assert(priority > 0);
    assert(name != NULL);

    // Update the task in the JSON feed with the given parameters
    task->priority = priority;
    task->name = name;
}

// Function to update a state in the FSA with the given parameters
void update_state(struct State *state, int id) {
    // Check if input is valid
    assert(state != NULL);
    assert(id > 0);

    // Update the state in the FSA with the given parameters
    state->id = id;
}

// Function to update a document in the JSON feed with the given parameters
void update_document(struct Document *document, char *text) {
    // Check if input is valid
    assert(document != NULL);
    assert(text != NULL);

    // Update the document in the JSON feed with the given parameters
    document->text = text;
}

// Function to delete a task from the JSON feed with the given parameters
void delete_task(struct Task *task) {
    // Check if input is valid
    assert(task != NULL);

    // Delete the task from the JSON feed with the given parameters
    free(task);
}

// Function to delete a state from the FSA with the given parameters
void delete_state(struct State *state) {
    // Check if input is valid
    assert(state != NULL);

    // Delete the state from the FSA with the given parameters
    free(state);
}

// Function to delete a document from the JSON feed with the given parameters
void delete_document(struct Document *document) {
    // Check if input is valid
    assert(document != NULL);

    // Delete the document from the JSON feed with the given parameters
    free(document);
}
